// Player-rig screenshot harness (ACJ) — Playwright capture for the iteration
// loop, replacing the flaky preview MCP path (see MEMORY: hidden-tab throttling
// + dynamic-import isolation wedged the MCP screenshotter mid-session).
//
// Boots its own Vite dev server on a dedicated port, drives the in-page
// `window.__game.rigStudio()` studio (headless enter + even lighting + framed
// canonical angle — D134/D135), poses the rig, and writes PNGs to verification/.
//
// Usage:
//   node scripts/rig-shot.mjs                              # idle pose, default angles
//   node scripts/rig-shot.mjs --pose=apose --angles=front,3q,head
//   node scripts/rig-shot.mjs --pose=walk --angles=left --tag=knee
//
//   --pose    idle | apose | walk        (default idle)
//   --angles  comma list of front,back,left,right,3q,head  (default front,3q,left,head)
//   --tag     filename tag                (default "shot")
//   --port    dev server port            (default 5191)
//
// Output: verification/rig-<tag>-<pose>-<angle>.png  (one per angle)

import { chromium } from 'playwright';
import { spawn, spawnSync } from 'node:child_process';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
// Screenshot/artifact output dir. RIG_OUT_DIR lets a CALLER give this process its own
// directory — the parallel gate runner (scripts/verify-chunks.mjs) sets it per leg so two
// concurrent legs of the same scenario at different seeds can never race on the same
// verification/scen-*.png. Unset (every interactive/manual run) ⇒ verification/, unchanged.
const OUT = resolve(ROOT, process.env.RIG_OUT_DIR || 'verification');
if (!existsSync(OUT)) mkdirSync(OUT, { recursive: true });

const argv = Object.fromEntries(
  process.argv.slice(2).map((a) => {
    const [k, v] = a.replace(/^--/, '').split('=');
    return [k, v ?? true];
  }),
);
const POSE = argv.pose || 'idle';
const ANGLES = String(argv.angles || 'front,3q,left,head').split(',').map((s) => s.trim());
const TAG = argv.tag || 'shot';
const PORT = Number(argv.port || 5191);
const CLOSEUP = argv.closeup || ''; // shoulder|hip|hand|knee|elbow|face — overrides angles
const LIT = argv.lit || '';         // "form" = dramatic key/fill/shadow lighting (rigStudio's flat even light hides all form)

// Close-up targets: frame a joint from the front-side at close range. Offsets
// are [side, up, fwd] in the HEAD's facing frame so framing is consistent
// regardless of the (heading-dependent) spawn orientation.
const CLOSEUPS = {
  shoulder: { joint: 'rig.shoulders[1]', off: [0.30, 0.20, 0.62], look: [0, -0.08, 0] },
  hip:      { joint: 'rig.hips[1]',      off: [0.34, 0.12, 0.66], look: [0, -0.15, 0] },
  hand:     { joint: 'rig.wrists[1]',    off: [0.10, 0.26, 0.55], look: [0, -0.06, 0] },
  knee:     { joint: 'rig.knees[1]',     off: [0.30, 0.08, 0.58], look: [0, -0.05, 0] },
  elbow:    { joint: 'rig.elbows[1]',    off: [0.28, 0.10, 0.50], look: [0, 0, 0] },
  face:     { joint: 'rig.headGroup',    off: [0.11, 0.04, 0.36], look: [0, -0.03, 0] },
  torso:    { joint: 'rig.headGroup',    off: [0.18, -0.45, 1.05], look: [0, -0.62, 0] },
  full:     { joint: 'rig.headGroup',    off: [0.55, -0.55, 2.15], look: [0, -0.92, 0] },     // whole figure, fills the portrait frame
  full3q:   { joint: 'rig.headGroup',    off: [1.25, -0.55, 1.75], look: [0, -0.92, 0] },     // whole figure, 3/4
};

// Pose presets — run inside page.evaluate against window.__game.ctx.player.rig.
// Bones are Object3D, so .rotation.set works identically to the old Groups.
const POSES = {
  idle: `for(const i of [0,1]){ rig.shoulders[i].rotation.set(0.06,0,(i===1?1:-1)*0.05); rig.elbows[i].rotation.x=0.08; rig.wrists[i].rotation.x=-0.12; rig.hips[i].rotation.set(0,0,0); rig.knees[i].rotation.x=0.03; rig.ankles[i].rotation.x=0; }`,
  apose: `for(const i of [0,1]){ rig.shoulders[i].rotation.set(0.20,0,(i===1?1:-1)*0.55); rig.elbows[i].rotation.x=0.22; rig.wrists[i].rotation.x=0; rig.hips[i].rotation.set(0,0,(i===1?1:-1)*0.06); rig.knees[i].rotation.x=0.03; rig.ankles[i].rotation.x=0; }`,
  walk: `rig.hips[1].rotation.x=0.6; rig.knees[1].rotation.x=1.0; rig.ankles[1].rotation.x=0.2; rig.hips[0].rotation.x=-0.25; rig.knees[0].rotation.x=0.10; rig.ankles[0].rotation.x=0; rig.shoulders[1].rotation.set(-0.4,0,0.05); rig.elbows[1].rotation.x=0.5; rig.wrists[1].rotation.x=-0.1; rig.shoulders[0].rotation.set(0.4,0,-0.05); rig.elbows[0].rotation.x=0.3; rig.wrists[0].rotation.x=-0.1;`,
  // Natural relaxed contrapposto — weight on the right leg, left leg eased, pelvis
  // + spine + head counter-tilt, arms hang with a slight elbow bend + small gap.
  relaxed: `rig.hips[1].rotation.set(-0.04,0,0.02); rig.knees[1].rotation.x=0.02; rig.ankles[1].rotation.x=0; rig.hips[0].rotation.set(0.10,0.05,0.03); rig.knees[0].rotation.x=0.20; rig.ankles[0].rotation.x=-0.05; rig.spineBend.rotation.set(0.05,0,-0.05); rig.shoulders[1].rotation.set(0.10,0,0.10); rig.elbows[1].rotation.x=0.22; rig.wrists[1].rotation.x=-0.12; rig.shoulders[0].rotation.set(0.06,0,-0.13); rig.elbows[0].rotation.x=0.30; rig.wrists[0].rotation.x=-0.12; rig.headGroup.rotation.set(0.03,0.12,-0.05);`,
};

// ── ACN — LIVE scenario mode (--scenario=…) ─────────────────────────────────
// The pose/angle path above captures STATIC frames (it pauses + poses the rig).
// Live-FEEL features (creature AI, aim-twist sweep, weapon fire) need the sim
// TICKING — so these scenarios enter the game live, force the pointer-lock gate
// open (so `isPlaying()` is true and every system ticks — the gate that the
// hidden-preview path can't satisfy, D146), set up a situation, and capture a
// STRIP of frames over wall-clock time. Output: verification/scen-<name>-fNN.png.
const SCENARIO = argv.scenario || '';
// Deep-Desert cycle 5 (D257) — the sled-ride probe must run with the rideable-sled
// feature forced ON. Vite exposes VITE_-prefixed env vars from process.env at
// dev-server start; the spawned `npm run dev` inherits process.env, so setting it
// here (before startDev) flips FEATURES.rideableSled true for THIS probe only.
if (SCENARIO === 'sled-ride' || SCENARIO === 'sled-dune' || SCENARIO === 'sled-pose' || SCENARIO === 'sled-packup') process.env.VITE_RIDEABLE_SLED = '1';
// UNDERWORLD cycle 1 (D307) — the cave-mouth probe forces the entrance-chunk collider
// swap ON via the flag for THIS probe only (VITE_ is read by Vite from process.env at
// dev-server start; the spawned `npm run dev` inherits it). verify:all runs it OFF.
if (SCENARIO === 'cave-walk' || SCENARIO === 'cave-digest' || SCENARIO === 'cave-void' || SCENARIO === 'cave-look' || SCENARIO === 'cave-audit' || SCENARIO === 'pool-fill' || SCENARIO === 'pool-look' || SCENARIO === 'cave-streamed' || SCENARIO === 'cave-kinds' || SCENARIO === 'cave-light' || SCENARIO === 'crevice-profile' || SCENARIO === 'crevice-sweep') process.env.VITE_CAVE_TEST = '1';
// DEEPER cycle 2 — the watertight SDF surface is the cave's ONLY meshing path (the `--sdf` selector
// is gone with the shell kit). `--sdfbench` re-polygonizes at the measurement resolutions and prints
// the cost table; it changes nothing about what ships.
if (argv.sdfbench) process.env.VITE_CAVE_SDF_BENCH = '1';
// DEEPER cycle 5 — `--cave=0` boots with the whole cave feature OFF (the shipped kill-switch). Used by
// the cave-preload gate's FLAG-OFF leg: the boot preload must not exist and must not have regressed
// the no-cave world.
if (String(argv.cave) === '0') process.env.VITE_CAVE = '0';
const FRAMES = Number(argv.frames || 10);
const INTERVAL = Number(argv.interval || 300); // ms between strip frames

// GL backend selector — MODULE scope so a scenario can LABEL its own measurements with the backend
// they were taken on (the cave-audit perf table is meaningless without it). `--gl=swiftshader` is the
// same switch as RIG_GL=swiftshader, exposed as a flag so a software-renderer run still goes through
// `npm run rig -- …` (the SPEED RULES' zero-prompt path) instead of needing a shell env prefix.
// See main() for what each mode passes to chromium.
const GL_MODE = argv.gl || process.env.RIG_GL || 'angle';

/** Enter gameplay LIVE (ticking) — dev loadout, pointer-lock gate forced open,
 *  unpaused, canvas sized, daylight for legibility. Does NOT pause/pose. */
async function enterLive(page, thirdPerson) {
  await page.evaluate((tp) => {
    const g = window.__game;
    g.enterGame(true);                              // dev loadout + handoff (skipLock — ACN)
    const ctx = g.ctx;
    ctx.input.controls.isLocked = true;             // make isPlaying()===true so all systems tick
    ctx.flags.paused = false;
    ctx.flags.thirdPerson = tp;
    g.setTime(0.42);                                // mid-morning: scene legible
    ctx.three.renderer.setSize(900, 1100, false);
    const cam = ctx.three.camera;
    if (cam.isPerspectiveCamera) { cam.aspect = 900 / 1100; cam.updateProjectionMatrix(); }
  }, thirdPerson);
  await page.waitForTimeout(500); // let several ticks run so the rig settles at the body
}

/** FAST STREAM-TO-SITE (2026-07-13 probe-infra pass). Replaces the old
 *  multi-hop 140m streaming walk that dominated skyfall probe wall-clock (~1-2
 *  min/run at 14fps/hop). A SINGLE teleport past the anchor margin re-anchors
 *  the chunk ring at the destination in a few frames — the gradual hop was
 *  cargo-culted caution. Parks ~`park`m off the target, then POLLS (not a
 *  fixed 140-frame wait) until the deferred landmark thunk has built the named
 *  group near the site, or a frame cap. Streaming CORRECTNESS is covered by the
 *  chunk-streaming gate; re-proving it in every shot is pure tax.
 *  Returns { built, frames } — built=false means the group never appeared. */
async function streamToSite(page, x, z, { park = 30, groupName = 'skyfallWreck', maxFrames = 240 } = {}) {
  return page.evaluate(async ({ x, z, park, groupName, maxFrames }) => {
    const ctx = window.__game.ctx;
    ctx.flags.paused = false;
    const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
    // ONE jump to the park spot (past the anchor margin → full re-anchor).
    const px = x - park;
    ctx.player.body.body.setTranslation({ x: px, y: ctx.terrain.heightAt(px, z) + 1.6, z }, true);
    ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
    // Poll: the chunk streams in + its ONE deferred skyfall thunk builds (a
    // few frames), then the merged group appears. Stop as soon as it's there.
    let built = false, f = 0;
    for (; f < maxFrames; f++) {
      await raf();
      let found = false;
      ctx.three.scene.traverse((o) => {
        if (o.name === groupName && o.userData && o.userData.skyfallCenter) {
          const c = o.userData.skyfallCenter;
          if ((c.x - x) ** 2 + (c.z - z) ** 2 < 4) found = true;
        }
      });
      if (found) { built = true; break; }
    }
    // A few settle frames so colliders register + the merge finalizes.
    for (let i = 0; i < 12; i++) await raf();
    return { built, frames: f };
  }, { x, z, park, groupName, maxFrames });
}

/** Capture FRAMES screenshots spaced INTERVAL ms apart. `perFrame` (optional)
 *  is a function string run in-page each frame before the wait (gets the frame
 *  index) — used to drive aim sweep / trigger fire / re-aim a tracking camera. */
async function captureStrip(page, name, perFrame) {
  for (let i = 0; i < FRAMES; i++) {
    if (perFrame) await page.evaluate(`(${perFrame})(${i})`);
    await page.waitForTimeout(INTERVAL);
    const path = join(OUT, `scen-${name}-f${String(i).padStart(2, '0')}.png`);
    await page.screenshot({ path, fullPage: false, animations: 'disabled', timeout: 60000 });
  }
  console.log(`[rig-shot] saved ${FRAMES} frames: scen-${name}-f00..f${String(FRAMES - 1).padStart(2, '0')}.png`);
}

const SCENARIOS = {
  // ── sled-ride (Deep-Desert cycle 5, D257) ──────────────────────────────────
  // Proves the rideable-sled CORE (flag forced ON via VITE_RIDEABLE_SLED=1, set
  // above). Spawns a sled on a real origin-world slope, MOUNTS via the real code
  // path (E + look + range), then asserts over stepped frames:
  //   (a) mounted → capsule pinned to the seat (dist < 0.1m each frame)
  //   (b) on a slope the sled accelerates downhill + its path follows the gradient
  //   (c) on flat it decelerates to rest
  //   (d) JUMP dismount → player standing beside the sled on terrain, KCC restored
  //   (e) re-mount works
  // Also screenshots the mounted mid-slide (3P). Numbers are printed per phase.
  'sled-ride': async (page) => {
    // ── PHASE A — find a slope, spawn a sled, mount via the real path, measure pin.
    const a = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const step = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      ctx.flags.paused = false;
      ctx.flags.thirdPerson = true;
      const nh = (x, z) => { const n = ctx.terrain.normalAt(x, z); return Math.hypot(n.x, n.z); };
      // Search a coarse ring grid for the STEEPEST moderate slope (not a cliff) —
      // a steeper face gives a clearer accel + descent read for phase B.
      let slope = null;
      for (let r = 24; r <= 500; r += 6) {
        for (let deg = 0; deg < 360; deg += 12) {
          const x = Math.cos(deg * Math.PI / 180) * r;
          const z = Math.sin(deg * Math.PI / 180) * r;
          const m = nh(x, z);
          if (m > 0.12 && m < 0.6 && (!slope || m > slope.m)) slope = { x, z, m };
        }
      }
      if (!slope) return { error: 'no slope near origin' };
      const sn = ctx.terrain.normalAt(slope.x, slope.z);
      const shm = Math.hypot(sn.x, sn.z);
      const downX = sn.x / shm, downZ = sn.z / shm;   // terrain normal XZ points downhill
      const yaw = Math.atan2(-downX, -downZ);          // bow (local -Z) faces downhill
      const { id } = window.__game.spawnSled(slope.x, slope.z, yaw);
      window.__sr = { id, slope, downX, downZ };
      const find = () => ctx.sleds.list.find((s) => s.id === id);
      let sled = find();
      sled._slideVx = 0; sled._slideVz = 0;
      await step(2);
      // Stand up-slope of the sled, within mount range, camera on it; press E.
      const pbx = slope.x - downX * 2.4, pbz = slope.z - downZ * 2.4;
      const pby = ctx.terrain.heightAt(pbx, pbz) + 1.0;
      ctx.player.body.body.setTranslation({ x: pbx, y: pby, z: pbz }, true);
      sled = find();
      const cam = ctx.three.camera;
      cam.position.set(pbx, pby + 0.85, pbz);
      cam.lookAt(sled.pos.x, sled.pos.y + 0.2, sled.pos.z);
      cam.updateMatrixWorld(true);
      await step(1);
      ctx.input.pressed.add('KeyE');
      await step(2);
      const mountedOk = ctx.player.ridingSledId === id;
      // Pin distance (capsule XZ vs sled center) over 6 frames WHILE sliding.
      const pin = [];
      for (let i = 0; i < 6; i++) {
        await step(1);
        sled = find();
        const p = ctx.player.body.body.translation();
        pin.push(+Math.hypot(p.x - sled.pos.x, p.z - sled.pos.z).toFixed(3));
      }
      sled = find();
      const p = ctx.player.body.body.translation();
      const capBottomOverDeck = +((p.y - (ctx.player.body.halfHeight + ctx.player.body.radius)) - sled.pos.y).toFixed(3);
      return {
        slopeX: +slope.x.toFixed(0), slopeZ: +slope.z.toFixed(0), slopeMag: +slope.m.toFixed(3),
        mountedOk, pin, capBottomOverDeck,
      };
    });
    if (a.error) { console.log('[sled-ride] ABORT: ' + a.error); return; }
    const pinMax = Math.max(...a.pin);
    console.log(`[sled-ride] PHASE A (mount + pin): slope@(${a.slopeX},${a.slopeZ}) normHoriz=${a.slopeMag} mounted=${a.mountedOk} pinDist(m)=${JSON.stringify(a.pin)} maxPin=${pinMax.toFixed(3)} capsuleBottomOverDeck(m)=${a.capBottomOverDeck} => ${a.mountedOk && pinMax < 0.1 ? 'PASS' : 'FAIL'}`);

    // ── PHASE B — slope slide (no input): accel downhill + path follows gradient.
    const b = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const sr = window.__sr;
      const find = () => ctx.sleds.list.find((s) => s.id === sr.id);
      let sled = find();
      const startX = sled.pos.x, startZ = sled.pos.z, startY = sled.pos.y;
      let px = startX, pz = startZ;
      const disp = [], ys = [];
      for (let i = 0; i < 42; i++) {
        await raf();
        sled = find();
        disp.push(+Math.hypot(sled.pos.x - px, sled.pos.z - pz).toFixed(4));
        ys.push(+sled.pos.y.toFixed(2));
        px = sled.pos.x; pz = sled.pos.z;
      }
      sled = find();
      const pathX = sled.pos.x - startX, pathZ = sled.pos.z - startZ;
      const pathLen = Math.hypot(pathX, pathZ);
      const pathDot = pathLen > 1e-4 ? +((pathX * sr.downX + pathZ * sr.downZ) / pathLen).toFixed(3) : 0;
      const descended = +(startY - sled.pos.y).toFixed(2);
      const early = disp.slice(1, 6).reduce((s, v) => s + v, 0) / 5;
      const late = disp.slice(30, 40).reduce((s, v) => s + v, 0) / 10;
      return { disp, ys, pathDot, descended, early: +early.toFixed(4), late: +late.toFixed(4) };
    });
    const accelerated = b.late > b.early;
    const bPass = accelerated && b.pathDot > 0.7 && b.descended > 0.2;
    console.log(`[sled-ride] PHASE B (slope slide): per-frame disp early=${b.early} late=${b.late} accelerated=${accelerated} pathDot(vs downhill)=${b.pathDot} descended(m)=${b.descended} => ${bPass ? 'PASS' : 'FAIL'}`);

    // Screenshot the mounted mid-slide (the 3P chase cam frames it; the loop keeps
    // ticking so the sled is actively descending when the shot lands).
    await page.waitForTimeout(150);
    await page.screenshot({ path: join(OUT, 'scen-sled-ride-midslide.png'), timeout: 60000 });
    console.log('[sled-ride] screenshot saved: scen-sled-ride-midslide.png');

    // ── PHASE C — flat decel: teleport the ridden sled to a flat spot, give it an
    //    initial slide, run frames, assert it decelerates to rest.
    const c = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const step = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const sr = window.__sr;
      const find = () => ctx.sleds.list.find((s) => s.id === sr.id);
      const nh = (x, z) => { const n = ctx.terrain.normalAt(x, z); return Math.hypot(n.x, n.z); };
      // Find the flattest point in a wide grid.
      let flat = null, flatM = 1;
      for (let r = 0; r <= 600; r += 15) {
        for (let deg = 0; deg < 360; deg += 15) {
          const x = Math.cos(deg * Math.PI / 180) * r;
          const z = Math.sin(deg * Math.PI / 180) * r;
          const m = nh(x, z);
          if (m < flatM) { flatM = m; flat = { x, z }; }
          if (r === 0) break;
        }
      }
      let sled = find();
      // Seed body Y = groundY + SLED_HALF_EXTENTS_Y (0.02) + SLED_GROUND_CLEARANCE
      // (0.06); the ride branch re-derives it each frame anyway.
      const gy = ctx.terrain.heightAt(flat.x, flat.z) + 0.08;
      sled.body.setTranslation({ x: flat.x, y: gy, z: flat.z }, true);
      sled.pos.set(flat.x, gy, flat.z);
      sled._slideVx = 5; sled._slideVz = 0;   // kick it moving across the flat
      await step(1);
      const speeds = [];
      let px = find().pos.x, pz = find().pos.z;
      for (let i = 0; i < 180; i++) {
        await raf();
        sled = find();
        const d = Math.hypot(sled.pos.x - px, sled.pos.z - pz);
        if (i % 18 === 0) speeds.push(+(d / (1 / 60)).toFixed(2));   // approx m/s samples
        px = sled.pos.x; pz = sled.pos.z;
      }
      const restSpeed = +(Math.hypot(find()._slideVx ?? 0, find()._slideVz ?? 0)).toFixed(3);
      return { flatM: +flatM.toFixed(3), speeds, restSpeed };
    });
    console.log(`[sled-ride] PHASE C (flat decel): flatNormHoriz=${c.flatM} m/s samples=${JSON.stringify(c.speeds)} restSlideSpeed(m/s)=${c.restSpeed} => ${c.restSpeed < 0.2 ? 'PASS' : 'FAIL'}`);

    // ── PHASE D — JUMP dismount: player standing beside the sled on terrain, KCC back.
    const d = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const step = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const sr = window.__sr;
      ctx.input.pressed.add('Space');
      await step(2);
      const dismounted = ctx.player.ridingSledId === null;
      // let the KCC settle the capsule on terrain a few frames
      await step(6);
      const p = ctx.player.body.body.translation();
      const gy = ctx.terrain.heightAt(p.x, p.z);
      const capBottom = p.y - (ctx.player.body.halfHeight + ctx.player.body.radius);
      const standGap = +(capBottom - gy).toFixed(3);   // ~0 = standing on terrain
      const onGround = ctx.player.onGround === true;
      const sled = ctx.sleds.list.find((s) => s.id === sr.id);
      const besideDist = sled ? +Math.hypot(p.x - sled.pos.x, p.z - sled.pos.z).toFixed(2) : -1;
      return { dismounted, standGap, onGround, besideDist };
    });
    console.log(`[sled-ride] PHASE D (jump dismount): dismounted=${d.dismounted} onGround=${d.onGround} standGap(m)=${d.standGap} besideSled(m)=${d.besideDist} => ${d.dismounted && d.onGround && Math.abs(d.standGap) < 0.15 ? 'PASS' : 'FAIL'}`);

    // ── PHASE E — re-mount: stand by the sled, look, press E again.
    const e = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const step = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const sr = window.__sr;
      const sled = ctx.sleds.list.find((s) => s.id === sr.id);
      const pbx = sled.pos.x + 2.0, pbz = sled.pos.z;
      const pby = ctx.terrain.heightAt(pbx, pbz) + 1.0;
      ctx.player.body.body.setTranslation({ x: pbx, y: pby, z: pbz }, true);
      const cam = ctx.three.camera;
      cam.position.set(pbx, pby + 0.85, pbz);
      cam.lookAt(sled.pos.x, sled.pos.y + 0.2, sled.pos.z);
      cam.updateMatrixWorld(true);
      await step(1);
      ctx.input.pressed.add('KeyE');
      await step(2);
      const remounted = ctx.player.ridingSledId === sr.id;
      const p = ctx.player.body.body.translation();
      const pin = +Math.hypot(p.x - sled.pos.x, p.z - sled.pos.z).toFixed(3);
      return { remounted, pin };
    });
    console.log(`[sled-ride] PHASE E (re-mount): remounted=${e.remounted} pinDist(m)=${e.pin} => ${e.remounted && e.pin < 0.1 ? 'PASS' : 'FAIL'}`);

    const allPass = a.mountedOk && Math.max(...a.pin) < 0.1
      && bPass
      && c.restSpeed < 0.2
      && d.dismounted && d.onGround && Math.abs(d.standGap) < 0.15
      && e.remounted && e.pin < 0.1;
    console.log(`[sled-ride] RESULT: ${allPass ? 'ALL PHASES PASS' : 'FAILURE — see phases above'}`);
  },

  // ── sled-packup (Deep-Desert review-fix) ───────────────────────────────────
  // Proves the RECLAIM affordance end-to-end via the REAL input path (aim the
  // camera at the deck + press RMB → updateInteraction sets the hover, then
  // updateWieldAction/handleContextAction → packUpSled). Asserts, in order:
  //   GUARD     cargo aboard → pack-up refused, sled + kit unchanged.
  //   PACK      empty deck → RMB packs it: sled gone from ctx.sleds.list, ONE
  //             sled_kit returned to the bag, the RigidBody (+ all its colliders)
  //             removed (world body-count drops).
  //   PERSIST   save + load does NOT resurrect the packed sled (list replay only
  //             replays what's in the list, and the spliced entry isn't).
  //   REDEPLOY  a fresh sled can be placed again afterward.
  'sled-packup': async (page) => {
    const r = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const step = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      ctx.flags.paused = false;
      ctx.flags.thirdPerson = false;                 // FP → interaction ray from cam.position
      ctx.input.controls.isLocked = true;            // isPlaying() → wieldAction ticks

      const countKit = () => {
        let n = 0;
        for (const s of ctx.inventory.slots) if (s.item === 'sled_kit') n += s.count;
        for (const s of ctx.inventory.backpack) if (s.item === 'sled_kit') n += s.count;
        return n;
      };

      // Spawn a sled a few metres ahead on ~flat ground.
      const p0 = ctx.player.body.body.translation();
      const sx = p0.x + 3, sz = p0.z;
      const { id } = window.__game.spawnSled(sx, sz, 0);
      await step(3);
      const find = () => ctx.sleds.list.find((s) => s.id === id);
      if (!find()) return { error: 'sled spawn failed' };

      const bodiesWithSled = ctx.physics.world.bodies.len();
      const kitBefore = countKit();

      // Aim at the deck from ~1.2m (inside the 2.5m interaction reach) + RMB one frame.
      // Stand the player + let the KCC SETTLE the capsule first, THEN aim from the
      // real (post-settle) eye — the FP interaction ray originates at the eye, so
      // aiming before the capsule settles fires the ray from the wrong height.
      const rmbOnSled = async () => {
        const sled = find();
        if (!sled) return null;
        const ex = sled.pos.x - 1.2, ez = sled.pos.z;
        ctx.player.body.body.setTranslation({ x: ex, y: ctx.terrain.heightAt(ex, ez) + 1.0, z: ez }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        await step(5);                               // KCC settles the capsule on terrain
        const cam = ctx.three.camera;                // == player eye now (updatePlayer set it)
        cam.lookAt(sled.pos.x, sled.pos.y + 0.05, sled.pos.z);
        cam.updateMatrixWorld(true);
        await step(1);                               // updateInteraction raycasts → sets the hover
        const hovType = ctx.inventory.hover ? ctx.inventory.hover.type : null;
        ctx.input.mousePressed.add(2);               // RMB pressed THIS frame
        await step(1);                               // wieldAction/handleContextAction consumes it
        return hovType;
      };

      // ── GUARD: cargo aboard blocks the pack-up. ──
      find().contents.push({ itemId: 'rope', count: 1 });
      const hovA = await rmbOnSled();
      const blockedStillThere = !!find();
      const kitAfterBlocked = countKit();

      // ── PACK: empty the deck, RMB packs it. ──
      find().contents.length = 0;
      const hovB = await rmbOnSled();
      const goneAfterPack = !find();
      const kitAfterPack = countKit();
      const bodiesAfterPack = ctx.physics.world.bodies.len();

      // ── PERSIST: save + reload → stays gone. ──
      const sv = window.__game.saveGame();
      const ld = window.__game.loadGame();
      await step(3);
      const goneAfterReload = !ctx.sleds.list.find((s) => s.id === id);

      // ── REDEPLOY: a fresh sled can be placed again. ──
      const before = ctx.sleds.list.length;
      window.__game.spawnSled(p0.x + 5, p0.z + 1, 0);
      await step(2);
      const redeployedOk = ctx.sleds.list.length === before + 1;

      return {
        id, hovA, hovB, bodiesWithSled, kitBefore,
        blockedStillThere, kitAfterBlocked,
        goneAfterPack, kitAfterPack, bodiesAfterPack,
        saveOk: sv && sv.ok !== false, loadOk: ld && ld.ok !== false,
        goneAfterReload, redeployedOk,
      };
    });
    if (r.error) { console.log('[sled-packup] ABORT: ' + r.error); return; }
    const guardPass = r.blockedStillThere && r.kitAfterBlocked === r.kitBefore;
    const packPass = r.goneAfterPack && r.kitAfterPack === r.kitBefore + 1 && r.bodiesAfterPack < r.bodiesWithSled;
    const persistPass = r.goneAfterReload && r.saveOk && r.loadOk;
    console.log(`[sled-packup] hover types seen: guard=${r.hovA} pack=${r.hovB} (expect open_sled)`);
    console.log(`[sled-packup] GUARD (cargo blocks): stillThere=${r.blockedStillThere} kit=${r.kitAfterBlocked}(was ${r.kitBefore}) => ${guardPass ? 'PASS' : 'FAIL'}`);
    console.log(`[sled-packup] PACK  (empty→kit): gone=${r.goneAfterPack} kit=${r.kitAfterPack} bodies ${r.bodiesWithSled}->${r.bodiesAfterPack} => ${packPass ? 'PASS' : 'FAIL'}`);
    console.log(`[sled-packup] PERSIST (save+load): goneAfterReload=${r.goneAfterReload} saveOk=${r.saveOk} loadOk=${r.loadOk} => ${persistPass ? 'PASS' : 'FAIL'}`);
    console.log(`[sled-packup] REDEPLOY (kit→new sled): ${r.redeployedOk} => ${r.redeployedOk ? 'PASS' : 'FAIL'}`);
    console.log(`[sled-packup] RESULT: ${guardPass && packPass && persistPass && r.redeployedOk ? 'ALL PASS' : 'FAILURE — see above'}`);
  },

  // ── crest-smoke (Deep-Desert review-fix — spindrift subtlety) ───────────────
  // Warp to an erg, climb to a mega-dune crest, then shoot the crest spindrift
  // from the PLAYER'S EYE at three framings so the "circle read" can be judged:
  //   (1) mid  — stand at the crest, look downwind + slightly down the slip face.
  //   (2) close — drop just under the lip, look ALONG it (streaks blow across).
  //   (3) night — same as mid but at deep night, to re-verify NO glow.
  // Prints the erg wind + weather so runs are comparable. Framing is first-person
  // (rig + viewmodel hidden). Filenames: scen-crest-{mid,close,night}.png.
  'crest-smoke': async (page) => {
    const info = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const step = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      ctx.flags.paused = false;
      ctx.flags.thirdPerson = false;
      ctx.input.controls.isLocked = true;
      // Hide the FP viewmodel + rig so nothing photobombs the sky/dune framing.
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.three.renderer.setSize(1200, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1200 / 720; cam.updateProjectionMatrix(); }

      const erg = window.__game.gotoErg();
      if (!erg) return { error: 'no erg within 14km for this seed' };
      for (let i = 0; i < 10; i++) await raf();
      const H = (x, z) => ctx.terrain.heightAt(x, z);
      const nh = (x, z) => { const n = ctx.terrain.normalAt(x, z); return Math.hypot(n.x, n.z); };
      // Find a slip face near the erg, climb to its crest (mirrors sled-dune PHASE 0).
      let best = null;
      for (let r = 40; r <= 1200; r += 18) {
        for (let deg = 0; deg < 360; deg += 5) {
          const x = erg.x + Math.cos(deg * Math.PI / 180) * r;
          const z = erg.z + Math.sin(deg * Math.PI / 180) * r;
          const m = nh(x, z);
          if (m > 0.42 && m < 0.64) {
            const score = -Math.abs(m - 0.53);
            if (!best || score > best.score) best = { x, z, m, score };
          }
        }
      }
      if (!best) return { error: 'no slip face found in erg' };
      let cx = best.x, cz = best.z;
      for (let s = 0; s < 40; s++) {
        const n = ctx.terrain.normalAt(cx, cz); const m = Math.hypot(n.x, n.z);
        if (m < 0.12) break;
        cx += (-n.x / m) * 2.5; cz += (-n.z / m) * 2.5;
      }
      const crestH = H(cx, cz);
      // Downhill (slip-face) direction at the crest.
      const nc = ctx.terrain.normalAt(cx, cz); const mc = Math.hypot(nc.x, nc.z) || 1;
      const downX = nc.x / mc, downZ = nc.z / mc;
      // Erg wind (the smoke streams along this).
      const ei = ctx.biomes.ergInfoAt(cx, cz);
      const windRad = ei ? ei.windRad : 0;
      const mask = ei ? +ei.mask.toFixed(2) : 0;

      // Breezy so the veil reads without being a whiteout (mid-strength stream).
      ctx.weather.intensity = 0.35;
      window.__cs = { cx, cz, crestH, downX, downZ, windRad };
      window.__game.setTime(0.42);
      await step(30);   // let the pool seed onto the crests
      return { erg: [+erg.x.toFixed(0), +erg.z.toFixed(0)], crest: [+cx.toFixed(0), +cz.toFixed(0)], crestH: +crestH.toFixed(1), windRad: +windRad.toFixed(2), mask };
    });
    if (info.error) { console.log('[crest-smoke] ABORT: ' + info.error); return; }
    console.log(`[crest-smoke] erg@(${info.erg}) crest@(${info.crest}) crestH=${info.crestH} windRad=${info.windRad} mask=${info.mask}`);

    // Framing helper — place the eye + aim, run a few frames so smoke advects.
    const frame = async (mode) => {
      await page.evaluate(async (mode) => {
        const ctx = window.__game.ctx;
        const raf = () => new Promise((r) => requestAnimationFrame(r));
        const cs = window.__cs;
        const H = (x, z) => ctx.terrain.heightAt(x, z);
        const cam = ctx.three.camera;
        // Stand on the DOWNWIND (slip-face) side and look BACK UP at the crest lip
        // against the sky — the spindrift streams off the lip toward the camera, so
        // the puffs read against bright sky (the worst case for a circular-sprite
        // read). 'close' = near the lip (near-camera sprite test); 'mid'/'night'
        // pull back for the postcard.
        const back = mode === 'close' ? 11 : 26;
        if (mode === 'close') ctx.weather.intensity = 0.5;
        else ctx.weather.intensity = 0.35;
        const ex = cs.cx + cs.downX * back, ez = cs.cz + cs.downZ * back;
        const ey = H(ex, ez) + 1.7;
        ctx.player.body.body.setTranslation({ x: ex, y: ey, z: ez }, true);
        cam.position.set(ex, ey, ez);
        // Aim at the lip, a touch above it so the sky sits behind the streaming sand.
        cam.lookAt(cs.cx, cs.crestH + 1.2, cs.cz);
        if (mode === 'night') window.__game.setTime(0.86);
        else window.__game.setTime(0.42);
        cam.updateMatrixWorld(true);
        // Camera is hand-placed; keep updatePlayer from yanking it back by pausing
        // AFTER a few advection frames. Run frames first so smoke drifts into frame.
        for (let i = 0; i < 24; i++) { await raf(); cam.updateMatrixWorld(true); }
      }, mode);
      await page.waitForTimeout(120);
      await page.screenshot({ path: join(OUT, `scen-crest-${mode}.png`), timeout: 60000 });
      console.log(`[crest-smoke] screenshot saved: scen-crest-${mode}.png`);
    };
    await frame('mid');
    await frame('close');
    await frame('night');
    console.log('[crest-smoke] done — inspect scen-crest-{mid,close,night}.png');
  },

  // ── sled-dune (Deep-Desert cycle 6) ────────────────────────────────────────
  // The PAYOFF probe: a ride down a REAL erg slip face. Warps to the nearest erg
  // (window.__game.gotoErg → deterministic biome centroid), scans the dune sea for
  // a 30-34° slip face, walks the gradient to the CREST above it + the TROUGH below,
  // spawns a sled at the crest bow-downhill, then measures over stepped frames:
  //   PHASE 0  erg geometry — crest/trough/drop/face-slope numbers.
  //   PHASE A  free descent (no input) — descent time (crest→trough), MAX speed
  //            (vs PLAYER_SPRINT=13.2), per-frame surface gap |deckY−heightAt| < 0.3
  //            at every frame at speed (the follow holds), runout distance + no
  //            abrupt stop, no clip (deckY never below terrain).
  //   PHASE B  carve — A held vs no-input path: lateral deviation grows.
  //   PHASE C  uphill stall — kicked UPHILL it decelerates + slides back (no creep).
  //   PHASE D  dismount at speed — sled keeps sliding briefly then settles; player
  //            on ground, safely uphill-side, not mid-air/under the sled.
  // Also screenshots the crouched rider mid-slip-face with the dust trail (postcard).
  // Run per seed: `node scripts/rig-shot.mjs --scenario=sled-dune --seed=<n>`.
  'sled-dune': async (page) => {
    const SPRINT = 13.2;   // WALK_SPEED(6.0) × SPRINT_MULTIPLIER(2.2)
    // ── PHASE 0 — warp to the erg, find a slip face, locate crest + trough, spawn.
    const g0 = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const erg = window.__game.gotoErg();
      if (!erg) return { error: 'no erg within 14km for this seed' };
      // A few frames so the warp re-anchors chunks (not needed for heightAt, but
      // keeps the scene coherent for the screenshot later).
      for (let i = 0; i < 8; i++) await raf();
      const nh = (x, z) => { const n = ctx.terrain.normalAt(x, z); return Math.hypot(n.x, n.z); };
      const H = (x, z) => ctx.terrain.heightAt(x, z);
      // Scan a polar grid around the erg centre for the point whose slope is
      // closest to the 32° slip-face target (sinθ≈0.53), inside a walkable band.
      let best = null;
      for (let r = 40; r <= 1200; r += 18) {
        for (let deg = 0; deg < 360; deg += 5) {
          const x = erg.x + Math.cos(deg * Math.PI / 180) * r;
          const z = erg.z + Math.sin(deg * Math.PI / 180) * r;
          const m = nh(x, z);
          if (m > 0.44 && m < 0.64) {
            const score = -Math.abs(m - 0.53);
            if (!best || score > best.score) best = { x, z, m, score };
          }
        }
      }
      if (!best) return { error: 'no 30-34° slip face found in erg', erg };
      // Climb UPHILL (against the downhill normal) to the crest: slope < 0.12, ≤70m.
      let cx = best.x, cz = best.z;
      for (let s = 0; s < 40; s++) {
        const n = ctx.terrain.normalAt(cx, cz); const m = Math.hypot(n.x, n.z);
        if (m < 0.12) break;
        cx += (-n.x / m) * 2.5; cz += (-n.z / m) * 2.5;
      }
      const crestH = H(cx, cz);
      // Descend the gradient from the crest to the TROUGH: slope < 0.09 after ≥25m.
      let tx = cx, tz = cz, dist = 0;
      for (let s = 0; s < 90; s++) {
        const n = ctx.terrain.normalAt(tx, tz); const m = Math.hypot(n.x, n.z);
        if (m < 0.09 && dist > 25) break;
        if (m < 1e-4) break;
        tx += (n.x / m) * 2; tz += (n.z / m) * 2; dist += 2;
      }
      const troughH = H(tx, tz);
      const drop = crestH - troughH;
      // Bow (local -Z) faces downhill from the crest.
      const nc = ctx.terrain.normalAt(cx, cz); const mc = Math.hypot(nc.x, nc.z);
      const cdX = nc.x / mc, cdZ = nc.z / mc;
      const yaw = Math.atan2(-cdX, -cdZ);
      const { id } = window.__game.spawnSled(cx, cz, yaw);
      window.__sd = { id, cx, cz, crestH, tx, tz, troughH, drop, yaw, downX: cdX, downZ: cdZ };
      const slopeDeg = +(Math.asin(best.m) * 180 / Math.PI).toFixed(1);
      // Slope-distance of the face (crest→trough along the ground).
      const faceRun = Math.hypot(tx - cx, tz - cz);
      const faceLen = Math.hypot(faceRun, drop);
      return {
        ergX: +erg.x.toFixed(0), ergZ: +erg.z.toFixed(0),
        crest: [+cx.toFixed(0), +cz.toFixed(0)], crestH: +crestH.toFixed(1),
        troughH: +troughH.toFixed(1), drop: +drop.toFixed(1),
        faceSlopeDeg: slopeDeg, faceRun: +faceRun.toFixed(0), faceLen: +faceLen.toFixed(0),
      };
    });
    if (g0.error) { console.log('[sled-dune] ABORT: ' + g0.error); return; }
    console.log(`[sled-dune] PHASE 0 (erg geometry): erg@(${g0.ergX},${g0.ergZ}) crest@(${g0.crest}) crestH=${g0.crestH} troughH=${g0.troughH} DROP=${g0.drop}m faceSlope=${g0.faceSlopeDeg}° faceRun=${g0.faceRun}m faceLen=${g0.faceLen}m`);

    // ── PHASE A — free descent (real E-mount at the crest, no rider input).
    const a = await page.evaluate(async (SPRINT) => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const step = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const sd = window.__sd;
      const find = () => ctx.sleds.list.find((s) => s.id === sd.id);
      let sled = find();
      // Reset sled to the crest, stationary.
      const gy = ctx.terrain.heightAt(sd.cx, sd.cz);
      sled.body.setTranslation({ x: sd.cx, y: gy + 0.08, z: sd.cz }, true);
      sled.pos.set(sd.cx, gy + 0.08, sd.cz);
      sled.yaw = sd.yaw; sled._slideVx = 0; sled._slideVz = 0;
      await step(2);
      // Stand up-slope of the sled + look at it; press E (the real mount path).
      const pbx = sd.cx - sd.downX * 2.4, pbz = sd.cz - sd.downZ * 2.4;
      const pby = ctx.terrain.heightAt(pbx, pbz) + 1.0;
      ctx.player.body.body.setTranslation({ x: pbx, y: pby, z: pbz }, true);
      const cam = ctx.three.camera;
      cam.position.set(pbx, pby + 0.85, pbz);
      cam.lookAt(sled.pos.x, sled.pos.y + 0.2, sled.pos.z);
      cam.updateMatrixWorld(true);
      await step(1);
      ctx.input.pressed.add('KeyE');
      await step(2);
      const mounted = ctx.player.ridingSledId === sd.id;
      // Descend. Record per frame until near the trough elevation or a hard cap.
      const t0 = performance.now();
      let maxSpeed = 0, gapMax = 0, clipMin = 999;
      let px = sd.cx, pz = sd.cz;
      const disp = [];
      let reachedTroughFrame = -1, frames = 0;
      const startY = sled.pos.y;
      let stoppedFrame = -1;
      for (let i = 0; i < 900; i++) {
        await raf();
        frames++;
        sled = find();
        const vx = sled._slideVx ?? 0, vz = sled._slideVz ?? 0;
        const sp = Math.hypot(vx, vz);
        if (sp > maxSpeed) maxSpeed = sp;
        // Surface gap: deck (sled.pos.y) vs terrain at the sled XZ. Should stay
        // within clearance (~0.06-0.08) — proves the follow holds at speed.
        const terr = ctx.terrain.heightAt(sled.pos.x, sled.pos.z);
        const gap = Math.abs(sled.pos.y - terr);
        if (i > 3) gapMax = Math.max(gapMax, gap);
        clipMin = Math.min(clipMin, sled.pos.y - terr);   // <0 = clipped under terrain
        const d = Math.hypot(sled.pos.x - px, sled.pos.z - pz);
        disp.push(+d.toFixed(3));
        px = sled.pos.x; pz = sled.pos.z;
        // Reached the trough elevation?
        if (reachedTroughFrame < 0 && sled.pos.y <= sd.troughH + 1.0 && (startY - sled.pos.y) > sd.drop * 0.6) {
          reachedTroughFrame = frames;
        }
        // Fully stopped (runout complete)?
        if (reachedTroughFrame > 0 && sp < 0.4) { stoppedFrame = frames; break; }
      }
      const t1 = performance.now();
      sled = find();
      const descendedY = +(startY - sled.pos.y).toFixed(1);
      // Descent time = wall-clock to the trough (approx; the loop runs at rAF≈60fps).
      const descentTime = reachedTroughFrame > 0 ? +(reachedTroughFrame / 60).toFixed(2) : -1;
      const runoutTime = stoppedFrame > 0 ? +(stoppedFrame / 60).toFixed(2) : -1;
      // Runout distance from the trough point to the final rest.
      const runoutDist = +Math.hypot(sled.pos.x - sd.tx, sled.pos.z - sd.tz).toFixed(1);
      return {
        mounted, maxSpeed: +maxSpeed.toFixed(1), sprintX: +(maxSpeed / SPRINT).toFixed(2),
        gapMax: +gapMax.toFixed(3), clipMin: +clipMin.toFixed(3),
        descendedY, descentTime, runoutTime, runoutDist,
        wallMs: +(t1 - t0).toFixed(0),
        dispEarly: +(disp.slice(2, 8).reduce((s, v) => s + v, 0) / 6).toFixed(3),
        dispPeak: +Math.max(...disp).toFixed(3),
      };
    }, SPRINT);
    const aPass = a.mounted && a.maxSpeed > SPRINT * 1.8 && a.maxSpeed < SPRINT * 3.2
      && a.gapMax < 0.3 && a.clipMin > -0.15
      && a.descentTime >= 3.0 && a.descentTime <= 9.0;
    console.log(`[sled-dune] PHASE A (free descent): mounted=${a.mounted} maxSpeed=${a.maxSpeed}m/s (${a.sprintX}× sprint) descentTime=${a.descentTime}s descended=${a.descendedY}m gapMax=${a.gapMax}m clipMin=${a.clipMin}m runoutDist=${a.runoutDist}m runoutTime=${a.runoutTime}s dispPeak=${a.dispPeak}m/frame => ${aPass ? 'PASS' : 'FAIL'}`);

    // Screenshot the crouched rider mid-slip-face (re-mount + descend a bit, shoot).
    // Framed from a cinematic 3/4 SIDE-FRONT angle (not the chase cam) so the crouch,
    // forward lean, arms + the dust trail all read — this is the postcard AND the
    // pose-critique frame. `--poseangle=side|3q|front|chase` overrides.
    const poseAngle = argv.poseangle || '3q';
    await page.evaluate(async ({ poseAngle }) => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const sd = window.__sd;
      const sled = ctx.sleds.list.find((s) => s.id === sd.id);
      const gy = ctx.terrain.heightAt(sd.cx, sd.cz);
      sled.body.setTranslation({ x: sd.cx, y: gy + 0.08, z: sd.cz }, true);
      sled.pos.set(sd.cx, gy + 0.08, sd.cz);
      sled.yaw = sd.yaw; sled._slideVx = 0; sled._slideVz = 0;
      ctx.player.ridingSledId = sd.id;                  // direct mount for the shot
      ctx.flags.thirdPerson = true;
      window.__game.setTime(0.36);
      // Descend ~1.2s so it's mid-face at speed with a dust trail.
      for (let i = 0; i < 72; i++) await raf();
      // PAUSE so the ride's per-frame camera pin (pinRiderToSeat) can't overwrite
      // the framing below. The rig + dust freeze in their last posed state.
      ctx.flags.paused = true;
      // Frame the rider. Bow forward = sled local -Z = (-sin yaw, -cos yaw); right
      // of the bow = (cos yaw, -sin yaw). Place the camera off to the side-front.
      const cam = ctx.three.camera;
      const s2 = ctx.sleds.list.find((s) => s.id === sd.id);
      const cx = s2.pos.x, cy = s2.pos.y, cz = s2.pos.z;
      const fwdX = -Math.sin(s2.yaw), fwdZ = -Math.cos(s2.yaw);
      const rgtX = Math.cos(s2.yaw), rgtZ = -Math.sin(s2.yaw);
      const D = 4.2;
      let ex, ez, ey;
      if (poseAngle === 'side') { ex = cx + rgtX * D; ez = cz + rgtZ * D; ey = cy + 1.3; }
      else if (poseAngle === 'front') { ex = cx + fwdX * D; ez = cz + fwdZ * D; ey = cy + 1.4; }
      else if (poseAngle === 'chase') { ex = cx - fwdX * D; ez = cz - fwdZ * D; ey = cy + 1.8; }
      else { ex = cx + (fwdX * 0.7 + rgtX * 0.8) * D; ez = cz + (fwdZ * 0.7 + rgtZ * 0.8) * D; ey = cy + 1.5; } // 3q front-side
      cam.position.set(ex, ey, ez);
      cam.lookAt(cx, cy + 0.9, cz);
      cam.updateMatrixWorld(true);
    }, { poseAngle });
    await page.waitForTimeout(120);
    await page.screenshot({ path: join(OUT, 'scen-sled-dune-postcard.png'), timeout: 60000 });
    console.log('[sled-dune] screenshot saved: scen-sled-dune-postcard.png');
    // Unpause — the postcard paused the sim to freeze the framing; the remaining
    // measurement phases need the sled to move again.
    await page.evaluate(() => { window.__game.ctx.flags.paused = false; });

    // ── PHASE B — carve: A-held path deviates laterally from the free path.
    const b = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const sd = window.__sd;
      const find = () => ctx.sleds.list.find((s) => s.id === sd.id);
      // Start mid-face (already at speed — carve authority is speed-gated, so the
      // test must be ON the moving face, not nosing over the flat crest). Helper:
      // reset to a point 1/3 down the face with a downhill kick, direct-mount, run
      // N frames with an optional steer key held, return the final XZ.
      const sx = sd.cx + (sd.tx - sd.cx) * 0.30, sz = sd.cz + (sd.tz - sd.cz) * 0.30;
      const run = async (holdKey, N) => {
        const sled = find();
        const gy = ctx.terrain.heightAt(sx, sz);
        sled.body.setTranslation({ x: sx, y: gy + 0.08, z: sz }, true);
        sled.pos.set(sx, gy + 0.08, sz);
        sled.yaw = sd.yaw;
        sled._slideVx = sd.downX * 10; sled._slideVz = sd.downZ * 10;   // moving downhill
        ctx.player.ridingSledId = sd.id;
        ctx.input.keys['KeyA'] = false; ctx.input.keys['KeyD'] = false;
        if (holdKey) ctx.input.keys[holdKey] = true;
        for (let i = 0; i < N; i++) await raf();
        if (holdKey) ctx.input.keys[holdKey] = false;
        const s = find();
        return { x: s.pos.x, z: s.pos.z };
      };
      const N = 110;
      const free = await run(null, N);
      const carve = await run('KeyA', N);
      // Re-derive crest-relative offsets from the mid-face start for logging.
      sd.cx; sd.cz;
      // Lateral deviation = distance between the two end points projected off the
      // straight downhill line from the crest.
      const dxF = free.x - sx, dzF = free.z - sz;
      const dxC = carve.x - sx, dzC = carve.z - sz;
      const sep = Math.hypot(carve.x - free.x, carve.z - free.z);
      // DIRECTION assertion (2026-07-18 — the magnitude-only check passed on INVERTED
      // controls; Zach caught it in the walk-test). A = left. With forward (fx,fz),
      // left = (fz,-fx) (yaw+ is CCW from above). The A-held end must lie LEFT of the
      // free path's travel direction.
      const fl = Math.hypot(dxF, dzF) || 1;
      const leftX = dzF / fl, leftZ = -dxF / fl;
      const carveDot = +(((carve.x - free.x) * leftX + (carve.z - free.z) * leftZ) / (sep || 1)).toFixed(2);
      return { freeEnd: [+dxF.toFixed(1), +dzF.toFixed(1)], carveEnd: [+dxC.toFixed(1), +dzC.toFixed(1)], sep: +sep.toFixed(1), carveDot };
    });
    const bPass = b.sep > 3.0 && b.carveDot > 0.3;
    console.log(`[sled-dune] PHASE B (carve): freeEndOffset=${b.freeEnd} carveEndOffset=${b.carveEnd} lateralSep=${b.sep}m carveDot(A=left)=${b.carveDot} => ${bPass ? 'PASS' : 'FAIL'}`);

    // ── PHASE C — uphill stall: kick the sled UPHILL; it must decelerate + slide back.
    const c = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const sd = window.__sd;
      const find = () => ctx.sleds.list.find((s) => s.id === sd.id);
      // Place mid-face, facing UPHILL, kicked uphill at 9 m/s.
      const mx = (sd.cx + sd.tx) / 2, mz = (sd.cz + sd.tz) / 2;
      const gy = ctx.terrain.heightAt(mx, mz);
      const sled = find();
      sled.body.setTranslation({ x: mx, y: gy + 0.08, z: mz }, true);
      sled.pos.set(mx, gy + 0.08, mz);
      // Uphill dir = opposite the downhill normal at mid-face.
      const n = ctx.terrain.normalAt(mx, mz); const m = Math.hypot(n.x, n.z);
      const upX = -n.x / m, upZ = -n.z / m;
      sled.yaw = Math.atan2(-upX, -upZ);   // bow faces uphill
      sled._slideVx = upX * 9; sled._slideVz = upZ * 9;
      ctx.player.ridingSledId = sd.id;
      ctx.input.keys['KeyW'] = false;   // no paddle — pure momentum test
      const startH = sled.pos.y;
      let maxGainH = 0, maxUpDist = 0;
      for (let i = 0; i < 240; i++) {
        await raf();
        const s = find();
        maxGainH = Math.max(maxGainH, s.pos.y - startH);
        // signed uphill progress from start
        const px = s.pos.x - mx, pz = s.pos.z - mz;
        const upDist = px * upX + pz * upZ;
        maxUpDist = Math.max(maxUpDist, upDist);
      }
      const s = find();
      const endH = s.pos.y;
      const endVx = s._slideVx ?? 0, endVz = s._slideVz ?? 0;
      const endUpVel = endVx * upX + endVz * upZ;   // <0 = now sliding back down
      return {
        maxUpDist: +maxUpDist.toFixed(1), maxGainH: +maxGainH.toFixed(1),
        netH: +(endH - startH).toFixed(1), endUpVel: +endUpVel.toFixed(2),
      };
    });
    // Stall = climbed only a little then reversed (final velocity is downhill, and
    // it ended LOWER than it started — momentum carried it up briefly then gravity won).
    const cPass = c.maxUpDist < 12 && c.endUpVel < 0 && c.netH < 0;
    console.log(`[sled-dune] PHASE C (uphill stall): maxUphillDist=${c.maxUpDist}m maxHgain=${c.maxGainH}m netH=${c.netH}m finalUphillVel=${c.endUpVel}m/s => ${cPass ? 'PASS' : 'FAIL'}`);

    // ── PHASE D — dismount at speed on the slope: sled coasts + settles, player safe.
    const d = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const step = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const sd = window.__sd;
      const find = () => ctx.sleds.list.find((s) => s.id === sd.id);
      // Reset to crest, mount, build speed.
      const sled = find();
      const gy = ctx.terrain.heightAt(sd.cx, sd.cz);
      sled.body.setTranslation({ x: sd.cx, y: gy + 0.08, z: sd.cz }, true);
      sled.pos.set(sd.cx, gy + 0.08, sd.cz);
      sled.yaw = sd.yaw; sled._slideVx = 0; sled._slideVz = 0;
      ctx.player.ridingSledId = sd.id;
      // Descend until moving fast.
      let speedAtDismount = 0;
      for (let i = 0; i < 200; i++) {
        await raf();
        const s = find();
        speedAtDismount = Math.hypot(s._slideVx ?? 0, s._slideVz ?? 0);
        if (speedAtDismount > 10) break;
      }
      const sBefore = find();
      const sledYBefore = sBefore.pos.y;
      // Dismount (JUMP).
      ctx.input.pressed.add('Space');
      await step(2);
      const dismounted = ctx.player.ridingSledId === null;
      const p = ctx.player.body.body.translation();
      const pgy = ctx.terrain.heightAt(p.x, p.z);
      const capBottom = p.y - (ctx.player.body.halfHeight + ctx.player.body.radius);
      const standGap = +(capBottom - pgy).toFixed(3);
      // Player should be on the UPHILL side of the sled (higher terrain than the sled's).
      const sNow = find();
      const playerHigherThanSled = p.y > sNow.pos.y - 0.5;
      // Sled keeps sliding briefly then settles — sample speed a few frames on.
      const sledSpeedJustAfter = Math.hypot(sNow._slideVx ?? 0, sNow._slideVz ?? 0);
      await step(120);
      const sSettled = find();
      const sledSpeedSettled = Math.hypot(sSettled._slideVx ?? 0, sSettled._slideVz ?? 0);
      const sledClip = +(sSettled.pos.y - ctx.terrain.heightAt(sSettled.pos.x, sSettled.pos.z)).toFixed(3);
      return {
        speedAtDismount: +speedAtDismount.toFixed(1), dismounted,
        standGap, onGround: ctx.player.onGround === true, playerHigherThanSled,
        sledSpeedJustAfter: +sledSpeedJustAfter.toFixed(1), sledSpeedSettled: +sledSpeedSettled.toFixed(2),
        sledClip, sledCoasted: sledSpeedJustAfter > 0.5,
      };
    });
    // On a 32° slip face a released sled keeps sliding to the trough (Mad-Max rules) —
    // "settles" means it doesn't FREEZE mid-slope + doesn't tunnel, and the player is
    // placed safely uphill. So: retained its momentum (coasted, not frozen) + on ground
    // + safe uphill placement + never clipped through terrain while coasting.
    const dPass = d.dismounted && d.onGround && Math.abs(d.standGap) < 0.2
      && d.playerHigherThanSled && d.sledCoasted && d.sledClip > -0.15;
    console.log(`[sled-dune] PHASE D (dismount@speed): speedAtDismount=${d.speedAtDismount}m/s dismounted=${d.dismounted} onGround=${d.onGround} standGap=${d.standGap}m playerUphill=${d.playerHigherThanSled} sledCoasted=${d.sledCoasted} sledSpeedSettled=${d.sledSpeedSettled}m/s sledClip=${d.sledClip}m => ${dPass ? 'PASS' : 'FAIL'}`);

    const allPass = aPass && bPass && cPass && dPass;
    console.log(`[sled-dune] RESULT: ${allPass ? 'ALL PHASES PASS' : 'FAILURE — see phases above'}`);
  },

  // ── sled-pose (Deep-Desert cycle 6) — FAST rider-pose iteration. Spawns a sled
  // on a gentle slope near origin (no 13km erg warp), direct-mounts, ticks so
  // updatePlayerRig poses the crouched rider, gives it a little speed for a dust
  // puff, pauses, and shoots the pose from 3q / side / front (three files). Pure
  // pose critique — no physics measurement. ~1 boot, 3 frames.
  'sled-pose': async (page) => {
    const info = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      ctx.flags.paused = false;
      ctx.flags.thirdPerson = true;
      window.__game.setTime(0.36);
      const nh = (x, z) => { const n = ctx.terrain.normalAt(x, z); return Math.hypot(n.x, n.z); };
      // Find a mild slope near origin so the sled sits tilted (reads better) + can slide a touch.
      let best = { x: 20, z: 0, m: 0 };
      for (let r = 12; r <= 120; r += 6) {
        for (let deg = 0; deg < 360; deg += 15) {
          const x = Math.cos(deg * Math.PI / 180) * r, z = Math.sin(deg * Math.PI / 180) * r;
          const m = nh(x, z);
          if (m > 0.12 && m < 0.4 && m > best.m) best = { x, z, m };
        }
      }
      const n = ctx.terrain.normalAt(best.x, best.z); const mm = Math.hypot(n.x, n.z) || 1;
      const downX = n.x / mm, downZ = n.z / mm;
      const yaw = Math.atan2(-downX, -downZ);
      const { id } = window.__game.spawnSled(best.x, best.z, yaw);
      const sled = ctx.sleds.list.find((s) => s.id === id);
      sled._slideVx = downX * 6; sled._slideVz = downZ * 6;   // a little motion for a dust puff
      ctx.player.ridingSledId = id;
      for (let i = 0; i < 30; i++) await raf();               // pose settles + dust spawns
      window.__spose = { id };
      return { at: [+best.x.toFixed(0), +best.z.toFixed(0)], slope: +best.m.toFixed(2) };
    });
    console.log('[sled-pose] mounted on slope ' + JSON.stringify(info));
    for (const angle of ['3q', 'side', 'front']) {
      await page.evaluate((angle) => {
        const ctx = window.__game.ctx;
        const sled = ctx.sleds.list.find((s) => s.id === window.__spose.id);
        ctx.flags.paused = true;                              // freeze so the ride pin can't re-grab the camera
        const cam = ctx.three.camera;
        const cx = sled.pos.x, cy = sled.pos.y, cz = sled.pos.z;
        const fwdX = -Math.sin(sled.yaw), fwdZ = -Math.cos(sled.yaw);
        const rgtX = Math.cos(sled.yaw), rgtZ = -Math.sin(sled.yaw);
        const D = 3.8;
        let ex, ez, ey;
        if (angle === 'side') { ex = cx + rgtX * D; ez = cz + rgtZ * D; ey = cy + 1.2; }
        else if (angle === 'front') { ex = cx + fwdX * D; ez = cz + fwdZ * D; ey = cy + 1.3; }
        else { ex = cx + (fwdX * 0.7 + rgtX * 0.8) * D; ez = cz + (fwdZ * 0.7 + rgtZ * 0.8) * D; ey = cy + 1.4; }
        cam.position.set(ex, ey, ez);
        cam.lookAt(cx, cy + 0.85, cz);
        cam.updateMatrixWorld(true);
      }, angle);
      await page.waitForTimeout(120);
      await page.screenshot({ path: join(OUT, `scen-sled-pose-${angle}.png`), timeout: 60000 });
      console.log(`[sled-pose] saved scen-sled-pose-${angle}.png`);
      await page.evaluate(() => { window.__game.ctx.flags.paused = false; });
    }
  },

  // Prompt-3P (ACW F #149): place the player near a ground pickup, aim the 3P
  // camera at it so the eye-ray hovers it, tick live, then verify the prompt was
  // re-pinned to the object's projected screen position (inline left set to a px
  // value) instead of the CSS crosshair-center default ("50%"). Also screenshots.
  'prompt-3p': async (page) => {
    const setup = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; window.__game.setTime(0.5);
      ctx.three.renderer.toneMappingExposure = 1.1;
      ctx.three.renderer.setSize(900, 700, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 700; cam.updateProjectionMatrix(); }
      ctx.flags.thirdPerson = true;
      const p = ctx.pickups.list[0];
      if (!p) return { err: 'no pickup' };
      // Put the player ~2.4m from the pickup; aim the eye/camera at it.
      const px = p.pos.x, pz = p.pos.z, py = ctx.terrain.heightAt(px, pz);
      const bx = px, bz = pz + 2.4, by = py + 1.0;
      ctx.player.body.body.setTranslation({ x: bx, y: by, z: bz }, true);
      cam.position.set(bx, by + 0.7, bz + 1.5); // 3P behind; eye-ray still aims fwd
      cam.lookAt(px, py + 0.2, pz);
      cam.updateMatrixWorld(true);
      return { pickup: p.itemId, at: [+px.toFixed(1), +pz.toFixed(1)] };
    });
    console.log('[prompt-3p] setup ' + JSON.stringify(setup));
    // Tick live so updateInteraction raycasts + updateInteractPrompt repositions.
    for (let i = 0; i < 12; i++) {
      await page.evaluate(() => {
        const ctx = window.__game.ctx;
        const p = ctx.pickups.list[0];
        if (p) { const cam = ctx.three.camera; cam.lookAt(p.pos.x, ctx.terrain.heightAt(p.pos.x, p.pos.z) + 0.2, p.pos.z); cam.updateMatrixWorld(true); }
      });
      await page.waitForTimeout(70);
    }
    const result = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const el = document.getElementById('interact-prompt');
      return {
        hover: ctx.inventory.hover ? ctx.inventory.hover.promptNoun : null,
        promptLeft: el ? el.style.left : '(none)',
        promptTop: el ? el.style.top : '(none)',
        transform: el ? el.style.transform : '(none)',
      };
    });
    console.log('[prompt-3p] ' + JSON.stringify(result));
    await page.waitForTimeout(150);
    await page.screenshot({ path: join(OUT, 'scen-prompt-3p.png'), fullPage: false });
    console.log('[rig-shot] saved scen-prompt-3p.png');
  },

  // Shrew flee: face the player at a shrew ~5m ahead (< SPOT_DISTANCE 7m), 1P
  // static camera. The shrew flees directly AWAY from the camera, so it recedes
  // along the view axis and stays roughly centered — the strip shows the bolt
  // (recede + skittery hop) without per-frame tracking.
  'shrew-flee': async (page) => {
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.three.renderer.toneMappingExposure = 1.6; // brighten for a clear critter read
      const cam = ctx.three.camera;
      const s = ctx.shrews.list[0];
      const sx = s.pos.x, sz = s.pos.z, sy = ctx.terrain.heightAt(sx, sz);
      const px = sx, pz = sz - 2.8, py = sy + 1.6;   // 2.8m south of the shrew (well < SPOT 7m)
      ctx.player.body.body.setTranslation({ x: px, y: py, z: pz }, true);
      cam.position.set(px, py, pz);
      cam.lookAt(sx, sy + 0.1, sz);
      cam.updateMatrixWorld(true);
      return { shrewId: s.id, state0: s.state, start: [+sx.toFixed(2), +sz.toFixed(2)],
               horizDist: +Math.hypot(cam.position.x - sx, cam.position.z - sz).toFixed(2) };
    });
    console.log(`[shrew-flee] shrew#${info.shrewId} @${info.start} dist=${info.horizDist}m state=${info.state0}`);
    // Re-pin the 1P camera each frame, angled down at the critter (it flees away
    // from the camera so it recedes along the view axis + stays centered).
    await captureStrip(page, 'shrew-flee', `(i)=>{const c=window.__game.ctx;const s=c.shrews.list[0];const cam=c.three.camera;const gy=c.terrain.heightAt(s.pos.x,s.pos.z);cam.position.set(s.pos.x,gy+1.6,s.pos.z-2.8);cam.lookAt(s.pos.x,gy+0.1,s.pos.z);cam.updateMatrixWorld(true);console.log('[shrew-flee] f'+i+' state='+s.state+' pos='+s.pos.x.toFixed(2)+','+s.pos.z.toFixed(2));}`);
    const end = await page.evaluate(() => {
      const s = window.__game.ctx.shrews.list[0];
      return { state: s.state, pos: [+s.pos.x.toFixed(2), +s.pos.z.toFixed(2)] };
    });
    console.log(`[shrew-flee] END state=${end.state} pos=${end.pos}`);
  },

  // Lizard-flee (ACW B4): force the lizard into a FIXED-direction flee (the AI
  // normally flees away from the camera, which keeps it tail-on — useless for
  // reading a gait). We pin fleeDir north + a far fleeUntil, then track from a
  // CLOSE side-profile camera (east of the lizard) so the 4 stepping legs are
  // visible. brightened exposure + a tight frame.
  'lizard-flee': async (page) => {
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.three.renderer.toneMappingExposure = 1.7;
      const l = ctx.lizards[0];
      const sy = ctx.terrain.heightAt(l.pos.x, l.pos.z);
      // Force a steady northward flee (z+), independent of camera position.
      l.state = 'flee';
      l.fleeDir.set(0, 0, 1);
      l.fleeUntil = ctx.time.elapsed + 999;
      const cam = ctx.three.camera;
      // Teleport the player body to the side-view spot too — syncCameraToBody
      // re-pins the camera to the body each tick, so the camera alone won't stick.
      ctx.player.body.body.setTranslation({ x: l.pos.x + 0.55, y: sy + 0.50, z: l.pos.z + 0.15 }, true);
      cam.position.set(l.pos.x + 0.55, sy + 0.50, l.pos.z + 0.15);
      cam.lookAt(l.pos.x, sy + 0.04, l.pos.z);
      cam.updateMatrixWorld(true);
      return { lizardId: l.id, state0: l.state, pos: [+l.pos.x.toFixed(2), +l.pos.z.toFixed(2)] };
    });
    console.log(`[lizard-flee] lizard#${info.lizardId} state=${info.state0} pos=${info.pos}`);
    // Track from the east side at 0.85m, low angle, re-pinning fleeDir + body each frame.
    await captureStrip(page, 'lizard-flee', `(i)=>{const c=window.__game.ctx;const l=c.lizards[0];l.state='flee';l.fleeDir.set(0,0,1);l.fleeUntil=c.time.elapsed+999;const cam=c.three.camera;const gy=c.terrain.heightAt(l.pos.x,l.pos.z);c.player.body.body.setTranslation({x:l.pos.x+0.55,y:gy+0.50,z:l.pos.z+0.15},true);cam.position.set(l.pos.x+0.55,gy+0.50,l.pos.z+0.15);cam.lookAt(l.pos.x,gy+0.04,l.pos.z);cam.updateMatrixWorld(true);console.log('[lizard-flee] f'+i+' state='+l.state+' pos='+l.pos.x.toFixed(2)+','+l.pos.z.toFixed(2));}`);
    const end = await page.evaluate(() => {
      const l = window.__game.ctx.lizards[0];
      return { state: l.state, pos: [+l.pos.x.toFixed(2), +l.pos.z.toFixed(2)] };
    });
    console.log(`[lizard-flee] END state=${end.state} pos=${end.pos}`);
  },

  // Lizard-gait (ACW B4 STATIC): the reliable read for a small creature's
  // gait. Enter live (lizard + terrain exist), kill the storm + force bright
  // noon, then for each of several gait phases: PAUSE (main loop early-returns,
  // so a free camera sticks + the manual leg pose survives), replicate the
  // sprawl-gait formula on the lizard's stored leg pivots at that phase, frame
  // a close 3/4 camera, and screenshot. Output: scen-lizard-gait-pNN.png.
  'lizard-gait': async (page) => {
    const phases = [0.0, 0.2, 0.4, 0.6, 0.8];
    for (let i = 0; i < phases.length; i++) {
      const p = phases[i];
      await page.evaluate((p) => {
        const ctx = window.__game.ctx;
        ctx.weather.intensity = 0;               // clear any storm dimming
        window.__game.setTime(0.5);              // bright midday
        ctx.three.renderer.toneMappingExposure = 1.15;
        ctx.three.renderer.setSize(900, 900, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
        const l = ctx.lizards[0];
        const sy = ctx.terrain.heightAt(l.pos.x, l.pos.z);
        l.mesh.position.set(l.pos.x, sy + 0.06, l.pos.z);
        l.mesh.rotation.set(0, 0, 0);            // face local +X (toward camera-left)
        // Replicate animateLizardLegs at this phase (swing 0.55 / lift 0.014).
        const legs = l.mesh.userData.gaitLegs || [];
        const phase = p * Math.PI * 2;
        for (const leg of legs) {
          const pp = phase + leg.offset;
          leg.grp.rotation.z = Math.sin(pp) * 0.72;
          leg.grp.position.y = leg.baseY + Math.max(0, Math.cos(pp)) * 0.022;
        }
        ctx.flags.paused = true;                 // freeze so the camera + pose stick
        l.mesh.updateMatrixWorld(true);
        // Close 3/4 side view focused on the legs: lizard's local +X is world
        // +X (no yaw), so a camera off the +X/+Z corner at low height sees the
        // flank + all four legs stepping.
        cam.position.set(l.pos.x + 0.24, sy + 0.16, l.pos.z + 0.30);
        cam.lookAt(l.pos.x + 0.02, sy + 0.045, l.pos.z);
        cam.updateMatrixWorld(true);
      }, p);
      await page.waitForTimeout(250);
      const path = join(OUT, `scen-lizard-gait-p${String(i).padStart(2, '0')}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[lizard-gait] phase=${p} → ${path}`);
    }
  },

  // Shrew-gait (ACW B5 STATIC): same paused-pose technique as lizard-gait, for
  // the ~9cm shrew (camera pulled in tighter). Confirms the stubby-leg walk.
  'shrew-gait': async (page) => {
    const phases = [0.0, 0.25, 0.5, 0.75];
    for (let i = 0; i < phases.length; i++) {
      const p = phases[i];
      await page.evaluate((p) => {
        const ctx = window.__game.ctx;
        ctx.weather.intensity = 0;
        window.__game.setTime(0.5);
        ctx.three.renderer.toneMappingExposure = 1.15;
        ctx.three.renderer.setSize(900, 900, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
        const s = ctx.shrews.list[0];
        const sy = ctx.terrain.heightAt(s.pos.x, s.pos.z);
        s.mesh.position.set(s.pos.x, sy + 0.04, s.pos.z);
        s.mesh.rotation.set(0, 0, 0);
        const legs = s.mesh.userData.gaitLegs || [];
        const phase = p * Math.PI * 2;
        for (const leg of legs) {
          const pp = phase + leg.offset;
          leg.grp.rotation.z = Math.sin(pp) * 0.5;
          leg.grp.position.y = leg.baseY + Math.max(0, Math.cos(pp)) * 0.008;
        }
        ctx.flags.paused = true;
        s.mesh.updateMatrixWorld(true);
        cam.position.set(s.pos.x + 0.15, sy + 0.11, s.pos.z + 0.19);
        cam.lookAt(s.pos.x + 0.01, sy + 0.03, s.pos.z);
        cam.updateMatrixWorld(true);
      }, p);
      await page.waitForTimeout(250);
      const path = join(OUT, `scen-shrew-gait-p${String(i).padStart(2, '0')}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[shrew-gait] phase=${p} → ${path}`);
    }
  },

  // Shrew-burrow (ACW B5 STATIC): the live FP camera can't be parked reliably
  // (the KCC stomps the body teleport), so verify the DIVE VISUAL the paused
  // way: manually set burrowT at several depths, replicate the burrow math
  // (sink below the surface + nose-down tilt + vanish past 0.85), and shoot a
  // close camera that looks at the surface so the terrain occludes the sunk
  // body (reads as "submerged in the sand"). The puff + trigger are verified
  // functionally (state machine + emitBurst); the dive feel is foreground-owed.
  'shrew-burrow': async (page) => {
    // The shrew (~9cm) vanishes under the solid terrain plane by burrowT~0.3
    // (DEPTH 0.34m), so the VISIBLE dive is the early range — shoot it dense.
    const ts = [0.0, 0.08, 0.16, 0.26];
    for (let i = 0; i < ts.length; i++) {
      const t = ts[i];
      await page.evaluate((t) => {
        const ctx = window.__game.ctx;
        ctx.weather.intensity = 0;
        window.__game.setTime(0.5);
        ctx.three.renderer.toneMappingExposure = 1.15;
        ctx.three.renderer.setSize(900, 900, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
        const s = ctx.shrews.list[0];
        const sx = s.pos.x, sz = s.pos.z;
        const surfaceY = ctx.terrain.heightAt(sx, sz) + 0.04; // SHREW_TERRAIN_OFFSET
        const DEPTH = 0.34;
        s.mesh.position.set(sx, surfaceY - t * DEPTH, sz);
        s.mesh.rotation.set(0, 0, -t * 0.6); // nose-down dive tilt
        s.mesh.visible = t < 0.85;
        ctx.flags.paused = true;
        s.mesh.updateMatrixWorld(true);
        // Close ~45° view: sand line cuts across the shrew so the descending
        // body reads (top half above sand, lower half clipped into the ground).
        cam.position.set(sx + 0.17, surfaceY + 0.16, sz + 0.20);
        cam.lookAt(sx, surfaceY + 0.01, sz);
        cam.updateMatrixWorld(true);
      }, t);
      await page.waitForTimeout(250);
      const path = join(OUT, `scen-shrew-burrow-t${String(i).padStart(2, '0')}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[shrew-burrow] burrowT=${t} → ${path}`);
    }
  },

  // Rig3p (ACX): the TRUE 3P verification — equip an item (--item=<id>, omit for
  // bare hands), let the rig settle into its REAL idle pose (no posed-out arm),
  // then frame the camera BEHIND the player looking forward, matching what the
  // user sees in play. This is the correct frame for judging hand orientation +
  // which hand + item facing (the held-item scenario's posed-out arm lied).
  'rig3p': async (page) => {
    const item = argv.item || '';
    const lit = !!argv.lit;   // C27 — --lit lights a torch (meta.lit) so the 3P flame shows
    await page.evaluate(({ item, lit }) => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0;
      window.__game.setTime(lit ? 0.0 : 0.5);   // night for a lit-torch shot so the flame reads
      ctx.three.renderer.toneMappingExposure = 1.1;
      ctx.three.renderer.setSize(800, 950, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 800 / 950; cam.updateProjectionMatrix(); }
      ctx.flags.thirdPerson = true;
      const inv = ctx.inventory;
      if (item) {
        inv.slots[0].item = item; inv.slots[0].count = 1;
        inv.slots[0].meta = lit ? { lit: true, burnRemaining: 1 } : undefined;
        inv.selectedIdx = 0;
      } else { inv.slots[0].item = null; }
    }, { item, lit });
    await page.waitForTimeout(500); // settle the idle pose + swap the mesh into the hand
    const info = await page.evaluate((handCloseup) => {
      const ctx = window.__game.ctx;
      const rig = ctx.player.rig;
      ctx.flags.paused = true;
      rig.group.updateMatrixWorld(true);
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      const root = rig.group.getWorldPosition(new V());
      const h = rig.heading;
      // rig.group.rotation.y = heading rotates local +Z onto (sin h, 0, cos h),
      // so that is the player's forward. Camera BEHIND the player, looking fwd.
      const fwd = new V(Math.sin(h), 0, Math.cos(h));
      // Close behind view biased toward the player's RIGHT hand (where held
      // items now sit), hip-height, matching the user's screenshot framing.
      const pright = new V(-fwd.z, 0, fwd.x); // player's right (local -X → world)
      if (handCloseup === 'hand') {
        // Tight closeup on the right hand to judge palm/finger orientation.
        const hp = rig.rightHandAttach.getWorldPosition(new V());
        // Pure side view from OUTSIDE the body (player's right), at hand height,
        // so the torso/buttocks don't occlude the hand.
        cam.position.set(
          hp.x + pright.x * 0.42 + fwd.x * 0.05,
          hp.y + 0.05,
          hp.z + pright.z * 0.42 + fwd.z * 0.05,
        );
        cam.lookAt(hp.x, hp.y - 0.02, hp.z);
      } else if (handCloseup === 'profile') {
        // Side profile from the player's RIGHT, so forward (+fwd) reads as a
        // clear left/right screen axis — unambiguous for "item points forward".
        cam.position.set(
          root.x + pright.x * 2.0,
          root.y + 1.0,
          root.z + pright.z * 2.0,
        );
        cam.lookAt(root.x, root.y + 0.85, root.z);
      } else {
        cam.position.set(
          root.x - fwd.x * 1.1 + pright.x * 0.5,
          root.y + 1.15,
          root.z - fwd.z * 1.1 + pright.z * 0.5,
        );
        cam.lookAt(root.x + pright.x * 0.18, root.y + 0.85, root.z + pright.z * 0.18);
      }
      cam.updateMatrixWorld(true);
      // ACX debug — the hand-attach world frame + the direction (in
      // attach-LOCAL space) that points the player's world-forward. The item's
      // mesh-forward axis, after handAttachTransform.rot, must equal localFwd.
      const Q = cam.quaternion.constructor;
      const aq = rig.rightHandAttach.getWorldQuaternion(new Q());
      const inv = aq.clone().invert();
      const worldFwd = new V(Math.sin(h), 0, Math.cos(h));
      const worldUp = new V(0, 1, 0);
      const localFwd = worldFwd.clone().applyQuaternion(inv);
      const localUp = worldUp.clone().applyQuaternion(inv);
      console.error('[handframe] localFwd=' + [localFwd.x, localFwd.y, localFwd.z].map((v) => +v.toFixed(2)).join(',') +
        ' localUp=' + [localUp.x, localUp.y, localUp.z].map((v) => +v.toFixed(2)).join(','));
      return { heading: +h.toFixed(2), rootY: +root.y.toFixed(2) };
    }, argv.hand ? 'hand' : (argv.view || ''));
    console.log('[rig3p] ' + JSON.stringify(info));
    await page.waitForTimeout(200);
    const tag = (item || 'bare') + (lit ? '-lit' : '');
    await page.screenshot({ path: join(OUT, `scen-rig3p-${tag}.png`), fullPage: false });
    console.log(`[rig-shot] saved scen-rig3p-${tag}.png`);
  },

  // Footprint-repro (ACX): equip the gun in 3P, stamp a line of player
  // footprints at the feet, then frame low-behind so the held gun overlaps the
  // ground decals on screen — to confirm + diagnose footsteps-through-items.
  'footprint-repro': async (page) => {
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; window.__game.setTime(0.5);
      ctx.three.renderer.toneMappingExposure = 1.15; ctx.three.renderer.setSize(820, 820, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
      ctx.flags.thirdPerson = true;
      const inv = ctx.inventory;
      inv.slots[0].item = 'scrap_gun'; inv.slots[0].count = 1; inv.slots[0].meta = undefined; inv.selectedIdx = 0;
    });
    await page.waitForTimeout(500);
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const rig = ctx.player.rig;
      rig.group.updateMatrixWorld(true);
      const V = ctx.three.camera.position.constructor;
      const root = rig.group.getWorldPosition(new V());
      const h = rig.heading;
      const fwd = new V(Math.sin(h), 0, Math.cos(h));
      // Stamp a dense patch of footprints on the ground AHEAD of the player so
      // the hip-held gun projects onto them from a high-behind, looking-down cam.
      for (let i = 0; i <= 8; i++) {
        for (let j = -1; j <= 1; j++) {
          const px = root.x + fwd.x * (0.2 + i * 0.18) + (-fwd.z) * j * 0.18;
          const pz = root.z + fwd.z * (0.2 + i * 0.18) + (fwd.x) * j * 0.18;
          ctx.footprints.spawn('player', px, pz, h, ctx.time.elapsed);
        }
      }
      ctx.flags.paused = true;
      const cam = ctx.three.camera;
      // High behind, steep look-down so the gun (hip) overlaps the ground decals
      // ahead — the depth case that exposes see-through.
      cam.position.set(root.x - fwd.x * 0.6, root.y + 2.3, root.z - fwd.z * 0.6);
      cam.lookAt(root.x + fwd.x * 1.2, root.y, root.z + fwd.z * 1.2);
      cam.updateMatrixWorld(true);
    });
    await page.waitForTimeout(200);
    await page.screenshot({ path: join(OUT, 'scen-footprint-repro.png'), fullPage: false });
    console.log('[rig-shot] saved scen-footprint-repro.png');
  },

  // Speeder-seated (ACX): mount the bike in 3P + frame a clean chase cam behind
  // it, to verify the seated rig (facing forward, gripping bars, feet on pegs).
  'speeder-seated': async (page) => {
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; window.__game.setTime(0.5);
      ctx.three.renderer.toneMappingExposure = 1.1; ctx.three.renderer.setSize(820, 950, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 820 / 950; cam.updateProjectionMatrix(); }
      ctx.flags.thirdPerson = true;
      const s = ctx.speeder;
      // Force-mount: park the player capsule far below (as the real mount does)
      // and flag mounted so updateSpeeder's mounted path + updatePlayerRig's
      // seated branch run.
      s.mounted = true;
      ctx.player.body.body.setTranslation({ x: s.body.translation().x, y: -2000, z: s.body.translation().z }, true);
    });
    await page.waitForTimeout(300);
    // Point the camera-look along the bike's forward (as a rider looking ahead),
    // so the GAME's chase cam (driven by updateSpeeder) places itself behind +
    // the bike yaw aligns. We do NOT override the camera — this reproduces the
    // actual in-game view the user sees.
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const s = ctx.speeder;
      const yaw = s.yaw;
      const bf = new (ctx.three.camera.position.constructor)(-Math.sin(yaw), 0, -Math.cos(yaw));
      const cam = ctx.three.camera;
      const tgt = new (cam.position.constructor)(cam.position.x + bf.x, cam.position.y, cam.position.z + bf.z);
      cam.lookAt(tgt);
      cam.updateMatrixWorld(true);
    });
    await page.waitForTimeout(600); // let the live chase cam settle + bike-yaw lerp
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const s = ctx.speeder;
      const p = s.body.translation();
      const yaw = s.yaw;
      const bfx = -Math.sin(yaw), bfz = -Math.cos(yaw); // bike forward
      const cam = ctx.three.camera;
      // Measure the rig's actual facing (local +Z is the FACE, D137) + which
      // side of the bike the (game-placed) camera is on.
      const rig = ctx.player.rig;
      const V = cam.position.constructor; const Q = cam.quaternion.constructor;
      const rq = rig.group.getWorldQuaternion(new Q());
      const face = new V(0, 0, 1).applyQuaternion(rq);
      const faceDotFwd = +(face.x * bfx + face.z * bfz).toFixed(2);
      // camera-to-bike vector vs bikeForward: + = cam is BEHIND (sees rear), - = cam in FRONT.
      const camToBikeX = p.x - cam.position.x, camToBikeZ = p.z - cam.position.z;
      const camDotFwd = +(camToBikeX * bfx + camToBikeZ * bfz).toFixed(2);
      console.error('[seatfacing] faceDotFwd=' + faceDotFwd + (faceDotFwd > 0 ? '(rig FORWARD)' : '(rig BACKWARD)') +
        ' camDotFwd=' + camDotFwd + (camDotFwd > 0 ? '(cam BEHIND)' : '(cam FRONT)'));
      // BEHIND view (matches the user's chase-cam screenshot) so the riding
      // pose reads as they see it: hands on bars, feet on pegs, sit.
      ctx.flags.paused = true;
      cam.position.set(p.x - bfx * 3.0, p.y + 1.9, p.z - bfz * 3.0);
      cam.lookAt(p.x + bfx * 0.6, p.y + 0.4, p.z + bfz * 0.6);
      cam.updateMatrixWorld(true);
      return { yaw: +yaw.toFixed(2), faceDotFwd, camDotFwd };
    });
    console.log('[speeder-seated] ' + JSON.stringify(info));
    await page.waitForTimeout(200);
    await page.screenshot({ path: join(OUT, 'scen-speeder-seated.png'), fullPage: false });
    console.log('[rig-shot] saved scen-speeder-seated.png');
  },

  // Bike-truth (ACX): the DECISIVE multi-angle rig-on-bike inspection. Prior
  // speeder-seated lied because it OVERRODE the camera with a hand-placed
  // behind-cam — so it never rendered what the user actually sees, and its
  // faceDotFwd measurement assumed +Z=face. Here we (a) force bike yaw=0 so the
  // nose points world -Z and tail/+Z is unambiguous, (b) mount, (c) shoot the
  // REAL game chase camera (no override) = exactly the user's view, then (d)
  // shoot 5 fixed WORLD angles so the pose (facing, hands-on-bars, feet-on-pegs)
  // can be judged from every side. Output: scen-bike-<angle>.png.
  'bike-truth': async (page) => {
    // Mount + force yaw 0, on flat-ish ground, look along bike forward (-Z).
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; window.__game.setTime(0.5);
      ctx.three.renderer.toneMappingExposure = 1.1; ctx.three.renderer.setSize(900, 900, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
      ctx.flags.thirdPerson = true;
      const s = ctx.speeder;
      // Pin the bike to yaw=0 (nose → world -Z) so external angles are unambiguous.
      s.body.setRotation({ x: 0, y: 0, z: 0, w: 1 }, true);
      s.yaw = 0;
      const p = s.body.translation();
      s.mounted = true;
      ctx.player.body.body.setTranslation({ x: p.x, y: -2000, z: p.z }, true);
      // Camera euler.y = yaw makes getWorldDirection = (-sin yaw,0,-cos yaw) = bike fwd.
      cam.quaternion.setFromEuler(new (cam.rotation.constructor)(0, s.yaw, 0, 'YXZ'));
      cam.updateMatrixWorld(true);
      return { x: +p.x.toFixed(1), y: +p.y.toFixed(1), z: +p.z.toFixed(1) };
    });
    console.log('[bike-truth] bike@ ' + JSON.stringify(info));
    // Let updateSpeeder drive the chase cam + bike-yaw lerp settle (no override).
    await page.waitForTimeout(700);
    // (1) The REAL game chase-cam view — what the user sees. Pause AFTER the
    // game has positioned the camera this frame, do NOT touch cam.position.
    const meas = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const s = ctx.speeder; const cam = ctx.three.camera;
      const V = cam.position.constructor; const Q = cam.quaternion.constructor;
      const p = s.body.translation();
      const bfx = -Math.sin(s.yaw), bfz = -Math.cos(s.yaw);
      const rig = ctx.player.rig;
      const rq = rig.group.getWorldQuaternion(new Q());
      const face = new V(0, 0, 1).applyQuaternion(rq);
      const camToBikeX = p.x - cam.position.x, camToBikeZ = p.z - cam.position.z;
      // NUMERIC IK CHECK — world positions of the hands + feet vs the bike's
      // grip/peg world targets (yaw=0 so bike-local==world+bike pos). Distances
      // near 0 = contact. This is the trustworthy gate (not eyeballing pixels).
      rig.group.updateMatrixWorld(true);
      const wp = (n) => { const v = n.getWorldPosition(new V()); return [+v.x.toFixed(2), +v.y.toFixed(2), +v.z.toFixed(2)]; };
      const grip = [[p.x - 0.34, p.y + 0.42, p.z + 0.00], [p.x + 0.34, p.y + 0.42, p.z + 0.00]];
      const peg  = [[p.x - 0.43, p.y - 0.08, p.z + 0.15], [p.x + 0.43, p.y - 0.08, p.z + 0.15]];
      const dist = (a, b) => +Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]).toFixed(2);
      const hands = [wp(rig.wrists[0]), wp(rig.wrists[1])];
      const feet = [wp(rig.ankles[0]), wp(rig.ankles[1])];
      const hipsW = [wp(rig.hips[0]), wp(rig.hips[1])];
      // pair each hand/foot to its NEAREST target (don't assume index↔side).
      const handErr = hands.map((h) => Math.min(dist(h, grip[0]), dist(h, grip[1])));
      const footErr = feet.map((f) => Math.min(dist(f, peg[0]), dist(f, peg[1])));
      console.error('[ik] hands=' + JSON.stringify(hands) + ' grips=' + JSON.stringify(grip) + ' handErr=' + JSON.stringify(handErr));
      console.error('[ik] feet=' + JSON.stringify(feet) + ' pegs=' + JSON.stringify(peg) + ' footErr=' + JSON.stringify(footErr));
      console.error('[ik] hipsW=' + JSON.stringify(hipsW) + ' bikeY=' + p.y.toFixed(2));
      ctx.flags.paused = true; // freeze with the GAME camera in place
      return {
        yaw: +s.yaw.toFixed(2),
        rigFaceXZ: [+face.x.toFixed(2), +face.z.toFixed(2)],
        bikeFwdXZ: [+bfx.toFixed(2), +bfz.toFixed(2)],
        faceDotBikeFwd: +(face.x * bfx + face.z * bfz).toFixed(2),
        camDotBikeFwd: +(camToBikeX * bfx + camToBikeZ * bfz).toFixed(2),
        camPos: [+cam.position.x.toFixed(1), +cam.position.y.toFixed(1), +cam.position.z.toFixed(1)],
      };
    });
    console.log('[bike-truth] GAME-CAM ' + JSON.stringify(meas));
    await page.waitForTimeout(150);
    await page.screenshot({ path: join(OUT, 'scen-bike-gamecam.png'), fullPage: false });
    console.log('[rig-shot] saved scen-bike-gamecam.png (the REAL user view)');
    // (1b) POSE SWEEP — search the joint-angle space for the pose that lands the
    // wrists on the grips + the ankles on the pegs. Pure matrix math (paused),
    // so a coarse+fine grid runs in one boot. Logs the winning angles to bake
    // into playerRig.ts. Legs are independent of the torso lean; arms depend on
    // it (lean moves the shoulders), so arms sweep lean too.
    const best = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const s = ctx.speeder; const rig = ctx.player.rig;
      const V = ctx.three.camera.position.constructor;
      const p = s.body.translation();
      ctx.flags.paused = true;
      const grip = [[p.x - 0.34, p.y + 0.42, p.z], [p.x + 0.34, p.y + 0.42, p.z]];
      // Target the ANKLE node ~0.1m ABOVE the peg (the sole sits below the ankle).
      const peg = [[p.x - 0.43, p.y + 0.02, p.z + 0.15], [p.x + 0.43, p.y + 0.02, p.z + 0.15]];
      const wp = (n) => { const v = n.getWorldPosition(new V()); return [v.x, v.y, v.z]; };
      const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
      const near = (pt, ts) => Math.min(dist(pt, ts[0]), dist(pt, ts[1]));
      const setLegs = (hipX, hipZ, kneeX) => { for (let i = 0; i < 2; i++) { const sd = i === 1 ? 1 : -1; rig.hips[i].rotation.set(hipX, 0, sd * hipZ); rig.knees[i].rotation.x = kneeX; } rig.group.updateMatrixWorld(true); };
      const PIVOT_Y = 0.92; // mirror playerRig: lean pivots at the waist (no torso slide)
      const setArms = (lean, shX, shZ, elbX) => { rig.spineBend.rotation.set(lean, 0, 0); rig.spineBend.position.set(0, PIVOT_Y * (1 - Math.cos(lean)), -PIVOT_Y * Math.sin(lean)); for (let i = 0; i < 2; i++) { const sd = i === 1 ? 1 : -1; rig.shoulders[i].rotation.set(shX, 0, sd * shZ); rig.elbows[i].rotation.x = elbX; } rig.group.updateMatrixWorld(true); };
      const legErr = () => (near(wp(rig.ankles[0]), peg) + near(wp(rig.ankles[1]), peg)) / 2;
      const armErr = () => (near(wp(rig.wrists[0]), grip) + near(wp(rig.wrists[1]), grip)) / 2;
      // ── Legs: coarse grid then refine around the winner.
      const sweepLegs = (hipXs, hipZs, kneeXs) => {
        let b = { e: 1e9 };
        for (const hipX of hipXs) for (const hipZ of hipZs) for (const kneeX of kneeXs) {
          setLegs(hipX, hipZ, kneeX); const e = legErr();
          if (e < b.e) b = { e, hipX, hipZ, kneeX };
        }
        return b;
      };
      // hipX constrained ≥ -0.1: forbid strong backward thigh pitch (reads as
      // "legs facing backwards"); prefer down/forward + abduction splay.
      let L = sweepLegs([-0.1, 0.05, 0.2, 0.35, 0.5, 0.65], [0.2, 0.35, 0.5, 0.65, 0.8, 0.95], [0.0, 0.15, 0.3, 0.45, 0.6, 0.75]);
      L = sweepLegs(
        [Math.max(-0.1, L.hipX - 0.1), L.hipX - 0.03, L.hipX + 0.03, L.hipX + 0.1],
        [L.hipZ - 0.08, L.hipZ - 0.03, L.hipZ + 0.03, L.hipZ + 0.08],
        [L.kneeX - 0.1, L.kneeX - 0.03, L.kneeX + 0.03, L.kneeX + 0.1],
      );
      // ── Arms: sweep lean + shoulder pitch + elbow (shZ fixed; lateral was good).
      const sweepArms = (leans, shXs, elbXs) => {
        let b = { e: 1e9 };
        for (const lean of leans) for (const shX of shXs) for (const elbX of elbXs) {
          setArms(lean, shX, 0.12, elbX); const e = armErr();
          if (e < b.e) b = { e, lean, shX, elbX };
        }
        return b;
      };
      // Free sweep: deep lean (waist-pivot, no torso slide) + full shoulder range
      // (a deep lean wants the arm to hang slightly back-of-torso = vertical in
      // world). Find the genuine best reach for a CONNECTED torso.
      let A = sweepArms([0.3, 0.5, 0.7, 0.9, 1.1, 1.3], [-0.5, -0.25, 0.0, 0.25, 0.5], [0.0, 0.2, 0.4, 0.6]);
      A = sweepArms(
        [A.lean - 0.1, A.lean - 0.03, A.lean + 0.03, A.lean + 0.1],
        [A.shX - 0.12, A.shX - 0.04, A.shX + 0.04, A.shX + 0.12],
        [Math.max(0, A.elbX - 0.1), A.elbX - 0.03, A.elbX + 0.03, A.elbX + 0.1],
      );
      // Apply the combined winner so the screenshots reflect it.
      setLegs(L.hipX, L.hipZ, L.kneeX);
      setArms(A.lean, A.shX, 0.12, A.elbX);
      rig.group.updateMatrixWorld(true);
      // Post-sweep per-axis residuals (which axis is still off).
      const axErr = (pt, ts) => { const t = dist(pt, ts[0]) < dist(pt, ts[1]) ? ts[0] : ts[1]; return [+(pt[0] - t[0]).toFixed(2), +(pt[1] - t[1]).toFixed(2), +(pt[2] - t[2]).toFixed(2)]; };
      console.error('[ik2] handAx=' + JSON.stringify([axErr(wp(rig.wrists[0]), grip), axErr(wp(rig.wrists[1]), grip)]));
      console.error('[ik2] footAx=' + JSON.stringify([axErr(wp(rig.ankles[0]), peg), axErr(wp(rig.ankles[1]), peg)]) + ' (x=lateral y=height z=fwd/back)');
      const r3 = (x) => +x.toFixed(3);
      return {
        legs: { hipX: r3(L.hipX), hipZ: r3(L.hipZ), kneeX: r3(L.kneeX), errM: r3(L.e) },
        arms: { lean: r3(A.lean), shX: r3(A.shX), shZ: 0.12, elbX: r3(A.elbX), errM: r3(A.e) },
      };
    });
    console.log('[bike-truth] SWEEP-BEST ' + JSON.stringify(best));
    await page.waitForTimeout(120);
    await page.screenshot({ path: join(OUT, 'scen-bike-gamecam-opt.png'), fullPage: false });
    console.log('[rig-shot] saved scen-bike-gamecam-opt.png (swept pose, game cam)');
    // (2) Five fixed WORLD angles around the (yaw=0) bike. With yaw=0: nose=-Z,
    // tail=+Z, so "front" cam sits on -Z looking +Z (sees nose + rider front).
    const D = 3.2, UP = 1.1;
    const angles = [
      { tag: 'front', off: [0, UP, -D] },  // -Z side: sees the NOSE + rider's front (face if facing nose)
      { tag: 'tail',  off: [0, UP, D] },   // +Z side: sees engine + rider's BACK (if facing nose)
      { tag: 'left',  off: [-D, UP, 0] },
      { tag: 'right', off: [D, UP, 0] },
      { tag: '3q',    off: [D * 0.8, D * 0.7, D * 0.8] },
    ];
    for (const a of angles) {
      await page.evaluate(({ off }) => {
        const ctx = window.__game.ctx;
        const s = ctx.speeder; const p = s.body.translation();
        const cam = ctx.three.camera;
        ctx.flags.paused = true;
        cam.position.set(p.x + off[0], p.y + off[1], p.z + off[2]);
        cam.lookAt(p.x, p.y + 0.2, p.z);
        cam.updateMatrixWorld(true);
      }, a);
      await page.waitForTimeout(200);
      await page.screenshot({ path: join(OUT, `scen-bike-${a.tag}.png`), fullPage: false });
      console.log(`[bike-truth] world angle ${a.tag} → scen-bike-${a.tag}.png`);
    }
  },

  // Depthprobe (ACX): log the runtime material/render flags of the held 3P item
  // + the footprint decals, to diagnose why footsteps show through held items.
  'depthprobe': async (page) => {
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.flags.thirdPerson = true;
      const inv = ctx.inventory;
      inv.slots[0].item = 'scrap_gun'; inv.slots[0].count = 1; inv.slots[0].meta = undefined;
      inv.selectedIdx = 0;
    });
    await page.waitForTimeout(500);
    const probe = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const out = { item: [], decals: [], itemRenderOrderGroup: null };
      const rig = ctx.player.rig;
      rig.rightHandAttach.traverse((o) => {
        if (o.isMesh && o.material) {
          const m = o.material;
          out.item.push({
            name: o.name || o.geometry?.type || '?',
            transparent: m.transparent, depthTest: m.depthTest, depthWrite: m.depthWrite,
            renderOrder: o.renderOrder, matType: m.type, visible: o.visible,
          });
        }
      });
      // attach group renderOrder + visibility chain
      out.attachVisible = rig.rightHandAttach.visible;
      out.attachRenderOrder = rig.rightHandAttach.renderOrder;
      // Walk scene for footprint InstancedMeshes (player decals).
      ctx.three.scene.traverse((o) => {
        if (o.isInstancedMesh && o.material) {
          const m = o.material;
          out.decals.push({
            renderOrder: o.renderOrder, transparent: m.transparent,
            depthTest: m.depthTest, depthWrite: m.depthWrite,
            polygonOffset: m.polygonOffset, count: o.count,
          });
        }
      });
      out.rendererSortObjects = ctx.three.renderer.sortObjects;
      return out;
    });
    console.error('[depthprobe] ' + JSON.stringify(probe, null, 0));
  },

  // Held-item (ACW D9/D10): equip an item (--item=<id>), let updateViewModel
  // swap it into the rig's right hand in 3P, then PAUSE + free-camera close on
  // the hand so the makeViewModel mesh + its handAttachTransform can be judged.
  // Used to confirm item models render in-hand + to iterate the 3P grip pose.
  'held-item': async (page) => {
    const item = argv.item || 'machete';
    await page.evaluate((item) => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0;
      window.__game.setTime(0.5);
      ctx.three.renderer.toneMappingExposure = 1.1;
      ctx.three.renderer.setSize(900, 900, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
      ctx.flags.thirdPerson = true;
      const inv = ctx.inventory;
      inv.slots[0].item = item; inv.slots[0].count = 1; inv.slots[0].meta = undefined;
      inv.selectedIdx = 0;
    }, item);
    await page.waitForTimeout(450); // let updateViewModel swap the mesh into the hand
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const rig = ctx.player.rig;
      ctx.flags.paused = true;
      // Pose the right arm OUT in front so the held item clears the torso +
      // backpack (a relaxed hanging arm tucks the item against the body where
      // it can't be judged). Forward-and-up shoulder + slight elbow bend.
      rig.shoulders[1].rotation.set(-1.15, 0, 0.18);
      rig.elbows[1].rotation.x = 0.35;
      rig.wrists[1].rotation.x = -0.05;
      rig.group.updateMatrixWorld(true);
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      const hand = rig.rightHandAttach.getWorldPosition(new V());
      const fz = rig.headGroup.getWorldDirection(new V()); fz.y = 0; fz.normalize();
      const side = new V(-fz.z, 0, fz.x);
      // Frame from the hand's right side (perpendicular to the body facing), a
      // touch above, ~0.5m out — the extended arm keeps the body out of frame.
      cam.position.set(
        hand.x + side.x * 0.50 + fz.x * 0.10,
        hand.y + 0.10,
        hand.z + side.z * 0.50 + fz.z * 0.10,
      );
      cam.lookAt(hand.x, hand.y - 0.02, hand.z);
      cam.updateMatrixWorld(true);
    });
    await page.waitForTimeout(250);
    const path = join(OUT, `scen-held-${item}.png`);
    await page.screenshot({ path, fullPage: false });
    console.log(`[held-item] ${item} → ${path}`);
  },

  // Branches (ACAE): frame a world branch pickup near its dead tree — verifies
  // the dark wood-grain branch + that the ground branches match the trees.
  'branches': async (page) => {
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.42);
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.three.renderer.setSize(900, 700, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 700; cam.updateProjectionMatrix(); }
      const branches = (ctx.pickups.list || []).filter((p) => p.itemId === 'branch');
      const b = branches[0];
      if (!b) return { found: false };
      const p = b.pos;
      ctx.flags.paused = true;                  // freeze so our camera survives
      cam.position.set(p.x + 0.9, p.y + 0.7, p.z + 0.9);
      cam.lookAt(p.x, p.y + 0.1, p.z);
      cam.updateMatrixWorld(true);
      return { found: true, count: branches.length, pos: [p.x.toFixed(1), p.y.toFixed(1), p.z.toFixed(1)] };
    });
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, 'scen-branches.png'), fullPage: false });
    console.log(`[branches] ${JSON.stringify(r)}`);
  },

  // Tree (ACAF f/u): frame a whole dead tree from a low 3/4 angle to judge the
  // trunk taper + the buildBranchMesh limbs (connected, no floaters). --time set
  // for a legible mid-morning read; --tilt/--dist to vary the camera.
  // Wreck-form (ACAJ T1): isolate a shared wreck-form toolkit primitive against
  // the sky for screenshot iteration. --form=lathe|formers|breach|mound, --angle=.
  'wreck-form': async (page) => {
    const form = argv.form || 'lathe';
    const angle = argv.angle || 'side';
    const r = await page.evaluate((a) => {
      window.__game.setTime(0.5);
      window.__game.ctx.weather.intensity = 0;
      return window.__game.wreckFormStudio(a.form, a.angle);
    }, { form, angle });
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, `scen-wreck-form-${form}.png`), fullPage: false });
    console.log(`[wreck-form] ${JSON.stringify(r)}`);
  },

  // Megawreck (ACAJ T2): locate the mega-wreck POI + orbit it for the silhouette
  // rebuild. --angle=3q|side|front|rear|interior ; reports panel/shelter presence.
  'megawreck': async (page) => {
    const angle = argv.angle || '3q';
    const r = await page.evaluate((ang) => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.15;
      window.__game.setTime(0.34);                 // true midday (0.5 was 18:00) for max detail read
      ctx.three.renderer.toneMappingExposure = 1.2;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      let mw = null;
      ctx.three.scene.traverse((o) => { if (!mw && o.name === 'megaWreck') mw = o; });
      if (!mw) return { found: false };
      const V = ctx.three.camera.position.constructor;
      // bbox via traversal (Box3 not guaranteed on window)
      let minX = 1e9, minY = 1e9, minZ = 1e9, maxX = -1e9, maxY = -1e9, maxZ = -1e9;
      mw.updateMatrixWorld(true);
      mw.traverse((o) => {
        if (!o.isMesh || !o.geometry) return;
        o.geometry.computeBoundingBox();
        const bb = o.geometry.boundingBox;
        for (const cx of [bb.min.x, bb.max.x]) for (const cy of [bb.min.y, bb.max.y]) for (const cz of [bb.min.z, bb.max.z]) {
          const p = new V(cx, cy, cz); o.localToWorld(p);
          minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
          minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
          minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
        }
      });
      const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2, cz = (minZ + maxZ) / 2;
      const span = Math.max(maxX - minX, maxZ - minZ);
      const cam = ctx.three.camera;
      ctx.flags.paused = true;
      const h = maxY - minY;
      // Aim LOW at the visual mass (not the bbox centre, which sits high because of
      // the island/mast). Frame the full LENGTH; avoid end-on shots that foreshorten
      // the 136m dagger into a "squat blob".
      const D = Math.max(span, maxZ - minZ) * 1.02;
      const aimY = minY + h * 0.3, up = minY + h * 0.5;
      const aim = (camPos) => { cam.position.copy(camPos); cam.lookAt(cx, aimY, cz); };
      if (ang.startsWith('int')) {
        // Inside the canted wreck, in the SHELL frame (the interior is built there).
        // Place via the shell child's world matrix so the camera rides the list onto
        // the tilted deck. Shell-local interior viewpoints (deck ≈ y 1; eye ≈ y 2.6):
        const shellObj = mw.getObjectByName('shell') || mw;
        shellObj.updateMatrixWorld(true);
        const M = shellObj.matrixWorld;
        const sl = (x, y, z) => new V(x, y, z).applyMatrix4(M);
        const VIEWS = {
          'interior': [[1.4, 2.6, -28], [1, 1.5, 6]],       // bow compartment → fracture
          'int-bow':  [[1.5, 3.0, -42], [1, 1.5, -10]],     // bow entry looking aft
          'int-frac': [[3, 3.5, -22], [0, 4.5, 4]],         // from the bow toward the lit fracture opening
          'int-aft':  [[2.0, 3.2, 22], [1.5, 2.0, 48]],     // engineering looking aft
          'int-bridge': [[3.0, 3.0, 60], [3.0, 2.5, 73]],   // up to the bridge
        };
        const [eye, look] = VIEWS[ang] || VIEWS['interior'];
        cam.position.copy(sl(eye[0], eye[1], eye[2]));
        cam.lookAt(sl(look[0], look[1], look[2]));
      }
      else if (ang === 'side') aim(new V(cx + D, up, cz));                          // broadside (the money shot)
      else if (ang === 'hero') aim(new V(cx + D * 0.8, minY + h * 0.16, cz - D * 0.5)); // low bow-3/4 (length + list)
      else if (ang === '3q')   aim(new V(cx + D * 0.62, up, cz + D * 0.52));        // aft-3/4 (engines + island)
      else if (ang === 'rear') aim(new V(cx + D * 0.5, up + h * 0.1, cz + D * 0.85));// aft-3/4 (not pure end-on)
      else if (ang === 'front') aim(new V(cx - D * 0.5, up, cz - D * 0.85));         // bow-3/4 (not pure end-on)
      else aim(new V(cx + D * 0.6, up, cz - D * 0.55));
      cam.updateMatrixWorld(true);
      ctx.three.renderer.toneMappingExposure = 1.5;
      // Find the THREE light constructors off existing scene lights.
      let DirCtor = null, HemiCtor = null;
      ctx.three.scene.traverse((o) => { if (o.isDirectionalLight && !DirCtor) DirCtor = o.constructor; if (o.isHemisphereLight && !HemiCtor) HemiCtor = o.constructor; });
      // Front-high KEY light from just above + beside the camera (3/4 front), so
      // the face the camera sees is LIT — not a backlit silhouette.
      if (DirCtor) {
        const key = new DirCtor(); key.intensity = 2.0; key.color.set(0xfff2e0);
        const toC = new V(cx - cam.position.x, 0, cz - cam.position.z); // camera→wreck (XZ)
        key.position.set(cam.position.x + toC.x * 0.2 + span * 0.25, cam.position.y + h * 0.6, cam.position.z + toC.z * 0.2);
        key.target.position.set(cx, cy, cz); ctx.three.scene.add(key.target); ctx.three.scene.add(key);
      }
      // Hemisphere FILL so shadow faces aren't pure black.
      if (HemiCtor) { const fill = new HemiCtor(0xbfccdd, 0x6b5840, 0.7); ctx.three.scene.add(fill); }
      const panels = (ctx.salvageables?.list || []).filter((s) => s.kind === 'massive').length;
      return { found: true, span: +span.toFixed(0), height: +(maxY - minY).toFixed(0), panels };
    }, angle);
    await page.waitForTimeout(350);
    await page.screenshot({ path: join(OUT, `scen-megawreck-${angle}.png`), fullPage: false });
    console.log(`[megawreck] ${JSON.stringify(r)}`);
  },

  // Generic FLAGSHIP framer — finds a named flagship POI (megaShip / satelliteDish /
  // crashedHull / megaWreck) + frames its exterior + reports mesh count. Used to verify
  // the T6 static-merge is render-identical (before/after) + measure the mesh drop.
  // `--name=<group.name> --angle=<3q|side|front>`.
  'flagship': async (page) => {
    const name = argv.name || 'megaShip';
    const angle = argv.angle || '3q';
    const r = await page.evaluate(({ nm, ang }) => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.15;
      window.__game.setTime(0.34);
      ctx.three.renderer.toneMappingExposure = 1.5;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      let mw = null;
      ctx.three.scene.traverse((o) => { if (!mw && o.name === nm) mw = o; });
      if (!mw) return { found: false, name: nm };
      const V = ctx.three.camera.position.constructor;
      let minX = 1e9, minY = 1e9, minZ = 1e9, maxX = -1e9, maxY = -1e9, maxZ = -1e9;
      mw.updateMatrixWorld(true);
      let meshes = 0;
      mw.traverse((o) => {
        if (!o.isMesh || !o.geometry) return;
        meshes++;
        o.geometry.computeBoundingBox(); const bb = o.geometry.boundingBox;
        for (const cx of [bb.min.x, bb.max.x]) for (const cy of [bb.min.y, bb.max.y]) for (const cz of [bb.min.z, bb.max.z]) {
          const p = new V(cx, cy, cz); o.localToWorld(p);
          minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
          minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
          minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
        }
      });
      const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2, cz = (minZ + maxZ) / 2;
      const span = Math.max(maxX - minX, maxZ - minZ), h = maxY - minY;
      const cam = ctx.three.camera; ctx.flags.paused = true;
      const D = span * 1.2, up = minY + h * 0.55;
      const aim = (p) => { cam.position.copy(p); cam.lookAt(cx, minY + h * 0.4, cz); };
      if (ang === 'side') aim(new V(cx + D, up, cz));
      else if (ang === 'front') aim(new V(cx - D * 0.5, up, cz - D * 0.85));
      else aim(new V(cx + D * 0.62, up, cz + D * 0.52));   // 3q
      cam.updateMatrixWorld(true);
      let DirCtor = null, HemiCtor = null;
      ctx.three.scene.traverse((o) => { if (o.isDirectionalLight && !DirCtor) DirCtor = o.constructor; if (o.isHemisphereLight && !HemiCtor) HemiCtor = o.constructor; });
      if (DirCtor) { const key = new DirCtor(); key.intensity = 2.0; key.color.set(0xfff2e0); const toC = new V(cx - cam.position.x, 0, cz - cam.position.z); key.position.set(cam.position.x + toC.x * 0.2 + span * 0.25, cam.position.y + h * 0.6, cam.position.z + toC.z * 0.2); key.target.position.set(cx, cy, cz); ctx.three.scene.add(key.target); ctx.three.scene.add(key); }
      if (HemiCtor) { const fill = new HemiCtor(0xbfccdd, 0x6b5840, 0.7); ctx.three.scene.add(fill); }
      return { found: true, name: nm, span: +span.toFixed(0), height: +h.toFixed(0), meshes };
    }, { nm: name, ang: angle });
    await page.waitForTimeout(350);
    await page.screenshot({ path: join(OUT, `scen-flagship-${name}-${angle}.png`), fullPage: false });
    console.log(`[flagship] ${JSON.stringify(r)}`);
  },

  // ACBB Tier 3 — COLLIDER-AUDIT (no screenshot). For each POI archetype × a seed sweep,
  // assemble it pre-merge + assert every collidable-scale mesh is covered by a declared
  // collider (the audit lives in poiAssembler; __game.auditPOIColliders is pure → works at
  // title, no enterGame). Prints one `COLLIDER-AUDIT archetype=… seed=… pass=p/t fails=f`
  // line per (archetype,seed) for scripts/verify-colliders.mjs (mirrors the panels gate).
  // `--archetype=a,b` (default all 5) `--seeds=1,42,…` (default 1,42,1337,2024).
  'collider-audit': async (page) => {
    // seed 2 is included so the derelict WIDE-BODY form (parallel outrigger pods + cross-strut)
    // is exercised — seeds 1/42/1337/2024 all roll the linear/stacked forms (ACBB Tier 4).
    const seeds = (argv.seeds !== undefined ? String(argv.seeds) : '1,2,42,1337,2024')
      .split(',').map((s) => Number(s.trim())).filter((n) => !Number.isNaN(n));
    const archs = (argv.archetype ? String(argv.archetype) : 'satellite,wrecked_tank,debris_field,hollow_husk,derelict,well,debris_trail,enterable_wreck,relay_mast,buried_pipeline,cargo_crawler,refinery_stack,hab_dome,transit_car')
      .split(',').map((s) => s.trim()).filter(Boolean);
    await page.waitForFunction(() => !!(window.__game && window.__game.auditPOIColliders), { timeout: 20000 });
    const rows = await page.evaluate(({ archs, seeds }) => {
      const out = [];
      for (const a of archs) for (const s of seeds) {
        const r = window.__game.auditPOIColliders(a, s);
        out.push({ archetype: a, seed: s, total: r.total, pass: r.pass, fails: r.fails, details: r.details });
      }
      return out;
    }, { archs, seeds });
    let totalFails = 0;
    for (const r of rows) {
      totalFails += r.fails;
      console.log(`COLLIDER-AUDIT archetype=${r.archetype} seed=${r.seed} pass=${r.pass}/${r.total} fails=${r.fails}${r.fails ? ' :: ' + r.details.join(' | ') : ''}`);
    }
    console.log(`[collider-audit] ${rows.length} audits across ${archs.length} archetypes — ${totalFails} total fails`);
  },

  // ACAO — PROCGEN-WRECK framer (the BLOCKER from ACAN). Spawns a chosen procgen
  // wreck CLASS at a fixed clear anchor with a deterministic seed (via
  // __game.spawnProcgenWreckRig), names it 'procgenWreckRig', then frames it +
  // reports mesh count (same find/frame/mesh-count logic as `flagship`). THIS is
  // what makes procgen visual work (breaches / greebles / impact-asymmetry)
  // screenshot-verifiable — procgen wrecks are otherwise unnamed + random-spot.
  // `--class=<corvette|gunship|freighter|science_vessel|bulk_hauler|orbital_pod_cluster>`
  // `--angle=<3q|side|front> --seed=<n>`.
  'procgen-wreck': async (page) => {
    const cls = argv.class || 'corvette';
    const angle = argv.angle || '3q';
    // `--seed=N` (single) or `--seeds=1,2,3` (sweep — one screenshot per seed in
    // ONE dev-server boot, the fast path for screenshot-iterating procgen visuals).
    const seeds = (argv.seeds !== undefined ? String(argv.seeds)
      : argv.seed !== undefined ? String(argv.seed) : '1337')
      .split(',').map((s) => Number(s.trim())).filter((n) => !Number.isNaN(n));
    const zoom = argv.zoom !== undefined ? Number(argv.zoom) : 1;   // <1 = tighter (detail inspection)
    const fa = argv.forceanchor !== undefined;   // ACAZ T2A — pin the scale-anchor hatch to the +Z camera flank
    const variant = argv.variant !== undefined ? Number(argv.variant) : -1;   // ACAZ T2B — force one hull variant
    const archetype = argv.archetype || '';      // ACBA — POI archetype (satellite/tank_cluster/…); '' = ship
    const pinyaw = argv.pinyaw !== undefined;     // C41 — length-frame pin (spine broadside) for the visual gate
    for (const seed of seeds) {
    const r = await page.evaluate(({ cls, ang, seed, zoom, fa, variant, archetype, pinyaw }) => {
      const ctx = window.__game.ctx;
      window.__FORCE_ANCHOR_NEAR = fa;   // inspection only — forces the hatch camera-facing
      if (variant >= 0) window.__FORCE_HULL_VARIANT = variant; else delete window.__FORCE_HULL_VARIANT;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.15;
      window.__game.setTime(0.34);
      ctx.three.renderer.toneMappingExposure = 1.5;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      const spawn = window.__game.spawnProcgenWreckRig(cls, seed, archetype || undefined, pinyaw);
      let mw = null;
      ctx.three.scene.traverse((o) => { if (!mw && o.name === 'procgenWreckRig') mw = o; });
      if (!mw) return { found: false, cls, seed, spawn };
      const V = ctx.three.camera.position.constructor;
      let minX = 1e9, minY = 1e9, minZ = 1e9, maxX = -1e9, maxY = -1e9, maxZ = -1e9;
      mw.updateMatrixWorld(true);
      let meshes = 0;
      mw.traverse((o) => {
        if (!o.isMesh || !o.geometry) return;
        meshes++;
        o.geometry.computeBoundingBox(); const bb = o.geometry.boundingBox;
        for (const cx of [bb.min.x, bb.max.x]) for (const cy of [bb.min.y, bb.max.y]) for (const cz of [bb.min.z, bb.max.z]) {
          const p = new V(cx, cy, cz); o.localToWorld(p);
          minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
          minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
          minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
        }
      });
      const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2, cz = (minZ + maxZ) / 2;
      const span = Math.max(maxX - minX, maxZ - minZ), h = maxY - minY;
      const cam = ctx.three.camera; ctx.flags.paused = true;
      // Half-buried: frame the EXPOSED hull (terrain line → top), NOT the full
      // bbox — its bottom is under the sand, which would drag the eye down and
      // let the dune cut across mid-hull. spawn.pos[1] is the terrain Y.
      const groundY = (spawn && spawn.pos) ? spawn.pos[1] : minY;
      const expMid = (groundY + maxY) * 0.5;
      const expH = Math.max(0.6, maxY - groundY);
      const D = Math.max(span, expH * 2.2) * 1.35 * (zoom || 1);
      const eyeY = expMid + expH * 0.18;        // slightly above exposed-mid → gentle down-angle
      // Procgen wrecks are X-LONG (flanks ±Z; breaches + salvage panels live on
      // the +Z flank), so unlike the Z-long hero: 'side' is a +Z broadside (the
      // money shot for breach/greeble inspection), 'front' is nose-on down -X,
      // '3q' favors the +Z detail flank.
      const aim = (p) => { cam.position.copy(p); cam.lookAt(cx, expMid, cz); };
      if (ang === 'side') aim(new V(cx, eyeY, cz + D));
      else if (ang === 'front') aim(new V(cx - D, eyeY, cz + D * 0.12));
      else if (ang === 'tear') aim(new V(cx + D * 0.95, eyeY, cz + D * 0.22));   // look INTO the torn +X end (ribbing/flaps)
      else aim(new V(cx + D * 0.55, eyeY, cz + D * 0.62));   // 3q — length + +Z flank
      // ACAZ T2A — when --forceanchor, aim a CLOSE 3/4 shot straight at a hatch (its
      // world pos was recorded pre-merge on the wreck group). `--zoom` sets the
      // distance (×9): 0.3→~2.7m, 0.22→~2.0m. The hatch is pinned to the +Z flank.
      if (fa) {
        let ap = null;
        mw.traverse((o) => { if (!ap && o.userData && o.userData.anchorLocalPositions) ap = o.userData.anchorLocalPositions; });
        if (ap && ap.length >= 3) {
          const lp = new V(ap[0], ap[1], ap[2]);
          mw.localToWorld(lp);                 // transform by the rig's FINAL orientation
          const ax = lp.x, ay = lp.y, az = lp.z;
          const dist = (zoom || 1) * 9;
          cam.position.set(ax + dist * 0.30, ay + dist * 0.16, az + dist);
          cam.lookAt(ax, ay, az);
        }
      }
      cam.updateMatrixWorld(true);
      let DirCtor = null, HemiCtor = null;
      ctx.three.scene.traverse((o) => { if (o.isDirectionalLight && !DirCtor) DirCtor = o.constructor; if (o.isHemisphereLight && !HemiCtor) HemiCtor = o.constructor; });
      // Key + hemi fill — named so the seed sweep reuses them (reposition the key
      // each seed so framing-relative lighting stays correct).
      let key = ctx.three.scene.getObjectByName('__procgenKey');
      if (!key && DirCtor) { key = new DirCtor(); key.name = '__procgenKey'; key.intensity = 2.0; key.color.set(0xfff2e0); ctx.three.scene.add(key.target); ctx.three.scene.add(key); }
      if (key) { const toC = new V(cx - cam.position.x, 0, cz - cam.position.z); key.position.set(cam.position.x + toC.x * 0.2 + span * 0.25, cam.position.y + h * 0.6, cam.position.z + toC.z * 0.2); key.target.position.set(cx, cy, cz); key.target.updateMatrixWorld(true); }
      if (!ctx.three.scene.getObjectByName('__procgenFill') && HemiCtor) { const fill = new HemiCtor(0xbfccdd, 0x6b5840, 0.7); fill.name = '__procgenFill'; ctx.three.scene.add(fill); }
      return { found: true, cls: archetype || cls, seed, span: +span.toFixed(1), height: +h.toFixed(1), meshes };
    }, { cls, ang: angle, seed, zoom, fa, variant, archetype, pinyaw });
    await page.waitForTimeout(320);
    const tag = archetype ? archetype : cls;
    await page.screenshot({ path: join(OUT, `scen-procgen-${tag}-${angle}-s${seed}${variant >= 0 ? `-v${variant}` : ''}.png`), fullPage: false });
    console.log(`[procgen-wreck] ${JSON.stringify(r)}`);
    }
  },

  // ACAQ — WRECK-YARD biome framer (Cycle 8). Finds the seed-derived wreck-yard
  // anchor (ctx.biomes.wreckYardAnchor) + frames the region. `--angle=aerial|approach|ground`.
  // The framer for the whole wreck-yard build (biome → graveyard → pit).
  'wreck-yard': async (page) => {
    const angle = argv.angle || 'aerial';
    const r = await page.evaluate(({ ang, doBreakdown, openAmt }) => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.15;
      window.__game.setTime(0.36);
      ctx.three.renderer.toneMappingExposure = 1.4;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      const anchor = ctx.biomes.wreckYardAnchor;
      const rad = ctx.biomes.wreckYardRadius;
      const biomeHere = ctx.biomes.biomeAt(anchor.x, anchor.z);
      const cam = ctx.three.camera; ctx.flags.paused = true;
      const groundY = ctx.terrain.heightAt(anchor.x, anchor.z);
      if (ang === 'aerial') {
        cam.position.set(anchor.x, groundY + rad * 1.5, anchor.z + rad * 0.25);
        cam.lookAt(anchor.x, groundY, anchor.z);
      } else if (ang === 'approach') {
        cam.position.set(anchor.x + rad * 1.7, groundY + 26, anchor.z + rad * 1.7);
        cam.lookAt(anchor.x, groundY + 5, anchor.z);
      } else if (ang === 'pit' || ang === 'pit-eye' || ang === 'maw') {
        // The pit is now a RECESSED funnel crater (ACAR2) at its own dune anchor
        // (ctx.sarlaccPit.basePos = the carved crater FLOOR). Force the maw open for
        // the shot (no mesh-sink now). The rim sits ~CRATER_DEPTH above the floor, so
        // sample the undisturbed dune just outside the clearing for the camera height.
        const pit = ctx.sarlaccPit;
        const pr = (pit && pit.rOuter) || 10;
        const pb = pit ? pit.basePos : { x: anchor.x, y: groundY, z: anchor.z };
        if (pit) {
          pit.openAmt = openAmt;
          // ACBD — replicate updateSarlaccPit's buried-rise pose (the FSM doesn't run
          // while the shot is paused) so the still shows the real sink for this openAmt.
          const sink = 11 * (1 - openAmt);   // = SARLACC_PIT_BURY_DEPTH
          pit.parts.teeth.position.y = -sink;
          pit.parts.innerTeeth.position.y = -sink;
          for (const t of pit.parts.tendrils) t.position.y = -sink;
          const bk = pit.parts.beak;
          bk.position.y = (bk.userData.baseY || 0) + openAmt * pr * 0.16 - sink;
        }
        // Lower, raking sun + tamer exposure so the funnel's near-wall shadow reads
        // (overhead noon light flattens the depression). The crater depth shows as a
        // light/shadow gradient across the bowl.
        window.__game.setTime(0.4);
        ctx.three.renderer.toneMappingExposure = 1.1;
        const rimY = ctx.terrain.heightAt(pb.x + 34, pb.z);
        if (ang === 'maw') {
          // Tight, low 3/4 close-up of the MAW itself (beak/teeth/tentacles/throat) —
          // for iterating the creature detail. Inside the bowl, near the floor.
          cam.position.set(pb.x + pr * 0.95, pb.y + pr * 0.7, pb.z + pr * 0.95);
          cam.lookAt(pb.x, pb.y + pr * 0.12, pb.z);
        } else if (ang === 'pit-eye') {
          // Peer over the rim lip — the player's approach POV, close enough that the
          // bowl interior + maw read (not foreshortened to a flat disc from far off).
          cam.position.set(pb.x + pr * 1.9, rimY + 3.0, pb.z + pr * 0.5);
          cam.lookAt(pb.x, pb.y + pr * 0.1, pb.z);
        } else {
          // Elevated 3/4 look-down framing the WHOLE crater (rim to rim) so the sand
          // funnel around the maw is visible, not just the maw.
          cam.position.set(pb.x + pr * 2.4, rimY + pr * 2.0, pb.z + pr * 2.4);
          cam.lookAt(pb.x, pb.y + pr * 0.05, pb.z);
        }
      } else { // ground
        cam.position.set(anchor.x - rad * 0.55, groundY + 3.2, anchor.z - rad * 0.55);
        cam.lookAt(anchor.x, groundY + 2.5, anchor.z);
      }
      cam.updateMatrixWorld(true);
      // Count wrecks/objects near the anchor (for Y2+ verification).
      let near = 0;
      for (const o of ctx.three.scene.children) {
        const p = o.position; if (!p) continue;
        const dx = p.x - anchor.x, dz = p.z - anchor.z;
        if (dx * dx + dz * dz < rad * rad) near++;
      }
      // ACAS A4 — count salvageable panels registered within the graveyard (the
      // procgen wrecks + now the big hand-wrecks) to confirm loot registration.
      let nearSalvage = 0;
      const sl = ctx.salvageables && ctx.salvageables.list;
      if (sl) for (const s of sl) {
        const sp = s.pos || (s.group && s.group.position); if (!sp) continue;
        const dx = sp.x - anchor.x, dz = sp.z - anchor.z;
        if (dx * dx + dz * dz < rad * rad) nearSalvage++;
      }
      ctx.three.renderer.render(ctx.three.scene, cam);   // populate renderer.info for this view
      const info = ctx.three.renderer.info;
      // --breakdown perf probe (ACBC / D237) — opt-in yard draw-call attribution.
      // Buckets every VISIBLE mesh by a coarse "kind" (a draw call ≈ one visible
      // mesh = one material) so the dominant draw-call source in the dense yard is
      // measurable headlessly (page.screenshot times out on this scene). Salvage
      // panels are split into EXT_body / EXT_door / EXT_mask / EXT_rim / INTERIOR
      // so the merge-eligible static rim greeble (the ACBC cut target) is visible.
      // `inYard` counts meshes under the wreckYard group; `distinctMats` flags a
      // bucket that can't merge by-material (N meshes, N materials). Kept as a
      // reusable probe; inert without the flag.
      let breakdown = null;
      if (doBreakdown) {
        const yard = ctx.three.scene.getObjectByName('wreckYard');
        const kindOf = (o) => {
          // walk up: find the panel body (accessPanel) or interactType tag.
          let n = o, body = null;
          while (n) {
            if (n.userData?.accessPanel) { body = n; break; }
            if (n.userData?.interactType === 'salvage') { body = n; break; }
            if (n.userData?.interactType) return 'interact:' + n.userData.interactType;
            n = n.parent;
          }
          if (body) {
            // INTERIOR if o is a descendant of body.userData.panelInterior.
            const interior = body.userData.panelInterior;
            if (interior) {
              let q = o;
              while (q) { if (q === interior) return 'salvagePanel:INTERIOR'; q = q.parent; }
            }
            // sub-classify the exterior: BODY (the cavity box = raycast target),
            // DOOR (animated pivot), MASK (stencil), or RIM (static greeble).
            const doorV = body.userData.panelDoor;
            const mask = body.userData.panelMask;
            if (o === body) return 'salvagePanel:EXT_body';
            let q2 = o;
            while (q2) {
              if (q2 === doorV) return 'salvagePanel:EXT_door';
              if (q2 === mask) return 'salvagePanel:EXT_mask';
              q2 = q2.parent;
            }
            return 'salvagePanel:EXT_rim(' + ((o.material && o.material.name) || o.geometry?.type || '?') + ')';
          }
          const m = o.material;
          const mn = (m && m.name) || '';
          const gn = (o.name) || (o.geometry && o.geometry.type) || '';
          if (mn) return 'mat:' + mn;
          return 'geo:' + gn;
        };
        const buckets = {};        // kind -> { meshes, matUUIDs:Set, transparent, inYard }
        const matsAll = new Set();
        let visMeshes = 0;
        ctx.three.scene.traverse((o) => {
          if (!o.isMesh || !o.visible || !o.material) return;
          // skip if any ancestor invisible
          let p = o.parent, vis = true;
          while (p) { if (p.visible === false) { vis = false; break; } p = p.parent; }
          if (!vis) return;
          visMeshes++;
          const mat = Array.isArray(o.material) ? o.material[0] : o.material;
          matsAll.add(mat.uuid);
          const k = kindOf(o);
          let b = buckets[k];
          if (!b) { b = buckets[k] = { meshes: 0, mats: new Set(), transp: 0, inYard: 0 }; }
          b.meshes++; b.mats.add(mat.uuid);
          if (mat.transparent) b.transp++;
          // is it under the yardGroup?
          let q = o, isY = false;
          while (q) { if (q === yard) { isY = true; break; } q = q.parent; }
          if (isY) b.inYard++;
        });
        const ranked = Object.entries(buckets)
          .map(([k, b]) => ({ k, meshes: b.meshes, distinctMats: b.mats.size, transp: b.transp, inYard: b.inYard }))
          .sort((a, b) => b.meshes - a.meshes);
        breakdown = {
          visibleMeshesTotal: visMeshes,
          distinctMaterialsTotal: matsAll.size,
          yardChildren: yard ? yard.children.length : -1,
          top: ranked.slice(0, 22),
        };
      }
      return { anchor: [+anchor.x.toFixed(0), +anchor.z.toFixed(0)], rad, biomeHere, groundY: +groundY.toFixed(1), nearObjects: near, nearSalvage, drawCalls: info.render.calls, tris: info.render.triangles, breakdown };
    }, { ang: angle, doBreakdown: !!argv.breakdown, openAmt: argv.openamt !== undefined ? Number(argv.openamt) : 1 });
    await page.waitForTimeout(350);
    await page.screenshot({ path: join(OUT, `scen-wreckyard-${angle}.png`), fullPage: false });
    console.log(`[wreck-yard] ${JSON.stringify(r)}`);
  },

  // M8 ⑨ (C47) — render the DEEP CAVE descent funnel at its seeded anchor (the cave MOUTH).
  // `--angle=aerial` (3/4 look-down framing the whole funnel) | `approach` (peer over the rim).
  // Low raking sun + tame exposure so the funnel's near-wall shadow + the dark coloring read.
  'cave': async (page) => {
    const angle = argv.angle || 'aerial';
    const r = await page.evaluate(({ ang }) => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.15;
      window.__game.setTime(0.4);                                   // low raking sun
      ctx.three.renderer.toneMappingExposure = 1.1;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      const a = ctx.biomes.caveAnchor;
      const cam = ctx.three.camera; ctx.flags.paused = true;
      const floorY = ctx.terrain.heightAt(a.x, a.z);               // carved funnel floor
      const rimY = ctx.terrain.heightAt(a.x + 30, a.z);            // undisturbed dune just outside the rim
      const R = 22;                                                // ~CAVE_PIT_CLEARING
      if (ang === 'interior' || ang === 'door' || ang === 'inside') {
        // C52 — the rig boots in DEV MODE (companionAcquired=true → the boot reconcile
        // detaches the egg). Re-attach it so the M8 ⑩ egg renders on the dais for the shot.
        const dc = ctx.deepCave;
        if (dc && dc.egg && !dc.egg.group.parent) dc.group.add(dc.egg.group);
        // C49 dark-nav LOOK: emulate updateDeepCave for the shot (the real effect is
        // player-position-driven) — darken ambient/sun + light the REAL cave torch.
        ctx.lights.ambient.intensity *= 0.1;
        ctx.lights.sun.intensity *= 0.06;
        const torch = ctx.deepCave && ctx.deepCave.torch;
        if (ang === 'inside') {
          if (torch) { torch.visible = true; torch.intensity = 2.4; torch.position.set(a.x - 1.5, floorY + 1.6, a.z + 1.0); }
          cam.position.set(a.x - 2.2, floorY + 1.7, a.z + 1.6);
          cam.lookAt(a.x + 3, floorY + 1.4, a.z - 1.2);
        } else {
          if (torch) { torch.visible = true; torch.intensity = 2.4; torch.position.set(a.x - 4.5, floorY + 1.6, a.z); }
          cam.position.set(a.x - 6.5, floorY + 1.7, a.z);
          cam.lookAt(a.x + 1, floorY + 1.5, a.z);
        }
      } else if (ang === 'approach') {
        cam.position.set(a.x + R * 1.7, rimY + 3.0, a.z + R * 0.5);
        cam.lookAt(a.x, floorY + 2.0, a.z);
      } else {
        cam.position.set(a.x + R * 2.2, rimY + R * 1.9, a.z + R * 2.2);
        cam.lookAt(a.x, floorY + 1.0, a.z);
      }
      cam.updateMatrixWorld(true);
      ctx.three.renderer.render(ctx.three.scene, cam);
      // structural sanity: the deepCave interior group + its meshes (1 box mesh : 1 collider).
      let caveMeshes = 0, caveGroup = null;
      ctx.three.scene.traverse((o) => { if (o.name === 'deepCave') caveGroup = o; });
      if (caveGroup) caveGroup.traverse((o) => { if (o.isMesh) caveMeshes++; });
      return { anchor: [+a.x.toFixed(0), +a.z.toFixed(0)], floorY: +floorY.toFixed(1), rimY: +rimY.toFixed(1), depth: +(rimY - floorY).toFixed(1), caveMeshes, caveFound: !!caveGroup };
    }, { ang: angle });
    console.log(`[cave] ${JSON.stringify(r)}`);   // log BEFORE the screenshot so the carve numbers survive a screenshot flake
    await page.waitForTimeout(350);
    try {
      await page.screenshot({ path: join(OUT, `scen-cave-${angle}.png`), fullPage: false, timeout: 60000 });
      console.log(`[cave] saved scen-cave-${angle}.png`);
    } catch (e) {
      console.log(`[cave] screenshot flaked (${e.name}) — numeric result above stands`);
    }
  },

  // ACAS B2 — drop-test: drop capsule/sphere/box pickups + tick; confirm the bodies
  // SETTLE (finite + near terrain), i.e. the per-item collider shapes don't NaN or
  // explode. The settle FEEL (natural lie vs box) still needs an attended walk-test.
  // ── cave-spike (D254, attended 2026-07-19) ─────────────────────────────────
  // THE question every cave architecture branches on: can the KCC capsule EXIST
  // below the real terrain heightfield sheet and interact with it sanely? Runs
  // against the SHIPPING collider (not a synthetic scene). Four tests from
  // docs/research/cave-feasibility.md:
  //   A control: standing on terrain (must be normal).
  //   B rest-below: teleport 30m under the sheet, step 60 frames — ejected up?
  //     fell forever? or stable (gravity-falling is "no floor", also informative)?
  //   C walk-below: while under, drive the KCC laterally 40 frames — does
  //     movement work at all below the sheet?
  //   D punch-up: from 3m under, drive upward INTO the sheet (jump velocity) —
  //     tunnel through to the surface, or blocked from below (one-sided)?
  // Outcome map (digest): B stable + D blocked  → heightfield is two-sided-ish →
  // chunk trimesh swap optional; B stable + D tunnels → one-sided → underground
  // volumes are FREE (option 1/3 viable, portals unneeded); B ejected → hard
  // one-sided ejection → portal-island (option 2).
  'cave-spike': async (page) => {
    const r = await page.evaluate(async () => {
      const g = window.__game; g.enterGame(true);
      const ctx = g.ctx; ctx.flags.paused = false;
      const body = ctx.player.body.body;
      const raf = () => new Promise((res) => requestAnimationFrame(res));
      const P = (x, y, z) => body.setTranslation({ x, y, z }, true);
      const at = () => { const t = body.translation(); return { x: +t.x.toFixed(2), y: +t.y.toFixed(2), z: +t.z.toFixed(2) }; };
      const gy = (x, z) => ctx.terrain.heightAt(x, z);
      const px = 40, pz = 40;                      // flat-ish spot near origin
      const g0 = gy(px, pz);
      // A — control on the surface.
      P(px, g0 + 1.2, pz);
      for (let i = 0; i < 30; i++) await raf();
      const a = at(); const aOk = Math.abs(a.y - (g0 + 0.9)) < 1.5;
      // B — rest 30m below the sheet.
      P(px, g0 - 30, pz);
      const track = [];
      for (let i = 0; i < 60; i++) { await raf(); if (i % 10 === 0) track.push(at().y); }
      const b = at();
      const ejected = b.y > g0 - 2;                 // popped back above/near the surface
      const falling = track.length >= 2 && (track[track.length - 1] < track[0] - 8);
      // C — lateral drive below (only meaningful if not ejected).
      P(px, g0 - 30, pz);
      ctx.input.keys['KeyW'] = true;
      for (let i = 0; i < 40; i++) await raf();
      ctx.input.keys['KeyW'] = false;
      const c = at();
      const movedLat = Math.hypot(c.x - px, c.z - pz) > 1.0;
      // D — ELEVATOR: the player body is KINEMATIC (the KCC drives it — setLinvel
      // is silently ignored; the first spike run's punch-up verdict was vacuous).
      // Behavioral truth instead: a kinematic platform rises from 3m under the
      // sheet to 2m above it with the capsule standing on it. If the KCC resolves
      // the heightfield from BELOW, the capsule gets blocked/squeezed as the
      // platform passes the sheet; if the sheet is one-sided, the capsule rides
      // straight through and emerges standing on terrain.
      const RAPIER = g.RAPIER;
      const world = ctx.physics.world;
      const platBody = world.createRigidBody(RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(px, g0 - 3.2, pz));
      world.createCollider(RAPIER.ColliderDesc.cuboid(2, 0.2, 2), platBody);
      P(px, g0 - 2.2, pz);
      for (let i = 0; i < 20; i++) await raf();      // settle onto the platform
      const dStart = at();
      const onPlat = Math.abs(dStart.y - (g0 - 2.1)) < 1.2;
      let dEmerged = false, dStuckY = null;
      for (let i = 0; i < 240; i++) {
        const py = g0 - 3.2 + (i / 240) * 5.2;       // rise 5.2m over ~4s
        platBody.setNextKinematicTranslation({ x: px, y: py, z: pz });
        await raf();
        const y = at().y;
        if (y > g0 + 0.4) { dEmerged = true; break; }
        if (py > g0 + 0.6 && y < g0 - 0.5) { dStuckY = y; break; }   // platform passed the sheet, capsule left behind/squeezed
      }
      const d = at();
      world.removeRigidBody(platBody);
      return { g0: +g0.toFixed(2), A: { pos: a, ok: aOk }, B: { end: b, track, ejected, falling }, C: { end: c, movedLat }, D: { start: dStart, onPlat, end: d, emerged: dEmerged, stuckY: dStuckY } };
    });
    console.log(`[cave-spike] ${JSON.stringify(r, null, 1)}`);
    const verdict = r.B.ejected ? 'EJECTED below the sheet → portal-island (option 2)'
      : !r.D.onPlat ? 'INCONCLUSIVE: capsule never settled on the test platform — rerun'
      : r.D.emerged ? 'ONE-SIDED: capsule rides up THROUGH the sheet → underground volumes are free; caves need only their own floors/walls (trimesh interiors under the real terrain — option 1/3, no portals)'
      : 'TWO-SIDED: the sheet blocks from below → local heightfield→trimesh swap at the entrance chunk (option 3 ladder)';
    console.log(`[cave-spike] VERDICT: ${verdict}`);
  },

  // ── cave-digest (UNDERWORLD cycle 2) — the DETERMINISM gate (fast, no march). Reads the
  //    generated cave's layout digest (graph + vertex checksum). Run twice at one seed → stable;
  //    across two seeds → differs. Run: node scripts/rig-shot.mjs --scenario=cave-digest --seed=N
  'cave-digest': async (page) => {
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      let p = null;
      ctx.three.scene.traverse((o) => { if (o.userData && o.userData.caveGenProbe) p = o.userData.caveGenProbe; });
      if (!p) return { fail: 'no caveGenProbe (cave not built — flag off?)' };
      return { seed: ctx.seed, digest: p.digest, nodes: p.nodes.length, egg: +p.depthBelowSurface.toFixed(1), tris: p.triCount };
    });
    if (r.fail) { console.log(`CAVE-DIGEST FAIL ${r.fail}`); throw new Error('cave-digest FAILED'); }
    console.log(`CAVE-DIGEST seed=${r.seed} digest=${r.digest} nodes=${r.nodes} eggDepth=${r.egg}m tris=${r.tris}`);
  },

  // ── cave-walk (UNDERWORLD cycle 2) — the CAVE-GEN gate. A REAL KCC march covering the WHOLE
  //    tree (surface → mouth → every chamber depth-first, backtracking through junctions → back
  //    to the surface), plus castDown centreline sweeps (slope/headroom/floor-gaps/cover),
  //    topology asserts from the generator's own graph (tree, egg deepest, depth 25-40m), and the
  //    layout digest. Forces the flag ON. Run: node scripts/rig-shot.mjs --scenario=cave-walk --port=5210
  //
  //    ── DEEPER cycle 8 — REUSED, NOT FORKED ─────────────────────────────────────────────────
  //    `cave-streamed` walks STREAMED far-field caves with this exact machinery, by passing
  //    `opts.residentKey`. That is deliberate and it is the whole point: a second copy of a
  //    ~350-line march would drift from this one the first time either is tuned, and this
  //    project's driving lesson is that a gate measuring the wrong thing is worse than no gate.
  //    So the ONLY difference between walking the origin cave and walking a streamed one is
  //    WHICH probe pair the march reads — everything downstream (the Euler tour, the strand
  //    accounting, the corridor sweeps, the chamber-floor grid, the topology asserts) is shared
  //    code that cannot diverge. `opts` is absent for the origin run, so `cave-walk` itself is
  //    byte-for-byte the gate it has always been.
  //      opts.residentKey — walk THIS caveStream resident instead of the scene-traversed cave
  //      opts.noShots     — skip the 11-framing shot set (the streamed legs run 2-4 caves)
  //      opts.noThrow     — return the result instead of throwing, so the caller can aggregate
  'cave-walk': async (page, opts = {}) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      try { ctx.sandWorms.list.length = 0; } catch {}
      try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.42);
      ctx.three.renderer.setSize(1100, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 720; cam.updateProjectionMatrix(); }
    });
    const r = await page.evaluate(async (KEY) => {
      const g = window.__game; const ctx = g.ctx; const RAPIER = g.RAPIER;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      ctx.flags.paused = false; ctx.flags.thirdPerson = false;
      const body = ctx.player.body.body;
      const at = () => { const t = body.translation(); return { x: t.x, y: t.y, z: t.z }; };
      const CAP = ctx.player.body.halfHeight + ctx.player.body.radius;
      const RAD = ctx.player.body.radius;

      // WHICH CAVE. With no key this is the scene-traversed cave — with the origin cave preloaded
      // and pinned that is the egg cave, exactly as it has always been. With a key it is that
      // caveStream RESIDENT, read off the resident record rather than by scene traversal: once
      // caves stream, several `caveGen` groups can be in the scene at once and a traversal would
      // silently pick whichever came last. Reading the resident is the only unambiguous handle.
      let cavep = null, borep = null;
      if (KEY) {
        const res = (ctx.caveStream ? ctx.caveStream.residents() : []).find((x) => x.key === KEY);
        if (!res) return { fails: [`no resident cave keyed ${KEY} — it never streamed in`] };
        cavep = res.cave.probe;
        borep = res.entrance ? res.entrance.probe : null;
        if (!borep) return { fails: [`resident ${KEY} carries no crevice entrance — there is no way in to walk`] };
      } else {
        ctx.three.scene.traverse((o) => {
          if (o.userData && o.userData.caveGenProbe) cavep = o.userData.caveGenProbe;
          if (o.userData && o.userData.caveEntranceProbe) borep = o.userData.caveEntranceProbe;
        });
      }
      if (!cavep || !borep) return { fails: ['missing caveGenProbe / caveEntranceProbe (cave not built?)'] };
      const fails = [];
      const nodes = cavep.nodes;                 // {id,x,y,z,rx,height,kind,parent}
      const byId = (id) => nodes.find((n) => n.id === id);
      const egg = byId(cavep.eggId);

      const face = (dx, dz) => {
        const cam = ctx.three.camera; const t = body.translation();
        const L = Math.hypot(dx, dz) || 1;
        cam.position.set(t.x, t.y + ctx.player.eyeOffset, t.z);
        cam.lookAt(t.x + dx / L, t.y + ctx.player.eyeOffset, t.z + dz / L);
        cam.updateMatrixWorld(true);
      };
      const placeAt = async (wx, wy, wz) => {
        body.setTranslation({ x: wx, y: wy + CAP + 0.2, z: wz }, true);
        body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        ctx.player.velocityY = 0;
        await frames(40);
      };

      const rayUpFn = (x, y, z) => {
        const ray = new RAPIER.Ray({ x, y, z }, { x: 0, y: 1, z: 0 });
        const hit = ctx.physics.world.castRay(ray, 20, true, undefined, undefined, undefined, body);
        return hit ? hit.timeOfImpact : Infinity;
      };

      // ── REAL KCC walk toward an XZ target. Faces the target + holds W each frame; stops on
      //    arrival, or on a stall (no progress). Records the deepest Y for fall-through. ──
      let deepestSeen = Infinity;
      // Cast a horizontal ray from the capsule mid-height in an XZ direction; return clear distance.
      const sideClear = (px, py, pz, dirx, dirz) => {
        const half = ctx.player.body.halfHeight + ctx.player.body.radius;
        const ray = new RAPIER.Ray({ x: px, y: py - half + 1.0, z: pz }, { x: dirx, y: 0, z: dirz });
        const hit = ctx.physics.world.castRay(ray, 4, true, undefined, undefined, undefined, body);
        return hit ? hit.timeOfImpact : Infinity;
      };
      const walkToward = async (tx, tz, tFloorY, thresh, maxFrames) => {
        let best = Infinity, stall = 0, reached = false;
        ctx.input.keys['KeyW'] = true;
        for (let i = 0; i < maxFrames; i++) {
          const p = at();
          const dx = tx - p.x, dz = tz - p.z;
          const dist = Math.hypot(dx, dz);
          face(dx, dz);
          // UNSTICK: when progress stalls (a caught edge at a tight mouth/squeeze junction), a real
          // player wiggles — wall-slide toward the MORE-OPEN side (ray-picked, not blind), and when
          // deeply wedged back up a beat before re-approaching. Legitimate WASD, never a teleport.
          ctx.input.keys['KeyA'] = false; ctx.input.keys['KeyD'] = false; ctx.input.keys['KeyS'] = false;
          if (stall > 10) {
            const fl = Math.hypot(dx, dz) || 1; const ux = dx / fl, uz = dz / fl;
            const leftClear = sideClear(p.x, p.y, p.z, -uz, ux);     // heading rotated +90° (left)
            const rightClear = sideClear(p.x, p.y, p.z, uz, -ux);    // right
            // strafe toward the more open flank; if both are tight and we're really stuck, back up
            const deep = stall > 40;
            if (deep && (Math.floor(stall / 10) % 3 === 0)) { ctx.input.keys['KeyW'] = false; ctx.input.keys['KeyS'] = true; }
            else { ctx.input.keys['KeyW'] = true; ctx.input.keys[leftClear >= rightClear ? 'KeyA' : 'KeyD'] = true; }
          } else {
            ctx.input.keys['KeyW'] = true;
          }
          await raf();
          const q = at();
          deepestSeen = Math.min(deepestSeen, q.y);
          if (dist < thresh && Math.abs(q.y - tFloorY) < 2.4) { reached = true; break; }
          if (dist < best - 0.03) { best = dist; stall = 0; } else if (++stall > 200) break;
        }
        ctx.input.keys['KeyW'] = false; ctx.input.keys['KeyA'] = false; ctx.input.keys['KeyD'] = false; ctx.input.keys['KeyS'] = false;
        return reached;
      };

      // ── A — DESCENT + full-tree Euler-tour march (backtracking through junctions). ──
      const out = borep.waypoints.find((w) => w.name === 'outside');
      await placeAt(out.x, out.y, borep.centerZ);
      // DEEPER cycle 4 — THE CREVICE DESCENT. The entrance is no longer a straight 8m-wide ramp:
      // it is a ~2.2m slot that bends twice. "Face the target and hold W" cannot round a corner, so
      // the descent is walked LEG BY LEG along the entrance's own centreline waypoints. This is the
      // same steering aid the corridor march already uses (the two-phase mouth funnel), not a
      // teleport — every leg is a real KCC walk under gravity, and a leg that can't be walked fails
      // the gate. `placeAt` is used ONCE, on open desert outside the tor.
      const slotWps = borep.waypoints.filter((w) => w.name !== 'outside');
      const slotTrace = [];
      for (const w of slotWps) {
        const before = at();
        const okw = await walkToward(w.x, w.z, w.y, 1.7, 700);
        const after = at();
        slotTrace.push(`${w.name}:${okw ? 'ok' : 'X'}(${after.x.toFixed(1)},${after.z.toFixed(1)},y${after.y.toFixed(1)})`);
        if (!okw) {
          // one retry from where we are (a scrape against a slot wall is a steering artefact)
          const ok2 = await walkToward(w.x, w.z, w.y, 2.1, 600);
          slotTrace[slotTrace.length - 1] += ok2 ? '/retryOK' : '/RETRYFAIL';
          if (!ok2) {
            fails.push(`crevice descent: could not walk leg ${w.name} — from (${before.x.toFixed(1)},${before.z.toFixed(1)},y${before.y.toFixed(1)}) ended (${at().x.toFixed(1)},${at().z.toFixed(1)},y${at().y.toFixed(1)}) target (${w.x.toFixed(1)},${w.z.toFixed(1)},y${w.y.toFixed(1)})`);
            break;
          }
        }
      }
      const reached = new Set();
      const tour = cavep.tour;
      const trace = [];
      // 2026-07-26 — GATE HONESTY: RECORD THE LEGS THAT FAIL SILENTLY.
      // The Euler tour revisits junction chambers, and a revisit leg that stalls is tolerated (the
      // node is already in `reached`, so it can't "fail"). That tolerance is correct — a revisit is
      // not new coverage — but it was SILENT, and silence made the gate lie. Real case, seed 4242:
      // the capsule walked into dead-end pocket 9, could not walk back OUT, and the legs 9>6, 6>3,
      // 3>2 all stalled unreported; the first NEW node after them (5) then failed, so the gate
      // printed "could not reach node 5 (pocket) from 2" and dumped the floor profile of the 2→5
      // corridor — which is perfectly walkable and 60m from where the capsule actually was. A whole
      // investigation went hunting a corridor pinch that does not exist. A stranded capsule is now
      // named at the point it stranded, and the strand list rides the fail message + the result line.
      const strands = [];
      for (let ti = 0; ti < tour.length; ti++) {
        const n = byId(tour[ti]);
        const thresh = Math.max(1.4, n.rx * 0.6);
        // TWO-PHASE nav: first funnel to the corridor MOUTH on the current chamber's surface toward
        // the target (so the capsule enters the corridor aligned, not wedged against a wall at an
        // off-angle — how a real player lines up a doorway), THEN walk to the target centre.
        if (ti > 0) {
          const prev = byId(tour[ti - 1]);
          if (prev.id !== n.id) {
            const D = Math.hypot(n.x - prev.x, n.z - prev.z) || 1;
            const ux = (n.x - prev.x) / D, uz = (n.z - prev.z) / D;
            const mx = prev.x + ux * (prev.rx + 1.0), mz = prev.z + uz * (prev.rx + 1.0);
            await walkToward(mx, mz, prev.floorY, 2.2, 500);
          }
        }
        const p0 = at();
        // Distance-proportional frame budget (~0.1m/frame) + the entrance descent's extra margin;
        // stall detection breaks early if genuinely blocked, so a generous cap only costs frames
        // when the capsule is actually still walking.
        const dist0 = Math.hypot(n.x - p0.x, n.z - p0.z);
        const budget = Math.min(2400, Math.max(500, Math.ceil(dist0 * 26) + (ti === 0 ? 300 : 200)));
        let ok = await walkToward(n.x, n.z, n.y, thresh, budget);
        // Recovery: a transient stall (crude steering vs a tight mouth / a climb-out) can leave a
        // still-walkable node unreached. Re-approach from the last reached chamber and retry — up to
        // 3 times (a real player re-lines-up a doorway). The geometry is proven walkable; this only
        // de-flakes the crude probe steering.
        for (let retry = 0; retry < 3 && !ok && !reached.has(n.id); retry++) {
          let anchor = null;
          for (let bi = ti - 1; bi >= 0; bi--) { if (reached.has(tour[bi])) { anchor = byId(tour[bi]); break; } }
          if (!anchor) break;
          await walkToward(anchor.x, anchor.z, anchor.y, Math.max(1.4, anchor.rx * 0.6), 1600);
          ok = await walkToward(n.x, n.z, n.y, thresh, budget);
        }
        const p1 = at();
        trace.push(`${tour[ti]}:${ok ? 'ok' : 'X'} (${p1.x.toFixed(1)},${p1.z.toFixed(1)},${p1.y.toFixed(1)}) moved${Math.hypot(p1.x - p0.x, p1.z - p0.z).toFixed(1)}`);
        if (ok) reached.add(n.id);
        else if (reached.has(n.id)) {
          // A revisit leg that stalled: not a coverage failure, but the capsule is NOT where the
          // tour thinks it is, so every later leg is measured from the wrong place. Record it.
          const ps = at();
          strands.push(`${ti > 0 ? tour[ti - 1] : '?'}>${n.id}@(${ps.x.toFixed(1)},${ps.z.toFixed(1)},y${ps.y.toFixed(1)})d${Math.hypot(ps.x - n.x, ps.z - n.z).toFixed(1)}`);
        } else {
          const p = at();
          // diagnostic: the castDown floor profile from the previous tour node to this one
          const prevN = ti > 0 ? byId(tour[ti - 1]) : n;
          const prof = [];
          const Dd = Math.hypot(n.x - prevN.x, n.z - prevN.z) || 1;
          const hxd = (n.x - prevN.x) / Dd, hzd = (n.z - prevN.z) / Dd;
          const sAd = prevN.rx - 1.2, sBd = Dd - (n.rx - 1.2);
          for (let s = 0; s <= 8; s++) {
            const t = s / 8;
            const al = sAd + (sBd - sAd) * t;
            const x = prevN.x + hxd * al, z = prevN.z + hzd * al;
            const fg = prevN.y + (n.y - prevN.y) * t;
            const hit = g.castDown(x, z, fg + 1.0, true);
            const up = hit ? rayUpFn(x, hit.hitY + 0.2, z) : Infinity;
            prof.push(hit ? `${(hit.hitY - fg).toFixed(1)}/${up === Infinity ? '∞' : up.toFixed(1)}` : 'GAP');
          }
          // forward-clearance rays from the stall point toward the target at 3 heights
          const fdx = (n.x - p.x), fdz = (n.z - p.z); const fl = Math.hypot(fdx, fdz) || 1;
          const fwd = [];
          for (const hy of [0.3, 1.0, 1.7]) {
            const ray = new RAPIER.Ray({ x: p.x, y: p.y - (ctx.player.body.halfHeight + ctx.player.body.radius) + hy, z: p.z }, { x: fdx / fl, y: 0, z: fdz / fl });
            const hit = ctx.physics.world.castRay(ray, 8, true, undefined, undefined, undefined, body);
            fwd.push(hit ? hit.timeOfImpact.toFixed(1) : '∞');
          }
          // The strand list comes FIRST: when it is non-empty the capsule never made it back to
          // `prevN`, so the fwdClear/floor profile below describes a corridor it was never in, and
          // the real defect is at the FIRST strand. Read that before reading anything else.
          fails.push(`march: could not reach node ${n.id} (${n.kind}) from ${prevN.id}` +
            (strands.length ? ` — ⚠ STRANDED EARLIER, the tour never returned: [${strands.join(' ')}] — diagnose the FIRST of those, not this leg` : '') +
            ` — ended (${p.x.toFixed(1)},${p.z.toFixed(1)},y${p.y.toFixed(1)}); fwdClear@[.3/1/1.7]=[${fwd.join(' ')}]; floorΔ/head [${prof.join(' ')}]`);
          break;   // a broken link stalls the rest of the tour; one failure is enough
        }
        await frames(4);
      }
      for (const n of nodes) if (!reached.has(n.id)) fails.push(`march: chamber ${n.id} (${n.kind}) never reached`);
      if (deepestSeen < egg.y - 3.0) fails.push(`march: capsule fell through (minY ${deepestSeen.toFixed(1)} << egg floor ${egg.y.toFixed(1)})`);

      // ── B — ASCENT back to the surface (real KCC, up the throat + ramp). Retry from the throat
      //      if the crude surface leg stalls in the rim-boulder collar, and accept exit once the
      //      capsule is clearly ON the surface near the mouth (Y within ~1m of terrain), which is the
      //      real "out of the cave" criterion — a player who's climbed to surface height IS out. ──
      //      DEEPER cycle 4: the ascent now climbs the CREVICE — the same bent slot, walked in
      //      reverse, at ~30°. This is the leg most likely to break on a narrow steep entrance, so
      //      it is walked leg by leg like the descent (and every leg is a real KCC climb).
      let exited = false;
      const ascTrace = [];
      if (fails.length === 0) {
        // Funnel through the junction FIRST (i = length-1): the entrance hall is 9.6m across and
        // the slot mouth in its wall is 3.6m wide, so a capsule that ended the tour off to one side
        // walks a chord straight into the wall beside the door. Same two-phase nav the corridor
        // march already uses; the climb itself is unassisted.
        for (let i = slotWps.length - 1; i >= 0; i--) {
          const w = slotWps[i];
          // Sub-divide each climb leg: a 4.5m leg walked as one target lets the capsule drift onto
          // the slot wall and wedge (round-8 ascent: it reached the junction, then slid 2.4m
          // off-axis and stalled against the wall). Half-legs keep it near the centreline.
          const prevW = slotWps[Math.min(slotWps.length - 1, i + 1)];
          if (prevW !== w) await walkToward((w.x + prevW.x) * 0.5, (w.z + prevW.z) * 0.5, (w.y + prevW.y) * 0.5, 1.9, 500);
          let okw = await walkToward(w.x, w.z, w.y, 1.9, 800);
          if (!okw) okw = await walkToward(w.x, w.z, w.y, 2.4, 700);
          { const q = at(); ascTrace.push(`${w.name}:${okw ? 'ok' : 'X'}(${q.x.toFixed(1)},${q.z.toFixed(1)},y${q.y.toFixed(1)})→(${w.x.toFixed(1)},${w.z.toFixed(1)},y${w.y.toFixed(1)})`); }
        }
        const outW = borep.waypoints.find((x) => x.name === 'outside');
        exited = await walkToward(outW.x, outW.z, outW.y, 3.0, 900);
        const pE = at();
        // A player who has climbed back to surface height, outside the tor, IS out.
        if (!exited && pE.y >= borep.gy - 1.2 && pE.x <= borep.mouthX + 1.5) exited = true;
        if (!exited) fails.push(`ascent: could not climb back OUT of the crevice (ended x=${pE.x.toFixed(1)} z=${pE.z.toFixed(1)} y=${pE.y.toFixed(1)}; surface ${borep.gy.toFixed(1)}) legs=[${ascTrace.join(' ')}]`);
      }

      // ── C — castDown centreline sweeps along every corridor: floor continuity, slope ≤32°,
      //      headroom ≥2.0m, cover ≥1.5m below the terrain sheet. ──
      let maxSlope = 0, gaps = 0, minHeadroom = Infinity, minCover = Infinity, sweptSamples = 0, minCoverAt = "", maxSlopeAt = "", gapAt = [];
      const rayUp = rayUpFn;
      const OV = 1.2;   // CAVE_GEN_END_OVERLAP — the tube spans surface-to-surface (matches the mesh)
      for (const e of cavep.edges) {
        const a = byId(e.a), b = byId(e.b);
        const D = Math.hypot(b.x - a.x, b.z - a.z);
        const hx = (b.x - a.x) / D, hz = (b.z - a.z) / D;
        // sample the CORRIDOR span only (from just inside a's surface to just inside b's) with the
        // SAME floor function the mesh uses (linear centre-to-centre, projection-based) — measuring
        // through the chamber interiors gives false "gaps" (flat chamber floor ≠ the linear ramp).
        const sA = a.rx - OV, sB = D - (b.rx - OV);
        // Sample every ~1.3m: the corridor slope is measured over that baseline, smoothing out the
        // sub-metre floor-transition steps at the mouths (a real ramp is sustained; a 0.6m/0.7m
        // spike at a doorway is a mesh-transition artifact, not an unwalkable grade).
        const K = Math.max(4, Math.ceil((sB - sA) / 1.3));
        let prev = null;
        for (let s = 0; s <= K; s++) {
          const tt = s / K;                        // tube parameter (matches the mesh floor)
          // The outer ~12% of each corridor is the mouth OVERLAP with the chamber (the tube floor
          // meeting the flat-floor disk edge — a castDown transition zone). Floor there is proven by
          // the chamber-floor GRID check + the KCC march; the sweep checks the corridor INTERIOR.
          const interior = tt > 0.12 && tt < 0.88;
          const along = sA + (sB - sA) * tt;
          const x = a.x + hx * along, z = a.z + hz * along;
          const floorGuess = a.y + (b.y - a.y) * tt;
          // cast from just above the floor (BELOW the arch ceiling — even a pinched squeeze
          // clears ~1.8m — so we hit the FLOOR, not the roof: the cave-mouth lesson).
          // cast from well ABOVE the linear estimate (the actual tube floor rises above it at the
          // mouths) but below the ~2.7m doorway ceiling, so we always hit the floor, never start
          // below it (which read as a false "no floor"). Tolerance covers the mouth deviation.
          const hit = g.castDown(x, z, floorGuess + 2.2, true);
          if (!hit || Math.abs(hit.hitY - floorGuess) > 2.4) { if (interior) { gaps++; if (gapAt.length < 6) gapAt.push(`e${e.a}-${e.b}@tt${tt.toFixed(2)}(${x.toFixed(0)},${z.toFixed(0)})${hit ? 'dy' + (hit.hitY - floorGuess).toFixed(1) : 'MISS'}`); } prev = null; continue; }
          sweptSamples++;
          const up = rayUp(x, hit.hitY + 0.2, z);
          // Only measure headroom/cover where a real ceiling is found. Near the tube ends the
          // ceiling opens into the chamber above (rayUp = ∞) — that's the aperture, not a gap.
          if (up !== Infinity) {
            const head = up + 0.2;
            if (head < minHeadroom) minHeadroom = head;
            const cover = ctx.terrain.pureHeightAt(x, z) - (hit.hitY + head);
            if (cover < minCover) { minCover = cover; minCoverAt = `e${e.a}-${e.b}@(${x.toFixed(0)},${z.toFixed(0)})ceil${(hit.hitY + head).toFixed(1)}terr${ctx.terrain.pureHeightAt(x, z).toFixed(1)}`; }
          }
          if (prev && interior) {
            const dxh = Math.hypot(x - prev.x, z - prev.z);
            if (dxh > 0.4) { const sl = (Math.atan2(Math.abs(hit.hitY - prev.y), dxh) * 180) / Math.PI; if (sl > maxSlope) { maxSlope = sl; maxSlopeAt = `e${e.a}-${e.b}@(${x.toFixed(0)},${z.toFixed(0)})dy${(hit.hitY - prev.y).toFixed(1)}/dx${dxh.toFixed(1)}`; } }
          }
          prev = { x, z, y: hit.hitY };
        }
      }
      // A REAL fall-through hole is caught by the KCC march (deepestSeen) AND spans several 1.3m
      // samples; a single isolated castDown MISS is a ray threading a trimesh triangle edge (a swept
      // capsule can't — the march rode through fine), so require ≥2 to fail.
      if (gaps > 1) fails.push(`corridor floor: ${gaps} samples NO floor at [${gapAt.join(" ")}]`);
      if (maxSlope > 32) fails.push(`corridor slope: max ${maxSlope.toFixed(1)}° > 32° at ${maxSlopeAt}`);
      if (minHeadroom < 2.0) fails.push(`corridor headroom: min ${minHeadroom.toFixed(2)}m < 2.0m`);
      if (minCover < 1.5) fails.push(`cover: min ${minCover.toFixed(2)}m of rock over the cave < 1.5m (poke-through risk) at ${minCoverAt}`);

      // ── D — chamber floors solid (no gaps) + headroom, and NOT embedded (open void at centre). ──
      let chamGaps = 0, chamMinHead = Infinity;
      const holeSpots = [];
      for (const n of nodes) {
        // DENSE polar grid over the flat floor (rings × spokes, out to ~0.7·rx where the floor is
        // flat) — a coarse 5-point check misses a small hole the capsule can drop through.
        for (let ri = 0; ri <= 4; ri++) {
          const rr = (n.rx * 0.72 * ri) / 4;
          const spokes = ri === 0 ? 1 : 8;
          for (let si = 0; si < spokes; si++) {
            const ang = (si / spokes) * Math.PI * 2;
            const ox = Math.cos(ang) * rr, oz = Math.sin(ang) * rr;
            const hit = g.castDown(n.x + ox, n.z + oz, n.y + 1.5, true);
            if (!hit || Math.abs(hit.hitY - n.y) > 1.5) { chamGaps++; if (holeSpots.length < 8) holeSpots.push(`n${n.id}@(${(n.x + ox).toFixed(1)},${(n.z + oz).toFixed(1)})r${rr.toFixed(1)}`); continue; }
            const up = rayUp(n.x + ox, hit.hitY + 0.2, n.z + oz);
            if (up !== Infinity && up + 0.2 < chamMinHead) chamMinHead = up + 0.2;
          }
        }
      }
      if (chamGaps > 0) fails.push(`chamber floor: ${chamGaps} grid points found NO floor — holes at [${holeSpots.join(' ')}]`);
      if (chamMinHead < 2.0) fails.push(`chamber headroom: min ${chamMinHead.toFixed(2)}m < 2.0m`);

      // ── E — TOPOLOGY asserts from the generator's own graph. ──
      //
      //   DEEPER cycle 9 — KIND-AWARE ENVELOPE. The chamber count and egg depth used to be the
      //   literals 8-11 and 25-40m, which were the canonical cave's range and nothing else. With
      //   kinds those literals would fail a 14-room warren and a 48m collapsed shaft for being
      //   exactly what they are designed to be. They now come from the KIND'S OWN DECLARED envelope
      //   (`probe.envelope`), which `assertCaveKindTable` proves actually contains that kind's
      //   generator range — so a kind cannot widen its gate without widening it honestly, and
      //   `canonical` still declares 8-11 / 25-40m, i.e. the origin cave is asserted EXACTLY as
      //   before. Three things stay HARD LIMITS on every kind, because they are not taste:
      //     · the tree property (V-1 edges), · the egg is the deepest AND the largest chamber,
      //     · absolute floors nothing may cross (≥4 chambers, 15-70m deep) so a table that
      //       declared a nonsense envelope still cannot launder a broken cave as a pass.
      const V = nodes.length, E = cavep.edges.length;
      const env = cavep.envelope || { chambersMin: 8, chambersMax: 11, depthMin: 25, depthMax: 40 };
      const kindName = cavep.kind || 'canonical';
      if (V < env.chambersMin || V > env.chambersMax) fails.push(`topology: chamber count ${V} outside the '${kindName}' envelope ${env.chambersMin}-${env.chambersMax}`);
      if (V < 4) fails.push(`topology: chamber count ${V} < 4 — below the absolute floor no kind may cross`);
      if (E !== V - 1) fails.push(`topology: ${E} edges for ${V} nodes — not a tree (V-1 edges required)`);
      for (const n of nodes) if (n.id !== egg.id && n.y < egg.y) fails.push(`topology: node ${n.id} (y${n.y.toFixed(1)}) deeper than the egg (y${egg.y.toFixed(1)})`);
      for (const n of nodes) if (n.id !== egg.id && n.rx > egg.rx) fails.push(`topology: node ${n.id} (rx${n.rx.toFixed(1)}) larger than the egg (rx${egg.rx.toFixed(1)})`);
      const depth = cavep.depthBelowSurface;
      if (depth < env.depthMin || depth > env.depthMax) fails.push(`topology: egg depth ${depth.toFixed(1)}m outside the '${kindName}' envelope ${env.depthMin}-${env.depthMax}m`);
      if (depth < 15 || depth > 70) fails.push(`topology: egg depth ${depth.toFixed(1)}m outside the absolute 15-70m floor/ceiling no kind may cross`);
      const hasSqueeze = cavep.edges.some((e) => e.squeeze), hasGallery = cavep.edges.some((e) => !e.squeeze);
      if (!hasSqueeze || !hasGallery) fails.push(`topology: corridors lack varied cross-sections (squeeze=${hasSqueeze} gallery=${hasGallery})`);

      return {
        fails, seed: ctx.seed, digest: cavep.digest,
        caveKind: kindName,
        fungiClusters: cavep.fungiClusters ?? -1, rubbleHeaps: cavep.rubbleHeaps ?? -1,
        scrapAnchors: cavep.scrapAnchors ?? -1, pools: (cavep.pools || []).length,
        chambers: V, edges: E, eggId: cavep.eggId, eggKind: egg.kind, eggDepth: +depth.toFixed(1),
        eggRx: +egg.rx.toFixed(1), tris: cavep.triCount, reached: reached.size, tour: tour.length,
        maxSlope: +maxSlope.toFixed(1), minHeadroom: minHeadroom === Infinity ? 'n/a' : +minHeadroom.toFixed(2),
        chamMinHead: chamMinHead === Infinity ? 'n/a' : +chamMinHead.toFixed(2),
        minCover: minCover === Infinity ? 'n/a' : +minCover.toFixed(2), gaps, chamGaps, exited, deepest: +deepestSeen.toFixed(1),
        kinds: nodes.map((n) => n.kind).join(','),
        // DEEPER cycle 4 — the crevice, reported SEPARATELY from the corridor slope ceiling.
        entSlope: borep.descentAngleDeg, entMouthW: borep.mouthClearW, entPinchW: borep.pinchClearW,
        entTorTris: borep.torTris, entMs: borep.msTor, slotTrace, ascTrace,
        trace, tourStr: tour.join('>'), strands,
        nodesXY: nodes.map((n) => `${n.id}<-${n.parent}:(${n.x.toFixed(1)},${n.z.toFixed(1)},${n.y.toFixed(1)})r${n.rx.toFixed(1)}h${n.height.toFixed(1)}`),
      };
    }, opts.residentKey ?? null);
    const pass = r.fails.length === 0;
    console.log(`CAVE-WALK pass=${pass ? 1 : 0} seed=${r.seed ?? '?'} kind=${r.caveKind ?? '?'} digest=${r.digest ?? '?'} chambers=${r.chambers ?? '?'} edges=${r.edges ?? '?'} reached=${r.reached ?? '?'}/${r.chambers ?? '?'} tour=${r.tour ?? '?'} eggDepth=${r.eggDepth ?? '?'}m eggRx=${r.eggRx ?? '?'} slope=${r.maxSlope ?? '?'}° headroom=${r.minHeadroom ?? '?'} chamHead=${r.chamMinHead ?? '?'} cover=${r.minCover ?? '?'} ascent=${r.exited ? 'OUT' : 'FAIL'} tris=${r.tris ?? '?'} strands=${(r.strands ?? []).length} fails=${r.fails.length}`);
    if (r.fails.length) console.log('[cave-walk] ' + JSON.stringify(r.fails.slice(0, 12)));
    // Strands are reported on PASSING runs too — a tour that covered every chamber but had to
    // fight its way out of one of them is the early warning for the flake that eventually goes red.
    if (r.strands && r.strands.length) console.log(`[cave-walk] ⚠ STRANDED LEGS (tolerated, node already reached): [${r.strands.join(' ')}]`);
    console.log(`CAVE-CREVICE seed=${r.seed ?? '?'} slope=${r.entSlope ?? '?'}° mouthW=${r.entMouthW ?? '?'}m pinchW=${r.entPinchW ?? '?'}m torTris=${r.entTorTris ?? '?'} ms=${r.entMs ?? '?'}`);
    if (r.slotTrace) console.log(`[cave-walk] descent=[${r.slotTrace.join(' ')}] ascent=[${(r.ascTrace ?? []).join(' ')}]`);
    console.log(`[cave-walk] kinds=[${r.kinds ?? '?'}]`);
    if (r.nodesXY) console.log(`[cave-walk] nodes=[${r.nodesXY.join(' ')}] tour=${r.tourStr}`);
    if (r.trace) console.log(`[cave-walk] trace=[${r.trace.join(' | ')}]`);

    // The streamed legs stop here: the mouth-area mesh scan below and the 11-framing shot set are
    // origin-cave diagnostics, and re-shooting them per streamed cave would multiply the gate's
    // wall clock for pictures nobody reads. The MEASUREMENTS above are identical either way.
    if (opts.noShots) {
      if (!pass && !opts.noThrow) throw new Error('cave-walk GATE FAILED');
      return r;
    }

    // UNDERWORLD cycle 2 carry-item — hunt the "floating red cube" seen at the mouth in pass 1.
    // Position-based scan: ANY mesh (regardless of material) whose world pos sits within 22m (XZ) of
    // the bore mouth and above (surface - 4m), EXCLUDING the cave groups + the terrain — so we catch
    // the floating object no matter its material and report name + pos + parent chain + colour.
    const redScan = await page.evaluate(() => {
      const ctx = window.__game.ctx; const hits = [];
      const THREE = window.__game.THREE; const wp = new THREE.Vector3();
      let bx = null, bz = null, gy = null;
      ctx.three.scene.traverse((o) => { if (o.userData && o.userData.caveEntranceProbe) { bx = o.userData.caveEntranceProbe.mouthX; bz = o.userData.caveEntranceProbe.centerZ; gy = o.userData.caveEntranceProbe.gy; } });
      if (bx === null) return { note: 'no bore probe', hits };
      ctx.three.scene.traverse((o) => {
        if (!o.isMesh) return;
        let skip = false; for (let p = o; p; p = p.parent) { if (p.name === 'caveGen' || p.name === 'caveEntrance' || p.name === 'terrain' || (p.name && p.name.startsWith('chunk'))) { skip = true; break; } }
        if (skip) return;
        o.getWorldPosition(wp);
        if (Math.hypot(wp.x - bx, wp.z - bz) > 24 || wp.y < gy - 4) return;
        const m = Array.isArray(o.material) ? o.material[0] : o.material;
        const chain = []; for (let p = o; p && chain.length < 7; p = p.parent) chain.push(p.name || p.type);
        hits.push({ name: o.name || '(unnamed)', geo: o.geometry?.type, pos: [+wp.x.toFixed(1), +wp.y.toFixed(1), +wp.z.toFixed(1)], chain: chain.join('<'), color: m && m.color ? m.color.getHexString() : null, matType: m && m.type, interact: o.userData?.interactType || o.userData?.interactRegistry || null });
      });
      return { mouth: [bx, +gy.toFixed(1), bz], hits: hits.slice(0, 16) };
    });
    console.log(`[cave-walk] MOUTH-AREA MESH SCAN: ${JSON.stringify(redScan)}`);

    await caveShotSet(page, 'cave-walk');
    if (!pass && !opts.noThrow) throw new Error('cave-walk GATE FAILED');
    return r;
  },

  // ── cave-look (DEEPER cycle 3) — the FAST visual-iteration scenario. Exactly the `cave-walk`
  //    shot set (same 11 framings, same lighting, same names) with the ~4-minute KCC march and the
  //    topology asserts SKIPPED. This is the rule-8 iteration loop: build → shoot → critique →
  //    adjust, without paying for the traversability gate on every round. The gate itself
  //    (`cave-walk`) still runs once at the end of a batch, per the SPEED RULES.
  //    Run: npm run rig -- --scenario=cave-look --port=5243 [--seed=1337] [--tag=r1]
  'cave-look': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      try { ctx.sandWorms.list.length = 0; } catch {}
      try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.42);
      ctx.three.renderer.setSize(1100, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 720; cam.updateProjectionMatrix(); }
    });
    const tag = argv.tag ? `cave-look-${argv.tag}` : 'cave-look';
    await caveShotSet(page, tag);
  },

  // ── cave-audit (DEEPER cycle 7) — THE FULL-TREE VISUAL AUDIT SET ────────────────────────────
  //
  //   `cave-look` is the ITERATION loop: it inherits `cave-walk`'s framings, and half of those are
  //   rig-lit greybox shots (a flat 0.85 ambient + a fat fill PointLight) that exist so a builder can
  //   read FORM while sculpting. They are not what a player sees. This scenario is the AUDIT: every
  //   frame is the REAL player's-eye read at REAL shipping settings, across the WHOLE tree, so fresh
  //   critics grade the cave a player actually walks through rather than a lit-for-inspection model.
  //
  //   WHAT MAKES IT HONEST (the poolShotSet discipline, extended from one pool to the whole cave):
  //     · ONE exposure, `CAVE_AUDIT_EXPOSURE`, equal to src/core/scene.ts's toneMappingExposure.
  //       `cave-look`/`cave-walk` shoot at 1.15-1.55, i.e. 10-48% hot; nothing here is brightened.
  //     · The light model is not hand-set. Every framing PINS THE PLAYER at the stand point and runs
  //       the REAL tick chain (updateLighting → updateCaveAtmosphere) for a few frames, so ambient /
  //       sun / moon / fog colour+density / the mouth shaft are whatever the SHIPPING depth-fade
  //       gives at that spot — daylight at 78m out, the ramp-lit throat, true black in the deep tree.
  //       Then it pauses (the pause gate freezes lighting) and shoots. No probe-invented lights.
  //     · The carried light is the shipping torch/flashlight tuning at the flame offset the game uses.
  //     · NOTHING is hidden except the first-person body + view model. The exterior shots keep the
  //       real sky, terrain and weather fog, because "does the tor read as a landmark at 78m" is only
  //       answerable in the real desert.
  //     · Floors are snapped with a REAL physics castDown, not a node's nominal floorY, so the eye is
  //       1.68m above the surface the capsule would actually stand on.
  //
  //   Every frame also prints a `[cave-metric]` line (readPixels over the whole frame: mean/percentile
  //   luminance, the sub-L16 fraction, and the top/middle/bottom band means) so critics get NUMBERS
  //   alongside pixels — "the ceiling is a dark smoky band" is a claim a band mean can corroborate.
  //
  //   ALSO MEASURED HERE: the CAVE_ROCK_BUMP perf residual. `caveBumpPerf` renders a fixed cave
  //   framing N times with the shipping bump shader and N times with a rig-local NO-BUMP clone of the
  //   same material (a uniform of 0 would NOT answer the question — the shader still evaluates all
  //   eight value-noise samples and multiplies by zero), and reports mean/p95 frame ms for both. Run
  //   it with `--gl=swiftshader` for the low-end (software raster) answer and on the default GPU for
  //   reference. Nothing shipping changes: the clone lives for the length of the measurement.
  //
  //   Run: npm run rig -- --scenario=cave-audit --port=52xx [--seed=1337] [--only=shots|perf]
  //        npm run rig -- --scenario=cave-audit --port=52xx --only=perf --gl=swiftshader
  'cave-audit': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      try { ctx.sandWorms.list.length = 0; } catch {}
      try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.42);      // clear mid-morning — the surface read the tor gets
      ctx.flags.thirdPerson = false;                    // FIRST person: this audit is the player's eye
      ctx.three.renderer.setSize(1280, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1280 / 720; cam.updateProjectionMatrix(); }
    });
    const seed = Number(argv.seed ?? 1337);
    const only = String(argv.only || 'both');
    if (only !== 'perf') {
      await caveAuditShotSet(page, `caveaudit-${seed}` + (argv.hidesky ? '-nosky' : '') + (argv.tag ? '-' + argv.tag : ''), {
        framings: argv.framings ? String(argv.framings).split(',').map((s) => s.trim()) : null,
        hideSky: !!argv.hidesky,
        keepHud: !!argv.keephud,
        hideGroup: argv.hidegroup ? String(argv.hidegroup) : null,
      });
    }
    if (only !== 'shots') {
      await caveBumpPerf(page, { samples: Number(argv.perfsamples || 0) || undefined });
    }
  },

  // ── cave-light (DEEPER cycle 10) — DAY-INVARIANCE + NO SKY BODY THROUGH ROCK ────────────────
  //
  //   The ITERATION loop for the two teeth `cave-kinds` carries permanently (see the
  //   `caveLightAsserts` header for the WHY and the tolerances). `cave-kinds` builds four caves
  //   and marches them and takes ~25 min; this builds ONE and takes ~1, which is the difference
  //   between iterating on a light model and waiting on one.
  //
  //   `--kind=origin`   the boot cave (the population the cycle-7 fix was written against)
  //   `--kind=warren|fungal|flooded|shaft`  a STREAMED cave, arrived at through the shipped
  //                     `requestSite` path — the population where an origin-scoped fix stops applying
  //   `--shots=1`       also write the PNGs
  //   `--refs=1`        additionally shoot the CARRIED-LIGHT reference set (torch/flashlight/lantern
  //                     at the shipping dials) so a strength change has a documented before/after
  //
  //   Run: npm run rig -- --scenario=cave-light --kind=warren --port=52xx
  'cave-light': async (page) => {
    const KIND = String(argv.kind || 'origin');
    const SHOTS = !!Number(argv.shots || 0);
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      try { ctx.sandWorms.list.length = 0; } catch {}
      try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0;
      ctx.flags.thirdPerson = false;
      ctx.three.renderer.setSize(960, 540, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 960 / 540; cam.updateProjectionMatrix(); }
    });

    let key = null;
    if (KIND !== 'origin') {
      const site = await page.evaluate((K) => {
        const g = window.__game; const ctx = g.ctx;
        if (!ctx.caveStream) return { fatal: 'ctx.caveStream is null' };
        const all = g.caveSites(0, 0, 6000);
        if (!all.length) return { fatal: 'no cave sites within 6km' };
        const s = all.map((q) => ({ ...q, d: Math.hypot(q.x, q.z) })).sort((a, b) => a.d - b.d)[0];
        return { key: `lightgate:${K}`, x: s.x, z: s.z, seed: s.seed, kind: K };
      }, KIND);
      if (site.fatal) { console.log(`CAVE-LIGHT pass=0 FATAL ${site.fatal}`); throw new Error('cave-light FAILED'); }
      const arrive = await page.evaluate(async (S) => {
        const g = window.__game; const ctx = g.ctx; const T = g.Tuning;
        const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
        ctx.caveStream.setSiteSource(null);          // this leg measures ONE named cave
        const APPROACH = Math.min(120, T.CAVE_STREAM_REQUEST_M * 0.4);
        const px = S.x - APPROACH, pz = S.z;
        ctx.player.body.body.setTranslation({ x: px, y: ctx.terrain.heightAt(px, pz) + 2, z: pz }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        for (let f = 0; f < 2000; f++) { await raf(); if (f > 90 && ctx.terrain.isTileLoadedAt(S.x, S.z)) break; }
        if (!ctx.terrain.isTileLoadedAt(S.x, S.z)) return { ok: false, why: 'terrain tile never loaded' };
        if (!ctx.caveStream.requestSite({ key: S.key, x: S.x, z: S.z, seed: S.seed, kind: S.kind })) return { ok: false, why: 'requestSite refused' };
        for (let f = 0; f < 9000; f++) { await raf(); if (ctx.caveStream.residents().some((r) => r.key === S.key)) return { ok: true, at: [S.x, S.z] }; }
        return { ok: false, why: 'never built' };
      }, site);
      if (!arrive.ok) { console.log(`CAVE-LIGHT pass=0 FATAL ${arrive.why}`); throw new Error('cave-light FAILED'); }
      key = site.key;
      console.log(`[cave-light] streamed ${KIND} cave at (${arrive.at[0].toFixed(0)},${arrive.at[1].toFixed(0)})`);
    }

    const r = await caveLightAsserts(page, KIND, key, { shots: SHOTS });
    console.log(`[cave-light] cave: kind=${r.plan ? r.plan.kind : '?'} depth=${r.plan ? r.plan.depth : '?'}m eggRx=${r.plan ? r.plan.eggRx : '?'}m`);
    for (const row of r.rows) console.log(row);

    if (Number(argv.refs || 0)) await caveLightRefs(page, KIND, key);

    for (const f of r.fails) console.log(`[cave-light] FAIL ${f}`);
    console.log(`CAVE-LIGHT pass=${r.fails.length ? 0 : 1} kind=${KIND} fails=${r.fails.length}`);
    if (r.fails.length) throw new Error('cave-light GATE FAILED');
  },

  // ── pool-fill (DEEPER cycle 6) — THE UNDERGROUND-WATER GATE ────────────────────────────────
  //   Five things, all with teeth, none of them a screenshot:
  //
  //   1. EXISTENCE + DETERMINISM. The origin cave must have ≥1 pool (the spec's guarantee), and the
  //      pool set must be byte-stable: the caveGenProbe's pool list is compared against a SECOND
  //      generation of the same seed (`__game.rebuildCaveProbe`-free — we re-run the pure placement
  //      through the module, so the check costs milliseconds instead of a second cave build).
  //   2. RULE 9 — COLLISION MATCHES THE VISIBLE GEOMETRY. A Rapier ray dropped through the pool
  //      centre must NOT stop at the water plane: it must hit the rock at the FLOOR, and that hit
  //      must agree (≤5cm) with the first NON-WATER hit of a three.js raycast down the same line —
  //      i.e. the bottom you SEE through the water is the surface you STAND on. A collider on the
  //      water plane fails this immediately; so does a floor that has drifted from the visual.
  //   3. WADE-THROUGH — a REAL KCC march straight across the pool (entry point → far side, through
  //      the centre). It must arrive (no invisible wall), and the capsule's feet must track the
  //      FLOOR the whole way, never rising onto the water plane and never sinking below the bottom.
  //   4. REFILL — E at the pool fills the canteen, then fills the jerrycan.
  //   5. THE WELL REFUSAL — at a WELL the canteen fills and the jerrycan does NOT, with the
  //      diegetic prompt. Run against a real well in the world when one is in range; the
  //      registry-shape assertions run unconditionally.
  //
  //   Run: npm run rig -- --scenario=pool-fill --port=5232 [--seed=1337]
  'pool-fill': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      try { ctx.sandWorms.list.length = 0; } catch {}
      try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.42);
      ctx.three.renderer.setSize(320, 200, false);
    });

    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx; const RAPIER = g.RAPIER; const THREE = g.THREE;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const fails = [];
      const notes = {};
      ctx.flags.paused = false; ctx.flags.thirdPerson = false;

      let cavep = null, caveGroup = null;
      ctx.three.scene.traverse((o) => {
        if (o.userData && o.userData.caveGenProbe) cavep = o.userData.caveGenProbe;
        if (o.name === 'caveGen') caveGroup = o;
      });
      if (!cavep || !caveGroup) return { fails: ['no caveGenProbe / caveGen group (cave not built — flag off?)'] };

      // ── 1. EXISTENCE ───────────────────────────────────────────────────────
      const pools = cavep.pools || [];
      notes.poolCount = pools.length;
      // The one cost this feature adds to the ATOMIC dress stage (cycle-5 hitch budget): measured.
      notes.msPoolSampler = cavep.msPoolSampler;
      notes.pools = pools.map((p) => `n${p.node}@(${p.x.toFixed(1)},${p.y.toFixed(2)},${p.z.toFixed(1)})r${p.r.toFixed(1)}`);
      if (!pools.length) return { fails: ['origin cave has NO water pools (the cycle-6 guarantee is ≥1)'], notes };

      // ── 1a. THE SHADER-ANCHOR GUARD (round-13 fix 6a). `applyPoolShader` injects at nine three
      //     chunk names; `String.replace` is SILENT on a miss, so a renamed chunk on a three upgrade
      //     would leave a surface that still draws but has (say) no waterline discard or no ripple
      //     normal — and every other assertion in this file would stay green on it. The builder now
      //     records a match flag per material; the gate reads it.
      //     Also: EVERY cave gets its own material instance (the emitter uniforms are per-cave), so
      //     the pool meshes must NOT all share one module-level material.
      {
        const mats = [];
        ctx.three.scene.traverse((o) => { if (o.isMesh && o.name === 'cavePoolWater' && mats.indexOf(o.material) < 0) mats.push(o.material); });
        notes.poolMaterials = mats.length;
        notes.poolShaderAnchors = mats.map((mm) => mm.userData.poolShaderAnchorsOk);
        for (const mm of mats) {
          if (mm.userData.poolShaderAnchorsOk !== true) {
            fails.push(`pool water shader ANCHOR MISS: ${JSON.stringify(mm.userData.poolShaderMisses || [])} — three's chunk names moved and the surface is no longer the one this feature gates`);
          }
          if (!mm.userData.poolShaders || !mm.userData.poolShaders.length) {
            fails.push('pool water material exposes no compiled shader refs — the ripple clock has nothing to write to (updateCavePoolWater is a no-op)');
          }
        }
        // One material for the ONE resident cave here. More than one ⇒ a stray instance; zero ⇒ the
        // meshes are not using a registered pool material at all.
        if (mats.length !== 1) fails.push(`expected exactly 1 per-cave pool material in a single-cave world, found ${mats.length}`);
      }

      // The registry must carry one 'pool' source per placed pool, all with the large-vessel rule
      // set the right way round — and every well must have it set the other way.
      const srcPools = ctx.waterSources.list.filter((w) => w.kind === 'pool');
      const srcWells = ctx.waterSources.list.filter((w) => w.kind === 'well');
      notes.sources = { pools: srcPools.length, wells: srcWells.length };
      if (srcPools.length !== pools.length) fails.push(`waterSources has ${srcPools.length} pool sources for ${pools.length} placed pools`);
      for (const w of srcPools) {
        if (w.noun !== 'pool') fails.push(`pool source ${w.id} noun="${w.noun}" (expected "pool")`);
        if (w.deepEnoughForLargeVessel !== true) fails.push(`pool source ${w.id} is not deep enough for a large vessel`);
      }
      for (const w of srcWells) {
        if (w.noun !== 'well') fails.push(`well source ${w.id} noun="${w.noun}" (expected "well")`);
        if (w.deepEnoughForLargeVessel !== false) fails.push(`well source ${w.id} claims a jerrycan fits — a well must refuse`);
      }

      // ── 2. RULE 9 — the water has NO collider; the visible bottom IS the collider ──────────
      const P = pools[0];
      const node = cavep.nodes.find((n) => n.id === P.node);
      const floorY = node ? node.y : P.y - 0.26;
      const phys = g.castDown(P.x, P.z, P.y + 1.5, true);
      if (!phys) fails.push(`no physics floor under pool centre (${P.x.toFixed(1)},${P.z.toFixed(1)})`);
      const rc = new THREE.Raycaster();
      rc.far = 40;
      rc.set(new THREE.Vector3(P.x, P.y + 1.5, P.z), new THREE.Vector3(0, -1, 0));
      caveGroup.updateMatrixWorld(true);
      const hits = rc.intersectObject(caveGroup, true);
      const waterHit = hits.find((h) => h.object.userData && h.object.userData.cavePool);
      const rockHit = hits.find((h) => !(h.object.userData && h.object.userData.cavePool));
      notes.rule9 = {
        physFloorY: phys ? +phys.hitY.toFixed(3) : null,
        visWaterY: waterHit ? +waterHit.point.y.toFixed(3) : null,
        visRockY: rockHit ? +rockHit.point.y.toFixed(3) : null,
        graphFloorY: +floorY.toFixed(3),
      };
      if (!waterHit) fails.push('the water surface is not visible from directly above the pool centre');
      if (!rockHit) fails.push('no VISIBLE rock bottom under the water surface (you would see the void through it)');
      if (phys && waterHit && Math.abs(phys.hitY - waterHit.point.y) < 0.02) {
        fails.push(`RULE 9: the physics floor coincides with the WATER PLANE at y=${phys.hitY.toFixed(3)} — the water has a collider`);
      }
      if (phys && rockHit) {
        const d = Math.abs(phys.hitY - rockHit.point.y);
        notes.rule9.deltaVisibleVsCollider = +d.toFixed(4);
        if (d > 0.05) fails.push(`RULE 9: collider floor y=${phys.hitY.toFixed(3)} vs VISIBLE bottom y=${rockHit.point.y.toFixed(3)} — Δ${d.toFixed(3)}m > 0.05m`);
      }
      if (phys && waterHit) {
        const depth = waterHit.point.y - phys.hitY;
        notes.rule9.depthM = +depth.toFixed(3);
        if (depth <= 0.02) fails.push(`pool depth ${depth.toFixed(3)}m — the water is at or below the floor (not a pool)`);
        if (depth > 0.40) fails.push(`pool depth ${depth.toFixed(3)}m > 0.40m — deeper than the walkable-only decision allows`);
      }

      // ── 3. WADE-THROUGH — a real KCC crossing of the pool ─────────────────────────────────
      const body = ctx.player.body.body;
      const CAP = ctx.player.body.halfHeight + ctx.player.body.radius;
      const at = () => { const t = body.translation(); return { x: t.x, y: t.y, z: t.z }; };
      const face = (dx, dz) => {
        const cam = ctx.three.camera; const t = body.translation();
        const L = Math.hypot(dx, dz) || 1;
        cam.position.set(t.x, t.y + ctx.player.eyeOffset, t.z);
        cam.lookAt(t.x + dx / L, t.y + ctx.player.eyeOffset, t.z + dz / L);
        cam.updateMatrixWorld(true);
      };
      const placeAt = async (wx, wy, wz) => {
        body.setTranslation({ x: wx, y: wy + CAP + 0.2, z: wz }, true);
        body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        ctx.player.velocityY = 0;
        await frames(40);
      };
      // Pick a crossing DIAMETER whose two ends both stand on real cave floor. Staging the wade on a
      // fixed bearing once teleported the capsule into solid rock outside the chamber (it fell 33m
      // and the gate blamed the pool) — so the ends are chosen by castDown, not assumed. This also
      // means the "no invisible wall" result is about the WATER, never about the staging.
      const span = P.r + 1.6;
      const floorOk = (x, z) => {
        const h = g.castDown(x, z, P.y + 3.0, true);
        return h && Math.abs(h.hitY - floorY) < 1.5;
      };
      let ax = 0, az = 0, startX = 0, startZ = 0, endX = 0, endZ = 0, staged = false;
      for (let b = 0; b < 24 && !staged; b++) {
        const a = (b / 24) * Math.PI * 2;
        const ux = Math.cos(a), uz = Math.sin(a);
        const sx = P.x - ux * span, sz = P.z - uz * span;
        const ex = P.x + ux * span, ez = P.z + uz * span;
        if (floorOk(sx, sz) && floorOk(ex, ez)) {
          ax = ux; az = uz; startX = sx; startZ = sz; endX = ex; endZ = ez; staged = true;
        }
      }
      if (!staged) {
        fails.push(`no diameter across pool 0 has real cave floor at BOTH ends (r=${P.r.toFixed(1)}) — the pool does not sit on open walkable floor`);
        return { fails, notes, seed: ctx.seed, digest: cavep.digest };
      }
      await placeAt(startX, floorY, startZ);

      let minFeet = Infinity, maxFeet = -Infinity, insideSamples = 0, aboveWater = 0;
      let arrived = false, best = Infinity, stall = 0;
      ctx.input.keys['KeyW'] = true;
      for (let i = 0; i < 900; i++) {
        const p = at();
        const dx = endX - p.x, dz = endZ - p.z;
        const dist = Math.hypot(dx, dz);
        face(dx, dz);
        await raf();
        const q = at();
        const feet = q.y - CAP;
        const dc = Math.hypot(q.x - P.x, q.z - P.z);
        if (dc < P.r * 0.8) {                 // sampling only well INSIDE the pool footprint
          insideSamples++;
          if (feet < minFeet) minFeet = feet;
          if (feet > maxFeet) maxFeet = feet;
          if (feet > P.y + 0.05) aboveWater++;   // standing ON the water plane = an invisible floor
        }
        if (dist < 1.2) { arrived = true; break; }
        if (dist < best - 0.03) { best = dist; stall = 0; } else if (++stall > 160) break;
      }
      ctx.input.keys['KeyW'] = false;
      const endP = at();
      notes.wade = {
        from: [+startX.toFixed(1), +startZ.toFixed(1)], to: [+endX.toFixed(1), +endZ.toFixed(1)],
        ended: [+endP.x.toFixed(1), +endP.z.toFixed(1)],
        arrived, insideSamples,
        feetMin: insideSamples ? +minFeet.toFixed(3) : null,
        feetMax: insideSamples ? +maxFeet.toFixed(3) : null,
        floorY: +floorY.toFixed(3), waterY: +P.y.toFixed(3),
        framesStandingOnWater: aboveWater,
      };
      if (!arrived) fails.push(`wade: could not cross the pool — stalled at (${endP.x.toFixed(1)},${endP.z.toFixed(1)}), target (${endX.toFixed(1)},${endZ.toFixed(1)}) [invisible wall?]`);
      if (insideSamples < 3) fails.push(`wade: only ${insideSamples} samples inside the pool footprint — the crossing did not go through the water`);
      if (aboveWater > 0) fails.push(`wade: ${aboveWater} frames with the feet ABOVE the water plane — something is colliding with the surface`);
      if (insideSamples >= 3 && minFeet < floorY - 0.45) fails.push(`wade: feet sank to y=${minFeet.toFixed(2)}, ${(floorY - minFeet).toFixed(2)}m below the pool floor y=${floorY.toFixed(2)}`);

      // ── 4. REFILL at the pool ─────────────────────────────────────────────────────────────
      const src = ctx.waterSources.list.find((w) => w.kind === 'pool' && Math.hypot(w.pos.x - P.x, w.pos.z - P.z) < 0.5)
        || ctx.waterSources.list.find((w) => w.kind === 'pool');
      ctx.inventory.slots[0] = { item: 'canteen', count: 1, meta: { fillLevel: 0.1 } };
      ctx.inventory.slots[1] = { item: 'jerrycan', count: 1, meta: { fillLevel: 0 } };
      ctx.inventory.selectedIdx = 0;
      // Stand at the pool rim and look down into the water — a real player's aim, a real E press.
      await placeAt(P.x - ax * (P.r * 0.55), floorY, P.z - az * (P.r * 0.55));
      // Aim at a point and press E. Returns the FIRST prompt noun seen — the state the player was
      // actually looking at when they pressed, not the "already full" prompt the fill itself causes.
      const aimAndPress = async (tx, ty, tz, tries) => {
        let noun = null;
        for (let i = 0; i < tries; i++) {
          const cam = ctx.three.camera; const t = body.translation();
          cam.position.set(t.x, t.y + ctx.player.eyeOffset, t.z);
          cam.lookAt(tx, ty, tz);
          cam.updateMatrixWorld(true);
          ctx.input.pressed.add('KeyE');
          await raf();
          if (noun === null && ctx.inventory.hover) noun = ctx.inventory.hover.promptNoun;
          await raf();
        }
        return noun;
      };
      const poolNoun = await aimAndPress(P.x + ax * (P.r * 0.15), P.y, P.z + az * (P.r * 0.15), 8);
      const canteenAfterPool = ctx.inventory.slots[0].meta.fillLevel;
      // Now the canteen is full, so the SAME press must move on to the jerrycan.
      await aimAndPress(P.x + ax * (P.r * 0.15), P.y, P.z + az * (P.r * 0.15), 8);
      const jerryAfterPool = ctx.inventory.slots[1].meta.fillLevel;
      notes.poolRefill = { promptNoun: poolNoun, canteen: canteenAfterPool, jerrycan: jerryAfterPool };
      if (poolNoun !== 'pool') fails.push(`pool prompt noun was "${poolNoun}" (expected "pool")`);
      if (canteenAfterPool < 0.999) fails.push(`canteen did not fill at the pool (fillLevel ${canteenAfterPool})`);
      if (jerryAfterPool < 0.999) fails.push(`jerrycan did not fill at the pool (fillLevel ${jerryAfterPool})`);

      // ── 4b. THE NEGATIVE ASSERTION — NO REFILL OVER DRY ROCK (round-12 code critique, sev-2).
      //     The water mesh reaches CAVE_POOL_SHORE_M + the outer ring schedule PAST the rim (~1.1m of
      //     skirt), and it is the FRAGMENT SHADER that decides most of that skirt is not water: it
      //     discards where the measured depth reaches zero. `interaction.ts` raycasts meshes, not
      //     fragments, so before this fix the "[E] refill" prompt was live up to ~1.6m out, standing
      //     on visibly dry rock. A gate that only ever checks that refill WORKS cannot see that — so
      //     this leg checks that it correctly REFUSES.
      //
      //     ── ROUND-13, sev-2: THE OLD VERSION OF THIS LEG WAS TAUTOLOGICAL. It found "the visible
      //     waterline" by marching `mesh.userData.poolWaterDepthAt` — the very closure the raycast
      //     override rejects on — and then asserted that the raycast rejects outside it. The outer
      //     probes could not fail for any value of anything: CPU tested against its own predicate.
      //     Anchor the waterline in GPU TRUTH instead. An ORTHOGRAPHIC top-down pose over the pool
      //     is rendered TWICE (water visible / water hidden) and the ≥2/255 appearance mask of the
      //     difference is the pixels the water actually draws — the shader's own `discard` included,
      //     which is the thing no CPU-side check can see. Unprojecting the mask's outer edge along 8
      //     bearings gives `gpuEdge`, a waterline measured from the rendered image. Then:
      //       · |cpuEdge − gpuEdge| ≤ TOL  — the CPU twin tracks the GPU (this is also the honest
      //         measurement of the float32/interpolation residual; see cavePools.ts `waterDepthAt`),
      //       · a raycast at gpuEdge + PHANTOM must MISS — no [E] prompt on dry rock, anchored on
      //         the rendered waterline rather than on the predicate under test,
      //       · a raycast well inside gpuEdge must HIT on ≥6/8 bearings — so the fix can never be
      //         "reject everything".
      //     Two temporary pokes make the measurement honest, both restored: the damp collar is
      //     switched off (uPoolWetBand→0) so the mask edge IS the waterline and not the collar's
      //     outer edge 0.30m further out, and a bright lamp is added so the water's effect on the
      //     rock clears 2/255 (in shipping cave darkness both renders are black and there is no
      //     mask at all). Neither changes geometry; this is a measurement pose, not a look shot.
      {
        // TOLERANCE — MEASURED, not chosen. The CPU twin and the GPU cannot agree exactly: the GPU
        // reads `vPoolD`, the barycentric interpolation of per-vertex depth, while the CPU samples
        // the floor exactly at the query point, and over the ~0.11 m/m shore gradient a couple of cm
        // of depth disagreement is decimetres of lateral waterline.
        //   MEASURED, 8 bearings, this pose:
        //     seed 1337  float64 twin (pre-round-13):      meanAbs 0.148m, maxAbs 0.380m
        //     seed 1337  float32-faithful twin (shipping): meanAbs 0.135m, maxAbs 0.360m
        //     seed 7     float32-faithful twin (shipping): meanAbs 0.168m, maxAbs 0.460m
        //   i.e. making the hash fround-faithful is a real but SMALL improvement (~1-2cm), because
        //   the dominant term is the interpolation, not the precision. That is the honest budget —
        //   and it is three orders of magnitude off the "~1e-4 m" the old cavePools.ts comment
        //   claimed. TOL = worst measured (0.46, seed 7) + ~50% margin. TIGHTENING THIS MEANS
        //   TESSELLATING THE MESH FINER, not lowering the number: the residual is set by
        //   CAVE_POOL_EDGE_SEGS and the OUTER ring schedule. `annulusDev` is printed every run, so a
        //   retune of the shore gradient or the ring schedule shows up here first.
        const TOL = 0.70;
        // The separate phantom probe sits just past tolerance, NOT at a fixed large offset: the mesh
        // only reaches ~1.10m past the (wobbled) rim, so a probe at gpuEdge+1.10 fell OFF the
        // geometry on the wider bearings and could not fail for any value of anything — the exact
        // vacuity this leg was rewritten to remove. It is also cross-checked against the STOCK
        // raycast, so a probe that lands on no triangle is REPORTED as uninformative rather than
        // counted as a pass.
        const PHANTOM = TOL + 0.15;
        const src0 = ctx.waterSources.list
          .filter((w) => w.kind === 'pool' && w.mesh && w.mesh.userData.poolWaterDepthAt)
          .sort((a, b) => Math.hypot(a.pos.x - P.x, a.pos.z - P.z) - Math.hypot(b.pos.x - P.x, b.pos.z - P.z))[0];
        if (!src0) {
          fails.push('no pool mesh exposes poolWaterDepthAt — the raycast can no longer be checked against the shader waterline');
        } else {
          const legT0 = performance.now();
          const mesh = src0.mesh, depthAt = mesh.userData.poolWaterDepthAt;
          const R = ctx.three.renderer, gl = R.getContext();
          const saveW = R.domElement.width, saveH = R.domElement.height;
          R.setSize(900, 900, false);
          const W = R.domElement.width, H = R.domElement.height;
          // Ortho so world→screen is exact and height-independent (a perspective pose would make the
          // unprojection depend on the assumed water height, which is the thing under test).
          const S = P.r + 2.2;
          const oc = new THREE.OrthographicCamera(-S, S, S, -S, 0.05, 6);
          oc.position.set(P.x, P.y + 1.6, P.z);
          oc.up.set(0, 0, -1);
          oc.lookAt(P.x, P.y, P.z);
          oc.updateProjectionMatrix(); oc.updateMatrixWorld(true);
          const lamp = new THREE.PointLight(0xffffff, 40, 14, 1.4);
          lamp.position.set(P.x, P.y + 1.5, P.z);
          ctx.three.scene.add(lamp);
          // Collar OFF, so the ≥2/255 mask ends at the waterline and not 0.30m past it.
          const shaders = (mesh.material.userData && mesh.material.userData.poolShaders) || [];
          const savedBand = shaders.map((s) => (s.uniforms.uPoolWetBand ? s.uniforms.uPoolWetBand.value : null));
          for (const s of shaders) if (s.uniforms.uPoolWetBand) s.uniforms.uPoolWetBand.value = 0.0001;
          notes.annulusShaders = shaders.length;

          const read = () => { R.render(ctx.three.scene, oc); const px = new Uint8Array(W * H * 4); gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px); return px; };
          const waters = []; ctx.three.scene.traverse((o) => { if (o.isMesh && o.name === 'cavePoolWater' && o.visible) waters.push(o); });
          const on = read();
          for (const o of waters) o.visible = false;
          const off = read();
          for (const o of waters) o.visible = true;
          const mask = new Uint8Array(W * H);
          let maskN = 0;
          for (let i = 0, k = 0; k < W * H; k++, i += 4) {
            const dm = Math.max(Math.abs(on[i] - off[i]), Math.abs(on[i + 1] - off[i + 1]), Math.abs(on[i + 2] - off[i + 2]));
            if (dm >= 2) { mask[k] = 1; maskN++; }
          }
          // restore the pokes immediately — everything below is CPU-side
          for (let i = 0; i < shaders.length; i++) if (savedBand[i] !== null) shaders[i].uniforms.uPoolWetBand.value = savedBand[i];
          ctx.three.scene.remove(lamp);
          R.setSize(saveW, saveH, false);

          const vtmp = new THREE.Vector3();
          // 3×3 MAJORITY (≥5/9) so a stray speckle cannot invent a waterline 2m out.
          const inMask = (x, z) => {
            vtmp.set(x, P.y, z).project(oc);
            const cx = Math.floor((vtmp.x * 0.5 + 0.5) * W), cy = Math.floor((vtmp.y * 0.5 + 0.5) * H);
            if (cx < 1 || cy < 1 || cx >= W - 1 || cy >= H - 1) return false;
            let n = 0;
            for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) if (mask[(cy + dy) * W + (cx + dx)]) n++;
            return n >= 5;
          };
          const rc = new THREE.Raycaster(); rc.far = 60;
          const down = new THREE.Vector3(0, -1, 0);
          const hitsAt = (x, z) => { rc.set(new THREE.Vector3(x, src0.pos.y + 3, z), down); const h = []; mesh.raycast(rc, h); return h.length; };
          // The UNCLAMPED raycast — i.e. does the mesh have geometry here at all? Used to tell a
          // genuine "the clamp rejected it" from an uninformative "there was nothing to reject".
          const stockHitsAt = (x, z) => { rc.set(new THREE.Vector3(x, src0.pos.y + 3, z), down); const h = []; THREE.Mesh.prototype.raycast.call(mesh, rc, h); return h.length; };

          const rows = []; const devs = [];
          for (let b = 0; b < 8; b++) {
            const ang = (b / 8) * Math.PI * 2 + 0.31;
            const ux = Math.cos(ang), uz = Math.sin(ang);
            let cpuEdge = -1, gpuEdge = -1;
            for (let r = 0.1; r < P.r + 2.2; r += 0.02) {
              const x = P.x + ux * r, z = P.z + uz * r;
              if (depthAt(x, z) > 0) cpuEdge = r;
              if (inMask(x, z)) gpuEdge = r;
            }
            if (gpuEdge < 0) { rows.push({ b, gpu: null, cpu: cpuEdge < 0 ? null : +cpuEdge.toFixed(2), note: 'no GPU water on this bearing (occluded from above?)' }); continue; }
            if (cpuEdge < 0) { rows.push({ b, gpu: +gpuEdge.toFixed(2), cpu: null }); fails.push(`refill annulus: bearing ${b} renders water out to r=${gpuEdge.toFixed(2)}m but the CPU predicate finds NONE — the [E] prompt is dead over visible water`); continue; }
            const dev = cpuEdge - gpuEdge;
            devs.push(dev);
            const inn = hitsAt(P.x + ux * (gpuEdge * 0.6), P.z + uz * (gpuEdge * 0.6));
            const ox = P.x + ux * (gpuEdge + PHANTOM), oz = P.z + uz * (gpuEdge + PHANTOM);
            const out = hitsAt(ox, oz), outStock = stockHitsAt(ox, oz);
            rows.push({ b, gpu: +gpuEdge.toFixed(2), cpu: +cpuEdge.toFixed(2), dev: +dev.toFixed(3), inn, out, outStock });
            if (Math.abs(dev) > TOL) fails.push(`refill annulus: on bearing ${b} the CPU waterline (r=${cpuEdge.toFixed(2)}m) is ${dev >= 0 ? '' : '-'}${Math.abs(dev).toFixed(2)}m from the RENDERED waterline (r=${gpuEdge.toFixed(2)}m) — over the ${TOL}m twin tolerance`);
            if (out > 0) fails.push(`refill annulus: the water mesh still raycast-hits ${PHANTOM.toFixed(2)}m OUTSIDE its RENDERED waterline on bearing ${b} (r=${(gpuEdge + PHANTOM).toFixed(2)}m) — the [E] prompt would fire on dry rock`);
          }
          const innerOk = rows.filter((r) => r.inn > 0).length;
          const valid = rows.filter((r) => r.gpu !== null).length;
          // The phantom probe is only evidence where the mesh actually has geometry. If it lands off
          // the mesh on EVERY bearing the check proved nothing, and the run must say so out loud
          // rather than bank a green — the `dev ≤ TOL` assertion above is then the only anti-phantom
          // teeth, which is the honest state of affairs and needs to be visible.
          const outInformative = rows.filter((r) => r.outStock > 0).length;
          if (valid >= 6 && outInformative === 0) console.log(`[pool-fill] NOTE: the phantom probe landed off the water mesh on all ${valid} bearings (gpuEdge + ${PHANTOM.toFixed(2)}m is past the skirt) — anti-phantom rests on the dev≤TOL assertion this run`);
          if (valid < 6) fails.push(`refill annulus: only ${valid}/8 bearings produced a rendered waterline (mask ${maskN}px) — the top-down measurement pose is occluded or unlit`);
          if (innerOk < 6) fails.push(`refill annulus: only ${innerOk}/8 bearings raycast-hit water WELL INSIDE the rendered waterline — the raycast clamp is eating real water`);
          const adev = devs.map(Math.abs);
          notes.annulus = rows;
          notes.annulusDev = devs.length
            ? { n: devs.length, meanAbs: +(adev.reduce((a, c) => a + c, 0) / adev.length).toFixed(3), maxAbs: +Math.max(...adev).toFixed(3), tol: TOL, maskPx: maskN, ms: +(performance.now() - legT0).toFixed(0) }
            : { n: 0, maskPx: maskN, ms: +(performance.now() - legT0).toFixed(0) };
        }
      }

      // ── 4c. THE DARK SHARD (round-12 visual critique, sev-2). The r11 refill frame carried a
      //     4-6px, ~50%-darkening, stair-stepped near-vertical sliver lying across the water at
      //     ~(850,469)-(866,554). Per the project's z-fight rule: NAME IT before touching it. From
      //     the refill camera pose, list every object within 3m of the eye whose bounding box is
      //     thinner than 12cm in any axis — a thin unlit thing between the eye and the lit water.
      {
        // The HERO pool is the LARGEST one (that is what poolShotSet frames), not pools[0].
        const HP = pools.slice().sort((a, b) => b.r - a.r)[0];
        const hn = cavep.nodes.find((x) => x.id === HP.node) || { x: HP.x, z: HP.z, y: HP.y - 0.26 };
        let hx = hn.x - HP.x, hz = hn.z - HP.z; const HL = Math.hypot(hx, hz) || 1; hx /= HL; hz /= HL;
        const hFloor = hn.y;
        const cam = ctx.three.camera;
        const eye = new THREE.Vector3(HP.x + hx * (HP.r * 0.92), hFloor + 1.68, HP.z + hz * (HP.r * 0.92));
        const tgt = new THREE.Vector3(HP.x + hx * (HP.r * 0.92 - 0.42), HP.y - 0.02, HP.z + hz * (HP.r * 0.92 - 0.42));
        const R = ctx.three.renderer, gl = R.getContext();
        const W = R.domElement.width, H = R.domElement.height;
        const saveP = cam.position.clone(), saveQ = cam.quaternion.clone();
        cam.position.copy(eye); cam.lookAt(tgt); cam.updateMatrixWorld(true);
        R.render(ctx.three.scene, cam);
        const px = new Uint8Array(W * H * 4); gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px);
        const L = (x, y) => { const i = (((H - 1 - y) * W) + x) * 4; return 0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2]; };
        // The signature: a narrow dark NOTCH flanked by brighter pixels 4-6px either side.
        const notches = [];
        for (let y = 120; y < H - 120; y += 2) {
          for (let x = 60; x < W - 60; x++) {
            const c = L(x, y);
            const l = Math.max(L(x - 6, y), L(x - 5, y), L(x - 4, y));
            const r2 = Math.max(L(x + 4, y), L(x + 5, y), L(x + 6, y));
            const mn = Math.min(l, r2);
            if (mn > 4 && c < mn * 0.62) notches.push({ x, y, c: +c.toFixed(1), flank: +mn.toFixed(1) });
          }
        }
        notes.shardNotchPx = notches.length;
        // Name the darkest one: unproject it and raycast EVERYTHING.
        if (notches.length) {
          notches.sort((a, b) => (a.c / a.flank) - (b.c / b.flank));
          const q = notches[0];
          const ndc = new THREE.Vector3((q.x / W) * 2 - 1, -((q.y / H) * 2 - 1), 0.5);
          const rc2 = new THREE.Raycaster(); rc2.setFromCamera(ndc, cam); rc2.far = 40;
          const all = []; ctx.three.scene.traverse((o) => { if (o.isMesh && o.visible) all.push(o); });
          const hits = rc2.intersectObjects(all, false).slice(0, 5);
          notes.shardWorst = q;
          notes.shardHits = hits.map((h) => ({ name: h.object.name || h.object.type, d: +h.distance.toFixed(3), p: [+h.point.x.toFixed(2), +h.point.y.toFixed(3), +h.point.z.toFixed(2)] }));
        }
        cam.position.copy(saveP); cam.quaternion.copy(saveQ); cam.updateMatrixWorld(true);
      }

      // ── 5. THE WELL REFUSAL ───────────────────────────────────────────────────────────────
      // The proof chain is deliberately in two halves, because teleporting a kilometre to a real
      // well drags in chunk streaming and would make this gate flaky rather than strict:
      //   (a) the REGISTRY assertions above already prove every well has deepEnoughForLargeVessel
      //       === false, and
      //   (b) this leg proves that a source with that field false FILLS THE CANTEEN and REFUSES
      //       THE JERRYCAN, diegetically — run at the pool with the field temporarily flipped, so
      //       it drives the exact interaction branch a well drives.
      // (a) + (b) ⇒ wells refuse jerrycans, deterministically, with no teleport.
      ctx.inventory.slots[0].meta.fillLevel = 0.1;
      ctx.inventory.slots[1].meta.fillLevel = 0;
      src.deepEnoughForLargeVessel = false;                 // stand in a well's shoes
      const aimPt = [P.x + ax * (P.r * 0.15), P.y, P.z + az * (P.r * 0.15)];
      const shallowNoun1 = await aimAndPress(aimPt[0], aimPt[1], aimPt[2], 8);
      const canteenShallow = ctx.inventory.slots[0].meta.fillLevel;
      const shallowNoun2 = await aimAndPress(aimPt[0], aimPt[1], aimPt[2], 8);
      const jerryShallow = ctx.inventory.slots[1].meta.fillLevel;
      src.deepEnoughForLargeVessel = true;                  // restore
      notes.shallowRule = { noun1: shallowNoun1, noun2: shallowNoun2, canteen: canteenShallow, jerrycan: jerryShallow };
      if (canteenShallow < 0.999) fails.push(`a shallow source did not fill the CANTEEN (fillLevel ${canteenShallow}) — the well flow regressed`);
      if (jerryShallow > 0.001) fails.push(`a shallow source FILLED THE JERRYCAN (fillLevel ${jerryShallow}) — the volume rule is broken`);
      if (canteenShallow >= 0.999 && !(shallowNoun2 || '').includes('too shallow')) {
        fails.push(`the shallow-source refusal is SILENT — prompt was "${shallowNoun2}", expected it to say why`);
      }

      // Bonus teeth when a REAL well is close enough to stage without a cross-world teleport: run
      // the same two presses at actual well geometry. Skipped (reported, not failed) when the well
      // is far away — the deterministic leg above is what the gate stands on.
      let well = null, wellD = Infinity;
      const here = at();
      for (const w of srcWells) {
        const d = Math.hypot(w.pos.x - here.x, w.pos.z - here.z);
        if (d < wellD) { wellD = d; well = w; }
      }
      if (!well) {
        notes.realWell = 'no well in the world';
      } else {
        ctx.inventory.slots[0].meta.fillLevel = 0.1;
        ctx.inventory.slots[1].meta.fillLevel = 0;
        // Land ON the streamed ground next to the well: drop in high, let the chunks build, then
        // re-seat on whatever the physics floor turned out to be.
        const wx = well.pos.x + 1.7, wz = well.pos.z;
        body.setTranslation({ x: wx, y: ctx.terrain.heightAt(wx, wz) + 4, z: wz }, true);
        body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        await frames(90);
        const gh = g.castDown(wx, wz, well.pos.y + 8, true);
        if (gh) await placeAt(wx, gh.hitY, wz);
        const settled = at();
        const dOff = Math.hypot(settled.x - well.pos.x, settled.z - well.pos.z);
        const staged2 = dOff < 4 && Math.abs(settled.y - (gh ? gh.hitY : settled.y)) < 3;
        if (!staged2) {
          notes.realWell = { dist: +wellD.toFixed(0), staged: false, endedAt: [+settled.x.toFixed(1), +settled.y.toFixed(1), +settled.z.toFixed(1)] };
        } else {
          const box = new THREE.Box3().setFromObject(well.mesh);
          const c = box.getCenter(new THREE.Vector3());
          const n1 = await aimAndPress(c.x, box.max.y - 0.15, c.z, 12);
          const canteenAtWell = ctx.inventory.slots[0].meta.fillLevel;
          const n2 = await aimAndPress(c.x, box.max.y - 0.15, c.z, 12);
          const jerryAtWell = ctx.inventory.slots[1].meta.fillLevel;
          notes.realWell = { dist: +wellD.toFixed(0), staged: true, noun1: n1, noun2: n2, canteen: canteenAtWell, jerrycan: jerryAtWell };
          if (n1 === null) {
            notes.realWell.staged = 'no-hover';        // stood in the right place but never resolved the mesh
          } else {
            if (n1 !== 'well') fails.push(`well prompt noun was "${n1}" (expected "well")`);
            if (canteenAtWell < 0.999) fails.push(`canteen did not fill at the REAL well (fillLevel ${canteenAtWell})`);
            if (jerryAtWell > 0.001) fails.push(`JERRYCAN FILLED AT A REAL WELL (fillLevel ${jerryAtWell})`);
          }
        }
      }

      return { fails, notes, seed: ctx.seed, digest: cavep.digest };
    });

    // ── 1b. DETERMINISM ×2 — re-run the PURE placement for this seed and diff it against the
    //    probe's pool list. Cheap (no second cave build) and it fails on any hidden Math.random.
    const det = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      let cavep = null;
      ctx.three.scene.traverse((o) => { if (o.userData && o.userData.caveGenProbe) cavep = o.userData.caveGenProbe; });
      const caveGen = await import('/src/world/caveGen.ts');
      const seed = cavep.seed;
      const runs = [];
      let layout = null;
      for (let k = 0; k < 2; k++) {
        layout = caveGen.cavePoolLayout(seed, cavep.junction, ctx.terrain);
        runs.push(layout
          .map((p) => `${p.nodeId}:${p.x.toFixed(4)}:${p.z.toFixed(4)}:${p.waterY.toFixed(4)}:${p.radius.toFixed(4)}`).join('|'));
      }
      // ⚠ COMPARE NUMBERS, NOT FORMATTED STRINGS. Until cycle 7 this diffed the live list stringified
      // at 3dp against the rebuilt list stringified at 4dp AND THEN RE-ROUNDED to 3dp — a double
      // rounding, so any coordinate whose 4th/5th decimals landed near a …x5 boundary reported a
      // "determinism" failure of exactly one unit in the last printed digit. It fired the moment this
      // cycle's entrance work moved a pool by a few centimetres (seed 1337: -101.824 vs -101.825).
      // That is the project's own named failure mode — a gate that measures the wrong thing — so it
      // is fixed rather than tolerated: elementwise on the RAW floats, 0.1mm, node ids must match.
      const livePools = (cavep.pools || []);
      // 5mm. The live junction reaches this comparison through the probe's userData (rounded on the
      // way), so a pure re-derivation from it lands sub-millimetre away from the live layout — 4e-4m
      // on seed 7 — with nothing wrong. The teeth this check actually has are `stable ×2` (any hidden
      // Math.random) and gross placement drift: a real RNG or rule change moves a pool by METRES.
      const EPS = 5e-3;
      let matchesLive = layout.length === livePools.length;
      const diffs = [];
      for (let i = 0; matchesLive && i < layout.length; i++) {
        const a = layout[i], b = livePools[i];
        const dx = Math.abs(a.x - b.x), dz = Math.abs(a.z - b.z);
        if (a.nodeId !== b.node || dx > EPS || dz > EPS) {
          matchesLive = false;
          diffs.push(`#${i} n${a.nodeId}/n${b.node} dx=${dx.toExponential(2)} dz=${dz.toExponential(2)}`);
        }
      }
      const live = livePools.map((p) => `${p.node}:${p.x.toFixed(3)}:${p.z.toFixed(3)}`).join('|');
      const rebuilt = layout.map((p) => `${p.nodeId}:${p.x.toFixed(3)}:${p.z.toFixed(3)}`).join('|');
      return { stable: runs[0] === runs[1], matchesLive, diffs, a: runs[0], b: runs[1], live, rebuilt };
    }).catch((e) => ({ error: String(e && e.message || e) }));

    // ── 6. THE PER-CAVE EMITTER ISOLATION PROOF (round-13 fix 1) ──────────────────────────────
    //    THE BUG: `uPoolEmit` held the cave's mirrored fungi, and it lived in module-global arrays
    //    bound into ONE shared material. `setCavePoolEmitters` overwrote all 8 slots at every cave
    //    build, and CAVE_RESIDENT_MAX is 3 — so streaming a second cave into range stripped the
    //    reflections out of the cave the player was STANDING IN. Now each cave owns its material.
    //    The proof does not need two real caves (an SDF build is seconds): it drives the module's
    //    own exports. Snapshot the LIVE cave's slots, build a SECOND cave's material and publish a
    //    deliberately different emitter set into it, then re-read the live cave's slots. Under the
    //    old module-global code the live cave's slots would now be cave B's; they must be unchanged.
    const iso = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const cp = await import('/src/world/cavePools.ts');
      let liveMat = null;
      ctx.three.scene.traverse((o) => { if (o.isMesh && o.name === 'cavePoolWater' && !liveMat) liveMat = o.material; });
      if (!liveMat) return { error: 'no live cavePoolWater mesh' };
      const before = cp.readCavePoolEmitters(liveMat);
      if (!before) return { error: 'the live pool material is not registered as a pool material' };
      const liveBefore = JSON.stringify(before);
      const mats0 = cp.cavePoolLiveMaterials();
      // Cave B: its own material, its own emitters, at coordinates nothing in cave A shares.
      const matB = cp.createCavePoolMaterial();
      const THREE = window.__game.THREE;
      const emitB = [{ x: 9000, y: 9001, z: 9002, intensity: 7.5, color: new THREE.Color(1, 0, 0) }];
      cp.setCavePoolEmitters(matB, emitB, [{ nodeId: 0, x: 9000, z: 9002, radius: 2, waterY: 9001, score: 0 }]);
      const after = cp.readCavePoolEmitters(liveMat);
      const bSlots = cp.readCavePoolEmitters(matB);
      const matsAfterCreate = cp.cavePoolLiveMaterials();
      const released = cp.releaseCavePoolMaterial(matB);
      const matsAfterRelease = cp.cavePoolLiveMaterials();
      return {
        liveBefore, liveAfter: JSON.stringify(after),
        liveNonZero: before.filter((e) => e[3] > 0).length,
        bSlot0: bSlots ? bSlots[0] : null,
        mats0, matsAfterCreate, matsAfterRelease, released,
        bStillRegistered: cp.readCavePoolEmitters(matB) !== null,
      };
    }).catch((e) => ({ error: String((e && e.message) || e) }));

    const fails = (r.fails || []).slice();
    if (det.error) fails.push(`determinism check could not run: ${det.error}`);
    else {
      if (!det.stable) fails.push(`pool placement NOT deterministic — run A "${det.a}" vs run B "${det.b}"`);
      if (!det.matchesLive) fails.push(`rebuilt pool placement differs from the LIVE cave (>0.1mm) — ${(det.diffs || []).join(", ")} | live "${det.live}" vs rebuilt "${det.rebuilt}"`);
    }
    if (iso.error) fails.push(`per-cave emitter isolation check could not run: ${iso.error}`);
    else {
      if (!iso.liveNonZero) fails.push('the live cave publishes NO mirrored emitters at all — setCavePoolEmitters never ran, or no fungi are within CAVE_POOL_GLINT_RANGE_M of water');
      if (iso.liveAfter !== iso.liveBefore) fails.push(`BUILDING A SECOND CAVE CLOBBERED THE LIVE CAVE'S MIRRORED EMITTERS — before ${iso.liveBefore} / after ${iso.liveAfter} (the module-global emitter regression)`);
      if (!iso.bSlot0 || iso.bSlot0[3] <= 0) fails.push(`the second cave's own material did not receive its emitters (slot0 ${JSON.stringify(iso.bSlot0)})`);
      if (iso.matsAfterCreate !== iso.mats0 + 1) fails.push(`creating a cave material did not register it (${iso.mats0} → ${iso.matsAfterCreate})`);
      if (!iso.released || iso.matsAfterRelease !== iso.mats0) fails.push(`releaseCavePoolMaterial did not unregister (released=${iso.released}, ${iso.matsAfterCreate} → ${iso.matsAfterRelease}) — an evicted cave would keep a live material in the ripple clock forever`);
      if (iso.bStillRegistered) fails.push('a released pool material is still registered');
    }
    console.log(`[pool-fill] emitterIsolation ${JSON.stringify(iso)}`);

    // ══ DEEPER cycle 11, GATE A — LANTERN-RT ═══════════════════════════════════════════════════
    //    The deployable lantern is the light Zach asked to keep using underground, and until this
    //    cycle placing one in a cave put it tens of metres up INSIDE SOLID ROCK — because every
    //    placeable took its Y from `terrain.heightAt`, the SURFACE sampler. The bug was invisible
    //    from the surface and permanent once saved, so this gate proves the whole round trip on the
    //    REAL paths (real LMB through items.ts, real KCC walking, real RMB pack-up, real save/load):
    //
    //      1. It lands on the CAVE FLOOR — proven by COLLIDER IDENTITY, not by a plausible number.
    //         The hit collider must belong to the cave's own rigid body. A Y that merely looks right
    //         is exactly what the old code produced on the surface; only identity separates "on the
    //         cave floor" from "on the terrain sheet forty metres overhead".
    //      2. It is actually LIT — the pool light exists, is above zero, and is at the lantern
    //         rather than parked at PARK_Y = -10000 (an unlit breadcrumb is worse than none).
    //      3. It survives a REAL KCC round trip, not a teleport (the leviathan-walk lesson:
    //         teleported waypoints lie about traversability, and they would lie about eviction too).
    //      4. RMB retrieve returns the kit, the list, AND the pool slot.
    //      5. Save/reload puts it back at the same absolute position, still lit, at SAVE_VERSION 18
    //         read from the SAVE ITSELF — so a stray version bump reds this gate.
    //      6. The cap refuses the N+1th with a reason, and the refusal is not vacuous.
    //      7. G4: a placed lantern feeds the cave-rock bounce, AND with it packed up the bounce is
    //         EXACTLY zero again — the no-free-light canary, both directions.
    const lrt = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const fails = []; const notes = {};
      // Progress marker — a throw anywhere below names the stage it died at instead of leaving the
      // next session to bisect. `wasmAlive` distinguishes "this gate broke Rapier" from "Rapier was
      // already dead when this gate started".
      notes.stage = 'init';
      const S = (n) => { notes.stage = n; };
      try { g.castDown(0, 0, 100, true); notes.wasmAlive = true; } catch (e) { notes.wasmAlive = String((e && e.message) || e); }
      try {
      ctx.flags.paused = false; ctx.flags.thirdPerson = false;

      S('probe');
      let cavep = null;
      ctx.three.scene.traverse((o) => { if (o.userData && o.userData.caveGenProbe) cavep = o.userData.caveGenProbe; });
      if (!cavep) return { fails: ['no caveGenProbe'], notes };

      // The cave's OWN rigid body → the set of collider handles that mean "this is cave rock".
      S('cave-body');
      const res = ctx.caveStream ? ctx.caveStream.residents() : [];
      const origin = res.find((r) => r.key === 'origin') || res[0];
      if (!origin || !origin.cave.body) return { fails: ['origin cave resident has no rigid body — cannot assert collider identity'], notes };
      const caveHandles = new Set();
      for (let i = 0; i < origin.cave.body.numColliders(); i++) caveHandles.add(origin.cave.body.collider(i).handle);
      notes.caveColliders = caveHandles.size;

      // Stand in the roomiest chamber that is genuinely deep (so the darkness/cold model is live).
      // CaveGenProbe nodes carry `rx` + `height` and NO `rz`. Reading `rz` yields NaN, a NaN reaches
      // `setTranslation`, and Rapier answers a NaN transform with an `unreachable` trap that poisons
      // the whole wasm module for the rest of the run — every later Rapier call then reports
      // "recursive use of an object". Use the field that exists.
      const rooms = cavep.nodes.slice().sort((a, b) => b.rx - a.rx);
      const room = rooms[0];
      const body = ctx.player.body.body;
      const CAP = ctx.player.body.halfHeight + ctx.player.body.radius;
      const at = () => { const t = body.translation(); return { x: t.x, y: t.y, z: t.z }; };
      const look = (tx, ty, tz) => {
        const cam = ctx.three.camera; const t = body.translation();
        cam.position.set(t.x, t.y + ctx.player.eyeOffset, t.z);
        cam.lookAt(tx, ty, tz); cam.updateMatrixWorld(true);
      };
      // cave-walk's `face`: aim at a point 1m ahead at EYE HEIGHT, so the flattened heading is the
      // only thing the pitch can influence. Used for walking; `look` is used for aiming at things.
      const face = (dx, dz) => {
        const cam = ctx.three.camera; const t = body.translation();
        const L = Math.hypot(dx, dz) || 1;
        cam.position.set(t.x, t.y + ctx.player.eyeOffset, t.z);
        cam.lookAt(t.x + dx / L, t.y + ctx.player.eyeOffset, t.z + dz / L);
        cam.updateMatrixWorld(true);
      };
      const placeAt = async (wx, wy, wz) => {
        body.setTranslation({ x: wx, y: wy + CAP + 0.2, z: wz }, true);
        body.setLinvel({ x: 0, y: 0, z: 0 }, true); ctx.player.velocityY = 0;
        await frames(30);
      };
      // WALK-TEST 2026-07-29 — STAND OFF THE CHAMBER CENTRE. The roomiest chamber is the EGG
      // chamber, and its centre is occupied by the egg dais — a 0.9m rock pedestal. This probe
      // used to teleport the capsule INTO it and only worked because the dais was a hollow shell
      // with an open top; sealing that hole (the walk-test fix for "i can see through the model")
      // left the capsule embedded in solid rock, and the round trip reported pathLen 0. The
      // probe's INTENT was always "stand in a roomy deep chamber", never "stand inside the
      // pedestal", so it now stands clear of it — a player could not stand there either.
      const standR = Math.min(room.rx * 0.62, Math.min(room.rx * 0.34, 3.4) + 1.6);
      await placeAt(room.x + standR, room.y, room.z);
      S('stand');
      const cont = g.caveContainment();
      notes.stand = { room: room.id, depth: +cont.depth.toFixed(2), key: cont.key, kind: cont.kind };
      if (!cont.key || cont.depth <= 1) fails.push(`the probe is not underground (key=${cont.key}, depth=${cont.depth.toFixed(2)}m) — every assertion below would be vacuous`);

      // Capture toasts so a refusal can be asserted on the words the PLAYER sees.
      const toasts = [];
      const realToast = ctx.ui.showToast;
      ctx.ui.showToast = (m) => { toasts.push(m); return realToast.call(ctx.ui, m); };

      const poolInUse = () => ctx.lightPool.inUse.reduce((a, b) => a + (b ? 1 : 0), 0);
      // Count only LANTERN-OWNED scene objects. A raw `scene.children.length` is not a lantern
      // canary in a streaming world: this gate saves, loads, and walks 400m and back, and on seed 7
      // that legitimately left 15 more chunk children in the scene than it started with. A canary
      // another system can move is a canary that will eventually be silenced for being noisy.
      const lanternChildren = () => ctx.three.scene.children
        .filter((o) => o.userData && o.userData.interactRegistry === 'lanterns').length;
      const base = { pool: poolInUse(), lanterns: ctx.lanterns.list.length, children: lanternChildren() };
      notes.baseline = base;

      // ── REAL LMB deploy through the shipped item path (never deployLantern directly). ──
      // The hotbar is 4 slots (HOTBAR_SLOT_COUNT) — writing past it would GROW the array and
      // quietly invent inventory that the game does not have.
      const clearInv = () => {
        for (const s of ctx.inventory.slots) { s.item = null; s.count = 0; delete s.meta; }
        for (const s of ctx.inventory.backpack) { s.item = null; s.count = 0; delete s.meta; }
      };
      const kitsHeld = () => ctx.inventory.slots.concat(ctx.inventory.backpack)
        .reduce((a, s) => a + (s.item === 'lantern_kit' ? s.count : 0), 0);
      const giveKit = () => {
        clearInv();
        ctx.inventory.slots[0].item = 'lantern_kit';
        ctx.inventory.slots[0].count = 1;
        ctx.inventory.selectedIdx = 0;
      };
      const clickPlace = async () => {
        const before = ctx.lanterns.list.length;
        ctx.input.mousePressed.add(0);
        await raf(); await raf();
        return ctx.lanterns.list.length > before ? ctx.lanterns.list[ctx.lanterns.list.length - 1] : null;
      };
      S('deploy');
      giveKit();
      // Look slightly down and forward — a real player's aim when setting something on the floor.
      look(room.x + 3, room.y, room.z);
      const lant = await clickPlace();
      if (!lant) {
        ctx.ui.showToast = realToast;
        fails.push(`LMB deploy produced no lantern (toasts: ${JSON.stringify(toasts)})`);
        return { fails, notes };
      }
      notes.placed = { x: +lant.pos.x.toFixed(2), y: +lant.pos.y.toFixed(2), z: +lant.pos.z.toFixed(2) };

      // ── 1. COLLIDER IDENTITY — the thing it landed on must BE the cave. ──
      S('identity');
      const hit = g.castDown(lant.pos.x, lant.pos.z, lant.pos.y + 0.6, true);
      notes.landing = hit
        ? { hitY: +hit.hitY.toFixed(3), dY: +(hit.hitY - lant.pos.y).toFixed(3), handle: hit.colliderHandle, isCave: caveHandles.has(hit.colliderHandle) }
        : null;
      if (!hit) fails.push('nothing under the placed lantern at all — it is floating in the void');
      else {
        if (Math.abs(hit.hitY - lant.pos.y) > 0.05) fails.push(`lantern sits ${(lant.pos.y - hit.hitY).toFixed(2)}m off the floor under it (hitY ${hit.hitY.toFixed(2)} vs lantern ${lant.pos.y.toFixed(2)})`);
        if (!caveHandles.has(hit.colliderHandle)) fails.push(`COLLIDER IDENTITY: the lantern is resting on collider ${hit.colliderHandle}, which is NOT part of the cave body — it landed on the terrain sheet (the terrain.heightAt bug)`);
      }
      // And the surface sampler must DISAGREE, or this cave is not deep enough to prove anything.
      const surfHere = ctx.terrain.pureHeightAt(lant.pos.x, lant.pos.z);
      notes.surfaceWouldHaveBeen = +surfHere.toFixed(2);
      if (surfHere - lant.pos.y < 3) fails.push(`the terrain sheet is only ${(surfHere - lant.pos.y).toFixed(2)}m above the lantern — the old bug would have been invisible here, so this cell proves nothing (VACUOUS)`);

      // ── 2. LIT. ──
      notes.lit = lant.light ? { intensity: +lant.light.intensity.toFixed(3), y: +lant.light.position.y.toFixed(2) } : null;
      if (!lant.light) fails.push('the placed lantern has NO pool light — an unlit breadcrumb');
      else {
        if (!(lant.light.intensity > 0)) fails.push(`placed lantern light intensity ${lant.light.intensity}`);
        if (lant.light.position.y < -1000) fails.push(`the lantern's light is still PARKED at y=${lant.light.position.y} — it is claimed but not positioned`);
        if (Math.abs(lant.light.position.y - lant.pos.y) > 2.0) fails.push(`the lantern's light is ${(lant.light.position.y - lant.pos.y).toFixed(1)}m from the lantern`);
      }
      if (poolInUse() !== base.pool + 1) fails.push(`pool inUse ${poolInUse()} after one placement (expected ${base.pool + 1})`);

      // ── 7a. G4 — the rock answers a placed lantern, with nothing in hand. ──
      await frames(4);
      const rockLit = g.caveRockLight();
      notes.bounceWithLantern = +rockLit.bounce.toFixed(4);
      if (!(rockLit.bounce > 0)) fails.push('G4: a placed lantern within range contributes ZERO cave-rock bounce — the ceiling goes black beside your own light');

      // ── 3. REAL KCC round trip. ──
      const sideClear = (px, py, pz, dx, dz) => {
        const half = ctx.player.body.halfHeight + ctx.player.body.radius;
        const ray = new g.RAPIER.Ray({ x: px, y: py - half + 1.0, z: pz }, { x: dx, y: 0, z: dz });
        const h = ctx.physics.world.castRay(ray, 4, true, undefined, undefined, undefined, body);
        return h ? h.timeOfImpact : Infinity;
      };
      S('roundtrip');
      let pathLen = 0, maxFromLantern = 0;
      const walkToward = async (tx, tz, maxFrames, thresh) => {
        let best = Infinity, stall = 0, reached = false;
        const TH = thresh || 1.9;
        for (let i = 0; i < maxFrames; i++) {
          const p = at();
          const dx = tx - p.x, dz = tz - p.z;
          const dist = Math.hypot(dx, dz);
          face(dx, dz);
          ctx.input.keys['KeyA'] = false; ctx.input.keys['KeyD'] = false; ctx.input.keys['KeyS'] = false;
          if (stall > 10) {
            const fl = dist || 1; const ux = dx / fl, uz = dz / fl;
            const lc = sideClear(p.x, p.y, p.z, -uz, ux), rc2 = sideClear(p.x, p.y, p.z, uz, -ux);
            if (stall > 40 && (Math.floor(stall / 10) % 3 === 0)) { ctx.input.keys['KeyW'] = false; ctx.input.keys['KeyS'] = true; }
            else { ctx.input.keys['KeyW'] = true; ctx.input.keys[lc >= rc2 ? 'KeyA' : 'KeyD'] = true; }
          } else ctx.input.keys['KeyW'] = true;
          await raf();
          const q = at();
          pathLen += Math.hypot(q.x - p.x, q.z - p.z);
          maxFromLantern = Math.max(maxFromLantern, Math.hypot(q.x - lant.pos.x, q.z - lant.pos.z));
          if (dist < TH) { reached = true; break; }
          if (dist < best - 0.03) { best = dist; stall = 0; } else if (++stall > 200) break;
        }
        for (const k of ['KeyW', 'KeyA', 'KeyD', 'KeyS']) ctx.input.keys[k] = false;
        return reached;
      };
      // Walk the REAL CORRIDORS. "Face the target and hold W" cannot round a corner, so a node three
      // hops away is unreachable in a straight line — the first attempt stalled against a wall 8m out
      // and reported a vacuous 4.6m round trip. Chain graph EDGES instead: every leg is a corridor
      // the generator actually cut, and every leg is still a real KCC walk under gravity.
      const adj = new Map();
      for (const n of cavep.nodes) adj.set(n.id, []);
      for (const e of cavep.edges) { adj.get(e.a).push(e.b); adj.get(e.b).push(e.a); }
      const byId = new Map(cavep.nodes.map((n) => [n.id, n]));
      // BFS out from the room; take the first node whose straight-line distance clears the bar, and
      // keep the hop-by-hop path to it.
      const prev = new Map([[room.id, null]]);
      const q = [room.id];
      let goal = null;
      while (q.length && !goal) {
        const cur = q.shift();
        for (const nb of adj.get(cur) || []) {
          if (prev.has(nb)) continue;
          prev.set(nb, cur);
          const nn = byId.get(nb);
          if (Math.hypot(nn.x - lant.pos.x, nn.z - lant.pos.z) >= 14) { goal = nb; break; }
          q.push(nb);
        }
      }
      const path = [];
      for (let c = goal; c !== null && c !== undefined; c = prev.get(c)) path.unshift(c);
      const legs = path.slice(1).map((id) => byId.get(id));
      const before = { x: lant.pos.x, y: lant.pos.y, z: lant.pos.z };
      // cave-walk's proven leg recipe: aim at the MIDPOINT of the corridor first (a corridor bends,
      // and "face the target and hold W" cannot round a corner), then the node, then one retry at a
      // wider threshold. Every step is still real WASD under gravity — no waypoint teleports, which
      // is the whole reason leviathan-walk was once green on an unclimbable ramp.
      // SUB-STEP ALONG THE EDGE. Facing a chamber centre 20m away and holding W puts the capsule
      // into the wall beside the corridor mouth — the first attempt walked 46.6m of real path
      // without ever getting 3.1m from where it started, which is what a stuck-and-wiggling KCC
      // looks like. The corridor is generated ALONG the edge segment, so aiming at successive
      // fractions of it keeps every intermediate target inside the tube. Still real WASD under
      // gravity, still refuses to teleport; a sub-step that misses just hands off to the next one.
      const walkLeg = async (from, to) => {
        const N = 8;
        let last = false;
        for (let i = 1; i <= N; i++) {
          const t = i / N;
          last = await walkToward(from.x + (to.x - from.x) * t, from.z + (to.z - from.z) * t, 500, 2.2);
        }
        return last || Math.hypot(at().x - to.x, at().z - to.z) < 3.5;
      };
      let outOk = legs.length > 0;
      let cur = room;
      for (const n of legs) { if (!(await walkLeg(cur, n))) { outOk = false; break; } cur = n; }
      let backOk = true;
      const homeward = legs.slice(0, -1).reverse().concat([room]);
      for (const n of homeward) { if (!(await walkLeg(cur, n))) backOk = false; cur = n; }
      notes.roundTrip = {
        hops: path, outOk, backOk,
        pathLen: +pathLen.toFixed(1), maxFromLantern: +maxFromLantern.toFixed(1),
      };
      // The property under test is "the world going on around it does not disturb it", and it is
      // tested twice for two different reasons:
      //   (a) 25m of REAL KCC walking with the player, physics and every per-frame system live.
      //       Whether that walking gets OUT of the chamber is `cave-walk`'s question, not this
      //       gate's — corridor traversability already has its own leg with its own teeth, and
      //       asserting it a second time here would just make this gate red for someone else's bug.
      //       `outOk` is recorded as evidence, not as a verdict.
      //   (b) a deliberate FAR relocation (below), which is the only way to reach the distances the
      //       cave streamer's eviction actually runs at. That one is stated as a relocation, not
      //       dressed up as a walk — a teleport lies about traversability, which is exactly why it
      //       is not being used for (a).
      if (pathLen < 25) fails.push(`round trip walked only ${pathLen.toFixed(1)}m of real KCC path (need 25m) — the walk-away assertion is vacuous`);
      if (ctx.lanterns.list.indexOf(lant) < 0) fails.push('the lantern was REMOVED from the registry during the round trip (evicted with the cave?)');
      if (Math.hypot(lant.pos.x - before.x, lant.pos.y - before.y, lant.pos.z - before.z) > 0.01) fails.push('the lantern MOVED during the round trip');
      if (!lant.light || !(lant.light.intensity > 0)) fails.push('the lantern went dark during the round trip');

      // (b) FAR RELOCATION — out of the cave, 400m across the desert, and back. This is the range
      //     the resident cap and the chunk streamer operate at; 12m of corridor never was.
      const surfAway = ctx.terrain.heightAt(room.x + 400, room.z + 400);
      await placeAt(room.x + 400, surfAway, room.z + 400);
      await frames(60);
      const survivedAway = ctx.lanterns.list.indexOf(lant) >= 0 && !!lant.light;
      await placeAt(room.x + standR, room.y, room.z);
      await frames(30);
      notes.farField = {
        survivedAway, backPresent: ctx.lanterns.list.indexOf(lant) >= 0,
        stillLit: !!(lant.light && lant.light.intensity > 0),
        poolInUse: poolInUse(),
        moved: +Math.hypot(lant.pos.x - before.x, lant.pos.y - before.y, lant.pos.z - before.z).toFixed(4),
      };
      if (!survivedAway) fails.push('the lantern was destroyed while the player was 400m away — placed light is player property and must outlive the trip');
      if (ctx.lanterns.list.indexOf(lant) < 0) fails.push('the lantern is gone after returning from 400m away');
      if (!lant.light || !(lant.light.intensity > 0)) fails.push('the lantern lost its pool light over the 400m round trip');
      if (notes.farField.moved > 0.01) fails.push(`the lantern moved ${notes.farField.moved}m over the far-field trip`);

      // ── 5. SAVE / RELOAD (done before the retrieve so a live lantern is in the save). ──
      await placeAt(room.x + standR, room.y, room.z);
      S('saveload');
      const savedPos = { x: lant.pos.x, y: lant.pos.y, z: lant.pos.z };
      g.saveGame();
      let saveVersion = null, savedLanterns = null;
      try {
        const raw = JSON.parse(localStorage.getItem('dustfall.save.v1'));
        saveVersion = raw.version;
        savedLanterns = (raw.lanterns || []).length;
        notes.savedY = raw.lanterns && raw.lanterns[0] ? +raw.lanterns[0].pos.y.toFixed(3) : null;
      } catch (e) { fails.push(`could not read the save back: ${String(e)}`); }
      g.loadGame();
      await frames(10);
      notes.save = { version: saveVersion, lanterns: savedLanterns, afterLoad: ctx.lanterns.list.length };
      if (saveVersion !== 18) fails.push(`SAVE_VERSION in the written save is ${saveVersion}, expected 18 — cycle 11 must not bump the schema`);
      if (savedLanterns !== 1) fails.push(`the save carries ${savedLanterns} lanterns (expected 1)`);
      const re = ctx.lanterns.list[0];
      if (!re) fails.push('no lantern after reload');
      else {
        const d = Math.hypot(re.pos.x - savedPos.x, re.pos.y - savedPos.y, re.pos.z - savedPos.z);
        notes.reloadDelta = +d.toFixed(5);
        if (d > 0.01) fails.push(`reloaded lantern is ${d.toFixed(3)}m from where it was saved — the underground Y did not round-trip`);
        if (!re.light || !(re.light.intensity > 0)) fails.push('the reloaded lantern has no live pool light');
        const h2 = g.castDown(re.pos.x, re.pos.z, re.pos.y + 0.6, true);
        if (!h2 || !caveHandles.has(h2.colliderHandle)) fails.push('the reloaded lantern is no longer resting on the cave body');
      }

      // ── 6. THE CAP + a real refusal. ──
      toasts.length = 0;
      S('cap');
      let placedTotal = ctx.lanterns.list.length;
      const CAPN = 6;
      // Stand still and TURN. Teleporting into a ring risks parking the capsule inside solid rock,
      // and the placements only need to be further apart than LANTERN_NEAR_DISTANCE (1m): at
      // PLACEMENT_DISTANCE_M = 2.2m, adjacent bearings 30 deg apart land 1.14m apart.
      await placeAt(room.x + standR, room.y, room.z);
      const capToasts = [];
      for (let i = 0; i < 16 && capToasts.length < 3; i++) {
        giveKit();
        const a = (i / 12) * Math.PI * 2;
        look(room.x + Math.cos(a) * 8, room.y - 0.5, room.z + Math.sin(a) * 8);
        await raf();
        const n0 = ctx.lanterns.list.length;
        await clickPlace();
        placedTotal = ctx.lanterns.list.length;
        if (placedTotal === n0 && placedTotal >= CAPN) capToasts.push(toasts[toasts.length - 1]);
      }
      notes.cap = { placed: placedTotal, refusals: capToasts.length, toasts: toasts.slice(-3) };
      if (placedTotal > CAPN) fails.push(`${placedTotal} lanterns placed — the cap of ${CAPN} did not hold`);
      if (placedTotal !== CAPN) fails.push(`only ${placedTotal} lanterns placed, cap is ${CAPN} — the cap was never REACHED, so the refusal below is vacuous`);
      const capToast = toasts.find((m) => /pack one up first/.test(m || ''));
      if (!capToast) fails.push(`no cap-refusal message was shown to the player (saw ${JSON.stringify(toasts.slice(-3))})`);
      if (!capToasts.length) fails.push('the cap was never actually hit — no placement was refused, so the refusal assertion is vacuous');
      notes.capToast = capToast || null;

      // ── 4. REAL RMB retrieve of every one, through hover → handleContextAction. ──
      S('retrieve');
      clearInv();
      let retrieved = 0;
      for (let guard = 0; guard < 12 && ctx.lanterns.list.length; guard++) {
        const target = ctx.lanterns.list[0];
        await placeAt(target.pos.x + 1.2, target.pos.y, target.pos.z);
        const n0 = ctx.lanterns.list.length;
        for (let i = 0; i < 40 && ctx.lanterns.list.length === n0; i++) {
          look(target.pos.x, target.pos.y + 1.0, target.pos.z);
          await raf();                              // let interaction.ts set hover + hovered
          ctx.input.mousePressed.add(2);
          await raf();
        }
        if (ctx.lanterns.list.length < n0) retrieved++; else break;
      }
      const kitCountAfter = kitsHeld();
      notes.retrieve = { retrieved, remaining: ctx.lanterns.list.length, kitsBack: kitCountAfter };
      if (retrieved === 0) fails.push('RMB retrieve never fired — the shipped pack-up path is unreachable underground');
      if (ctx.lanterns.list.length !== 0) fails.push(`${ctx.lanterns.list.length} lanterns left after retrieving all of them`);
      if (kitCountAfter !== retrieved) fails.push(`retrieved ${retrieved} lanterns but got ${kitCountAfter} kits back`);

      // ── 7b. G4 canary, the OTHER direction: nothing held, nothing placed ⇒ EXACTLY zero. ──
      await frames(4);
      const rockDark = g.caveRockLight();
      notes.bounceAfterRetrieve = rockDark.bounce;
      if (rockDark.bounce !== 0) fails.push(`NO FREE LIGHT canary: with nothing held and no lantern placed the cave-rock bounce is ${rockDark.bounce}, must be exactly 0`);

      // ── 8. LEAK CANARY. ──
      S('teardown');
      const end = { pool: poolInUse(), lanterns: ctx.lanterns.list.length, children: lanternChildren() };
      notes.teardown = end;
      if (end.pool !== base.pool) fails.push(`pool leak: inUse ${base.pool} → ${end.pool} after full teardown`);
      if (end.lanterns !== base.lanterns) fails.push(`registry leak: ${base.lanterns} → ${end.lanterns}`);
      if (end.children !== base.children) fails.push(`scene-graph leak: ${base.children} → ${end.children} lantern objects still parented to the scene`);

      ctx.ui.showToast = realToast;
      try { localStorage.removeItem('dustfall.save.v1'); } catch (e) { void e; }
      S('done');
      } catch (err) {
        fails.push(`threw during stage "${notes.stage}": ${String((err && err.message) || err)}`);
      }
      return { fails, notes };
    }).catch((e) => ({ fails: [`LANTERN-RT harness threw: ${String((e && e.message) || e)}`], notes: {} }));

    for (const f of (lrt.fails || [])) { fails.push(`LANTERN-RT ${f}`); console.log(`[pool-fill] LANTERN-RT FAIL ${f}`); }
    console.log(`[pool-fill] LANTERN-RT ${JSON.stringify(lrt.notes || {})}`);
    console.log(`LANTERN-RT pass=${(lrt.fails || []).length === 0 ? 1 : 0} fails=${(lrt.fails || []).length}`);

    // ══ DEEPER cycle 11, GATE B — CAVE-COLD ════════════════════════════════════════════════════
    //    Zach: *"the temperature should be colder but not cold enough to damage the player."* The
    //    shipped model was backwards — underground the branch chain still ran off the SURFACE clock,
    //    so a cave WARMED you at noon and COLD_NIGHT_DRAIN killed you in it at midnight. INV-COLD
    //    replaces the ambient term underground with an equilibrium whose TARGET is hard-clamped, and
    //    this gate proves the clamp holds over the whole space rather than at the tuned point:
    //
    //      1. THE MATRIX, through the REAL updateStats tick (the capsule really is at that depth in
    //         the real cave AABB, so containment / pureHeightAt / branch order are the shipped ones).
    //      2. TOTALITY over kind × wet × depth on `caveColdTarget` itself — the one function the
    //         clamp lives in, which the tick provably routes through (assertion 5 ties the two).
    //      3. Corollary (b): a player who descends already freezing must come out WARMER.
    //      4. Surface parity: at depth 0 the cave term must be exactly a no-op, checked against the
    //         legacy constants themselves (midnight drains at exactly COLD_NIGHT_DRAIN) rather than
    //         against a digest this cycle would have generated for itself.
    //      5. Vacuous-pass guard — "green because the cold never fired" is the failure mode cycles 5
    //         and 8 both hit.
    const cold = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const fails = []; const notes = {};
      // These are hardcoded ON PURPOSE — the gate must pin the expected values independently, so
      // editing tuning.ts moves the game and reds the gate rather than moving both together.
      const T = { FLOOR: -0.48, DAMAGE: -1, VIGNETTE: 0.3, REGEN: 0.5, NIGHT_DRAIN: 1 / 420 };

      if (!g.caveColdFloorOk()) fails.push('the INV-COLD boot assert is RED: CAVE_COLD_FLOOR no longer clears the damage line by CAVE_COLD_SAFETY_MARGIN');

      // ── 2. TOTALITY on the clamped target: depth × kind × wet, exhaustively. ──
      const KINDS = ['canonical', 'warren', 'fungal', 'flooded', 'shaft'];
      let worstTarget = 0, worstCell = null, anyBelowVignette = false;
      for (const d of [0, 1, 5, 10, 20, 30, 40, 55, 200]) {
        for (const k of KINDS) {
          for (const wet of [false, true]) {
            const t = g.caveColdTarget(d, k, wet);
            if (t < worstTarget) { worstTarget = t; worstCell = `${k}@${d}m${wet ? ' wet' : ''}`; }
            if (t > 0) fails.push(`caveColdTarget(${d},${k},${wet}) = ${t} — a cave must never warm you ABOVE neutral`);
            if (t < T.FLOOR - 1e-9) fails.push(`caveColdTarget(${d},${k},${wet}) = ${t} — BELOW the clamp floor ${T.FLOOR}; a multiplier escaped the clamp`);
            if (d === 0 && t !== 0) fails.push(`caveColdTarget(0,${k},${wet}) = ${t} — depth 0 must be exactly a no-op`);
            if (t < -T.VIGNETTE) anyBelowVignette = true;
          }
        }
      }
      notes.worstTarget = { value: +worstTarget.toFixed(4), cell: worstCell };
      if (!anyBelowVignette) fails.push(`no depth/kind combination ever reaches past the cold vignette threshold (${-T.VIGNETTE}) — the cave never reads as cold at all (VACUOUS)`);
      if (worstTarget > -T.VIGNETTE) fails.push(`the coldest the cave ever gets is ${worstTarget.toFixed(3)} — the blue vignette (${-T.VIGNETTE}) never lights`);
      if (worstTarget < -T.REGEN) fails.push(`the coldest target ${worstTarget.toFixed(3)} suppresses health regen (|t| >= ${T.REGEN}) — Q6 says the deep must not`);

      // ── 1. THE MATRIX through the real tick. ──
      const DEPTHS = [0, 5, 10, 20, 30, 40, 55];
      const STARTS = [1, 0, -0.5, -0.99];
      const SUNS = [1.0, -0.5];              // noon / midnight, on the SURFACE clock
      const rows = [];
      let minTempAll = 1, maxColdReach = 0, damageCells = 0, depthsSeen = new Set();
      // The depth-0 cells assert SURFACE PARITY, so they have to be unambiguously on the surface.
      // Asking for depth exactly 0 puts the capsule ON the sheet, and Rapier stores translations as
      // f32: the round-trip can land a micron BELOW the f64 `pureHeightAt`, at which point the cave
      // branch correctly fires and the parity cell reads as a leak. Seed 1337 rounded one way and
      // seed 7 the other — a coin-flip gate. Stand the surface cells 30cm up instead, which is also
      // where a real player's body centre is: never within a micron of the sheet.
      for (const d of DEPTHS) {
        for (const wet of [false, true]) {
          for (const sun of SUNS) {
            for (const st of STARTS) {
              const r = g.caveColdRun({ depth: d === 0 ? -0.3 : d, sunHeight: sun, startTemp: st, wet, minutes: 12 });
              rows.push(r);
              if (r.observedDepth > 0.01) depthsSeen.add(d);
              if (d > 0) {
                if (!r.inCave) fails.push(`depth ${d}m: the probe was NOT registered as inside a cave (observedDepth ${r.observedDepth}) — the matrix is measuring the surface`);
                minTempAll = Math.min(minTempAll, r.minTemp);
                // Only cells that START at or above neutral can testify that the CAVE made them
                // cold; a cell seeded at -0.99 would otherwise satisfy the guard on its own seed.
                if (st >= 0) maxColdReach = Math.max(maxColdReach, -r.minTemp);
                if (r.minTemp <= T.DAMAGE + 1e-9 || r.coldDamageTicks > 0 || r.healthLost > 1e-9 || r.died) {
                  damageCells++;
                  fails.push(`CAVE DAMAGE at depth ${d}m sun ${sun} start ${st}${wet ? ' wet' : ''}: minTemp ${r.minTemp}, ${r.coldDamageTicks} damage ticks, health lost ${r.healthLost}${r.died ? ', DIED' : ''}`);
                }
                // INV-COLD bounds what the CAVE does, not where the player arrived: someone who
                // descends at -0.99 starts below the floor by definition. The bound is therefore
                // "never colder than where you started, and never colder than the floor".
                const bound = Math.min(st, T.FLOOR);
                if (r.minTemp < bound - 1e-6) fails.push(`depth ${d}m sun ${sun} start ${st}${wet ? ' wet' : ''}: minTemp ${r.minTemp} is below ${bound} — the cave made the player colder than the floor allows`);
                // ── 5. THE TICK ROUTES THROUGH THE CLAMPED TARGET. A cell that starts neutral or
                //    warm settles exactly on caveColdTarget; if the branch used any other formula
                //    this diverges, which is what stops assertion 2 from being a test of dead code.
                if (st >= 0) {
                  const want = g.caveColdTarget(r.observedDepth, r.kind, wet);
                  if (Math.abs(r.endTemp - want) > 0.02) fails.push(`depth ${d}m start ${st}${wet ? ' wet' : ''}: settled at ${r.endTemp} but caveColdTarget says ${want.toFixed(4)} — the tick is not using the clamped target`);
                }
                // ── 3. Corollary (b) — descending frozen must WARM you. ──
                if (st === -0.99 && !(r.endTemp > st + 1e-6)) fails.push(`depth ${d}m sun ${sun}${wet ? ' wet' : ''}: arrived at ${st} and ended at ${r.endTemp} — the cave did not warm a freezing descender`);
              } else {
                // ── 4. SURFACE PARITY — depth 0 must be the legacy model, unchanged. ──
                if (r.inCave) fails.push(`depth 0: registered as inside a cave — depth <= 0 must be exactly a no-op`);
                if (sun < 0 && st > -1) {
                  const want = -T.NIGHT_DRAIN / 30;
                  if (Math.abs(r.firstTempStep - want) > 1e-9) fails.push(`SURFACE PARITY: midnight step was ${r.firstTempStep} per tick, legacy COLD_NIGHT_DRAIN is ${want} — the cave branch is leaking onto the surface`);
                }
                if (sun > 0 && st < 1 && !(r.firstTempStep > 0)) fails.push(`SURFACE PARITY: midday on the surface did not warm (step ${r.firstTempStep})`);
              }
            }
          }
        }
      }
      notes.cells = rows.length;
      notes.minTempUnderground = +minTempAll.toFixed(4);
      notes.maxColdReach = +maxColdReach.toFixed(4);
      notes.damageCells = damageCells;
      notes.depthsSeen = depthsSeen.size;
      notes.sample = rows.filter((r) => r.depth === 55 && r.startTemp === 0).map((r) => `${r.wet ? 'wet' : 'dry'}/sun${r.sunHeight}: ${r.endTemp} (min ${r.minTemp}, dmg ${r.coldDamageTicks})`);

      // ── 5. VACUOUS-PASS GUARD. ──
      if (maxColdReach < 0.05) fails.push(`VACUOUS: the coldest the matrix ever got was ${maxColdReach.toFixed(4)} — nothing ever got cold, so "no damage" proves nothing`);
      if (depthsSeen.size < 5) fails.push(`VACUOUS: only ${depthsSeen.size} distinct depths were actually underground (need 5)`);
      return { fails, notes };
    }).catch((e) => ({ fails: [`CAVE-COLD threw: ${String((e && e.message) || e)}`], notes: {} }));

    for (const f of (cold.fails || [])) { fails.push(`CAVE-COLD ${f}`); console.log(`[pool-fill] CAVE-COLD FAIL ${f}`); }
    console.log(`[pool-fill] CAVE-COLD ${JSON.stringify(cold.notes || {})}`);
    console.log(`CAVE-COLD pass=${(cold.fails || []).length === 0 ? 1 : 0} fails=${(cold.fails || []).length}`);

    // ══ DEEPER walk-test 2026-07-29 — STORM-CAVE ═══════════════════════════════════════════════
    //    Zach: *"the cave should be shelter so the storm doesn't effect you in it."* Shelter is
    //    classified against registered ZONES and a cave is not one, so the haboob reached the player
    //    through thirty metres of rock.
    //
    //    THE TOOTH THAT MATTERS IS THE THIRD ONE. The obvious fix — `inShelter = true` underground —
    //    is wrong, because `updateStats` runs `if (inShelter) … else if (caveDepth > 0)`: setting it
    //    would PRE-EMPT cycle 11's cave-cold model and quietly make every cave temperature-neutral,
    //    inverting behaviour Zach reviewed and signed off one cycle ago. So this asserts BOTH halves
    //    at once — the storm is gone AND the cold still runs — because a fix for one that silently
    //    breaks the other is exactly what this gate exists to catch.
    const sc = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const fails = []; const notes = {};
      try {
        ctx.flags.paused = false;
        const body = ctx.player.body.body;
        const CAP = ctx.player.body.halfHeight + ctx.player.body.radius;
        const wasI = ctx.weather.intensity;
        // DRIVE THE REAL STORM, do not fake its number. A storm is a directional WALL and
        // `updateWeather` DERIVES `intensity` from the player's signed distance to it, every frame,
        // before `updateShelter` reads it — so assigning `intensity` from outside the tick is
        // overwritten within the same frame and measures a clear day. The first two runs of this
        // gate proved that by failing its own control tooth (surface perceivedIntensity 0.00 with no
        // shelter in sight). So: arm the wall through the shipped path, then park its core on the
        // player each frame and let the game compute the intensity itself.
        g.triggerStorm();
        const frames = async (n) => {
          for (let i = 0; i < n; i++) {
            const t = body.translation();
            const w = ctx.weather.wall;
            w.active = true; w.posX = t.x; w.posZ = t.z;
            await raf();
          }
        };

        const res = (ctx.caveStream ? ctx.caveStream.residents() : [])[0];
        if (!res) return { fails: ['no cave resident to test'], notes };
        const nodes = res.cave.probe.nodes.slice().sort((a, b) => a.y - b.y);
        const deep = nodes[0];

        // A — ON THE SURFACE, above the cave, in the storm. The control: without this the whole
        //     check could pass on a build where perceivedIntensity is always 0.
        const sy = ctx.terrain.heightAt(deep.x, deep.z);
        body.setTranslation({ x: deep.x, y: sy + CAP + 0.3, z: deep.z }, true);
        body.setLinvel({ x: 0, y: 0, z: 0 }, true); ctx.player.velocityY = 0;
        // WAIT ON THE CONDITION, not on a frame count: the wall's intensity RAMPS through the
        // weather state machine (a fixed 25 frames caught it at 0.06, still climbing).
        let waited = 0;
        while (ctx.weather.intensity < 0.85 && waited < 900) { await frames(1); waited++; }
        notes.rampFrames = waited;
        notes.surface = { inCave: ctx.player.inCave, perceived: +ctx.weather.perceivedIntensity.toFixed(2) };
        if (ctx.player.inCave) fails.push('the player reads as in-cave while standing on the surface');
        if (!(ctx.weather.perceivedIntensity > 0.5)) fails.push(`surface perceivedIntensity ${ctx.weather.perceivedIntensity.toFixed(2)} — the storm is not reaching an EXPOSED player, so the cave result below proves nothing`);

        // B — INSIDE, deepest chamber.
        body.setTranslation({ x: deep.x, y: deep.y + CAP + 0.3, z: deep.z }, true);
        body.setLinvel({ x: 0, y: 0, z: 0 }, true); ctx.player.velocityY = 0;
        await frames(40);
        const depth = g.caveContainment().depth;
        notes.cave = {
          inCave: ctx.player.inCave, perceived: +ctx.weather.perceivedIntensity.toFixed(2),
          inShelter: ctx.player.inShelter, depth: +depth.toFixed(1),
        };
        if (!(depth > 1)) fails.push(`the probe is not underground (depth ${depth.toFixed(2)}m) — every assertion here would be vacuous`);
        if (!ctx.player.inCave) fails.push('inCave is false inside the cave');
        if (ctx.weather.perceivedIntensity !== 0) fails.push(`perceivedIntensity ${ctx.weather.perceivedIntensity} underground — the storm still reaches the player`);
        // THE REGRESSION GUARD (see the note above).
        if (ctx.player.inShelter) fails.push('inShelter is TRUE inside a cave — that pre-empts the cave-cold branch in updateStats and makes caves temperature-neutral (cycle 11 INV-COLD would be silently dead)');

        // C — and the cold model is genuinely still running down here: temperature must walk NEGATIVE
        //     toward the cave target, not toward 0.
        ctx.stats.temperature = 0;
        const t0 = ctx.stats.temperature;
        await frames(90);
        const t1 = ctx.stats.temperature;
        notes.temp = { from: +t0.toFixed(3), to: +t1.toFixed(3) };
        if (!(t1 < t0 - 1e-4)) fails.push(`temperature went ${t0.toFixed(3)} → ${t1.toFixed(3)} underground — the cave-cold model is not running (a cave must chill you, not be neutral)`);

        ctx.weather.intensity = wasI;
        return { fails, notes };
      } catch (e) {
        fails.push(`STORM-CAVE threw: ${String((e && e.message) || e)}`);
        return { fails, notes };
      }
    }).catch((e) => ({ fails: [`STORM-CAVE harness threw: ${String((e && e.message) || e)}`], notes: {} }));
    for (const f of (sc.fails || [])) { fails.push(`STORM-CAVE ${f}`); console.log(`[pool-fill] STORM-CAVE FAIL ${f}`); }
    console.log(`[pool-fill] STORM-CAVE ${JSON.stringify(sc.notes || {})}`);
    console.log(`STORM-CAVE pass=${(sc.fails || []).length === 0 ? 1 : 0} fails=${(sc.fails || []).length}`);

    // ══ WALK-TEST 2026-07-29 — POOL-BASIN ══════════════════════════════════════════════════════
    //    Zach: the pools read as *"3d water sitting on top of the terrain … it should actually sit in
    //    some kind of pool."* The floor cut is now lowered under each pool, so the hollow is in the
    //    SDF and therefore in the COLLIDER.
    //
    //    MEASURED, NOT EYEBALLED, and deliberately so: `pool-look` renders at true shipping exposure,
    //    where the water is a very dark mirror — a basin and no basin look nearly identical in those
    //    frames. Geometry questions get geometry answers. This casts the REAL Rapier collider (the
    //    thing the player wades in) at each pool centre and at a ring outside the basin, and asserts
    //    the rock actually falls away between them.
    const pb = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const fails = []; const notes = { pools: [] };
      try {
        const T = g.Tuning;
        const res = (ctx.caveStream ? ctx.caveStream.residents() : [])[0];
        if (!res) return { fails: ['no cave resident'], notes };
        const specs = (res.cave.probe.pools || []);
        if (!specs.length) return { fails: ['the cave reported NO pools — nothing to measure'], notes };
        const handles = new Set();
        if (res.cave.body) for (let i = 0; i < res.cave.body.numColliders(); i++) handles.add(res.cave.body.collider(i).handle);
        for (const s of specs) {
          // Centre of the basin…
          const c = g.castDown(s.x, s.z, s.y + 3, true);
          // …and OUTSIDE it, on a ring past `radius × BASIN_R_MUL`, averaged over 8 bearings so one
          // unlucky lump of floor relief cannot pass or fail the whole check.
          const R = s.r * T.CAVE_POOL_BASIN_R_MUL * 1.25;
          let sum = 0, n = 0;
          for (let k = 0; k < 8; k++) {
            const a = (k / 8) * Math.PI * 2;
            const h = g.castDown(s.x + Math.cos(a) * R, s.z + Math.sin(a) * R, s.y + 3, true);
            if (h && handles.has(h.colliderHandle)) { sum += h.hitY; n++; }
          }
          if (!c) { fails.push(`pool at (${s.x.toFixed(0)},${s.z.toFixed(0)}): no rock under the centre`); continue; }
          if (!handles.has(c.colliderHandle)) { fails.push('the floor under a pool is not the cave body'); continue; }
          if (n < 4) { fails.push(`pool at (${s.x.toFixed(0)},${s.z.toFixed(0)}): only ${n}/8 rim samples hit cave rock`); continue; }
          const rim = sum / n;
          const drop = rim - c.hitY;                       // +ve = the centre is LOWER than the surround
          notes.pools.push({ x: +s.x.toFixed(0), z: +s.z.toFixed(0), drop: +drop.toFixed(3), waterAbove: +(s.y - c.hitY).toFixed(3) });
          // The basin is smootherstep-shaped and the floor carries its own relief, so this asserts a
          // GENEROUS fraction of the nominal depth rather than the number itself.
          if (!(drop > T.CAVE_POOL_BASIN_DEPTH_M * 0.45))
            fails.push(`pool at (${s.x.toFixed(0)},${s.z.toFixed(0)}) has no basin: the centre is only ${drop.toFixed(3)}m below its surround (want > ${(T.CAVE_POOL_BASIN_DEPTH_M * 0.45).toFixed(3)}m) — the water is sitting ON the floor`);
          // …and the water still has to be WADEABLE, not swimmable: cycle 6's whole design contract.
          const total = s.y - c.hitY;
          if (!(total > 0.2 && total < 0.95))
            fails.push(`pool depth ${total.toFixed(2)}m at the centre is outside the wadeable band 0.2-0.95m`);
        }
        return { fails, notes };
      } catch (e) {
        fails.push(`POOL-BASIN threw: ${String((e && e.message) || e)}`);
        return { fails, notes };
      }
    }).catch((e) => ({ fails: [`POOL-BASIN harness threw: ${String((e && e.message) || e)}`], notes: {} }));
    for (const f of (pb.fails || [])) { fails.push(`POOL-BASIN ${f}`); console.log(`[pool-fill] POOL-BASIN FAIL ${f}`); }
    console.log(`[pool-fill] POOL-BASIN ${JSON.stringify(pb.notes || {})}`);
    console.log(`POOL-BASIN pass=${(pb.fails || []).length === 0 ? 1 : 0} fails=${(pb.fails || []).length}`);

    // ── 7. THE PIXEL GATE (round-13 fix 2b) ──────────────────────────────────────────────────
    //    `pool-look` measures the water's on-screen appearance; nothing ran it in `verify:chunks`,
    //    so the whole visual contract (darker than lit rock · a LIVE ripple · no 8-bit banding · a
    //    surface that mirrors rather than glows) had no permanent gate. A REDUCED set of its
    //    framings now runs here, on the same shared verdict `pool-look` uses:
    //      rim   — standing over the water: darker-than-rock, ripple motion, plateau/banding.
    //      fungi — the mirrored-emitter framing (skipped when the seed puts no cluster near water).
    //      unlit — no lamp in the room: the median canary (it must not glow) AND the p99 canary
    //              (it must still mirror) — the one framing where an emitter is the only light.
    //    Screenshots are off (the pictures are `pool-look`'s job); the canvas is set to pool-look's
    //    1100×720 because the plateau and lit-pixel floors are calibrated at that resolution.
    const pixT0 = Date.now();
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.three.renderer.setSize(1100, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 720; cam.updateProjectionMatrix(); }
    });
    const pm = await poolShotSet(page, 'poolgate', { only: ['rim', 'fungi', 'unlit'], shots: false });
    const pixFails = poolPixelFails(pm, Object.keys(pm));
    for (const f of pixFails) fails.push(f);
    console.log(`[pool-fill] pixel gate: ${Object.keys(pm).length} framings, ${pixFails.length} fails, ${((Date.now() - pixT0) / 1000).toFixed(1)}s`);

    const pass = fails.length === 0 ? 1 : 0;
    for (const f of fails) console.log(`[pool-fill] FAIL ${f}`);
    console.log(`[pool-fill] ${JSON.stringify(r.notes || {})}`);
    console.log(`[pool-fill] determinism ${JSON.stringify({ stable: det.stable, matchesLive: det.matchesLive })}`);
    console.log(`POOL-FILL pass=${pass} seed=${r.seed} digest=${r.digest} pools=${(r.notes && r.notes.poolCount) || 0} fails=${fails.length}`);

    // `--shot` — one torch-lit player-eye frame of the pool, for the visual pass. OFF by default so
    // the permanent gate stays a fast measurement and never pays for a render.
    if (argv.shot) {
      await page.evaluate(() => {
        const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
        let cavep = null, caveGroup = null;
        ctx.three.scene.traverse((o) => {
          if (o.userData && o.userData.caveGenProbe) cavep = o.userData.caveGenProbe;
          if (o.name === 'caveGen') caveGroup = o;
        });
        const P = cavep.pools[0];
        const n = cavep.nodes.find((q) => q.id === P.node);
        ctx.flags.paused = true;
        ctx.three.renderer.setSize(1100, 720, false);
        const cam = ctx.three.camera;
        cam.aspect = 1100 / 720; cam.updateProjectionMatrix();
        // Stand back from the rim at eye height, looking down into the water — the player's own view.
        let dx = P.x - n.x, dz = P.z - n.z; const L = Math.hypot(dx, dz) || 1; dx /= L; dz /= L;
        cam.position.set(P.x + dx * (P.r + 2.4), P.y + 1.55, P.z + dz * (P.r + 2.4));
        cam.lookAt(P.x, P.y, P.z);
        cam.updateMatrixWorld(true);
        // The only real light down there is what you carry — put a torch in the player's hand-space.
        const torch = new THREE.PointLight(0xffb464, 14, 22, 1.6);
        torch.position.set(cam.position.x, cam.position.y - 0.25, cam.position.z);
        ctx.three.scene.add(torch);
        window.__poolShotTorch = torch;
        // Hide everything outside the cave so the one-sided terrain sheet doesn't fill the frame.
        const hidden = [];
        ctx.three.scene.traverse((o) => {
          if (!o.isMesh || !o.visible) return;
          let inCave = false; for (let p = o; p; p = p.parent) if (p === caveGroup) { inCave = true; break; }
          if (!inCave) { hidden.push(o); o.visible = false; }
        });
        window.__poolShotHidden = hidden;
        ctx.three.scene.background = new THREE.Color(0x000000);
        ctx.three.renderer.render(ctx.three.scene, cam);
      });
      await page.waitForTimeout(300);
      const name = argv.tag ? `pool-${argv.tag}` : 'pool';
      try { await page.screenshot({ path: join(OUT, `scen-${name}.png`) }); console.log(`[pool-fill] saved scen-${name}.png`); }
      catch (e) { console.log(`[pool-fill] shot flaked (${e.name})`); }
    }
    if (!pass) throw new Error('pool-fill FAILED');
  },

  // ── pool-look (DEEPER cycle 6, the HERO-VISUAL pass) — THE REAL PLAYER'S-EYE READ OF THE WATER ──
  //   The `pool-fill` gate measures; this one LOOKS, and it looks from where the player actually is.
  //   No rig fill light, no studio rig, no framed exterior: the shipping darkness floors, the shipping
  //   cave fog, and the shipping TORCH tuning (TORCH_LIGHT_*) carried where the game carries it — at
  //   the flame, 45cm ahead of the eye and 30cm to the right. The earlier `pool-fill --shot` used a
  //   14-intensity/22m rig torch, i.e. ~8× the real thing; that is why the water graded "chalky under
  //   a bright rig torch". A harness that invents its own light is testing a different scene.
  //   Eight framings, because a single one has hidden failures in this project every time:
  //     first-sight (entering the chamber) · rim (standing over it) · graze (across the surface) ·
  //     wade (looking at your feet through the water) · shore (the waterline close-up) ·
  //     flashlight · unlit (is it just a black hole?) · near-mushroom-glow.
  //   Run: npm run rig -- --scenario=pool-look --port=5244 [--seed=1337] [--tag=r1]
  'pool-look': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      try { ctx.sandWorms.list.length = 0; } catch {}
      try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.42);
      ctx.three.renderer.setSize(1100, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 720; cam.updateProjectionMatrix(); }
    });
    // ── `--flat=spec|all` — THE TEETH CALIBRATION for the modulation floor (round-13).
    //    A floor is only a gate if a BROKEN surface falls under it, so the floor is set from a
    //    measured flat surface, not from taste. This pokes the LIVE uniforms (reachable because each
    //    cave's material publishes its compiled shader refs on `userData.poolShaders`):
    //      spec = uPoolRipSlope 0        → the wave normal goes flat; the torch's answer is one lobe.
    //      all  = + uPoolCaustic/Gravel 0 → a genuinely smooth pane: no transmission bands either.
    //    NOT a shipping path and never run by a gate — it exists so the numbers in the floor's
    //    comment are reproducible.
    if (argv.flat) {
      const n = await page.evaluate((mode) => {
        const ctx = window.__game.ctx; let c = 0;
        ctx.three.scene.traverse((o) => {
          if (!o.isMesh || o.name !== 'cavePoolWater') return;
          const shaders = o.material && o.material.userData && o.material.userData.poolShaders;
          if (!shaders) return;
          for (const s of shaders) {
            if (s.uniforms.uPoolRipSlope) { s.uniforms.uPoolRipSlope.value = 0; c++; }
            if (mode === 'all') {
              if (s.uniforms.uPoolCaustic) s.uniforms.uPoolCaustic.value = 0;
              if (s.uniforms.uPoolGravelA) s.uniforms.uPoolGravelA.value = 0;
            }
          }
        });
        return c;
      }, String(argv.flat));
      console.log(`[pool-look] FLAT MODE "${argv.flat}" — zeroed ripple on ${n} live shader(s). These numbers CALIBRATE the floor; they are not a pass.`);
      if (!n) throw new Error('pool-look --flat: no live pool shader exposed userData.poolShaders — the teeth calibration cannot run');
    }
    const m = await poolShotSet(page, argv.tag ? `poollook-${argv.tag}` : 'poollook',
      argv.framings ? { only: String(argv.framings).split(',').map((s) => s.trim()) } : {});

    // ── THE PIXEL VERDICT (round-12 finding 12, shared since round-13). Machine-read at SHIPPING
    //    exposure, every run. `poolPixelFails` is the SAME judgement `pool-fill` applies inside
    //    `verify:chunks` — see its definition for what each rule proves and why.
    //    `--flat` runs are calibration, not verification: they are EXPECTED to fail.
    const fails = poolPixelFails(m, argv.framings ? Object.keys(m) : null);
    for (const f of fails) console.log(`[pool-look] FAIL ${f}`);
    console.log(`POOL-LOOK pass=${fails.length === 0 ? 1 : 0} exposure=${POOL_SHOT_EXPOSURE} framings=${Object.keys(m).length} fails=${fails.length}`);
    // UNCONDITIONAL (round-13 sev-2). This used to throw only under `--gate`, a flag NOTHING ever
    // passed — so the scenario printed FAIL lines and exited 0, and two red framings rode along for
    // a whole round. A scenario that prints FAIL must fail.
    if (fails.length) throw new Error(`pool-look FAILED (${fails.length} pixel assertions)`);
  },


  // ── cave-void (DEEPER cycle 1) — THE SEE-THROUGH GATE ───────────────────────
  //   Zach's cave walk-test (docs/campaign/cave-walktest-2026-07-24.md, D-2): "many of the
  //   interior walls and floors of the cave were invisible, i could see right through under
  //   the world". `cave-walk` is GREEN on that same cave — it only proves REACHABILITY, so it
  //   is structurally blind to a hole in the shell. This gate closes the whole class.
  //
  //   METHOD — a renderer-faithful void-ray sweep. From N sample points spread across EVERY
  //   chamber (centre + 4 offsets, at eye height above the floor) and EVERY corridor (points
  //   along the axis), cast K rays on a Fibonacci sphere with THREE.Raycaster against the cave
  //   mesh set. THREE.Mesh.raycast honours `material.side`, so a BackSide shell only registers
  //   BACK-face hits — exactly what the renderer does. A ray that hits nothing within FAR is an
  //   ESCAPE: from that spot, in that direction, the player sees the void.
  //
  //   THE DECLARED-OPENING ALLOWANCE (the leviathan lesson, verify-solid.mjs:268): rays that
  //   leave through the REAL entrance are the point of the cave, not a defect. They are excused
  //   by an explicit `userData.intendedOpening = {center,radius}` declaration (caveTest.ts:306),
  //   NOT by loosening the escape threshold. `open-end` once flagged the leviathan's front door
  //   and a later pass bricked up the interior — never again.
  //
  //   THE DISCRIMINATOR: every escape is re-cast with the cave materials temporarily forced to
  //   DoubleSide (probe-local, restored immediately — this is diagnosis, never a fix). An escape
  //   that becomes a HIT means the surface EXISTS but is back-face-culled from this side — the
  //   interpenetrating-zero-thickness-shell root cause. An escape that still misses means there
  //   is a genuine HOLE (a carve with no plug). The split localises the defect for the remesh.
  //
  //   Run: npm run rig -- --scenario=cave-void --port=5230 [--seed=1337]
  //
  //   DEEPER cycle 8 — REUSED, NOT FORKED (same reasoning as `cave-walk`): `cave-streamed` void-
  //   samples STREAMED caves through this identical sweep by passing `opts.residentKey`. Only the
  //   mesh set changes; the Fibonacci sphere, the declared-opening allowance, the DoubleSide /
  //   FrontSide discriminators, the vacuous-pass guard and the tally are shared code.
  'cave-void': async (page, opts = {}) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      try { ctx.sandWorms.list.length = 0; } catch {}
      try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.42);
      ctx.three.renderer.setSize(1100, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 720; cam.updateProjectionMatrix(); }
    });

    const r = await page.evaluate((ARGS) => {
      const PUNCTURE = ARGS.puncture, KEY = ARGS.residentKey;
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
      const FAR = 400;              // far past the cave AABB — no hit inside this = out of the world
      const K = 96;                 // rays per sample point (Fibonacci sphere)
      const EYE = 1.68;             // player eye height above the floor

      // WHICH CAVE — see the note on `cave-walk`. Once caves stream, scene traversal picks whichever
      // `caveGen` group came last; a resident key is the only unambiguous handle. Taking the mesh set
      // from the resident record also keeps the sweep HONEST for a streamed cave: it is sampled
      // against its OWN shell alone, so a ray that leaves it cannot be silently stopped by some other
      // cave's geometry kilometres away.
      let caveGroup = null, boreGroup = null, cavep = null;
      if (KEY) {
        const res = (ctx.caveStream ? ctx.caveStream.residents() : []).find((x) => x.key === KEY);
        if (!res) return { fatal: `no resident cave keyed ${KEY} — it never streamed in` };
        caveGroup = res.cave.group; cavep = res.cave.probe;
        boreGroup = res.entrance ? res.entrance.group : null;
      } else {
        ctx.three.scene.traverse((o) => {
          if (o.name === 'caveGen') caveGroup = o;
          if (o.name === 'caveEntrance') boreGroup = o;
          if (o.userData && o.userData.caveGenProbe) cavep = o.userData.caveGenProbe;
        });
      }
      if (!caveGroup || !cavep) return { fatal: 'no caveGen group / caveGenProbe (cave not built — flag off?)' };

      // The cave mesh set = the generated cave + the entrance bore (so entrance-hall rays can
      // legitimately terminate on the trench walls rather than false-flagging).
      const meshes = [];
      const collect = (root) => { if (!root) return; root.updateMatrixWorld(true); root.traverse((o) => { if (o.isMesh && o.visible) meshes.push(o); }); };
      collect(caveGroup); collect(boreGroup);

      // ── THE TEETH PROOF (`--puncture=P`). A gate that can only ever pass is worse than no gate.
      //    This deliberately deletes P% of the cave body's triangles BEFORE the sweep — a synthetic
      //    see-through defect. The gate MUST go red. Diagnostic only; never used by verify:*. ──
      if (PUNCTURE > 0) {
        for (const m of meshes) {
          if (!m.userData || !m.userData.caveSdf || !m.geometry.index) continue;
          const src = m.geometry.index.array;
          const keep = [];
          for (let t = 0; t < src.length; t += 3) {
            if ((t / 3) % Math.max(2, Math.round(100 / PUNCTURE)) === 0) continue;   // drop ~P% of faces
            keep.push(src[t], src[t + 1], src[t + 2]);
          }
          m.geometry.setIndex(keep);
        }
      }

      // Declared openings, WORLD space — verify-solid.mjs:268 precedent.
      const openings = [];
      for (const root of [caveGroup, boreGroup]) {
        if (!root) continue;
        root.traverse((o) => {
          const io = o.userData && o.userData.intendedOpening;
          if (!io) return;
          const c = new THREE.Vector3(io.center.x, io.center.y, io.center.z).applyMatrix4(o.matrixWorld);
          const s = new THREE.Vector3().setFromMatrixScale(o.matrixWorld);
          openings.push({ c, r: io.radius * Math.max(s.x, s.y, s.z), by: o.name || o.type });
        });
      }
      // A ray is EXCUSED iff it passes through a declared opening sphere going FORWARD.
      const _oc = new THREE.Vector3();
      const throughOpening = (origin, dir) => {
        for (const op of openings) {
          _oc.subVectors(op.c, origin);
          const t = _oc.dot(dir);
          if (t <= 0) continue;                             // opening is behind the ray
          const perp2 = _oc.lengthSq() - t * t;
          if (perp2 <= op.r * op.r) return op.by;
        }
        return null;
      };

      // Fibonacci sphere — K uniformly-spread directions.
      const dirs = [];
      const ga = Math.PI * (3 - Math.sqrt(5));
      for (let i = 0; i < K; i++) {
        const y = 1 - (i / (K - 1)) * 2;
        const rr = Math.sqrt(Math.max(0, 1 - y * y));
        const th = ga * i;
        dirs.push(new THREE.Vector3(Math.cos(th) * rr, y, Math.sin(th) * rr).normalize());
      }

      // ── Sample points: every chamber (centre + 4 offsets at 0.5·rx) + every corridor (3 along-axis). ──
      const nodes = cavep.nodes, byId = (id) => nodes.find((n) => n.id === id);
      const pts = [];
      for (const n of nodes) {
        const eye = Math.min(EYE, Math.max(0.8, n.height * 0.5));
        pts.push({ label: `chamber${n.id}:${n.kind}:c`, kind: 'chamber', node: n.id, p: new THREE.Vector3(n.x, n.y + eye, n.z) });
        for (let q = 0; q < 4; q++) {
          const a = (q / 4) * Math.PI * 2 + n.id * 0.37;
          pts.push({
            label: `chamber${n.id}:${n.kind}:o${q}`, kind: 'chamber', node: n.id,
            p: new THREE.Vector3(n.x + Math.cos(a) * n.rx * 0.5, n.y + eye, n.z + Math.sin(a) * n.rx * 0.5),
          });
        }
      }
      // ── CORRIDOR SAMPLE POINTS SIT ON THE CLEAR SPAN, NOT THE CENTRE-TO-CENTRE SPAN. ────────
      //   DEEPER cycle 9 fixed this, and the fix is a GATE-CORRECTNESS fix, not a loosened
      //   threshold — the sibling gate already had it, with the same reasoning written down:
      //   `cave-walk`'s corridor sweep samples `sA = a.rx - OV` to `sB = D - (b.rx - OV)` because
      //   "measuring through the chamber interiors gives false gaps (flat chamber floor != the
      //   linear ramp)". The void sweep never got the same treatment, and on canonical geometry it
      //   did not matter: with rx ~4-9 against a ~20m run, t=0.25 lands close enough to the mouth
      //   that the linear floor estimate is still inside open air.
      //
      //   The `fungal` kind broke that coincidence. Its chambers reach rx 12 against a 9m minimum
      //   clear span, so t=0.25 of the centre-to-centre span lands 7m INSIDE the chamber — where the
      //   floor is the chamber's FLAT disk, not the corridor's ramp. The estimate `a.y + (b.y-a.y)·t`
      //   then puts the sample point up to ~1.5m BELOW the real floor, i.e. inside solid rock, and
      //   ~45% of its ray sphere leaves through the underside. That is what seeds 7 and 4242 reported
      //   as `corridorEsc=83 / holes=83 / frontEsc=83` at exactly one or two corridor points: a
      //   measurement artefact with the signature of one (all-front-face, all classified holes, all
      //   in corridors, none in chambers).
      //
      //   The fix places every corridor point on the span the corridor's own floor actually spans,
      //   which is also the only stretch a player walks as a corridor. It REMOVES a false positive;
      //   it removes no true positive, because the chamber interiors those points were straying into
      //   are already sampled by five chamber points each. `--puncture` remains the proof-of-teeth.
      const OV_VOID = 1.2;   // CAVE_GEN_END_OVERLAP — matches cave-walk's corridor sweep exactly
      for (const e of cavep.edges) {
        const a = byId(e.a), b = byId(e.b);
        const eye = Math.min(EYE, Math.max(0.7, e.height * 0.45));
        const D = Math.hypot(b.x - a.x, b.z - a.z) || 1;
        const sA = Math.max(0, a.rx - OV_VOID), sB = Math.min(D, D - (b.rx - OV_VOID));
        // A degenerate clear span (chambers nearly touching) falls back to the midpoint rather than
        // silently emitting nothing — a corridor that stops being sampled is a gate losing teeth.
        const lo = sB > sA ? sA : D * 0.5, hi = sB > sA ? sB : D * 0.5;
        for (const t of [0.25, 0.5, 0.75]) {
          const along = lo + (hi - lo) * t;
          const u = along / D;
          pts.push({
            label: `corridor${e.a}-${e.b}${e.squeeze ? ':sq' : ':gal'}@${t}`, kind: 'corridor', node: e.a,
            p: new THREE.Vector3(a.x + (b.x - a.x) * u, a.y + (b.y - a.y) * u + eye, a.z + (b.z - a.z) * u),
          });
        }
      }

      const rc = new THREE.Raycaster();
      rc.far = FAR;
      const sweep = () => {
        const res = [];
        for (const sp of pts) {
          const esc = [];
          for (let d = 0; d < dirs.length; d++) {
            rc.set(sp.p, dirs[d]);
            const hits = rc.intersectObjects(meshes, false);
            if (hits.length === 0) esc.push(d);
          }
          res.push(esc);
        }
        return res;
      };

      // Pass 1 — renderer-faithful (materials exactly as they ship).
      const escRender = sweep();

      // Pass 2 + 3 — the DISCRIMINATORS. Re-sweep with every cave material forced DoubleSide, then
      // FrontSide; restore. DoubleSide separates "the surface exists but is culled from here" from
      // "there is a genuine hole". FrontSide answers the sharper question: is the SHIPPING side
      // simply INVERTED relative to the triangle winding? (If FrontSide is near-clean where the
      // shipping BackSide leaks, the shells are wound normals-inward and BackSide culls exactly the
      // faces the player is standing behind.) Probe-local, restored immediately — diagnosis, not a fix.
      const mats = new Set();
      for (const m of meshes) { const mm = Array.isArray(m.material) ? m.material : [m.material]; for (const x of mm) if (x) mats.add(x); }
      const saved = [...mats].map((m) => ({ m, side: m.side }));
      for (const s of saved) s.m.side = THREE.DoubleSide;
      const escBoth = sweep();
      for (const s of saved) s.m.side = THREE.FrontSide;
      const escFront = sweep();
      for (const s of saved) s.m.side = s.side;
      let frontEscapes = 0;
      for (const e of escFront) frontEscapes += e.length;

      // ── Tally ──
      let totalRays = 0, escapes = 0, excused = 0, culled = 0, holes = 0;
      const rows = [];
      for (let i = 0; i < pts.length; i++) {
        const sp = pts[i];
        const setBoth = new Set(escBoth[i]);
        let sEsc = 0, sExc = 0, sCul = 0, sHole = 0;
        for (const d of escRender[i]) {
          if (throughOpening(sp.p, dirs[d])) { sExc++; continue; }
          sEsc++;
          if (setBoth.has(d)) sHole++; else sCul++;    // still escapes with DoubleSide = real hole
        }
        totalRays += dirs.length; escapes += sEsc; excused += sExc; culled += sCul; holes += sHole;
        let sFront = 0;
        for (const d of escFront[i]) if (!throughOpening(sp.p, dirs[d])) sFront++;
        rows.push({
          label: sp.label, kind: sp.kind, esc: sEsc, exc: sExc, culled: sCul, hole: sHole, front: sFront,
          pct: +((sEsc / dirs.length) * 100).toFixed(1),
          p: [+sp.p.x.toFixed(1), +sp.p.y.toFixed(1), +sp.p.z.toFixed(1)],
          // the worst escape direction from this point (first unexcused), for the visual shot
          dir: (() => { for (const d of escRender[i]) if (!throughOpening(sp.p, dirs[d])) return [+dirs[d].x.toFixed(3), +dirs[d].y.toFixed(3), +dirs[d].z.toFixed(3)]; return null; })(),
        });
      }
      // ── THE VACUOUS-PASS GUARD. The worst possible outcome of this gate is that it goes green
      //    because it silently sampled NOTHING (a probe that finds no chambers/corridors, or a graph
      //    read that returns an empty node list, would report escapes=0 and look like a fix). A cave
      //    always has ≥8 chambers → ≥40 chamber points; refuse to report a pass below that. ──
      if (pts.length < 40 || totalRays === 0) {
        return { fatal: `vacuous sweep — ${pts.length} sample points / ${totalRays} rays (expected ≥40 points). The gate would have passed by measuring nothing.` };
      }
      rows.sort((a, b) => b.esc - a.esc);
      const chamRows = rows.filter((x) => x.kind === 'chamber'), corRows = rows.filter((x) => x.kind === 'corridor');
      const sum = (a, k) => a.reduce((s, x) => s + x[k], 0);

      return {
        sdfStats: caveGroup.userData.caveSdfStats || null,
        sdfBench: caveGroup.userData.caveSdfBench || null,
        shellTris: cavep.triCount, colliderTris: cavep.colliderTris, msCollider: cavep.msCollider, msMesh: cavep.msMesh,
        seed: ctx.seed, digest: cavep.digest, meshes: meshes.length,
        points: pts.length, K: dirs.length, totalRays,
        escapes, excused, culled, holes,
        frontEscapes, frontRate: +((frontEscapes / totalRays) * 100).toFixed(2),
        escapeRate: +((escapes / totalRays) * 100).toFixed(2),
        leakyPoints: rows.filter((x) => x.esc > 0).length,
        chamberEscapes: sum(chamRows, 'esc'), corridorEscapes: sum(corRows, 'esc'),
        chamberRays: chamRows.length * dirs.length, corridorRays: corRows.length * dirs.length,
        chamberFront: sum(chamRows, 'front'), corridorFront: sum(corRows, 'front'),
        chamberHoles: sum(chamRows, 'hole'), corridorHoles: sum(corRows, 'hole'),
        openings: openings.map((o) => ({ by: o.by, c: [+o.c.x.toFixed(1), +o.c.y.toFixed(1), +o.c.z.toFixed(1)], r: +o.r.toFixed(1) })),
        worst: rows.slice(0, 14),
      };
    }, { puncture: Number(argv.puncture || 0), residentKey: opts.residentKey ?? null });

    if (r.fatal) {
      console.log(`CAVE-VOID FAIL ${r.fatal}`);
      if (opts.noThrow) return r;
      throw new Error('cave-void FAILED');
    }
    const pass = r.escapes === 0;
    console.log(`CAVE-VOID pass=${pass ? 1 : 0} seed=${r.seed} digest=${r.digest} points=${r.points} rays=${r.totalRays} escapes=${r.escapes} rate=${r.escapeRate}% leakyPoints=${r.leakyPoints}/${r.points} culled=${r.culled} holes=${r.holes} excused=${r.excused} chamberEsc=${r.chamberEscapes} corridorEsc=${r.corridorEscapes} meshes=${r.meshes} frontEsc=${r.frontEscapes} frontRate=${r.frontRate}%`);
    console.log(`[cave-void] SPLIT chambers ${r.chamberEscapes}/${r.chamberRays} (${(100*r.chamberEscapes/r.chamberRays).toFixed(1)}%) back, ${r.chamberFront}/${r.chamberRays} (${(100*r.chamberFront/r.chamberRays).toFixed(1)}%) front, holes ${r.chamberHoles} | corridors ${r.corridorEscapes}/${r.corridorRays} (${(100*r.corridorEscapes/r.corridorRays).toFixed(1)}%) back, ${r.corridorFront}/${r.corridorRays} (${(100*r.corridorFront/r.corridorRays).toFixed(1)}%) front, holes ${r.corridorHoles}`);
    console.log(`[cave-void] declared openings: ${JSON.stringify(r.openings)}`);
    console.log(`[cave-void] BAKE COST: colliderTris=${r.colliderTris} rapierTrimeshBake=${r.msCollider}ms polygonize=${r.msMesh}ms`);
    if (r.sdfStats) console.log(`[cave-void] SDF remesh: voxel=${r.sdfStats.voxel}m dims=${r.sdfStats.dims.join('x')} evaluated=${r.sdfStats.samples}/${r.sdfStats.gridSamples} verts=${r.sdfStats.verts} tris=${r.sdfStats.tris} | field=${r.sdfStats.msField}ms nets=${r.sdfStats.msNets}ms normals=${r.sdfStats.msNormals}ms TOTAL=${r.sdfStats.msTotal}ms (whole-cave tri incl. dressing=${r.shellTris})`);
    if (r.sdfBench) for (const s of r.sdfBench) console.log(`[cave-void] SDF-BENCH voxel=${String(s.voxel).padEnd(5)} dims=${s.dims.join('x').padEnd(14)} tris=${String(s.tris).padStart(7)} verts=${String(s.verts).padStart(7)} field=${String(s.msField).padStart(7)}ms nets=${String(s.msNets).padStart(6)}ms total=${String(s.msTotal).padStart(7)}ms`);
    for (const w of r.worst) console.log(`[cave-void] ${w.label.padEnd(28)} esc=${String(w.esc).padStart(3)}/${r.K} (${w.pct}%) culled=${w.culled} hole=${w.hole} front=${w.front} excused=${w.exc} at ${JSON.stringify(w.p)}`);

    // ── The VISUAL: stand at the leakiest sample point, at player eye height, and look down the
    //    escape direction. Two shots per spot: (a) lit — what the player sees; (b) the same frame
    //    with the scene background flat MAGENTA and fog off, so every escaping pixel is unmistakable.
    //    NOTE (declared in the report): the cave ships near-black, so these shots ADD a fill light
    //    and raise exposure purely for legibility. The geometry/culling is untouched. ──
    // (With `opts.noShots` — the streamed legs — the numbers above are the whole verdict; on a RED
    //  streamed sweep, re-run that one site on its own to get the pictures.)
    const shots = opts.noShots ? [] : r.worst.filter((w) => w.dir).slice(0, 3);
    for (let i = 0; i < shots.length; i++) {
      const w = shots[i];
      for (const magenta of [false, true]) {
        await page.evaluate((s) => {
          const ctx = window.__game.ctx; const THREE = window.__game.THREE;
          const cam = ctx.three.camera; const L = ctx.lights;
          const fg = ctx.three.scene.fog;
          window.__voidRestore = { bg: ctx.three.scene.background, fog: fg, fogD: fg ? fg.density : 0, amb: L.ambient.intensity, sun: L.sun.intensity, exp: ctx.three.renderer.toneMappingExposure };
          // Kill fog by DENSITY, not by nulling scene.fog — caveAtmosphere writes fog.density every
          // frame and a null fog spams "Cannot set properties of null" through the probe log.
          if (fg && 'density' in fg) fg.density = 0; else ctx.three.scene.fog = null;
          if (s.magenta) ctx.three.scene.background = new THREE.Color(0xff00ff);
          L.ambient.intensity = 0.9; L.sun.intensity = 0;
          ctx.three.renderer.toneMappingExposure = 1.4;
          let fill = window.__voidFill;
          if (!fill) { fill = new THREE.PointLight(0xffe6c4, 40, 60); window.__voidFill = fill; ctx.three.scene.add(fill); }
          fill.position.set(s.p[0], s.p[1] + 0.6, s.p[2]); fill.intensity = 40; fill.visible = true;
          cam.position.set(s.p[0], s.p[1], s.p[2]);
          cam.lookAt(s.p[0] + s.d[0] * 10, s.p[1] + s.d[1] * 10, s.p[2] + s.d[2] * 10);
          cam.updateMatrixWorld(true);
          ctx.three.renderer.render(ctx.three.scene, cam);
        }, { p: w.p, d: w.dir, magenta });
        await page.waitForTimeout(200);
        const nm = `${i}-${w.label.replace(/[^a-z0-9]+/gi, '_')}${magenta ? '-VOID' : '-lit'}`;
        try { await page.screenshot({ path: join(OUT, `scen-cave-void-${nm}.png`), fullPage: false, timeout: 60000 }); console.log(`[cave-void] saved scen-cave-void-${nm}.png`); }
        catch (e) { console.log(`[cave-void] ${nm} shot flaked (${e.name})`); }
        await page.evaluate(() => {
          const ctx = window.__game.ctx; const st = window.__voidRestore; if (!st) return;
          ctx.three.scene.background = st.bg; ctx.three.scene.fog = st.fog;
          if (st.fog && 'density' in st.fog) st.fog.density = st.fogD;
          ctx.lights.ambient.intensity = st.amb; ctx.lights.sun.intensity = st.sun;
          ctx.three.renderer.toneMappingExposure = st.exp;
          if (window.__voidFill) window.__voidFill.visible = false;
          window.__voidRestore = null;
        });
      }
    }

    if (!pass && !opts.noThrow) throw new Error('cave-void GATE FAILED');
    return r;
  },

  'drop-test': async (page) => {
    const ids = await page.evaluate(() => {
      const g = window.__game; g.enterGame(true);
      g.ctx.flags.paused = false;
      return {
        capsule: g.dropTestItem('pipe_staff'),
        sphere: g.dropTestItem('canteen'),
        rifle: g.dropTestItem('amban_rifle'),
        box: g.dropTestItem('scrap_bar'),   // no hint → default cuboid (control)
      };
    });
    await page.waitForTimeout(4000);   // let the bodies fall + settle
    const after = await page.evaluate((ids) => {
      const ctx = window.__game.ctx;
      const read = (id) => {
        const p = ctx.pickups.list.find((pp) => pp.id === id);
        if (!p || !p.body) return { ok: false };
        const t = p.body.translation();
        const finite = Number.isFinite(t.x) && Number.isFinite(t.y) && Number.isFinite(t.z);
        const gy = ctx.terrain.heightAt(t.x, t.z);
        return { ok: true, finite, dy: +(t.y - gy).toFixed(2), settled: finite && Math.abs(t.y - gy) < 1.0 };
      };
      const out = {};
      for (const k in ids) out[k] = read(ids[k]);
      return out;
    }, ids);
    const allOk = Object.values(after).every((r) => r.ok && r.finite && r.settled);
    console.log(`[drop-test] ${allOk ? 'PASS' : 'FAIL'} ${JSON.stringify(after)}`);
  },

  // Scavenger's Economy (build 2) — MATERIAL PICKUP + ICON probe. Spawns the four
  // new salvage-material WORLD pickups (spawnMaterialTest → the streamed-scatter
  // path) in a row in front of the player, asserts each builds a non-degenerate
  // mesh + carries the right itemId (what E-take grants), takes them via the real
  // acquire path (giveItem = addItem) so the ItemId lands in inventory, and puts
  // the four in the (cleared) hotbar so their makeIcon glyphs render for a
  // screenshot. Screenshots the game view (ground pickups + hotbar icons).
  'material-probe': async (page) => {
    const IDS = ['metal_pipe', 'machine_part', 'wiring', 'battery'];
    const r = await page.evaluate((IDS) => {
      const g = window.__game; g.enterGame(true);
      const ctx = g.ctx;
      ctx.weather.intensity = 0; g.setTime(0.42);
      ctx.three.renderer.toneMappingExposure = 1.15;
      ctx.flags.paused = false;
      // Clear the dev loadout so the 4 materials land in the 4 hotbar slots (icons).
      for (const s of ctx.inventory.slots) { s.item = null; s.count = 0; s.meta = undefined; }
      for (const s of ctx.inventory.backpack) { s.item = null; s.count = 0; s.meta = undefined; }
      const world = {};
      let off = -2.1;
      for (const id of IDS) {
        const pid = g.spawnMaterialTest(id, off); off += 1.4;
        const p = ctx.pickups.list.find((pp) => pp.id === pid);
        const geo = p && p.mesh && p.mesh.geometry;
        let sz = null;
        if (geo) { geo.computeBoundingBox(); const b = geo.boundingBox; sz = { x: +(b.max.x - b.min.x).toFixed(3), y: +(b.max.y - b.min.y).toFixed(3), z: +(b.max.z - b.min.z).toFixed(3) }; }
        world[id] = {
          spawned: !!p,
          itemIdMatches: !!p && p.itemId === id,          // what E-take would grant
          meshNonZero: !!sz && sz.x > 0.02 && sz.y > 0.02 && sz.z > 0.02,
          sz,
        };
      }
      // Take path: the four via the REAL acquire path (giveItem = addItem, exactly
      // what interaction.ts calls on E), landing them in the cleared hotbar.
      for (const id of IDS) g.giveItem(id, 1);
      const inv = {};
      for (const id of IDS) {
        inv[id] = ctx.inventory.slots.concat(ctx.inventory.backpack)
          .filter((s) => s.item === id).reduce((a, s) => a + s.count, 0);
      }
      // Icons: after giveItem, the hotbar DOM re-renders makeIcon SVGs into its
      // slots. Count the rendered <svg> nodes in the hotbar (>0 = icons render).
      const hotbarSvgs = document.querySelectorAll('#hotbar svg').length;
      return { world, inv, hotbarSvgs };
    }, IDS);
    await page.waitForTimeout(600);
    await page.screenshot({ path: join(OUT, 'scen-material-probe.png'), fullPage: false, timeout: 60000 });
    const worldOk = IDS.every((id) => r.world[id].spawned && r.world[id].itemIdMatches && r.world[id].meshNonZero);
    const takeOk = IDS.every((id) => r.inv[id] === 1);
    const pass = worldOk && takeOk;
    console.log(`[material-probe] ${pass ? 'PASS' : 'FAIL'} (world=${worldOk} take=${takeOk}) ${JSON.stringify(r)}`);
  },

  // WALK-TEST FIX (2026-07-17) — ORIGIN-WORLD ground-scatter gate. Proves the fresh
  // boot world (not the streamed far field) has IDENTITY MATERIAL pickups on the
  // ground around wrecks/POIs, not just scrap. Buckets every material pickup by its
  // nearest salvageable (attributed to that wreck's archetype, or kind:* for the
  // generic hulls), prints per-POI-type counts, and PASSES when ≥3 distinct POI
  // types carry materials INCLUDING at least one GENERIC wreck (a kind:* / generic
  // hull) — the "every wreck teaches materials exist" contract. Then frames the
  // richest origin wreck so the ground materials are visible in a screenshot.
  'material-scatter': async (page) => {
    const MATS = ['metal_pipe', 'machine_part', 'wiring', 'battery'];
    const GENERIC_ARCH = ['derelict', 'hollow_husk', 'enterable_wreck', 'crash_husk', 'ship'];
    const r = await page.evaluate(({ MATS, GENERIC_ARCH }) => {
      const g = window.__game; const ctx = g.ctx;
      const matSet = new Set(MATS);
      // Archetype from a salvageable mesh's ancestry (poiAssembler stamps
      // group.userData.poiArchetype; legacy/anchor/hero wrecks have none).
      const archOf = (obj) => { for (let o = obj; o; o = o.parent) { const a = o.userData && o.userData.poiArchetype; if (typeof a === 'string') return a; } return null; };
      // Bucket label per wreck: archetype id, else kind:<salvageKind>. Filter
      // TRANSIENT (chunk-streamed) salvageables so this measures the BOOT origin
      // world exactly — not far-field content streamed in once the player entered.
      const salv = ctx.salvageables.list.filter((s) => !s.transient).map((s) => {
        const a = archOf(s.mesh);
        const label = a || ('kind:' + s.kind);
        const generic = !a || GENERIC_ARCH.indexOf(a) >= 0 || label.indexOf('kind:') === 0;
        return { x: s.pos.x, z: s.pos.z, label, generic };
      });
      const perType = {};   // label -> {metal_pipe,machine_part,wiring,battery,total,generic}
      let orphan = 0;       // materials with no salvageable within radius
      let best = null;      // richest wreck (most nearby materials) for the shot
      const nearby = new Map();
      const RADIUS = 22;    // ≥ the massive scrap-ring max; nearest wins on overlap
      for (const p of ctx.pickups.list) {
        if (!matSet.has(p.itemId) || p.transient) continue;   // boot materials only (not streamed)
        let bi = -1, bd = RADIUS * RADIUS;
        for (let i = 0; i < salv.length; i++) {
          const dx = p.pos.x - salv[i].x, dz = p.pos.z - salv[i].z;
          const d = dx * dx + dz * dz;
          if (d < bd) { bd = d; bi = i; }
        }
        if (bi < 0) { orphan++; continue; }
        const s = salv[bi];
        const b = perType[s.label] || (perType[s.label] = { metal_pipe: 0, machine_part: 0, wiring: 0, battery: 0, total: 0, generic: s.generic });
        b[p.itemId]++; b.total++;
        nearby.set(bi, (nearby.get(bi) || 0) + 1);
      }
      for (const [i, n] of nearby) if (!best || n > best.n) best = { i, n, x: salv[i].x, z: salv[i].z, label: salv[i].label };
      // Frame the richest wreck: camera up-and-back, looking down at the ground ring.
      if (best) {
        ctx.weather.intensity = 0; g.setTime(0.42);
        ctx.three.renderer.toneMappingExposure = 1.15;
        ctx.flags.paused = true;
        const gy = ctx.terrain.heightAt(best.x, best.z);
        const cam = ctx.three.camera;
        cam.position.set(best.x + 6, gy + 4.2, best.z + 6);
        cam.lookAt(best.x, gy + 0.1, best.z);
        cam.updateMatrixWorld(true);
      }
      const totalMats = ctx.pickups.list.filter((p) => matSet.has(p.itemId) && !p.transient).length;
      const typesWithMats = Object.keys(perType).length;
      const genericTypes = Object.keys(perType).filter((k) => perType[k].generic);
      return { perType, orphan, totalMats, typesWithMats, genericTypes, best };
    }, { MATS, GENERIC_ARCH });
    await page.waitForTimeout(500);
    await page.screenshot({ path: join(OUT, 'scen-material-scatter.png'), fullPage: false, timeout: 60000 });
    // Per-type table.
    const rows = Object.entries(r.perType).sort((a, b) => b[1].total - a[1].total);
    console.log(`[material-scatter] ${r.totalMats} material pickups in the origin world across ${r.typesWithMats} POI types (orphan=${r.orphan}):`);
    for (const [label, b] of rows) {
      console.log(`  ${label.padEnd(18)} total=${String(b.total).padStart(3)} ${b.generic ? '[generic]' : '[specialty]'}  pipe=${b.metal_pipe} part=${b.machine_part} wiring=${b.wiring} batt=${b.battery}`);
    }
    const enough = r.typesWithMats >= 3;
    const hasGeneric = r.genericTypes.length > 0;
    const pass = enough && hasGeneric && r.totalMats > 0;
    console.log(`[material-scatter] ${pass ? 'PASS' : 'FAIL'} — ≥3 POI types with materials: ${enough} (${r.typesWithMats}); includes a generic wreck: ${hasGeneric} (${r.genericTypes.join(',') || 'none'})`);
    if (r.best) console.log(`[material-scatter] shot framed on richest wreck "${r.best.label}" (${r.best.n} materials nearby) → verification/scen-material-scatter.png`);
  },

  // Crafting rework — PICKUP-GATED discovery gate (replaces the old craft-chooser
  //   gate). A recipe unlocks once ALL its ingredient TYPES have been collected
  //   (any means — pickup/craft/loot, all via addItem). Runs NON-dev (enterGame(false),
  //   clean empty inventory) so the real cold→warm→unlocked progression is exercised:
  //     - machete (id 19, scrap×2+cloth×1): cold → +scrap = warm → +cloth = unlocked.
  //     - fire_kit (id 2) + signal_flare (id 18) share branch×3+scrap×1 — the old
  //       collision now unlocks as TWO independent cards on the same ingredient set.
  //     - sled_kit (id 9, scrap+branch+ROPE): rope is CRAFTED not picked up, so
  //       obtaining a rope (real acquire path) is what flips sled cold/warm → unlocked.
  'craft-unlock': async (page) => {
    const r = await page.evaluate(() => {
      const g = window.__game;
      // enterLive() already handed off in DEV mode, whose loadout pre-discovers
      // every recipe + seeds the collected-type ledger. Reset both to a clean
      // new-game baseline so the pickup-gated progression is exercised honestly.
      // (Dev items left in the bag are irrelevant — craftCardState reads only
      // the discovered + collected ledgers, not bag counts.)
      g.ctx.inventory.discoveredRecipes.length = 0;
      g.ctx.inventory.collectedItemTypes.clear();
      const MACHETE = 19, FIRE = 2, SIGNAL = 18, SLED = 9;
      const out = {};
      out.start = { machete: g.craftCardState(MACHETE), fire: g.craftCardState(FIRE) };
      g.giveItem('scrap', 1);
      out.afterScrap = { machete: g.craftCardState(MACHETE) };
      g.giveItem('cloth', 1);
      out.afterCloth = { machete: g.craftCardState(MACHETE) };
      g.giveItem('branch', 1);
      out.afterBranch = { fire: g.craftCardState(FIRE), signal: g.craftCardState(SIGNAL) };
      // Scavenger's Economy (build 3) — sled_kit now also needs metal_pipe. Give it
      // FIRST so the chain still proves "the CRAFTED rope is what flips warm→unlocked".
      g.giveItem('metal_pipe', 1);
      out.sledBefore = g.craftCardState(SLED);           // warm — pipe+scrap+branch collected, no rope
      g.giveItem('rope', 1);                             // simulate crafting a rope
      out.sledAfter = g.craftCardState(SLED);            // unlocked — crafted-ingredient chain
      return out;
    });
    const s = r || {};
    const coldStart = s.start && s.start.machete.state === 'cold' && !s.start.machete.discovered
      && s.start.fire.state === 'cold';
    const warmScrap = s.afterScrap && s.afterScrap.machete.state === 'warm' && !s.afterScrap.machete.discovered;
    const unlockedCloth = s.afterCloth && s.afterCloth.machete.state === 'unlocked' && s.afterCloth.machete.discovered;
    const collision = s.afterBranch
      && s.afterBranch.fire.state === 'unlocked' && s.afterBranch.fire.discovered
      && s.afterBranch.signal.state === 'unlocked' && s.afterBranch.signal.discovered;
    const chain = s.sledBefore && s.sledBefore.state === 'warm'
      && s.sledAfter && s.sledAfter.state === 'unlocked' && s.sledAfter.discovered;

    // ── Scavenger's Economy (build 3) — new/updated recipe craft gate. Proves:
    //   • the 3 NEW recipes (pipe_staff 21, scrap_gun 22, worm_lure 23) unlock on
    //     collecting their inputs, craft through the REAL craft path, CONSUME the
    //     right inputs, and YIELD the output.
    //   • worm_lure's "raw meat" input is ANY-OF (raw_shrew_meat satisfies it).
    //   • flashlight (5) now requires battery+wiring+scrap — the OLD scrap×2+cloth
    //     must NOT unlock or craft it.
    const eco = await page.evaluate(async () => {
      const g = window.__game;
      const inv = g.ctx.inventory;
      const count = (id) => {
        let n = 0;
        for (const s of [...inv.slots, ...inv.backpack]) {
          if (s.item === id && s.count > 0 && !s.meta) n += s.count;
        }
        return n;
      };
      const reset = () => { inv.discoveredRecipes.length = 0; inv.collectedItemTypes.clear();
        for (const s of [...inv.slots, ...inv.backpack]) { s.item = null; s.count = 0; s.meta = undefined; } };
      const PIPE = 21, GUN = 22, LURE = 23, FLASH = 5;
      const out = {};

      // — NEW recipes: grant the full material spread + rope/cloth/scrap. —
      reset();
      for (const [id, n] of [['metal_pipe',2],['machine_part',1],['wiring',1],['battery',1],
                             ['scrap',2],['cloth',1],['rope',1],['raw_shrew_meat',1]]) g.giveItem(id, n);
      out.states = { pipe: g.craftCardState(PIPE), gun: g.craftCardState(GUN), lure: g.craftCardState(LURE) };

      // pipe_staff — consumes metal_pipe+cloth+rope, yields pipe_staff.
      const pipeBefore = { pipe: count('metal_pipe'), cloth: count('cloth'), rope: count('rope'), out: count('pipe_staff') };
      out.pipeCraft = await g.craft(PIPE);
      out.pipeAfter = { pipe: count('metal_pipe'), cloth: count('cloth'), rope: count('rope'), out: count('pipe_staff'), before: pipeBefore };

      // scrap_gun — consumes metal_pipe+machine_part+scrap, yields scrap_gun.
      const gunBefore = { pipe: count('metal_pipe'), mp: count('machine_part'), scrap: count('scrap'), out: count('scrap_gun') };
      out.gunCraft = await g.craft(GUN);
      out.gunAfter = { pipe: count('metal_pipe'), mp: count('machine_part'), scrap: count('scrap'), out: count('scrap_gun'), before: gunBefore };

      // worm_lure — consumes battery+wiring+ANY raw meat (raw_shrew_meat here), yields worm_lure.
      const lureBefore = { batt: count('battery'), wire: count('wiring'), shrew: count('raw_shrew_meat'), out: count('worm_lure') };
      out.lureCraft = await g.craft(LURE);
      out.lureAfter = { batt: count('battery'), wire: count('wiring'), shrew: count('raw_shrew_meat'), out: count('worm_lure'), before: lureBefore };

      // — flashlight negative: OLD recipe (scrap×2 + cloth) must NOT make it. —
      reset();
      g.giveItem('scrap', 2); g.giveItem('cloth', 1);
      out.flashOld = { state: g.craftCardState(FLASH), craft: await g.craft(FLASH) };
      // — flashlight positive: battery+wiring+scrap DOES. —
      reset();
      g.giveItem('battery', 1); g.giveItem('wiring', 1); g.giveItem('scrap', 1);
      const flBefore = { batt: count('battery'), wire: count('wiring'), scrap: count('scrap'), out: count('flashlight') };
      out.flashNewState = g.craftCardState(FLASH);
      out.flashNewCraft = await g.craft(FLASH);
      out.flashNewAfter = { batt: count('battery'), wire: count('wiring'), scrap: count('scrap'), out: count('flashlight'), before: flBefore };
      return out;
    });

    const e = eco || {};
    const newUnlocked = e.states
      && e.states.pipe.state === 'unlocked' && e.states.pipe.discovered
      && e.states.gun.state === 'unlocked' && e.states.gun.discovered
      && e.states.lure.state === 'unlocked' && e.states.lure.discovered;
    const pipeOk = e.pipeCraft && e.pipeCraft.crafted && e.pipeCraft.output === 'pipe_staff'
      && e.pipeAfter.out === 1 && e.pipeAfter.pipe === e.pipeAfter.before.pipe - 1
      && e.pipeAfter.cloth === e.pipeAfter.before.cloth - 1 && e.pipeAfter.rope === e.pipeAfter.before.rope - 1;
    const gunOk = e.gunCraft && e.gunCraft.crafted && e.gunCraft.output === 'scrap_gun'
      && e.gunAfter.out === 1 && e.gunAfter.pipe === e.gunAfter.before.pipe - 1
      && e.gunAfter.mp === e.gunAfter.before.mp - 1 && e.gunAfter.scrap === e.gunAfter.before.scrap - 1;
    const lureOk = e.lureCraft && e.lureCraft.crafted && e.lureCraft.output === 'worm_lure'
      && e.lureAfter.out === 1 && e.lureAfter.batt === e.lureAfter.before.batt - 1
      && e.lureAfter.wire === e.lureAfter.before.wire - 1 && e.lureAfter.shrew === e.lureAfter.before.shrew - 1;
    const flashNeg = e.flashOld && e.flashOld.state.state !== 'unlocked' && !e.flashOld.craft.crafted;
    const flashPos = e.flashNewState && e.flashNewState.state === 'unlocked'
      && e.flashNewCraft && e.flashNewCraft.crafted && e.flashNewCraft.output === 'flashlight'
      && e.flashNewAfter.out === 1 && e.flashNewAfter.batt === 0 && e.flashNewAfter.wire === 0 && e.flashNewAfter.scrap === 0;

    const pass = coldStart && warmScrap && unlockedCloth && collision && chain
      && newUnlocked && pipeOk && gunOk && lureOk && flashNeg && flashPos;
    console.log(`[craft-unlock] ${pass ? 'PASS' : 'FAIL'} (cold=${coldStart} warm=${warmScrap} unlocked=${unlockedCloth} collision=${collision} chain=${chain} newUnlocked=${newUnlocked} pipe=${pipeOk} gun=${gunOk} lure=${lureOk} flashNeg=${flashNeg} flashPos=${flashPos}) ${JSON.stringify(r)} ECO=${JSON.stringify(eco)}`);
  },

  // Scavenger's Economy (build 3) — SCREENSHOT the crafting panel with the new
  // cards visible + a source-hint line for a missing material. Enters NON-dev
  // (real card states), collects every material type so the new recipes unlock,
  // then EMPTIES battery from the bag so flashlight reads unlocked-but-short →
  // its detail footer shows the "battery — found in pods, habs and relays" hint.
  //   node scripts/rig-shot.mjs --scenario=craft-panel --port=5263
  'craft-panel': async (page) => {
    await page.evaluate(async () => {
      const g = window.__game;
      g.enterGame(false);                 // NON-dev: real card states
      const ctx = g.ctx;
      ctx.input.controls.isLocked = false;
      ctx.flags.paused = false;
      g.setTime(0.42);
      ctx.three.renderer.setSize(1000, 1300, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 1300; cam.updateProjectionMatrix(); }
      // Deterministic clean slate (a CONTINUE loadout can otherwise pre-fill the
      // bag): empty every slot + the discovery ledgers before granting exactly
      // what we want on screen.
      const inv = ctx.inventory;
      inv.discoveredRecipes.length = 0; inv.collectedItemTypes.clear();
      for (const s of [...inv.slots, ...inv.backpack]) { s.item = null; s.count = 0; s.meta = undefined; }
      // Collect every material TYPE so the new + updated recipes all unlock, and
      // leave enough in the bag that pipe_staff is fully craftable (green).
      for (const [id, n] of [['metal_pipe',2],['machine_part',1],['wiring',1],['battery',1],
                             ['scrap',3],['cloth',2],['branch',2],['rope',1],['raw_lizard_meat',1]]) {
        g.giveItem(id, n);
      }
      // Drop battery OUT of the bag (its TYPE stays collected) so battery-bearing
      // recipes read unlocked-but-short → the source hint renders. Zero the slots
      // directly (no in-page import — Vite dynamic-import module isolation).
      for (const s of [...inv.slots, ...inv.backpack]) {
        if (s.item === 'battery') { s.item = null; s.count = 0; s.meta = undefined; }
      }
      await g.openCrafting();
    });
    await page.waitForTimeout(400);
    // Select the worm-lure card (a NEW recipe, short on battery) so the detail
    // footer + its source-hint line render for the shot.
    const sel = await page.evaluate(() => {
      const cards = [...document.querySelectorAll('.craft-card')];
      const names = cards.map((c) => c.querySelector('.craft-card-name')?.textContent || '');
      const idx = names.findIndex((n) => n.startsWith('worm-lure'));
      if (idx >= 0) cards[idx].click();
      return { count: cards.length, names, picked: idx };
    });
    console.log('[craft-panel] ' + JSON.stringify(sel));
    await page.waitForTimeout(300);
    const diag = await page.evaluate(() => {
      const selCard = document.querySelector('.craft-card.selected .craft-card-name')?.textContent || '(none)';
      const detail = (document.querySelector('.craft-detail')?.textContent || '').slice(0, 240);
      const el = document.querySelector('.craft-detail-sources');
      return { selCard, detail, src: el ? el.textContent : '(no source block)' };
    });
    console.log('[craft-panel] diag = ' + JSON.stringify(diag));
    await page.screenshot({ path: join(OUT, 'scen-craft-panel.png'), fullPage: false });
    console.log('[rig-shot] saved scen-craft-panel.png');
  },

  // M6 ② (C38) — survival-rebalance gate. Drives the REAL updateStats deterministically
  // under controlled scenarios (the godmode floor is bypassed inside survivalProbe) to
  // assert the FORGIVING Long-Dark curve: each urgent single-neglect path (heat/cold/thirst)
  // kills in ~7-13 min; hunger is the slow background path (~12-18 min); a PREPARED player
  // never dies and HEALS back to full. Numeric only — no screenshot.
  'survival-probe': async (page) => {
    const r = await page.evaluate(() => {
      const g = window.__game; g.enterGame(true);
      return {
        heat: g.survivalProbe('heat'),
        cold: g.survivalProbe('cold'),
        thirst: g.survivalProbe('thirst'),
        hunger: g.survivalProbe('hunger'),
        prepared: g.survivalProbe('prepared'),
        // M3 (campaign 2026-07-09) — the SHADE payoff: midday sun, fully occluded.
        // Open sun kills in ~7.5 min; a wreck's shadow must keep you alive.
        heatShade: g.survivalProbe('heat-shade'),
        // M3 occluder-coverage: the decoupled threshold + procgen registration must
        // yield far more shade sources than the ~3 hand flagships of C31.
        occluders: g.sunInfo ? g.sunInfo().occluders : -1,
      };
    });
    // Death→overlay path (dormant under GOD_MODE for a long time): force a real death LAST
    // (it leaves the game in the death state) and confirm the overlay un-hides.
    const deathUi = await page.evaluate(() => window.__game.triggerDeath('the desert took you'));
    const inBand = (m, lo, hi) => m != null && m >= lo && m <= hi;
    const urgent = ['heat', 'cold', 'thirst'].every((k) => r[k].died && inBand(r[k].timeToDeathMin, 7, 13));
    const hungerOk = r.hunger.died && inBand(r.hunger.timeToDeathMin, 12, 18);
    const preparedOk = !r.prepared.died && r.prepared.finalHealth >= 0.95;
    const shadeOk = !r.heatShade.died && r.heatShade.minHealth >= 0.95;   // shade SAVES you at midday
    const coverOk = r.occluders >= 20;                                     // decoupled threshold → wide shade coverage
    const deathOk = deathUi.dead === true && deathUi.overlayShown === true;
    const pass = urgent && hungerOk && preparedOk && shadeOk && coverOk && deathOk;
    console.log(`[survival-probe] ${pass ? 'PASS' : 'FAIL'} (urgent=${urgent} hunger=${hungerOk} prepared=${preparedOk} shade=${shadeOk} occluders=${r.occluders} deathUi=${deathOk}) ${JSON.stringify({ ...r, deathUi })}`);
    if (!pass) throw new Error('survival-probe GATE FAILED');
  },

  // (M4 'ambient-beds' gate REMOVED 2026-07-09 — the procedural life beds it verified were
  // cut per user feel-veto. The day/night stems are silent again; nothing to assert.)

  // M5 diurnal-cycle GATE (campaign 2026-07-09) — creature activity binds to time of
  // day: lizard DIURNAL (≈1 noon / floor at midnight), shrew CREPUSCULAR (peaks at the
  // dawn band, quiet at noon+midnight), vulture DAY-FLIER (0 = roosting at night; a
  // perched bird must NOT launch at midnight when the player walks up, but MUST by day).
  // Asserts the activity curve via __game.diurnalInfo + the perched-launch behavior.
  'diurnal-probe': async (page) => {
    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      g.enterGame(true);
      ctx.input.controls.isLocked = true; ctx.flags.paused = false;
      await frames(10);
      const at = async (t) => { g.setTime(t); await frames(3); return g.diurnalInfo(); };
      const noon = await at(0.42);
      const midnight = await at(0.0);
      // Find DAWN: sweep dayTime for sunHeight nearest the crepuscular peak (0.08).
      let dawnT = 0.25, best = 1e9;
      for (let t = 0.1; t < 0.45; t += 0.01) {
        const d = await at(t);
        const err = Math.abs(d.sunHeight - 0.08);
        if (err < best) { best = err; dawnT = t; }
      }
      const dawn = await at(dawnT);
      // Behavioral: a perched vulture must stay perched at midnight, launch by day.
      let perchTest = 'no-perched-vulture';
      const v = (ctx.vultures.list || []).find((x) => x.state === 'perched');
      if (v) {
        const pb = ctx.player.body;
        await at(0.0);   // midnight
        pb.body.setTranslation({ x: v.pos.x + 1.5, y: v.pos.y + 1, z: v.pos.z }, true);
        await frames(60);
        const stayed = v.state === 'perched';
        await at(0.42);  // day
        await frames(180);
        const launched = v.state !== 'perched';
        perchTest = `stayedAtNight=${stayed} launchedByDay=${launched}`;
        if (!stayed || !launched) perchTest = 'FAIL ' + perchTest;
      }
      return { noon, midnight, dawnT: +dawnT.toFixed(2), dawn, perchTest };
    });
    console.log('[diurnal-probe] ' + JSON.stringify(r));
    const ok =
      r.noon.lizard > 0.9 && r.noon.vulture > 0.9 && r.noon.shrew < 0.5
      && Math.abs(r.midnight.lizard - 0.15) < 0.03 && r.midnight.vulture === 0 && r.midnight.shrew < 0.35
      && r.dawn.shrew > 0.85 && r.dawn.shrew > r.noon.shrew && r.dawn.shrew > r.midnight.shrew
      && !String(r.perchTest).startsWith('FAIL');
    console.log(`[diurnal-probe] ${ok ? 'PASS' : 'FAIL'}`);
    if (!ok) throw new Error(`diurnal-probe GATE FAILED: ${JSON.stringify(r)}`);
  },

  // Infinite Sands S1 (campaign 2026-07-10) — CHUNK-DETERMINISM GATE.
  // The determinism law extended to the infinite grid: a chunk's content
  // descriptor must be a PURE function of (worldSeed, cx, cz). Samples a
  // spread of chunk coords (origin, negative, far, VERY far) and asserts
  // each descriptor is byte-identical across repeated derivations. Prints a
  // digest line so the verify:chunks wrapper can additionally assert that
  // DIFFERENT seeds produce DIFFERENT worlds (the seed actually feeds in).
  'chunk-determinism': async (page) => {
    const r = await page.evaluate(() => {
      const g = window.__game;
      const coords = [
        [0, 0], [1, 0], [0, -1], [3, -2], [-7, 5],
        [123, -456], [-1000, 1000], [90071, -90071],
      ];
      const fails = [];
      let concat = '';
      for (const [cx, cz] of coords) {
        const a = JSON.stringify(g.chunkDescribe(cx, cz));
        const b = JSON.stringify(g.chunkDescribe(cx, cz));
        if (a !== b) fails.push(`(${cx},${cz}) descriptor unstable across derivations`);
        concat += a;
      }
      // Neighboring chunks must differ (the coord feeds the hash — a broken
      // mix that collapses to the world seed would pass the identity check).
      const d00 = JSON.stringify(g.chunkDescribe(0, 0));
      const d10 = JSON.stringify(g.chunkDescribe(1, 0));
      const d01 = JSON.stringify(g.chunkDescribe(0, 1));
      const strip = (s) => s.replace(/"cx":-?\d+,"cz":-?\d+,/, '');
      if (strip(d00) === strip(d10) || strip(d00) === strip(d01)) {
        fails.push('adjacent chunks produced identical content (seed mix broken)');
      }
      // FNV-1a over the concatenated descriptors — the per-seed world digest.
      let h = 0x811c9dc5;
      for (let i = 0; i < concat.length; i++) {
        h ^= concat.charCodeAt(i);
        h = Math.imul(h, 0x01000193) >>> 0;
      }
      return { seed: g.ctx.seed, digest: h.toString(16), fails, total: coords.length };
    });
    const pass = r.fails.length === 0;
    console.log(`CHUNK-DET seed=${r.seed} digest=${r.digest} pass=${r.total - r.fails.length}/${r.total} fails=${r.fails.length}`);
    console.log(`[chunk-determinism] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r.fails)}`);
    if (!pass) throw new Error('chunk-determinism GATE FAILED');
  },

  // Infinite Sands S1 (campaign 2026-07-10) — CHUNK-STREAMING / LEAK GATE.
  // Walks the player from the origin out to +1500m (past the OLD ±1200m
  // world edge), back, out again, and home, asserting at each stage:
  //   • the terrain tile ring FOLLOWS (ground + collider exist at 1500m,
  //     collider height agrees with heightAt, tile count never grows);
  //   • content chunks load within the ring and fully unload behind
  //     (active-key window bounded, no duplicate chunk groups at seams);
  //   • re-entering a chunk regenerates marker content IDENTICALLY
  //     (load→unload→reload byte-identity, world-space positions);
  //   • rule 9 / no leaks: global Rapier body count returns to baseline
  //     after the round trip (±3 tolerance for ambient creature churn).
  'chunk-streaming': async (page) => {
    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const fails = [];
      // Quiet the ambient systems that add/remove bodies or CREATURES
      // mid-walk: worms breach (kinematic bodies) if the path crosses
      // territory, and circling vultures HUNT lizards/shrews (a grabbed
      // lizard leaves the list — it false-failed the population-baseline
      // assert as a "leak"). Emptying the lists stops their updates; their
      // frozen meshes/bodies stay put (the body baseline is taken after).
      ctx.sandWorms.list.length = 0;
      ctx.vultures.list.length = 0;
      // Numeric probe — shrink the render target so swiftshader fill cost
      // doesn't dominate the walk (900×1100 made this probe take ~15 min).
      ctx.three.renderer.setSize(320, 240, false);
      const tp = async (x, z, settle) => {
        const y = ctx.terrain.heightAt(x, z) + 1.6;
        ctx.player.body.body.setTranslation({ x, y, z }, true);
        await frames(settle);
      };
      // HOME is (56, 56) — the CENTER of chunk (0,0), > the anchor margin
      // from every boundary, so the anchor ring resolves identically no
      // matter which direction the player arrived from. ((0,0) exactly is
      // a 4-chunk corner: the anchor there is legitimately path-dependent
      // by the margin hysteresis, which false-failed the set-equality
      // assert.) The walk runs at z=56 for the same reason.
      g.setChunkMarkers(true);
      await tp(56, 56, 90);   // settle the origin ring with markers on
      const base = g.chunkStats();
      if (!base.markersEnabled || base.markerMeshCount === 0) {
        fails.push(`markers did not enable (meshes=${base.markerMeshCount})`);
      }
      // S3 — creature population baselines (streamed fauna must all
      // despawn on the way home; boot fauna must be untouched).
      const baseLiz = base.totalLizards;
      const baseShrews = base.totalShrews;
      // D299 — dressing registry baselines (pickups/wells/cacti must
      // return to boot counts after the round trip).
      const basePk = base.totalPickups;
      // BY KIND (DEEPER cycle 6 round-13). `totalWells` filters ctx.waterSources to kind 'well', so
      // once cycle 6 put cave POOLS in the same registry the old single baseline stopped watching
      // half of it — "a pool source never outlives its cave" (caveStream.ts) had no gate. Both kinds
      // are baselined and checked separately, plus the per-cave water MATERIAL count (a cave that is
      // evicted without releasing its material leaks a live shader the ripple clock keeps writing to).
      const baseWells = base.totalWells;
      const basePools = base.totalPools;
      const basePoolMats = base.totalPoolMaterials;
      const baseCacti = base.totalCacti;
      // Content snapshot of chunks guaranteed-loaded around a position:
      // WORLD-space positions of every mesh (markers + streamed-POI content)
      // in chunks within LOAD_RADIUS-1 of the player's chunk (immune to
      // hysteresis-path differences at the ring edge). World space matters:
      // merged POI meshes sit at local origin — their placement lives in the
      // group transform.
      const snapshot = (px, pz) => {
        const SIZE = 112, R = 2;
        const pcx = Math.floor(px / SIZE), pcz = Math.floor(pz / SIZE);
        const rows = [];
        const wp = new window.__game.THREE.Vector3();
        for (const grp of ctx.three.scene.children) {
          if (!grp.name || !grp.name.startsWith('chunk-')) continue;
          const m = grp.name.match(/^chunk-(-?\d+)_(-?\d+)$/);
          if (!m) continue;
          const cx = +m[1], cz = +m[2];
          if (Math.max(Math.abs(cx - pcx), Math.abs(cz - pcz)) > R) continue;
          grp.traverse((o) => {
            if (!o.isMesh) return;
            o.getWorldPosition(wp);
            rows.push(`${grp.name}/${o.name}:${wp.x.toFixed(3)},${wp.y.toFixed(3)},${wp.z.toFixed(3)}`);
          });
        }
        return rows.sort().join('|');
      };
      // S2/S3 — descriptor-vs-render check over the FULL ACTIVE SET: every
      // descriptor-rolled POI / rock / fauna must be placed, and vice versa
      // (the active set is exactly the anchor ring once settled).
      const contentRenderCheck = (label) => {
        const st = g.chunkStats();
        let expPois = 0, expRocks = 0, expLiz = 0, expShrews = 0, expLandmarks = 0;
        let expTrees = 0, expWells = 0, expCacti = 0, minPk = 0, maxPk = 0;
        for (const k of st.activeKeys) {
          const [cx, cz] = k.split(',').map(Number);
          const d = g.chunkDescribe(cx, cz);
          if (d.poi.present) { expPois++; minPk += 2; maxPk += 4; }   // scrap ring 2-4
          expRocks += d.rocks.length;
          expLiz += d.fauna.lizards.length + d.fauna.roamLizards.length;
          expShrews += d.fauna.shrews.length + d.fauna.roamShrews.length;
          if (d.landmark.present) {
            expLandmarks++;
            if (d.landmark.kind === 'wreck_knot') expPois += 3;   // knot wrecks stamp poiArchetype too
          }
          expTrees += d.dressing.trees.length;
          minPk += d.dressing.trees.length * 2;   // 2-4 branches per tree
          maxPk += d.dressing.trees.length * 4;
          if (d.dressing.well.present) expWells++;
          expCacti += d.dressing.cacti.length;
        }
        if (expPois !== st.chunkPoiCount) fails.push(`${label}: POI descriptor/render mismatch — ${expPois} rolled, ${st.chunkPoiCount} placed`);
        if (expRocks !== st.chunkRockCount) fails.push(`${label}: rock descriptor/render mismatch — ${expRocks} rolled, ${st.chunkRockCount} placed`);
        if (expLiz !== st.chunkLizardCount) fails.push(`${label}: lizard descriptor/render mismatch — ${expLiz} rolled, ${st.chunkLizardCount} tracked`);
        if (expShrews !== st.chunkShrewCount) fails.push(`${label}: shrew descriptor/render mismatch — ${expShrews} rolled, ${st.chunkShrewCount} tracked`);
        if (expLandmarks !== st.chunkLandmarkCount) fails.push(`${label}: landmark descriptor/render mismatch — ${expLandmarks} rolled, ${st.chunkLandmarkCount} placed`);
        // D299 dressing (trees/wells/cacti exact; pickups band — branch
        // counts are render-rng, bounded 2-4 per tree/wreck).
        if (expTrees !== st.chunkTreeCount) fails.push(`${label}: tree descriptor/render mismatch — ${expTrees} rolled, ${st.chunkTreeCount} placed`);
        if (expWells !== st.chunkWellCount) fails.push(`${label}: well descriptor/render mismatch — ${expWells} rolled, ${st.chunkWellCount} placed`);
        if (expCacti !== st.chunkCactusCount) fails.push(`${label}: cactus descriptor/render mismatch — ${expCacti} rolled, ${st.chunkCactusCount} placed`);
        if (st.chunkPickupCount < minPk || st.chunkPickupCount > maxPk) {
          fails.push(`${label}: streamed pickups ${st.chunkPickupCount} outside band [${minPk},${maxPk}]`);
        }
        return { expPois, expRocks, expLiz, expShrews, expLandmarks, expTrees, expWells, expCacti };
      };
      const dupCheck = (label) => {
        const seen = new Set();
        for (const grp of ctx.three.scene.children) {
          if (!grp.name || !grp.name.startsWith('chunk-')) continue;
          if (seen.has(grp.name)) fails.push(`${label}: duplicate ${grp.name} (seam double-load)`);
          seen.add(grp.name);
        }
        return seen.size;
      };
      // ── Leg 1: origin → +1500m in 150m strides ──
      for (let x = 150; x <= 1500; x += 150) await tp(x, 56, 12);
      await frames(60);   // let the ring finish filling at the far point
      const far = g.chunkStats();
      // Ground-truth ray at a point deterministically CLEAR of marker
      // posts AND of the player capsule standing at (1500, 0) — a ray on
      // either asserts the obstacle's top, not the terrain (both
      // false-failed earlier probe runs).
      const clearPoint = () => {
        const SIZE = 112;
        for (let pz = 6; pz < 106; pz += 4) {
          if (Math.abs(pz - 56) < 4) continue;   // the player stands at (1500, 56)
          const cx = Math.floor(1500 / SIZE), cz = Math.floor(pz / SIZE);
          let blocked = false;
          for (let dx = -1; dx <= 1 && !blocked; dx++) {
            for (let dz = -1; dz <= 1 && !blocked; dz++) {
              const d = g.chunkDescribe(cx + dx, cz + dz);
              for (const m of d.markers) {
                if (Math.hypot(m.x - 1500, m.z - pz) < 2) { blocked = true; break; }
              }
              // S2 — streamed wrecks are big; give them a wide berth.
              if (d.poi.present && Math.hypot(d.poi.x - 1500, d.poi.z - pz) < 30) blocked = true;
            }
          }
          if (!blocked) return pz;
        }
        return 6;
      };
      const cpz = clearPoint();
      const cd = g.castDown(1500, cpz);
      const hExpect = ctx.terrain.heightAt(1500, cpz);
      if (!cd) fails.push('no ground collider at +1500m (terrain did not follow)');
      else if (Math.abs(cd.hitY - hExpect) > 0.5) fails.push(`collider/heightAt disagree at (1500,${cpz}): ${cd.hitY.toFixed(2)} vs ${hExpect.toFixed(2)}`);
      if (far.terrainTileKeys.length !== base.terrainTileKeys.length) {
        fails.push(`terrain tile count changed: ${base.terrainTileKeys.length} → ${far.terrainTileKeys.length}`);
      }
      const maxActive = (2 * 3 + 1) ** 2;        // full (2*LOAD_R+1)² ring
      const minActive = maxActive - (2 * 3 + 1);  // minus one still-loading edge
      if (far.activeKeys.length < minActive || far.activeKeys.length > maxActive) {
        fails.push(`active chunk count out of window at far point: ${far.activeKeys.length} (want ${minActive}..${maxActive})`);
      }
      if (far.markerMeshCount === 0) fails.push('no markers at +1500m (content did not stream)');
      dupCheck('far');
      const farContent = contentRenderCheck('far');
      const farSnapA = snapshot(1500, 56);
      // ── S5 — PERSISTENCE: extract from a streamed wreck (the mutation a
      //    real player makes), then prove it survives unload→reload,
      //    reaches the save file sparsely, and (node-side, after this
      //    evaluate) survives a REAL page reload + CONTINUE. ──
      let persist = null;
      {
        // Restrict to a chunk-own POI wreck ('poi/...' ids) so the salvage
        // mutation AND the taken scrap below land in the SAME chunk — the
        // save-file sparsity assert expects exactly one modified chunk.
        const t = ctx.salvageables.list.find((s) => s.transient && s.chunkContentId && s.chunkContentId.startsWith('poi/'));
        if (!t) fails.push('S5: no transient salvageable at the far point (persistence leg vacuous)');
        else {
          const comps = (t.panel.userData.panelComponents || []);
          const vis = comps.findIndex((cm) => cm.visible);
          if (vis < 0) fails.push('S5: far panel has no visible components to extract');
          else {
            comps[vis].visible = false;          // what extraction does (WYSIWYG)
            t.salvageRemaining -= 1;
            persist = { contentId: t.chunkContentId, expectedRemaining: t.salvageRemaining, hiddenIdx: vis };
          }
        }
        // D299 — also TAKE a streamed pickup the way a real take does;
        // its absence must persist like the salvage. Same chunk as the
        // mutated wreck (its own scrap ring — 'poi/sc*' ids share the
        // wreck's chunk via the POI edge margin).
        const tChunk = persist && (() => {
          const tt = ctx.salvageables.list.find((s) => s.chunkContentId === persist.contentId && s.transient);
          return tt ? `${Math.floor(tt.pos.x / 112)},${Math.floor(tt.pos.z / 112)}` : null;
        })();
        const bp = ctx.pickups.list.find((pp) =>
          pp.transient && pp.chunkContentId && pp.chunkContentId.startsWith('poi/sc') &&
          `${Math.floor(pp.pos.x / 112)},${Math.floor(pp.pos.z / 112)}` === tChunk);
        if (bp) {
          const pkId = bp.chunkContentId;
          g.despawnPickupById(bp.id);
          if (persist) persist.takenPickup = pkId;
          else fails.push('D299: pickup taken but no salvage persist record (assert wiring)');
        } else if (persist) {
          fails.push('D299: no streamed pickup at the far point (scrap ring / branches missing?)');
        }
      }
      // S2 — SAVE SAFETY with streamed wrecks live: the serialized save
      // must contain ONLY boot-placed salvageables (transient excluded) —
      // a leaked load-order-dependent id would silently patch the WRONG
      // wreck after reload.
      {
        const sv = g.saveGame();
        if (!sv.ok) fails.push('saveGame failed at far point: ' + (sv.error || '?'));
        else {
          const raw = JSON.parse(localStorage.getItem('dustfall.save.v1'));
          const savedIds = new Set(raw.salvageables.map((s) => s.id));
          const liveTransient = ctx.salvageables.list.filter((s) => s.transient);
          if (liveTransient.length === 0) fails.push('no transient salvage live at the far save point (save-safety test vacuous — extend the walk)');
          for (const s of liveTransient) {
            if (savedIds.has(s.id)) fails.push(`transient salvage id ${s.id} leaked into the save`);
          }
          const bootCount = ctx.salvageables.list.filter((s) => !s.transient).length;
          if (raw.salvageables.length !== bootCount) {
            fails.push(`saved salvageable count ${raw.salvageables.length} != boot (non-transient) count ${bootCount}`);
          }
          // S3 — same rule for streamed fauna: only boot creatures serialize.
          const bootLiz = ctx.lizards.filter((l) => !l.transient).length;
          const bootShr = ctx.shrews.list.filter((s) => !s.transient).length;
          if (raw.lizards.length !== bootLiz) fails.push(`saved lizard count ${raw.lizards.length} != boot count ${bootLiz}`);
          if ((raw.shrews || []).length !== bootShr) fails.push(`saved shrew count ${(raw.shrews || []).length} != boot count ${bootShr}`);
          // D299 — only boot pickups/cacti serialize (streamed are transient).
          const bootPk = ctx.pickups.list.filter((pp) => !pp.transient).length;
          if ((raw.pickupSurvivors || []).length !== bootPk) fails.push(`saved pickupSurvivors ${(raw.pickupSurvivors || []).length} != boot pickup count ${bootPk}`);
          const bootCact = ctx.cacti.list.filter((cc) => !cc.transient).length;
          if ((raw.cacti || []).length !== bootCact) fails.push(`saved cacti ${(raw.cacti || []).length} != boot cactus count ${bootCact}`);
          if (ctx.lizards.filter((l) => l.transient).length === 0 && farContent.expLiz > 0) {
            fails.push('descriptor rolled streamed lizards but none are live (spawn path broken)');
          }
          // S5 — the save must carry the (live-captured) chunk diff, and
          // ONLY that one chunk (sparsity).
          const diffKeys = Object.keys(raw.chunkDiffs || {});
          if (persist && diffKeys.length !== 1) {
            fails.push(`S5: expected exactly 1 chunkDiff in the save, got ${diffKeys.length} [${diffKeys.join(' ')}]`);
          }
          if (persist && diffKeys.length === 1) {
            const d = raw.chunkDiffs[diffKeys[0]];
            const entry = d.salvage && d.salvage[persist.contentId];
            if (!entry || entry.remaining !== persist.expectedRemaining) {
              fails.push(`S5: saved diff entry wrong for ${persist.contentId}: ${JSON.stringify(entry)}`);
            }
            persist.chunkKey = diffKeys[0];
          }
        }
      }
      // ── Leg 1b: EXERCISE THE FAUNA PATH — walk to the nearest
      //    descriptor-rolled fauna chunk (the straight +X walk can land on
      //    all-salt POIs where fauna correctly skips, leaving the
      //    spawn/despawn path untested). ──
      const walkTo = async (txp, tzp) => {
        const cur = ctx.player.body.body.translation();
        const dist = Math.hypot(txp - cur.x, tzp - cur.z);
        const steps = Math.max(1, Math.ceil(dist / 140));
        for (let i = 1; i <= steps; i++) {
          const x = cur.x + (txp - cur.x) * (i / steps);
          const z = cur.z + (tzp - cur.z) * (i / steps);
          await tp(x, z, 12);
        }
        await frames(60);
      };
      let faunaSite = null;
      {
        let best = null;
        for (let cx = 12; cx <= 40; cx++) {
          for (let cz = -14; cz <= 14; cz++) {
            const d = g.chunkDescribe(cx, cz);
            if (d.fauna.lizards.length === 0) continue;
            const fx = d.poi.x, fz = d.poi.z;
            const dd = (fx - 1500) * (fx - 1500) + (fz - 56) * (fz - 56);
            if (!best || dd < best.dd) best = { x: fx, z: fz, dd };
          }
        }
        faunaSite = best;
      }
      if (!faunaSite) {
        fails.push('no fauna chunk in the scan window (seed-dependent — widen the scan)');
      } else {
        await walkTo(faunaSite.x + 20, faunaSite.z + 20);   // stand OFF the wreck (not inside its collider)
        contentRenderCheck('fauna-site');
        const liveTransientLiz = ctx.lizards.filter((l) => l.transient).length;
        if (liveTransientLiz === 0) fails.push('at a descriptor-rolled fauna site but no streamed lizards live (spawn path broken)');
      }
      // ── Leg 1c (S4): LANDMARK site — walk to the nearest region-rolled
      //    hero landmark and assert descriptor↔render there too. ──
      let lmSite = null;
      {
        let best = null;
        for (let cx = 12; cx <= 60; cx++) {
          for (let cz = -20; cz <= 20; cz++) {
            const d = g.chunkDescribe(cx, cz);
            if (!d.landmark.present) continue;
            const cur = ctx.player.body.body.translation();
            const dd = (d.landmark.x - cur.x) ** 2 + (d.landmark.z - cur.z) ** 2;
            if (!best || dd < best.dd) best = { x: d.landmark.x, z: d.landmark.z, kind: d.landmark.kind, dd };
          }
        }
        lmSite = best;
      }
      if (!lmSite) {
        fails.push('no landmark in the scan window (seed-dependent — widen the scan or raise CHUNK_LANDMARK_CHANCE)');
      } else {
        await walkTo(lmSite.x + 30, lmSite.z + 30);   // stand off the landmark
        contentRenderCheck('landmark-site');
      }
      // ── S4: regional wreck-yard existence — scan the pure biome field
      //    directly over ±15km (≈280 regions at p=0.08 → a yard is
      //    statistically certain; rendering flows through already-gated
      //    paths, so existence is the load-bearing assert). Also assert the
      //    ORIGIN ring is untouched: no regional yard reads inside ±1200m
      //    beyond what the origin anchor itself produces. ──
      {
        let found = false;
        for (let x = -15000; x <= 15000 && !found; x += 400) {
          for (let z = -15000; z <= 15000 && !found; z += 400) {
            if (x * x + z * z < 2200 * 2200) continue;   // skip the origin field
            if (ctx.biomes.wreckYardAt(x, z) > 0.5) found = true;
          }
        }
        if (!found) fails.push('no regional wreck-yard in a ±15km biome scan (regional anchors broken)');
      }
      // ── Leg 2: return home (unloads the far field) ──
      await walkTo(56, 56);
      const homeKeys = new Set(g.chunkStats().activeKeys);
      if (homeKeys.has('12,0') || homeKeys.has('13,0')) {
        fails.push('far chunks still loaded after returning home (unload broken)');
      }
      // ── Leg 3: out again — the reload must regenerate IDENTICAL content ──
      await walkTo(1500, 56);
      const farSnapB = snapshot(1500, 56);
      if (farSnapA !== farSnapB) fails.push('reloaded chunk content differs from first visit (determinism broken across unload/reload)');
      if (farSnapA.length === 0) fails.push('empty marker snapshot at far point (nothing to compare)');
      // S5 — the extraction must have SURVIVED the unload→reload cycle:
      // the re-registered record carries the diff-applied state.
      if (persist) {
        // Content ids ('poi/0', 'poi/sc0') repeat across chunks — scope every
        // find to the mutated chunk (persist.chunkKey, from the save's diff).
        const inChunk = (pos) => `${Math.floor(pos.x / 112)},${Math.floor(pos.z / 112)}` === persist.chunkKey;
        const t2 = ctx.salvageables.list.find((s) => s.transient && s.chunkContentId === persist.contentId && inChunk(s.pos));
        if (!t2) fails.push(`S5: re-registered record ${persist.contentId} not found on revisit`);
        else {
          if (t2.salvageRemaining !== persist.expectedRemaining) {
            fails.push(`S5: revisit remaining ${t2.salvageRemaining} != expected ${persist.expectedRemaining} (diff not applied)`);
          }
          const comps2 = (t2.panel.userData.panelComponents || []);
          if (comps2[persist.hiddenIdx] && comps2[persist.hiddenIdx].visible) {
            fails.push('S5: extracted component visible again on revisit (diff not applied)');
          }
        }
        // D299 — the taken pickup must NOT respawn on revisit.
        if (persist.takenPickup) {
          const back = ctx.pickups.list.find((pp) => pp.transient && pp.chunkContentId === persist.takenPickup && inChunk(pp.pos));
          if (back) fails.push(`D299: taken pickup ${persist.takenPickup} respawned on revisit (pickups diff not applied)`);
        }
      }
      // ── Leg 4: home again — leak check against the baseline ──
      await walkTo(56, 56);
      await frames(90);
      const end = g.chunkStats();
      const sameKeys = JSON.stringify(end.activeKeys) === JSON.stringify(base.activeKeys);
      if (!sameKeys) fails.push(`active chunk set at home differs from baseline (${end.activeKeys.length} vs ${base.activeKeys.length})`);
      if (JSON.stringify(end.terrainTileKeys) !== JSON.stringify(base.terrainTileKeys)) {
        fails.push(`terrain tiles at home differ from baseline: ${end.terrainTileKeys.join(' ')} vs ${base.terrainTileKeys.join(' ')}`);
      }
      const bodyDrift = end.worldBodies - base.worldBodies;
      if (Math.abs(bodyDrift) > 3) fails.push(`Rapier body LEAK: ${base.worldBodies} → ${end.worldBodies} (drift ${bodyDrift})`);
      if (end.markerMeshCount !== base.markerMeshCount) {
        fails.push(`marker mesh count at home drifted: ${base.markerMeshCount} → ${end.markerMeshCount}`);
      }
      // S2 — streamed-wreck salvage entries must all splice back out: the
      // global registry returns to its boot size (origin wrecks only).
      if (end.registrySalvageCount !== base.registrySalvageCount) {
        fails.push(`salvage registry LEAK: ${base.registrySalvageCount} → ${end.registrySalvageCount} (streamed entries not spliced on unload)`);
      }
      if (end.chunkSalvageCount !== 0 || end.chunkPoiCount !== 0) {
        fails.push(`streamed POI content at HOME (inside the origin exclusion): pois=${end.chunkPoiCount} salvage=${end.chunkSalvageCount}`);
      }
      // S3 — creature populations return to their boot baselines.
      if (end.totalLizards !== baseLiz) fails.push(`lizard population LEAK: ${baseLiz} → ${end.totalLizards} (streamed fauna not despawned)`);
      if (end.totalShrews !== baseShrews) fails.push(`shrew population LEAK: ${baseShrews} → ${end.totalShrews}`);
      if (end.chunkRockCount !== 0) fails.push(`streamed rocks at HOME (inside the origin exclusion): ${end.chunkRockCount}`);
      // D299 — dressing registries return to boot baselines.
      if (end.totalPickups !== basePk) fails.push(`pickup registry LEAK: ${basePk} → ${end.totalPickups} (streamed branches/scrap not despawned)`);
      if (end.totalWells !== baseWells) fails.push(`well registry LEAK: ${baseWells} → ${end.totalWells}`);
      if (end.totalPools !== basePools) fails.push(`POOL registry LEAK: ${basePools} → ${end.totalPools} (an evicted cave's pool sources outlived it — caveStream detach)`);
      if (end.totalPoolMaterials !== basePoolMats) fails.push(`pool MATERIAL leak: ${basePoolMats} → ${end.totalPoolMaterials} (a per-cave water material was not released on eviction)`);
      if (end.totalCacti !== baseCacti) fails.push(`cactus registry LEAK: ${baseCacti} → ${end.totalCacti}`);
      dupCheck('home');
      // ── Leg 5 (D297): SPEEDER RIDE — streaming must follow the BIKE.
      //    While mounted the real game PARKS the capsule at (0,-2000,0)
      //    and drives the camera from the bike; capsule-centered
      //    streaming re-anchored the world to the origin mid-ride (the
      //    playtest bug). Mimic the real mount exactly, hop the BIKE
      //    diagonally into fresh chunks, assert the rings follow. ──
      if (ctx.speeder) {
        const s = ctx.speeder;
        s.mounted = true;
        ctx.player.body.body.setTranslation({ x: 0, y: -2000, z: 0 }, true);
        const b0 = s.body.translation();
        for (let i = 1; i <= 8; i++) {
          const bx = b0.x + i * 130, bz = b0.z - i * 130;
          s.body.setTranslation({ x: bx, y: ctx.terrain.heightAt(bx, bz) + 1.4, z: bz }, true);
          s.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
          await frames(15);
        }
        await frames(60);
        const bt = s.body.translation();
        const st2 = g.chunkStats();
        const bikeChunk = `${Math.floor(bt.x / 112)},${Math.floor(bt.z / 112)}`;
        const bikeTile = `${Math.round(bt.x / 800)},${Math.round(bt.z / 800)}`;
        if (!st2.activeKeys.includes(bikeChunk)) {
          fails.push(`RIDE: chunk ring did not follow the bike (missing ${bikeChunk} — streaming from the parked capsule?)`);
        }
        if (!st2.terrainTileKeys.includes(bikeTile)) {
          fails.push(`RIDE: terrain ring did not follow the bike (missing tile ${bikeTile})`);
        }
        // Dismount-mimic: capsule beside the bike (the real dismount path).
        s.mounted = false;
        ctx.player.body.body.setTranslation({ x: bt.x + 2, y: ctx.terrain.heightAt(bt.x + 2, bt.z) + 1.6, z: bt.z }, true);
        await frames(30);
      } else {
        fails.push('no speeder on this world — the D297 ride leg is vacuous');
      }
      g.setChunkMarkers(false);
      return {
        fails,
        persist,
        baseBodies: base.worldBodies, endBodies: end.worldBodies,
        baseChunks: base.activeKeys.length, farChunks: far.activeKeys.length,
        farMarkers: far.markerMeshCount, farPois: farContent.expPois,
        farSalvage: far.chunkSalvageCount, farRocks: farContent.expRocks,
        farFauna: farContent.expLiz + farContent.expShrews,
        tiles: end.terrainTileKeys.length,
      };
    });
    // ── S5 node-side leg: a REAL page reload + CONTINUE must re-apply the
    //    chunk diff (proves the save→loadDiffs→apply wiring end-to-end,
    //    not just the in-memory map). Player restores at the far save
    //    point; the modified chunk streams back in with its diff. ──
    if (r.persist) {
      await page.reload();
      await page.waitForFunction(() => !!(window.__game && window.__game.ctx?.player?.rig), undefined, { timeout: 60000 });
      const clicked = await page.evaluate(() => {
        const btns = Array.from(document.querySelectorAll('button'));
        const cont = btns.find((b) => (b.textContent || '').trim().toUpperCase() === 'CONTINUE');
        if (!cont) return false;
        cont.click();
        return true;
      });
      if (!clicked) {
        r.fails.push('S5-reload: no CONTINUE button after a real page reload');
      } else {
        const rr = await page.evaluate(async (persist) => {
          const ctx = window.__game.ctx;
          const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
          ctx.input.controls.isLocked = true; ctx.flags.paused = false;
          for (let i = 0; i < 200; i++) await raf();   // stream the ring at the restored far position
          const fails = [];
          // Content ids repeat across chunks — scope finds to the mutated chunk.
          const inChunk = (pos) => `${Math.floor(pos.x / 112)},${Math.floor(pos.z / 112)}` === persist.chunkKey;
          const t = ctx.salvageables.list.find((s) => s.transient && s.chunkContentId === persist.contentId && inChunk(s.pos));
          if (!t) fails.push(`S5-reload: ${persist.contentId} not re-registered after reload+CONTINUE`);
          else {
            if (t.salvageRemaining !== persist.expectedRemaining) {
              fails.push(`S5-reload: remaining ${t.salvageRemaining} != expected ${persist.expectedRemaining} (loadDiffs->apply broken)`);
            }
            const comps = (t.panel.userData.panelComponents || []);
            if (comps[persist.hiddenIdx] && comps[persist.hiddenIdx].visible) {
              fails.push('S5-reload: extracted component visible again after a real reload');
            }
          }
          if (persist.takenPickup) {
            const back = ctx.pickups.list.find((pp) => pp.transient && pp.chunkContentId === persist.takenPickup && inChunk(pp.pos));
            if (back) fails.push(`S5-reload: taken pickup ${persist.takenPickup} respawned after a real reload`);
          }
          return fails;
        }, r.persist);
        r.fails.push(...rr);
      }
    }
    const pass = r.fails.length === 0;
    console.log(`CHUNK-STREAM pass=${pass ? 1 : 0} bodies=${r.baseBodies}->${r.endBodies} chunks=${r.baseChunks}/${r.farChunks} farMarkers=${r.farMarkers} farPois=${r.farPois} farSalvage=${r.farSalvage} farRocks=${r.farRocks} farFauna=${r.farFauna} tiles=${r.tiles} persisted=${r.persist ? 1 : 0} fails=${r.fails.length}`);
    console.log(`[chunk-streaming] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r.fails)}`);
    if (!pass) throw new Error('chunk-streaming GATE FAILED');
  },

  // Infinite Sands S6 (campaign 2026-07-10) — CHUNK-PERF GATE. Generation
  // must be hitch-free: terrain tiles build SLICED (a bounded stage-step
  // per frame, never a synchronous 37k-vertex bake mid-walk) and chunk
  // loads stay bounded; draw calls + Rapier bodies hold ceilings across a
  // multi-km walk. Thresholds are GROSS-REGRESSION tripwires (a synchronous
  // bake is ~100-200ms; a sliced step ~2-10ms), generous enough to be
  // machine-load flake-resistant (D291) — the sharp assert is
  // syncBuilds === 0: a contiguous walk must never hit the synchronous
  // (anchor-teleport) path.
  // DEEPER cycle 5 (walk-test D-4) — THE ORIGIN-CAVE PRELOAD gate. Boot-only (no walk), so it is
  //   cheap enough to run at BOTH flag states. Asserts, with the cave ON: the origin cave was built
  //   during module init (i.e. behind the boot loading screen, before the first presented frame), is
  //   adopted as a PINNED resident with real triangles, and the boot overlay came back down. With
  //   `--cave=0`: no preload happened at all and the flag-off world still boots — the kill-switch
  //   path cannot be regressed by the preload wiring.
  //   Run: npm run rig -- --scenario=cave-preload --port=5231   (add --cave=0 for the off leg)
  'cave-preload': async (page) => {
    const r = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      const fails = [];
      const on = !!ctx.caveStream;
      const p = g.cavePerf();
      const boot = window.__bootT || [];
      const bootTotal = boot.length > 1 ? boot[boot.length - 1][1] - boot[0][1] : -1;
      if (document.getElementById('boot-overlay')) fails.push('#boot-overlay still present after boot — the loading screen never came down');
      let digest = '-';
      if (on) {
        if (!p.preload) fails.push('cave flag ON but no __cavePreloadMs record — the origin cave was NOT preloaded at boot');
        const o = p.residents.find((x) => x.key === 'origin');
        if (!o) fails.push('cave flag ON but no origin resident — the preload was not adopted');
        else {
          digest = o.digest;
          if (!o.pinned) fails.push('the origin resident is NOT pinned — the resident cap could evict the egg cave');
          if (!(o.tris > 0)) fails.push('the origin resident carries 0 triangles');
          if (!(o.colliderTris > 0)) fails.push('the origin resident carries 0 COLLIDER triangles');
        }
        if (p.preload && !(p.preload.body > 0)) fails.push('the preload record reports 0ms of cave-body build — nothing was measured');
      } else {
        if (p.preload) fails.push('cave flag OFF but a preload record exists — the cave built anyway');
        if (p.residents.length) fails.push(`cave flag OFF but ${p.residents.length} cave residents exist`);
        if (!ctx.terrain.meshes.length) fails.push('flag-off boot produced no terrain — the kill-switch path regressed');
      }
      return {
        fails, on, bootTotal: +bootTotal.toFixed(1), digest,
        ent: p.preload ? p.preload.entrance : -1,
        body: p.preload ? p.preload.body : -1,
        total: p.preload ? p.preload.total : -1,
        tris: on && p.residents[0] ? p.residents[0].tris : 0,
      };
    });
    const pass = r.fails.length === 0;
    console.log(`CAVE-PRELOAD pass=${pass ? 1 : 0} flag=${r.on ? 1 : 0} boot=${r.bootTotal}ms preload=${r.total}ms(ent=${r.ent}/body=${r.body}) tris=${r.tris} digest=${r.digest} fails=${r.fails.length}`);
    console.log(`[cave-preload] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r.fails)}`);
    if (!pass) throw new Error('cave-preload GATE FAILED');
  },

  // ── DEEPER cycle 8 — CAVES AS ROCKY-TERRAIN DENSITY. The placement + hole-lifecycle gate.
  //
  //   Four legs, one boot:
  //
  //   A. PLACEMENT PURITY + RULES. The site list over a 12km box is derived TWICE and digested:
  //      byte-stable, and (across the two gate seeds, compared by verify-chunks) different worlds
  //      must produce different lists. Every site is then audited against the rules that make the
  //      cycle safe rather than merely present: rocky biome, outside the origin-protection radius,
  //      never inside a terrain-carving regional biome, and — the one that matters most —
  //      MINIMUM SPACING, asserted against the cave's MEASURED horizontal extent rather than a
  //      constant someone once believed. Two cave bodies that interpenetrate is not a taste bug.
  //
  //   B. REALIZED DENSITY, measured not asserted. Counts sites per km² of world and per km² of
  //      rocky ground, and converts it to the number Zach actually asked about: encounters per
  //      hour of travel. The rejection ladder (biome / relief / content conflict) eats into the
  //      nominal CAVE_SITE_CHANCE, so the honest density is the counted one.
  //
  //   C. THE HOLE MECHANISM, IN ISOLATION — the leg with the sharpest teeth. Before any cave
  //      exists, a 200-point grid is cast down onto bare terrain and every hit recorded. Then a
  //      hole is opened through the REAL `terrain.addCaveHole` path (band-decomposed heightfields)
  //      and the grid re-cast: points inside the hole must MISS, and every point outside it must
  //      hit at the IDENTICAL height — which is also what proves the sub-heightfield row/column
  //      convention is right, because a transposed height matrix would move every sample. Then the
  //      hole is closed and the grid cast a third time: max |Δ| against the ORIGINAL must be
  //      exactly 0. That is teardown symmetry as a number, not as a claim (rule 9).
  //
  //   D. THE LIVE LIFECYCLE. A real descriptor site is streamed in (crevice tor + interior +
  //      carved hole), then released by walking out of range with its terrain tile still loaded,
  //      then streamed in AGAIN. Asserts: the unit arrives whole; the hole exists exactly while
  //      the cave does; the teardown returns rigid-body count, water-source count, pool count and
  //      pool-material count to their pre-stream baselines (the leak canaries); and the re-entered
  //      cave's digest is BIT-IDENTICAL to the first visit's — a streamed cave is descriptor-
  //      derived, so coming back must not produce a different cave.
  //
  //   Run: npm run rig -- --scenario=cave-density --seed=1337 --port=5236
  'cave-density': async (page) => {
    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const fails = [];
      const T = g.Tuning;
      if (!ctx.caveStream) { fails.push('ctx.caveStream is null — the cave scheduler did not boot'); return { fails, skipped: true }; }
      ctx.sandWorms.list.length = 0;
      ctx.three.renderer.setSize(320, 240, false);

      const fnv = (vals) => {
        let h = 0x811c9dc5 >>> 0;
        for (const v of vals) h = Math.imul(h ^ (v & 0xffffffff), 0x01000193) >>> 0;
        return (h >>> 0).toString(16).padStart(8, '0');
      };

      // ── A. placement purity + rules ─────────────────────────────────────────────────────
      const BOX = 6000;                              // ±6km → a 12km box
      const derive = () => g.caveSites(0, 0, BOX * Math.SQRT2)
        .filter((s) => Math.abs(s.x) <= BOX && Math.abs(s.z) <= BOX)
        .sort((a, b) => (a.gx - b.gx) || (a.gz - b.gz));
      const listA = derive();
      const listB = derive();
      const digestOf = (l) => fnv(l.flatMap((s) => [s.gx, s.gz, Math.round(s.x * 100), Math.round(s.z * 100), s.seed]));
      const siteDigest = digestOf(listA);
      if (siteDigest !== digestOf(listB)) fails.push('site list is NOT stable across two derivations — placement is not pure');

      // ══ DEEPER cycle 12, GATE A — BEAT-SITES ═════════════════════════════════════════════════
      //    Which caves carry the dead explorer, proven over HUNDREDS of sites without building one:
      //    the predicate is a pure read of the site descriptor's kind, so this costs milliseconds and
      //    rides the leg that already sweeps sites purely at both seeds.
      //
      //    THE PREDICATE IS READ FROM THE GAME'S OWN KIND TABLE, never re-implemented here. A gate
      //    that hardcodes `kind === 'warren'` is asserting its own opinion of where the beat is, and
      //    would stay green through the exact change it exists to catch (someone flipping the flag on
      //    another kind, or onto canonical).
      const beatSites = (() => {
        const tbl = g.caveKindTable();
        const carries = (k) => !!(tbl.params[k] && tbl.params[k].deadExplorer);
        const notes = {};
        // 1 — SEED PURITY. Re-derived twice above; the beat flag must agree with itself and with the
        //     kind on both derivations.
        const flagsA = listA.map((s) => carries(s.kind)), flagsB = listB.map((s) => carries(s.kind));
        if (flagsA.length !== flagsB.length || flagsA.some((v, i) => v !== flagsB[i]))
          fails.push('BEAT-SITES the beat flag is not stable across two derivations — the predicate is not seed-pure');
        // 2 — VACUOUS-PASS GUARDS, before any assertion that could pass by measuring nothing.
        const beats = listA.filter((s) => carries(s.kind));
        const kindsSeen = new Set(listA.map((s) => s.kind));
        notes.sites = listA.length; notes.beats = beats.length; notes.kinds = kindsSeen.size;
        if (listA.length < 40) fails.push(`BEAT-SITES only ${listA.length} sites swept — too few to conclude anything`);
        if (!kindsSeen.has('warren')) fails.push('BEAT-SITES no warren appeared in a 12km box — the sweep proves nothing about the beat');
        if (beats.length === 0) fails.push('BEAT-SITES not one site carries the beat — it would never appear in a real world');
        // 3 — ORIGIN PARITY, PROVEN PURELY. This is the assertion that makes "ec2ebf98 / 876749d6
        //     cannot move" a machine fact instead of a claim in a comment.
        if (carries('canonical')) fails.push('BEAT-SITES canonical carries the beat — the ORIGIN CAVE would carry an authored corpse and its parity digest would be at risk');
        const originClear = T.CAVE_SITE_ORIGIN_CLEAR_M;   // `clr` is not declared until below this block
        const inClear = beats.filter((s) => Math.hypot(s.x, s.z) < originClear);
        if (inClear.length) fails.push(`BEAT-SITES ${inClear.length} beat site(s) inside the ${originClear}m origin exclusion`);
        // 4 — FINDABILITY, asserted against the MEASUREMENT and not against the plan's arithmetic.
        //     The plan estimated ~0.19 beat caves/km² and a ~1.3km nearest; the envelope is generous
        //     on purpose — this tooth exists to catch "none in the world" and "one every 200m", not
        //     to freeze a density Zach may want to tune.
        let nearest = Infinity;
        for (const s of beats) nearest = Math.min(nearest, Math.hypot(s.x, s.z));
        const perKm2Beat = beats.length / ((BOX * 2 / 1000) ** 2);
        notes.nearestKm = +(nearest / 1000).toFixed(2); notes.perKm2 = +perKm2Beat.toFixed(3);
        if (!(nearest < 6000)) fails.push(`BEAT-SITES nearest beat cave is ${(nearest / 1000).toFixed(1)}km — unfindable in practice`);
        if (!(perKm2Beat > 0.01 && perKm2Beat < 2)) fails.push(`BEAT-SITES beat density ${perKm2Beat.toFixed(3)}/km² is outside the sane envelope 0.01-2`);
        return notes;
      })();
      if (listA.length < 40) fails.push(`only ${listA.length} sites in a 12km box — too few to audit (vacuous-pass guard)`);

      const clr = T.CAVE_SITE_ORIGIN_CLEAR_M;
      let offBiome = 0, insideOrigin = 0, inRegion = 0;
      for (const s of listA) {
        if (ctx.biomes.biomeAt(s.x, s.z) !== 'rocky') offBiome++;
        if (s.x * s.x + s.z * s.z <= clr * clr) insideOrigin++;
        if (ctx.biomes.ergAt(s.x, s.z) > 0 || ctx.biomes.wreckYardAt(s.x, s.z) > 0
          || ctx.biomes.boneFieldAt(s.x, s.z) > 0 || ctx.biomes.sarlaccPitAt(s.x, s.z) > 0) inRegion++;
      }
      if (offBiome) fails.push(`${offBiome} sites are NOT on rocky biome`);
      if (insideOrigin) fails.push(`${insideOrigin} sites inside the ${clr}m origin protection — the egg cave is not unique`);
      if (inRegion) fails.push(`${inRegion} sites inside a terrain-carving regional biome (erg / yard / bone / pit)`);

      // ── A2. THE TILE-SEAM CHECK (DEEPER cycle 8, closing agent) ──────────────────────────
      //   A `CaveHoleBlock` names ONE terrain tile and `caveEntranceHoleBlock` clamps its cell
      //   range to that tile. A site on a tile seam therefore gets a hole truncated or shifted by
      //   a cell (4.17m), leaving the sheet SOLID over part of the descent slot — a cave whose tor
      //   you can see and cannot enter. Nothing else reports it: the tor builds, the interior
      //   builds, the hole registry lists a hole, and every other gate stays green. It hits 1.56%
      //   of snapped positions (~1 cave in 64), which is exactly the rate that survives a small
      //   gate net and then shows up in play.
      //
      //   METHOD: the SHIPPED block (`g.caveHoleBlock` → `caveEntranceHoleBlock`) is compared against
      //   the block it WOULD have produced with no clamp, derived here from the site coordinates.
      //   The re-derivation is deliberate and is the only form of this check with teeth: the defect
      //   IS the shipped function quietly clamping, so asking that same function what "correct" looks
      //   like could only ever agree with itself. Any disagreement — a lost cell (TRUNC) or a whole
      //   block slid sideways (SHIFT, the j0=0 case, which moves the mouth a cell off the tor) — is
      //   the clamp firing.
      //
      //   NOT a defect, and this cost a red gate to learn: a hole that merely TOUCHES the tile's
      //   first or last cell row (`i[189,191]`, `j[190,191]`) is perfectly correct — it is the full
      //   3×2 block, unclamped, ending exactly at the seam, and the band decomposition tiles around
      //   it with no gap. The first version of this check flagged those six sites as failures. A
      //   gate that fails on healthy geometry is the same class of error as one that passes on
      //   broken geometry (the `open-end`/leviathan-front-door precedent), so the criterion is
      //   EQUALITY WITH THE UNCLAMPED IDEAL, never proximity to an edge.
      //
      //   `caveSites.ts` rejects clamping sites by construction, so this must read ZERO — it is the
      //   proof the rejection is live, over the whole 12km site list on both gate seeds.
      const HOLE_CELLS_X = T.CREVICE_HOLE_CELLS_X, HOLE_CELLS_Z = T.CREVICE_HOLE_CELLS_Z;
      const TSIZE = T.TERRAIN_CHUNK_SIZE, TCELLS = T.TERRAIN_CHUNK_CELLS;
      let seamSites = 0; const seamAt = [];
      for (const s of listA) {
        const hb2 = g.caveHoleBlock(s.x, s.z);
        const tx = Math.round(s.x / TSIZE), tz = Math.round(s.z / TSIZE);
        const i0 = Math.round(((s.x - tx * TSIZE) / TSIZE + 0.5) * TCELLS);
        const j0 = Math.round(((s.z - tz * TSIZE) / TSIZE + 0.5) * TCELLS);
        const wIMin = i0 - 1, wIMax = i0 - 1 + HOLE_CELLS_X - 1;
        const wJMin = j0 - Math.floor(HOLE_CELLS_Z / 2), wJMax = wJMin + HOLE_CELLS_Z - 1;
        if (hb2.iMin !== wIMin || hb2.iMax !== wIMax || hb2.jMin !== wJMin || hb2.jMax !== wJMax) {
          seamSites++;
          const wI = hb2.iMax - hb2.iMin + 1, wJ = hb2.jMax - hb2.jMin + 1;
          const kind = (wI !== HOLE_CELLS_X || wJ !== HOLE_CELLS_Z) ? 'TRUNC' : 'SHIFT';
          if (seamAt.length < 6) seamAt.push(`${s.key}@(${s.x.toFixed(0)},${s.z.toFixed(0)})got_i[${hb2.iMin},${hb2.iMax}]j[${hb2.jMin},${hb2.jMax}]_want_i[${wIMin},${wIMax}]j[${wJMin},${wJMax}]_${kind}`);
        }
      }
      if (seamSites) {
        fails.push(`${seamSites} sites sit on a terrain-tile seam — the shipped hole block differs from the unclamped ideal, so the carved hole is truncated/shifted and the descent slot stays floored: [${seamAt.join(' ')}]`);
      }

      // Nearest-neighbour spacing across the whole list (O(n²) on ~100 sites — fine).
      let minSpacing = Infinity, minPair = '-';
      for (let i = 0; i < listA.length; i++) {
        for (let j = i + 1; j < listA.length; j++) {
          const d = Math.hypot(listA[i].x - listA[j].x, listA[i].z - listA[j].z);
          if (d < minSpacing) { minSpacing = d; minPair = `${listA[i].key}|${listA[j].key}`; }
        }
      }
      const nominalMin = T.CAVE_SITE_CELL_M - 2 * T.CAVE_SITE_JITTER_M;
      if (minSpacing < nominalMin - 0.5) {
        fails.push(`min site spacing ${minSpacing.toFixed(1)}m < the ${nominalMin}m the grid guarantees (${minPair})`);
      }

      // ── B. realized density ─────────────────────────────────────────────────────────────
      // Rocky fraction of the SAME box, sampled on a coarse grid (the density denominator).
      let rockySamples = 0, totalSamples = 0;
      for (let x = -BOX; x <= BOX; x += 120) {
        for (let z = -BOX; z <= BOX; z += 120) {
          totalSamples++;
          if (ctx.biomes.biomeAt(x, z) === 'rocky') rockySamples++;
        }
      }
      const rockyFrac = rockySamples / totalSamples;
      // Exclude the origin-protected disc from the area — no site can be there by design.
      const areaKm2 = ((2 * BOX) ** 2 - Math.PI * clr * clr) / 1e6;
      const perKm2 = listA.length / areaKm2;
      const perKm2Rocky = perKm2 / Math.max(1e-6, rockyFrac);
      // Zach's own unit: encounters per hour of travel (13km at WALK_SPEED, 150m sighting corridor).
      const encPerHour = 13000 * 2 * 150 * (perKm2 / 1e6);

      // ── C. the hole mechanism, in isolation ─────────────────────────────────────────────
      // A patch of loaded terrain far from the origin cave and from any streamed site.
      const HX = -520, HZ = 340;
      ctx.player.body.body.setTranslation({ x: HX, y: ctx.terrain.heightAt(HX, HZ) + 2, z: HZ }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      await frames(30);
      const holeSitesNear = g.caveSites(HX, HZ, 400).length;
      const block = (() => {
        // The same grid-aligned block the real path uses — derived through the shipped helper by
        // asking the terrain for a hole at exactly this site.
        const CELL = T.TERRAIN_CHUNK_SIZE / T.TERRAIN_CHUNK_CELLS;
        return { x: Math.round(HX / CELL) * CELL, z: Math.round(HZ / CELL) * CELL };
      })();
      const samples = [];
      for (let i = -7; i <= 7; i++) {
        for (let j = -7; j <= 7; j++) samples.push({ x: block.x + i * 2.6, z: block.z + j * 2.6 });
      }
      const castDown = (x, z) => {
        const ray = new g.RAPIER.Ray({ x, y: 400, z }, { x: 0, y: -1, z: 0 });
        const hit = ctx.physics.world.castRay(ray, 800, true);
        return hit ? 400 - hit.timeOfImpact : null;
      };
      const before = samples.map((s) => castDown(s.x, s.z));
      const nullsBefore = before.filter((v) => v === null).length;
      if (nullsBefore) fails.push(`${nullsBefore}/${samples.length} probe rays MISSED bare terrain before any hole — the probe is broken, not the terrain`);
      // The band-decomposition indexing proof: the collider surface must agree with heightAt.
      let worstVsHeight = 0;
      for (let i = 0; i < samples.length; i++) {
        if (before[i] === null) continue;
        const d = Math.abs(before[i] - ctx.terrain.heightAt(samples[i].x, samples[i].z));
        if (d > worstVsHeight) worstVsHeight = d;
      }
      if (worstVsHeight > 0.35) fails.push(`terrain collider disagrees with heightAt by ${worstVsHeight.toFixed(2)}m before any hole`);

      const hb = g.caveHoleBlock(block.x, block.z);
      ctx.terrain.addCaveHole('gate:hole', hb);
      await frames(4);                                  // step physics so the QueryPipeline sees it
      const during = samples.map((s) => castDown(s.x, s.z));
      let insideHit = 0, outsideMoved = 0, outsideMissed = 0, worstOutside = 0, insideMissed = 0;
      for (let i = 0; i < samples.length; i++) {
        const s = samples[i];
        const inside = s.x > hb.xMin + 0.6 && s.x < hb.xMax - 0.6 && s.z > hb.zMin + 0.6 && s.z < hb.zMax - 0.6;
        if (inside) {
          if (during[i] !== null && Math.abs(during[i] - before[i]) < 0.05) insideHit++;
          else insideMissed++;
        } else if (s.x < hb.xMin - 1.5 || s.x > hb.xMax + 1.5 || s.z < hb.zMin - 1.5 || s.z > hb.zMax + 1.5) {
          if (during[i] === null) outsideMissed++;
          else {
            const d = Math.abs(during[i] - before[i]);
            if (d > worstOutside) worstOutside = d;
            if (d > 1e-4) outsideMoved++;
          }
        }
      }
      if (insideMissed === 0) fails.push('the carved hole let NO ray through — addCaveHole did not open the sheet (vacuous)');
      if (insideHit) fails.push(`${insideHit} rays still hit the sheet INSIDE the carved hole — the hole is not a real opening`);
      if (outsideMissed) fails.push(`${outsideMissed} rays fell through OUTSIDE the hole — the band decomposition left a gap in the sheet`);
      if (outsideMoved) fails.push(`${outsideMoved} sample heights MOVED outside the hole (worst ${worstOutside.toFixed(4)}m) — the decomposed sheet is not the same surface`);

      ctx.terrain.removeCaveHole('gate:hole');
      await frames(4);
      const after = samples.map((s) => castDown(s.x, s.z));
      let restoreMax = 0, restoreMissed = 0;
      for (let i = 0; i < samples.length; i++) {
        if (after[i] === null) { restoreMissed++; continue; }
        const d = Math.abs(after[i] - before[i]);
        if (d > restoreMax) restoreMax = d;
      }
      if (restoreMissed) fails.push(`${restoreMissed} rays still fall through after removeCaveHole — the sheet was NOT restored`);
      if (restoreMax > 0) fails.push(`terrain surface differs by ${restoreMax.toFixed(4)}m after a hole open/close cycle — restore is not exact`);
      if (ctx.terrain.caveHoleKeys().length) fails.push(`hole registry not empty after removal: ${ctx.terrain.caveHoleKeys().join(',')}`);

      // ── D. the live lifecycle ───────────────────────────────────────────────────────────
      const target = listA.find((s) => Math.hypot(s.x, s.z) < 4000) || listA[0];
      const APPROACH = 140;
      const px = target.x - APPROACH, pz = target.z;
      // THE AUTO DRIVER IS OFF FOR THIS LEG. The leak canaries below compare counts at the SAME
      // player position with and without the cave; letting the density poll stream a DIFFERENT
      // nearby cave in between would make the comparison meaningless (and the first run of this
      // gate duly reported a "leak" that was the chunk ring breathing, not the cave).
      ctx.caveStream.setSiteSource(null);
      const settleAt = async (sx, sz) => {
        ctx.player.body.body.setTranslation({ x: sx, y: ctx.terrain.heightAt(sx, sz) + 2, z: sz }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        // The terrain ring builds ONE sliced tile at a time (~18 frames each) — waiting a fixed 90
        // frames was not enough and the request was refused for a tile that simply hadn't arrived.
        for (let f = 0; f < 1200; f++) {
          await raf();
          if (f > 60 && ctx.terrain.isTileLoadedAt(target.x, target.z) && g.chunkStats().activeKeys.length) {
            if (f > 200) break;
          }
        }
      };
      await settleAt(px, pz);
      if (!ctx.terrain.isTileLoadedAt(target.x, target.z)) fails.push('the site tile never loaded at the approach position');

      const baseBodies = ctx.physics.world.bodies.len();
      const baseWater = ctx.waterSources.list.length;
      const basePools = g.chunkStats().totalPools;
      const baseMats = g.chunkStats().totalPoolMaterials;
      g.resetCavePerf();
      const progKeys = () => (ctx.three.renderer.info.programs ?? []).map((p) => String(p.cacheKey ?? ''));
      const keysBefore = progKeys();
      const progBefore = keysBefore.length;

      const queued = g.requestCaveSite(target);
      if (!queued) fails.push(`requestCaveSite refused ${target.key} — its terrain tile was not loaded at ${APPROACH}m`);
      // THE WORST FRAME IS ATTRIBUTED TO A NAMED STAGE, not left anonymous (DEEPER cycle 8, closing
      // agent). A bare "worst frame 1592ms" is unactionable and — worse — invites the assumption
      // that it is the one stage already reported (the tor), which it was not. The scheduler's
      // pending stage is sampled BEFORE the frame that pays for it, so the number and the stage that
      // produced it are the same event. `heavyFrames` keeps every frame over 40ms in order, which is
      // what turns "something hitched" into "these three stages, in this sequence".
      // Only frame 0 is excluded — it carries this probe's own `resetCavePerf` + `requestCaveSite`.
      // It used to be `f > 2`, which quietly excluded the CREVICE TOR: the request lands on f=0, the
      // scheduler picks the queue item up on f=1 and runs the ~155ms unsliced tor on f=2, so the one
      // stage the module documents as unsliced was the one stage this number could not see. `tor=…ms`
      // reported it separately, so nothing was hidden — but a field called `worst frame` that skips
      // the worst frame is the kind of half-true number this project has been bitten by, and with the
      // stage attribution below there is no reason to keep the hole.
      let builtFrames = 0, worstFrameMs = 0, worstFrameStage = '-', last = performance.now();
      const heavyFrames = [];
      let progsOnVisibleFrame = 0;
      for (let f = 0; f < 9000; f++) {
        const p0 = ctx.caveStream.pending();
        const stg = p0 ? p0.stage : (ctx.caveStream.queued() ? 'queued' : 'idle');
        const nProg0 = ctx.three.renderer.info.programs?.length ?? 0;
        await raf();
        const now = performance.now(); const gap = now - last; last = now;
        if (f > 0) {
          if (gap > worstFrameMs) { worstFrameMs = gap; worstFrameStage = stg; }
          if (gap > 40 && heavyFrames.length < 24) heavyFrames.push(`${stg}:${gap.toFixed(0)}`);
        }
        builtFrames++;
        const st = g.cavePerf();
        if (st.residents.some((x) => x.key === target.key)) {
          // THE frame that put the cave in the scene. Whatever it compiled, it compiled while the
          // player was looking at it — that is the 1.6s stall, and it must be zero.
          progsOnVisibleFrame = (ctx.three.renderer.info.programs?.length ?? 0) - nProg0;
          break;
        }
      }
      const keysAfter = progKeys();
      const progAfter = keysAfter.length;
      const beforeSet = new Set(keysBefore);
      const newPrograms = keysAfter.filter((k) => !beforeSet.has(k)).map((k) => k.slice(0, 260));
      const built = g.cavePerf();
      const res1 = built.residents.find((x) => x.key === target.key);
      if (!res1) fails.push(`the streamed cave ${target.key} never built in ${builtFrames} frames`);
      const firstDigest = res1 ? res1.digest : '-';
      if (res1 && !(res1.tris > 0)) fails.push('the streamed cave has 0 visual triangles');
      if (res1 && !(res1.colliderTris > 0)) fails.push('the streamed cave has 0 COLLIDER triangles');
      const holeOpen = ctx.terrain.caveHoleKeys().includes(target.key);
      if (!holeOpen) fails.push(`no carved terrain hole for the resident cave ${target.key} — the sheet never opened`);
      const siteRec = built.sites.find((x) => x.key === target.key);
      if (siteRec && !siteRec.hasEntrance) fails.push('the streamed resident carries no crevice entrance');
      const bodiesWith = ctx.physics.world.bodies.len();

      // Release it by walking out of range while its TERRAIN TILE is still loaded.
      const ox = target.x - (T.CAVE_STREAM_DROP_M + 80), oz = target.z;
      ctx.player.body.body.setTranslation({ x: ox, y: ctx.terrain.heightAt(ox, oz) + 2, z: oz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      let released = false;
      for (let f = 0; f < 900; f++) {
        await raf();
        if (!g.cavePerf().residents.some((x) => x.key === target.key)) { released = true; break; }
      }
      if (!released) fails.push('the streamed cave was never released after moving out of range');
      const tileStillLoaded = ctx.terrain.isTileLoadedAt(target.x, target.z);
      if (!tileStillLoaded) fails.push('the site tile unloaded too — the teardown test did not exercise a hole close on a LIVE tile');
      if (ctx.terrain.caveHoleKeys().includes(target.key)) fails.push('the carved hole SURVIVED the cave that owned it — an opening onto nothing');
      // Back to the EXACT approach position (still no auto driver) so the canaries compare like
      // with like: the same chunk ring, the same tiles, the only difference being the cave.
      await settleAt(px, pz);
      const endBodies = ctx.physics.world.bodies.len();
      const endWater = ctx.waterSources.list.length;
      const endPools = g.chunkStats().totalPools;
      const endMats = g.chunkStats().totalPoolMaterials;
      if (endBodies !== baseBodies) fails.push(`rigid-body LEAK: ${baseBodies} → ${bodiesWith} → ${endBodies} across one stream in/out`);
      if (endWater !== baseWater) fails.push(`water-source LEAK: ${baseWater} → ${endWater} (a released cave's pools outlived it)`);
      if (endPools !== basePools) fails.push(`pool-registry LEAK: ${basePools} → ${endPools}`);
      if (endMats !== baseMats) fails.push(`pool-MATERIAL LEAK: ${baseMats} → ${endMats}`);

      // Re-entry: the same site must re-derive the SAME cave.
      if (!g.requestCaveSite(target)) fails.push('requestCaveSite refused the re-entry request');
      let secondDigest = '-';
      for (let f = 0; f < 9000; f++) {
        await raf();
        const rr = g.cavePerf().residents.find((x) => x.key === target.key);
        if (rr) { secondDigest = rr.digest; break; }
      }
      if (secondDigest === '-') fails.push('the released cave never re-streamed on return');
      else if (secondDigest !== firstDigest) {
        fails.push(`RE-ENTRY digest ${secondDigest} != first visit ${firstDigest} — a streamed cave is not descriptor-stable`);
      }
      if (!ctx.terrain.caveHoleKeys().includes(target.key)) fails.push('the hole did not reopen on re-entry');

      const end = g.cavePerf();
      // ── THE SHADER WARM-UP HAS TEETH (DEEPER cycle 8, closing agent). The 1.6s finalize frame was
      //    a COLD PROGRAM LINK inside the frame that made the cave visible, not anything in the
      //    build — `renderer.info.programs` grew by 2 across that one frame. Two numbers guard it,
      //    and they guard different failures: `warms` proves the precompile stage RAN AT ALL (a
      //    silently-skipped warm would leave every other number looking healthy on a machine whose
      //    programs happened to be cached), and `progsOnVisibleFrame` proves it WORKED.
      //
      //    ⚠ THE MEASUREMENT THAT LOOKS RIGHT AND IS NOT, because the first version of this check was
      //    it: comparing the program count across the WHOLE build. That count legitimately grows —
      //    by exactly the 2 programs the warm-up compiles — so the check failed on the fixed build.
      //    A gate that reds on healthy work is the same class of error as one that greens on broken
      //    work (the `open-end`/leviathan-front-door precedent). What actually matters is narrower:
      //    nothing may be compiled on THE frame that puts the cave in the scene, which is the frame
      //    the player pays for. Compiles on the warm-up frames are the fix doing its job.
      if (!end.stream.warms) fails.push('the shader warm-up never ran for a streamed cave build — the precompile stage is not wired');
      if (progsOnVisibleFrame > 0) {
        fails.push(`${progsOnVisibleFrame} shader program(s) compiled ON THE FRAME the cave became visible `
          + `— the warm-up missed them (build total ${progBefore}→${progAfter}): [${newPrograms.map((k) => k.split(',').pop()).join(' ')}]`);
      }
      if (end.stream.warmTimeouts) {
        fails.push(`${end.stream.warmTimeouts} warm-up(s) hit CAVE_WARM_MAX_FRAMES and finalized anyway — the cold-compile stall is back`);
      }
      // Measured cave extent vs the spacing the grid guarantees (leg A's real teeth).
      let extent = 0;
      for (const rr of ctx.caveStream.residents()) {
        const b = rr.box;
        extent = Math.max(extent, Math.hypot(b.max.x - b.min.x, b.max.z - b.min.z));
      }
      if (minSpacing < extent) {
        fails.push(`min site spacing ${minSpacing.toFixed(0)}m < the MEASURED cave extent ${extent.toFixed(0)}m — two cave bodies can interpenetrate`);
      }
      return {
        fails, skipped: false, siteDigest, sites: listA.length, beatSites,
        minSpacing: +minSpacing.toFixed(1), nominalMin, extent: +extent.toFixed(1),
        rockyFrac: +rockyFrac.toFixed(3), perKm2: +perKm2.toFixed(3), perKm2Rocky: +perKm2Rocky.toFixed(2),
        encPerHour: +encPerHour.toFixed(2),
        seamSites, seamAt,
        worstVsHeight: +worstVsHeight.toFixed(3), restoreMax: +restoreMax.toFixed(4),
        insideMissed, outsideMissed, outsideMoved, holeSitesNear,
        firstDigest, secondDigest, released: released ? 1 : 0, tileStillLoaded: tileStillLoaded ? 1 : 0,
        baseBodies, bodiesWith, endBodies,
        torMs: +end.stream.maxTorMs.toFixed(1), finMs: +end.stream.maxFinalizeMs.toFixed(1),
        teardownMs: +end.stream.maxTeardownMs.toFixed(1),
        holeRebuildMs: +end.holeStats.maxRebuildMs.toFixed(2), holeRebuilds: end.holeStats.rebuilds,
        worstFrameMs: +worstFrameMs.toFixed(1), worstFrameStage, heavyFrames, builtFrames,
        progBefore, progAfter, newPrograms, progsOnVisibleFrame,
        warms: end.stream.warms, warmMs: +end.stream.maxWarmMs.toFixed(1),
        warmFrames: end.stream.maxWarmFrames, warmTimeouts: end.stream.warmTimeouts,
        maxSliceMs: +end.stream.maxSliceMs.toFixed(1), maxAtomicMs: +end.stream.maxAtomicMs.toFixed(1),
        worstAtomicStage: end.stream.worstAtomicStage, maxStepMs: +end.stream.maxStepMs.toFixed(1),
      };
    });
    if (r.skipped) { console.log(`CAVE-DENSITY pass=0 SKIPPED ${JSON.stringify(r.fails)}`); throw new Error('cave-density GATE FAILED'); }
    // DEEPER cycle 12 — GATE A rides this leg as a sub-row (no 25th leg, no port churn).
    {
      const bf = (r.fails || []).filter((f) => String(f).startsWith('BEAT-SITES'));
      for (const f of bf) console.log(`[cave-density] BEAT-SITES FAIL ${f.replace(/^BEAT-SITES /, '')}`);
      console.log(`[cave-density] BEAT-SITES ${JSON.stringify(r.beatSites || {})}`);
      console.log(`BEAT-SITES pass=${bf.length === 0 ? 1 : 0} fails=${bf.length}`);
    }
    const pass = r.fails.length === 0;
    console.log(`CAVE-DENSITY pass=${pass ? 1 : 0} digest=${r.siteDigest} sites=${r.sites} spacing=${r.minSpacing}m/${r.nominalMin}m extent=${r.extent}m rocky=${r.rockyFrac} perKm2=${r.perKm2} perKm2Rocky=${r.perKm2Rocky} encPerHour=${r.encPerHour} restoreMax=${r.restoreMax}m reentry=${r.firstDigest === r.secondDigest ? 1 : 0} bodies=${r.baseBodies}->${r.bodiesWith}->${r.endBodies} tor=${r.torMs}ms fin=${r.finMs}ms teardown=${r.teardownMs}ms holeRebuild=${r.holeRebuildMs}ms slice=${r.maxSliceMs}ms atomic=${r.maxAtomicMs}ms(${r.worstAtomicStage}) warm=${r.warmMs}ms/${r.warmFrames}f×${r.warms} progs=${r.progBefore}->${r.progAfter}(visibleFrame ${r.progsOnVisibleFrame}) frame=${r.worstFrameMs}ms(${r.worstFrameStage}) fails=${r.fails.length}`);
    console.log(`[cave-density] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r)}`);
    if (!pass) throw new Error('cave-density GATE FAILED');
  },

  // ── DEEPER cycle 8 — THE CHARTER GATE: STREAMED CAVES GET WALKED AND VOID-SAMPLED ────────────
  //
  //   WHY THIS EXISTS, in one sentence: `cave-walk` and `cave-void` have only ever run on the ORIGIN
  //   cave, and cycle 8 just made caves a world-wide feature built from the SAME generator at
  //   DESCRIPTOR INPUTS THE ORIGIN CAVE NEVER EXERCISES — a different seed, a different surface
  //   height, a different crevice heading, a different local terrain. "Same generator, so it must be
  //   fine" is exactly the argument this project's history refutes: UNDERWORLD shipped on a 2-seed
  //   net and widening that net immediately surfaced two generator defects (sibling-corridor crossing
  //   and the chamber-disk/corridor-ramp step), both fixed BY CONSTRUCTION. A cave you cannot walk out
  //   of, or can see through, is exactly as broken 4km from spawn as it is at spawn — and far less
  //   likely to be noticed, because nobody hand-tests the far field.
  //
  //   WHAT IT DOES, per seed:
  //     1. Takes the N nearest streamed cave sites from the deterministic `caveSites` list. Nearest
  //        rather than random, so the gate walks the caves a player is most likely to meet, and so
  //        the set is stable run-to-run (a flaky gate gets ignored).
  //     2. Streams each in THROUGH THE REAL PATH — the player is teleported to within
  //        CAVE_STREAM_REQUEST_M, the terrain ring is allowed to build its tiles, and then the
  //        shipped `pollSites` → `requestSite` → sliced build → atomic finalize → `addCaveHole`
  //        chain runs on its own. Nothing here fabricates a junction: if the density system cannot
  //        deliver a cave at a site it advertises, this gate says so.
  //     3. Runs the FULL `cave-walk` machinery on it (`residentKey`) — the Euler-tour KCC march over
  //        every chamber, the crevice descent AND ASCENT, the corridor sweeps, the chamber-floor
  //        grid, the topology asserts — and the FULL `cave-void` sweep. Same code, not a copy.
  //
  //   ⚠ STRANDS ARE REPORTED LOUDLY AND ARE NEVER PAPERED OVER. A nonzero strand count means the
  //     capsule got wedged somewhere and the Euler tour continued measuring from the wrong place. On
  //     the origin cave that has been treated as a tolerated steering artefact; on a streamed cave at
  //     unexercised descriptor inputs it is the leading indicator of a real wedge trap, so it rides
  //     the summary line and `verify:chunks` prints it whether the run is green or red.
  //
  //   COST, and the compromise — stated because the alternative is a gate nobody runs:
  //     the full march is ~2-4 minutes of real KCC walking PER CAVE. Void-sampling is ~10-25s.
  //     Defaults are therefore `--sites=2 --march=1`: BOTH nearest sites are void-sampled, the
  //     nearest is additionally fully marched. Per seed that is 1 full march + 2 void sweeps; over
  //     the two gate seeds, 2 marched streamed caves + 4 void-sampled streamed caves. Raise
  //     `--march=2` to walk both (that is what the cycle-8 measurement run did) — the flag exists so
  //     the deeper net is one word away, and a suspicious change should use it.
  //
  //   Run: npm run rig -- --scenario=cave-streamed --seed=1337 --port=5238 [--sites=2] [--march=1]
  'cave-streamed': async (page) => {
    const NSITES = Math.max(1, Number(argv.sites ?? 2));
    const NMARCH = Math.max(0, Number(argv.march ?? 1));

    // ── Pick the sites. Nearest-first from the origin, but never so near that the origin cave's own
    //    terrain neighbourhood is involved — CAVE_SITE_ORIGIN_CLEAR_M already guarantees that. ──
    const picked = await page.evaluate((N) => {
      const g = window.__game; const ctx = g.ctx;
      if (!ctx.caveStream) return { fatal: 'ctx.caveStream is null — the cave scheduler did not boot' };
      ctx.sandWorms.list.length = 0;
      ctx.vultures.list.length = 0;
      ctx.weather.intensity = 0;
      const all = g.caveSites(0, 0, 6000);
      if (all.length < N) return { fatal: `only ${all.length} cave sites within 6km — cannot pick ${N}` };
      const near = all
        .map((s) => ({ ...s, d: Math.hypot(s.x, s.z) }))
        .sort((a, b) => a.d - b.d)
        .slice(0, N);
      return { sites: near, total: all.length, seed: ctx.seed };
    }, NSITES);
    if (picked.fatal) { console.log(`CAVE-STREAMED pass=0 FATAL ${picked.fatal}`); throw new Error('cave-streamed FAILED'); }
    console.log(`[cave-streamed] seed=${picked.seed} ${picked.total} sites within 6km; walking the nearest ${picked.sites.length}: ` +
      picked.sites.map((s) => `${s.key}@(${s.x.toFixed(0)},${s.z.toFixed(0)})d${s.d.toFixed(0)}m`).join(' '));

    const fails = [];
    const details = [];
    let marched = 0, voided = 0, strandTotal = 0, escTotal = 0, excTotal = 0, culTotal = 0, holeTotal = 0;
    let voidPoints = 0, voidRays = 0, minChambers = 99, marchOk = 0, ascentOut = 0;

    for (let i = 0; i < picked.sites.length; i++) {
      const site = picked.sites[i];
      const doMarch = i < NMARCH;
      const t0 = Date.now();

      // ── ARRIVAL, through the shipped streaming path ───────────────────────────────────────
      //    The site source is parked while the player is moved and the terrain ring catches up,
      //    then re-installed so the REAL `pollSites` does the requesting. That ordering is not a
      //    shortcut around the streamer — it reproduces what actually happens in play (you walk
      //    into a neighbourhood whose tiles are already built) and it removes the one source of
      //    nondeterminism that would otherwise decide WHICH cave this gate walks: with the source
      //    live during a 300-frame teleport settle, the poll can latch a different nearby site and
      //    the gate silently measures a cave it did not choose.
      const arrive = await page.evaluate(async (S) => {
        const g = window.__game; const ctx = g.ctx; const T = g.Tuning;
        const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
        const notes = [];
        ctx.caveStream.setSiteSource(null);
        // Stand well inside CAVE_STREAM_REQUEST_M, and closer to this site than the grid can put
        // any other one (min spacing is CELL − 2·JITTER), so "nearest first" resolves to our target.
        const APPROACH = Math.min(120, T.CAVE_STREAM_REQUEST_M * 0.4);
        const px = S.x - APPROACH, pz = S.z;
        ctx.player.body.body.setTranslation({ x: px, y: ctx.terrain.heightAt(px, pz) + 2, z: pz }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        // The terrain ring builds ONE sliced tile at a time; wait for the site's tile specifically.
        let tileFrames = 0;
        for (let f = 0; f < 2000; f++) {
          await raf(); tileFrames++;
          if (f > 90 && ctx.terrain.isTileLoadedAt(S.x, S.z)) break;
        }
        if (!ctx.terrain.isTileLoadedAt(S.x, S.z)) {
          return { ok: false, why: `the site's terrain tile never loaded from ${APPROACH}m away in ${tileFrames} frames`, tileFrames };
        }
        // Re-install the SHIPPED site source and let the streamer decide on its own.
        ctx.caveStream.setSiteSource((x, z, r) => window.__caveSites(x, z, r));
        g.resetCavePerf();
        let buildFrames = 0, worstFrameMs = 0, last = performance.now();
        let arrived = false;
        for (let f = 0; f < 9000; f++) {
          await raf(); buildFrames++;
          const now = performance.now(); const gap = now - last; last = now;
          if (f > 2 && gap > worstFrameMs) worstFrameMs = gap;
          if (ctx.caveStream.residents().some((r) => r.key === S.key)) { arrived = true; break; }
        }
        const p = g.cavePerf();
        if (!arrived) {
          return {
            ok: false, tileFrames, buildFrames,
            why: `the streamer never built ${S.key} in ${buildFrames} frames (requests=${p.stream.requests}, queued=${p.queued}, pending=${p.pending ? p.pending.key + '/' + p.pending.stage : 'none'}, residents=[${p.residents.map((r) => r.key).join(',')}])`,
          };
        }
        // PARK THE SOURCE FOR THE WALK. Not to hide anything — to keep the march measuring the cave
        // this leg chose. With it live, a second site 300-330m away can queue mid-march, and its
        // unsliced ~180ms tor frame lands inside the KCC walk; worse, a third resident would invite
        // the cap to evict. Everything the live source does is already gated by `cave-density`.
        ctx.caveStream.setSiteSource(null);
        const res = p.residents.find((r) => r.key === S.key);
        const rec = p.sites.find((r) => r.key === S.key);
        return {
          ok: true, tileFrames, buildFrames, worstFrameMs: +worstFrameMs.toFixed(1),
          requests: p.stream.requests, torMs: +p.stream.maxTorMs.toFixed(1),
          finMs: +p.stream.maxFinalizeMs.toFixed(1), sliceMs: +p.stream.maxSliceMs.toFixed(1),
          atomicMs: +p.stream.maxAtomicMs.toFixed(1), atomicStage: p.stream.worstAtomicStage,
          tris: res ? res.tris : 0, colliderTris: res ? res.colliderTris : 0, digest: res ? res.digest : '-',
          hasEntrance: rec ? rec.hasEntrance : false,
          holeOpen: ctx.terrain.caveHoleKeys().includes(S.key),
          residents: p.residents.map((r) => r.key),
        };
      }, site);

      if (!arrive.ok) {
        fails.push(`${site.key}: ${arrive.why}`);
        details.push(`${site.key} @(${site.x.toFixed(0)},${site.z.toFixed(0)}) d=${site.d.toFixed(0)}m  *** NEVER ARRIVED *** ${arrive.why}`);
        continue;
      }
      // The streamed unit must be WHOLE before it is worth walking (rule 9 — geometry and collision
      // together, plus the carved hole that makes it reachable at all).
      if (!(arrive.tris > 0)) fails.push(`${site.key}: streamed cave has 0 visual triangles`);
      if (!(arrive.colliderTris > 0)) fails.push(`${site.key}: streamed cave has 0 COLLIDER triangles`);
      if (!arrive.hasEntrance) fails.push(`${site.key}: streamed resident carries no crevice entrance`);
      if (!arrive.holeOpen) fails.push(`${site.key}: no carved terrain hole — the sheet never opened over the cave`);

      // ── THE MARCH — the identical `cave-walk` gate, pointed at this resident ───────────────
      let w = null;
      if (doMarch) {
        w = await SCENARIOS['cave-walk'](page, { residentKey: site.key, noShots: true, noThrow: true });
        marched++;
        if (w.fails.length) {
          for (const f of w.fails) fails.push(`${site.key} march: ${f}`);
        } else { marchOk++; }
        if (w.exited) ascentOut++;
        else if (!w.fails.length) fails.push(`${site.key} march: reported no failures but never exited the cave`);
        const st = (w.strands || []).length;
        strandTotal += st;
        if (st) {
          // Loud, on purpose. A strand is a wedge trap until proven otherwise.
          console.log(`[cave-streamed] ⚠ ${site.key} STRANDED ${st} leg(s) — the capsule could not walk back out of a chamber it had reached: [${w.strands.join(' ')}]`);
        }
        if (typeof w.chambers === 'number' && w.chambers < minChambers) minChambers = w.chambers;
      }

      // ── THE VOID SWEEP — the identical `cave-void` gate, pointed at this resident ──────────
      const v = await SCENARIOS['cave-void'](page, { residentKey: site.key, noShots: true, noThrow: true });
      voided++;
      if (v.fatal) {
        fails.push(`${site.key} void: ${v.fatal}`);
      } else {
        escTotal += v.escapes; excTotal += v.excused; culTotal += v.culled; holeTotal += v.holes;
        voidPoints += v.points; voidRays += v.totalRays;
        if (v.escapes > 0) {
          fails.push(`${site.key} void: ${v.escapes} unexcused escapes (${v.escapeRate}%) across ${v.leakyPoints}/${v.points} points — culled=${v.culled} holes=${v.holes}`);
          for (const x of v.worst.slice(0, 6)) console.log(`[cave-streamed] ${site.key} VOID ${x.label.padEnd(28)} esc=${x.esc}/${v.K} culled=${x.culled} hole=${x.hole} at ${JSON.stringify(x.p)}`);
        }
        // The excused count is reported and asserted, not merely printed: a declared opening that
        // starts swallowing rays would quietly convert a see-through into a "pass".
        if (v.excused > 0) fails.push(`${site.key} void: ${v.excused} rays excused through a declared opening — the origin cave excuses none, so this is new behaviour to explain, not to accept`);
      }

      const secs = ((Date.now() - t0) / 1000).toFixed(0);
      details.push(
        `${site.key} @(${site.x.toFixed(0)},${site.z.toFixed(0)}) d=${site.d.toFixed(0)}m seed=${site.seed} ` +
        `arrive=${arrive.buildFrames}f/${arrive.tileFrames}tileF tor=${arrive.torMs}ms fin=${arrive.finMs}ms slice=${arrive.sliceMs}ms atomic=${arrive.atomicMs}ms(${arrive.atomicStage}) tris=${arrive.tris}/${arrive.colliderTris} hole=${arrive.holeOpen ? 1 : 0} digest=${arrive.digest} | ` +
        (w ? `MARCH chambers=${w.chambers} reached=${w.reached}/${w.chambers} tour=${w.tour} ascent=${w.exited ? 'OUT' : 'FAIL'} strands=${(w.strands || []).length} slope=${w.maxSlope}° head=${w.minHeadroom} chamHead=${w.chamMinHead} cover=${w.minCover} eggDepth=${w.eggDepth}m crevice=${w.entSlope}°/${w.entPinchW}m fails=${w.fails.length} | ` : 'MARCH skipped | ') +
        (v.fatal ? `VOID FATAL ${v.fatal}` : `VOID points=${v.points} rays=${v.totalRays} escapes=${v.escapes} excused=${v.excused} culled=${v.culled} holes=${v.holes}`) +
        ` | ${secs}s`,
      );
    }

    if (marched === 0 && NMARCH > 0) fails.push('no streamed cave was marched — the gate would have passed by measuring nothing');
    if (voided === 0) fails.push('no streamed cave was void-sampled — the gate would have passed by measuring nothing');
    if (voided < picked.sites.length) fails.push(`only ${voided}/${picked.sites.length} sites were reached`);

    const pass = fails.length === 0;
    console.log(`CAVE-STREAMED pass=${pass ? 1 : 0} seed=${picked.seed} sites=${picked.sites.length} marched=${marched} voided=${voided} marchOk=${marchOk}/${marched} ascentOut=${ascentOut}/${marched} minChambers=${minChambers === 99 ? 0 : minChambers} strands=${strandTotal} voidPoints=${voidPoints} voidRays=${voidRays} escapes=${escTotal} excused=${excTotal} culled=${culTotal} holes=${holeTotal} fails=${fails.length}`);
    for (const d of details) console.log(`[cave-streamed] ${d}`);
    if (fails.length) for (const f of fails) console.log(`[cave-streamed] FAIL ${f}`);
    if (!pass) throw new Error('cave-streamed GATE FAILED');
  },

  // ── cave-kinds (DEEPER cycle 9) — THE KIND GATE ─────────────────────────────────────────────
  //
  //   WHAT IT PROVES, and why each half exists:
  //
  //   1. THE MIX IS REAL AND PURE. Over a large box of deterministic sites, every kind occurs at
  //      roughly its weight and NO KIND IS ABSENT. The absent-kind check is the vacuous-pass guard
  //      that matters most here: a typo in the weight table, a reordered `CAVE_KIND_LIST`, or a
  //      broken hash would produce a world that still builds caves and still passes every other
  //      gate — it would just quietly only ever build one kind. The weighted picker is ALSO tested
  //      directly over 20k uniform rolls, because a site sample can only ever be a loose check.
  //
  //   2. EVERY KIND IS WALKABLE AND WATERTIGHT. Per kind: a REAL streamed build at a REAL
  //      descriptor-accepted site, then the FULL `cave-walk` Euler-tour KCC march (every chamber,
  //      the crevice descent AND ascent, corridor sweeps, chamber-floor grids, topology) and the
  //      FULL `cave-void` sweep. Same shared code as the origin gate and as `cave-streamed` —
  //      pointed at this resident by `residentKey` — never a second copy that can drift.
  //
  //   HOW A KIND GETS UNDER TEST. The gate takes the N nearest sites the placement rules already
  //   accepted and requests each through the SHIPPED entry point (`caveStream.requestSite`, the same
  //   call `pollSites` makes) with the kind OVERRIDDEN. It does not hunt the world for a site that
  //   happened to roll the kind under test: that would make the gate's coverage depend on the
  //   weights, so re-tuning the mix could silently stop testing a kind. Everything else — the tor,
  //   the sliced interior build, the atomic finalize, the carved terrain hole — is the real path.
  //
  //   3. THE KIND ACTUALLY TOOK. Walk-green is necessary and nowhere near sufficient: a kind table
  //      that silently fell back to canonical would march perfectly. So each kind asserts its own
  //      DEFINING signal (the warren's room count + its scrap, the fungal cavern's fungi, the
  //      flooded cave's pools, the shaft's depth + rubble), and the cross-kind block asserts the
  //      kinds differ from each other in the ways the table claims.
  //
  //   4. NO KIND OUTGROWS ITS PLOT. The measured horizontal extent of each kind's cave must stay
  //      under the minimum spacing the site grid guarantees, or two cave bodies can interpenetrate.
  //      Cycle 8 asserts this for the canonical cave; a bigger kind is exactly how it would break.
  //
  //   COST — stated because the alternative is a gate nobody runs. A full march is ~2-4 minutes of
  //   real KCC walking per cave, plus ~40-60s of arrival and ~20s of void sampling. Four kinds is
  //   ~18-22 minutes at one seed. The PERMANENT leg in `verify:chunks` is therefore each kind × the
  //   ONE seed 1337 (4 marches); the x3 seed net (12 marches, seeds 1337/7/4242) was run once at
  //   cycle 9 and is one flag away (`--seed=`) whenever the generator is touched again.
  //
  //   Run: npm run rig -- --scenario=cave-kinds --seed=1337 --port=52xx
  //        …--kinds=shaft --march=0 --shots=1     (fast: build + smoke shots, no march)
  'cave-kinds': async (page) => {
    const ALL = ['warren', 'fungal', 'flooded', 'shaft'];
    const KINDS = argv.kinds ? String(argv.kinds).split(',').map((k) => k.trim()).filter(Boolean) : ALL;
    const DO_MARCH = argv.march === undefined ? 1 : Number(argv.march);
    const DO_VOID = argv.void === undefined ? 1 : Number(argv.void);
    const DO_SHOTS = Number(argv.shots || 0);
    // `--siteOffset=N` shifts which nearest-sites the kinds land on. It exists for ONE reason and it
    // is a diagnostic one: when a kind fails at its site, the only way to tell a KIND defect from a
    // SITE defect is to put a DIFFERENT kind on the SAME site. Default 0 = the permanent gate.
    const SITE_OFFSET = Number(argv.siteOffset || argv.siteoffset || 0);
    const fails = [];
    const details = [];

    // ── A. THE TABLE + THE MIX ──────────────────────────────────────────────────────────────
    const dist = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      if (!ctx.caveStream) return { fatal: 'ctx.caveStream is null — the cave scheduler did not boot' };
      const out = { fails: [] };
      const table = g.caveKindTable();
      out.kinds = table.kinds;
      out.weights = table.weights;

      // A1 — the PICKER itself, over a uniform sweep. Exact, cheap, and independent of placement:
      //      if the weighted selection is wrong this fails in milliseconds instead of hiding behind
      //      the noise of a site sample.
      const N = 20000; const hit = {};
      for (const k of table.kinds) hit[k] = 0;
      for (let i = 0; i < N; i++) hit[g.pickCaveKind((i + 0.5) / N)]++;
      let tot = 0; for (const k of table.kinds) tot += table.weights[k];
      out.pickerShare = {}; out.pickerWant = {};
      for (const k of table.kinds) {
        const got = hit[k] / N, want = table.weights[k] / tot;
        out.pickerShare[k] = +got.toFixed(4); out.pickerWant[k] = +want.toFixed(4);
        if (Math.abs(got - want) > 0.01) out.fails.push(`picker: '${k}' takes ${(got * 100).toFixed(1)}% of a uniform sweep, weights say ${(want * 100).toFixed(1)}%`);
      }

      // A2 — the REAL site list. Purity first (two derivations must agree on every kind), then the
      //      observed share, then the hard no-kind-absent rule.
      const BOX = 9000;
      const derive = () => g.caveSites(0, 0, BOX * Math.SQRT2)
        .filter((s) => Math.abs(s.x) <= BOX && Math.abs(s.z) <= BOX)
        .sort((a, b) => (a.gx - b.gx) || (a.gz - b.gz));
      const A = derive(), B = derive();
      out.sites = A.length;
      if (A.length !== B.length) out.fails.push(`site list length is not stable (${A.length} vs ${B.length})`);
      let kindDrift = 0;
      for (let i = 0; i < Math.min(A.length, B.length); i++) if (A[i].kind !== B[i].kind) kindDrift++;
      if (kindDrift) out.fails.push(`${kindDrift} sites changed KIND between two derivations — the kind roll is not pure (D290)`);
      if (A.length < 120) out.fails.push(`only ${A.length} sites in an 18km box — too few to audit the mix (vacuous-pass guard)`);
      // ── A3 — THE ENTRANCE-HEADROOM INVARIANT, over the WHOLE listed population (DEEPER cycle 9).
      //   The defect this closes was not visible to any march: 11% of seed-1337's sites and 10.5% of
      //   seed-7's pinched the roofed descent under the 1.70m capsule, and `cave-kinds` only found it
      //   because ONE of its four picked sites happened to be one of them. A per-site march can never
      //   be the net for a population-wide placement defect — the population is.
      //
      //   THE BOUND IS THE PHYSICAL REQUIREMENT, NOT THE POLICY DIAL. `CREVICE_MIN_CLEAR_M` (2.25) is
      //   what placement rejects on; this gate asserts 2.10 — the 1.90m the capsule actually needs
      //   (1.70 + KCC/step margin) plus the 0.20m by which the noise-free model was MEASURED to read
      //   high against the ray instrument. Hard-coding the requirement here rather than reading the
      //   dial is the whole point: lower the dial and this goes RED, which is exactly the red/green
      //   proof this tooth was signed off on.
      const MODEL_BOUND = 2.10;
      const clearOf = window.__caveClear;
      if (!clearOf) out.fails.push('__caveClear is not exposed — the entrance-headroom invariant could not be swept (vacuous-pass guard)');
      else {
        let worst = Infinity, worstAt = null, under = 0;
        for (const s of A) {
          const h = clearOf({ x: s.x, z: s.z }, s.seed).minH;
          if (h < worst) { worst = h; worstAt = s; }
          if (h < MODEL_BOUND) under++;
        }
        out.clearWorst = +worst.toFixed(2);
        out.clearWorstAt = worstAt ? { x: +worstAt.x.toFixed(0), z: +worstAt.z.toFixed(0), kind: worstAt.kind } : null;
        out.clearUnder = under;
        out.clearBound = MODEL_BOUND;
        if (under > 0) {
          out.fails.push(`${under}/${A.length} listed sites model a descent clearance under ${MODEL_BOUND}m `
            + `(worst ${worst.toFixed(2)}m at ${worstAt ? `(${worstAt.x.toFixed(0)},${worstAt.z.toFixed(0)})` : '?'}) — those caves cannot be walked into. `
            + 'Placement rule 8 (CREVICE_MIN_CLEAR_M) is not holding.');
        }
      }

      const count = {}; for (const k of table.kinds) count[k] = 0;
      let unknown = 0;
      for (const s of A) { if (count[s.kind] === undefined) unknown++; else count[s.kind]++; }
      if (unknown) out.fails.push(`${unknown} sites carry a kind that is not in CAVE_KIND_LIST`);
      out.count = count;
      out.share = {};
      for (const k of table.kinds) {
        const got = count[k] / Math.max(1, A.length), want = table.weights[k] / tot;
        out.share[k] = +got.toFixed(4);
        // NO KIND ABSENT is the hard rule; the band is deliberately loose (a few hundred sites is a
        // small sample and this is a distribution check, not a chi-squared test).
        if (count[k] === 0) out.fails.push(`kind '${k}' does not occur ONCE in ${A.length} sites — it is unreachable in play`);
        else if (got < want * 0.55 || got > want * 1.45) out.fails.push(`kind '${k}' takes ${(got * 100).toFixed(1)}% of ${A.length} sites, weights say ${(want * 100).toFixed(1)}% (±45% band)`);
      }
      return out;
    });
    if (dist.fatal) { console.log(`CAVE-KINDS pass=0 FATAL ${dist.fatal}`); throw new Error('cave-kinds FAILED'); }
    for (const f of dist.fails) fails.push(`mix: ${f}`);
    console.log(`[cave-kinds] mix over ${dist.sites} sites: ` + dist.kinds.map((k) => `${k}=${dist.count[k]}(${(dist.share[k] * 100).toFixed(1)}%/want ${(dist.pickerWant[k] * 100).toFixed(1)}%)`).join(' '));
    if (dist.clearWorst !== undefined) {
      console.log(`[cave-kinds] entrance headroom over ${dist.sites} sites: worst modelled clear ${dist.clearWorst}m`
        + `${dist.clearWorstAt ? ` at (${dist.clearWorstAt.x},${dist.clearWorstAt.z}) [${dist.clearWorstAt.kind}]` : ''}`
        + ` · under ${dist.clearBound}m: ${dist.clearUnder}`);
    }

    // ── B. PICK THE SITES. Nearest-first, one per kind under test. ─────────────────────────
    const picked = await page.evaluate((N) => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0; ctx.vultures.list.length = 0; ctx.weather.intensity = 0;
      const all = g.caveSites(0, 0, 6000);
      if (all.length < N) return { fatal: `only ${all.length} cave sites within 6km — cannot pick ${N}` };
      return {
        seed: ctx.seed,
        sites: all.map((s) => ({ ...s, d: Math.hypot(s.x, s.z) })).sort((a, b) => a.d - b.d).slice(0, N),
      };
    }, KINDS.length + SITE_OFFSET);
    if (picked.fatal) { console.log(`CAVE-KINDS pass=0 FATAL ${picked.fatal}`); throw new Error('cave-kinds FAILED'); }

    const per = {};
    let marched = 0, voided = 0, built = 0, strandTotal = 0, escTotal = 0;
    let lightChecked = 0;   // DEEPER cycle 10 — kinds whose light teeth actually ran

    for (let i = 0; i < KINDS.length; i++) {
      const kind = KINDS[i];
      const site = picked.sites[i + SITE_OFFSET];
      const key = `kindgate:${kind}`;
      const t0 = Date.now();

      // ── ARRIVAL through the shipped streaming path, with the kind forced. ────────────────
      const arrive = await page.evaluate(async (S) => {
        const g = window.__game; const ctx = g.ctx; const T = g.Tuning;
        const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
        // Park the descriptor-driven source: this leg builds ONE named cave and must measure that
        // one. (Identical reasoning to `cave-streamed`; the density system is gated elsewhere.)
        ctx.caveStream.setSiteSource(null);
        const APPROACH = Math.min(120, T.CAVE_STREAM_REQUEST_M * 0.4);
        const px = S.x - APPROACH, pz = S.z;
        ctx.player.body.body.setTranslation({ x: px, y: ctx.terrain.heightAt(px, pz) + 2, z: pz }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        let tileFrames = 0;
        for (let f = 0; f < 2000; f++) {
          await raf(); tileFrames++;
          if (f > 90 && ctx.terrain.isTileLoadedAt(S.x, S.z)) break;
        }
        if (!ctx.terrain.isTileLoadedAt(S.x, S.z)) return { ok: false, why: `terrain tile never loaded in ${tileFrames} frames` };
        g.resetCavePerf();
        // THE SHIPPED ENTRY POINT, kind overridden. `requestSite` is what `pollSites` calls.
        const queued = ctx.caveStream.requestSite({ key: S.key, x: S.x, z: S.z, seed: S.seed, kind: S.kind });
        if (!queued) return { ok: false, why: 'requestSite refused the synthesized descriptor' };
        let buildFrames = 0, worstFrameMs = 0, last = performance.now(), arrived = false;
        for (let f = 0; f < 9000; f++) {
          await raf(); buildFrames++;
          const now = performance.now(); const gap = now - last; last = now;
          if (f > 2 && gap > worstFrameMs) worstFrameMs = gap;
          if (ctx.caveStream.residents().some((r) => r.key === S.key)) { arrived = true; break; }
        }
        const p = g.cavePerf();
        if (!arrived) return { ok: false, buildFrames, why: `the streamer never built ${S.key} in ${buildFrames} frames (queued=${p.queued}, pending=${p.pending ? p.pending.stage : 'none'})` };
        const res = ctx.caveStream.residents().find((r) => r.key === S.key);
        const pr = res.cave.probe;
        // ── THE ENTRANCE-HEADROOM MEASUREMENT (DEEPER cycle 9), with physics rays against the
        //    SHIPPED colliders. The population sweep in section A is the broad net and it runs on a
        //    MODEL; this is the calibration that stops the model laundering a defect. Same sampling
        //    as the `crevice-profile` instrument (0.3m of arc along the real station polyline, start
        //    the down-ray INSIDE the slot so the intact terrain sheet overhead is never mistaken for
        //    the floor), minus the width rays this gate does not need.
        //
        //    ⚠ THE FRAMES BELOW ARE LOAD-BEARING and their absence is the exact failure this project
        //    has already shipped once: Rapier's QueryPipeline only rebuilds inside `world.step()`, so
        //    a ray cast on the same tick the cave's colliders were inserted queries a pipeline that
        //    has never seen them. The first cut of this sweep did that and reported "27 descent
        //    samples found NO FLOOR" at a site the ray instrument measures as perfectly sound — a
        //    gate that invents a defect, which is the same class of error as one that hides a defect.
        const RAPIER = g.RAPIER;
        for (let f = 0; f < 3; f++) await raf();
        const pbody = ctx.player.body.body;
        const upTo = (x, y, z) => {
          const h = ctx.physics.world.castRay(new RAPIER.Ray({ x, y, z }, { x: 0, y: 1, z: 0 }), 14, true, undefined, undefined, undefined, pbody);
          return h ? h.timeOfImpact : Infinity;
        };
        let minClear = null, minClearAt = null, clearGaps = 0, clearSamples = 0;
        const eline = res.entrance ? res.entrance.line : null;
        if (eline) {
          const stn = eline.stations;
          let acc = 0;
          for (let i = 1; i < stn.length; i++) {
            const a = stn[i - 1], b = stn[i];
            const dx = b.x - a.x, dz = b.z - a.z, D = Math.hypot(dx, dz) || 1;
            const ux = dx / D, uz = dz / D;
            for (let t = 0; t < D - 1e-6; t += 0.3) {
              const x = a.x + ux * t, z = a.z + uz * t;
              const guess = a.floorY + (b.floorY - a.floorY) * (t / D);
              let hit = g.castDown(x, z, guess + 1.2, true);
              if (!hit) hit = g.castDown(x, z, guess + 0.4, true);
              if (!hit) { clearGaps++; continue; }
              clearSamples++;
              const h = Math.min(14, upTo(x, hit.hitY + 0.12, z) + 0.12);
              if (minClear === null || h < minClear) { minClear = +h.toFixed(2); minClearAt = { s: +(acc + t).toFixed(2), x: +x.toFixed(1), z: +z.toFixed(1) }; }
            }
            acc += D;
          }
        }
        // Measured horizontal extent of THIS cave body — the number the site grid's guaranteed
        // spacing has to clear (see leg 4 in the header).
        const b = res.box;
        let meshes = 0; res.cave.group.traverse((o) => { if (o.isMesh) meshes++; });
        return {
          ok: true, buildFrames, tileFrames, worstFrameMs: +worstFrameMs.toFixed(1),
          minClear, minClearAt, clearGaps, clearSamples,
          capH: +((ctx.player.body.halfHeight + ctx.player.body.radius) * 2).toFixed(2),
          modelClear: window.__caveClear ? +window.__caveClear({ x: S.x, z: S.z }, S.seed).minH.toFixed(2) : null,
          kind: pr.kind, envelope: pr.envelope, digest: pr.digest,
          chambers: pr.nodes.length, edges: pr.edges.length,
          eggRx: +pr.nodes[pr.eggId].rx.toFixed(1), eggDepth: +pr.depthBelowSurface.toFixed(1),
          fungiClusters: pr.fungiClusters, rubbleHeaps: pr.rubbleHeaps, scrapAnchors: pr.scrapAnchors,
          fungiWallShelves: pr.fungiWallShelves ?? -1, fungiWallHidden: pr.fungiWallHidden ?? -1,
          pools: pr.pools.length, poolR: pr.pools.map((q) => q.r),
          squeezes: pr.edges.filter((e) => e.squeeze).length,
          corridorH: +Math.min.apply(null, pr.edges.map((e) => e.height)).toFixed(2),
          tris: pr.triCount, colliderTris: pr.colliderTris, meshes,
          extent: +Math.hypot(b.max.x - b.min.x, b.max.z - b.min.z).toFixed(1),
          minSpacing: +g.caveSiteMinSpacing().toFixed(0),
          torMs: +p.stream.maxTorMs.toFixed(1), finMs: +p.stream.maxFinalizeMs.toFixed(1),
          sliceMs: +p.stream.maxSliceMs.toFixed(1), atomicMs: +p.stream.maxAtomicMs.toFixed(1),
          atomicStage: p.stream.worstAtomicStage,
          holeOpen: ctx.terrain.caveHoleKeys().includes(S.key),
          // The warren's scrap is a PICKUP spawned by the resident sink, not cave geometry — so it
          // is counted in the live pickup list, which is the only place a dangling one would show.
          // UNDERGROUND-ONLY: `transient` scrap is also what the D299 streamed wreck scrap rings
          // are, so a plain radius test counts surface salvage too (the first run of this gate read
          // 19 pickups against 6 anchors, and read non-zero for kinds that scatter none). A pickup
          // more than 3m BELOW the terrain sheet can only have come from a cave.
          scrapPickups: ctx.pickups.list.filter((q) => q.itemId === 'scrap' && q.transient
            && Math.hypot(q.pos.x - S.x, q.pos.z - S.z) < 400
            && q.pos.y < ctx.terrain.pureHeightAt(q.pos.x, q.pos.z) - 3).length,
        };
      }, { ...site, key, kind });

      if (!arrive.ok) {
        fails.push(`${kind}: ${arrive.why}`);
        details.push(`${kind.padEnd(8)} *** NEVER BUILT *** ${arrive.why}`);
        continue;
      }
      built++;
      per[kind] = arrive;

      // ── THE KIND ACTUALLY TOOK (leg 3) ──────────────────────────────────────────────────
      if (arrive.kind !== kind) fails.push(`${kind}: the resident reports kind '${arrive.kind}' — the override did not reach the generator`);
      if (!arrive.holeOpen) fails.push(`${kind}: no carved terrain hole — the sheet never opened over the cave`);
      // ── THE ENTRANCE-HEADROOM TOOTH (DEEPER cycle 9). 1.90m = the 1.70m capsule plus the margin a
      //    KCC needs to walk rather than scrape. Measured with rays, so it cannot be laundered by the
      //    model the placement rule uses — and it names the metre it failed at, which is the whole
      //    difference between this and "could not walk leg slot2".
      if (arrive.minClear === null) {
        fails.push(`${kind}: the resident carries no crevice entrance — the headroom measurement could not run (vacuous-pass guard)`);
      } else {
        if (arrive.clearSamples < 20) fails.push(`${kind}: only ${arrive.clearSamples} headroom samples along the descent — the sweep did not actually run`);
        if (arrive.minClear < 1.90) {
          fails.push(`${kind}: descent clear height falls to ${arrive.minClear}m at s=${arrive.minClearAt.s} (${arrive.minClearAt.x},${arrive.minClearAt.z}) `
            + `— the capsule is ${arrive.capH}m tall, so this cave cannot be entered (model said ${arrive.modelClear}m)`);
        }
        if (arrive.clearGaps > 0) fails.push(`${kind}: ${arrive.clearGaps} descent samples found NO FLOOR under the slot`);
      }
      if (!(arrive.tris > 0) || !(arrive.colliderTris > 0)) fails.push(`${kind}: ${arrive.tris} visual / ${arrive.colliderTris} collider triangles`);
      if (arrive.extent >= arrive.minSpacing) fails.push(`${kind}: measured cave extent ${arrive.extent}m ≥ the site grid's guaranteed min spacing ${arrive.minSpacing}m — two cave bodies of this kind can interpenetrate`);
      if (kind === 'warren') {
        if (arrive.chambers < 10) fails.push(`warren: only ${arrive.chambers} chambers — the warren is supposed to be MANY small rooms`);
        if (arrive.scrapAnchors < 4) fails.push(`warren: ${arrive.scrapAnchors} scrap anchors — the salvage scatter did not happen`);
        if (arrive.scrapPickups !== arrive.scrapAnchors) fails.push(`warren: ${arrive.scrapPickups} live UNDERGROUND scrap pickups for ${arrive.scrapAnchors} anchors — the resident sink did not spawn exactly one per anchor`);
        if (arrive.squeezes < arrive.edges * 0.5) fails.push(`warren: only ${arrive.squeezes}/${arrive.edges} corridors are squeezes`);
      }
      if (kind !== 'warren' && arrive.scrapPickups > 0) fails.push(`${kind}: ${arrive.scrapPickups} underground scrap pickups near a kind that scatters none — either the anchors leaked or a previously-evicted cave's pickups were never despawned`);
      if (kind === 'fungal') {
        if (arrive.fungiClusters < 15) fails.push(`fungal: ${arrive.fungiClusters} fungi clusters — a canonical cave already carries ~7-13, so the density did not take`);
        if (arrive.eggRx < 11) fails.push(`fungal: egg chamber rx ${arrive.eggRx}m — the vault did not take`);
      }
      if (kind === 'flooded') {
        if (arrive.pools < 4) fails.push(`flooded: only ${arrive.pools} pools — canonical already carries 1-3`);
      }
      if (kind === 'shaft') {
        if (arrive.eggDepth < 40) fails.push(`shaft: egg depth ${arrive.eggDepth}m — the shaft did not descend`);
        if (arrive.rubbleHeaps < 3) fails.push(`shaft: ${arrive.rubbleHeaps} rubble heaps — the collapse dressing did not take`);
      }

      // ── THE FUNGI CONTACT ASSERT (DEEPER cycle-9 close-out round 2, finding N3 half ii) ───────
      //
      //   WHY IT EXISTS. "Are the mushrooms attached to anything?" has been argued from STILLS for
      //   three rounds — a critic spots a cap hanging in the dark, a fix lands, a later frame shows
      //   another one, and nobody can say whether the rest of the cave is sound because a frame only
      //   ever contains the handful of anchors that happen to be lit. That is exactly the class of
      //   defect this project's own lesson says must become a NUMBER: every failure that got a
      //   machine gate stopped recurring; every failure that got only prose recurred.
      //
      //   WHAT IT MEASURES. Every fungi anchor in the built cave — floor clusters AND wall shelves —
      //   raycast against the SHIPPED COLLIDERS (rule 9: the trimesh IS the visible geometry) and the
      //   distance to rock asserted ≤ eps. Floors cast straight down; wall shelves cast back along
      //   the anchor normal they declared. `--fungiEps=` exists so the tooth can be RED-PROVED
      //   without editing this file (tighten it absurdly, watch the leg go red, restore).
      const FUNGI_EPS = argv.fungiEps === undefined ? 0.25 : Number(argv.fungiEps);
      const contact = await page.evaluate(async (S) => {
        const g = window.__game; const ctx = g.ctx; const RAPIER = g.RAPIER;
        const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
        // ⚠ Rapier's QueryPipeline only rebuilds inside `world.step()` — a ray cast on the tick the
        //   cave's colliders were inserted queries a pipeline that has never seen them (this project
        //   has already shipped a gate that invented a defect exactly this way).
        for (let f = 0; f < 3; f++) await raf();
        const res = ctx.caveStream.residents().find((r) => r.key === S.key);
        if (!res) return { fatal: 'the resident vanished before the contact sweep' };
        const pbody = ctx.player.body.body;
        const bad = []; let ok = 0;
        for (const c of res.cave.fungi) {
          // SIGNED: +gap = the cluster hovers over the rock (the defect this exists for); -gap = it is
          // bedded INTO the rock, which is only a defect once it swallows the stalks, so it gets its
          // own (looser) allowance instead of being reported as "floating".
          // START THE RAY JUST ABOVE THE ANCHOR, not a metre up. A 1m column through a cave floor
          // catches whatever DRESSING happens to stand at the same (x, z) — a stalagmite flank, a
          // heap boulder — and reports the mushroom as buried under it. That is a gate inventing a
          // defect, the same class of error as one hiding a defect, and it did exactly that on two
          // anchors (fungal -0.45m, shaft -0.57m: both stable across three rebuilds, both bogus).
          // `eps` above the anchor is the honest origin: it can still see a float of any size, and it
          // cannot see a rock whose surface is already higher than the anchor's own tolerance.
          const h = g.castDown(c.pos.x, c.pos.z, c.pos.y + S.eps, true);
          const d = h ? c.pos.y - h.hitY : null;
          // …and the second measurement is kept for the DIAGNOSTIC only, so a real burial is still
          // nameable rather than silently excused by the shorter ray.
          const hi = g.castDown(c.pos.x, c.pos.z, c.pos.y + 1.0, true);
          const dHi = hi ? +(c.pos.y - hi.hitY).toFixed(2) : null;
          if (d !== null && d <= S.eps && d >= -S.sink) ok++;
          else bad.push({ t: 'floor', at: [+c.pos.x.toFixed(1), +c.pos.y.toFixed(1), +c.pos.z.toFixed(1)], gap: d === null ? null : +d.toFixed(2), fromAbove: dHi });
        }
        const shelves = [];
        res.cave.group.traverse((o) => { const w = o.userData && o.userData.wallShelf; if (w && o.visible) shelves.push(w); });
        for (const w of shelves) {
          const B = 1.5;
          const hit = ctx.physics.world.castRay(
            new RAPIER.Ray({ x: w.x + w.nx * B, y: w.y + w.ny * B, z: w.z + w.nz * B },
              { x: -w.nx, y: -w.ny, z: -w.nz }),
            B + 1.2, true, undefined, undefined, undefined, pbody,
          );
          const d = hit ? hit.timeOfImpact - B : null;   // + = the mount stands off the rock
          if (d !== null && d <= S.eps && d >= -S.sink) ok++;
          else bad.push({ t: 'wall', at: [+w.x.toFixed(1), +w.y.toFixed(1), +w.z.toFixed(1)], gap: d === null ? null : +d.toFixed(2) });
        }
        return { ok, bad: bad.length, worst: bad.slice(0, 6), floors: res.cave.fungi.length, walls: shelves.length };
      }, { key, eps: FUNGI_EPS, sink: Math.max(FUNGI_EPS, 0.45) });
      if (contact.fatal) fails.push(`${kind} fungiContact: ${contact.fatal}`);
      else {
        const total = contact.ok + contact.bad;
        console.log(`[cave-kinds] ${kind} fungiContact ok=${contact.ok} bad=${contact.bad} `
          + `(${contact.floors} floor clusters + ${contact.walls} visible wall shelves, eps ${FUNGI_EPS}m)`);
        if (total === 0) fails.push(`${kind} fungiContact: ZERO anchors measured — every kind seeds fungi, so this check passed by measuring nothing`);
        if (contact.bad > 0) {
          fails.push(`${kind} fungiContact: ${contact.bad}/${total} fungi anchors are not touching rock (stand-off > ${FUNGI_EPS}m, or bedded deeper than ${Math.max(FUNGI_EPS, 0.45)}m) — the mount is not a mount`);
          for (const b of contact.worst) console.log(`[cave-kinds] ${kind} fungiContact FLOAT ${b.t} at ${JSON.stringify(b.at)} gap=${b.gap === null ? 'NO ROCK FOUND' : b.gap + 'm'}${b.fromAbove === undefined ? '' : ` (1m-column read ${b.fromAbove}m)`}`);
        }
      }

      // ── THE MARCH + THE VOID SWEEP — the identical shared gates, pointed at this resident ──
      let w = null;
      if (DO_MARCH) {
        w = await SCENARIOS['cave-walk'](page, { residentKey: key, noShots: true, noThrow: true });
        marched++;
        for (const f of w.fails) fails.push(`${kind} march: ${f}`);
        if (!w.exited && !w.fails.length) fails.push(`${kind} march: reported no failures but never exited the cave`);
        const st = (w.strands || []).length;
        strandTotal += st;
        if (st) console.log(`[cave-kinds] ⚠ ${kind} STRANDED ${st} leg(s) — the capsule could not walk back out of a chamber it had reached: [${w.strands.join(' ')}]`);
      }
      // `--void=0` is an ITERATION flag only (a look pass reshoots the same cave a dozen times and
      // the sweep is ~40s of that loop). The permanent gate never passes it, and `--void=0` also
      // suppresses the pass line below so a skipped sweep can never be reported as a green one.
      const v = DO_VOID
        ? await SCENARIOS['cave-void'](page, { residentKey: key, noShots: true, noThrow: true })
        : { skipped: true, escapes: 0, excused: 0, points: 0, rays: 0 };
      if (DO_VOID) voided++;
      if (v.fatal) fails.push(`${kind} void: ${v.fatal}`);
      else if (DO_VOID) {
        escTotal += v.escapes;
        if (v.escapes > 0) {
          fails.push(`${kind} void: ${v.escapes} unexcused escapes (${v.escapeRate}%) across ${v.leakyPoints}/${v.points} points`);
          for (const x of v.worst.slice(0, 6)) console.log(`[cave-kinds] ${kind} VOID ${x.label.padEnd(28)} esc=${x.esc}/${v.K} at ${JSON.stringify(x.p)}`);
        }
        if (v.excused > 0) fails.push(`${kind} void: ${v.excused} rays excused through a declared opening — the origin cave excuses none`);
      }
      per[kind].walk = w; per[kind].voidSweep = v;

      // Smoke shots are DIAGNOSTIC, never load-bearing: a framing that throws must not take the
      // walk/void result down with it. THEY RUN BEFORE THE TEARDOWN LEG — the teardown deliberately
      // teleports 5km away and EVICTS the resident, so shooting after it silently produced zero
      // warren frames ("no resident to shoot") for the whole of cycle 9.
      if (DO_SHOTS) { try { await caveKindShots(page, kind, key); } catch (e) { console.log(`[cave-kinds] ${kind} shots failed: ${e.message}`); } }

      // ── THE LIGHT GATE (DEEPER cycle 10). Two teeth, both from Zach's walk-test, both run against
      //   the STREAMED population because that is where the origin-scoped cycle-7 fix stopped
      //   applying: (A) the deep chamber's read must not change between noon and midnight, and (B)
      //   hiding the sun/moon sprites must not change a single pixel of an upward deep framing.
      //   See `caveLightAsserts` for the tolerances and why B is a per-pixel A/B and not a max.
      //   Cost: ~10 renders per kind, ~8s total for the leg — it does not move the suite budget.
      //   RUNS BEFORE THE TEARDOWN LEG, for the same reason the shots do.
      {
        const lg = await caveLightAsserts(page, kind, key);
        for (const row of lg.rows) console.log(row);
        for (const f of lg.fails) fails.push(`light: ${f}`);
        if (!lg.rows.length) fails.push(`light: ${kind} produced NO light-gate rows — the light teeth did not run (VACUOUS)`);
        else lightChecked++;
        per[kind].light = lg.data || null;
      }

      // ══ DEEPER cycle 12, GATE B — BEAT-BUILD ═══════════════════════════════════════════════
      //    The dead explorer, proven on the built cave through the REAL paths. Rides `cave-kinds`
      //    because it is the only leg that builds a warren by construction (`pool-fill` boots the
      //    preloaded ORIGIN cave, which is canonical and by design never carries the beat).
      //
      //      1. It exists at its seed-pure anchor — skeleton, journal and cache all present.
      //      2. It is seated on the REAL cave floor, proven by COLLIDER IDENTITY rather than by a
      //         plausible number: the hit collider must belong to the cave's own rigid body. This is
      //         the rule-9 idiom `skyfall-walk` and cycle 11's LANTERN-RT both use, and it is the
      //         only thing separating "on the cave floor" from "on the terrain sheet 30m overhead".
      //      3. It is READABLE through the shipped interaction path — real WASD under gravity, never
      //         a teleport (the leviathan-walk lesson: that leg was once green on an unclimbable ramp
      //         because its waypoints teleported). `placeJournal` does NOT register itself, so this
      //         tooth is the one that catches a beat that is visible, correct and completely inert.
      //      4. It GRANTS ONCE — empty it, save, read SAVE_VERSION out of the written JSON (a stray
      //         bump reds this), reload, and the cache must not refill.
      if (kind === 'warren') {
        const bb = await page.evaluate(async () => {
          const g = window.__game; const ctx = g.ctx;
          const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
          const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
          const fails = []; const notes = {};
          notes.stage = 'init';
          const S = (n) => { notes.stage = n; };
          try {
            ctx.flags.paused = false; ctx.flags.thirdPerson = false;
            S('resident');
            const res = (ctx.caveStream ? ctx.caveStream.residents() : []).find((q) => q.cave && q.cave.beatAnchor);
            if (!res) return { fails: ['no resident cave published a beatAnchor'], notes };
            const ba = res.cave.beatAnchor;
            const A = { x: ba.pos.x, y: ba.pos.y, z: ba.pos.z };
            notes.key = res.key;

            // ── 1. EXISTS (with vacuous guards — "green because nothing was tested" is the failure
            //       mode cycles 5 and 8 both hit).
            S('exists');
            const near2 = (p, r) => Math.hypot(p.x - A.x, p.z - A.z) < r;
            const journal = ctx.journals.list.find((j) => near2(j.pos, 2.0));
            if (!journal) fails.push('no journal registered within 2m of the beat anchor — placeJournal does not self-register');
            else if (journal.kind !== 'cave_explorer') fails.push(`journal kind is '${journal.kind}', expected 'cave_explorer'`);
            const crate = ctx.lootContainers.list.find((c) => near2(c.pos, 2.5));
            if (!crate) fails.push('no loot container within 2.5m of the beat anchor');
            notes.cacheItems = crate ? crate.contents.length : 0;
            if (crate && crate.contents.length === 0) fails.push('the cache spawned EMPTY — every grant assertion below would be vacuous');
            let tableaus = 0;
            ctx.three.scene.traverse((o) => { if (o.name === 'deadExplorer') tableaus++; });
            notes.tableaus = tableaus;
            if (tableaus !== 1) fails.push(`${tableaus} deadExplorer tableaus in the scene, expected exactly 1`);

            // ── 2. SEATED ON REAL CAVE ROCK, BY COLLIDER IDENTITY.
            S('floor-identity');
            if (!res.cave.body) fails.push('the resident has no rigid body — collider identity cannot be asserted');
            else {
              const handles = new Set();
              for (let i = 0; i < res.cave.body.numColliders(); i++) handles.add(res.cave.body.collider(i).handle);
              const hit = g.castDown(A.x, A.z, A.y + 1.6, true);
              if (!hit) fails.push('a downcast from above the beat anchor hit NOTHING');
              else {
                notes.anchorGap = +(A.y - hit.hitY).toFixed(3);
                if (Math.abs(A.y - hit.hitY) > 0.05) fails.push(`the beat anchor is ${(A.y - hit.hitY).toFixed(3)}m off the real floor (>5cm)`);
                if (!handles.has(hit.colliderHandle)) fails.push('the floor under the beat is NOT the cave body — it is the terrain sheet or another collider');
              }
            }

            // DIAGNOSTIC (W-4 close-out): anchor↔pool geometry + a floor transect. Two fixes shipped
            // on the "basin skirt under the seat" hypothesis and neither moved the gap a millimetre —
            // so print what is actually true before a third.
            {
              const pools = (res.cave.probe.pools || []).map((p) => ({
                d: +Math.hypot(p.x - A.x, p.z - A.z).toFixed(2), r: +p.r.toFixed(2),
                skirt: +(p.r * g.Tuning.CAVE_POOL_BASIN_R_MUL).toFixed(2),
              }));
              const tx = [];
              for (let t = -1.0; t <= 1.01; t += 0.25) {
                const px = A.x + t * 1.0, pz = A.z;   // a 2m X-transect through the anchor
                const h = g.castDown(px, pz, A.y + 1.6, true);
                tx.push(h ? +(A.y - h.hitY).toFixed(3) : null);
              }
              notes.diag = { anchor: { x: +A.x.toFixed(1), y: +A.y.toFixed(2), z: +A.z.toFixed(1) }, pools, transectX: tx };
            }
            // ── 2b. NOTHING IN THE TABLEAU FLOATS. The permanent form of the defect this cycle
            //    actually fixed: the anchor is exact only AT THE SEAT, and a rigid 2.4m arrangement
            //    over displaced rock left the journal 8.8cm and the lantern 10.0cm in the air.
            //    Measured per prop as LOWEST VERTEX vs the rock under its own footprint — an object's
            //    origin is not its contact point (a tipped lantern rests on its cage), and the anchor
            //    plane is not the prop.
            //
            //    ⚠ THIS TOOTH EXISTS BECAUSE THE ANCHOR TOOTH ABOVE HAS NO TEETH HERE. Seating the
            //    anchor on the ANALYTIC plane instead of the real rock — the historical bug — was
            //    red-proof-attempted and came back at 4.2cm on this seed, INSIDE the 5cm bar. So the
            //    5cm anchor check passes on a build with the old bug in it; this per-prop check is
            //    what actually holds the line, and it IS red-provable (10.0cm before the fix).
            S('bedding');
            {
              const beat = ctx.three.scene.getObjectByName('deadExplorer');
              const props = [];
              if (beat) {
                beat.updateMatrixWorld(true);
                beat.traverse((o) => { if (o.userData && o.userData.beatProp) props.push([o.userData.beatProp, o]); });
              }
              if (journal) props.push(['journal', journal.mesh]);
              if (crate) props.push(['crate', crate.mesh]);
              if (!props.length) fails.push('BEDDING measured no props — the check would pass by testing nothing');
              const gaps = {};
              for (const [nm, o] of props) {
                const bb = new g.THREE.Box3().setFromObject(o);
                if (!isFinite(bb.min.y)) continue;
                const cx2 = (bb.min.x + bb.max.x) / 2, cz2 = (bb.min.z + bb.max.z) / 2;
                const h = g.castDown(cx2, cz2, bb.max.y + 1.6, true);
                if (!h) { fails.push(`BEDDING no rock found under '${nm}'`); continue; }
                const gap = bb.min.y - h.hitY;
                gaps[nm] = +gap.toFixed(3);
                if (gap > 0.05) fails.push(`BEDDING '${nm}' hangs ${gap.toFixed(3)}m above the rock (>5cm of daylight)`);
              }
              notes.bedding = gaps;
            }

            // ── 3. READABLE THROUGH THE REAL PATH. Walk with WASD under gravity to the journal.
            //    Skipped (not thrown) when tooth 1 already found no journal: the absence is ALREADY
            //    reported above, and a NPE here would bury it.
            if (journal) {
            S('walk');
            const body = ctx.player.body.body;
            const CAP = ctx.player.body.halfHeight + ctx.player.body.radius;
            const at = () => { const t = body.translation(); return { x: t.x, y: t.y, z: t.z }; };
            const face = (dx, dz) => {
              const cam = ctx.three.camera; const t = body.translation();
              const L = Math.hypot(dx, dz) || 1;
              cam.position.set(t.x, t.y + ctx.player.eyeOffset, t.z);
              cam.lookAt(t.x + dx / L, t.y + ctx.player.eyeOffset, t.z + dz / L);
              cam.updateMatrixWorld(true);
            };
            // Start 3.5m off along the room-centre bearing (never inside the wall the body leans on).
            const node = res.cave.probe.nodes.reduce((b, n) =>
              (Math.hypot(n.x - A.x, n.z - A.z) < Math.hypot(b.x - A.x, b.z - A.z) ? n : b), res.cave.probe.nodes[0]);
            let bx = node.x - A.x, bz = node.z - A.z;
            const bl = Math.hypot(bx, bz) || 1; bx /= bl; bz /= bl;
            const sx = A.x + bx * 3.5, sz = A.z + bz * 3.5;
            const sh = g.castDown(sx, sz, A.y + 3, true);
            body.setTranslation({ x: sx, y: (sh ? sh.hitY : A.y) + CAP + 0.2, z: sz }, true);
            body.setLinvel({ x: 0, y: 0, z: 0 }, true); ctx.player.velocityY = 0;
            await frames(30);
            const startD = Math.hypot(at().x - journal.pos.x, at().z - journal.pos.z);
            ctx.input.keys['KeyW'] = true;
            let best = Infinity, stall = 0;
            for (let i = 0; i < 420; i++) {
              const p = at();
              const dx = journal.pos.x - p.x, dz = journal.pos.z - p.z;
              const d = Math.hypot(dx, dz);
              face(dx, dz);
              await raf();
              if (d < 1.6) break;
              if (d < best - 0.03) { best = d; stall = 0; } else if (++stall > 150) break;
            }
            ctx.input.keys['KeyW'] = false;
            await frames(6);
            const endP = at();
            notes.walk = { startD: +startD.toFixed(2), endD: +Math.hypot(endP.x - journal.pos.x, endP.z - journal.pos.z).toFixed(2) };
            if (!(startD > 2.0)) fails.push(`the walk started ${startD.toFixed(2)}m from the journal — too close to prove anything`);

            // Aim at the book and read the SHIPPED hover state.
            S('hover');
            const cam = ctx.three.camera; const t = body.translation();
            cam.position.set(t.x, t.y + ctx.player.eyeOffset, t.z);
            cam.lookAt(journal.pos.x, journal.pos.y + 0.05, journal.pos.z);
            cam.updateMatrixWorld(true);
            await frames(4);
            const hov = ctx.inventory.hover;
            notes.hover = hov ? { type: hov.type, d: +hov.distance.toFixed(2) } : null;
            if (!hov || hov.type !== 'read') fails.push(`no 'read' hover on the journal after walking to it (got ${hov ? hov.type : 'null'}) — the prop is inert`);

            S('read');
            const before = ctx.inventory.journalReadKinds.has('cave_explorer');
            // `ctx.input.pressed` (the EDGE set), never `ctx.input.keys` — `updateInteraction` reads
            // the edge, and `endInputFrame` clears it every frame, so a held key is not a press.
            ctx.input.pressed.add('KeyE'); await frames(2); await frames(6);
            const open = g.isJournalPanelOpen ? g.isJournalPanelOpen() : null;
            notes.panelOpen = open; notes.readBefore = before;
            if (open === false) fails.push('pressing E on the journal did not open the journal panel');
            if (!ctx.inventory.journalReadKinds.has('cave_explorer')) fails.push("reading the journal did not add 'cave_explorer' to journalReadKinds");
            if (g.closeJournalPanel) g.closeJournalPanel();
            await frames(4);
            }

            // ── 4. GRANTS ONCE. Empty it, save, reload, and it must not refill.
            S('grant');
            if (crate) {
              crate.contents.length = 0; crate.opened = true;
              const saved = g.saveGame ? g.saveGame() : null;
              const raw = window.localStorage.getItem('dustfall.save.v1');
              let ver = null;
              try { ver = JSON.parse(raw).version; } catch (e) { ver = `unparseable (${String(e && e.message)})`; }
              notes.saveVersion = ver;
              notes.saved = !!saved;
              if (ver !== 18) fails.push(`SAVE_VERSION in the written save is ${ver}, expected 18 — cycle 12 must not bump it`);
              const rec = (JSON.parse(raw).caveBeats || []).find((b) => b.key === res.key);
              notes.beatRecord = rec ? { looted: rec.looted, left: (rec.contents || []).length } : null;
              if (!rec) fails.push('the emptied cache was NOT recorded in save.caveBeats — it would refill on re-entry');
              else if (!rec.looted) fails.push('the emptied cache was recorded as not looted');
              const inArr = (JSON.parse(raw).lootContainers || []).some((c) => c.id === crate.id);
              if (inArr) fails.push('the beat container rode the id-keyed lootContainers array — its runtime id is load-order dependent (D292)');
            }
            return { fails, notes };
          } catch (e) {
            // APPEND, never replace. The first red-proof of this gate threw at the walk stage and the
            // old `return { fails: [msg] }` discarded the two findings already collected — including
            // the one that explained the throw. A gate that loses what it already knew when it trips
            // is a gate that makes the next session bisect.
            fails.push(`threw at stage '${notes.stage}': ${String((e && e.message) || e)}`);
            return { fails, notes };
          }
        }).catch((e) => ({ fails: [`BEAT-BUILD harness threw: ${String((e && e.message) || e)}`], notes: {} }));
        for (const f of (bb.fails || [])) { fails.push(`BEAT-BUILD ${f}`); console.log(`[cave-kinds] BEAT-BUILD FAIL ${f}`); }
        console.log(`[cave-kinds] BEAT-BUILD ${JSON.stringify(bb.notes || {})}`);
        console.log(`BEAT-BUILD pass=${(bb.fails || []).length === 0 ? 1 : 0} fails=${(bb.fails || []).length}`);
      }

      // ── THE SCRAP TEARDOWN LEG (warren only). ────────────────────────────────────────────
      //   A cave's scrap pickups live OUTSIDE the cave's scene graph — in `ctx.pickups` — so the
      //   resident sink has to despawn them when the cave is evicted. The dangerous case is not the
      //   happy path: it is a pickup that has ALREADY left the list before eviction, which happens
      //   every time a player takes one. `despawnPickup` on a POOLED pickup whose slot is already
      //   freed falls through to `scene.remove(pickup.mesh)`, and `mesh` is the SHARED scrap
      //   InstancedMesh — so a double despawn deletes every scrap pickup in the WORLD from the
      //   scene. This leg walks that exact sequence: take one, evict the cave by walking out of
      //   range through the shipped `releaseOutOfRange` path, and assert the pool survived and the
      //   cave's remaining scrap went with the cave.
      if (kind === 'warren' && arrive.scrapAnchors > 0) {
        const td = await page.evaluate(async (S) => {
          const g = window.__game; const ctx = g.ctx;
          const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
          const under = () => ctx.pickups.list.filter((q) => q.itemId === 'scrap' && q.transient
            && Math.hypot(q.pos.x - S.x, q.pos.z - S.z) < 400
            && q.pos.y < ctx.terrain.pureHeightAt(q.pos.x, q.pos.z) - 3);
          const before = under();
          if (!before.length) return { fatal: 'no underground scrap to take' };
          const totalScrapBefore = ctx.pickups.list.filter((q) => q.itemId === 'scrap').length;
          // 1 — TAKE one, through the shipped despawn path (what picking it up does).
          const took = g.despawnPickupById(before[0].id);
          // 2 — walk out of range: teleport far and tick until the streamer releases the resident.
          ctx.player.body.body.setTranslation({ x: S.x + 5000, y: 400, z: S.z + 5000 }, true);
          let f = 0;
          // The sim clock across the wait — `elapsedΔ` is what tells a "the streamer is slow" read
          // apart from a "the world is frozen" one. (Cycle 10: this printed 0.00s over 900 frames
          // and named the pause leak in one run; it stays because it costs nothing and the next
          // freeze will be diagnosed from the log instead of from a code read.)
          const el0 = ctx.time.elapsed;
          for (; f < 900; f++) {
            await raf();
            if (!ctx.caveStream.residents().some((r) => r.key === S.key)) break;
          }
          const simDt = +(ctx.time.elapsed - el0).toFixed(2);
          const evicted = !ctx.caveStream.residents().some((r) => r.key === S.key);
          // 3 — the shared pool must still be in the scene, and some scrap must still exist.
          const anyScrap = ctx.pickups.list.find((q) => q.itemId === 'scrap' && q.inst);
          return {
            took, evicted, frames: f, simDt,
            underAfter: under().length, totalScrapBefore,
            totalScrapAfter: ctx.pickups.list.filter((q) => q.itemId === 'scrap').length,
            poolInScene: anyScrap ? !!anyScrap.mesh.parent : null,
          };
        }, { x: site.x, z: site.z, key });
        if (td.fatal) fails.push(`warren teardown: ${td.fatal}`);
        else {
          if (!td.took) fails.push('warren teardown: could not take a cave scrap pickup');
          if (!td.evicted) fails.push(`warren teardown: the cave was never released after ${td.frames} frames 5km away`
            + ` (sim clock advanced ${td.simDt}s over those frames — a 0.00s here means the WORLD IS FROZEN, i.e. an earlier`
            + ` leg left ctx.flags.paused set, not that the streamer is slow)`);
          if (td.underAfter !== 0) fails.push(`warren teardown: ${td.underAfter} underground scrap pickups survived their cave's eviction — dangling interaction targets`);
          if (td.poolInScene === false) fails.push('warren teardown: the SHARED scrap InstancedMesh left the scene — a double despawn removed every scrap pickup in the world');
          console.log(`[cave-kinds] warren teardown: took=${td.took ? 1 : 0} evicted=${td.evicted ? 1 : 0} in ${td.frames}f (sim ${td.simDt}s), underground scrap ${arrive.scrapPickups}\u2192${td.underAfter}, world scrap ${td.totalScrapBefore}\u2192${td.totalScrapAfter}, shared pool in scene=${td.poolInScene}`);
        }
      }

      const secs = ((Date.now() - t0) / 1000).toFixed(0);
      details.push(
        `${kind.padEnd(8)} @(${site.x.toFixed(0)},${site.z.toFixed(0)}) seed=${site.seed} digest=${arrive.digest} ` +
        `chambers=${arrive.chambers} depth=${arrive.eggDepth}m eggRx=${arrive.eggRx} squeeze=${arrive.squeezes}/${arrive.edges} corrH=${arrive.corridorH}m ` +
        `fungi=${arrive.fungiClusters} shelves=${arrive.fungiWallShelves}(hidden ${arrive.fungiWallHidden}) pools=${arrive.pools} rubble=${arrive.rubbleHeaps} scrap=${arrive.scrapAnchors}/${arrive.scrapPickups} ` +
        `extent=${arrive.extent}m/${arrive.minSpacing}m tris=${arrive.tris}/${arrive.colliderTris} meshes=${arrive.meshes} ` +
        `clear=${arrive.minClear}m@s${arrive.minClearAt ? arrive.minClearAt.s : '?'}(model ${arrive.modelClear}) ` +
        `tor=${arrive.torMs}ms fin=${arrive.finMs}ms slice=${arrive.sliceMs}ms atomic=${arrive.atomicMs}ms(${arrive.atomicStage}) frame=${arrive.worstFrameMs}ms | ` +
        (w ? `MARCH reached=${w.reached}/${w.chambers} ascent=${w.exited ? 'OUT' : 'FAIL'} strands=${(w.strands || []).length} slope=${w.maxSlope}° head=${w.minHeadroom} chamHead=${w.chamMinHead} cover=${w.minCover} fails=${w.fails.length} | ` : 'MARCH skipped | ') +
        (v.fatal ? `VOID FATAL ${v.fatal}` : `VOID points=${v.points} rays=${v.totalRays} escapes=${v.escapes} excused=${v.excused}`) +
        ` | ${secs}s`,
      );
    }

    // ── C. CROSS-KIND DISTINCTNESS. Each kind marching green proves nothing about whether the
    //      kinds are DIFFERENT PLACES — a table that collapsed to canonical would look perfect
    //      above. These are the inequalities the table claims, asserted against measured caves. ──
    const have = (k) => per[k] && per[k].ok;
    if (have('warren') && have('fungal')) {
      if (!(per.warren.chambers > per.fungal.chambers)) fails.push(`distinctness: warren has ${per.warren.chambers} chambers, fungal has ${per.fungal.chambers} — the warren must be the many-small-rooms kind`);
      if (!(per.fungal.eggRx > per.warren.eggRx + 2)) fails.push(`distinctness: fungal egg rx ${per.fungal.eggRx} vs warren ${per.warren.eggRx} — the vault is not vaulted`);
    }
    if (have('shaft') && have('flooded')) {
      if (!(per.shaft.eggDepth > per.flooded.eggDepth + 4)) fails.push(`distinctness: shaft depth ${per.shaft.eggDepth}m vs flooded ${per.flooded.eggDepth}m — the shaft does not go deeper`);
    }
    if (have('flooded') && have('warren')) {
      if (!(per.flooded.pools > per.warren.pools)) fails.push(`distinctness: flooded has ${per.flooded.pools} pools, warren has ${per.warren.pools}`);
    }
    if (have('fungal') && have('shaft')) {
      if (!(per.fungal.fungiClusters > per.shaft.fungiClusters)) fails.push(`distinctness: fungal has ${per.fungal.fungiClusters} fungi clusters, shaft has ${per.shaft.fungiClusters}`);
    }
    // Vacuous-pass guards on the run itself.
    if (built < KINDS.length) fails.push(`only ${built}/${KINDS.length} kinds built`);
    if (DO_MARCH && marched === 0) fails.push('no kind was marched — the gate would have passed by measuring nothing');
    if (DO_VOID && voided === 0) fails.push('no kind was void-sampled — the gate would have passed by measuring nothing');
    if (lightChecked < KINDS.length) fails.push(`only ${lightChecked}/${KINDS.length} kinds ran the light teeth (day-invariance + sky occlusion) — the rest passed by measuring nothing`);
    if (!DO_VOID) console.log('[cave-kinds] ⚠ --void=0: the watertightness sweep DID NOT RUN. This run is an iteration shot, not a gate result.');

    const pass = fails.length === 0;
    console.log(`CAVE-KINDS pass=${pass ? 1 : 0} seed=${picked.seed} kinds=${KINDS.length} built=${built} marched=${marched} voided=${voided} lit=${lightChecked} sites=${dist.sites} strands=${strandTotal} escapes=${escTotal} fails=${fails.length}`);
    for (const d of details) console.log(`[cave-kinds] ${d}`);
    if (fails.length) for (const f of fails) console.log(`[cave-kinds] FAIL ${f}`);
    if (!pass) throw new Error('cave-kinds GATE FAILED');
  },

  // ── crevice-profile (DEEPER cycle 9) — THE ENTRANCE CLEARANCE PROFILE ────────────────────────
  //
  //   WHY IT EXISTS. `cave-walk` reports the crevice descent as a pass/fail per LEG: "could not walk
  //   leg slot2". That is the right gate and a useless diagnostic — it says a capsule stopped, not
  //   what stopped it, and the two candidate causes (the slot's ceiling clamped down onto the walker
  //   vs. its walls closing in) call for opposite fixes. This scenario measures the actual clear
  //   envelope of the descent with physics rays against the SHIPPED colliders: at 0.3m of arc length
  //   along the real station polyline, a castDown for the floor, an up-ray for clear HEIGHT, and
  //   perpendicular pairs at ankle (0.35m) and head (1.65m) for clear WIDTH.
  //
  //   The capsule that has to fit is stated in the output, not assumed: 2·radius wide and
  //   2·(halfHeight+radius) tall, read off `ctx.player.body`.
  //
  //   Run: npm run rig -- --scenario=crevice-profile --seed=1337 --siteOffset=2 --port=52xx
  //        (--siteOffset picks the Nth-nearest cave site — the same ordering `cave-kinds` uses, so a
  //         site that failed there can be profiled here by the same index.)
  'crevice-profile': async (page) => {
    const OFF = Number(argv.siteOffset || argv.siteoffset || 0);
    // `--siteX=675 --siteZ=1113` targets the site NEAREST those coordinates instead of the Nth
    // nearest to origin. A site index moves the moment a placement rule changes; a coordinate does
    // not, so a defect measured once can be re-measured after the fix on the SAME ground.
    const AT = argv.siteX !== undefined || argv.sitex !== undefined
      ? { x: Number(argv.siteX ?? argv.sitex), z: Number(argv.siteZ ?? argv.sitez) } : null;
    const r = await page.evaluate(async ([O, AT]) => {
      const g = window.__game; const ctx = g.ctx; const RAPIER = g.RAPIER;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      ctx.sandWorms.list.length = 0; ctx.vultures.list.length = 0; ctx.weather.intensity = 0;
      const all = g.caveSites(0, 0, 9000).map((s) => ({ ...s, d: Math.hypot(s.x, s.z) })).sort((a, b) => a.d - b.d);
      const S = AT
        ? all.reduce((m, s) => (Math.hypot(s.x - AT.x, s.z - AT.z) < Math.hypot(m.x - AT.x, m.z - AT.z) ? s : m), all[0])
        : all[O];
      if (!S) return { fatal: `no cave site at offset ${O}` };
      if (AT && Math.hypot(S.x - AT.x, S.z - AT.z) > 60) return { fatal: `nearest site to (${AT.x},${AT.z}) is (${S.x.toFixed(0)},${S.z.toFixed(0)}), ${Math.hypot(S.x - AT.x, S.z - AT.z).toFixed(0)}m away — that ground carries no cave (a placement rule rejected it)` };
      ctx.caveStream.setSiteSource(null);
      const px = S.x - 120, pz = S.z;
      const body = ctx.player.body.body;
      body.setTranslation({ x: px, y: ctx.terrain.heightAt(px, pz) + 2, z: pz }, true);
      for (let f = 0; f < 2000; f++) { await raf(); if (f > 90 && ctx.terrain.isTileLoadedAt(S.x, S.z)) break; }
      const key = 'creviceprofile';
      if (!ctx.caveStream.requestSite({ key, x: S.x, z: S.z, seed: S.seed, kind: 'canonical' })) return { fatal: 'requestSite refused the descriptor' };
      let res = null;
      for (let f = 0; f < 9000; f++) { await raf(); res = ctx.caveStream.residents().find((q) => q.key === key); if (res) break; }
      if (!res) return { fatal: 'the streamer never built the site' };
      if (!res.entrance) return { fatal: 'the resident carries no crevice entrance' };
      const line = res.entrance.line, ep = res.entrance.probe;
      // Park the capsule 400m up: it must not be what a ray hits, and the filter below excludes it
      // anyway — belt and braces, because a self-hit reads as "zero clearance" and would invent a
      // defect that is not there.
      body.setTranslation({ x: S.x, y: ctx.terrain.heightAt(S.x, S.z) + 400, z: S.z }, true);
      await raf();
      const RAD = ctx.player.body.radius, HH = ctx.player.body.halfHeight;
      const toi = (ox, oy, oz, dx, dy, dz, maxT) => {
        const h = ctx.physics.world.castRay(new RAPIER.Ray({ x: ox, y: oy, z: oz }, { x: dx, y: dy, z: dz }),
          maxT, true, undefined, undefined, undefined, body);
        return h ? h.timeOfImpact : Infinity;
      };
      const st = line.stations;
      const rows = [];
      let acc = 0;
      for (let i = 1; i < st.length; i++) {
        const a = st[i - 1], b = st[i];
        const dx = b.x - a.x, dz = b.z - a.z, D = Math.hypot(dx, dz) || 1;
        const ux = dx / D, uz = dz / D, nx = -uz, nz = ux;
        for (let t = 0; t < D - 1e-6; t += 0.3) {
          const x = a.x + ux * t, z = a.z + uz * t;
          const guess = a.floorY + (b.floorY - a.floorY) * (t / D);
          // ⚠ THE RAY ORIGIN IS THE WHOLE MEASUREMENT. The descent is ROOFED past the sky run, and
          // the terrain sheet sits a couple of metres over that roof. A castDown from `guess + 3`
          // therefore starts ABOVE the slot's own ceiling and reports the SHEET as the floor —
          // Δ ≈ +2.5m, walls at infinity, a bogus "0.9m clear height". The first cut of this probe
          // did exactly that and it read as a rock plug in the descent at BOTH a failing and a
          // passing site, which is how it was caught. Start INSIDE the slot (the clear height is
          // ~2.55m, so +1.2 is under the ceiling and over the floor) and only fall back upward if
          // that misses, flagging the row when it does.
          const s = +(acc + t).toFixed(2);
          let hit = g.castDown(x, z, guess + 1.2, true), from = 1.2;
          if (!hit) { hit = g.castDown(x, z, guess + 0.4, true); from = 0.4; }
          if (!hit) { hit = g.castDown(x, z, guess + 3.0, true); from = 3.0; }
          if (!hit) { rows.push({ s, x: +x.toFixed(1), z: +z.toFixed(1), gap: 1 }); continue; }
          const fy = hit.hitY;
          const up = toi(x, fy + 0.12, z, 0, 1, 0, 14);
          const wl0 = toi(x, fy + 0.35, z, nx, 0, nz, 6), wr0 = toi(x, fy + 0.35, z, -nx, 0, -nz, 6);
          const wl1 = toi(x, fy + 1.65, z, nx, 0, nz, 6), wr1 = toi(x, fy + 1.65, z, -nx, 0, -nz, 6);
          rows.push({
            s, x: +x.toFixed(1), z: +z.toFixed(1), from,
            fy: +fy.toFixed(2), dFloor: +(fy - guess).toFixed(2),
            h: +Math.min(14, up + 0.12).toFixed(2),
            wFoot: +Math.min(12, wl0 + wr0).toFixed(2),
            wHead: +Math.min(12, wl1 + wr1).toFixed(2),
          });
        }
        acc += D;
      }
      // THE MODEL, ON THE SAME GROUND. `creviceClearProfile` is what the placement rule consults, and
      // a placement rule built on a model nobody checks is a gate that measures the wrong thing. Its
      // prediction is printed next to every ray sample, and its worst value next to the ray's worst.
      const model = window.__caveClear ? window.__caveClear({ x: S.x, z: S.z }, S.seed, { rows: true, step: 0.25 }) : null;
      const modelAt = (s) => {
        if (!model) return null;
        let best = null;
        for (const q of model.rows) if (!best || Math.abs(q.s - s) < Math.abs(best.s - s)) best = q;
        return best;
      };
      for (const q of rows) if (!q.gap) { const m = modelAt(q.s); if (m) q.mh = m.h; }
      const solid = rows.filter((q) => !q.gap);
      const minBy = (f) => solid.reduce((m, q) => (f(q) < f(m) ? q : m), solid[0]);
      return {
        model: model ? { minH: +model.minH.toFixed(2), atS: +model.atS.toFixed(2), atX: +model.atX.toFixed(1), atZ: +model.atZ.toFixed(1) } : null,
        site: { x: +S.x.toFixed(0), z: +S.z.toFixed(0), seed: S.seed, kind: S.kind, d: +S.d.toFixed(0) },
        gy: +ep.gy.toFixed(2), slope: ep.descentAngleDeg, mouthW: ep.mouthClearW, pinchW: ep.pinchClearW,
        capW: +(RAD * 2).toFixed(2), capH: +((HH + RAD) * 2).toFixed(2),
        stations: st.map((q) => ({ x: +q.x.toFixed(1), z: +q.z.toFixed(1), y: +q.floorY.toFixed(2), hw: +q.halfW.toFixed(2) })),
        gaps: rows.filter((q) => q.gap).length,
        minH: minBy((q) => q.h), minWFoot: minBy((q) => q.wFoot), minWHead: minBy((q) => q.wHead),
        rows,
      };
    }, [OFF, AT]);
    if (r.fatal) { console.log(`CREVICE-PROFILE FATAL ${r.fatal}`); throw new Error('crevice-profile FAILED'); }
    console.log(`CREVICE-PROFILE site=(${r.site.x},${r.site.z}) d=${r.site.d}m seed=${r.site.seed} gy=${r.gy} slope=${r.slope}° mouthW=${r.mouthW} pinchW=${r.pinchW} capsule=${r.capW}m wide × ${r.capH}m tall gaps=${r.gaps}`);
    console.log(`[crevice-profile] MIN clearHeight ${r.minH.h}m @s=${r.minH.s} (${r.minH.x},${r.minH.z}) | MIN width@foot ${r.minWFoot.wFoot}m @s=${r.minWFoot.s} | MIN width@head ${r.minWHead.wHead}m @s=${r.minWHead.s} (${r.minWHead.x},${r.minWHead.z})`);
    if (r.model) console.log(`[crevice-profile] MODEL minH ${r.model.minH}m @s=${r.model.atS} (${r.model.atX},${r.model.atZ}) — vs RAY ${r.minH.h}m @s=${r.minH.s}; model−ray = ${(r.model.minH - r.minH.h).toFixed(2)}m`);
    console.log(`[crevice-profile] stations=${JSON.stringify(r.stations)}`);
    for (const q of r.rows) {
      if (q.gap) { console.log(`[crevice-profile] s=${String(q.s).padStart(6)} (${q.x},${q.z}) *** NO FLOOR ***`); continue; }
      const flag = (q.h < r.capH + 0.2 ? ' ⚠LOW-ROOF' : '') + (q.wHead < r.capW + 0.2 ? ' ⚠NARROW-HEAD' : '') + (q.wFoot < r.capW + 0.2 ? ' ⚠NARROW-FOOT' : '');
      console.log(`[crevice-profile] s=${String(q.s).padStart(6)} (${String(q.x).padStart(7)},${String(q.z).padStart(7)}) floor=${String(q.fy).padStart(7)} Δ=${String(q.dFloor).padStart(6)} clearH=${String(q.h).padStart(6)} model=${String(q.mh ?? '-').padStart(6)} wFoot=${String(q.wFoot).padStart(6)} wHead=${String(q.wHead).padStart(6)} from+${q.from}${flag}`);
    }
  },

  // ── crevice-sweep (DEEPER cycle 9) — THE HEADROOM MODEL OVER HUNDREDS OF REAL SITES ──────────
  //
  //   `crevice-profile` measures ONE site with physics rays and takes ~3 minutes (it streams a whole
  //   cave in). That is the right instrument for ground truth and the wrong one for choosing between
  //   levers: "does extending the carved hole fix this, and what does it cost in density?" is a
  //   question about the WHOLE SITE POPULATION. This sweep answers it from the pure model
  //   (`creviceClearProfile`) with no builds at all — hundreds of sites in seconds — and prints the
  //   rejection rate each candidate lever would cost.
  //
  //   Run: npm run rig -- --scenario=crevice-sweep --seed=1337 --n=250 --port=52xx
  'crevice-sweep': async (page) => {
    const N = Number(argv.n || 250);
    const r = await page.evaluate(async (n) => {
      const g = window.__game;
      const clear = window.__caveClear, fits = window.__caveHoleFits;
      if (!clear) return { fatal: '__caveClear is not exposed — the cave feature is off' };
      const all = g.caveSites(0, 0, 9000).map((s) => ({ ...s, d: Math.hypot(s.x, s.z) })).sort((a, b) => a.d - b.d).slice(0, n);
      if (!all.length) return { fatal: 'no cave sites' };
      const VARIANTS = [
        { name: 'shipped        ', o: {} },
        { name: 'holeX=4        ', o: { cellsX: 4 } },
        { name: 'holeX=5        ', o: { cellsX: 5 } },
        { name: 'roofUnder=0.6  ', o: { roofUnder: 0.6 } },
        { name: 'roofUnder=0.45 ', o: { roofUnder: 0.45 } },
        { name: 'holeX=4+rU=0.6 ', o: { cellsX: 4, roofUnder: 0.6 } },
        { name: 'holeX=5+rU=0.6 ', o: { cellsX: 5, roofUnder: 0.6 } },
      ];
      const BOUNDS = [1.9, 2.0, 2.1, 2.2, 2.3];
      const out = { count: all.length, variants: [], worst: [] };
      const perSite = [];
      for (const v of VARIANTS) {
        const hs = [];
        for (const s of all) hs.push(clear({ x: s.x, z: s.z }, s.seed, v.o).minH);
        if (v.name.startsWith('shipped')) for (let i = 0; i < all.length; i++) perSite.push({ s: all[i], h: hs[i] });
        const sorted = [...hs].sort((a, b) => a - b);
        const below = {};
        for (const b of BOUNDS) below[b] = hs.filter((h) => h < b).length;
        out.variants.push({
          name: v.name, below,
          min: +sorted[0].toFixed(2),
          p05: +sorted[Math.floor(sorted.length * 0.05)].toFixed(2),
          p50: +sorted[Math.floor(sorted.length * 0.50)].toFixed(2),
        });
      }
      // Tile-fit cost of a longer hole, measured over THIS list (every site here already passes the
      // 3-cell rule, so a survivor that fails the 4-cell rule is exactly the density the lever costs).
      out.fitLoss = {};
      if (fits) for (const cx of [4, 5]) out.fitLoss[cx] = all.filter((s) => !fits({ x: s.x, z: s.z }, cx)).length;
      perSite.sort((a, b) => a.h - b.h);
      out.worst = perSite.slice(0, 12).map((q) => ({ x: +q.s.x.toFixed(0), z: +q.s.z.toFixed(0), d: +q.s.d.toFixed(0), kind: q.s.kind, seed: q.s.seed, h: +q.h.toFixed(2) }));
      return out;
    }, N);
    if (r.fatal) { console.log(`CREVICE-SWEEP FATAL ${r.fatal}`); throw new Error('crevice-sweep FAILED'); }
    console.log(`CREVICE-SWEEP sites=${r.count}`);
    for (const v of r.variants) {
      const bel = Object.entries(v.below).map(([b, n]) => `<${b}:${n}(${((n / r.count) * 100).toFixed(1)}%)`).join(' ');
      console.log(`[crevice-sweep] ${v.name} min=${v.min} p05=${v.p05} p50=${v.p50} | ${bel}`);
    }
    for (const [cx, n] of Object.entries(r.fitLoss || {})) console.log(`[crevice-sweep] tile-fit loss at holeX=${cx}: ${n}/${r.count} (${((n / r.count) * 100).toFixed(1)}%) of currently-valid sites`);
    for (const w of r.worst) console.log(`[crevice-sweep] WORST (${String(w.x).padStart(6)},${String(w.z).padStart(6)}) d=${w.d}m kind=${w.kind} seed=${w.seed} modelled minH=${w.h}`);
  },

  'chunk-perf': async (page) => {
    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      const fails = [];
      ctx.sandWorms.list.length = 0;
      ctx.vultures.list.length = 0;
      ctx.three.renderer.setSize(320, 240, false);
      // Settle at home, then reset the perf maxima so the walk is the sample.
      const tp = async (x, z, settle) => {
        ctx.player.body.body.setTranslation({ x, y: ctx.terrain.heightAt(x, z) + 1.6, z }, true);
        await frames(settle);
      };
      await tp(56, 56, 60);
      const baseBodies = ctx.physics.world.bodies.len();
      const baseDraw = ctx.three.renderer.info.render.calls;
      g.resetChunkPerf();
      // Walk out through the landmark-bearing far field and back — every
      // 140m hop queues tiles + chunks (a WORSE generation load than real
      // walking speed).
      let maxDraw = 0, maxBodies = 0;
      const hop = async (x, z) => {
        await tp(x, z, 12);
        const d = ctx.three.renderer.info.render.calls;
        const b = ctx.physics.world.bodies.len();
        if (d > maxDraw) maxDraw = d;
        if (b > maxBodies) maxBodies = b;
      };
      const cur = () => ctx.player.body.body.translation();
      const walkTo = async (txp, tzp) => {
        const c0 = cur();
        const steps = Math.max(1, Math.ceil(Math.hypot(txp - c0.x, tzp - c0.z) / 140));
        for (let i = 1; i <= steps; i++) {
          await hop(c0.x + (txp - c0.x) * (i / steps), c0.z + (tzp - c0.z) * (i / steps));
        }
        await frames(30);
      };
      await walkTo(2500, 56);
      // Route through the nearest region-rolled LANDMARK so its (deferred,
      // one-piece-per-frame) render cost is in the sample.
      {
        // Prefer a wreck_knot — its DEFERRED per-frame piece renders are
        // the path this gate exists to sample (an unexercised deferred
        // path shipping is the cycle-3 fauna lesson); fall back to any
        // landmark. Wide scan: knot kinds are a 50% sub-roll of a
        // 0.3/region roll, so ~40 regions makes one near-certain.
        let lm = null, knot = null;
        for (let cx = 12; cx <= 110; cx++) {
          for (let cz = -48; cz <= 48; cz++) {
            const d = g.chunkDescribe(cx, cz);
            if (!d.landmark.present) continue;
            if (!lm) lm = d.landmark;
            if (!knot && d.landmark.kind === 'wreck_knot') { knot = d.landmark; break; }
          }
          if (knot) break;
        }
        const target = knot || lm;
        if (target) { await walkTo(target.x + 40, target.z + 40); await frames(90); }
        fails.__route = target ? `${target.kind}@${target.x.toFixed(0)},${target.z.toFixed(0)}` : 'none';
      }
      await walkTo(2500, 2500);
      await walkTo(56, 56);
      await frames(90);
      const perf = g.chunkPerf();
      const endBodies = ctx.physics.world.bodies.len();
      // ── Asserts ──
      // Slicing must be the NORM: plenty of slice steps ran, and sync
      // (anchor-safety) bakes stay RARE. The teleport-hop walk moves
      // ~100× faster than real play, so the ring legitimately lags on
      // diagonal legs and the anchor-tile safety bake may fire a few
      // times — that's fall-through protection working, not a
      // regression. A real regression (ring fills reverting to sync)
      // does ~30+ sync bakes on this walk and near-zero slice steps.
      if (perf.terrain.sliceSteps < 100) {
        fails.push(`only ${perf.terrain.sliceSteps} slice steps — sliced builds are not running (reverted to sync?)`);
      }
      if (perf.terrain.syncBuilds > 4) {
        fails.push(`${perf.terrain.syncBuilds} SYNCHRONOUS tile bakes (maxSyncMs=${perf.terrain.maxSyncMs.toFixed(1)}) — far above the teleport-pace safety allowance; slicing regressed`);
      }
      if (perf.terrain.maxSyncMs > 250) fails.push(`sync anchor bake ${perf.terrain.maxSyncMs.toFixed(1)}ms > 250ms tripwire`);
      if (perf.terrain.maxSliceMs > 60) fails.push(`terrain slice step ${perf.terrain.maxSliceMs.toFixed(1)}ms > 60ms tripwire (stages: ${JSON.stringify(perf.terrain.maxStageMs)})`);
      if (perf.chunks.maxLoadMs > 120) fails.push(`chunk load ${perf.chunks.maxLoadMs.toFixed(1)}ms > 120ms tripwire (poi=${perf.chunks.maxPoiLoadMs.toFixed(1)})`);
      if (perf.chunks.maxLandmarkLoadMs > 120) fails.push(`landmark piece ${perf.chunks.maxLandmarkLoadMs.toFixed(1)}ms > 120ms tripwire (deferred staging regressed)`);
      if (maxDraw > baseDraw + 500) fails.push(`draw calls unbounded: max ${maxDraw} vs base ${baseDraw}`);
      if (maxBodies > baseBodies + 300) fails.push(`bodies unbounded: max ${maxBodies} vs base ${baseBodies}`);
      if (Math.abs(endBodies - baseBodies) > 3) fails.push(`bodies did not return to baseline: ${baseBodies} → ${endBodies}`);
      return {
        fails,
        route: fails.__route,
        sliceSteps: perf.terrain.sliceSteps,
        maxSliceMs: +perf.terrain.maxSliceMs.toFixed(1),
        stages: {
          fill: +perf.terrain.maxStageMs.fill.toFixed(1),
          geometry: +perf.terrain.maxStageMs.geometry.toFixed(1),
          finalize: +perf.terrain.maxStageMs.finalize.toFixed(1),
        },
        loads: perf.chunks.loads,
        maxLoadMs: +perf.chunks.maxLoadMs.toFixed(1),
        maxLandmarkLoadMs: +perf.chunks.maxLandmarkLoadMs.toFixed(1),
        baseDraw, maxDraw, baseBodies, maxBodies, endBodies,
      };
    });
    const pass = r.fails.length === 0;
    console.log(`CHUNK-PERF pass=${pass ? 1 : 0} slice=${r.maxSliceMs}ms(fill=${r.stages.fill}/geo=${r.stages.geometry}/fin=${r.stages.finalize}) steps=${r.sliceSteps} load=${r.maxLoadMs}ms lm=${r.maxLandmarkLoadMs}ms draw=${r.baseDraw}->${r.maxDraw} bodies=${r.baseBodies}->${r.maxBodies}->${r.endBodies} fails=${r.fails.length}`);
    console.log(`[chunk-perf] route=${r.route} ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r.fails)}`);

    // ── DEEPER cycle 5 (walk-test D-4) — THE CAVE BUILD BUDGET + THE RESIDENT CAP.
    //    Caves are not placed by the streamer yet (that is cycle 8); this leg drives the SAME
    //    machinery cycle 8 will consume — `__game.requestCave(x, z, seed)` queues a real cave body
    //    at a real far-field site and the scheduler builds it in CAVE_BUILD_SLICE_MS stage-steps.
    //
    //    THE TRIPWIRES, because "green because nothing built" is this project's recurring failure:
    //      · `builds` must equal the number requested and every new resident must carry triangles —
    //        a cave that silently didn't build cannot pass.
    //      · `steps` must be large — a build that reverted to ONE synchronous call would report 1
    //        step and a ~1200ms max, so slicing cannot be silently lost.
    //      · the divisible slice budget and the ATOMIC finalize (Rapier trimesh bake, unsliceable)
    //        are asserted SEPARATELY so neither launders the other.
    //      · the observed worst rAF gap is measured independently of the counters — a cost the
    //        counters miss still shows up here.
    //      · the cap must actually evict, and the cave the player is STANDING IN must survive it.
    const cv = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const fails = [];
      if (!ctx.caveStream) { fails.push('ctx.caveStream is null — the cave scheduler did not boot'); return { fails, skipped: true }; }
      const pre = g.cavePerf();
      if (!pre.preload) fails.push('no __cavePreloadMs record — the ORIGIN cave was not preloaded at boot');
      const originRes = pre.residents.find((x) => x.key === 'origin');
      if (!originRes) fails.push('the origin cave is not a resident — the boot preload was not adopted');
      else if (!originRes.pinned) fails.push('the origin cave is NOT pinned — the cap could evict the egg cave');
      else if (!(originRes.tris > 0)) fails.push('the origin cave resident carries 0 triangles');

      const CAP = 3;                                    // Tuning.CAVE_RESIDENT_MAX
      const N = CAP + 1;                                // one more than the cap, so eviction MUST fire
      g.resetCavePerf();
      const sites = [];
      for (let i = 0; i < N; i++) sites.push({ x: 4000 + i * 700, z: 4000 });
      for (const st of sites) g.requestCave(st.x, st.z, 1337 + st.x);

      // Drive frames until every requested cave is built (bounded), sampling the observed frame gap.
      let worstFrameMs = 0, framesRun = 0;
      let last = performance.now();
      for (let f = 0; f < 6000; f++) {
        await raf();
        const now = performance.now();
        const gap = now - last; last = now;
        if (f > 2 && gap > worstFrameMs) worstFrameMs = gap;
        framesRun++;
        const st = g.cavePerf();
        if (st.stream.builds >= N && st.queued === 0 && !st.pending) break;
      }
      const mid = g.cavePerf();
      if (mid.stream.builds !== N) fails.push(`only ${mid.stream.builds}/${N} caves BUILT in ${framesRun} frames — the sliced build never completed (tripwire)`);
      if (mid.stream.steps < 100) fails.push(`only ${mid.stream.steps} cave slice steps for ${N} caves — the build is not sliced (reverted to sync?)`);
      if (mid.stream.maxSliceMs > 20) fails.push(`DIVISIBLE cave slice step ${mid.stream.maxSliceMs.toFixed(1)}ms > 20ms tripwire (budget is 8ms)`);
      if (mid.stream.maxAtomicMs > 170) fails.push(`INDIVISIBLE cave step ${mid.stream.maxAtomicMs.toFixed(1)}ms (${mid.stream.worstAtomicStage}) > 170ms tripwire`);
      if (worstFrameMs > 260) fails.push(`worst observed frame gap ${worstFrameMs.toFixed(1)}ms > 260ms during the cave builds`);
      // Every NEW resident must be a real cave (non-empty, collider == visual body, rule 9).
      for (const r of mid.residents) {
        if (r.key === 'origin') continue;
        if (!(r.tris > 0)) fails.push(`resident ${r.key} has 0 visual triangles`);
        if (!(r.colliderTris > 0)) fails.push(`resident ${r.key} has 0 COLLIDER triangles — nothing was baked`);
      }
      // The cap evicted: origin (pinned) + CAP-1 far caves would be over, so residents must equal CAP.
      if (mid.residents.length > CAP) fails.push(`${mid.residents.length} residents > cap ${CAP} — the resident cap did not evict`);
      if (mid.stream.evictions < 1) fails.push('no evictions ran despite exceeding the cap (tripwire)');
      if (!mid.residents.some((x) => x.key === 'origin')) fails.push('the PINNED origin cave was evicted — the pin does not hold');

      // ── NEVER EVICT THE OCCUPIED CAVE. Stand the player INSIDE a resident far cave, then request
      //    more caves so the cap fires every frame. That cave must still be resident afterwards.
      const far = ctx.caveStream.residents().filter((r) => !r.pinned);
      let occKey = null, occSurvived = true, occBlocked = 0;
      if (far.length) {
        const target = far[0];
        occKey = target.key;
        const c = target.center;
        for (let i = 0; i < 3; i++) g.requestCave(9000 + i * 700, 9000, 4242 + i);
        for (let f = 0; f < 6000; f++) {
          // Hold the capsule inside the occupied cave (gravity would otherwise drop it out of the box).
          ctx.player.body.body.setTranslation({ x: c.x, y: c.y, z: c.z }, true);
          ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
          await raf();
          const st = g.cavePerf();
          if (st.stream.builds >= N + 3 && st.queued === 0 && !st.pending) break;
        }
        const post = g.cavePerf();
        occBlocked = post.stream.occupiedEvictionsBlocked;
        occSurvived = post.residents.some((x) => x.key === occKey);
        if (!occSurvived) fails.push(`the OCCUPIED cave ${occKey} was evicted while the player stood in it — fall-through risk`);
        if (post.stream.evictions < 2) fails.push('the second eviction round never ran — the cap test is vacuous');
        if (occBlocked < 1) fails.push('occupiedEvictionsBlocked never incremented — the occupancy guard was never exercised (vacuous)');
        const occNow = ctx.caveStream.occupied(ctx.player.body.body.translation());
        if (!occNow || occNow.key !== occKey) fails.push(`occupancy test does not report the player inside ${occKey} (got ${occNow ? occNow.key : 'null'})`);
      } else {
        fails.push('no non-pinned resident to run the occupied-eviction test against');
      }
      // -- THE DIGEST CONTRACT. Slicing must change only WHEN work runs, never WHAT it computes.
      //    Rebuild the ORIGIN cave's exact junction + seed through the SLICED path and require a
      //    byte-identical caveDigest against the synchronously-preloaded original. This is the
      //    tripwire that makes "the digest moved" a bug report rather than a re-baseline.
      let cloneDigest = '-', originDigest = '-';
      {
        const org = ctx.caveStream.residents().find((x) => x.key === 'origin');
        if (org) {
          originDigest = org.cave.probe.digest;
          // Stand at the origin cave first: the clone lands on the SAME site, so the near-distance
          // guard keeps the cap from evicting it in the very frame it finalizes (it did, first run).
          ctx.player.body.body.setTranslation({ x: org.center.x, y: org.center.y, z: org.center.z }, true);
          ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
          ctx.caveStream.request('digest-clone', org.cave.probe.junction, org.cave.probe.seed);
          for (let f = 0; f < 6000; f++) {
            await raf();
            if (!ctx.caveStream.pending() && !ctx.caveStream.queued()) break;
          }
          const cl = ctx.caveStream.residents().find((x) => x.key === 'digest-clone');
          if (!cl) fails.push('the sliced digest-clone cave never built (tripwire)');
          else {
            cloneDigest = cl.cave.probe.digest;
            if (cloneDigest !== originDigest)
              fails.push(`SLICED build digest ${cloneDigest} != SYNC preload digest ${originDigest} — slicing altered the geometry`);
          }
        } else {
          fails.push('no origin resident to run the sliced-vs-sync digest check against');
        }
      }
      const end = g.cavePerf();
      return {
        fails, skipped: false, cloneDigest, originDigest,
        preload: pre.preload, originTris: originRes ? originRes.tris : 0,
        builds: end.stream.builds, steps: end.stream.steps,
        maxSliceMs: +end.stream.maxSliceMs.toFixed(1),
        maxAtomicMs: +end.stream.maxAtomicMs.toFixed(1),
        worstAtomicStage: end.stream.worstAtomicStage,
        maxStepMs: +end.stream.maxStepMs.toFixed(1),
        worstFrameMs: +worstFrameMs.toFixed(1),
        residents: end.residents.length, evictions: end.stream.evictions,
        refused: end.stream.evictionsRefused, occBlocked, occKey, occSurvived,
        framesRun,
      };
    });
    const cvPass = cv.fails.length === 0;
    console.log(`CAVE-BUILD pass=${cvPass ? 1 : 0} preload=${cv.preload ? cv.preload.total : -1}ms(ent=${cv.preload ? cv.preload.entrance : -1}/body=${cv.preload ? cv.preload.body : -1}) builds=${cv.builds} steps=${cv.steps} slice=${cv.maxSliceMs}ms atomic=${cv.maxAtomicMs}ms(${cv.worstAtomicStage}) frame=${cv.worstFrameMs}ms residents=${cv.residents} evict=${cv.evictions} occBlocked=${cv.occBlocked} occSurvived=${cv.occSurvived ? 1 : 0} fails=${cv.fails.length}`);
    console.log(`[cave-build] sync-digest=${cv.originDigest} sliced-digest=${cv.cloneDigest} ${cvPass ? 'PASS' : 'FAIL'} ${JSON.stringify(cv.fails)}`);

    if (!pass) throw new Error('chunk-perf GATE FAILED');
    if (!cvPass) throw new Error('cave-build GATE FAILED');
  },

  // Infinite Sands S1 — VISUAL sanity shots for the streamed world (the
  // appearance side of the S1 gate; systems work, placement-sanity bar).
  // Walks the player out past the old ±1200m world edge with markers on and
  // captures the PLAYER'S REAL EYE VIEW (per the visual-gate canon):
  //   fwd1500  — standing at +1500m looking INTO the unexplored field
  //   back1500 — same spot looking back toward the origin
  //   seam     — looking +X across the 800m terrain-tile boundary at x=1200
  //   marker   — close-up of a marker post (ground contact, not floating)
  // ── bone_field — the titan-graveyard biome POP check. Finds the nearest
  //    far-field bone_field zone, streams into it, and shoots the REAL player-
  //    eye reads: (1) the ground-colour CONTRAST at the biome edge (bleached
  //    bone vs tan desert in one frame), (2) an entry-distance vista over the
  //    strewn field, (3) a close half-buried bone read. The bar: a fresh
  //    viewer goes "whoa, a bone field" on sight.
  //    Run: node scripts/rig-shot.mjs --scenario=bone-field --port=5781
  'bone-field': async (page) => {
    await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0;
      ctx.weather.intensity = 0; g.setTime(0.5);          // noon — high neutral sun so the pale ground + bleached bone read true
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1180, 780, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1180 / 780; cam.updateProjectionMatrix(); }
    });
    // Find the nearest bone_field core, then REFINE to the true field centroid
    // (a coarse grid cell can sit near the rim → cameras placed off it land on
    // dune; the probe caught exactly that). The centroid of all bf>0.5 cells in
    // a local fine sweep is the plateau centre — cameras offset from it stay
    // solidly inside the field.
    const center = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      let coarse = null, bestD = Infinity;
      for (let x = -13000; x <= 13000; x += 200) {
        for (let z = -13000; z <= 13000; z += 200) {
          if (x * x + z * z < 2600 * 2600) continue;
          if (ctx.biomes.boneFieldAt(x, z) > 0.9) {
            const dd = x * x + z * z;
            if (dd < bestD) { bestD = dd; coarse = { x, z }; }
          }
        }
      }
      if (!coarse) return null;
      let sx = 0, sz = 0, w = 0;
      for (let dx = -200; dx <= 200; dx += 8) {
        for (let dz = -200; dz <= 200; dz += 8) {
          const bf = ctx.biomes.boneFieldAt(coarse.x + dx, coarse.z + dz);
          if (bf > 0.5) { sx += coarse.x + dx; sz += coarse.z + dz; w++; }
        }
      }
      return w ? { x: Math.round(sx / w), z: Math.round(sz / w) } : coarse;
    });
    if (!center) { console.log('[bone-field] no bone_field zone found in the 13km scan (seed-dependent)'); return; }
    console.log(`[bone-field] zone core at ${center.x.toFixed(0)},${center.z.toFixed(0)} (dist ${Math.hypot(center.x, center.z).toFixed(0)}m)`);
    // Stream the zone in: one teleport past the anchor margin, then wait for
    // the ring (incl. the bone scatter, built synchronously in loadChunk).
    await page.evaluate(async (c) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      ctx.player.body.body.setTranslation({ x: c.x, y: ctx.terrain.heightAt(c.x, c.z) + 1.6, z: c.z }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 150; f++) await raf();
    }, center);
    // Diagnostics: bone-scatter descriptor density + the biome-edge location.
    const diag = await page.evaluate((c) => {
      const g = window.__game; const ctx = g.ctx;
      const SIZE = 112;
      const cx0 = Math.floor(c.x / SIZE), cz0 = Math.floor(c.z / SIZE);
      let ribcages = 0, bits = 0, chunksWithBones = 0;
      let ribT = null, ribScale = 0;
      for (let dx = -2; dx <= 2; dx++) {
        for (let dz = -2; dz <= 2; dz++) {
          const d = g.chunkDescribe(cx0 + dx, cz0 + dz);
          if (d.bones.length) chunksWithBones++;
          for (const b of d.bones) {
            if (b.kind === 'ribcage') { ribcages++; if (b.scale > ribScale) { ribScale = b.scale; ribT = { x: b.x, z: b.z, scale: b.scale }; } }
            else bits++;
          }
        }
      }
      // Walk outward from core to find the bone/desert edge (boneFieldAt→0).
      let edge = null;
      for (let r = 20; r <= 260; r += 6) {
        const ex = c.x + r, ez = c.z;
        if (ctx.biomes.biomeAt(ex, ez) !== 'bone_field') { edge = { x: ex, z: ez }; break; }
      }
      // Ground truth: boneFieldAt + the nearest BAKED terrain vertex colour at
      // the core and at the entry-camera spot (is the pale overlay real, not fog?).
      const sampleVtx = (sx, sz) => {
        let best = null;
        for (const m of ctx.terrain.meshes) {
          const posA = m.geometry.getAttribute('position');
          const colA = m.geometry.getAttribute('color');
          if (!colA) continue;
          for (let i = 0; i < posA.count; i += 37) {
            const wx = posA.getX(i) + m.position.x;
            const wz = posA.getZ(i) + m.position.z;
            const dd = (wx - sx) ** 2 + (wz - sz) ** 2;
            if (!best || dd < best.dd) best = { dd, r: colA.getX(i), g: colA.getY(i), b: colA.getZ(i) };
          }
        }
        return best ? { rgb: [best.r.toFixed(2), best.g.toFixed(2), best.b.toFixed(2)], at: Math.sqrt(best.dd).toFixed(0) + 'm' } : null;
      };
      const core = { bf: +ctx.biomes.boneFieldAt(c.x, c.z).toFixed(2), vtx: sampleVtx(c.x, c.z) };
      const cam = { x: c.x - 38, z: c.z - 24 };
      const camPt = { bf: +ctx.biomes.boneFieldAt(cam.x, cam.z).toFixed(2), vtx: sampleVtx(cam.x, cam.z) };
      return { ribcages, bits, chunksWithBones, ribT, edge, core, camPt };
    }, center);
    console.log(`[bone-field] scatter (5x5 chunks): ${diag.ribcages} ribcages + ${diag.bits} bits across ${diag.chunksWithBones} chunks`);
    console.log(`[bone-field] core boneFieldAt=${diag.core.bf} vtxColor=${JSON.stringify(diag.core.vtx)}`);
    console.log(`[bone-field] entry-cam boneFieldAt=${diag.camPt.bf} vtxColor=${JSON.stringify(diag.camPt.vtx)}`);
    const aim = (fx, fz, tx, tz, lift = 1.7, tiltDown = 0) => `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera;
      ctx.flags.paused = true;
      cam.position.set(${fx}, ctx.terrain.heightAt(${fx}, ${fz}) + ${lift}, ${fz});
      cam.lookAt(${tx}, ctx.terrain.heightAt(${tx}, ${tz}) - ${tiltDown}, ${tz});
      cam.updateMatrixWorld(true);
    })()`;
    const shot = async (name, code) => {
      await page.evaluate(code);
      await page.waitForTimeout(400);
      await page.screenshot({ path: join(OUT, `scen-bone-field-${name}.png`), timeout: 60000 });
      console.log(`[bone-field] saved scen-bone-field-${name}.png`);
    };
    // (1) EDGE contrast — stand ~25m out on the tan desert, look across the
    //     boundary into the pale field (both grounds in one frame).
    if (diag.edge) {
      const ex = diag.edge.x + 25, ez = diag.edge.z;
      await shot('edge-contrast', aim(ex, ez, center.x, center.z, 1.8, 0.55));
    }
    // (2) ENTRY vista — INSIDE the field at eye level, looking across the
    //     strewn floor (bones in the near/mid ground, pale floor filling the
    //     lower frame). tiltDown drops the horizon so it's field, not sky.
    await shot('entry-vista', aim(center.x - 38, center.z - 24, center.x - 6, center.z - 2, 1.7, 0.45));
    // (3) A second entry angle for coverage.
    await shot('entry-vista2', aim(center.x + 34, center.z + 28, center.x + 4, center.z + 4, 1.7, 0.45));
    // (4) CLOSE read — the biggest nearby ribcage from ~10m, half-buried.
    if (diag.ribT) {
      console.log(`[bone-field] close ribcage at ${diag.ribT.x.toFixed(0)},${diag.ribT.z.toFixed(0)} scale ${diag.ribT.scale.toFixed(2)}`);
      const rx = diag.ribT.x, rz = diag.ribT.z;
      await shot('close-ribcage', aim(rx - 9, rz - 7, rx, rz, 1.6, 0.9));
    }
    // (5) A top-down-ish ground read to confirm the pale colour + mottle.
    await shot('ground', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera;
      ctx.flags.paused = true;
      const px = ${center.x}, pz = ${center.z};
      cam.position.set(px, ctx.terrain.heightAt(px, pz) + 8, pz);
      cam.lookAt(px + 6, ctx.terrain.heightAt(px + 6, pz), pz + 6);
      cam.updateMatrixWorld(true);
    })()`);
  },

  // ── bone-hero — the bone_field HERO "wow" gate. Finds the nearest bone_field
  //    region, streams to its ANCHOR (the field centre, where the colossal
  //    half-buried RIBCAGE spawns), and shoots the REAL player-eye reads:
  //    (1) ENTRY — a player-eye 3/4 approach: does it read as a colossal walk-under
  //        ribcage tunnel — spine ridge overhead, ribs to the ground, dwarfing us?
  //    (2) BROADSIDE — full length + the arched backbone ridge + the hanging ribs.
  //    (3) UNDER-TUNNEL — player-eye INSIDE, level down the centre aisle: arches
  //        must pass OVER the head, backbone running overhead.
  //    (4) UNDER-LOOKUP — player-eye pitched UP: the spine + ribs arch overhead.
  //    (5) END-ON — from the tunnel mouth looking in: the arch colonnade read.
  //    (6) LOWGRAZE — a very low angle across the rib bases (float / paper check).
  //    Run: node scripts/rig-shot.mjs --scenario=bone-hero --port=5782
  // ── bone-daynight — the NIGHT-GLOW gate. Same real bone_field player-eye reads
  //    as bone-hero, but shot at NIGHT (setTime 0.0) and DAY (setTime 0.5) from the
  //    IDENTICAL cameras, so the pair can be compared directly:
  //      NIGHT: the bones must sit DARK with the terrain/rocks — the sun-cancelling
  //             bone emissive must be off (it is self-illumination; a constant one
  //             made the graveyard glow in the dark).
  //      DAY:   unchanged — pale weathered bone popping against the warm sand.
  //    Also prints each registered bone material's live emissiveIntensity at both
  //    times (the mechanism check behind the pixels).
  //    Run: node scripts/rig-shot.mjs --scenario=bone-daynight --port=5793
  'bone-daynight': async (page) => {
    await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0;
      ctx.weather.intensity = 0;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1180, 780, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1180 / 780; cam.updateProjectionMatrix(); }
    });
    const anchor = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      let coarse = null, bestD = Infinity;
      for (let x = -13000; x <= 13000; x += 200) {
        for (let z = -13000; z <= 13000; z += 200) {
          if (x * x + z * z < 2600 * 2600) continue;
          if (ctx.biomes.boneFieldAt(x, z) > 0.9) {
            const dd = x * x + z * z;
            if (dd < bestD) { bestD = dd; coarse = { x, z }; }
          }
        }
      }
      if (!coarse) return null;
      const a = ctx.biomes.boneFieldAnchor(coarse.x, coarse.z);
      return a ? { x: a.x, z: a.z } : coarse;
    });
    if (!anchor) { console.log('[bone-daynight] no bone_field zone found'); return; }
    console.log(`[bone-daynight] field anchor at ${anchor.x.toFixed(0)},${anchor.z.toFixed(0)}`);
    await page.evaluate(async (a) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      ctx.player.body.body.setTranslation({ x: a.x, y: ctx.terrain.heightAt(a.x, a.z) + 1.6, z: a.z }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 200; f++) await raf();
    }, anchor);
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      let rc = null;
      ctx.three.scene.traverse((o) => { if (o.name === 'giantRibcage') rc = o; });
      if (!rc) return null;
      rc.updateMatrixWorld(true);
      const V = ctx.three.camera.position.constructor;
      const p0 = rc.localToWorld(new V(0, 0, 0));
      const p1 = rc.localToWorld(new V(1, 0, 0));
      const fwd = { x: p1.x - p0.x, y: 0, z: p1.z - p0.z };
      const fl = Math.hypot(fwd.x, fwd.z); fwd.x /= fl; fwd.z /= fl;
      return { cx: p0.x, cy: p0.y, cz: p0.z, fwd, length: rc.userData.length || 40, maxH: rc.userData.maxHeight || 15 };
    });
    if (!info) { console.log('[bone-daynight] ribcage group not found under the anchor'); return; }
    const side = { x: -info.fwd.z, z: info.fwd.x };
    const L = info.length, H = info.maxH, gy = info.cy;
    // The SAME cameras at both times — a night/day pair is only readable if nothing
    // else moved between the two frames.
    const CAMS = {
      // ENTRY — player-eye 3/4 approach across the open field (bones + dunes + rocks
      // all in frame: the "are the bones darker than their surroundings" comparison).
      entry: `(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
        const fx = ${info.cx} + ${side.x} * ${L * 0.72} - ${info.fwd.x} * ${L * 0.42};
        const fz = ${info.cz} + ${side.z} * ${L * 0.72} - ${info.fwd.z} * ${L * 0.42};
        cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 1.7, fz);
        cam.lookAt(${info.cx}, ${gy} + ${H * 0.42}, ${info.cz});
        cam.updateMatrixWorld(true);
      })()`,
      // BROADSIDE — the whole carcass + the surrounding field of scatter bits.
      broadside: `(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
        const fx = ${info.cx} + ${side.x} * ${L * 0.92};
        const fz = ${info.cz} + ${side.z} * ${L * 0.92};
        cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + ${H * 0.5}, fz);
        cam.lookAt(${info.cx}, ${gy} + ${H * 0.4}, ${info.cz});
        cam.updateMatrixWorld(true);
      })()`,
      // FLANKCLOSE — 16m player-eye off the flank: the close bone-surface read.
      flankclose: `(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
        const fx = ${info.cx} + ${side.x} * 16 - ${info.fwd.x} * ${L * 0.16};
        const fz = ${info.cz} + ${side.z} * 16 - ${info.fwd.z} * ${L * 0.16};
        cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 1.7, fz);
        cam.lookAt(${info.cx}, ${gy} + 3.2, ${info.cz});
        cam.updateMatrixWorld(true);
      })()`,
    };
    for (const [when, t] of [['night', 0.0], ['day', 0.5]]) {
      // Unpause + tick so updateLighting actually runs at the new time (it is inside
      // the pause gate — a paused setTime would leave the emissive on its old value).
      const probe = await page.evaluate(async (tt) => {
        const g = window.__game; const ctx = g.ctx;
        ctx.flags.paused = false;
        g.setTime(tt);
        const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
        for (let f = 0; f < 12; f++) await raf();
        const mats = new Set();
        ctx.three.scene.traverse((o) => {
          const m = o.material;
          if (m && m.userData && m.userData.boneEmissiveBase !== undefined) mats.add(m);
        });
        return {
          sunHeight: ctx.time.sunHeight,
          bones: [...mats].map((m) => ({
            base: m.userData.boneEmissiveBase,
            live: m.emissiveIntensity,
            hex: m.emissive.getHexString(),
          })),
        };
      }, t);
      console.log(`[bone-daynight] ${when}: sunHeight=${probe.sunHeight.toFixed(3)} ` +
        probe.bones.map((b) => `#${b.hex} base=${b.base} live=${b.live.toFixed(3)}`).join(' | '));
      for (const [name, code] of Object.entries(CAMS)) {
        await page.evaluate(code);
        await page.waitForTimeout(450);
        await page.screenshot({ path: join(OUT, `scen-bone-${when}-${name}.png`), timeout: 60000 });
        console.log(`[bone-daynight] saved scen-bone-${when}-${name}.png`);
      }
    }
    // ── ADOPTION + SHARED-MATERIAL-SURVIVAL probe. Two failure modes this catches:
    //    (a) the scatter ribcages keep a per-call material → it is NOT registered,
    //        so it glows at night (the bug, in a branch the shots may under-sample);
    //    (b) an adopted SHARED material gets disposed on chunk unload (the _treeMat
    //        rule) → the bones render black/broken after a revisit. Load→unload→
    //        reload the field and assert the shared material is still alive + still
    //        the one on the meshes. ──
    const adopt = await page.evaluate(async (a) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const scan = () => {
        let rcMeshes = 0, adopted = 0, unregistered = 0;
        const mats = new Set();
        ctx.three.scene.traverse((o) => {
          if (!o.isMesh) return;
          let w = o, streamed = false;
          while (w) { if (w.userData && w.userData.streamBone) { streamed = true; break; } w = w.parent; }
          if (!streamed) return;
          rcMeshes++;
          const m = o.material;
          if (m && m.userData && m.userData.boneEmissiveBase !== undefined) { adopted++; mats.add(m); }
          else unregistered++;
        });
        return { rcMeshes, adopted, unregistered, mats: [...mats] };
      };
      const before = scan();
      const matRefs = before.mats;
      // Walk far away → the field unloads; come back → it re-streams.
      ctx.player.body.body.setTranslation({ x: a.x + 4000, y: 200, z: a.z + 4000 }, true);
      for (let f = 0; f < 120; f++) await raf();
      ctx.player.body.body.setTranslation({ x: a.x, y: ctx.terrain.heightAt(a.x, a.z) + 1.6, z: a.z }, true);
      for (let f = 0; f < 200; f++) await raf();
      const after = scan();
      // A disposed material has had its program/uniform state torn down; three sets
      // `version`-tracked internals, but the robust signal is identity + still usable:
      // the re-streamed meshes must point at the SAME material objects.
      const sameRefs = after.mats.every((m) => matRefs.includes(m));
      return {
        before: { meshes: before.rcMeshes, adopted: before.adopted, unregistered: before.unregistered, mats: before.mats.length },
        after: { meshes: after.rcMeshes, adopted: after.adopted, unregistered: after.unregistered, mats: after.mats.length },
        sameRefs,
      };
    }, anchor);
    console.log(`[bone-daynight] adoption: before ${adopt.before.adopted}/${adopt.before.meshes} streamed bone meshes on registered materials ` +
      `(${adopt.before.mats} distinct, ${adopt.before.unregistered} unregistered)`);
    console.log(`[bone-daynight] after unload+reload: ${adopt.after.adopted}/${adopt.after.meshes} on registered materials ` +
      `(${adopt.after.mats} distinct, ${adopt.after.unregistered} unregistered) — shared refs reused: ${adopt.sameRefs}`);
    const ok = adopt.before.unregistered === 0 && adopt.after.unregistered === 0 && adopt.sameRefs
      && adopt.after.mats <= adopt.before.mats;
    console.log(`[bone-daynight] ${ok ? '[OK]' : '[FAIL]'} every streamed bone mesh is on a registered, sun-driven, reused shared material`);
  },

  'bone-hero': async (page) => {
    await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0;
      ctx.weather.intensity = 0; g.setTime(0.5);          // noon — pale bone reads true
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1180, 780, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1180 / 780; cam.updateProjectionMatrix(); }
    });
    // Find the nearest bone_field zone, then resolve its exact anchor (the field
    // centre — where the worm skeleton is hosted).
    const anchor = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      let coarse = null, bestD = Infinity;
      for (let x = -13000; x <= 13000; x += 200) {
        for (let z = -13000; z <= 13000; z += 200) {
          if (x * x + z * z < 2600 * 2600) continue;
          if (ctx.biomes.boneFieldAt(x, z) > 0.9) {
            const dd = x * x + z * z;
            if (dd < bestD) { bestD = dd; coarse = { x, z }; }
          }
        }
      }
      if (!coarse) return null;
      const a = ctx.biomes.boneFieldAnchor(coarse.x, coarse.z);
      return a ? { x: a.x, z: a.z } : coarse;
    });
    if (!anchor) { console.log('[bone-hero] no bone_field zone found in the 13km scan (seed-dependent)'); return; }
    console.log(`[bone-hero] field anchor at ${anchor.x.toFixed(0)},${anchor.z.toFixed(0)} (dist ${Math.hypot(anchor.x, anchor.z).toFixed(0)}m)`);
    // Stream the anchor chunk in (teleport onto it, let the ring settle).
    await page.evaluate(async (a) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      ctx.player.body.body.setTranslation({ x: a.x, y: ctx.terrain.heightAt(a.x, a.z) + 1.6, z: a.z }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 200; f++) await raf();
    }, anchor);
    // Locate the ribcage group + read its world frame (centre, +X spine axis,
    // skull world point, length, height) from userData — no global THREE needed.
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      let rc = null;
      ctx.three.scene.traverse((o) => { if (o.name === 'giantRibcage') rc = o; });
      if (!rc) return null;
      rc.updateMatrixWorld(true);
      const V = ctx.three.camera.position.constructor;
      const p0 = rc.localToWorld(new V(0, 0, 0));
      const p1 = rc.localToWorld(new V(1, 0, 0));
      const fwd = { x: p1.x - p0.x, y: 0, z: p1.z - p0.z };
      const fl = Math.hypot(fwd.x, fwd.z); fwd.x /= fl; fwd.z /= fl;
      const sk = rc.userData.skullLocal
        ? rc.localToWorld(rc.userData.skullLocal.clone()) : p0;
      // The SNAP the tight fracture read frames: pick the break whose stump face sits
      // highest above the sand near mid-span — the most legible one at eye height,
      // and the one whose fallen half is also in frame.
      let brk = null;
      const bl = rc.userData.breaks || [];
      let best = -Infinity;
      for (const b of bl) {
        const sw = rc.localToWorld(b.stump.clone());
        const fw = rc.localToWorld(b.fallen.clone());
        const h = sw.y - ctx.terrain.heightAt(sw.x, sw.z);
        // want it clearly above eye height but still readable from the ground
        const score = -Math.abs(h - 3.4) - Math.abs(sw.x - p0.x) * 0.02 - Math.abs(sw.z - p0.z) * 0.02;
        if (h > 1.8 && score > best) {
          best = score;
          // The axis is a DIRECTION — rotate it by the group's world matrix, don't
          // localToWorld it (that would add the translation).
          const ax = b.axis.clone().transformDirection(rc.matrixWorld);
          // The landmark is placed with a SCALE, so the local radius is not the world
          // radius — framing off the local one put the camera ~2× too far out and made
          // three rounds of fracture reads uselessly small. Measure the scale.
          const s0 = rc.localToWorld(new V(0, 0, 0));
          const s1 = rc.localToWorld(new V(1, 0, 0));
          const scale = Math.hypot(s1.x - s0.x, s1.y - s0.y, s1.z - s0.z);
          brk = {
            s: { x: sw.x, y: sw.y, z: sw.z }, f: { x: fw.x, y: fw.y, z: fw.z },
            a: { x: ax.x, y: ax.y, z: ax.z }, r: b.r * scale, scale,
          };
        }
      }
      return {
        cx: p0.x, cy: p0.y, cz: p0.z, fwd,
        skull: { x: sk.x, y: sk.y, z: sk.z },
        brk,
        length: rc.userData.length || 40,
        maxH: rc.userData.maxHeight || 15,
      };
    });
    if (!info) { console.log('[bone-hero] ribcage group not found under the anchor (descriptor/placement bug)'); return; }
    console.log(`[bone-hero] ribcage center ${info.cx.toFixed(0)},${info.cz.toFixed(0)} len ${info.length.toFixed(0)}m height ${info.maxH.toFixed(1)}m`);
    const shot = async (name, code) => {
      await page.evaluate(code);
      await page.waitForTimeout(450);
      await page.screenshot({ path: join(OUT, `scen-ribcage-${name}.png`), timeout: 60000 });
      console.log(`[bone-hero] saved scen-ribcage-${name}.png`);
    };
    const side = { x: -info.fwd.z, z: info.fwd.x };  // perpendicular to the spine axis
    const L = info.length, H = info.maxH;
    const gy = info.cy;
    // (1) ENTRY — a 3/4 approach at player eye height: the "does it read colossal
    //     + dwarfing" gate.
    await shot('entry', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const fx = ${info.cx} + ${side.x} * ${L * 0.72} - ${info.fwd.x} * ${L * 0.42};
      const fz = ${info.cz} + ${side.z} * ${L * 0.72} - ${info.fwd.z} * ${L * 0.42};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 1.7, fz);
      cam.lookAt(${info.cx}, ${gy} + ${H * 0.42}, ${info.cz});
      cam.updateMatrixWorld(true);
    })()`);
    // (2) BROADSIDE — perpendicular, lifted, framing the whole length + the ribs
    //     + the dorsal sail.
    await shot('broadside', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const fx = ${info.cx} + ${side.x} * ${L * 0.92};
      const fz = ${info.cz} + ${side.z} * ${L * 0.92};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + ${H * 0.5}, fz);
      cam.lookAt(${info.cx}, ${gy} + ${H * 0.4}, ${info.cz});
      cam.updateMatrixWorld(true);
    })()`);
    // (3) UNDER-TUNNEL — the KEY walk-under read: player-eye, standing INSIDE on
    //     the centre aisle (Z≈0) in the tall mid-section, looking level down the
    //     tunnel. The rib arches must clearly pass OVER the player's head + the
    //     backbone run overhead down the length.
    await shot('undertunnel', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const fx = ${info.cx} - ${info.fwd.x} * ${L * 0.3};
      const fz = ${info.cz} - ${info.fwd.z} * ${L * 0.3};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 1.7, fz);
      cam.lookAt(${info.cx} + ${info.fwd.x} * ${L * 0.32}, ${gy} + 3.0, ${info.cz} + ${info.fwd.z} * ${L * 0.32});
      cam.updateMatrixWorld(true);
    })()`);
    // (4) UNDER-LOOKUP — player-eye at the tunnel centre, pitched UP: confirms the
    //     spine ridge + ribs arch OVERHEAD (the "walk beneath the backbone" read).
    await shot('underlookup', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const fx = ${info.cx} - ${info.fwd.x} * ${L * 0.12};
      const fz = ${info.cz} - ${info.fwd.z} * ${L * 0.12};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 1.7, fz);
      cam.lookAt(${info.cx} + ${info.fwd.x} * ${L * 0.14}, ${gy} + ${H * 0.85}, ${info.cz} + ${info.fwd.z} * ${L * 0.14});
      cam.updateMatrixWorld(true);
    })()`);
    // (5) END-ON — from just outside the tunnel MOUTH at eye height, looking in
    //     along the spine axis: the arch cross-section / colonnade read.
    await shot('endon', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const fx = ${info.cx} - ${info.fwd.x} * ${L * 0.62};
      const fz = ${info.cz} - ${info.fwd.z} * ${L * 0.62};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 2.0, fz);
      cam.lookAt(${info.cx}, ${gy} + ${H * 0.5}, ${info.cz});
      cam.updateMatrixWorld(true);
    })()`);
    // (6) LOWGRAZE — a very low angle skimming across the rib bases: the FLOAT
    //     check (every rib base must plant in the sand, no gaps under the bones).
    await shot('lowgraze', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const fx = ${info.cx} + ${side.x} * ${L * 0.55} - ${info.fwd.x} * ${L * 0.3};
      const fz = ${info.cz} + ${side.z} * ${L * 0.55} - ${info.fwd.z} * ${L * 0.3};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 0.8, fz);
      cam.lookAt(${info.cx}, ${gy} + 1.2, ${info.cz});
      cam.updateMatrixWorld(true);
    })()`);
    // (7) FLANK-CLOSE — the RIB-GAUGE + DECAY read the far shots can't give: a
    //     player-eye stand ~16m off the flank at the tall mid-section. This is the
    //     frame that answers "are the bones too chunky / too thin?" and "do the
    //     snapped stumps + the halves lying beside them read as a weathered
    //     carcass?" (the 70m broadside renders a 77×8m carcass as a thin band).
    await shot('flankclose', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const fx = ${info.cx} + ${side.x} * 16 - ${info.fwd.x} * ${L * 0.16};
      const fz = ${info.cz} + ${side.z} * 16 - ${info.fwd.z} * ${L * 0.16};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 1.7, fz);
      cam.lookAt(${info.cx}, ${gy} + 3.2, ${info.cz});
      cam.updateMatrixWorld(true);
    })()`);
    // (8) FALLEN-CLOSE — a 9m player-eye read of the sand OUTBOARD of the rib feet,
    //     where the snapped-off halves came to rest: are they resting IN the sand
    //     (part-buried, not floating), and does a fallen half pair up with a stump?
    await shot('fallenclose', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const fx = ${info.cx} + ${side.x} * 19 + ${info.fwd.x} * ${L * 0.1};
      const fz = ${info.cz} + ${side.z} * 19 + ${info.fwd.z} * ${L * 0.1};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + 1.6, fz);
      cam.lookAt(${info.cx} + ${side.x} * 6, ${gy} + 0.4, ${info.cz} + ${side.z} * 6);
      cam.updateMatrixWorld(true);
    })()`);
    // (9) BREAK-CLOSE + (10) BREAK-PAIR — the TIGHT fracture read. The flank shots are
    //     15-20m out; at that range a jagged snap and a rounded sausage end are the
    //     same handful of pixels. These frame ONE real snap (userData.breaks, resolved
    //     above): `breakclose` is ~4m off the STUMP's break face — is it unmistakably a
    //     splintered snap? `breakpair` backs off to hold the stump AND the half that
    //     fell off it in one frame — do the two faces read as one break?
    if (info.brk) {
      const b = info.brk;
      console.log(`[bone-hero] framing snap at ${b.s.x.toFixed(0)},${b.s.y.toFixed(1)},${b.s.z.toFixed(0)} worldR=${b.r.toFixed(2)}m (group scale ${b.scale.toFixed(2)})`);
      // Framing the fracture took three tries; both prerequisites are load-bearing:
      //  • FRONT-LIT. Shooting from wherever the flank normal pointed put the sun
      //    BEHIND the break — it rendered as an undifferentiated dark cavity and I was
      //    grading the lighting, not the geometry (visual-diagnostic-methodology).
      //  • PERPENDICULAR TO THE SHAFT. Standing "sunward of the break" put the camera
      //    down the rib's own axis, filling the frame with shaft. Project the sun
      //    azimuth onto the plane ⊥ the rib axis (falling back to axis × up when the
      //    rib points at the sun) → front-lit AND square-on to the break face.
      const camCode = (dist, up, roll) => `(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
        const V = cam.position.constructor;
        const ax = new V(${b.a.x}, ${b.a.y}, ${b.a.z}).normalize();
        const sd = ctx.time.sunDir;
        let view = new V(sd.x, 0, sd.z).normalize();       // stand toward the sun
        view.addScaledVector(ax, -view.dot(ax));           // ...but ⊥ to the rib
        if (view.length() < 0.25) view.copy(ax).cross(new V(0, 1, 0));
        view.normalize();
        // roll the view around the rib axis so the shard side is not self-occluded
        view.applyAxisAngle(ax, ${roll});
        const p = new V(${b.s.x}, ${b.s.y}, ${b.s.z}).addScaledVector(view, ${dist});
        cam.position.set(p.x, p.y + ${up}, p.z);
        cam.lookAt(${b.s.x}, ${b.s.y}, ${b.s.z});
        cam.updateMatrixWorld(true);
      })()`;
      // Distances are in BONE DIAMETERS, not metres — the landmark is placed at a
      // per-instance scale, so a fixed metre standoff frames a different-sized bone
      // every seed. Square-on to the break face at ~5 diameters.
      await shot('breakclose', camCode((5.0 * b.r).toFixed(2), (0.5 * b.r).toFixed(2), 0));
      // ...and 55° around the shaft — a fracture has to read as a snap from more than
      // one angle (verify-visual-multi-angle), and the oblique slash only shows its
      // slant once you are off-square.
      await shot('breakprofile', camCode((5.6 * b.r).toFixed(2), (1.2 * b.r).toFixed(2), 0.95));
      await shot('breakpair', `(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
        const mx = (${b.s.x} + ${b.f.x}) * 0.5, my = (${b.s.y} + ${b.f.y}) * 0.5, mz = (${b.s.z} + ${b.f.z}) * 0.5;
        const d = 9.5;
        cam.position.set(mx + ${side.x} * d, ctx.terrain.heightAt(mx + ${side.x} * d, mz + ${side.z} * d) + 1.7, mz + ${side.z} * d);
        cam.lookAt(mx, my, mz);
        cam.updateMatrixWorld(true);
      })()`);
    } else {
      console.log('[bone-hero] no snap found in userData.breaks — fracture read SKIPPED');
    }
    // (DIAG) Isolate the ribcage — hide every OTHER scene child so only the
    //   ribcage renders. Any bone still visible in the other shots but GONE here
    //   is a separate boneScatter decoration, not a ribcage floater.
    await shot('isolate', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      let rc = null; ctx.three.scene.traverse((o) => { if (o.name === 'giantRibcage') rc = o; });
      window.__diagHidden = [];
      ctx.three.scene.traverse((o) => {
        if (!o.isMesh) return;
        let w = o, isRc = false;
        while (w) { if (w === rc) { isRc = true; break; } w = w.parent; }
        const isTerrain = /terrain|tile|ground|sky/i.test(o.name || '');
        if (!isRc && !isTerrain && o.visible) { window.__diagHidden.push(o); o.visible = false; }
      });
      const fx = ${info.cx} + ${side.x} * ${L * 0.92};
      const fz = ${info.cz} + ${side.z} * ${L * 0.92};
      cam.position.set(fx, ctx.terrain.heightAt(fx, fz) + ${H * 0.5}, fz);
      cam.lookAt(${info.cx}, ${gy} + ${H * 0.4}, ${info.cz});
      cam.updateMatrixWorld(true);
    })()`);
    await page.evaluate(`(() => { (window.__diagHidden||[]).forEach(o => o.visible = true); window.__diagHidden = []; })()`);
    // ── Rule-9 leak probe: the ribcage's rib + spine + skull colliders must tear
    //    down on unload and not accumulate across repeated visits. Load→unload→
    //    reload the anchor chunk; the physics-body count must return to baseline. ──
    const leak = await page.evaluate(async (a) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const settle = async (x, z, frames) => {
        ctx.player.body.body.setTranslation({ x, y: ctx.terrain.heightAt(x, z) + 1.6, z }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        for (let f = 0; f < frames; f++) await raf();
      };
      await settle(a.x, a.z, 200);
      const loaded = ctx.physics.world.bodies.len();
      await settle(a.x + 3000, a.z + 3000, 220);   // far → worm chunk unloads
      const away = ctx.physics.world.bodies.len();
      await settle(a.x, a.z, 220);                  // back → worm chunk reloads
      const reloaded = ctx.physics.world.bodies.len();
      return { loaded, away, reloaded };
    }, anchor);
    const leakOk = leak.loaded === leak.reloaded;
    console.log(`[bone-hero] body-leak probe: loaded=${leak.loaded} away=${leak.away} reloaded=${leak.reloaded} ${leakOk ? 'NO LEAK' : 'LEAK!'}`);
  },

  'chunk-vista': async (page) => {
    await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      ctx.sandWorms.list.length = 0;
      g.setChunkMarkers(true);
      ctx.weather.intensity = 0; g.setTime(0.42);
      // The camera is hand-placed at the player's position — hide the 3P
      // rig + viewmodel so they don't photobomb the frame.
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1100, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 760; cam.updateProjectionMatrix(); }
      for (let x = 150; x <= 1500; x += 150) {
        ctx.player.body.body.setTranslation({ x, y: ctx.terrain.heightAt(x, 56) + 1.6, z: 56 }, true);
        await frames(12);
      }
      await frames(90);
      // Kill any in-flight dorsal-ridge crossing (its ~480m humps re-show
      // themselves every active frame — a scene-side hide can't stick, so
      // use the module's own reset; it photobombed the first fwd shot).
      g.resetWormCrossing();
    });
    const shot = async (name, evalFn) => {
      await page.evaluate(evalFn);
      await page.waitForTimeout(400);
      await page.screenshot({ path: join(OUT, `scen-chunk-vista-${name}.png`), timeout: 60000 });
      console.log(`[chunk-vista] saved scen-chunk-vista-${name}.png`);
    };
    const aim = (fx, fz, tx, tz, lift = 1.7, tiltDown = 0) => `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera;
      ctx.flags.paused = true;
      cam.position.set(${fx}, ctx.terrain.heightAt(${fx}, ${fz}) + ${lift}, ${fz});
      cam.lookAt(${tx}, ctx.terrain.heightAt(${tx}, ${tz}) - ${tiltDown}, ${tz});
      cam.updateMatrixWorld(true);
    })()`;
    // Diagnostic: name every large mesh near the far viewpoint so an
    // unexpected photobomber (ambient spectacle, stray landmark) is
    // identifiable from the log instead of a mystery silhouette.
    const near = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
      // Raycast from the fwd-shot camera position straight at the mystery
      // hump — identifies the actual on-screen occluder, merged meshes
      // included (a world-position sweep misses origin-anchored merges).
      const from = new THREE.Vector3(1500, ctx.terrain.heightAt(1500, 56) + 1.7, 56);
      const rc = new THREE.Raycaster(from, new THREE.Vector3(1, 0.05, 0).normalize(), 0.5, 2000);
      const meshes = [];
      ctx.three.scene.traverse((o) => { if (o.isMesh && o.visible) meshes.push(o); });
      const hits = [];
      for (const m of meshes) {
        try { rc.intersectObject(m, false, hits); } catch { /* skip broken raycast targets */ }
      }
      hits.sort((a, b) => a.distance - b.distance);
      return hits.slice(0, 4).map((h) => {
        const o = h.object;
        const chain = [];
        let p = o;
        while (p) { chain.unshift(p.name || p.type); p = p.parent; }
        const mat = Array.isArray(o.material) ? o.material[0] : o.material;
        return `${chain.join('>')} geo=${o.geometry ? o.geometry.type : '?'} d=${h.distance.toFixed(1)} col=${mat && mat.color ? mat.color.getHexString() : '?'}`;
      });
    });
    console.log('[chunk-vista] fwd-ray hits: ' + JSON.stringify(near));
    // Height profile along the fwd sightline — confirms whether a close
    // occluder is a dune face (terrain) vs an actual object.
    const prof = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const rows = [];
      for (let x = 1500; x <= 1560; x += 10) rows.push(`${x}:${ctx.terrain.heightAt(x, 56).toFixed(1)}`);
      return rows.join(' ');
    });
    console.log('[chunk-vista] height profile z=56: ' + prof);
    // Fwd vista from the local CREST (scan ±40m for the high point) so the
    // player-eye shot looks OUT over the field instead of into a dune face.
    const crest = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      let best = { x: 1500, z: 56, h: -1e9 };
      for (let x = 1460; x <= 1540; x += 4) {
        for (let z = 16; z <= 96; z += 4) {
          const h = ctx.terrain.heightAt(x, z);
          if (h > best.h) best = { x, z, h };
        }
      }
      return best;
    });
    await shot('fwd1500', aim(crest.x, crest.z, crest.x + 200, crest.z));
    await shot('back1500', aim(crest.x, crest.z, crest.x - 200, crest.z));
    // Walk back near the tile seam (unpause so streaming rebuilds), then shoot.
    await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      for (let x = 1350; x >= 1185; x -= 55) {
        ctx.player.body.body.setTranslation({ x, y: ctx.terrain.heightAt(x, 56) + 1.6, z: 56 }, true);
        for (let i = 0; i < 12; i++) await raf();
      }
      for (let i = 0; i < 60; i++) await raf();
    });
    await shot('seam', aim(1185, 56, 1300, 56, 3.5, 2));
    // Marker close-up: the center post of the chunk at (1512.5, 56) area —
    // use the player-chunk descriptor for an exact target.
    await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      for (let x = 1240; x <= 1460; x += 55) {
        ctx.player.body.body.setTranslation({ x, y: ctx.terrain.heightAt(x, 56) + 1.6, z: 56 }, true);
        for (let i = 0; i < 12; i++) await raf();
      }
      for (let i = 0; i < 60; i++) await raf();
    });
    await shot('marker', `(() => {
      const g = window.__game; const ctx = g.ctx; const cam = ctx.three.camera;
      const md = g.chunkDescribe(13, 0).markers[0];
      ctx.flags.paused = true;
      const gy = ctx.terrain.heightAt(md.x - 6, md.z - 6);
      cam.position.set(md.x - 6, gy + 1.7, md.z - 6);
      cam.lookAt(md.x, ctx.terrain.heightAt(md.x, md.z) + 1.2, md.z);
      cam.updateMatrixWorld(true);
    })()`);
    // S2 — a STREAMED wreck, player-eye: find the nearest descriptor-rolled
    // POI beyond the origin exclusion, walk there (streaming builds it),
    // frame it from ~20m at eye height.
    const poi = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      let target = null;
      outer:
      for (let cx = 12; cx <= 34; cx++) {
        for (let cz = -8; cz <= 8; cz++) {
          const d = g.chunkDescribe(cx, cz);
          if (d.poi.present) { target = d.poi; break outer; }
        }
      }
      if (!target) return null;
      ctx.flags.paused = false;
      // Step toward it so chunks stream in along the way.
      const from = ctx.player.body.body.translation();
      const steps = 10;
      for (let i = 1; i <= steps; i++) {
        const x = from.x + (target.x - from.x) * (i / steps);
        const z = from.z + (target.z - from.z) * (i / steps);
        ctx.player.body.body.setTranslation({ x, y: ctx.terrain.heightAt(x, z) + 1.6, z }, true);
        for (let f = 0; f < 12; f++) await raf();
      }
      for (let f = 0; f < 60; f++) await raf();
      return { x: target.x, z: target.z, archetype: target.archetype };
    });
    if (poi) {
      console.log(`[chunk-vista] streamed POI: ${poi.archetype} at ${poi.x.toFixed(0)},${poi.z.toFixed(0)}`);
      await shot('streamed-poi', `(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera;
        ctx.flags.paused = true;
        const px = ${poi.x}, pz = ${poi.z};
        const cx2 = px - 20, cz2 = pz - 14;
        cam.position.set(cx2, ctx.terrain.heightAt(cx2, cz2) + 1.7, cz2);
        cam.lookAt(px, ctx.terrain.heightAt(px, pz) + 2.5, pz);
        cam.updateMatrixWorld(true);
      })()`);
    } else {
      console.log('[chunk-vista] no streamed POI rolled in the scan window (seed-dependent)');
    }
    // S3 — a streamed ROCK FIELD (rocky biome) and a streamed WORDLESS
    // SCENE, both player-eye. Deterministic descriptor scans.
    const walkShoot = async (name, target, lookLift) => {
      if (!target) { console.log(`[chunk-vista] no ${name} in the scan window (seed-dependent)`); return; }
      await page.evaluate(async (t) => {
        const ctx = window.__game.ctx;
        ctx.flags.paused = false;
        const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
        const from = ctx.player.body.body.translation();
        for (let i = 1; i <= 10; i++) {
          const x = from.x + (t.x - from.x) * (i / 10);
          const z = from.z + (t.z - from.z) * (i / 10);
          ctx.player.body.body.setTranslation({ x, y: ctx.terrain.heightAt(x, z) + 1.6, z }, true);
          for (let f = 0; f < 12; f++) await raf();
        }
        for (let f = 0; f < 60; f++) await raf();
      }, target);
      await shot(name, `(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera;
        ctx.flags.paused = true;
        const px = ${target.x}, pz = ${target.z};
        const cx2 = px - 14, cz2 = pz - 10;
        cam.position.set(cx2, ctx.terrain.heightAt(cx2, cz2) + 1.7, cz2);
        cam.lookAt(px, ctx.terrain.heightAt(px, pz) + ${lookLift}, pz);
        cam.updateMatrixWorld(true);
      })()`);
    };
    const targets = await page.evaluate(() => {
      const g = window.__game;
      let rockT = null, sceneT = null;
      for (let cx = 12; cx <= 40 && (!rockT || !sceneT); cx++) {
        for (let cz = -12; cz <= 12 && (!rockT || !sceneT); cz++) {
          const d = g.chunkDescribe(cx, cz);
          if (!rockT && d.rocks.length >= 4) rockT = { x: d.rocks[0].x, z: d.rocks[0].z };
          if (!sceneT && d.scene.present) sceneT = { x: d.scene.x, z: d.scene.z };
        }
      }
      return { rockT, sceneT };
    });
    await walkShoot('streamed-rocks', targets.rockT, 0.6);
    await walkShoot('streamed-scene', targets.sceneT, 0.8);
    // D299 — the far-field DRESSING reads inhabited: the nearest streamed
    // dead tree and the nearest streamed well, player-eye.
    const dressT = await page.evaluate(() => {
      const g = window.__game;
      let treeT = null, wellT = null;
      for (let cx = 12; cx <= 60 && (!treeT || !wellT); cx++) {
        for (let cz = -20; cz <= 20 && (!treeT || !wellT); cz++) {
          const d = g.chunkDescribe(cx, cz);
          if (!treeT && d.dressing.trees.length > 0) treeT = { x: d.dressing.trees[0].x, z: d.dressing.trees[0].z };
          if (!wellT && d.dressing.well.present) wellT = { x: d.dressing.well.x, z: d.dressing.well.z };
        }
      }
      return { treeT, wellT };
    });
    if (dressT.treeT) console.log(`[chunk-vista] streamed tree at ${dressT.treeT.x.toFixed(0)},${dressT.treeT.z.toFixed(0)}`);
    await walkShoot('streamed-tree', dressT.treeT, 2.2);
    if (dressT.wellT) console.log(`[chunk-vista] streamed well at ${dressT.wellT.x.toFixed(0)},${dressT.wellT.z.toFixed(0)}`);
    await walkShoot('streamed-well', dressT.wellT, 0.8);
    // S4 — the nearest hero landmark + the nearest regional wreck-yard.
    const s4targets = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      let lmT = null;
      for (let cx = 12; cx <= 60 && !lmT; cx++) {
        for (let cz = -20; cz <= 20 && !lmT; cz++) {
          const d = g.chunkDescribe(cx, cz);
          if (d.landmark.present) lmT = { x: d.landmark.x, z: d.landmark.z, kind: d.landmark.kind };
        }
      }
      let yardT = null, bestD = Infinity;
      for (let x = -15000; x <= 15000; x += 400) {
        for (let z = -15000; z <= 15000; z += 400) {
          if (x * x + z * z < 2200 * 2200) continue;
          if (ctx.biomes.wreckYardAt(x, z) > 0.9) {
            const dd = x * x + z * z;
            if (dd < bestD) { bestD = dd; yardT = { x, z }; }
          }
        }
      }
      return { lmT, yardT };
    });
    if (s4targets.lmT) console.log(`[chunk-vista] landmark: ${s4targets.lmT.kind} at ${s4targets.lmT.x.toFixed(0)},${s4targets.lmT.z.toFixed(0)}`);
    await walkShoot('streamed-landmark', s4targets.lmT, 4.0);
    // M7 — the nearest SKYFALL freighter, player-eye at two reads: an
    // approach framing (~45m) and a close hull read (~15m).
    const skyT = await page.evaluate(() => {
      const g = window.__game;
      for (let r = 1; r <= 8; r++) {                       // spiral out by chunk rings
        for (let cx = -r * 16; cx <= r * 16; cx += 4) {
          for (let cz = -r * 16; cz <= r * 16; cz += 4) {
            for (let dx = 0; dx < 4; dx++) for (let dz = 0; dz < 4; dz++) {
              const d = g.chunkDescribe(cx + dx, cz + dz);
              if (d.landmark.present && d.landmark.kind === 'skyfall_freighter') {
                return { x: d.landmark.x, z: d.landmark.z };
              }
            }
          }
        }
      }
      return null;
    });
    if (skyT) console.log(`[chunk-vista] SKYFALL freighter at ${skyT.x.toFixed(0)},${skyT.z.toFixed(0)}`);
    await walkShoot('skyfall-approach', skyT, 3.0);
    if (skyT) {
      await shot('skyfall-close', `(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera;
        ctx.flags.paused = true;
        const px = ${skyT.x}, pz = ${skyT.z};
        const cx2 = px + 11, cz2 = pz + 11;
        cam.position.set(cx2, ctx.terrain.heightAt(cx2, cz2) + 1.7, cz2);
        cam.lookAt(px, ctx.terrain.heightAt(px, pz) + 2.0, pz);
        cam.updateMatrixWorld(true);
      })()`);
    }
    if (s4targets.yardT) console.log(`[chunk-vista] regional wreck-yard at ${s4targets.yardT.x.toFixed(0)},${s4targets.yardT.z.toFixed(0)}`);
    await walkShoot('regional-wreck-yard', s4targets.yardT, 1.2);
    if (s4targets.yardT) {
      // Diag: is the regional yard actually BAKED into the tile? Read the
      // nearest terrain vertex color + the live sampler value at the spot.
      const diag = await page.evaluate((t) => {
        const ctx = window.__game.ctx;
        const wy = ctx.biomes.wreckYardAt(t.x, t.z);
        const biome = ctx.biomes.biomeAt(t.x, t.z);
        let best = null;
        for (const m of ctx.terrain.meshes) {
          const posA = m.geometry.getAttribute('position');
          const colA = m.geometry.getAttribute('color');
          for (let i = 0; i < posA.count; i += 37) {
            const wx = posA.getX(i) + m.position.x;
            const wz = posA.getZ(i) + m.position.z;
            const dd = (wx - t.x) ** 2 + (wz - t.z) ** 2;
            if (!best || dd < best.dd) best = { dd, r: colA.getX(i), g: colA.getY(i), b: colA.getZ(i) };
          }
        }
        return { wy: +wy.toFixed(3), biome, vtx: best ? [best.r.toFixed(2), best.g.toFixed(2), best.b.toFixed(2), Math.sqrt(best.dd).toFixed(0) + 'm'] : null };
      }, s4targets.yardT);
      console.log('[chunk-vista] yard diag: ' + JSON.stringify(diag));
    }
  },

  // ── M7 SKYFALL — a DEDICATED fast exterior framer for the crashed heavy
  //    freighter blockout (S1). Copies the chunk-vista teleport-stream pattern
  //    but skips the whole 1500m biome sweep: spiral-scan for the nearest
  //    region-rolled 'skyfall_freighter', hop the player there (~140m steps so
  //    chunks stream + the deferred build fires), read the wreck's true yaw off
  //    the built group, then shoot 4 player-eye reads keyed to the hull axis:
  //    a long broadside silhouette (~70m), an approach (~40m), a close broadside
  //    (~20m), and a bow close-quarter (~12m). ~1 min vs ~5.
  //    Run: node scripts/rig-shot.mjs --scenario=skyfall-shot --seed=1337 --port=5760
  'skyfall-shot': async (page) => {
    await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      ctx.sandWorms.list.length = 0;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.1;
      g.setTime(0.40);                                 // mid-morning: raking front light, form reads
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1280, 720, false);    // wide frame — length must dominate
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1280 / 720; cam.updateProjectionMatrix(); }
      await frames(4);
    });
    // Spiral-scan the descriptor grid for the nearest skyfall freighter.
    const skyT = await page.evaluate(() => {
      const g = window.__game;
      for (let r = 1; r <= 10; r++) {
        for (let cx = -r * 16; cx <= r * 16; cx += 4) {
          for (let cz = -r * 16; cz <= r * 16; cz += 4) {
            for (let dx = 0; dx < 4; dx++) for (let dz = 0; dz < 4; dz++) {
              const d = g.chunkDescribe(cx + dx, cz + dz);
              if (d.landmark.present && d.landmark.kind === 'skyfall_freighter') {
                return { x: d.landmark.x, z: d.landmark.z };
              }
            }
          }
        }
      }
      return null;
    });
    if (!skyT) { console.log('[skyfall-shot] no skyfall freighter found in scan window (check FEATURES.skyfall / seed)'); return; }
    console.log(`[skyfall-shot] SKYFALL freighter at ${skyT.x.toFixed(0)},${skyT.z.toFixed(0)}`);
    // FAST: single-teleport stream + poll-until-built (was a multi-hop walk).
    const streamed = await streamToSite(page, skyT.x, skyT.z, { park: 30 });
    console.log(`[skyfall-shot] streamed in ${streamed.frames} frames (built=${streamed.built})`);
    // Read the wreck's true yaw + center off the built group (the builder stashes
    // it on root.userData) so the camera can frame a genuine broadside/bow read.
    const info = await page.evaluate((t) => {
      const ctx = window.__game.ctx;
      let wreck = null, bestD = Infinity;
      ctx.three.scene.traverse((o) => {
        if (o.name === 'skyfallWreck' && o.userData && o.userData.skyfallCenter) {
          const c = o.userData.skyfallCenter;
          const dd = (c.x - t.x) ** 2 + (c.z - t.z) ** 2;
          if (dd < bestD) { bestD = dd; wreck = o; }
        }
      });
      if (!wreck) return { built: false };
      return { built: true, yaw: wreck.userData.skyfallYaw, cx: wreck.userData.skyfallCenter.x, cz: wreck.userData.skyfallCenter.z };
    }, skyT);
    if (!info.built) { console.log('[skyfall-shot] WARN: wreck group not found near target (deferred build did not fire?)'); }
    const yaw = info.built ? info.yaw : 0;
    console.log(`[skyfall-shot] wreck built=${info.built} yaw=${(yaw).toFixed(2)}rad`);
    // Hull local +Z (forward) maps to world (sin yaw, cos yaw) under the Y-rot;
    // broadside is perpendicular. skyfallCenter is the BOW origin, so aim at a
    // point ~22m forward = the whole-wreck midpoint (fore + snap + stern), so
    // the long/broadside reads capture the full length AND the snapped stern.
    const fwd = [Math.sin(yaw), Math.cos(yaw)];
    const broad = [Math.cos(yaw), -Math.sin(yaw)];
    const norm = (v) => { const m = Math.hypot(v[0], v[1]) || 1; return [v[0] / m, v[1] / m]; };
    const bcx = info.cx ?? skyT.x, bcz = info.cz ?? skyT.z;
    // aimAlong = forward offset (m) of the look target from the bow origin.
    const shot = async (name, camDir, dist, lift, lookY, aimAlong = 22) => {
      const ax = bcx + fwd[0] * aimAlong, az = bcz + fwd[1] * aimAlong;
      await page.evaluate(({ ax, az, dx, dz, dist, lift, lookY }) => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera;
        ctx.flags.paused = true;
        const px = ax + dx * dist, pz = az + dz * dist;
        const gy = ctx.terrain.heightAt(px, pz);
        cam.position.set(px, gy + lift, pz);
        cam.lookAt(ax, ctx.terrain.heightAt(ax, az) + lookY, az);
        cam.updateMatrixWorld(true);
      }, { ax, az, dx: camDir[0], dz: camDir[1], dist, lift, lookY });
      await page.waitForTimeout(350);
      await page.screenshot({ path: join(OUT, `scen-skyfall-${name}.png`), timeout: 60000 });
      console.log(`[skyfall-shot] saved scen-skyfall-${name}.png`);
    };
    const threeQ = norm([broad[0] * 0.8 + fwd[0] * 0.6, broad[1] * 0.8 + fwd[1] * 0.6]);
    const bowDir = norm([fwd[0] * 0.7 + broad[0] * 0.5, fwd[1] * 0.7 + broad[1] * 0.5]);
    await shot('long', broad, 72, 4.0, 2.0, 20);      // long broadside silhouette — full length + snap
    await shot('approach', threeQ, 42, 3.0, 2.5, 20); // 3/4 approach
    await shot('broadside', broad, 22, 2.6, 2.5, 20); // close broadside — bridge + containers + snap
    await shot('close', bowDir, 12, 1.9, 2.4, 5);     // bow close-quarter — burial + blunt bow read
    await shot('snap', threeQ, 18, 2.6, 1.5, 36);     // the SNAP: fracture mouths + stern engine block + gap
    // ── M7-R BUGHUNT — grazing-flank / underside / along-hull reads that
    //    REPRODUCE the user's close-range viewpoint (the curated angles above
    //    hide the hull-skin culling bug). The camera stands RIGHT BESIDE the
    //    hull flank at eye height and looks ALONG the length, so a culled outer
    //    skin reads as "see through the hull to the inner wall / to the sky."
    const flankShot = async (name, side, camAlong, camOut, camLift, aimAlong, aimOut, aimY) => {
      await page.evaluate(({ side, camAlong, camOut, camLift, aimAlong, aimOut, aimY, fwd, broad, bcx, bcz }) => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera;
        ctx.flags.paused = true;
        const px = bcx + fwd[0] * camAlong + broad[0] * camOut * side;
        const pz = bcz + fwd[1] * camAlong + broad[1] * camOut * side;
        const gy = ctx.terrain.heightAt(px, pz);
        cam.position.set(px, gy + camLift, pz);
        const ax = bcx + fwd[0] * aimAlong + broad[0] * aimOut * side;
        const az = bcz + fwd[1] * aimAlong + broad[1] * aimOut * side;
        cam.lookAt(ax, ctx.terrain.heightAt(ax, az) + aimY, az);
        cam.updateMatrixWorld(true);
      }, { side, camAlong, camOut, camLift, aimAlong, aimOut, aimY, fwd, broad, bcx, bcz });
      await page.waitForTimeout(350);
      await page.screenshot({ path: join(OUT, `scen-skyfall-${name}.png`), timeout: 60000 });
      console.log(`[skyfall-shot] saved scen-skyfall-${name}.png`);
    };
    // Stand beside the fore flank near the mouth, look ALONG the plating toward
    // the bow (the user's "standing next to the hull looking along it" view).
    await flankShot('flank-graze', 1, 26, 7, 1.7, 4, 4.5, 1.4);
    // Tight face-on-ish flank, grazing down the mid plating (see any skin cull).
    await flankShot('flank-close', -1, 16, 6.5, 1.6, 20, 4.8, 1.2);
    // Low near the belly/keel looking up + along the flank (underside read).
    await flankShot('flank-low', 1, 20, 9, 0.35, 8, 5.5, 2.6);
    // MOUTH GRAZE — stand just outboard of the fracture mouth (along≈mouth) at
    // deck-lip height and look ACROSS the opening plane at the wall sandwich, so a
    // see-through slot between the hull skins + interior wall, or a paper-thin
    // exposed edge, is unmissable (the entrance-gap diagnostic).
    await flankShot('mouth-graze', 1, 31.5, 5.5, 0.9, 29.5, 2.6, 0.9);
    await flankShot('mouth-graze2', -1, 31.5, 5.5, 0.9, 29.5, 2.6, 0.9);
    // M7-S2 — interior reads (player-eye, from the builder's probe waypoints).
    const probe = await page.evaluate(() => {
      let p = null;
      window.__game.ctx.three.scene.traverse((o) => { if (o.userData?.skyfallProbe) p = o.userData.skyfallProbe; });
      return p ? { waypoints: p.waypoints } : null;
    });
    if (probe) {
      const wpByName = Object.fromEntries(probe.waypoints.map((w) => [w.name, w]));
      const interiorShot = async (name, fromW, toW) => {
        await page.evaluate(({ f, t }) => {
          const ctx = window.__game.ctx; const cam = ctx.three.camera;
          ctx.flags.paused = true;
          cam.position.set(f.x, f.y + 1.6, f.z);
          cam.lookAt(t.x, t.y + 1.2, t.z);
          cam.updateMatrixWorld(true);
        }, { f: fromW, t: toW });
        await page.waitForTimeout(350);
        await page.screenshot({ path: join(OUT, `scen-skyfall-${name}.png`), timeout: 60000 });
        console.log(`[skyfall-shot] saved scen-skyfall-${name}.png`);
      };
      await interiorShot('int-mouth', wpByName.outside, wpByName.hold);     // standing outside, looking in
      await interiorShot('int-hold', wpByName.hold, wpByName.door2);        // hold → the mid doorway
      await interiorShot('int-mid', wpByName.mid, wpByName.door1);          // mid bay → the cabin doorway
      await interiorShot('int-cabin', wpByName.cabin, wpByName.mid);        // cabin, looking back aft
      // bow-ward look at the cabin console + bow wall (the S6 focal point) —
      // the bow is DECREASING local z = the −fwd world direction from the cabin.
      await interiorShot('int-cabin-fwd', wpByName.cabin, { x: wpByName.cabin.x - fwd[0] * 4, y: wpByName.cabin.y, z: wpByName.cabin.z - fwd[1] * 4 });
      // HEAD-ON read of the mid-bay PORT wall (the ripped-open machine-room
      // signature): stand toward the starboard side of the mid bay, look at the
      // torn panel + exposed conduit/wire loom. local +X = broad, +Z = fwd.
      {
        const mid = wpByName.mid;
        const atLocal = (lx, lz, ly) => ({ x: mid.x + broad[0] * lx + fwd[0] * (lz - 16), y: mid.y + ly, z: mid.z + broad[1] * lx + fwd[1] * (lz - 16) });
        await page.evaluate(({ f, t }) => {
          const ctx = window.__game.ctx; const cam = ctx.three.camera;
          ctx.flags.paused = true;
          cam.position.set(f.x, f.y, f.z);
          cam.lookAt(t.x, t.y, t.z);
          cam.updateMatrixWorld(true);
        }, { f: atLocal(2.2, 16.8, 1.5), t: atLocal(-3.0, 14.4, 1.3) });
        await page.waitForTimeout(350);
        await page.screenshot({ path: join(OUT, 'scen-skyfall-int-mid-wall.png'), timeout: 60000 });
        console.log('[skyfall-shot] saved scen-skyfall-int-mid-wall.png');
      }
    }
  },

  // M7-S2 — the Skyfall WALK PROBE (rule 9, real motion): stream to the
  // nearest skyfall freighter, then WALK the interior — outside → mouth →
  // hold → doorway → mid → doorway → cabin → back out → re-enter — in small
  // stepped moves with physics settling, asserting at every waypoint that a
  // castDown hits the DECK collider (terrain sits within ~0.4m of the deck,
  // so collider IDENTITY is the fall-through proof), that the capsule wasn't
  // ejected (doorway/sill fit), and that ceiling + both walls answer rays.
  'skyfall-walk': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0; ctx.vultures.list.length = 0;
      ctx.weather.intensity = 0; g.setTime(0.40);
      // TINY CANVAS (2026-07-13 probe-infra): a physics/collision probe needs
      // NO pixels — shrink the render target so swiftshader fill cost is ~nil
      // (this is the CPU-heat lever for walk probes). 64² still ticks rAF.
      ctx.three.renderer.setSize(64, 64, false);
    });
    const skyT = await page.evaluate(() => {
      const g = window.__game;
      for (let r = 1; r <= 10; r++) {
        for (let cx = -r * 16; cx <= r * 16; cx += 4) {
          for (let cz = -r * 16; cz <= r * 16; cz += 4) {
            for (let dx = 0; dx < 4; dx++) for (let dz = 0; dz < 4; dz++) {
              const d = g.chunkDescribe(cx + dx, cz + dz);
              if (d.landmark.present && d.landmark.kind === 'skyfall_freighter') {
                return { x: d.landmark.x, z: d.landmark.z };
              }
            }
          }
        }
      }
      return null;
    });
    if (!skyT) throw new Error('skyfall-walk: no skyfall freighter in the scan window');
    // FAST: single-teleport stream + poll-until-built (was a multi-hop walk).
    const streamed = await streamToSite(page, skyT.x, skyT.z, { park: 30 });
    console.log(`[skyfall-walk] streamed in ${streamed.frames} frames (built=${streamed.built})`);
    const r = await page.evaluate(async (t) => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      ctx.flags.paused = false;
      const body = ctx.player.body.body;
      // Fetch the builder's probe data.
      let probe = null;
      ctx.three.scene.traverse((o) => { if (o.userData?.skyfallProbe) probe = o.userData.skyfallProbe; });
      if (!probe) return { fails: ['no skyfallProbe userData (wreck not built?)'] };
      const wps = Object.fromEntries(probe.waypoints.map((w) => [w.name, w]));
      const fails = [];
      const CAP = 1.05;   // capsule-center height above feet used for placement
      // Place at a waypoint (drop-in), settle under gravity/KCC.
      const placeAt = async (w) => {
        body.setTranslation({ x: w.x, y: w.y + CAP + 0.25, z: w.z }, true);
        body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        await frames(45);
      };
      // Walk from the current position to a waypoint in 0.5m steps at the
      // CURRENT settled height — collisions (lip, sills, jambs) resolve per
      // step; a blocked path shows up as failure to arrive.
      const walkTo = async (w) => {
        for (let i = 0; i < 200; i++) {
          const p = body.translation();
          const dx = w.x - p.x, dz = w.z - p.z;
          const d = Math.hypot(dx, dz);
          if (d < 0.35) break;
          const s = Math.min(0.5, d);
          body.setTranslation({ x: p.x + (dx / d) * s, y: p.y + 0.12, z: p.z + (dz / d) * s }, true);
          body.setLinvel({ x: 0, y: 0, z: 0 }, true);
          await frames(6);
        }
        await frames(30);
      };
      const arrived = (w, name) => {
        const p = body.translation();
        const d = Math.hypot(w.x - p.x, w.z - p.z);
        if (d > 0.8) fails.push(`${name}: did not arrive (blocked ${d.toFixed(2)}m short)`);
        return d <= 0.8;
      };
      const floorSet = new Set(probe.floorHandles ?? [probe.deckHandle]);
      const onDeck = (name, w) => {
        const p = body.translation();
        const hit = g.castDown(p.x, p.z, p.y, true);   // exclude the player capsule
        if (!hit) { fails.push(`${name}: castDown hit NOTHING`); return; }
        if (floorSet.has(hit.colliderHandle)) return;
        // Terrain AT-or-slightly-above the deck line = sand ingress in the
        // buried end (walkable, shin-deep max — legit wreck language).
        // Terrain BELOW the deck line = the capsule fell through. The bound
        // also fails waist-deep ingress (an unwalkable compartment).
        if (hit.hitY >= w.y - 0.05 && hit.hitY <= w.y + 0.5) return;
        fails.push(`${name}: on collider ${hit.colliderHandle} (deck=${probe.deckHandle} shape=${hit.shape}) hitY=${hit.hitY.toFixed(2)} py=${p.y.toFixed(2)} deckY=${w ? w.y.toFixed(2) : '?'} (FALL-THROUGH or deep ingress)`);
      };
      // ── The walk ──
      await placeAt(wps.outside);                          // on the sand off the mouth
      await walkTo(wps.mouth);                             // ENTER through the fracture
      if (arrived(wps.mouth, 'enter-mouth')) onDeck('enter-mouth', wps.mouth);
      await walkTo(wps.hold); if (arrived(wps.hold, 'hold')) onDeck('hold', wps.hold);
      await walkTo(wps.door2); if (arrived(wps.door2, 'door2 (mid↔hold doorway)')) onDeck('door2', wps.door2);
      await walkTo(wps.mid); if (arrived(wps.mid, 'mid')) onDeck('mid', wps.mid);
      await walkTo(wps.door1); if (arrived(wps.door1, 'door1 (cabin↔mid doorway)')) onDeck('door1', wps.door1);
      await walkTo(wps.cabin); if (arrived(wps.cabin, 'cabin')) onDeck('cabin', wps.cabin);
      // Exit the full length + off the ship, then RE-ENTER to the hold.
      await walkTo(wps.mouth); if (arrived(wps.mouth, 'exit-mouth')) onDeck('exit-mouth', wps.mouth);
      await walkTo(wps.outside);
      {
        const p = body.translation();
        if (Math.hypot(wps.outside.x - p.x, wps.outside.z - p.z) > 0.8) fails.push('exit: did not get back OUT of the mouth');
      }
      await walkTo(wps.hold); if (arrived(wps.hold, 're-enter hold')) onDeck('re-enter hold', wps.hold);
      // Ceiling presence: the capsule settled UNDER the roof everywhere it
      // stood — prove clearance is bounded (not open sky) by the deck-relative
      // ceiling value the builder exported: place mid, check headroom via a
      // high drop (a capsule dropped from +5 must still settle ON the deck —
      // the roof blocks a re-placement THROUGH it from above).
      body.setTranslation({ x: wps.mid.x, y: wps.mid.y + 6.0, z: wps.mid.z }, true);
      body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      await frames(50);
      {
        const p = body.translation();
        const hit = g.castDown(p.x, p.z, p.y, true);
        if (hit && hit.colliderHandle === probe.deckHandle) {
          fails.push('roof: a capsule dropped from ABOVE the hull landed on the interior deck (hole in the roof colliders)');
        }
      }
      return { fails, wps: probe.waypoints.length };
    }, skyT);
    const pass = r.fails.length === 0;
    console.log(`SKYFALL-WALK pass=${pass ? 1 : 0} waypoints=${r.wps ?? 0} fails=${r.fails.length}`);
    console.log(`[skyfall-walk] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r.fails)}`);
    if (!pass) throw new Error('skyfall-walk GATE FAILED');
  },

  // M6 ③ (C39) — flat-color-texture-audit render: deploy the camp objects (fire/bedroll/tent/
  // lantern) in a row so the procedural-material swaps are visible, frame them in good front
  // light, and report the shader-PROGRAM count (must stay at baseline — the audit reuses the
  // existing factories, adds zero new programs). The screenshot drives the appearance gate.
  'camp-studio': async (page) => {
    const r = await page.evaluate(() => {
      const g = window.__game; g.enterGame(true);
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      g.setTime(0.40);                       // morning — sun high + angled, not backlighting the row
      ctx.weather.cloudiness = 0.1; ctx.weather.intensity = 0;
      ctx.three.renderer.setSize(1000, 600, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 600; cam.updateProjectionMatrix(); }
      const out = g.campStudio();            // spawns the row ahead of the player + returns center + programs
      return out;
    });
    await page.waitForTimeout(400);
    await page.evaluate((center) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = true;
      const cam = ctx.three.camera;
      // Stand ~2.2m in FRONT of the row centre (forward = camera→centre) at near eye-level so the
      // fire logs + bedroll fabric read close, in 3/4 profile (not foreshortened top-down).
      const cx = center[0] - cam.position.x, cz = center[2] - cam.position.z;
      const d = Math.hypot(cx, cz) || 1;
      const fx = cx / d, fz = cz / d;
      cam.position.set(center[0] - fx * 2.2, center[1] + 1.3, center[2] - fz * 2.2);
      cam.lookAt(center[0], center[1] + 0.4, center[2]);
      cam.updateMatrixWorld(true);
      ctx.three.renderer.render(ctx.three.scene, cam);
    }, r.center);
    await page.waitForTimeout(150);
    await page.screenshot({ path: join(OUT, 'scen-camp-studio.png'), fullPage: false });
    console.log(`[camp-studio] programs=${r.programs} ${JSON.stringify(r)}`);
  },

  // M6 ④ (C40) — diegetic-survival WIRING gate (numeric). Forces diegetic mode + drives each
  // stat to its tell; asserts the matching vignette lights (>0) while the others stay dark
  // (~0), a healthy player shows nothing, and the HUD stat bars hide/show on toggle.
  'diegetic-probe': async (page) => {
    const r = await page.evaluate(() => { const g = window.__game; g.enterGame(true); return g.diegeticProbe(); });
    const lit = (v) => v > 0.02, dark = (v) => v < 0.02;
    const pass =
      lit(r.thirsty.thirst) && dark(r.thirsty.cold) && dark(r.thirsty.heat) && dark(r.thirsty.health) &&
      lit(r.cold.cold) && dark(r.cold.thirst) && dark(r.cold.heat) &&
      lit(r.hot.heat) && dark(r.hot.cold) &&
      lit(r.starving.hunger) &&
      lit(r.wounded.health) &&
      dark(r.healthy.thirst) && dark(r.healthy.cold) && dark(r.healthy.heat) && dark(r.healthy.hunger) && dark(r.healthy.health) &&
      r.barsHidden === true && r.barsShown === true;
    console.log(`[diegetic-probe] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r)}`);
  },

  // M6 ④ (C40) — diegetic-survival vignette RENDER (appearance gate). Forces diegetic mode +
  // sets ONE stat to its tell level so the screen-edge vignette shows over the game, then
  // screenshots. --stat=thirst|cold|heat|hunger|health (default health).
  'diegetic-vignette': async (page) => {
    const stat = argv.stat || 'health';
    await page.evaluate((stat) => {
      const g = window.__game; g.enterGame(true);
      const ctx = g.ctx;
      g.setTime(0.5);                       // noon — a cooler, brighter backdrop so the coloured tints read
      ctx.weather.cloudiness = 0.1; ctx.weather.intensity = 0;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(820, 520, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 820 / 520; cam.updateProjectionMatrix(); }
      // Aim at a clean dune horizon (slightly down), away from the spawn wreck.
      cam.rotation.set(-0.08, 0, 0);
      cam.updateMatrixWorld(true);
      g.showDiegeticVignette(stat);
      ctx.three.renderer.render(ctx.three.scene, cam);
      ctx.flags.paused = true;   // freeze so the live tick doesn't recompute the vignette
    }, stat);
    await page.waitForTimeout(550);   // let the CSS opacity transition settle to the target
    const op = await page.evaluate(() => {
      const ids = ['cold', 'thirst', 'heat', 'hunger', 'health'];
      const out = {};
      for (const id of ids) {
        const el = document.getElementById('stat-vignette-' + id);
        out[id] = el ? { o: el.style.opacity, comp: getComputedStyle(el).opacity, z: getComputedStyle(el).zIndex, disp: getComputedStyle(el).display } : null;
      }
      return out;
    });
    await page.screenshot({ path: join(OUT, `scen-diegetic-${stat}.png`), fullPage: false });
    console.log(`[diegetic-vignette] ${stat} rendered — ${JSON.stringify(op)}`);
  },

  // ACAQ — Sarlacc-pit behavior smoke test. Teleport the player onto the maw, let
  // the live game tick, confirm the maw OPENS + BITES (health drops). The pull
  // FEEL can't be judged headless (attended walk-test); this gates the wiring.
  'sarlacc-test': async (page) => {
    const before = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const pit = ctx.sarlaccPit;
      if (!pit) return { ok: false, reason: 'no pit' };
      // Teleport the player onto the maw rim.
      const bp = pit.basePos;
      ctx.player.body.body.setNextKinematicTranslation({ x: bp.x + 4, y: bp.y + 2, z: bp.z + 4 });
      ctx.stats.health = 1;
      return { ok: true, health0: ctx.stats.health, openAmt0: +pit.openAmt.toFixed(2), state0: pit.state, meshY0: +pit.mesh.position.y.toFixed(2) };
    });
    await page.waitForTimeout(5000);   // live ticks: maw opens + bites
    const after = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const pit = ctx.sarlaccPit;
      const tr = ctx.player.body.body.translation();
      const d = Math.hypot(tr.x - pit.basePos.x, tr.z - pit.basePos.z);
      return {
        health1: +ctx.stats.health.toFixed(3),
        openAmt1: +pit.openAmt.toFixed(2),
        state1: pit.state,
        meshY1: +pit.mesh.position.y.toFixed(2),
        playerDist: +d.toFixed(1),
        damaged: ctx.stats.health < 1,
        dead: ctx.stats.dead,
      };
    });
    console.log(`[sarlacc-test] ${JSON.stringify({ before, after })}`);
  },

  // Crashed-pod (T1.1) — the HERO escape-pod exterior at the desert wake spot.
  // SCENARIO-TRUTH FIX (2026-07-05): this scenario USED to place the DEV-ONLY placeCrashedPodWreck
  // (buildHeroPodMesh — a squat DOMED capsule, buried at yaw≈0.55, with an unconditional sand berm) —
  // a build the PLAYER NEVER SEES. The real crash flow grounds the ONE persistent walk-in pod via
  // unifyEnterablePod (buildPodScene canonical geometry, gentle _CRASH_PITCH/ROLL lean, NO yaw, plain
  // terrain — ENABLE_CRASH_GROUND_DRESSING off). So the old wake-frame findings (a detached flank
  // plate, tilt/drift/hardware mismatches) were grading a phantom. This now DRIVES THE REAL CHAIN
  // (startIntro → impact → wake → stepOut → unifyEnterablePod), like door-flush-audit / stepout-pod,
  // and frames the REAL landed 'escapePodCabin'. The player's-eye wake read is the gate (D165). The
  // real front DOOR faces cabin-local −Z (FDOOR_AZ=π; pod yaw≈0 → world outward (0,−1)); angles frame
  // relative to that normal. Angles: wake (player's-eye beside), hatch (close on the −Z door face),
  // oblique (3/4 whole silhouette), back (the +Z salvage-panel flank), close (upper-hull detail).
  // --time=<0..1> for the dawn/morning desert light. Front-lit.
  // (the 'smoke-intro' health GATE lives further down — a single definition now.)

  'crashed-pod': async (page) => {
    const angle = argv.angle || 'wake';
    const t = argv.time !== undefined ? Number(argv.time) : 0.32;   // dawn-ish, sun low + warm
    const popchute = !!argv.popchute;   // T4.3 — fire the comic chute-pop + freeze on the fully-inflated frame
    // ── Drive the REAL crash → wake → step-out chain so the REAL unified landed pod is the subject
    //    (mirrors stepout-pod / door-flush-audit — NOT the dev wreck). Each jump needs a live tick.
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(960, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 960 / 720; cam.updateProjectionMatrix(); }
      g.startIntro();
      g.jumpToBeat('impact');
    });
    await page.waitForTimeout(2600);
    await page.evaluate(() => { window.__game.jumpToBeat('wake'); });
    await page.waitForTimeout(1600);
    await page.evaluate(() => { window.__game.jumpToBeat('stepOut'); });
    await page.waitForTimeout(1400);   // let stepOut's init tick run unifyEnterablePod (skin + colliders + salvage)
    await page.evaluate(() => { window.__game.skipIntro(); });   // hand off to the real game (pod persists, HUD/sun restored)
    await page.waitForTimeout(900);
    if (popchute) { const adv = argv.settled ? 16.0 : 3.0; await page.evaluate((a) => { try { window.__game.popChute(a); } catch (e) { console.log('popChute err', e); } }, adv); }
    const r = await page.evaluate(({ ang, t }) => {
      const g = window.__game;
      const ctx = g.ctx;
      g.setTime(t);
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.12;
      ctx.three.renderer.toneMappingExposure = 1.25;
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      ctx.flags.paused = true;
      // the REAL unified landed pod persists under 'escapePodCabin'; derive its world (x,z).
      const pod = ctx.three.scene.getObjectByName('escapePodCabin');
      let px = 0, pz = 0;
      if (pod) { pod.updateMatrixWorld(true); const p = new V(); p.setFromMatrixPosition(pod.matrixWorld); px = p.x; pz = p.z; }
      const gy = ctx.terrain.heightAt(px, pz);
      // the front DOOR world-outward normal (FDOOR_AZ = π → (0,−1) at pod yaw≈0).
      const haz = Math.PI, hnx = Math.sin(haz), hnz = Math.cos(haz);
      // TALL VERTICAL CAPSULE: exposed body ~gy → gy+1.9. Aim at mid-body so the whole standing
      //   silhouette frames.
      const aimY = gy + 0.95;
      if (ang === 'wake') {
        // Player's-eye wake-beside: ~4.5m out on the hatch (−Z) side, biased +X so the door face AND
        //   the riveted flank both read at ~45° (a round 3D volume, not a flat slab).
        cam.position.set(px + hnx * 4.2 + 1.4, gy + 1.7, pz + hnz * 4.2 + 0.6);
        cam.lookAt(px - 0.1, aimY, pz);
      } else if (ang === 'hatch') {
        // Close-up squarely onto the −Z front door (the blown-open walk-in / salvage-adjacent face).
        const hd2 = 3.0;
        cam.position.set(px + hnx * hd2, gy + 1.2, pz + hnz * hd2);
        cam.lookAt(px + hnx * 0.3, gy + 0.9, pz + hnz * 0.3);
      } else if (ang === 'oblique') {
        // 3/4 of the WHOLE standing silhouette from a higher, further vantage (nose dome + base frame).
        cam.position.set(px + hnx * 4.4 + 2.2, gy + 2.6, pz + hnz * 4.4 + 1.4);
        cam.lookAt(px, aimY + 0.1, pz);
      } else if (ang === 'back') {
        // The +Z back flank (away from the −Z door) — the real salvage panel + riveted flank.
        cam.position.set(px - hnx * 4.2 + 0.6, gy + 1.9, pz - hnz * 4.2 - 0.4);
        cam.lookAt(px, aimY, pz);
      } else if (ang === 'flankx') {
        // ADDITIVE (chute r3) — the +X flank 3/4 where the drape POURS down the side. This is the vantage
        //   the user's screenshot showed the striped canopy INTERSECTING the hull, so it's the primary
        //   standoff-clip read. Camera out on +X, biased so the falling curtain + hull edge both frame.
        cam.position.set(px + 4.3, gy + 1.85, pz + 1.6);
        cam.lookAt(px, gy + 1.0, pz);
      } else if (ang === 'flankx-low') {
        // ADDITIVE (chute r3) — a LOWER, closer +X flank read grazing the hull edge-on, so any fabric that
        //   phases THROUGH the riveted skin is caught in profile (the standoff gap must read here).
        cam.position.set(px + 3.4, gy + 1.15, pz + 0.9);
        cam.lookAt(px - 0.2, gy + 1.1, pz + 0.1);
      } else if (ang === 'topdown') {
        // ADDITIVE (chute r3) — a near-top-down looking DOWN the pod axis: the draped cloth should ring the
        //   hull as an annulus a few cm PROUD of the riveted skin, never crossing inside the circle.
        cam.position.set(px + 1.2, gy + 5.6, pz + 1.2);
        cam.lookAt(px, gy + 1.4, pz);
      } else { // close — tight detail of the upper hull (porthole / rivets / nose)
        cam.position.set(px + hnx * 2.6 + 1.2, gy + 2.0, pz + hnz * 2.6 + 0.8);
        cam.lookAt(px, gy + 1.3, pz);
      }
      cam.updateMatrixWorld(true);
      // Front KEY light from above + beside the camera so the camera-facing hull is LIT (not a backlit
      //   silhouette — the harness front-light prerequisite).
      let DirCtor = null, HemiCtor = null;
      ctx.three.scene.traverse((o) => { if (o.isDirectionalLight && !DirCtor) DirCtor = o.constructor; if (o.isHemisphereLight && !HemiCtor) HemiCtor = o.constructor; });
      let key = ctx.three.scene.getObjectByName('__podKey');
      if (!key && DirCtor) { key = new DirCtor(); key.name = '__podKey'; key.intensity = 1.8; key.color.set(0xffe9cf); ctx.three.scene.add(key.target); ctx.three.scene.add(key); }
      if (key) {
        const toP = new V(px - cam.position.x, 0, pz - cam.position.z);
        key.position.set(cam.position.x + toP.x * 0.2 + 2, cam.position.y + 3, cam.position.z + toP.z * 0.2 + 1);
        key.target.position.set(px, aimY, pz); key.target.updateMatrixWorld(true);
      }
      if (!ctx.three.scene.getObjectByName('__podFill') && HemiCtor) { const fill = new HemiCtor(0xbfccdd, 0x6b5840, 0.5); fill.name = '__podFill'; ctx.three.scene.add(fill); }
      // Report: the REAL pod's exposed height above the sand + structural mesh count + the settled pose.
      let meshes = 0, maxY = -1e9, minY = 1e9;
      if (pod) { pod.updateMatrixWorld(true); pod.traverse((o) => { if (o.isMesh && o.geometry) { meshes++; o.geometry.computeBoundingBox(); const bb = o.geometry.boundingBox; for (const cy of [bb.min.y, bb.max.y]) { const wv = new V(0, cy, 0); o.localToWorld(wv); maxY = Math.max(maxY, wv.y); minY = Math.min(minY, wv.y); } } }); }
      const rot = pod ? [+pod.rotation.x.toFixed(3), +pod.rotation.y.toFixed(3), +pod.rotation.z.toFixed(3)] : null;
      const enterable = !!(g.probeCabinDoor && g.probeCabinDoor().built);
      return { angle: ang, podAt: [+px.toFixed(1), +pz.toFixed(1)], groundY: +gy.toFixed(2), exposedH: +(maxY - gy).toFixed(2), meshes, rot, enterable, found: !!pod, real: true };
    }, { ang: angle, t });
    await page.waitForTimeout(350);
    const tag = popchute ? `${angle}-chute` : angle;
    await page.screenshot({ path: join(OUT, `scen-crashed-pod-${tag}.png`), fullPage: false, animations: 'disabled', timeout: 60000 });
    console.log(`[crashed-pod] ${JSON.stringify(r)}`);
  },

  // Chute-lifecycle (round-2b) — a MOTION strip through the deployed chute's DEFLATE + DRAPE
  //   life-cycle (pop → flutter → deflate → settle). Drives the REAL crash→wake→stepOut→handoff
  //   chain (like crashed-pod) to land the ONE persistent pod, frames the pod + chute from a
  //   fixed exterior vantage, keeps the loop LIVE (updateChutePop ticks the lifecycle), pops the
  //   chute, then captures --frames screenshots --interval ms apart across the ~14s arc. The
  //   camera is fixed (not per-frame) so the strip reads as pure canopy motion. Flags:
  //     --wind=<0..1>   drive the storm intensity/wind so the flutter reads (default 0 = calm)
  //     --angle=front|side|high   the vantage on the pod+chute
  //     --frames=15 --interval=1000  (defaults tuned to span pop→settle; override for detail)
  //     --time=<0..1>   dawn/morning light (default 0.34 midday for max read)
  'chute-lifecycle': async (page) => {
    const angle = argv.angle || 'front';
    const wind = argv.wind !== undefined ? Math.max(0, Math.min(1, Number(argv.wind))) : 0;
    const t = argv.time !== undefined ? Number(argv.time) : 0.34;
    // Drive the REAL chain to the landed pod (mirrors crashed-pod), but leave the loop LIVE.
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(960, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 960 / 720; cam.updateProjectionMatrix(); }
      g.startIntro();
      g.jumpToBeat('impact');
    });
    await page.waitForTimeout(2600);
    await page.evaluate(() => { window.__game.jumpToBeat('wake'); });
    await page.waitForTimeout(1600);
    await page.evaluate(() => { window.__game.jumpToBeat('stepOut'); });
    await page.waitForTimeout(1400);
    await page.evaluate(() => { window.__game.skipIntro(); });   // hand off to the real game (pod persists)
    await page.waitForTimeout(900);
    // PAUSE the loop (so the game's updatePlayer can't stomp the camera) + fix camera/light/wind,
    //   then POP the chute at t=0. The lifecycle is ticked MANUALLY per frame via __game.tickChute
    //   (deterministic, no real-time wait) so the strip reads as pure canopy motion.
    const info = await page.evaluate(({ ang, t, wind }) => {
      const g = window.__game; const ctx = g.ctx;
      g.setTime(t);
      ctx.weather.intensity = wind; ctx.weather.perceivedIntensity = wind; ctx.weather.cloudiness = wind * 0.4;
      ctx.three.renderer.toneMappingExposure = 1.25;
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      ctx.flags.paused = true;   // freeze the sim — the camera stays where we put it below
      const pod = ctx.three.scene.getObjectByName('escapePodCabin');
      let px = 0, pz = 0;
      if (pod) { pod.updateMatrixWorld(true); const p = new V(); p.setFromMatrixPosition(pod.matrixWorld); px = p.x; pz = p.z; }
      const gy = ctx.terrain.heightAt(px, pz);
      const haz = Math.PI, hnx = Math.sin(haz), hnz = Math.cos(haz);
      window.__CHUTE_CAM = { px, pz, gy, hnx, hnz, ang };   // stash for the per-frame re-assert
      window.__CHUTE_WIND = wind; window.__CHUTE_WIND_DIR = { x: 0.85, z: 0.52 };   // fixed downwind for the lean
      // POP the chute directly (the real gag path is the pry; here we fire it so the strip starts at
      //   lifecycle t=0). The per-frame tickChute advances it.
      try { g.popChute(); } catch (e) { console.log('popChute err', e); }
      return { podAt: [+px.toFixed(1), +pz.toFixed(1)], groundY: +gy.toFixed(2), wind, angle: ang, found: !!pod };
    }, { ang: angle, t, wind });
    console.log(`[chute-lifecycle] setup ${JSON.stringify(info)}`);
    // Each strip frame: RE-ASSERT the camera + light (the pause holds them, but be safe), step the
    //   lifecycle ~1.05s (so 15 frames span the ~14s arc + a settled tail), pin exposure.
    const wtag = wind > 0.02 ? `-wind${Math.round(wind * 100)}` : '';
    await captureStrip(page, `chute-lifecycle-${angle}${wtag}`, `(i)=>{
      const g=window.__game; const ctx=g.ctx; const V=ctx.three.camera.position.constructor;
      const s=window.__CHUTE_CAM; const cam=ctx.three.camera; const {px,pz,gy,hnx,hnz,ang}=s;
      if(ang==='side'){cam.position.set(px-hnz*9.5+1.0,gy+3.6,pz+hnx*9.5+0.5);cam.lookAt(px,gy+2.5,pz);}
      else if(ang==='high'){cam.position.set(px+hnx*7.5+2.5,gy+6.5,pz+hnz*7.5+1.5);cam.lookAt(px,gy+2.2,pz);}
      else{cam.position.set(px+hnx*8.8+1.4,gy+3.6,pz+hnz*8.8+0.6);cam.lookAt(px-0.1,gy+2.6,pz);}
      cam.updateMatrixWorld(true);
      let DirCtor=null,HemiCtor=null; ctx.three.scene.traverse((o)=>{if(o.isDirectionalLight&&!DirCtor)DirCtor=o.constructor;if(o.isHemisphereLight&&!HemiCtor)HemiCtor=o.constructor;});
      let key=ctx.three.scene.getObjectByName('__podKey');
      if(!key&&DirCtor){key=new DirCtor();key.name='__podKey';key.intensity=1.7;key.color.set(0xffe9cf);ctx.three.scene.add(key.target);ctx.three.scene.add(key);}
      if(key){const toP=new V(px-cam.position.x,0,pz-cam.position.z);key.position.set(cam.position.x+toP.x*0.2+2,cam.position.y+4,cam.position.z+toP.z*0.2+1);key.target.position.set(px,gy+2.5,pz);key.target.updateMatrixWorld(true);}
      if(!ctx.three.scene.getObjectByName('__podFill')&&HemiCtor){const fill=new HemiCtor(0xbfccdd,0x6b5840,0.55);fill.name='__podFill';ctx.three.scene.add(fill);}
      ctx.three.renderer.toneMappingExposure=1.25;
      // step the lifecycle ~1.05s this frame (i>0; frame 0 shows the fresh pop). elapsed drives noise.
      if(i>0){const el=i*1.05; const dir=window.__CHUTE_WIND_DIR||{x:0.85,z:0.52}; for(let k=0;k<21;k++){g.tickChute(0.05,window.__CHUTE_WIND||0,el+k*0.05,dir.x,dir.z);}}
      const ph=g.chutePopT?g.chutePopT():{t:'?',phase:'?'}; console.log('[chute-lc] f'+i+' t='+ph.t+' phase='+ph.phase);
    }`);
  },

  // Pod-interior (T1.2): the REAL seated first-person view inside the HERO escape-pod
  // cabin. Drives the game's OWN intro path (startIntro → jumpToBeat) so the camera +
  // seat are EXACTLY what the player sees through enterPod/descent/parachute — NOT an
  // idealized studio rig. --angle: forward (viewport ahead), lever (look right at the
  // parachute lever + console), eject (look left at the eject control), wide (head-
  // turned 3/4 of the cabin), descent (forward with the planet swelled). --pull=<0..1>
  // poses the parachute lever; --snap droops it (the gag's broken state).
  'pod-interior': async (page) => {
    const angle = argv.angle || 'forward';
    const beat = argv.beat || (angle === 'descent' ? 'descent' : 'enterPod');
    const pull = argv.pull !== undefined ? Number(argv.pull) : 0;
    const snap = !!argv.snap;
    // --descent=<0..1> drives the vista swell/atmosphere ramp so the planet can be shot
    // at several altitudes (high 0.0 → low 0.9). Overrides the beat's own 0.7 default.
    const descent = argv.descent !== undefined ? Number(argv.descent) : null;
    const r = await page.evaluate(({ angle, beat, pull, snap, descent }) => {
      const g = window.__game;
      const ctx = g.ctx;
      // First-person (the seated read); hide the rig so it doesn't block the FP camera.
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      // Drive the real intro: start it (force), jump to the requested beat so the beat
      // controller builds the pod + seats the player facing −Z (the genuine FP frame).
      g.startIntro();
      g.jumpToBeat(beat);
      ctx.three.renderer.setSize(1000, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 760; cam.updateProjectionMatrix(); }
      if (descent !== null) { try { g.setDescentProgress(descent); } catch {} }
      else if (angle === 'descent' || beat === 'descent') { try { g.setDescentProgress(0.7); } catch {} }
      if (pull > 0 || snap) { try { g.setParachuteLeverPull(pull, snap); } catch {} }
      return { beat, angle };
    }, { angle, beat, pull, snap, descent });
    // Let the beat controller tick (it runs in the page's RAF loop) so the pod builds +
    // the player is seated, THEN pose the camera for the chosen look. We re-seat from the
    // real spawn + aim the head — mirroring the seated FP look directions.
    await page.waitForTimeout(600);
    const meas = await page.evaluate(({ angle, pull, snap, descent }) => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.paused = true;
      if (descent !== null) { try { g.setDescentProgress(descent); } catch {} }
      if (pull > 0 || snap) { try { g.setParachuteLeverPull(pull, snap); } catch {} }
      // R1b — mirror tickDescent's fog thinning so the rig sees the SAME real-world descent
      // view the player gets (the game's survival fog otherwise hazes the ground from altitude).
      if (descent !== null) {
        const fog = ctx.three.scene.fog;
        // W6 item 5 — mirror the descent fog: thin high (the clear vista), blending to survival as
        //   the pod drops below ~150 m (altitude = 600·(1−p^1.7)). Faithful to blendDescentFog.
        if (fog && 'density' in fog) {
          const alt = 600 * (1 - Math.pow(descent, 1.7));
          const kRaw = Math.max(0, Math.min(1, 1 - alt / 150));
          const k = kRaw * kRaw * (3 - 2 * kRaw);
          const survival = 0.0018;   // FOG_DENSITY_CLEAR (the game's survival target at ground level)
          fog.density = 0.00006 + (survival - 0.00006) * k;
        }
        // Mirror tickDescent's SKY blend: space (1) high → desert (0) as the pod drops. Without this
        // the rig's descent shows the normal daytime sky (a tan fog wall), not the orbit vista.
        // W6 item 3 — drive the planet APPROACH with the NEW two-phase curve (slow far, faster near)
        //   via the exported planetApproachCurve, so the rig shows the reworked approach faithfully.
        try { g.setSkyIntroMode(1 - Math.min(1, Math.max(0, (descent - 0.14) / 0.34))); } catch {}
        try { g.setPlanetApproach(g.planetApproachCurve(descent)); } catch {}
      }
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      // R1b — the pod now PHYSICALLY descends (setDescentProgress moves the pod GROUP + the
      // collider cage to the current altitude). setDescentProgress(descent) above moved the
      // pod, but NOT the player body, so derive the seated EYE from the POD GROUP world origin
      // (floor-top centre) — the genuine seated FP eye relative to the descending capsule. The
      // seat math mirrors getPodSpawn: origin + (halfHeight+radius) for the body centre, +0.35
      // aft, + the seated eyeOffset for the eye. Falls back to the body if the pod isn't found.
      const pod0 = ctx.three.scene.getObjectByName('escapePodCabin');
      let eye;
      if (pod0) {
        pod0.updateMatrixWorld(true);
        const o = pod0.getWorldPosition(new V());
        const pb = ctx.player.body;
        const bodyY = o.y + (pb.halfHeight || 0.6) + (pb.radius || 0.3);
        eye = new V(o.x, bodyY + (ctx.player.eyeOffset || 0.5), o.z + 0.35);
        // Re-seat the actual body too (so any live tick agrees + nothing snaps it back).
        pb.body.setTranslation({ x: o.x, y: bodyY, z: o.z + 0.35 }, true);
      } else {
        const tr = ctx.player.body.body.translation();
        eye = new V(tr.x, tr.y + (ctx.player.eyeOffset || 0.6), tr.z);
      }
      cam.position.copy(eye);
      // Look directions in the pod-local frame: −Z is forward (viewport), +X is right
      // (the parachute lever / console), −X is left (the eject control).
      let look;
      if (angle === 'forward') look = new V(eye.x, eye.y - 0.08, eye.z - 1);
      // R1b — the DESCENT look pitch tracks altitude (matches tickDescent): SHALLOW high (the
      // horizon + far dunes read) → STEEP low (the desert rushes up). pitch = -0.12 - 0.28·p².
      else if (angle === 'descent') {
        const dp = descent !== null ? descent : 0.7;
        const pitch = -0.12 - 0.28 * (dp * dp);
        look = new V(eye.x, eye.y + Math.tan(pitch), eye.z - 1);
      }
      else if (angle === 'down') look = new V(eye.x, eye.y - 1.0, eye.z - 0.45);   // R1b probe — look DOWN-and-out the porthole at the approaching ground
      else if (angle === 'lever') look = new V(eye.x + 1, eye.y - 0.25, eye.z - 0.55);
      else if (angle === 'eject') look = new V(eye.x - 0.9, eye.y - 0.25, eye.z - 0.8);
      else if (angle === 'wide') look = new V(eye.x + 0.7, eye.y - 0.1, eye.z - 0.7);
      else if (angle === 'floor') look = new V(eye.x, eye.y - 1.0, eye.z - 0.6);   // look DOWN at the deck/footwell
      else look = new V(eye.x, eye.y - 0.08, eye.z - 1);
      cam.lookAt(look);
      cam.updateMatrixWorld(true);
      // Report: is the cabin built? mesh count? eye world pos? pod altitude above the spawn?
      const pod = ctx.three.scene.getObjectByName('escapePodCabin');
      let meshes = 0;
      if (pod) pod.traverse((o) => { if (o.isMesh) meshes++; });
      const rp = ctx.intro && ctx.intro.returnPos ? ctx.intro.returnPos : null;
      const podY = pod ? +pod.getWorldPosition(new V()).y.toFixed(1) : null;
      const altAboveSpawn = (pod && rp) ? +(pod.getWorldPosition(new V()).y - rp.y).toFixed(1) : null;
      return {
        found: !!pod, meshes, eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)],
        podY, altAboveSpawn, spawn: rp ? [+rp.x.toFixed(1), +rp.y.toFixed(1), +rp.z.toFixed(1)] : null,
      };
    }, { angle, pull, snap, descent });
    // RE-ANCHOR the camera-relative space planet + star field + sky dome to the posed camera, and
    // apply the space-mode fog/background darkening — all of which updateSky does per-frame but we
    // paused before it could run at the pod's high-altitude camera. Without this the porthole shows
    // the stale desert-fog/background TAN (the same bug the cockpit had), not the real orbit vista.
    await page.evaluate((descent) => {
      const ctx = window.__game.ctx;
      const cam = ctx.three.camera; cam.updateMatrixWorld(true);
      const V = cam.position.constructor;
      const s = (ctx.three.scene);
      if (descent === null) return;
      // The space blend for this altitude (mirrors tickDescent): full space high → dawn desert low.
      // C3 — MATCH tickDescent's (descent−0.14)/0.34 curve so the rig's blend is faithful.
      const space01 = 1 - Math.min(1, Math.max(0, (descent - 0.14) / 0.34));
      // W6 item 3 — the planet-approach factor at this altitude via the NEW two-phase curve (slow
      //   far, faster near), so the paused rig mirrors the reworked approach.
      const approach = window.__game.planetApproachCurve(descent);
      if (space01 <= 0.01) return;   // low in the fall the sky has crossed to the dawn desert — leave it
      let dome = null, stars = null, planetGroup = null;
      s.traverse((o) => {
        if (o.isMesh && o.material && o.material.uniforms && o.material.uniforms.uTopColor) dome = o;
        if (o.isPoints && o.renderOrder === -0.5) stars = o;
        if (o.isMesh && o.renderOrder === -0.4 && o.parent) planetGroup = o.parent;
      });
      // Manually APPLY the space-mode uniforms + anchor (applySpaceMode runs in updateSky, which is
      // gated by the pause — so at a paused descent frame the dome is still the daytime sky). Set the
      // dome black + kill clouds + lift stars, matching applySpaceMode, scaled by space01.
      if (dome) {
        const u = dome.material.uniforms; const C = u.uTopColor.value.constructor;
        u.uTopColor.value.lerp(new C(0x01020a), space01);
        u.uHorizonColor.value.lerp(new C(0x03050f), space01);
        if (u.uSpace) u.uSpace.value = space01;
        if (u.uCloudiness) u.uCloudiness.value *= (1 - space01);
        if (u.uSunGlow) u.uSunGlow.value *= (1 - space01 * 0.9);
        dome.position.copy(cam.position); dome.updateMatrixWorld(true);
      }
      if (stars) {
        const u = stars.material.uniforms;
        if (u.uOpacity) u.uOpacity.value = Math.max(u.uOpacity.value, space01);
        if (u.uBrightness) u.uBrightness.value = 3.0 * space01 + u.uBrightness.value * (1 - space01);
        if (u.uSpace) u.uSpace.value = space01;
        stars.position.copy(cam.position); stars.updateMatrixWorld(true);
      }
      if (planetGroup) {
        // C3 — mirror applySpaceMode's APPROACH: scale the group up + slide it DOWN as the planet
        //   approaches (ease-in), so the paused rig shows the SAME swelling planet the live descent
        //   produces (the planet fills the porthole across d0→d0.2).
        // SEV2 2026-07-05 — anchor/approach constants now read from sky.ts's userData TRUTH STAMP
        //   (buildSpacePlanet stamps them on the group) so this mirror can't drift again: the old
        //   hardcoded DIST=400/drop=150 predated the W4 400→1000 retune (radius 66→165, drop 375)
        //   → the paused rig rendered a 2.6×-oversized planet (false frame). Fallbacks = current sky.ts.
        const ud = planetGroup.userData || {};
        const ad = ud.spaceAnchorDir || [0.30, 0.10, -1];
        const dir = new V(ad[0], ad[1], ad[2]).normalize();
        const DIST = ud.spaceAnchorDistance || 1000;
        const ae = approach * approach;
        const scale = 1 + ((ud.approachMaxScale || 3.6) - 1) * ae;   // _PLANET_APPROACH_MAX_SCALE
        const drop = (ud.approachDrop || 375) * ae;                  // _PLANET_APPROACH_DROP
        planetGroup.scale.setScalar(scale);
        planetGroup.position.set(cam.position.x + dir.x*DIST, cam.position.y + dir.y*DIST - drop, cam.position.z + dir.z*DIST);
        planetGroup.updateMatrixWorld(true);
        planetGroup.traverse((o) => { if (o.material && o.material.uniforms && o.material.uniforms.uOpacity) o.material.uniforms.uOpacity.value = space01; });
      }
      // darken the background + thin/space-tint the fog (mirrors applySpaceMode) so no tan shows.
      const bg = s.background;
      if (bg && bg.isColor) { const C = bg.constructor; bg.lerp(new C(0x01020a), space01); }
      const fog = s.fog;
      if (fog && fog.density !== undefined) { fog.density = fog.density * (1 - space01) + 0.00002 * space01; if (fog.color) { const C = fog.color.constructor; fog.color.lerp(new C(0x03050f), space01); } }
      // Full-intro coherence fix mirror: dim the WORLD sun + ambient by the orbit blend so the
      // paused rig shows the SAME vacuum-lit cabin the in-game applySpaceMode now produces (the
      // desert noon light no longer floods the pod cabin to pale white). See sky.ts applySpaceMode.
      if (ctx.lights) {
        ctx.lights.sun.intensity *= (1 - space01 * 0.88);
        ctx.lights.ambient.intensity *= (1 - space01 * 0.94);
      }
    }, descent);
    await page.waitForTimeout(300);
    const perfPi = await page.evaluate(() => { const ctx = window.__game.ctx; ctx.three.renderer.info.reset(); ctx.three.renderer.render(ctx.three.scene, ctx.three.camera); const i = ctx.three.renderer.info; const pod = ctx.three.scene.getObjectByName('escapePodCabin'); let pm = 0; if (pod) pod.traverse((o) => { if (o.isMesh) pm++; }); return { draws: i.render.calls, tris: i.render.triangles, programs: i.programs?.length ?? -1, podMeshes: pm }; });
    console.log('[pod-interior-perf] ' + JSON.stringify(perfPi));
    const dtag = descent !== null ? `-d${String(descent).replace('.', '')}` : '';
    const tag = `pod-interior-${angle}${dtag}${pull > 0 ? '-pull' + pull : ''}${snap ? '-snap' : ''}`;
    await page.screenshot({ path: join(OUT, `scen-${tag}.png`), fullPage: false, animations: 'disabled', timeout: 60000 });
    console.log(`[pod-interior] ${JSON.stringify(meas)} → scen-${tag}.png`);
  },

  // DESCENT-FIX DIAGNOSTIC (additive) — reproduce the re-entry streak/fire read from the SEATED
  //   porthole eye with the FX ANIMATING LIVE (not a paused static frame — the streaks scroll, so a
  //   still can miss the bleed). Un-pauses on a keepalive, drives setDescentProgress into the re-entry
  //   window (default p=0.24 peak), and captures N frames. Also reports the world-Z depth ordering of
  //   the porthole GLASS vs the reentry PLASMA/SHIMMER meshes + their material flags (the occlusion
  //   diagnosis). --descent=<p> re-entry sample point · --frames=<n> · --out=<basename>.
  'descent-fx-probe': async (page) => {
    const descent = argv.descent !== undefined ? Number(argv.descent) : 0.24;
    const frames = argv.frames !== undefined ? Number(argv.frames) : 3;
    const live = !!argv.live;   // --live: let the real beat tick advance through re-entry (no pause/pin) + camera-follow the falling pod
    const base = argv.out || `scen-descent-fix-fxprobe-d${String(descent).replace('.', '')}`;
    if (live) {
      // TRUE-LIVE reproduction — jump to descent, keep the sim RUNNING, let tickDescent drive the fall
      //   naturally through the re-entry window while we camera-follow the falling pod + capture. This
      //   is the faithful render-loop path (transparent sort, per-frame FX drive) the streak bug lives
      //   in; the paused pin can't reproduce a sort/depth instability. The keepalive forces paused=false
      //   (rig-shot pauses by default) so the RAF beat controller runs.
      await page.evaluate(() => {
        const g = window.__game; const ctx = g.ctx;
        ctx.flags.thirdPerson = false;
        if (ctx.player.rig) ctx.player.rig.group.visible = false;
        if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
        g.startIntro(); g.jumpToBeat('descent');
        ctx.three.renderer.setSize(1000, 760, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 760; cam.updateProjectionMatrix(); }
        // Camera-follow: each RAF re-seat the eye on the falling pod + aim forward at the porthole.
        //   updatePlayer would re-pin the camera to the body; we override AFTER by patching the eye in
        //   a rAF hook. Simpler: a fast interval that un-pauses + re-aims the camera at the pod.
        window.__fxLive = setInterval(() => {
          ctx.flags.paused = false;
          const V = ctx.three.camera.position.constructor;
          const pod = ctx.three.scene.getObjectByName('escapePodCabin');
          if (!pod) return;
          pod.updateMatrixWorld(true);
          const o = pod.getWorldPosition(new V());
          const pb = ctx.player.body;
          const bodyY = o.y + (pb.halfHeight || 0.6) + (pb.radius || 0.3);
          const cam2 = ctx.three.camera;
          cam2.position.set(o.x, bodyY + (ctx.player.eyeOffset || 0.5), o.z + 0.35);
          // FREE-LOOK PAN: slowly sweep the yaw across ±0.5 rad (the player glancing around the cabin
          //   during the fall) so a plasma plane that bleeds when the porthole is OFF-CENTRE is caught.
          const yaw = 0.5 * Math.sin(performance.now() / 900);
          const tgt = new V(o.x - Math.sin(yaw) * 3, cam2.position.y - 0.12, o.z - Math.cos(yaw) * 3);
          cam2.lookAt(tgt);
          cam2.updateMatrixWorld(true);
        }, 30);
      });
      // Capture a burst as the fall runs through the re-entry window (~p0.1→0.4).
      for (let i = 0; i < frames; i++) {
        await page.waitForTimeout(350);
        const st = await page.evaluate(() => {
          const g = window.__game; const ctx = g.ctx;
          const p = ctx.intro && ctx.intro.scratch ? +(((ctx.intro.scratch.t || 0) / 5.6)).toFixed(3) : null;
          return { p };
        });
        await page.screenshot({ path: join(OUT, `${base}-live-f${i}.png`), fullPage: false, animations: 'disabled', timeout: 60000 });
        console.log(`[descent-fx-probe LIVE] frame ${i} (p≈${st.p}) → ${base}-live-f${i}.png`);
      }
      await page.evaluate(() => { if (window.__fxLive) clearInterval(window.__fxLive); });
      return;
    }
    // Build + seat exactly like pod-interior's descent angle, but keep the sim LIVE.
    await page.evaluate((descent) => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      g.startIntro(); g.jumpToBeat('descent');
      ctx.three.renderer.setSize(1000, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 760; cam.updateProjectionMatrix(); }
    }, descent);
    await page.waitForTimeout(700);
    // PAUSE the sim so the live beat controller can't override the descent progress back to p≈0 (it
    //   runs its own tickDescent each RAF). With paused=true nothing re-drives the FX, so WE pin the
    //   re-entry window by re-calling setDescentProgress(descent) right before each capture — uTime
    //   reads performance.now() so the streaks still SCROLL between captures (real time advances even
    //   while paused). This is the faithful re-entry-peak seated read the streak bug lives in.
    const depthInfo = await page.evaluate((descent) => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.paused = true;
      try { g.setDescentProgress(descent); } catch {}
      // Re-anchor the seated eye from the pod group (same as pod-interior).
      const cam = ctx.three.camera; const V = cam.position.constructor;
      const pod = ctx.three.scene.getObjectByName('escapePodCabin');
      let report = { found: !!pod };
      if (pod) {
        pod.updateMatrixWorld(true);
        const o = pod.getWorldPosition(new V());
        const pb = ctx.player.body;
        const bodyY = o.y + (pb.halfHeight || 0.6) + (pb.radius || 0.3);
        const eye = new V(o.x, bodyY + (ctx.player.eyeOffset || 0.5), o.z + 0.35);
        pb.body.setTranslation({ x: o.x, y: bodyY, z: o.z + 0.35 }, true);
        cam.position.copy(eye);
        const pitch = -0.12 - 0.28 * (descent * descent);
        cam.lookAt(new V(eye.x, eye.y + Math.tan(pitch), eye.z - 1));
        cam.updateMatrixWorld(true);
        // Depth-ordering diagnosis: find the porthole glass (inner + outer domes), the reentry plasma
        //   + shimmer meshes; report their world-Z + material flags relative to the seated eye.
        const meshInfo = [];
        pod.traverse((m) => {
          if (!m.isMesh || !m.material) return;
          const mat = m.material;
          const isGlass = mat.transparent && mat.emissive && mat.metalness !== undefined && mat.opacity !== undefined && mat.opacity < 0.5 && !mat.isShaderMaterial;
          if (isGlass) {
            const wp = m.getWorldPosition(new V());
            meshInfo.push({ kind: 'glass', z: +wp.z.toFixed(3), depthWrite: mat.depthWrite, depthTest: mat.depthTest, opacity: mat.opacity, renderOrder: m.renderOrder });
          }
        });
        // The reentry FX live at scene/group level under the pod group; scan by shader uniforms.
        pod.traverse((m) => {
          if (!m.isMesh || !m.material || !m.material.isShaderMaterial) return;
          const u = m.material.uniforms;
          if (u && u.uRe !== undefined) {
            const wp = m.getWorldPosition(new V());
            meshInfo.push({ kind: u.uRe ? 'reentryFX' : 'fx', z: +wp.z.toFixed(3), uRe: u.uRe.value, depthWrite: m.material.depthWrite, depthTest: m.material.depthTest, side: m.material.side, renderOrder: m.renderOrder, visible: m.visible });
          }
        });
        report.eye = [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)];
        report.meshInfo = meshInfo;
      }
      return report;
    }, descent);
    console.log('[descent-fx-probe] depth/mat report: ' + JSON.stringify(depthInfo, null, 0));
    // Capture N frames — re-pin the re-entry window each frame (paused, so nothing else drives it) +
    //   force one render so the FX composite; uTime advances in real time so the streaks scroll.
    for (let i = 0; i < frames; i++) {
      await page.waitForTimeout(260);
      await page.evaluate((descent) => {
        const g = window.__game; const ctx = g.ctx;
        try { g.setDescentProgress(descent); } catch {}
        ctx.three.renderer.render(ctx.three.scene, ctx.three.camera);
      }, descent);
      await page.screenshot({ path: join(OUT, `${base}-f${i}.png`), fullPage: false, animations: 'disabled', timeout: 60000 });
      console.log(`[descent-fx-probe] frame ${i} → ${base}-f${i}.png`);
    }
  },

  // TEXTURE-CRAWL DIAGNOSTIC (additive, 2026-07-06) — reproduce + root-cause the interior-metal
  //   "crawling texture" the user sees ONLY while the pod is DESCENDING, reportedly on the DOOR /
  //   LEVER / CONSOLE but NOT the main walls. Method (rule 8, diagnose-by-reproduction):
  //     (1) Build the pod at the descent beat, seat the camera at the FIXED seated eye. The camera
  //         NEVER moves between motion frames — so any pixel change is the SURFACE, not the view.
  //     (2) Step setDescentProgress across a mid-descent MOTION window (the pod physically
  //         translates ~hundreds of metres). readPixels over probe boxes: DOOR, CONSOLE/LEVER,
  //         WALL, DECK — compute a per-region frame-to-frame RMS delta. Crawl = the affected
  //         regions churn frame-to-frame while the walls stay ~constant.
  //     (3) ISOLATION passes toggle one candidate mechanism at a time + re-measure: freeze the
  //         descent lights, drop the pod's local-Y translation (pure lateral vs vertical),
  //         flat-matte the metal (kill the rusted-hull shader), and snap altitude discretely vs a
  //         moving pod. Whichever pass zeroes the affected delta names the mechanism.
  //   --window=lo,hi motion range (default 0.42,0.74) · --steps=<n> frames (default 8) · captures
  //   scen-crawl-*.png strips for the eye + logs the machine deltas.
  'crawl-probe': async (page) => {
    const win = String(argv.window || '0.42,0.74').split(',').map(Number);
    const steps = Number(argv.steps || 8);
    const [lo, hi] = win;
    // Build + seat exactly like pod-interior's descent angle, then PIN the camera absolutely.
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      g.startIntro(); g.jumpToBeat('descent');
      ctx.three.renderer.setSize(1000, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 760; cam.updateProjectionMatrix(); }
    });
    await page.waitForTimeout(700);   // let the descent init tick build the pod + seat the player
    const fixPitch = !argv.vpitch;   // default: FIXED pitch (isolate crawl); --vpitch = the lived p-pitch
    const midP = (lo + hi) / 2;
    await page.evaluate(({ fixPitch, midP }) => {
      window.__game.ctx.flags.paused = true;
      window.__crawlFixPitch = fixPitch; window.__crawlMidP = midP;
    }, { fixPitch, midP });
    console.log(`[crawl-probe] camera pitch mode: ${fixPitch ? 'FIXED@mid (isolates crawl)' : 'p-dependent (lived view)'}`);

    // Helper injected into the page: seat the FIXED eye relative to the pod ORIGIN, but keep the
    //   eye's OFFSET from the pod origin constant across the motion (so the camera rides the fall
    //   exactly like the seated player — the pod moves under a fixed relative eye; nothing about the
    //   VIEW changes, only the world position of the whole rig). Returns pixel probes.
    const runPass = async (passName, setup, teardown) => {
      // apply the isolation setup once
      await page.evaluate(setup || '(()=>{})');
      const series = [];
      for (let i = 0; i < steps; i++) {
        const p = lo + (hi - lo) * (i / (steps - 1));
        const probe = await page.evaluate((p) => {
          const g = window.__game; const ctx = g.ctx;
          const THREE = g.THREE;
          try { g.setDescentProgress(p); } catch {}
          if (window.__crawlHook) window.__crawlHook(p);   // per-pass per-frame override
          const cam = ctx.three.camera;
          const V = cam.position.constructor;
          const pod = ctx.three.scene.getObjectByName('escapePodCabin');
          pod.updateMatrixWorld(true);
          const o = pod.getWorldPosition(new V());
          // Seated eye: pod origin + the constant seated offset (mirrors pod-interior's derivation).
          const pb = ctx.player.body;
          const eyeY = o.y + (pb.halfHeight || 0.6) + (pb.radius || 0.3) + (ctx.player.eyeOffset || 0.5);
          cam.position.set(o.x, eyeY, o.z + 0.35);
          // Descent look pitch. DEFAULT: FIXED at the window midpoint so the view RELATIVE to the pod
          //   is IDENTICAL across every motion frame — any pixel change is then pure SURFACE crawl, not
          //   view parallax. (--vpitch drives the real p-dependent pitch to also show the lived view.)
          const midP = window.__crawlMidP != null ? window.__crawlMidP : p;
          const useP = window.__crawlFixPitch ? midP : p;
          const pitch = -0.12 - 0.28 * (useP * useP);
          cam.lookAt(o.x, eyeY + Math.tan(pitch), o.z - 1);
          cam.updateMatrixWorld(true);
          ctx.three.renderer.render(ctx.three.scene, ctx.three.camera);
          // Read the framebuffer back. Probe boxes are in CANVAS pixels (1000x760). The seated eye
          //   faces −Z: the porthole/door fills the upper-centre; the console/lever sit lower-RIGHT;
          //   the deck fills the bottom; the curved walls flank left+right at mid height.
          const gl = ctx.three.renderer.getContext();
          const W = ctx.three.renderer.domElement.width, H = ctx.three.renderer.domElement.height;
          const readBox = (x0, y0, x1, y1) => {
            const w = x1 - x0, h = y1 - y0;
            const buf = new Uint8Array(w * h * 4);
            // WebGL readPixels origin is BOTTOM-left; flip the y range.
            gl.readPixels(x0, H - y1, w, h, gl.RGBA, gl.UNSIGNED_BYTE, buf);
            return Array.from(buf);
          };
          return {
            p: +p.toFixed(3), podY: +o.y.toFixed(2),
            door:    readBox(390, 150, 610, 360),   // door slab + porthole ring (upper-centre)
            console: readBox(560, 430, 860, 660),   // console body + lever (lower-right)
            lever:   readBox(600, 470, 720, 640),   // the lever grip/shaft specifically
            wall:    readBox(60, 300, 220, 520),     // left curved wall (the "fixed" control)
            deck:    readBox(360, 640, 640, 750),    // deck plate (bottom)
          };
        }, p);
        series.push(probe);
      }
      await page.evaluate(teardown || '(()=>{})');
      await page.evaluate('window.__crawlHook = null');
      // Frame-to-frame RMS delta per region (ignore fully-black pixels so a void frame doesn't skew).
      const regions = ['door', 'console', 'lever', 'wall', 'deck'];
      const out = { pass: passName, podY: series.map((s) => s.podY) };
      for (const r of regions) {
        let sum = 0, n = 0, peak = 0;
        for (let i = 1; i < series.length; i++) {
          const a = series[i - 1][r], b = series[i][r];
          let f = 0, fn = 0;
          for (let k = 0; k < a.length; k += 4) {
            const d = Math.abs(a[k] - b[k]) + Math.abs(a[k + 1] - b[k + 1]) + Math.abs(a[k + 2] - b[k + 2]);
            f += d * d; fn++;
          }
          const rms = Math.sqrt(f / fn);
          sum += rms; n++; peak = Math.max(peak, rms);
        }
        out[r] = { meanΔ: +(sum / n).toFixed(2), peakΔ: +peak.toFixed(2) };
      }
      return out;
    };

    // ── PASS A: BASELINE — the real descent, nothing altered. Establishes the crawl signature.
    const baseline = await runPass('A-baseline', null, null);
    console.log('[crawl-probe] ' + JSON.stringify(baseline));

    // ── PASS B: FREEZE LIGHTS — pin every descent-driven light to a constant so a moving/ramping
    //   light or shadow can't be the churn. If the affected delta drops → it's lighting, not surface.
    const passB = await runPass('B-frozen-lights',
      `(() => {
        const ctx = window.__game.ctx;
        window.__crawlHook = () => {
          ctx.three.scene.traverse((o) => {
            if (o.isLight) { o.userData.__frzI = o.userData.__frzI ?? o.intensity; o.intensity = o.userData.__frzI;
                             if (o.color) o.color.setRGB(1,1,1); }
          });
        };
      })()`,
      `(() => { window.__game.ctx.three.scene.traverse((o)=>{ if(o.isLight && o.userData.__frzI!==undefined){ o.intensity=o.userData.__frzI; delete o.userData.__frzI; } }); })()`);
    console.log('[crawl-probe] ' + JSON.stringify(passB));

    // ── PASS C: FLAT-MATTE METAL — replace every rusted-hull material's fragment output with the
    //   plain base color (kill the onBeforeCompile weathering + any view-dependent term) on the
    //   DOOR/CONSOLE/LEVER family. If the affected delta drops to the wall level → the churn is in
    //   the metal MATERIAL (shader/spec), pointing at the surface effect. We do this by swapping the
    //   affected meshes to a plain MeshBasicMaterial (no lighting, no shader) captured by name-ish
    //   heuristics: any mesh under the pod whose material is a MeshStandard (glass/metal spec) OR a
    //   Lambert with onBeforeCompile, in the console/lever/door screen-region, is flattened.
    const passC = await runPass('C-flat-matte-metal',
      `(() => {
        const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
        const pod = ctx.three.scene.getObjectByName('escapePodCabin');
        window.__crawlSwaps = [];
        pod.traverse((o) => {
          if (!o.isMesh || !o.material) return;
          const m = o.material;
          // Flatten anything that could carry a view/shader-dependent term: standard mats (spec/metal)
          //   and lambert mats that were patched (onBeforeCompile set). Leave basic/emissive LEDs alone.
          const patched = typeof m.onBeforeCompile === 'function' && m.onBeforeCompile.length > 0;
          if (m.isMeshStandardMaterial || patched) {
            const flat = new THREE.MeshBasicMaterial({ color: (m.color ? m.color.getHex() : 0x808080) });
            window.__crawlSwaps.push([o, m]);
            o.material = flat;
          }
        });
      })()`,
      `(() => { for (const [o, m] of (window.__crawlSwaps || [])) o.material = m; window.__crawlSwaps = []; })()`);
    console.log('[crawl-probe] ' + JSON.stringify(passC));

    // ── PASS D: KILL SPECULAR/METALNESS ONLY — set every MeshStandardMaterial's metalness=0 +
    //   roughness=1 (kills the view-dependent specular lobe) but KEEP the lambert rusted-hull shader.
    //   Isolates spec-aliasing (candidate #2) from the rest of the material.
    const passD = await runPass('D-no-spec',
      `(() => {
        const g = window.__game; const ctx = g.ctx;
        const pod = ctx.three.scene.getObjectByName('escapePodCabin');
        window.__crawlSpec = [];
        pod.traverse((o) => {
          if (!o.isMesh || !o.material || !o.material.isMeshStandardMaterial) return;
          const m = o.material;
          window.__crawlSpec.push([m, m.metalness, m.roughness]);
          m.metalness = 0; m.roughness = 1; m.needsUpdate = true;
        });
      })()`,
      `(() => { for (const [m, met, rgh] of (window.__crawlSpec || [])) { m.metalness = met; m.roughness = rgh; m.needsUpdate = true; } window.__crawlSpec = []; })()`);
    console.log('[crawl-probe] ' + JSON.stringify(passD));

    // ── PASS E: DISCRETE ALTITUDE (no motion) — hold the pod at a SINGLE altitude and re-render the
    //   SAME progress each step (no translation between frames). If the affected delta collapses to
    //   ~0 → the churn is genuinely motion-correlated (confirms it tracks the fall, not RNG/time).
    const passE = await runPass('E-no-motion',
      `(() => { window.__crawlHook = () => { window.__game.setDescentProgress(0.58); }; })()`,
      null);
    console.log('[crawl-probe] ' + JSON.stringify(passE));

    // Summary table for the eye.
    const table = [baseline, passB, passC, passD, passE].map((r) => ({
      pass: r.pass, door: r.door.meanΔ, console: r.console.meanΔ, lever: r.lever.meanΔ, wall: r.wall.meanΔ, deck: r.deck.meanΔ,
    }));
    console.log('[crawl-probe] SUMMARY (meanΔ per region): ' + JSON.stringify(table, null, 0));
  },

  // W6 item 6 — THE SEALED CABIN DOOR must sit FLUSH (not slanted) at every sealed stage. Probes the
  //   cabin hatch pivot's rotation (x,y,z) at descent (sealed), impact (sealed, crashed), and reports
  //   whether any residual tilt exists; then shoots a TRUE head-on porthole-centred frame at descent
  //   so the door slab edges vs the frame can be eyeballed. A non-zero pivot.x/z (or y≠0 when sealed)
  //   = the slant. --descent=<0..1> picks the sealed descent altitude to shoot (default 0.02).
  'door-check': async (page) => {
    const descent = argv.descent !== undefined ? Number(argv.descent) : 0.02;
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      g.startIntro();
      g.jumpToBeat('descent');   // the descent init tick (next RAF) builds + seats the pod
    });
    await page.waitForTimeout(700);   // let the descent init tick build the pod (like pod-interior)
    const probe = await page.evaluate((descent) => {
      const g = window.__game;
      try { g.setDescentProgress(descent); } catch {}
      const atDescent = g.probeCabinDoor();
      // IMPACT (sealed, crashed) — the crash pose tilts the GROUP; the door pivot LOCAL should stay 0.
      try { g.setDescentProgress(1); g.setCabinCrashPose(1); } catch {}
      const atImpact = g.probeCabinDoor();
      // back to the sealed descent pose for the head-on shot
      try { g.setCabinCrashPose(0); g.setDescentProgress(descent); } catch {}
      return { atDescent, atImpact };
    }, descent);
    console.log('[door-check] pivot ' + JSON.stringify(probe));
    // head-on shot: camera at the porthole centre height, dead −Z, close.
    await page.waitForTimeout(300);
    await page.evaluate((descent) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = true;
      try { window.__game.setDescentProgress(descent); } catch {}
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      const pod = ctx.three.scene.getObjectByName('escapePodCabin');
      pod.updateMatrixWorld(true);
      const o = pod.getWorldPosition(new V());
      // VP_CY = 1.34 (porthole centre height above the floor origin); CAB_R front wall at z = o.z − 1.28.
      cam.position.set(o.x, o.y + 1.34, o.z + 0.9);
      cam.lookAt(o.x, o.y + 1.34, o.z - 1.28);
      cam.updateMatrixWorld(true);
      ctx.three.renderer.setSize(900, 900, false);
      if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
    }, descent);
    await page.waitForTimeout(200);
    await page.screenshot({ path: join(OUT, 'scen-door-check.png'), fullPage: false, animations: 'disabled', timeout: 60000 });
    console.log('[door-check] → scen-door-check.png');
  },

  // Hauler (T3.1): the HERO cargo-hauler exterior seen THROUGH the pod porthole at the
  // shipExplode beat — the worn freighter the player just fled, floating in orbit ahead
  // (−Z) about to explode. Builds the pod cabin (so the porthole frames the shot) + the
  // hauler exterior, seats the camera at the seated EYE facing −Z (the real FP-through-
  // porthole view), then shoots that + a couple of framing angles. --angle:
  //   porthole  the FP-through-the-window view (the GATE — the seated eye, −Z)         [default]
  //   wide      a framing angle: the whole hauler in free space (no pod), 3/4
  //   broadside the hauler dead-on broadside (silhouette legibility)
  //   engines   a closer 3/4 on the rear engine cluster (the explosion feature)
  //   nose      a closer 3/4 on the cockpit/bridge
  'hauler': async (page) => {
    const angle = argv.angle || 'porthole';
    // C1 — --depart=<0..1> drives the post-eject DEPARTURE recession (0 = the framed hero pose,
    //   1 = the ship receded/drifted away as the pod pulls clear). For the eject-departure shots.
    const depart = argv.depart !== undefined ? Number(argv.depart) : null;
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      // Build the real pod cabin (porthole frame) via the intro path, then the hauler.
      g.startIntro();
      // enterPod builds the pod cabin + seats the player at the porthole eye (the proven
      // pod-interior path); shipExplode's scripted camera doesn't seat in the pod.
      g.jumpToBeat('enterPod');
      // Reset the descent vista to deep ORBIT (0) so the porthole shows SPACE (the
      // shipExplode beat sits in orbit) — not the low-altitude desert that swells in
      // later. The hauler then reads through the window against the star void.
      try { g.setDescentProgress(0); } catch {}
      g.buildHauler();
      ctx.three.renderer.setSize(1000, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 760; cam.updateProjectionMatrix(); }
    });
    // Let the beat controller tick so the pod builds + the player is seated.
    await page.waitForTimeout(600);
    const meas = await page.evaluate(({ angle, depart }) => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.paused = true;
      try { g.setDescentProgress(0); } catch {}
      // C1 — pose the eject-departure recession (the ship receding in the porthole).
      if (depart !== null) { try { g.setHaulerDeparture(depart); } catch {} }
      // Hide the descent VISTA (orbital planet + atmosphere + its own starfield + the
      // depth-occluder) so the porthole shows the HAULER against ITS star backdrop. The
      // vista meshes use ShaderMaterials or the starOccluder flag; the cabin structure
      // uses Lambert/rusted-hull mats. Done HERE (after the pod has built on a tick).
      const cabin0 = ctx.three.scene.getObjectByName('escapePodCabin');
      if (cabin0) cabin0.traverse((o) => {
        if (!o.isMesh) return;
        const m = o.material;
        if ((m && m.isShaderMaterial) || (o.userData && o.userData.starOccluder)) o.visible = false;
      });
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      // Locate the hauler centre (world) so the framing angles can orbit it.
      const hauler = ctx.three.scene.getObjectByName('escapePodHauler');
      let hc = null;
      if (hauler) { hauler.updateMatrixWorld(true); hc = new V(); hauler.getWorldPosition(hc); }
      if (angle === 'porthole') {
        // THE GATE: the seated EYE world position, looking straight out −Z (the porthole).
        const tr = ctx.player.body.body.translation();
        const eye = new V(tr.x, tr.y + (ctx.player.eyeOffset || 0.6), tr.z);
        cam.position.copy(eye);
        cam.lookAt(eye.x, eye.y - 0.05, eye.z - 1);
      } else if (hc) {
        // Free-space framing angles (the studio diagnostic — additional, not the verdict).
        // Hide the pod cabin so it doesn't block the external read.
        const cabin = ctx.three.scene.getObjectByName('escapePodCabin');
        if (cabin) cabin.visible = false;
        // The ship's local axes in WORLD space (so framing angles track the yaw).
        const Q = cam.quaternion.constructor;
        const hq = hauler.getWorldQuaternion(new Q());
        const axX = new V(1, 0, 0).applyQuaternion(hq);   // ship NOSE direction (local +X)
        const axZ = new V(0, 0, 1).applyQuaternion(hq);   // ship broadside flank (local +Z)
        if (angle === 'broadside') {
          cam.position.set(hc.x, hc.y + 1.0, hc.z + 15);
          cam.lookAt(hc.x, hc.y, hc.z);
        } else if (angle === 'engines') {
          // off the TAIL (−X) end + the camera-side flank → the flared nozzles read.
          const e = new V(hc.x - axX.x * 9 + axZ.x * 6, hc.y + 2.5, hc.z - axX.z * 9 + axZ.z * 6);
          cam.position.copy(e);
          cam.lookAt(hc.x - axX.x * 6, hc.y, hc.z - axX.z * 6);
        } else if (angle === 'nose') {
          // off the NOSE (+X) end + the camera-side flank → the cockpit/windscreen reads.
          const n = new V(hc.x + axX.x * 9 + axZ.x * 6, hc.y + 2, hc.z + axX.z * 9 + axZ.z * 6);
          cam.position.copy(n);
          cam.lookAt(hc.x + axX.x * 6, hc.y + 0.5, hc.z + axX.z * 6);
        } else { // wide 3/4
          cam.position.set(hc.x + 11, hc.y + 5, hc.z + 15);
          cam.lookAt(hc.x, hc.y, hc.z);
        }
      }
      cam.updateMatrixWorld(true);
      let meshes = 0;
      if (hauler) hauler.traverse((o) => { if (o.isMesh) meshes++; });
      // DIAGNOSTIC: where is the camera, where is the hauler, what's the descent state?
      const cabin = ctx.three.scene.getObjectByName('escapePodCabin');
      let lowAltVis = null, planetVis = null;
      if (cabin) cabin.traverse((o) => {
        if (o.material && o.material.uniforms && o.material.uniforms.uLowAlt) lowAltVis = { vis: o.visible, lowAlt: o.material.uniforms.uLowAlt.value };
      });
      console.error('[hauler-diag] camPos=' + [cam.position.x, cam.position.y, cam.position.z].map((v) => +v.toFixed(1)).join(',') +
        ' haulerPos=' + (hc ? [hc.x, hc.y, hc.z].map((v) => +v.toFixed(1)).join(',') : 'null') +
        ' cabin=' + !!cabin + ' lowAlt=' + JSON.stringify(lowAltVis));
      return { found: !!hauler, meshes, angle };
    }, { angle, depart });
    await page.waitForTimeout(300);
    const deptag = depart !== null ? `-depart${String(depart).replace('.', '')}` : '';
    await page.screenshot({ path: join(OUT, `scen-hauler-${angle}${deptag}.png`), fullPage: false });
    console.log(`[hauler] ${JSON.stringify(meas)} → scen-hauler-${angle}${deptag}.png`);
  },

  // Ship-explode (T3.2): THE CLIMACTIC SPECTACLE — the player watches their hauler DIE
  // through the porthole. Builds the pod cabin (porthole frame) + the hauler, drives the
  // explosion FX to a chosen moment (--t=<0..1> into the blast; default 0.22 = mid-fireball),
  // and shoots the REAL seated FP-through-the-window view (−Z). --view=free renders a free
  // 3/4 angle on the exploding ship instead (the studio diagnostic). --strip captures a
  // sequence of moments (0.03 flash → 0.15 fireball → 0.35 breakup → 0.7 husk) in one boot.
  'ship-explode': async (page) => {
    const view = argv.view || 'porthole';
    const t = argv.t !== undefined ? Number(argv.t) : 0.22;
    const strip = !!argv.strip;
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      // Build the real pod cabin at the ORBIT frame + seat the player at the porthole eye,
      // then the hauler. (buildPodOrbit builds+seats deterministically — the enterPod beat
      // stalls in its walk-up phase in a headless boot, never sealing the cabin.)
      g.startIntro();
      g.jumpToBeat('shipExplode');   // the real beat context (mode seated, faces −Z)
      g.buildPodOrbit();             // build + seat the pod cabin at orbit (porthole eye)
      try { g.setDescentProgress(0); } catch {}   // orbital vista through the window
      g.buildHauler();
      ctx.three.renderer.setSize(1000, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 760; cam.updateProjectionMatrix(); }
    });
    await page.waitForTimeout(600);   // let the pod cabin build + seat on a tick
    // Frame + drive-explosion + shoot. `moments` is a list of (tag, explosionT) — one for a
    // single shot, or the strip preset.
    const moments = strip
      ? [['f00-flash', 0.03], ['f01-bloom', 0.13], ['f02-fireball', 0.24], ['f03-breakup', 0.42], ['f04-husk', 0.72]]
      : [[`t${String(t).replace('.', '')}`, t]];
    for (const [tag, et] of moments) {
      const meas = await page.evaluate(({ view, et }) => {
        const g = window.__game;
        const ctx = g.ctx;
        ctx.flags.paused = true;
        try { g.setDescentProgress(0); } catch {}
        try { g.setHaulerExplosion(et); } catch {}
        const cam = ctx.three.camera;
        const V = cam.position.constructor;
        // Hide any cabin ShaderMaterial meshes (the re-entry plasma/shimmer — invisible at
        // descent=0 anyway) so nothing layers over the porthole read (matches the hauler scenario).
        const cabin = ctx.three.scene.getObjectByName('escapePodCabin');
        if (cabin) cabin.traverse((o) => {
          if (!o.isMesh) return;
          const m = o.material;
          if ((m && m.isShaderMaterial) || (o.userData && o.userData.starOccluder)) o.visible = false;
        });
        // Full-intro coherence fix mirror: this beat sits in full orbit (descent=0, space01=1) —
        // dim the world sun+ambient so the paused rig shows the vacuum-lit cabin (not the pale
        // noon-flooded one). Matches sky.ts applySpaceMode (sun ×0.12, ambient ×0.06 at s=1).
        // X2a gate post-mortem: the old one-shot `*=` compounded across strip re-evaluates AND
        // could be re-derived back to noon by a live lighting tick before the capture (the false
        // PALE frame). Idempotent SET from a stashed base; re-applied again just before capture.
        if (ctx.lights) {
          if (window.__rigSpaceBase === undefined) window.__rigSpaceBase = { sun: ctx.lights.sun.intensity, amb: ctx.lights.ambient.intensity };
          ctx.lights.sun.intensity = window.__rigSpaceBase.sun * 0.12;
          ctx.lights.ambient.intensity = window.__rigSpaceBase.amb * 0.06;
        }
        const hauler = ctx.three.scene.getObjectByName('escapePodHauler');
        let hc = null;
        if (hauler) { hauler.updateMatrixWorld(true); hc = new V(); hauler.getWorldPosition(hc); }
        if (view === 'porthole') {
          // THE GATE: the seated EYE world pos (derived from the cabin group), looking −Z.
          let eye;
          const pod0 = ctx.three.scene.getObjectByName('escapePodCabin');
          if (pod0) {
            pod0.updateMatrixWorld(true);
            const o = pod0.getWorldPosition(new V());
            const pb = ctx.player.body;
            const bodyY = o.y + (pb.halfHeight || 0.6) + (pb.radius || 0.3);
            eye = new V(o.x, bodyY + (ctx.player.eyeOffset || 0.5), o.z + 0.35);
          } else {
            const tr = ctx.player.body.body.translation();
            eye = new V(tr.x, tr.y + (ctx.player.eyeOffset || 0.5), tr.z);
          }
          cam.position.copy(eye);
          cam.lookAt(eye.x, eye.y - 0.05, eye.z - 1);
        } else if (hc) {
          // FREE 3/4 on the exploding ship (studio diagnostic — hide the cabin).
          if (cabin) cabin.visible = false;
          cam.position.set(hc.x + 12, hc.y + 6, hc.z + 17);
          cam.lookAt(hc.x, hc.y, hc.z);
        }
        cam.updateMatrixWorld(true);
        return { view, et, hauler: !!hauler };
      }, { view, et });
      await page.waitForTimeout(250);
      // Re-assert the vacuum dim AFTER the settle wait — a live lighting tick during the wait
      // re-derives noon sun/ambient and produced the false PALE cabin frame (X2a flag).
      await page.evaluate(() => {
        const ctx = window.__game.ctx;
        if (ctx.lights && window.__rigSpaceBase !== undefined) {
          ctx.lights.sun.intensity = window.__rigSpaceBase.sun * 0.12;
          ctx.lights.ambient.intensity = window.__rigSpaceBase.amb * 0.06;
        }
      });
      const fname = strip ? `scen-ship-explode-${tag}.png` : `scen-ship-explode-${view}-${tag}.png`;
      await page.screenshot({ path: join(OUT, fname), fullPage: false });
      console.log(`[ship-explode] ${JSON.stringify(meas)} → ${fname}`);
    }
  },

  // W1 COLLIDER ENUM (item 7 diagnosis) — list every collider whose AABB sits in the cockpit box,
  //   flagging those AFT of the seat (z_local > 0) that could box the player in. No shot.
  'cockpit-colliders': async (page) => {
    const out = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const realClock = ctx.three.clock; realClock.getDelta = () => 0.05;
      ctx.three.renderer.setSize(48, 48, false);
      try { g.skipIntro(); } catch {}
      for (let i = 0; i < 40; i++) { await sleep(16); if (!ctx.intro || !ctx.intro.active) break; }
      g.startIntro();
      for (let a = 0; a < 20; a++) { g.jumpToBeat('cockpit'); for (let i = 0; i < 30; i++) { await sleep(16); if (ctx.player.body.body.translation().y > 2900) break; } if (ctx.player.body.body.translation().y > 2900) break; }
      const sp = ctx.player.body.body.translation();
      const ORIGIN = { x: sp.x, y: sp.y - (ctx.player.body.halfHeight + ctx.player.body.radius) - 0.85, z: sp.z + 0.30 };  // approx ship origin (seat z_local=-0.30)
      const world = ctx.physics.world;
      const hits = [];
      world.forEachCollider((col) => {
        const t = col.translation();
        // local to ship origin
        const lx = t.x - sp.x, ly = t.y, lz = t.z - (sp.z + 0.30);
        // only near the cockpit (|lx|<4, |lz|<4, world y near ship origin ~3000)
        if (Math.abs(lx) < 4 && Math.abs(lz) < 4 && ty(t.y)) {
          let half = null;
          try { const s = col.halfExtents ? col.halfExtents() : null; if (s) half = [ +s.x.toFixed(2), +s.y.toFixed(2), +s.z.toFixed(2) ]; } catch {}
          hits.push({ lx: +lx.toFixed(2), lz: +lz.toFixed(2), wy: +t.y.toFixed(1), half, aftOfSeat: lz > -0.15 && Math.abs(lx) < 0.9 });
        }
        function ty(y) { return y > 2990 && y < 3010; }
      });
      const aft = hits.filter((h) => h.aftOfSeat);
      return { total: hits.length, aftOfSeat: aft, all: hits };
    });
    console.log('[cockpit-colliders] total=' + out.total + ' aftOfSeat=' + out.aftOfSeat.length);
    for (const h of out.aftOfSeat) console.log('[cockpit-colliders][AFT] ' + JSON.stringify(h));
    for (const h of out.all) console.log('[cockpit-colliders] ' + JSON.stringify(h));
  },

  // W1 COCKPIT MOTION PROBE (item 7 — "remove the chair collider + the invisible collider behind
  //   the chair; I want to walk the cockpit freely"). The B1.f real-KCC motion proof: seat the
  //   player at getShipSpawn, then drive REAL WASD in each direction (aft / left / right / fwd) and
  //   report the max body displacement. A FREE cockpit = large Δ aft + strafe (no wall boxing the
  //   seat). No screenshot — a motion assertion (like pod-walkin). Pins a FIXED dt so it's
  //   throttle-proof under the ~1 fps headless tab.
  // GLASS-SEAL CONTAINMENT PROBE (LIVE-fix 2026-07-05) — the cockpit-motion gate passed while a
  //   walk-through-glass hole existed at the SIDE closures (it only tests 4 cardinal legs + 5 roam
  //   targets, none of which push straight OUT through a closure pane). This probe is strictly
  //   stronger: from the cabin walk centre it walks OUTWARD at 12 azimuths (30° steps) and asserts the
  //   KCC is CONTAINED at EVERY azimuth (never escapes past the dome sill radius). PASS = the max
  //   outward radius reached at every azimuth stays inside the glass line + a small margin.
  //   node scripts/rig-shot.mjs --scenario=cockpit-glass-seal --port=5192
  'cockpit-glass-seal': async (page) => {
    const out = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      const realClock = ctx.three.clock; const FIXED_DT = 0.05;
      realClock.getDelta = () => FIXED_DT;
      ctx.three.renderer.setSize(48, 48, false);
      const drive = async (simBudget, perTick) => {
        const s0 = ctx.time.elapsed; let last = s0, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          if (perTick) perTick();
          await sleep(16);
          const now = ctx.time.elapsed;
          if (now > last + 1e-6) { last = now; stalls = 0; } else if (++stalls > 600) break;
          if (now - s0 >= simBudget) break;
        }
      };
      try { g.skipIntro(); } catch {}
      await drive(0.2);
      g.startIntro();
      for (let a = 0; a < 20; a++) { g.jumpToBeat('cockpit'); await drive(0.3); if (ctx.player.body.body.translation().y > 2900) break; }
      try { g.setSkyIntroMode(0); } catch {}
      ctx.flags.paused = false;
      ctx.input.controls.isLocked = true;
      const cam = ctx.three.camera; cam.rotation.order = 'YXZ';
      const clearKeys = () => { for (const k of ['KeyW', 'KeyS', 'KeyA', 'KeyD']) ctx.input.keys[k] = false; };
      const origin = () => ctx.player.body.body.translation();
      const s0 = origin(); const SEAT = { x: s0.x, y: s0.y, z: s0.z };
      // walk-centre: a hair aft of the seat (mid cabin) so all 12 outward pushes start from one interior point.
      const CX = SEAT.x, CZ = SEAT.z + 0.4;
      // the dome sill radius envelope (ship-local): the glass line the player must NOT cross. Front reach
      //   (−Z) is far (nose ≈ z−2.25); the sides ≈ x±2.08; we compute the outward distance from the walk
      //   centre to the sill footprint at each azimuth and assert the body stays inside it + a KCC margin.
      const results = [];
      const STEPS = 12;
      for (let s = 0; s < STEPS; s++) {
        const yaw = (s / STEPS) * Math.PI * 2;      // 0..2π (0 = −Z forward under YXZ fwd = (−sinθ,0,−cosθ))
        clearKeys();
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.player.eyeOffset = 0.85; }
        ctx.player.body.body.setTranslation({ x: CX, y: SEAT.y, z: CZ }, true);
        await drive(0.2);
        // push OUTWARD along this azimuth for a good while (try hard to escape the canopy).
        await drive(2.6, () => { cam.rotation.set(0, yaw, 0); ctx.input.keys['KeyW'] = true; });
        clearKeys();
        const p = origin();
        const rx = p.x - CX, rz = p.z - CZ;
        const r = Math.hypot(rx, rz);
        // forward dir under YXZ at this yaw:
        const fx = -Math.sin(yaw), fz = -Math.cos(yaw);
        results.push({ deg: Math.round((yaw * 180) / Math.PI), r: +r.toFixed(2), at: [+rx.toFixed(2), +rz.toFixed(2)], fwd: [+fx.toFixed(2), +fz.toFixed(2)] });
      }
      let dbg = null;
      try {
        const w = ctx.physics.world; const bodyY = SEAT.y; const near = [];
        w.forEachCollider((c) => {
          const t = c.translation();
          // dome ring colliders: ship-local x<−1.5 AND ship-local z in [−2.5, 0.6] (the forward glass band)
          const lz = t.z - CZ + 0.1, lx = t.x - CX;
          if (Math.abs(t.y - bodyY) < 3 && lx < -1.5 && lz < 0.6 && lz > -2.6) near.push({ x: +lx.toFixed(2), y: +(t.y - bodyY).toFixed(2), z: +(t.z - CZ).toFixed(2), hx: +(c.halfExtents ? c.halfExtents().x : -1).toFixed(2), hy: +(c.halfExtents ? c.halfExtents().y : -1).toFixed(2) });
        });
        dbg = { bodyY: +bodyY.toFixed(2), domeLeftColliders: near.length, sample: near };
      } catch (e) { dbg = { err: String(e) }; }
      return { results, centre: [+CX.toFixed(2), +CZ.toFixed(2)], dbg };
    });
    console.log('[cockpit-glass-seal][dbg] ' + JSON.stringify(out.dbg));
    // Containment check — classify by the FINAL body position (ship-local, relative to the walk centre
    //   at [0, +0.4]-ish; the probe reports `at` = [dx, dz] from centre). A GLASS BREACH = the body
    //   ended OUTSIDE the canopy envelope: to the SIDE (|dx| > 2.2 while not deep aft) or FORWARD past
    //   the nose (dz < −2.5). The AFT DOORWAY (the corridor, |dx|<1.2 and dz large positive) is a
    //   DESIGNED opening → NOT a breach; the aft-corner reaches (dz≈+2, |dx|≈2.4 at the door jamb/quarters
    //   region) are inside the ship, also not glass. This is what makes the probe strictly stronger than
    //   cockpit-motion (which counted any long walk as "free").
    const CZ0 = out.centre[1];   // walk-centre z (ship-local), so world dz = at[1]; absolute z = CZ0+at[1]
    const isGlassBreach = (r) => {
      const dx = r.at[0], dz = r.at[1];
      const zAbs = CZ0 + dz;
      const sideBreach = Math.abs(dx) > 2.2 && zAbs < 1.5;      // walked out a side/forward closure into space
      const noseBreach = zAbs < -2.5;                            // walked out the forward nose glazing
      return sideBreach || noseBreach;
    };
    const breaches = out.results.filter(isGlassBreach);
    const maxR = Math.max(...out.results.map((r) => r.r));
    const pass = breaches.length === 0;
    console.log('[cockpit-glass-seal] ' + (pass ? 'PASS' : 'FAIL') + ' glassBreaches=' + breaches.length + ' maxR=' + maxR.toFixed(2) + ' centre=' + JSON.stringify(out.centre));
    console.log('[cockpit-glass-seal][azimuths] ' + JSON.stringify(out.results.map((r) => ({ [r.deg]: '[' + r.at[0] + ',' + r.at[1] + ']' }))));
    if (breaches.length) console.log('[cockpit-glass-seal][BREACH] ' + JSON.stringify(breaches));
  },

  'cockpit-motion': async (page) => {
    const out = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      const realClock = ctx.three.clock; const FIXED_DT = 0.05;
      realClock.getDelta = () => FIXED_DT;
      ctx.three.renderer.setSize(48, 48, false);
      const drive = async (simBudget, perTick) => {
        const s0 = ctx.time.elapsed; let last = s0, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          if (perTick) perTick();
          await sleep(16);
          const now = ctx.time.elapsed;
          if (now > last + 1e-6) { last = now; stalls = 0; } else if (++stalls > 600) break;
          if (now - s0 >= simBudget) break;
        }
      };
      try { g.skipIntro(); } catch {}
      await drive(0.2);
      g.startIntro();
      for (let a = 0; a < 20; a++) { g.jumpToBeat('cockpit'); await drive(0.3); if (ctx.player.body.body.translation().y > 2900) break; }
      try { g.setSkyIntroMode(0); } catch {}
      ctx.flags.paused = false;
      ctx.input.controls.isLocked = true;   // isPlaying() → real KCC motion processed
      const cam = ctx.three.camera; cam.rotation.order = 'YXZ';
      const clearKeys = () => { for (const k of ['KeyW', 'KeyS', 'KeyA', 'KeyD']) ctx.input.keys[k] = false; };
      const origin = () => ctx.player.body.body.translation();
      // capture the SEAT as the seated spawn position (the body is at getShipSpawn right after the jump)
      const s0 = origin(); const SEAT = { x: s0.x, y: s0.y, z: s0.z };
      const reseat = () => ctx.player.body.body.setTranslation({ x: SEAT.x, y: SEAT.y, z: SEAT.z }, true);
      const runLeg = async (label, yaw, key) => {
        clearKeys(); reseat();
        // force WALK mode + standing eye (the cockpit opening is SEATED by design → locomotion off;
        //   "walk the cockpit freely" is the walk-enabled state — that's what item 7 tests).
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.player.eyeOffset = 0.85; }
        await drive(0.2);
        const start = origin(); const p0 = { x: start.x, z: start.z };
        await drive(2.2, () => { cam.rotation.set(0, yaw, 0); ctx.input.keys[key] = true; });
        clearKeys();
        const p1 = origin();
        const d = Math.hypot(p1.x - p0.x, p1.z - p0.z);
        const dir = ctx.three.camera.getWorldDirection(new (ctx.three.camera.position.constructor)());
        return { label, dx: +(p1.x - p0.x).toFixed(2), dz: +(p1.z - p0.z).toFixed(2), d: +d.toFixed(2),
                 camY: +ctx.three.camera.rotation.y.toFixed(2), fwd: [+dir.x.toFixed(2), +dir.z.toFixed(2)],
                 introActive: !!(ctx.intro && ctx.intro.active), mode: ctx.intro && ctx.intro.mode, eyeOff: +(ctx.player.eyeOffset||0).toFixed(2) };
      };
      const legs = [];
      // KeyW drives ALONG the camera-forward; yaw π → aft(+Z, the door egress), −π/2 → −X, +π/2 → +X, 0 → fwd(−Z)
      legs.push(await runLeg('aft(+Z)', Math.PI, 'KeyW'));
      legs.push(await runLeg('left(−X)', -Math.PI / 2, 'KeyW'));
      legs.push(await runLeg('right(+X)', Math.PI / 2, 'KeyW'));
      legs.push(await runLeg('fwd(−Z)', 0, 'KeyW'));
      // ── WHOLE-COCKPIT ROAM (coordinator: prove the whole floor, not just the egress lane). Place
      //    the body at each aisle spot + walk TOWARD a target corner; report how close it reaches.
      //    ORIGIN.z = SEAT.z + 0.30. Walkable band ≈ |x|<1.9, z ∈ (−1.0 .. 2.2).
      const OZ = SEAT.z + 0.30;
      const roam = [];
      const roamTo = async (label, from, target) => {
        clearKeys();
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.player.eyeOffset = 0.85; }
        ctx.player.body.body.setTranslation({ x: SEAT.x + from.x, y: SEAT.y, z: OZ + from.z }, true);
        await drive(0.2);
        const yawTo = Math.atan2(-(target.x - from.x), -(target.z - from.z));   // face the target (YXZ fwd = (−sinθ,0,−cosθ))
        await drive(2.0, () => { cam.rotation.set(0, yawTo, 0); ctx.input.keys['KeyW'] = true; });
        clearKeys();
        const p = origin();
        const reached = Math.hypot((p.x - SEAT.x) - target.x, (p.z - OZ) - target.z);
        return { label, at: [+(p.x - SEAT.x).toFixed(2), +(p.z - OZ).toFixed(2)], distToTarget: +reached.toFixed(2) };
      };
      roam.push(await roamTo('fwd-L (beside console)', { x: -1.4, z: -0.6 }, { x: -1.6, z: -1.1 }));
      roam.push(await roamTo('fwd-R (beside console)', { x: 1.4, z: -0.6 }, { x: 1.6, z: -1.1 }));
      roam.push(await roamTo('wall-L (mid)', { x: 0, z: 0.4 }, { x: -1.8, z: 0.4 }));
      roam.push(await roamTo('wall-R (mid)', { x: 0, z: 0.4 }, { x: 1.8, z: 0.4 }));
      roam.push(await roamTo('aft-door', { x: 0, z: 1.0 }, { x: 0, z: 2.3 }));
      return { legs, roam, seat: [+SEAT.x.toFixed(2), +SEAT.y.toFixed(2), +SEAT.z.toFixed(2)] };
    });
    const freeDirs = out.legs.filter((l) => l.d >= 0.8).length;
    // roam OK = each target reached within a capsule-radius standoff (~0.55) OR the body walked PAST
    //   it (overshoot past a wall-clear target = even freer). The aft-door target is a pass-through.
    const roamOk = out.roam.every((r) => {
      if (r.label === 'aft-door') return r.at[1] >= 2.0;          // walked to/through the door mouth
      return r.distToTarget <= 0.6 || Math.abs(r.at[0]) >= Math.abs(1.6);   // reached the corner or the wall standoff
    });
    const pass = freeDirs >= 3 && out.legs.find((l) => l.label === 'aft(+Z)').d >= 0.8 && roamOk;
    console.log('[cockpit-motion] ' + (pass ? 'PASS' : 'FAIL') + ' freeDirs=' + freeDirs + ' roamOk=' + roamOk);
    console.log('[cockpit-motion][legs] ' + JSON.stringify(out.legs.map((l) => ({ [l.label]: l.d }))));
    console.log('[cockpit-motion][roam] ' + JSON.stringify(out.roam));
  },

  // Cockpit (T3.3): the GAME'S OPENING SHOT — the REAL seated first-person view inside the
  // HERO single-pilot cockpit. Drives the game's OWN intro path (startIntro → jumpToBeat
  // 'cockpit') so the beat machine builds the ship + seats the player at getShipSpawn facing
  // −Z (looking out the forward window at the orbit view) — NOT an idealized studio rig.
  //   --angle: forward (Beat-0 seated, out the window)   [default]
  //            console (look down-forward at the dash/screens)
  //            door    (stood + turned aft to the corridor doorway — the "check engines" exit)
  //            left/right (head-turned reads of the side walls / clutter)
  //            wide    (head-turned 3/4 of the whole bridge)
  //   --stand draws the standing eye (rise + walk read) instead of the seated eye.
  //   --alert=<0|1|2> drives the cockpit alert state (verify the escalation surface).
  'cockpit': async (page) => {
    const angle = argv.angle || 'forward';
    const stand = !!argv.stand;
    const colliders = !!argv.colliders;   // A1 evidence — overlay the Rapier collider wireframe on the hull
    const alert = argv.alert !== undefined ? Number(argv.alert) : 0;
    const space = argv.space !== undefined ? Number(argv.space === true ? 1 : argv.space) : 0; // REBUILD v2 R1a — --space[=0..1] drives the orbit sky
    const hideStars = !!argv.hidestars;
    const noPlanet = !!argv.noplanet;
    const noGlass = !!argv.noglass;
    const noDome = !!argv.nodome;
    const noHull = !!argv.nohull;
    await page.evaluate(({ space, hideStars, noPlanet, noGlass, noDome, noHull }) => {
      window.__RIG_SPACE01 = space;
      window.__RIG_HIDESTARS = hideStars;
      window.__RIG_NOPLANET = noPlanet;
      window.__RIG_NOGLASS = noGlass;
      window.__RIG_NODOME = noDome;
      window.__RIG_NOHULL = noHull;
      const g = window.__game;
      const ctx = g.ctx;
      // First-person seated read; hide the rig so it doesn't block the FP camera.
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      // KILL the weather (the rain/dust streaks read as a dirty-lens filter over the cockpit
      // — they are world atmosphere, not the cabin) + a touch of warm exposure for the mood.
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      try { ctx.three.renderer.toneMappingExposure = 1.08; } catch {}
      // Drive the real intro: start it (force) + jump to the cockpit beat → the beat
      // controller builds the ship + seats the player facing −Z (the genuine FP frame).
      g.startIntro();
      g.jumpToBeat('cockpit');
      // REBUILD v2 R1a — drive the real sky into space mode so the window reads as orbit.
      if (space > 0) {
        try { g.setSkyIntroMode(space); } catch {}
        // Vacuum cabin has no floating dust — suppress the camera-anchored mote/dust
        // layers (these are atmospheric, not orbital). The space BEATS must do the same
        // (coordinator handoff); here we mirror that so the sky read is clean.
        try { if (ctx.dustMotes) ctx.dustMotes.particles.visible = false; } catch {}
        try { if (ctx.ambientDust) ctx.ambientDust.particles.visible = false; } catch {}
        try { for (const k of ['near', 'mid', 'far']) { const L = ctx.weather.layers && ctx.weather.layers[k]; if (L && L.particles) L.particles.visible = false; } } catch {}
      } else { try { g.setSkyIntroMode(0); } catch {} }   // control: prove space-mode off = normal sky
      ctx.three.renderer.setSize(1100, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 760; cam.updateProjectionMatrix(); }
    }, { space, hideStars, noPlanet, noGlass, noDome, noHull });
    // Let the beat controller tick (page RAF) so the ship builds + the player seats.
    await page.waitForTimeout(700);
    // --eye=dx,dy,dz --look=lx,ly,lz — a free camera override in SHIP-LOCAL coords (offsets from the
    //   spawn XZ / ship floor). Lets a fix-agent shoot arbitrary STANDING / WALKING / CROUCHED vantages
    //   around the glass perimeter that the fixed seated/stand poses can't reach (the C63 vantage lesson).
    const eyeOv = argv.eye ? String(argv.eye).split(',').map(Number) : null;
    const lookOv = argv.look ? String(argv.look).split(',').map(Number) : null;
    const meas = await page.evaluate(({ angle, stand, alert, colliders, eyeOv, lookOv }) => {
      const g = window.__game;
      const ctx = g.ctx;
      if (alert > 0) { try { g.setCockpitAlert(alert); } catch {} }
      // A1 EVIDENCE — overlay the Rapier collider wireframe (bright green LineSegments, depthTest off)
      //   so the shot shows the collider surface OVER the visible hull skin. The COCKPIT colliders are
      //   at world y≈3000 (SHIP_ORIGIN.y), so they render right on the cockpit hull. `three` is reached
      //   via a dynamic import (Vite serves the module); the overlay is finished in an async step below.
      if (colliders) { window.__RIG_WANT_COLLIDERS = true; }
      // REBUILD v2 R1a debug — --hidestars proves whether the top speckles are the
      // real star sphere (set the env via argv passthrough below).
      if (window.__RIG_HIDESTARS) {
        ctx.three.scene.traverse((o) => { if (o.isPoints && o.renderOrder === -0.5) o.visible = false; });
      }
      if (window.__RIG_NOPLANET) { ctx.three.scene.traverse((o)=>{ if(o.isMesh && (o.renderOrder===-0.4||o.renderOrder===-0.39||o.renderOrder===-0.41)) o.visible=false; }); }   // -0.41 = the SEV2 depth-occluder shell (sky.ts) — hide it with the planet or --noplanet leaves an invisible star-blocking disc
      // --noglass: hide the windscreen glass + smudge + streak overlays (transparent meshes near the
      // -Z window plane) to see the RAW background behind the window.
      if (window.__RIG_NOGLASS) {
        const ship = ctx.three.scene.getObjectByName('escapePodShipCockpit');
        if (ship) ship.traverse((o) => {
          if (o.isMesh && o.material && o.material.transparent && o.position.z < -1.8) o.visible = false;
        });
      }
      // --nodome: hide the sky dome sphere (the big uTopColor mesh) so we can tell if the tan is the sky.
      if (window.__RIG_NODOME) {
        ctx.three.scene.traverse((o) => { if (o.isMesh && o.material && o.material.uniforms && o.material.uniforms.uTopColor) o.visible = false; });
      }
      // --nohull: hide every ship mesh FORWARD of the eye (world z<2998.7) to strip whatever fills the window.
      if (window.__RIG_NOHULL) {
        const ship = ctx.three.scene.getObjectByName('escapePodShipCockpit');
        const hidden = {};
        if (ship) ship.traverse((o) => {
          if (o.isMesh && o.visible) {
            const wp = o.getWorldPosition(new (ctx.three.camera.position.constructor)());
            if (wp.z < 2998.7) { o.visible = false; const k=(o.material&&o.material.name)||(o.geometry&&o.geometry.type)||'?'; hidden[k]=(hidden[k]||0)+1; }
          }
        });
        console.error('[nohull] hid ' + JSON.stringify(hidden));
      }
      ctx.flags.paused = true;
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      // Keep the framed aspect for THIS shot (other scenarios may have left a stale size).
      ctx.three.renderer.setSize(1100, 760, false);
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 760; cam.updateProjectionMatrix(); }
      // The SEATED PILOT eye: LOW + leaned back into the seat (a pilot sits low at the
      // controls). The spawn is the forward pilot station; the seated pose lowers the eye to
      // ~1.15m above the floor (this mirrors the in-game seated pose sequence.ts will wire —
      // see the agent's hand-back note). For "stand", raise to a standing eye + step aft.
      const tr = ctx.player.body.body.translation();
      const floorY = tr.y - (ctx.player.body.halfHeight + ctx.player.body.radius); // ship floor world-y
      if (angle === 'wide') {
        // The WIDE 3/4 is NOT a seated-eye shot — it must SHOW the seat + station, so park the
        // camera up + WELL behind the pilot's right shoulder (near the aft wall), looking
        // forward-down over the whole chair at the dash + window (the chair clearly in frame).
        const sx = tr.x + 1.3, sy = floorY + 2.05, sz = tr.z + 2.0;
        cam.position.set(sx, sy, sz);
        cam.lookAt(tr.x - 0.25, floorY + 0.7, tr.z - 1.4);
        cam.updateMatrixWorld(true);
        const ship0 = ctx.three.scene.getObjectByName('escapePodShipCockpit');
        let m0 = 0; if (ship0) ship0.traverse((o) => { if (o.isMesh) m0++; });
        return { found: !!ship0, meshes: m0, eye: [+sx.toFixed(2), +sy.toFixed(2), +sz.toFixed(2)], alert };
      }
      // The SEATED PILOT eye = the REAL in-game seated eye: body-centre + the seated eye
      // offset (POD_SEATED_EYE_OFFSET 0.50 → floor + 0.85 + 0.50 = floor+1.35). This is the
      // genuine Beat-0 frame the player sees (NOT a fabricated viewpoint). For "stand", raise
      // to a standing eye + step aft (the rise + walk-to-the-door read).
      const seatedEye = (ctx.player.eyeOffset || 0.5);   // the controller sets this to the seated offset in intro
      const eyeY = stand ? floorY + 1.62 : (tr.y + seatedEye);
      const eyeZ = tr.z + (stand ? -0.1 : 0.1);   // seated: a hair back into the seat
      const eye = new V(tr.x, eyeY, eyeZ);
      // FREE OVERRIDE (--eye/--look): offset from the spawn XZ + ship floor. dy is height ABOVE the floor.
      if (eyeOv) { eye.set(tr.x + eyeOv[0], floorY + eyeOv[1], tr.z + eyeOv[2]); }
      cam.position.copy(eye);
      if (lookOv) {
        cam.up.set(0, 1, 0);
        cam.lookAt(new V(tr.x + lookOv[0], floorY + lookOv[1], tr.z + lookOv[2]));
        cam.updateMatrixWorld(true);
        const shipF = ctx.three.scene.getObjectByName('escapePodShipCockpit');
        let mF = 0; if (shipF) shipF.traverse((o) => { if (o.isMesh) mF++; });
        return { found: !!shipF, meshes: mF, eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)], alert };
      }
      // Look directions in the cockpit-local frame: −Z is forward (window), +Z is aft
      // (the corridor doorway), +X right, −X left.
      if (angle === 'forward') {
        // Mirror the beat's OWN opening framing (tickCockpit faceControl(-0.09, -0.03)) via the SAME
        // YXZ euler method — so this shot is the REAL in-game opening gaze, not a fabricated lookAt.
        // rotation.set(pitch, yaw, 0) with YXZ; faceControl(yaw, pitch) → set(pitch, yaw, 0).
        cam.rotation.order = 'YXZ';
        cam.rotation.set(-0.03, -0.09, 0);
        cam.updateMatrixWorld(true);
      } else {
        let look;
        if (angle === 'console') look = new V(eye.x, eye.y - 0.7, eye.z - 0.8);    // down-forward at the dash
        else if (angle === 'door') look = new V(eye.x, eye.y - 0.05, eye.z + 1);        // turn aft to the corridor
        else if (angle === 'left') look = new V(eye.x - 1, eye.y - 0.1, eye.z - 0.2);
        else if (angle === 'right') look = new V(eye.x + 1, eye.y - 0.1, eye.z - 0.2);
        else look = new V(eye.x, eye.y + 0.06, eye.z - 1);
        cam.lookAt(look);
        cam.updateMatrixWorld(true);
      }
      // Report: is the cockpit built? mesh count? eye height?
      const ship = ctx.three.scene.getObjectByName('escapePodShipCockpit');
      let meshes = 0;
      if (ship) ship.traverse((o) => { if (o.isMesh) meshes++; });
      return { found: !!ship, meshes, eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)], alert };
    }, { angle, stand, alert, colliders, eyeOv, lookOv });
    // A1 — inject the collider wireframe (green LineSegments) using the game's exposed THREE namespace.
    if (colliders) {
      const cinfo = await page.evaluate(async () => {
        const ctx = window.__game.ctx;
        const three = window.__game.THREE;
        const dr = ctx.physics.world.debugRender();
        const bg = new three.BufferGeometry();
        bg.setAttribute('position', new three.BufferAttribute(dr.vertices, 3));
        const mat = new three.LineBasicMaterial({ color: 0x39ff5a, depthTest: false, transparent: true, opacity: 0.95 });
        const seg = new three.LineSegments(bg, mat);
        seg.renderOrder = 9999; seg.frustumCulled = false;
        ctx.three.scene.add(seg);
        return { segVerts: dr.vertices.length / 3 };
      });
      console.log('[cockpit] collider wireframe: ' + JSON.stringify(cinfo));
    }
    // RE-ANCHOR the camera-relative space planet to the NOW-POSED camera. The planet is
    // anchored each frame in updateSky (cam + dir*distance); we paused before it could run
    // at the ship-origin camera (y≈3000), so it was left stale 3000m below at y≈0 → NOT in
    // the window. Mirror applySpaceMode's anchor here so the rig shows the REAL in-game
    // frame (the planet where the seated pilot actually sees it out the windscreen).
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      let group = null;
      ctx.three.scene.traverse((o) => { if (o.isMesh && o.renderOrder === -0.4 && o.parent) group = o.parent; });
      if (!group) return;
      const cam = ctx.three.camera; cam.updateMatrixWorld(true);
      const V = cam.position.constructor;
      // SEV2 2026-07-05 — read the anchor from sky.ts's userData TRUTH STAMP (buildSpacePlanet
      // stamps spaceAnchorDir/spaceAnchorDistance on the group) instead of a hand mirror. The
      // old hardcoded DIST=400 predated the W4 400→1000 retune (radius 66→165), so this block
      // placed the 165m planet at 400m — a 2.6×-oversized (~49° vs the real ~19°) FALSE FRAME;
      // the adversarial gate read the open starfield inside its huge limb arcs as "stars
      // visible through the planet's dark side". Fallbacks match sky.ts's current constants.
      const ud = group.userData || {};
      const ad = ud.spaceAnchorDir || [0.30, 0.10, -1];
      const dir = new V(ad[0], ad[1], ad[2]).normalize();
      const DIST = ud.spaceAnchorDistance || 1000;
      group.position.set(cam.position.x + dir.x * DIST, cam.position.y + dir.y * DIST, cam.position.z + dir.z * DIST);
      group.updateMatrixWorld(true);
      // Re-anchor the star field + sky DOME to the posed camera too (updateSky does this each
      // frame via .position.copy(cam), but we paused before it ran at the ship-origin camera →
      // they'd be stuck at the world origin 3000m below, so the window showed no stars). Mirror it.
      ctx.three.scene.traverse((o) => {
        if (o.isPoints && o.renderOrder === -0.5) { o.position.copy(cam.position); o.updateMatrixWorld(true); }        // stars
        if (o.isMesh && o.material && o.material.uniforms && o.material.uniforms.uTopColor) { o.position.copy(cam.position); o.updateMatrixWorld(true); }   // dome sphere
      });
      // Full-intro coherence fix mirror: dim the world sun+ambient by the orbit blend so the paused
      // cockpit rig shows the SAME vacuum lighting the in-game applySpaceMode now applies (no desert
      // noon flooding the cockpit at orbit). Uses window.__RIG space passthrough via the closure arg.
      if (ctx.lights) { const sp = (window.__RIG_SPACE01 || 0); ctx.lights.sun.intensity *= (1 - sp * 0.88); ctx.lights.ambient.intensity *= (1 - sp * 0.94); }
    });
    await page.waitForTimeout(300);
    const perfC = await page.evaluate(() => { const ctx = window.__game.ctx; ctx.three.renderer.info.reset(); ctx.three.renderer.render(ctx.three.scene, ctx.three.camera); const i = ctx.three.renderer.info; const ship = ctx.three.scene.getObjectByName('escapePodShipCockpit'); let sm = 0; if (ship) ship.traverse((o) => { if (o.isMesh) sm++; }); return { draws: i.render.calls, tris: i.render.triangles, programs: i.programs?.length ?? -1, shipMeshes: sm }; });
    console.log('[cockpit-perf] ' + JSON.stringify(perfC));
    const tag = `cockpit-${argv.tag || angle}${stand ? '-stand' : ''}${alert > 0 ? '-a' + alert : ''}${space > 0 ? '-space' + (space === 1 ? '' : space) : ''}${hideStars ? '-nostars' : ''}`;
    // Clip to the canvas rect + disable animations + generous timeout: the full-page
    // font/compositor wait can stall on the space-mode ship scene (the cockpit build);
    // a clipped grab of just the WebGL canvas snapshots reliably.
    await page.screenshot({ path: join(OUT, `scen-${tag}.png`), fullPage: false, clip: { x: 0, y: 0, width: 1100, height: 760 }, animations: 'disabled', timeout: 60000 });
    console.log(`[cockpit] ${JSON.stringify(meas)} → scen-${tag}.png`);
  },

  // ROUND-2d item-2 — GLASS HAZE PARITY PROBE. Machine-measures the dome-glass luminance in the
  //   FRONT / SIDE / TOP pane regions against an IDENTICAL pure-BLACK sky (dome + stars + planet +
  //   ALL non-glass ship geometry hidden), so the number is the glass presence ITSELF (emissive
  //   glaze + border + rim), not contaminated by whatever sky patch or frame sits behind each region.
  //   The per-pose MEAN is confounded by how much of the frame is face-on pane vs grazing sliver vs
  //   black gap; the robust per-pane read = the MEDIAN of the body-band pixels (the typical pane-
  //   INTERIOR glaze value, coverage-independent) = the "haze" the seated eye perceives per pane.
  //   Parity = the three region medians within a tight tolerance (±10%). --nolights removes the cabin
  //   point lights so the metric is the pure emissive presence; --save writes per-region PNGs.
  //     node scripts/rig-shot.mjs --scenario=cockpit-glass-luma --port=5192 [--nolights] [--save]
  'cockpit-glass-luma': async (page) => {
    const noLights = !!argv.nolights;
    await page.evaluate((noLights) => {
      window.__RIG_NOLIGHTS = noLights;
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      try { ctx.three.renderer.toneMappingExposure = 1.08; } catch {}
      g.startIntro(); g.jumpToBeat('cockpit'); g.setSkyIntroMode(1);
    }, noLights);
    await page.waitForTimeout(700);
    const regions = { front: [0.0, 1.55, -1.0], side: [-1.0, 1.7, -0.35], top: [0.0, 2.6, -1.0] };
    const out = await page.evaluate((regions) => {
      const ctx = window.__game.ctx;
      // ISOLATE THE GLASS: hide EVERY mesh/points/sprite EXCEPT the dome glass sheet (the renderOrder-2
      //   transparent sheet) → against pure black, every non-black pixel IS glass. Optionally kill the
      //   cabin lights (the view-dependent specular of the point lights otherwise makes face-on FRONT
      //   panes read hotter than grazing SIDE/TOP — a measurement confound the median already tames).
      ctx.three.scene.traverse((o) => {
        if (o.isMesh || o.isPoints || o.isSprite) {
          const isGlass = o.isMesh && o.material && o.material.transparent && o.renderOrder === 2;
          if (!isGlass) o.visible = false;
        }
        if (window.__RIG_NOLIGHTS && o.isLight) o.intensity = 0;
      });
      ctx.three.renderer.setClearColor(0x000000, 1);
      ctx.flags.paused = true;
      const cam = ctx.three.camera; const V = cam.position.constructor;
      const W = 1100, H = 760; ctx.three.renderer.setSize(W, H, false);
      if (cam.isPerspectiveCamera) { cam.aspect = W / H; cam.updateProjectionMatrix(); }
      const tr = ctx.player.body.body.translation();
      const floorY = tr.y - (ctx.player.body.halfHeight + ctx.player.body.radius);
      const eye = new V(tr.x, tr.y + (ctx.player.eyeOffset || 0.5), tr.z + 0.1);
      const gl = ctx.three.renderer.getContext();
      const res = {};
      for (const [name, look] of Object.entries(regions)) {
        cam.position.copy(eye); cam.up.set(0, 1, 0);
        cam.lookAt(new V(tr.x + look[0], floorY + look[1], tr.z + look[2]));
        cam.updateMatrixWorld(true);
        ctx.three.renderer.render(ctx.three.scene, ctx.three.camera);
        const px = new Uint8Array(W * H * 4);
        gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px);
        const body = []; let sumAll = 0, nAll = 0;
        for (let i = 0; i < px.length; i += 4) {
          const l = 0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2];
          if (l > 1.5) { sumAll += l; nAll++; if (l < 26) body.push(l); }   // body = the faint glaze fill (below the bright border/rim)
        }
        body.sort((a, b) => a - b);
        const med = body.length ? body[Math.floor(body.length / 2)] : 0;
        const meanBody = body.length ? body.reduce((a, b) => a + b, 0) / body.length : 0;
        res[name] = { bodyMed: +med.toFixed(3), bodyMean: +meanBody.toFixed(3), allMean: nAll ? +(sumAll / nAll).toFixed(3) : 0, glassPx: nAll };
      }
      return res;
    }, regions);
    if (argv.save) {
      for (const [name, look] of Object.entries(regions)) {
        await page.evaluate((look) => {
          const ctx = window.__game.ctx; const cam = ctx.three.camera; const V = cam.position.constructor;
          const tr = ctx.player.body.body.translation();
          const floorY = tr.y - (ctx.player.body.halfHeight + ctx.player.body.radius);
          const eye = new V(tr.x, tr.y + (ctx.player.eyeOffset || 0.5), tr.z + 0.1);
          cam.position.copy(eye); cam.up.set(0, 1, 0);
          cam.lookAt(new V(tr.x + look[0], floorY + look[1], tr.z + look[2])); cam.updateMatrixWorld(true);
          ctx.three.renderer.render(ctx.three.scene, ctx.three.camera);
        }, look);
        await page.screenshot({ path: join(OUT, `glass-luma-${name}.png`), clip: { x: 0, y: 0, width: 1100, height: 760 } });
      }
    }
    const medVals = ['front', 'side', 'top'].map((k) => out[k].bodyMed);
    const meanVals = ['front', 'side', 'top'].map((k) => out[k].bodyMean);
    const parity = (vals) => { const m = vals.reduce((a, b) => a + b, 0) / vals.length; const d = Math.max(...vals.map((v) => Math.abs(v - m) / (m || 1))); return { m, d }; };
    const pm = parity(medVals), pmn = parity(meanVals);
    const pass = pm.d <= 0.10;
    console.log('[glass-luma] ' + JSON.stringify(out));
    console.log('[glass-luma] BODY-MEDIAN front=' + medVals[0] + ' side=' + medVals[1] + ' top=' + medVals[2] +
      ' | mean=' + pm.m.toFixed(3) + ' maxDev=' + (pm.d * 100).toFixed(1) + '% ' + (pass ? 'PARITY-OK' : 'MISMATCH'));
    console.log('[glass-luma] BODY-MEAN   front=' + meanVals[0] + ' side=' + meanVals[1] + ' top=' + meanVals[2] +
      ' | mean=' + pmn.m.toFixed(3) + ' maxDev=' + (pmn.d * 100).toFixed(1) + '% (coverage-confounded; median is the parity metric)');
  },

  // ── PER-CELL glass haze parity (Z1). The region probe above samples 3 CAMERA DIRECTIONS and reads
  //   every glass pixel in the frame — it can't tell a hull-adjacent CLOSURE strip or a literal CROWN
  //   cell apart from the front panes it shares the frame with (the C60/C63 "region centre" blind spot
  //   the user named). THIS probe walks the merged glass sheet's TRIANGLE BUFFER: every cell = 2 tris
  //   = 6 verts = 18 position floats, in build order (8 front panes, then 4 side-closure strips). For
  //   each cell it: (a) computes the world centroid + face normal, (b) frames the camera head-on to
  //   that cell from the inboard side at a fixed stand-off, (c) renders the ISOLATED glass over black,
  //   (d) reads a tight pixel window around the projected centroid and takes the body-band MEDIAN (the
  //   coverage-independent per-cell glaze read). Parity = every cell within ±10% of the FRONT-PANE median.
  //   DEFAULT MODE = --seated: measures each cell (all front panes + every side-closure strip) AS THE
  //   PILOT SEES IT — from the real seated eye, full composited render (lights + env), sky hidden so the
  //   glaze reads over black. This is the faithful per-cell gate. The diagnostic flags below strip the
  //   scene to isolate a root cause and are NOT the gate (they bottom out at the 8-bit quantization floor):
  //     --isolatecell  draw one cell at a time (kills stacking) · --frontside force FrontSide (kills the
  //     DoubleSide 2-face composite) · --nolights kill cabin lights (pure emissive). Use --raw to run the
  //     old synthetic head-on single-pane path instead of seated. --save writes per-cell frames.
  //     node scripts/rig-shot.mjs --scenario=cockpit-glass-cells --port=5192
  'cockpit-glass-cells': async (page) => {
    const noLights = !!argv.nolights;
    const isolateCell = !!argv.isolatecell;
    const frontSide = !!argv.frontside;
    // seated (the faithful gate) is the DEFAULT; --raw / any isolate/frontside/nolights flag opts into the
    //   synthetic head-on diagnostic path.
    const seated = !argv.raw && !isolateCell && !frontSide && !noLights;
    await page.evaluate(({ noLights, isolateCell, frontSide, seated }) => {
      window.__RIG_NOLIGHTS = noLights;
      window.__RIG_ISOLATECELL = isolateCell;
      window.__RIG_FRONTSIDE = frontSide;
      window.__RIG_SEATED = seated;
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      try { ctx.three.renderer.toneMappingExposure = 1.08; } catch {}
      g.startIntro(); g.jumpToBeat('cockpit'); g.setSkyIntroMode(1);
    }, { noLights, isolateCell, frontSide, seated });
    await page.waitForTimeout(700);
    const out = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const THREE = ctx.three.THREE || window.THREE;
      // Isolate the dome glass sheet (renderOrder 2, transparent). Hide everything else → black backdrop.
      let glassMesh = null;
      ctx.three.scene.traverse((o) => {
        if (o.isMesh || o.isPoints || o.isSprite) {
          const isGlass = o.isMesh && o.material && o.material.transparent && o.renderOrder === 2;
          if (!isGlass) o.visible = false; else glassMesh = o;
        }
        if (window.__RIG_NOLIGHTS && o.isLight) o.intensity = 0;
      });
      if (glassMesh && window.__RIG_FRONTSIDE) { glassMesh.material.side = 0; glassMesh.material.needsUpdate = true; }
      // Kill the ENVIRONMENT reflection (non-seated modes only) so the synthetic head-on metric isolates
      //   the pure EMISSIVE GLAZE ("haze") — not the glass reflecting the (non-uniform) space IBL, which
      //   is a legitimately per-direction reflection, NOT haze. Seated mode keeps env+lights (the REAL look).
      if (glassMesh && !window.__RIG_SEATED) { glassMesh.material.envMap = null; glassMesh.material.envMapIntensity = 0; glassMesh.material.needsUpdate = true; }
      if (!window.__RIG_SEATED) { try { ctx.three.scene.environment = null; } catch {} }
      if (!glassMesh) return { error: 'no glass mesh found' };
      ctx.three.renderer.setClearColor(0x000000, 1);
      ctx.flags.paused = true;
      const cam = ctx.three.camera; const V = cam.position.constructor;
      const W = 900, H = 900; ctx.three.renderer.setSize(W, H, false);
      if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.fov = 50; cam.updateProjectionMatrix(); }
      const gl = ctx.three.renderer.getContext();

      // Reconstruct cells from the position buffer (6 verts / cell, world-space).
      glassMesh.updateMatrixWorld(true);
      const pos = glassMesh.geometry.getAttribute('position');
      const M = glassMesh.matrixWorld;
      const nCells = Math.floor(pos.count / 6);
      // build-order labels: 4 columns × 2 bands front (col L-wrap, L-ctr, R-ctr, R-wrap × band lo/hi),
      //   then closure L lo/hi, closure R lo/hi.
      const frontLabels = [];
      const cols = ['Lwrap', 'Lctr', 'Rctr', 'Rwrap'];
      for (const c of cols) for (const b of ['lo', 'hi']) frontLabels.push('front-' + c + '-' + b);
      const closureLabels = ['closL-lo', 'closL-hi', 'closR-lo', 'closR-hi'];
      const labels = frontLabels.concat(closureLabels);

      const cellData = [];
      for (let ci = 0; ci < nCells; ci++) {
        const verts = [];
        for (let vi = 0; vi < 6; vi++) {
          const idx = ci * 6 + vi;
          const p = new V(pos.getX(idx), pos.getY(idx), pos.getZ(idx)).applyMatrix4(M);
          verts.push(p);
        }
        const centroid = new V();
        for (const p of verts) centroid.add(p);
        centroid.multiplyScalar(1 / 6);
        // face normal from the first triangle
        const e1 = verts[1].clone().sub(verts[0]);
        const e2 = verts[2].clone().sub(verts[0]);
        const nrm = e1.cross(e2).normalize();
        cellData.push({ centroid, nrm, label: labels[ci] || ('cell' + ci), _ci: ci });
      }

      // the pilot head centre (dome centre) — the inboard viewing side.
      const domeCentre = new V(0.0, 1.30, -0.12);
      const res = [];
      // ── SEATED-EYE mode: measure each cell AS THE PLAYER PERCEIVES IT — from the real seated eye,
      //   full composited render (all glass panes, lights+env), sky meshes hidden so the glaze reads over
      //   black. This is the faithful per-cell version of the region probe (which the user validated at
      //   ~16 luma). The synthetic head-on single-pane read (the default below) bottoms out at the 8-bit
      //   quantization floor (2-5 luma), where a 1-unit variation blows ±10% — not representative of the
      //   perceived haze. Sample the window where each cell projects on screen from the seated eye.
      if (window.__RIG_SEATED) {
        const tr = ctx.player.body.body.translation();
        const floorY = tr.y - (ctx.player.body.halfHeight + ctx.player.body.radius);
        // sweep the same look directions the region probe uses (fwd/up/left/right) + gather every cell
        //   that projects into frame front-facing; take its body median from that composited frame.
        const eye = new V(tr.x, floorY + 1.35, tr.z + 0.1);   // seated eye height
        // Sweep MANY seated look directions so every cell is centred+near-head-on in at least one frame
        //   (the eye pans across the whole canopy from the seat). For each cell keep the frame where its
        //   projected centroid is nearest screen-centre (most head-on, least foreshortened).
        const looks = [];
        for (const ax of [-1.4, -0.7, 0, 0.7, 1.4]) for (const ay of [1.35, 1.9, 2.5]) looks.push([ax, ay, -1.0]);
        // add strong LATERAL looks so the side-closure panes (which wrap aft to the collar, behind the
        //   shoulders) get framed head-on too — a purely-forward gaze never faces them.
        for (const ay of [1.35, 1.9]) { looks.push([-2.2, ay, 0.2]); looks.push([2.2, ay, 0.2]); looks.push([-2.0, ay, 0.5]); looks.push([2.0, ay, 0.5]); }
        const cellBest = new Map();   // label → { med, bodyPx, score }
        for (const look of looks) {
          cam.position.copy(eye); cam.up.set(0, 1, 0);
          cam.lookAt(new V(tr.x + look[0], floorY + look[1], tr.z + look[2]));
          cam.updateMatrixWorld(true); cam.updateProjectionMatrix();
          ctx.three.renderer.render(ctx.three.scene, cam);
          const px = new Uint8Array(W * H * 4); gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px);
          for (const cell of cellData) {
            const proj = cell.centroid.clone().project(cam);
            if (proj.z > 1 || Math.abs(proj.x) > 0.9 || Math.abs(proj.y) > 0.9) continue;
            const sx = Math.round((proj.x * 0.5 + 0.5) * W), sy = Math.round((proj.y * 0.5 + 0.5) * H);
            const centreDist = Math.hypot(proj.x, proj.y);   // 0 = dead centre (most head-on)
            const win = 18; const body = []; let nAll = 0;
            for (let dy = -win; dy <= win; dy++) { const yy = sy + dy; if (yy < 0 || yy >= H) continue;
              for (let dx = -win; dx <= win; dx++) { const xx = sx + dx; if (xx < 0 || xx >= W) continue;
                const i = (yy * W + xx) * 4; const l = 0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2];
                if (l > 1.5) { nAll++; if (l < 40) body.push(l); } } }
            if (body.length < 120) continue;   // the window must be mostly glass (cell present, unoccluded)
            body.sort((a, b) => a - b); const med = body[Math.floor(body.length / 2)];
            const prev = cellBest.get(cell.label);
            if (!prev || centreDist < prev.score) cellBest.set(cell.label, { med: +med.toFixed(2), bodyPx: body.length, score: centreDist, bodyMean: +(body.reduce((a, b) => a + b, 0) / body.length).toFixed(2) });
          }
        }
        for (const label of labels) {
          const b = cellBest.get(label);
          res.push({ label, bodyMed: b ? b.med : 0, bodyMean: b ? b.bodyMean : 0, bodyPx: b ? b.bodyPx : 0, glassPx: 0, allMean: 0, cy: 0, ndv: 1, rgb: [0, 0, 0], seen: !!b });
        }
        return { nCells, res, seated: true };
      }
      const lightDump = [];
      ctx.three.scene.traverse((o) => { if (o.isLight && o.visible) lightDump.push(o.type + ':' + (o.intensity || 0).toFixed(2)); });
      for (const cell of cellData) {
        // View each cell along its TRUE FACE NORMAL (inboard-pointing), NOT toward the dome centre —
        //   framing toward the centre hits steeply-raked closures/crown at a grazing angle and confounds
        //   the Fresnel-alpha with real material differences. The inboard normal removes that confound:
        //   every cell is now viewed head-on, so any residual luma difference is genuinely material/geo.
        let viewDir = cell.nrm.clone();
        // ensure it points toward the cabin interior (inboard = toward the dome centre side).
        if (viewDir.dot(domeCentre.clone().sub(cell.centroid)) < 0) viewDir.negate();
        if (viewDir.lengthSq() < 1e-6) viewDir = domeCentre.clone().sub(cell.centroid).normalize();
        viewDir.normalize();
        const standOff = 1.15;
        const camPos = cell.centroid.clone().add(viewDir.clone().multiplyScalar(standOff));
        cam.position.copy(camPos); cam.up.set(0, 1, 0);
        cam.lookAt(cell.centroid);
        cam.updateMatrixWorld(true);
        cam.updateProjectionMatrix();
        // --isolatecell: draw ONLY this cell's 6 verts (drawRange) so NO other stacked/DoubleSide
        //   glass layer composites into the read — isolates the SINGLE-pane material presence. Without
        //   it, overhead/crown cells read hotter because more glass panes stack behind them along the ray.
        if (window.__RIG_ISOLATECELL) glassMesh.geometry.setDrawRange(cell._ci * 6, 6);
        ctx.three.renderer.render(ctx.three.scene, cam);
        // stash the projected NdV + a couple of cell frames for save-mode diagnosis
        cell._proj = null;
        if (window.__RIG_ISOLATECELL) glassMesh.geometry.setDrawRange(0, Infinity);
        // project the centroid to screen pixels
        const proj = cell.centroid.clone().project(cam);
        const sx = Math.round((proj.x * 0.5 + 0.5) * W);
        const sy = Math.round((proj.y * 0.5 + 0.5) * H);   // gl origin bottom-left
        const px = new Uint8Array(W * H * 4);
        gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px);
        // sample a tight window (±win px) around the projected centroid → the CELL BODY.
        const win = 90;
        const body = []; let nAll = 0, sumAll = 0;
        for (let dy = -win; dy <= win; dy++) {
          const yy = sy + dy; if (yy < 0 || yy >= H) continue;
          for (let dx = -win; dx <= win; dx++) {
            const xx = sx + dx; if (xx < 0 || xx >= W) continue;
            const i = (yy * W + xx) * 4;
            const l = 0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2];
            if (l > 1.5) { nAll++; sumAll += l; if (l < 26) body.push(l); }   // body = the faint glaze fill
          }
        }
        body.sort((a, b) => a - b);
        const med = body.length ? body[Math.floor(body.length / 2)] : 0;
        const meanBody = body.length ? body.reduce((a, b) => a + b, 0) / body.length : 0;
        // dump the exact centroid pixel RGB (helps distinguish an alpha vs a colour/hue difference).
        const ci4 = (Math.max(0, Math.min(H - 1, sy)) * W + Math.max(0, Math.min(W - 1, sx))) * 4;
        const rgb = [px[ci4], px[ci4 + 1], px[ci4 + 2]];
        res.push({
          label: cell.label,
          bodyMed: +med.toFixed(2),
          bodyMean: +meanBody.toFixed(2),
          bodyPx: body.length,
          glassPx: nAll,
          allMean: nAll ? +(sumAll / nAll).toFixed(2) : 0,
          cy: +cell.centroid.y.toFixed(2),
          ndv: +Math.abs(cell.nrm.dot(viewDir)).toFixed(3),   // 1 = head-on; low = grazing (Fresnel fires)
          rgb,
        });
      }
      return { nCells, res, lightDump, hasEnv: !!ctx.three.scene.environment, glassEnv: !!(glassMesh && glassMesh.material.envMap), glassEnvI: glassMesh ? glassMesh.material.envMapIntensity : -1 };
    });
    if (out.lightDump) console.log('[glass-cells][diag] lights=' + JSON.stringify(out.lightDump) + ' sceneEnv=' + out.hasEnv + ' glassEnvMap=' + out.glassEnv + ' glassEnvI=' + out.glassEnvI);
    if (argv.save) {
      // re-render + save a frame for each cell so we can SEE what the window contains.
      const cellsToSave = out.res ? out.res.map((r) => r.label) : [];
      for (let ci = 0; ci < cellsToSave.length; ci++) {
        await page.evaluate((ci) => {
          const ctx = window.__game.ctx;
          const cam = ctx.three.camera; const V = cam.position.constructor;
          let glassMesh = null;
          ctx.three.scene.traverse((o) => { if (o.isMesh && o.material && o.material.transparent && o.renderOrder === 2) glassMesh = o; });
          if (!glassMesh) return;
          glassMesh.updateMatrixWorld(true);
          const pos = glassMesh.geometry.getAttribute('position'); const M = glassMesh.matrixWorld;
          const c = new V();
          for (let vi = 0; vi < 6; vi++) { const idx = ci * 6 + vi; c.add(new V(pos.getX(idx), pos.getY(idx), pos.getZ(idx)).applyMatrix4(M)); }
          c.multiplyScalar(1 / 6);
          const a = new V(pos.getX(ci * 6), pos.getY(ci * 6), pos.getZ(ci * 6)).applyMatrix4(M);
          const b = new V(pos.getX(ci * 6 + 1), pos.getY(ci * 6 + 1), pos.getZ(ci * 6 + 1)).applyMatrix4(M);
          const cc = new V(pos.getX(ci * 6 + 2), pos.getY(ci * 6 + 2), pos.getZ(ci * 6 + 2)).applyMatrix4(M);
          let nrm = b.clone().sub(a).cross(cc.clone().sub(a)).normalize();
          const dome = new V(0, 1.30, -0.12);
          if (nrm.dot(dome.clone().sub(c)) < 0) nrm.negate();
          cam.position.copy(c.clone().add(nrm.clone().multiplyScalar(1.15))); cam.up.set(0, 1, 0);
          cam.lookAt(c); cam.updateMatrixWorld(true); cam.updateProjectionMatrix();
          if (window.__RIG_ISOLATECELL) glassMesh.geometry.setDrawRange(ci * 6, 6);
          ctx.three.renderer.render(ctx.three.scene, cam);
          if (window.__RIG_ISOLATECELL) glassMesh.geometry.setDrawRange(0, Infinity);
        }, ci);
        await page.screenshot({ path: join(OUT, `glass-cell-${String(ci).padStart(2, '0')}-${cellsToSave[ci]}.png`), clip: { x: 0, y: 0, width: 900, height: 900 } });
      }
      console.log('[glass-cells] saved ' + cellsToSave.length + ' per-cell frames to verification/');
    }
    if (out.error) { console.log('[glass-cells] ERROR ' + out.error); return; }
    // front-pane reference median = median of the 8 front cells' bodyMed.
    const fronts = out.res.filter((r) => r.label.startsWith('front-')).map((r) => r.bodyMed).sort((a, b) => a - b);
    const frontMed = fronts.length ? fronts[Math.floor(fronts.length / 2)] : 0;
    console.log('[glass-cells] nCells=' + out.nCells + '  FRONT-PANE reference median=' + frontMed.toFixed(2));
    console.log('[glass-cells] ' + 'cell'.padEnd(14) + 'bodyMed'.padStart(9) + 'bodyMean'.padStart(10) + '  dev-vs-front  bodyPx');
    let worst = 0, worstLabel = '';
    for (const r of out.res) {
      const dev = frontMed > 0 ? (r.bodyMed - frontMed) / frontMed : 0;
      if (Math.abs(dev) > Math.abs(worst)) { worst = dev; worstLabel = r.label; }
      const flag = Math.abs(dev) > 0.10 ? '  <<< OUT' : '';
      console.log('[glass-cells] ' + r.label.padEnd(14) + String(r.bodyMed).padStart(9) + String(r.bodyMean).padStart(10) +
        '  ' + (dev >= 0 ? '+' : '') + (dev * 100).toFixed(1).padStart(6) + '%' + '     ' + String(r.bodyPx).padStart(6) + ' rgb=' + JSON.stringify(r.rgb) + flag);
    }
    const allWithin = out.res.every((r) => frontMed > 0 && Math.abs((r.bodyMed - frontMed) / frontMed) <= 0.10);
    console.log('[glass-cells] ' + (allWithin ? 'PARITY-OK (every cell within ±10% of front median)' :
      'MISMATCH worst=' + worstLabel + ' ' + (worst >= 0 ? '+' : '') + (worst * 100).toFixed(1) + '%'));
  },

  // PARALLAX-FIX PROBE (sky.ts): measure the space planet's projected ANGULAR DIAMETER
  // from (a) the seated pilot eye and (b) ~10m aft down the corridor doorway, comparing the
  // OLD camera-anchored placement (planet re-centered on the camera → ZERO parallax → it
  // balloons as the ship shrinks) vs the NEW fixed-world-anchor placement (near-constant
  // angular size + natural tiny parallax). Prints hard numbers — the reproduction + the fix
  // evidence. Drives the real cockpit beat + space mode LIVE (updateSky/applySpaceMode run,
  // so the NEW numbers come from the shipped code, not a rig fabrication).
  //   node scripts/rig-shot.mjs --scenario=planet-parallax
  'planet-parallax': async (page) => {
    const aft = argv.aft !== undefined ? Number(argv.aft) : 10;   // metres aft to sample the "backed down the corridor" view
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      g.startIntro();
      g.jumpToBeat('cockpit');
      g.setSkyIntroMode(1);
    });
    // Let the beat build the ship + seat the player, and let a few live frames run so
    // updateSky→applySpaceMode CAPTURES the world anchor at the seated eye (the fix).
    await page.waitForTimeout(900);
    // Shrink the canvas so each throttled tick is cheap, then RESET + re-engage space mode
    // AFTER the seat has settled — the first (transient, pre-seat) capture frame is gone, so
    // the anchor now captures at the real seated eye. Then pump time so the recapture-on-teleport
    // path also has a chance to run. Mirrors the real game where the 60fps loop recaptures freely.
    await page.evaluate(() => {
      const g = window.__game;
      g.ctx.three.renderer.setSize(96, 96, false);
      g.setSkyIntroMode(0);   // drop the stale pre-seat anchor
      g.setSkyIntroMode(1);   // re-engage → next sky tick captures at the seated eye
    });
    await page.waitForTimeout(1400);
    const r = await page.evaluate(({ aft }) => {
      const g = window.__game; const ctx = g.ctx;
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      // Find the space-planet group + its geometric radius.
      let planetMesh = null;
      ctx.three.scene.traverse((o) => { if (o.isMesh && o.renderOrder === -0.4) planetMesh = o; });
      if (!planetMesh) return { error: 'planet mesh not found (space mode not built?)' };
      const group = planetMesh.parent;
      const R = (planetMesh.geometry.boundingSphere
        ? planetMesh.geometry.boundingSphere.radius
        : (planetMesh.geometry.computeBoundingSphere(), planetMesh.geometry.boundingSphere.radius));

      // The REAL seated eye (mirror the cockpit scenario's seated pose).
      const tr = ctx.player.body.body.translation();
      const seatedEye = (ctx.player.eyeOffset || 0.5);
      const eye = new V(tr.x, tr.y + seatedEye, tr.z + 0.1);
      // Aft sample = eye stepped +Z down the corridor doorway (backing away from the −Z window).
      const eyeAft = new V(eye.x, eye.y, eye.z + aft);

      // Angular DIAMETER (deg) of a sphere radius R at centre C seen from P: 2*asin(R/|C−P|).
      const angDiam = (Cx, Cy, Cz, P) => {
        const dx = Cx - P.x, dy = Cy - P.y, dz = Cz - P.z;
        const dist = Math.hypot(dx, dy, dz);
        const s = Math.min(1, R / dist);
        return { deg: 2 * Math.asin(s) * 180 / Math.PI, dist };
      };

      // The LIVE (NEW, fixed-world-anchor) planet centre — where applySpaceMode has it now.
      const Cnew = group.getWorldPosition(new V());

      // OLD camera-anchored math: centre = camera + dir*DIST (recomputed per camera pos → the bug).
      // DIST is read LIVE from the current anchor→seat distance (W4 moved it 400→1400), so the "old"
      // camera-anchored reference uses the SAME geometry as the live planet — the comparison stays honest.
      const dir = new V(0.30, 0.10, -1).normalize();
      const DIST = Cnew.distanceTo(eye);
      const oldCentre = (P) => new V(P.x + dir.x * DIST, P.y + dir.y * DIST, P.z + dir.z * DIST);

      const oldSeat = angDiam(oldCentre(eye).x, oldCentre(eye).y, oldCentre(eye).z, eye);
      const oldAft  = angDiam(oldCentre(eyeAft).x, oldCentre(eyeAft).y, oldCentre(eyeAft).z, eyeAft);
      // NEW: the planet is fixed at Cnew; only the eye moves.
      const newSeat = angDiam(Cnew.x, Cnew.y, Cnew.z, eye);
      const newAft  = angDiam(Cnew.x, Cnew.y, Cnew.z, eyeAft);

      const pct = (a, b) => +((b.deg - a.deg) / a.deg * 100).toFixed(2);
      return {
        // World-fixed planet centre (NEW) + the seated eye it was captured from.
        planetWorld: [+Cnew.x.toFixed(1), +Cnew.y.toFixed(1), +Cnew.z.toFixed(1)],
        seatedEye: [+eye.x.toFixed(1), +eye.y.toFixed(1), +eye.z.toFixed(1)],
        aftMeters: aft,
        planetRadius: R,
        old: {
          seatedDeg: +oldSeat.deg.toFixed(3), aftDeg: +oldAft.deg.toFixed(3),
          seatedDist: +oldSeat.dist.toFixed(1), aftDist: +oldAft.dist.toFixed(1),
          changePct: pct(oldSeat, oldAft),
        },
        new: {
          seatedDeg: +newSeat.deg.toFixed(3), aftDeg: +newAft.deg.toFixed(3),
          seatedDist: +newSeat.dist.toFixed(1), aftDist: +newAft.dist.toFixed(1),
          changePct: pct(newSeat, newAft),
        },
        // Sanity: at the SEATED eye the new anchor should EQUAL the old placement (capture == camera-relative).
        seatedMatchDeg: +(newSeat.deg - oldSeat.deg).toFixed(4),
        maxCamDist: +Math.max(newSeat.dist, newAft.dist).toFixed(1),
      };
    }, { aft });
    console.log(`[planet-parallax] ${JSON.stringify(r, null, 2)}`);
  },

  // REAL-CHAIN PARALLAX PROBE (W4 regression). The old `planet-parallax` probe FABRICATES the aft
  // sample (it measures a synthetic eyeAft point against the already-captured centre; it never moves
  // the body + re-runs updateSky), so it can't see a per-frame regression. THIS drives the REAL chain:
  // start intro → cockpit (space mode engaged live) → physically walk the body +Z down the corridor
  // frame-by-frame, letting updateSky→applySpaceMode run EACH ticked frame, and SAMPLES the planet
  // group's WORLD position + projected angular DIAMETER at the seat / 10m aft / 15m aft. If the planet
  // moves WITH the camera (world pos tracks the body) the anchor isn't holding → the balloon regression.
  //   node scripts/rig-shot.mjs --scenario=planet-parallax-real
  'planet-parallax-real': async (page) => {
    const log = await page.evaluate(async () => {
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      const FIXED_DT = 0.05;
      const realClock = ctx.three.clock;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      const V = ctx.three.camera.position.constructor;
      // Drive the live loop until cond() or simBudget sim-seconds (throttle-proof; mirrors pod-walkout).
      const drive = async (simBudget, cond, perTick) => {
        const simStart = ctx.time.elapsed;
        let lastSim = simStart, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          if (perTick) perTick();
          await sleep(16);
          const nowSim = ctx.time.elapsed;
          if (nowSim > lastSim + 1e-6) { lastSim = nowSim; stalls = 0; }
          else if (++stalls > 600) break;
          if (cond && cond()) return { ok: true, sim: +(nowSim - simStart).toFixed(2) };
          if (nowSim - simStart >= simBudget) break;
        }
        return { ok: cond ? cond() : true, sim: +(ctx.time.elapsed - simStart).toFixed(2) };
      };
      // Find the space-planet mesh + its geometric radius (renderOrder −0.4).
      const findPlanet = () => { let m = null; ctx.three.scene.traverse((o) => { if (o.isMesh && o.renderOrder === -0.4) m = o; }); return m; };
      // Angular DIAMETER (deg) of the planet sphere seen from the current camera, using the LIVE
      // world-space group position + the live group scale (the approach scale grows the visual radius).
      const sample = (label) => {
        const planetMesh = findPlanet();
        if (!planetMesh) return { label, error: 'planet mesh not found' };
        const group = planetMesh.parent;
        group.updateMatrixWorld(true);
        const C = group.getWorldPosition(new V());
        const R0 = planetMesh.geometry.boundingSphere
          ? planetMesh.geometry.boundingSphere.radius
          : (planetMesh.geometry.computeBoundingSphere(), planetMesh.geometry.boundingSphere.radius);
        const scl = group.scale.x;                         // the approach scale (1 in orbit)
        const R = R0 * scl;
        const cam = ctx.three.camera.position;
        const body = ctx.player.body.body.translation();
        const dx = C.x - cam.x, dy = C.y - cam.y, dz = C.z - cam.z;
        const dist = Math.hypot(dx, dy, dz);
        const s = Math.min(1, R / dist);
        // The camera-anchored distant-planet SPRITE (makePlanetTexture, renderOrder 0) — should be
        // fully faded (opacity ~0) in full space mode. If it's still visible it's a 2nd, zero-parallax
        // planet (a candidate "balloon" the anchor fix never touched).
        let spriteOp = -1, spriteVis = false;
        ctx.three.scene.traverse((o) => { if (o.isSprite && o.material && o.material.map && o.renderOrder === 0 && o.scale.x > 5) { spriteOp = o.material.opacity; spriteVis = o.visible; } });
        return {
          label,
          bodyZ: +body.z.toFixed(2), camZ: +cam.z.toFixed(2), camY: +cam.y.toFixed(1),
          planetWorld: [+C.x.toFixed(1), +C.y.toFixed(1), +C.z.toFixed(1)],
          groupScale: +scl.toFixed(3),
          camDist: +dist.toFixed(1),
          angDiamDeg: +(2 * Math.asin(s) * 180 / Math.PI).toFixed(3),
          distSprite: { op: +spriteOp.toFixed(3), vis: spriteVis },
        };
      };
      const samples = [];
      try {
        realClock.getDelta = () => FIXED_DT;
        ctx.three.renderer.setSize(64, 64, false);   // tiny canvas → more real frames tick per second
        // FORCE the pointer-lock gate open so isPlaying()===true → updatePlayer runs REAL KCC + camera-anchor.
        ctx.input.controls.isLocked = true;
        ctx.flags.paused = false;
        g.startIntro();                              // REAL new-game entry point (beat 0 = cockpit)
        // let the cockpit build + several live frames run so applySpaceMode CAPTURES the anchor at the SEATED eye
        await drive(2.0, () => ctx.intro && ctx.intro.beat === 'cockpit' && ctx.intro.scratch.shipBuilt === true);
        await drive(0.6, null);
        samples.push(sample('seat'));
        // Advance to checkEngines the REAL way: the cockpit dwell auto-advances after COCKPIT_DWELL, but
        // drive it deterministically — jumpToBeat('checkEngines') flips mode='walk' (stand up + walk),
        // matching the real transition. NO setSkyIntroMode call here → the anchor must HOLD.
        g.jumpToBeat('checkEngines');
        await drive(0.6, null);
        samples.push(sample('stand'));               // stood up (eyeOffset 0.5→0.85) — anchor still held?
        // WALK AFT by translating the body in small increments, letting updatePlayer anchor the camera
        // NATURALLY (no cameraSnapNextFrame) so this is the realest possible per-frame camera-follow the
        // anchor path sees. Each increment is followed by ticked frames so updateSky→applySpaceMode runs
        // at the freshly-anchored camera. This traverses the full 14m corridor + then a big 80m jump to
        // FORCE the recapture path (proving whether recapture returns the camera-relative balloon).
        const shipZ = ctx.player.body.body.translation().z;
        const glideTo = async (targetDz, label, snap) => {
          const steps = Math.max(6, Math.ceil(Math.abs(targetDz)));   // ~1m per increment
          const startZ = ctx.player.body.body.translation().z;
          for (let k = 1; k <= steps; k++) {
            const t = ctx.player.body.body.translation();
            const z = startZ + (shipZ + targetDz - startZ) * (k / steps);
            ctx.player.body.body.setTranslation({ x: t.x, y: t.y, z }, true);
            if (snap) ctx.player.cameraSnapNextFrame = true;   // else the camera lerps/snaps via syncCameraToBody naturally
            await drive(0.15, null);
          }
          samples.push(sample(label));
        };
        window.__PP_seatZ = shipZ;
        await glideTo(10, 'aft10', false);
        await glideTo(14, 'aft14', false);
        // Back toward the window (−Z) — "walk back" toward the seat/planet.
        await glideTo(0.5, 'backToWindow', false);
        // ── A/B MODEL COMPARISON (the design call, kept for the record). At the SEAT and 12m AFT,
        //   compute the planet's projected on-screen DIAMETER (NDC, = "size in the frame") under three
        //   anchor models at the SAME ~19° seat framing: (400) the OLD world-anchor @400m [the W4
        //   regression the user re-reported], (cam) pure camera-anchor [0% — but glued to the camera],
        //   and (LIVE) the SHIPPED far world-anchor [read from the module's live geometry]. This is what
        //   the user actually SEES; it shows the shipped model reads "same size as I move" (≈−1%).
        {
          const cam = ctx.three.camera;
          const planetMesh = findPlanet();
          const Rlive = planetMesh.geometry.boundingSphere.radius;     // the SHIPPED radius (module const)
          const Clive = planetMesh.parent.getWorldPosition(new V());   // the SHIPPED anchor (module const · dir)
          const distLive = Clive.distanceTo(new V(0, 3001.4, shipZ));  // the SHIPPED distance
          const dir = new V(0.30, 0.10, -1).normalize();
          const ndcDiam = (C, R, eye) => {
            const d = Math.hypot(C.x - eye.x, C.y - eye.y, C.z - eye.z);
            const ang = 2 * Math.asin(Math.min(1, R / d));
            const fov = cam.fov * Math.PI / 180;
            return ang / fov;                                          // fraction of the vertical FOV the disc spans
          };
          const seatEye = new V(0, 3001.4, shipZ);
          const aftEye = new V(0, 3001.4, shipZ + 12);
          // OLD 400m world anchor with a radius that hits the SAME seat framing (66 for a 19° disc @400).
          const R400 = 66, D400 = 400;
          const C400 = new V(seatEye.x + dir.x * D400, seatEye.y + dir.y * D400, seatEye.z + dir.z * D400);
          const mk = (eye) => ({
            oldWorldAnchor400: +ndcDiam(C400, R400, eye).toFixed(4),
            cameraAnchored: +ndcDiam(new V(eye.x + dir.x * D400, eye.y + dir.y * D400, eye.z + dir.z * D400), R400, eye).toFixed(4),
            shippedFarAnchor: +ndcDiam(Clive, Rlive, eye).toFixed(4),
          });
          window.__PP_ab = { seat: mk(seatEye), aft12: mk(aftEye), shippedDist: +distLive.toFixed(0) };
        }
        // ── DESCENT-APPROACH regression check: the planet MUST still GROW during the descent beats
        //   (intentional — "we are falling INTO that"). Drive setSkyIntroMode + setPlanetApproach exactly
        //   as tickDescent does, at progress 0 / 0.11 / 0.22, and measure the group scale + angular diameter
        //   from the descending pod eye. The disc should visibly swell across the approach (scale 1→3.6).
        const descSamples = [];
        for (const prog of [0.0, 0.11, 0.22]) {
          g.setSkyIntroMode(1 - Math.min(1, Math.max(0, (prog - 0.14) / 0.34)));
          g.setPlanetApproach(Math.min(1, prog / 0.22));
          await drive(0.15, null);
          const pm = findPlanet();
          const grp = pm.parent; grp.updateMatrixWorld(true);
          const C = grp.getWorldPosition(new V());
          const scl = grp.scale.x;
          const R = pm.geometry.boundingSphere.radius * scl;
          const cam2 = ctx.three.camera.position;
          const dist = Math.hypot(C.x - cam2.x, C.y - cam2.y, C.z - cam2.z);
          descSamples.push({ prog, groupScale: +scl.toFixed(3), camDist: +dist.toFixed(0), angDiamDeg: +(2 * Math.asin(Math.min(1, R / dist)) * 180 / Math.PI).toFixed(2) });
        }
        window.__PP_desc = descSamples;
      } finally {
        ctx.input.keys['KeyW'] = false;
        realClock.getDelta = origGetDelta;
        ctx.three.renderer.setSize(origW, origH, false);
      }
      return { samples, ab: window.__PP_ab, desc: window.__PP_desc };
    });
    if (log.desc) {
      console.log('[planet-parallax-real] DESCENT-APPROACH (must GROW — intentional): progress → group scale / angular diameter:');
      for (const d of log.desc) console.log(`[planet-parallax-real]   p=${d.prog}: scale ${d.groupScale}× · camDist ${d.camDist}m · angDiam ${d.angDiamDeg}°`);
    }
    if (log.ab) {
      const pct = (a, b) => ((b - a) / a * 100).toFixed(1) + '%';
      console.log(`[planet-parallax-real] MODEL A/B — planet on-screen diameter (fraction of vertical FOV), seat → 12m aft (shipped anchor dist=${log.ab.shippedDist}m):`);
      for (const model of ['oldWorldAnchor400', 'cameraAnchored', 'shippedFarAnchor']) {
        const s = log.ab.seat[model], a = log.ab.aft12[model];
        console.log(`[planet-parallax-real]   ${model}: ${s} → ${a}  (${pct(s, a)} change as you back up 12m)`);
      }
    }
    console.log('[planet-parallax-real] REAL-CHAIN samples (seat → 10m aft → 15m aft):');
    for (const s of log.samples) console.log('[planet-parallax-real] ' + JSON.stringify(s));
    // Drift = angular-diameter change relative to the seat sample.
    const seat = log.samples.find((s) => s.label === 'seat');
    if (seat && !seat.error) {
      for (const s of log.samples) {
        if (s.error || s.label === 'seat') continue;
        const drift = (s.angDiamDeg - seat.angDiamDeg) / seat.angDiamDeg * 100;
        const posDrift = Math.hypot(s.planetWorld[0] - seat.planetWorld[0], s.planetWorld[1] - seat.planetWorld[1], s.planetWorld[2] - seat.planetWorld[2]);
        console.log(`[planet-parallax-real] ${s.label}: angDiam ${seat.angDiamDeg}°→${s.angDiamDeg}° (${drift >= 0 ? '+' : ''}${drift.toFixed(2)}%), planet world moved ${posDrift.toFixed(2)}m from the seat anchor`);
      }
    }
  },

  // Corridor disaster (T3.4): the engine-bay FIRE + the RED-ALERT corridor (the disaster the
  // player flees). Builds the ship, drives the disaster state (fire + red-alert + HULL BREACH),
  // and shoots the corridor. --angle: fire (mid-corridor looking AFT at the engine-bay blaze)
  //   [default] · flee (at the dead-end looking FORWARD down the red corridor toward the bridge).
  'corridor': async (page) => {
    const angle = argv.angle || 'fire';
    if (argv.smoke) {
      await page.evaluate(() => { window.__game.startIntro(); });
      const res = await page.evaluate(() => window.__game.smokeIntro());
      console.log(`[corridor-smoke] ${JSON.stringify(res)}`);
      return;
    }
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      g.startIntro();
      g.jumpToBeat('cockpit');   // builds the ship + seats the player
    });
    await page.waitForTimeout(700);
    const calm = !!argv.calm;   // --calm shoots the pre-disaster (normal-lit) corridor
    const meas = await page.evaluate(({ angle, calm }) => {
      const g = window.__game;
      const ctx = g.ctx;
      // Drive the disaster state directly (the corridor beat does this at the dead-end).
      if (calm) { try { g.setEngineFire(0, 0); g.setShipAlert(0, 0); g.setCockpitAlert(0); } catch {} }
      else { try { g.setEngineFire(1, 2.1); g.setShipAlert(2, 0.9); g.setCockpitAlert(2); } catch {} }
      ctx.flags.paused = true;
      ctx.three.renderer.setSize(1100, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 760; cam.updateProjectionMatrix(); }
      const tr = ctx.player.body.body.translation();
      const floorY = tr.y - (ctx.player.body.halfHeight + ctx.player.body.radius);   // ship floor world-y
      const V = cam.position.constructor;
      // Corridor runs +Z (local z 2.6→14.6); the engine-bay fire sits at the dead-end (z≈14.4).
      let eye, look;
      if (angle === 'flee') {
        eye = new V(tr.x, floorY + 1.55, tr.z + 12.5);              // at the dead-end
        look = new V(tr.x, floorY + 1.2, tr.z + 2.0);              // forward down the red corridor to the bridge
      } else if (angle === 'engineroom') {
        eye = new V(tr.x, floorY + 1.55, tr.z + 12.4);             // close to the dead-end glass door
        look = new V(tr.x, floorY + 1.35, tr.z + 17.0);           // aft THROUGH the glass into the engine room
      } else if (angle === 'entrance') {
        // stood a few m INTO the corridor, looking back FORE at the cockpit archway + the mouth-flank
        //   junction-manifold hardware on BOTH walls (the "very messy entranceway" the user flagged)
        eye = new V(tr.x, floorY + 1.55, tr.z + 5.0);
        look = new V(tr.x, floorY + 1.35, tr.z + 2.4);
      } else if (angle === 'entrance-left') {
        // angled at the −X (left) flank of the entranceway (the manifold + low-pipe elbow + conduit run)
        eye = new V(tr.x + 0.6, floorY + 1.55, tr.z + 4.6);
        look = new V(tr.x - 1.0, floorY + 1.3, tr.z + 2.8);
      } else if (angle === 'entrance-right') {
        // angled at the +X (right) flank of the entranceway (the fore manifold + breaker/placards)
        eye = new V(tr.x - 0.6, floorY + 1.55, tr.z + 4.6);
        look = new V(tr.x + 1.0, floorY + 1.3, tr.z + 2.8);
      } else if (angle === 'quarters') {
        // face the −X crew-quarters door + jamb (the z-fighting jamb sides the user flagged), from
        //   mid-corridor a touch aft so both jamb posts are in frame
        eye = new V(tr.x + 0.85, floorY + 1.5, tr.z + 9.6);
        look = new V(tr.x - 3.0, floorY + 1.35, tr.z + 9.6);
      } else if (angle === 'quarters-graze') {
        // a GRAZING oblique down the −X wall past the quarters jamb (where coplanar jamb/wall faces
        //   shimmer worst — the near-parallel view that exposes z-fighting)
        eye = new V(tr.x + 0.4, floorY + 1.45, tr.z + 7.4);
        look = new V(tr.x - 0.9, floorY + 1.3, tr.z + 10.8);
      } else if (angle === 'quarters-in') {
        // Z2 — INSIDE the room, just past the threshold, looking at the WHOLE cabin (back + fore walls
        //   + bunk alcove). The player's-eye read on entering. Room local x −4.1..−1.0, z 8.2..12.0.
        eye = new V(tr.x - 1.55, floorY + 1.62, tr.z + 9.6);       // just inside the door, room centre-z
        look = new V(tr.x - 3.6, floorY + 1.25, tr.z + 9.2);       // toward the back wall / bunk
      } else if (angle === 'quarters-bunk') {
        // Z2 — the bunk ALCOVE, from the room centre, so the recess + integrated frame reads.
        eye = new V(tr.x - 2.2, floorY + 1.55, tr.z + 11.4);
        look = new V(tr.x - 3.9, floorY + 1.15, tr.z + 9.4);
      } else if (angle === 'quarters-viewport') {
        // Z2 — the HERO view: standing in the cabin, looking BACK through the door across the corridor
        //   to the starboard viewport (real stars). Composition test: is the sightline clear + framed?
        eye = new V(tr.x - 2.6, floorY + 1.60, tr.z + 9.6);
        look = new V(tr.x + 3.0, floorY + 1.45, tr.z + 9.8);
      } else if (angle === 'quarters-back') {
        // Z2 — the BACK-WALL closeup (the user's "models overlapping at the back wall" vantage).
        eye = new V(tr.x - 2.4, floorY + 1.55, tr.z + 11.2);
        look = new V(tr.x - 4.0, floorY + 1.3, tr.z + 11.6);
      } else if (angle === 'quarters-desk') {
        // Z2 r2 — the desk/console moved DOOR-SIDE of the fore wall (deskX≈−1.95, z≈8.56). Look at it
        //   from mid-room toward the fore-door corner.
        eye = new V(tr.x - 2.5, floorY + 1.58, tr.z + 10.2);
        look = new V(tr.x - 1.6, floorY + 1.2, tr.z + 8.5);
      } else if (angle === 'quarters-wide') {
        // Z2 r2 — a WIDE room overview from the door threshold looking diagonally across to the far
        //   back-aft corner, so the WHOLE composition (bunk alcove on the back wall, lockers aft, desk
        //   fore, ceiling fixture) reads in one frame. The "does this read as a real cabin?" gate.
        eye = new V(tr.x - 1.2, floorY + 1.68, tr.z + 9.55);
        look = new V(tr.x - 3.6, floorY + 1.05, tr.z + 11.3);
      } else if (angle === 'quarters-lockers') {
        // Z2 r2 — the AFT-wall locker bank + coverall (the storage read), from mid-room.
        eye = new V(tr.x - 2.2, floorY + 1.58, tr.z + 9.9);
        look = new V(tr.x - 3.4, floorY + 1.25, tr.z + 11.6);
      } else {
        eye = new V(tr.x, floorY + 1.5, tr.z + 7.0);               // mid-corridor
        look = new V(tr.x, floorY + 1.1, tr.z + 14.5);            // aft at the engine-bay blaze
      }
      cam.position.copy(eye);
      cam.lookAt(look);
      cam.updateMatrixWorld(true);
      const ship = ctx.three.scene.getObjectByName('escapePodShipCockpit');
      let meshes = 0;
      if (ship) ship.traverse((o) => { if (o.isMesh) meshes++; });
      return { found: !!ship, meshes, shipAlert: g.ctx ? undefined : 0, eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)] };
    }, { angle, calm });
    await page.waitForTimeout(300);
    const perfCo = await page.evaluate(() => { const ctx = window.__game.ctx; ctx.three.renderer.info.reset(); ctx.three.renderer.render(ctx.three.scene, ctx.three.camera); const i = ctx.three.renderer.info; return { draws: i.render.calls, tris: i.render.triangles, programs: i.programs?.length ?? -1 }; });
    console.log('[corridor-perf] ' + JSON.stringify(perfCo));
    const tag = `corridor-${angle}${calm ? '-calm' : ''}`;
    await page.screenshot({ path: join(OUT, `scen-${tag}.png`), fullPage: false });
    console.log(`[corridor] ${JSON.stringify(meas)} → scen-${tag}.png`);
  },

  // ZFIGHT-PROBE (the Y2 flicker-metric): pan the camera in tiny sub-steps across a named ship
  //   junction and measure the % of pixels that FLIP between consecutive sub-frames (z-fighting =
  //   the depth-test winner alternating as the camera moves sub-pixel amounts → a churning band).
  //   A clean junction reads near-0% (only AA edges churn a trace); a real coplanar z-fight reads a
  //   distinct percentage. Reports per-junction flickerPct (mean churn across the pan) + a peak.
  //   Usage: node scripts/rig-shot.mjs --scenario=zfight-probe --junction=quarters --port=5192
  //   --junction=all runs the whole hotspot set (archway, quarters-fore, quarters-aft, airlock,
  //   engine-glass, viewport). Target: <0.1% mean per junction.
  'zfight-probe': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      g.startIntro();
      g.jumpToBeat('cockpit');
    });
    await page.waitForTimeout(700);
    const which = argv.junction || 'all';
    const out = await page.evaluate(({ which, shot, hideBehind, doorClosed }) => {
      const g = window.__game; const ctx = g.ctx;
      window.__zfShot = !!shot;
      window.__zfHideBehind = !!hideBehind;
      try { g.setEngineFire(0, 0); g.setShipAlert(0, 0); g.setCockpitAlert(0); } catch {}
      // OPEN the sliding airlock door + quarters door so the apertures + jambs read (not sealed).
      //   (--doorclosed keeps the airlock SEALED — used to isolate whether a jamb flip is the open leaf.)
      try { g.setBayAirlockDoor?.(doorClosed ? 0 : 1); } catch {}
      try { g.setQuartersDoor?.(0); } catch {}
      ctx.flags.paused = true;
      const W = 300, H = 300;
      ctx.three.renderer.setSize(W, H, false);
      const cam = ctx.three.camera;
      cam.aspect = W / H; cam.updateProjectionMatrix();
      const tr = ctx.player.body.body.translation();
      const floorY = tr.y - (ctx.player.body.halfHeight + ctx.player.body.radius);
      const V = cam.position.constructor;
      // DIAGNOSTIC (--hidebehind): hide meshes whose world centre is OUTBOARD of the −X corridor wall
      //   (x < wallX−0.02) — the collar/bellows/pod behind the open door — to isolate the corridor-side
      //   airlock FRAME z-fight from anything visible THROUGH the aperture.
      if (window.__zfHideBehind) {
        const wallXW = tr.x - 1.02;
        const wp = new V();
        (ctx.three.scene.getObjectByName('escapePodShipCockpit') || ctx.three.scene).traverse((o) => {
          if (o.isMesh) { o.getWorldPosition(wp); if (wp.x < wallXW) o.visible = false; }
        });
      }
      // Each junction: an eye + a look target; the pan sweeps the eye a small arc laterally.
      // pan = a TINY lateral jitter (≈1cm total) so real-geometry silhouette reprojection stays sub-pixel
      //   (near-zero AA churn on a clean scene) while a z-fight depth-winner still flips across the whole
      //   coplanar band (it flips at ANY camera motion). The flicker thus isolates the z-fighting face.
      const J = {
        'archway':       { eye: [tr.x, floorY + 1.55, tr.z + 4.6], look: [tr.x, floorY + 1.35, tr.z + 2.4], pan: [0.01, 0, 0] },
        'quarters-fore': { eye: [tr.x + 0.7, floorY + 1.45, tr.z + 8.6], look: [tr.x - 2.0, floorY + 1.3, tr.z + 8.98], pan: [0, 0, 0.01] },
        'quarters-aft':  { eye: [tr.x + 0.7, floorY + 1.45, tr.z + 10.6], look: [tr.x - 2.0, floorY + 1.3, tr.z + 10.22], pan: [0, 0, 0.01] },
        'airlock':       { eye: [tr.x + 0.7, floorY + 1.5, tr.z + 4.8], look: [tr.x - 2.0, floorY + 1.3, tr.z + 4.8], pan: [0, 0, 0.01] },
        // Z4 item-2 — the AIRLOCK DOORWAY EDGES (the user's clipping/overlap report). Head-on-ish looks
        //   at the proud FRAME FACES (jamb posts, hazard strips, the aft control panel, the lintel band)
        //   so a COPLANAR winner-flip fills a face. GATE THESE WITH --doorclosed (the RESTING doorway the
        //   report is about — all clean, hardPct≈0). With the door OPEN, airlock-jamb-aft reads ~0.38%
        //   hardPct, but that is the moving LEAF's greeble SILHOUETTE (the flip-centroid raycast pins a
        //   _channel edge 6 cm IN FRONT of the _steel behind it — a parallax edge, NOT a <1 cm coplanar
        //   z-fight); the real doorway overlaps (hazard-strip-on-post, buried panel readout, leaf-inset-
        //   on-slab) were the closed-state coplanars and are FIXED. So the item-2 gate is --doorclosed.
        'airlock-jamb-fore': { eye: [tr.x + 0.5, floorY + 1.15, tr.z + 3.9], look: [tr.x - 0.75, floorY + 1.1, tr.z + 4.05], pan: [0.006, 0, 0.004] },
        'airlock-jamb-aft':  { eye: [tr.x + 0.5, floorY + 1.15, tr.z + 5.7], look: [tr.x - 0.75, floorY + 1.1, tr.z + 5.55], pan: [0.006, 0, 0.004] },
        'airlock-lintel':    { eye: [tr.x + 0.5, floorY + 1.55, tr.z + 4.4], look: [tr.x - 0.75, floorY + 2.25, tr.z + 4.8], pan: [0.005, 0, 0.005] },
        'airlock-panel':     { eye: [tr.x + 0.6, floorY + 1.42, tr.z + 5.3], look: [tr.x - 0.75, floorY + 1.45, tr.z + 5.94], pan: [0.005, 0, 0.004] },
        'engine-glass':  { eye: [tr.x, floorY + 1.55, tr.z + 12.4], look: [tr.x, floorY + 1.35, tr.z + 16.5], pan: [0.008, 0, 0] },
        'viewport':      { eye: [tr.x - 0.7, floorY + 1.5, tr.z + 9.7], look: [tr.x + 2.0, floorY + 1.35, tr.z + 9.7], pan: [0, 0, 0.008] },
        // Z2 — the RE-LOFTED crew-quarters INTERIOR coplanar hotspots (bunk-on-backwall, locker-on-
        //   aftwall, desk-on-forewall, wall-dressing-on-shell). Eye INSIDE the room (room local x −1.5..
        //   −3.6). Head-onto each surface so a coplanar winner-flip fills a face.
        'quarters-bunk':    { eye: [tr.x - 1.7, floorY + 1.35, tr.z + 10.2], look: [tr.x - 3.9, floorY + 1.1, tr.z + 10.3], pan: [0.005, 0, 0.004] },
        'quarters-lockers': { eye: [tr.x - 2.2, floorY + 1.4, tr.z + 10.0], look: [tr.x - 3.0, floorY + 1.3, tr.z + 11.7], pan: [0.004, 0, 0.005] },
        'quarters-desk':    { eye: [tr.x - 2.4, floorY + 1.3, tr.z + 9.8], look: [tr.x - 1.9, floorY + 1.1, tr.z + 8.5], pan: [0.005, 0, 0.004] },
        'quarters-backwall':{ eye: [tr.x - 2.0, floorY + 1.55, tr.z + 9.4], look: [tr.x - 3.95, floorY + 1.6, tr.z + 9.3], pan: [0.004, 0, 0.005] },
      };
      for (const k of Object.keys(J)) if (J[k].pan[0] === 0.01 || J[k].pan[2] === 0.01) { J[k].pan = J[k].pan.map((v) => v === 0.01 ? 0.008 : v); }
      const names = which === 'all' ? Object.keys(J) : [which];
      const gl = ctx.three.renderer.getContext();
      const readFrame = (ex, ey, ez, lx, ly, lz) => {
        cam.position.set(ex, ey, ez); cam.lookAt(lx, ly, lz); cam.updateMatrixWorld(true);
        ctx.three.renderer.render(ctx.three.scene, ctx.three.camera);
        const buf = new Uint8Array(W * H * 4);
        gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, buf);
        return buf;
      };
      const results = {};
      // Motion = a tiny AXIAL DOLLY (a few mm toward/away from the look target) instead of a lateral pan.
      //   A dolly barely moves silhouettes laterally (near-zero AA churn) but it perturbs the depth buffer
      //   maximally → a z-fight's per-pixel depth-winner flips across the whole coplanar band. This
      //   isolates z-fighting from ordinary silhouette AA far better than a lateral pan (which reprojects
      //   the whole scene). THRESH=60 counts a hard color flip; hardPct (Δ>150) counts only the strongest
      //   winner-flips (a different-material coplanar pair), the cleanest z-fight signal.
      const STEPS = 12, THRESH = 60, HARD = 150, DOLLY = 0.012;   // ±6mm dolly
      const churn = (a, b, th) => { let f = 0; for (let i = 0; i < W * H; i++) { const o = i * 4; if (Math.abs(a[o] - b[o]) + Math.abs(a[o + 1] - b[o + 1]) + Math.abs(a[o + 2] - b[o + 2]) > th) f++; } return (f / (W * H)) * 100; };
      for (const nm of names) {
        const j = J[nm];
        const dir = [j.look[0] - j.eye[0], j.look[1] - j.eye[1], j.look[2] - j.eye[2]];
        const dl = Math.hypot(dir[0], dir[1], dir[2]); const u = [dir[0] / dl, dir[1] / dl, dir[2] / dl];
        // static noise floor: two renders at the CENTRE with no motion (renderer non-determinism/dither)
        const c0 = readFrame(j.eye[0], j.eye[1], j.eye[2], j.look[0], j.look[1], j.look[2]);
        const c1 = readFrame(j.eye[0], j.eye[1], j.eye[2], j.look[0], j.look[1], j.look[2]);
        const floor = churn(c0, c1, THRESH);
        let prev = null; let churnSum = 0; let churnPeak = 0; let hardSum = 0; let frames = 0;
        for (let s = 0; s < STEPS; s++) {
          const t = ((s / (STEPS - 1)) - 0.5) * DOLLY;   // ±DOLLY/2 along the view axis
          const ex = j.eye[0] + u[0] * t, ey = j.eye[1] + u[1] * t, ez = j.eye[2] + u[2] * t;
          const buf = readFrame(ex, ey, ez, j.look[0], j.look[1], j.look[2]);
          if (prev) { const pct = churn(buf, prev, THRESH); churnSum += pct; churnPeak = Math.max(churnPeak, pct); hardSum += churn(buf, prev, HARD); frames++; }
          prev = buf;
        }
        results[nm] = { meanPct: +(churnSum / Math.max(1, frames)).toFixed(3), hardPct: +(hardSum / Math.max(1, frames)).toFixed(3), peakPct: +churnPeak.toFixed(3), floorPct: +floor.toFixed(3) };
        // DIAGNOSTIC (--shot): for the probed junction, blit the CENTRE frame + a HARD-FLIP MASK (pixels
        //   that winner-flip under the dolly, painted magenta on a dim base) so the z-fighting REGION is
        //   visible. Returned as data-URLs; the node side writes them out.
        if (window.__zfShot) {
          const base = readFrame(j.eye[0], j.eye[1], j.eye[2], j.look[0], j.look[1], j.look[2]);
          const a = readFrame(j.eye[0] - u[0] * DOLLY / 2, j.eye[1] - u[1] * DOLLY / 2, j.eye[2] - u[2] * DOLLY / 2, j.look[0], j.look[1], j.look[2]);
          const b = readFrame(j.eye[0] + u[0] * DOLLY / 2, j.eye[1] + u[1] * DOLLY / 2, j.eye[2] + u[2] * DOLLY / 2, j.look[0], j.look[1], j.look[2]);
          const cv = document.createElement('canvas'); cv.width = W; cv.height = H;
          const c2 = cv.getContext('2d'); const img = c2.createImageData(W, H);
          for (let y = 0; y < H; y++) { const sy = H - 1 - y; for (let x = 0; x < W; x++) { const s = (sy * W + x) * 4, d = (y * W + x) * 4;
            const flip = Math.abs(a[s] - b[s]) + Math.abs(a[s + 1] - b[s + 1]) + Math.abs(a[s + 2] - b[s + 2]) > HARD;
            if (flip) { img.data[d] = 255; img.data[d + 1] = 0; img.data[d + 2] = 255; }
            else { img.data[d] = base[s] >> 1; img.data[d + 1] = base[s + 1] >> 1; img.data[d + 2] = base[s + 2] >> 1; }
            img.data[d + 3] = 255; } }
          c2.putImageData(img, 0, 0);
          (window.__zfShots = window.__zfShots || {})[nm] = cv.toDataURL('image/png');
          // RAYCAST the flip centroid → name the hit mesh (path + material) so the coplanar pair is pinned.
          let fx = 0, fy = 0, fn = 0;
          for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) { const s = ((H - 1 - y) * W + x) * 4; if (Math.abs(a[s] - b[s]) + Math.abs(a[s + 1] - b[s + 1]) + Math.abs(a[s + 2] - b[s + 2]) > HARD) { fx += x; fy += y; fn++; } }
          if (fn) {
            fx /= fn; fy /= fn;
            const ndc = { x: (fx / W) * 2 - 1, y: -((fy / H) * 2 - 1) };
            cam.position.set(j.eye[0], j.eye[1], j.eye[2]); cam.lookAt(j.look[0], j.look[1], j.look[2]); cam.updateMatrixWorld(true);
            const THREE = g.THREE; const rc = new THREE.Raycaster();
            rc.setFromCamera(ndc, cam);
            const hits = rc.intersectObjects(ctx.three.scene.children, true).filter((h) => h.object.visible && h.object.isMesh).slice(0, 3);
            const desc = hits.map((h) => { let p = h.object, path = ''; for (let k = 0; k < 5 && p; k++) { path = (p.name || p.type) + (path ? '>' : '') + path; p = p.parent; } const m = h.object.material; return { path, mat: (m && m.name) || (m && m.color && m.color.getHexString && m.color.getHexString()) || '?', d: +h.distance.toFixed(2) }; });
            (window.__zfRay = window.__zfRay || {})[nm] = { centroidPx: [Math.round(fx), Math.round(fy)], nFlip: fn, hits: desc };
          }
        }
      }
      return results;
    }, { which, shot: !!argv.shot, hideBehind: !!argv.hidebehind, doorClosed: !!argv.doorclosed });
    console.log('[zfight-probe] ' + JSON.stringify(out));
    if (argv.shot) {
      const shots = await page.evaluate(() => window.__zfShots || {});
      const { writeFileSync } = await import('node:fs');
      for (const [nm, durl] of Object.entries(shots)) {
        const p = join(OUT, `scen-zfight-${nm}.png`);
        writeFileSync(p, Buffer.from(durl.replace(/^data:image\/png;base64,/, ''), 'base64'));
        console.log(`[zfight-probe] flip-mask ${nm} → scen-zfight-${nm}.png`);
      }
      const rays = await page.evaluate(() => window.__zfRay || {});
      for (const [nm, r] of Object.entries(rays)) {
        console.log(`[zfight-probe] flip-centroid ${nm} px=${JSON.stringify(r.centroidPx)} nFlip=${r.nFlip} hits=` +
          r.hits.map((h) => `${h.path}[${h.mat}]@${h.d}m`).join(' | '));
      }
    }
    // gate on hardPct (Δ>150 under an axial dolly = a different-material coplanar winner-flip = a real
    //   z-fight; meanPct still carries residual silhouette AA in dense views). Target: hardPct < 0.1%.
    const fails = Object.entries(out).filter(([, v]) => v.hardPct >= 0.1);
    console.log('[zfight-probe] ' + (fails.length ? 'FLICKER: ' + fails.map(([k, v]) => `${k} hard=${v.hardPct}% mean=${v.meanPct}%`).join(' ') : 'CLEAN (all junctions hardPct < 0.1%)'));
  },

  // Pod-bay (R5c): the DOCKED escape pod in its bay at the bridge end — what the fleeing player
  // runs toward + physically enters (no teleport). Builds the ship (bay + docked pod), then shoots
  // the REAL in-corridor view. --angle: flee (down the corridor at the bay, the flee approach)
  //   [default] · hatch (close at the open hatch — cabin peek + the swung door) · wide (a framing
  //   3/4 of the bay alcove). --calm shoots pre-disaster lighting (default calm; --disaster for red).
  'pod-bay': async (page) => {
    const angle = argv.angle || 'flee';
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      g.startIntro();
      g.jumpToBeat('cockpit');   // builds the ship (incl. the pod-bay + docked pod)
    });
    await page.waitForTimeout(700);
    const disaster = !!argv.disaster;
    const meas = await page.evaluate(({ angle, disaster }) => {
      const g = window.__game;
      const ctx = g.ctx;
      if (disaster) { try { g.setEngineFire(1, 2.1); g.setShipAlert(2, 0.9); g.setCockpitAlert(2); } catch {} }
      ctx.flags.paused = true;
      ctx.three.renderer.setSize(1100, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 760; cam.updateProjectionMatrix(); }
      const tr = ctx.player.body.body.translation();
      const floorY = tr.y - (ctx.player.body.halfHeight + ctx.player.body.radius);   // ship floor world-y
      const V = cam.position.constructor;
      // W2b airlock layout: aperture at local z≈4.8 on the −X wall (x=−1.0); collar to x=−1.92; the
      //   docked pod centre x = SHIP_ORIGIN.x − 3.36 (mostly OUTSIDE the hull); pod door face x=−1.92.
      const bayZ = tr.z + 4.8;            // world z of the airlock centre (tr.z is SHIP_ORIGIN.z at spawn)
      const wallX = tr.x - 1.0;           // the −X wall / sliding-door plane
      const podDoorX = tr.x - 1.92;       // the pod door face (collar far end)
      const podX = tr.x - 3.36;           // the docked pod centre (out in the void)
      // open the sliding door for the hatch/collar/exterior reads so the pod door + collar show.
      //   setBayAirlockDoor isn't yet on __game (the orchestrator wires it) — drive the named leaves
      //   directly here (mirror the slide math: fore leaf −Z, aft leaf +Z into wall pockets).
      if (angle === 'hatch' || angle === 'collar' || angle === 'exterior') {
        const aHW = 0.72, travel = 0.82, bzL = 4.8;   // LOCAL bay-group z (group is at SHIP_ORIGIN)
        const lL = ctx.three.scene.getObjectByName('airlockDoorLeafL');
        const lR = ctx.three.scene.getObjectByName('airlockDoorLeafR');
        if (lL) lL.position.z = (bzL - aHW / 2) - travel;
        if (lR) lR.position.z = (bzL + aHW / 2) + travel;
      }
      let eye, look;
      if (angle === 'hatch') {
        // in the collar mouth, looking −X at the whole pod door face + the lit cabin peek through its glass
        eye = new V(wallX - 0.05, floorY + 1.45, bayZ + 0.05);
        look = new V(podDoorX - 0.2, floorY + 1.2, bayZ);
      } else if (angle === 'collar') {
        // stood back in the CORRIDOR at the open sliding door, looking down the lit collar to the pod
        //   door (the sliding door → airlock collar → docked pod read — the money shot)
        eye = new V(wallX + 1.9, floorY + 1.55, bayZ);
        look = new V(podDoorX, floorY + 1.28, bayZ);
      } else if (angle === 'exterior') {
        // DIAGNOSTIC — from outside the ship's −X hull, looking back at the docked pod (verifies the pod
        //   sits OUTSIDE the hull, not floating/clipping). Not a player view; a build check.
        eye = new V(podX - 2.6, floorY + 2.2, bayZ + 2.4);
        look = new V(podX + 0.2, floorY + 1.3, bayZ);
      } else if (angle === 'sealed' || angle === 'sealed-left' || angle === 'sealed-right') {
        // ROUND-1f AIRTIGHT check — seat the eye INSIDE the docked pod facing the CLOSED +X door (the
        //   user's sealed-eye vantage). Star-gaps down the door sides = the slab clearance against the
        //   curved shell reads as space. Keep the pod door CLOSED (don't open it). The seat backs the
        //   aft (−X) wall facing +X, so the eye sits just aft of the door looking +X.
        try { g.setBayPodDoorOpen(0); } catch {}
        const zc = angle === 'sealed-left' ? -0.55 : angle === 'sealed-right' ? 0.55 : 0.0;
        eye = new V(podX + 0.25, floorY + 1.30, bayZ + zc * 0.4);
        look = new V(podDoorX + 0.4, floorY + 1.12, bayZ + zc);
      } else if (angle === 'wide') {
        // a 3/4 framing from down the corridor, angled INTO the airlock (the docked pod is the subject)
        eye = new V(tr.x + 0.3, floorY + 1.65, bayZ + 3.2);
        look = new V(podDoorX + 0.2, floorY + 1.3, bayZ);
      } else {
        // flee: near the corridor centreline, level with the airlock, looking across at the
        //   sliding door in the −X wall (the run-past-and-see-THE-EXIT read; door CLOSED by default).
        //   W2 gate post-mortem: the old x=+0.85 eye stood 0.15m off the +X wall — proud wall hardware
        //   (breaker-box latch, steel greebles) grazed the frame edge as "floating triangle" slivers
        //   the real centreline player never sees (the D165 harness-viewpoint trap). Judge from where
        //   the player actually runs.
        eye = new V(tr.x + 0.45, floorY + 1.62, bayZ + 2.2);
        look = new V(wallX - 0.2, floorY + 1.3, bayZ - 0.1);
      }
      cam.position.copy(eye);
      cam.lookAt(look);
      cam.updateMatrixWorld(true);
      const bay = ctx.three.scene.getObjectByName('escapePodBay');
      let meshes = 0; if (bay) bay.traverse((o) => { if (o.isMesh) meshes++; });
      return { found: !!bay, meshes, eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)] };
    }, { angle, disaster });
    await page.waitForTimeout(300);
    const tag = `pod-bay-${angle}${disaster ? '-red' : ''}`;
    await page.screenshot({ path: join(OUT, `scen-${tag}.png`), fullPage: false });
    console.log(`[pod-bay] ${JSON.stringify(meas)} → scen-${tag}.png`);
  },

  // ── Z5b — POD-SEAL-SWEEP: the sealed +X bay-pod door must read AIRTIGHT (zero see-through cracks)
  //    from the SEATED eye at EVERY rotation angle. The user sees star-gaps down the door edges only
  //    in the ROTATED state (post setBayPodYaw). This probe drives the bay, seals the door, and for
  //    each yaw in {0, π/4, π/2} fires a RAYCAST FAN from the seated eye through a dense sample of the
  //    door PERIMETER (both side jambs + top arc + bottom), and classifies each ray: does it (a) hit
  //    opaque pod geometry near the door plane (SEALED — good), or (b) pass the door plane into the
  //    bore/void with no near opaque backing (a SEE-THROUGH CRACK — the defect)? Reports the worst
  //    (largest) open sliver + the pod-local exit coords per edge. Renders a seated-eye shot at yaw 0
  //    and yaw π/2 (backdrop differs: airlock-lit vs starfield) so the human read matches the machine.
  //    Machine gate: `--gate` throws if any perimeter ray shows a see-through crack.
  'pod-seal-sweep': async (page) => {
    await page.evaluate((noseal) => {
      const g = window.__game; const ctx = g.ctx;
      if (noseal) globalThis.__NOSEAL__ = true;   // dev-only probe-sensitivity toggle: build WITHOUT the seal
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      g.startIntro();
      g.jumpToBeat('cockpit');   // builds the ship (incl. the pod-bay + docked pod)
    }, !!argv.noseal);
    await page.waitForTimeout(800);
    const gate = !!argv.gate;
    const results = await page.evaluate(async ({ yaws }) => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      let pod = null;
      for (let i = 0; i < 120; i++) { pod = ctx.three.scene.getObjectByName('dockedCanonicalPod'); if (pod) break; await sleep(16); }
      if (!pod) return { error: 'dockedCanonicalPod not found' };
      try { g.setBayPodDoorOpen(0); } catch {}   // seal the door
      const W = 1.02, H = 1.98, CY = 1.10, R = 1.44;
      // opaque POD meshes (skip glass/spec/transparent) — the seal must be POD metal.
      const podMeshes = [];
      pod.traverse((o) => {
        if (!o.isMesh) return;
        const m = o.material;
        const transp = (m && m.transparent && m.opacity < 0.9) || (m && m.name && /glass|spec/i.test(m.name));
        if (transp) return;
        podMeshes.push(o);
      });
      // whole-scene opaque set (to name what a crack ray ULTIMATELY exits through).
      const sceneMeshes = [];
      ctx.three.scene.traverse((o) => {
        if (!o.isMesh) return;
        const m = o.material;
        if ((m && m.transparent && m.opacity < 0.9) || (m && m.name && /glass|spec/i.test(m.name))) return;
        sceneMeshes.push(o);
      });
      const ray = new THREE.Raycaster(); ray.far = 400;
      const out = { byYaw: [] };
      // The seal test: fan a DENSE grid of rays from the seated eye across the door aperture + a thin
      //   MARGIN ring just OUTSIDE each aperture edge (that ring is where the slab-edge↔shell-cut sliver
      //   lives). For each ray, the nearest OPAQUE POD hit must sit at the near door face (≈ R−CAB_R…R+slab
      //   in pod-radius); if the nearest pod hit is FAR (past the door, e.g. the opposite shell) or the
      //   ray reaches SPACE with no pod metal in the door band, that ray SEES THROUGH the seal = a crack.
      //   We express the door surface as a pod-RADIUS test: a sealed hit lands at pod-radius ≈ R (1.44)
      //   ± the slab/lip depth (~0.15). A crack ray's first pod hit is either absent or at radius ≪ R−0.3
      //   (it slipped inside toward the far wall) — or the scene-exit is void.
      // The crack is a GRAZING sightline — a seated player free-looking from a LOW/off-axis eye whose
      //   ray skims the door edge and threads the slab↔shell wedge to space. So sweep a SET of eyes
      //   (low, high, left, right, centre — all within the seated head's reach) and, for each door-edge
      //   sample, test whether the eye→edge ray reaches VOID/far-scene WITHOUT hitting pod-opaque metal
      //   in the door band. That is the definitive see-through test (radius-at-aim missed the grazing case).
      const eyeLocals = [
        new THREE.Vector3(0.30, 1.05, -0.42),  // LOW + shifted −Z (grazes the LEFT jamb — the user's read)
        new THREE.Vector3(0.30, 1.05, 0.42),   // LOW + shifted +Z (grazes the RIGHT jamb)
        new THREE.Vector3(0.30, 1.30, 0.00),   // centre seated
      ];
      for (const yaw of yaws) {
        try { g.setBayPodYaw(yaw); } catch {}
        pod.updateMatrixWorld(true);
        ctx.three.scene.updateMatrixWorld(true);
        const podInv = new THREE.Matrix4().copy(pod.matrixWorld).invert();
        // aim points span the aperture + a 0.10m margin ring (so the edge slivers are sampled).
        const MARG = 0.10;
        const NX = 28, NY = 40;
        let crackCount = 0, sealCount = 0, total = 0;
        const crackRays = [];
        const edgeTally = { 'left-jamb': 0, 'right-jamb': 0, top: 0, bottom: 0, field: 0 };
        for (const eyeLocal of eyeLocals) {
        const eyeWorld = eyeLocal.clone().applyMatrix4(pod.matrixWorld);
        for (let iy = 0; iy <= NY; iy++) {
          for (let ix = 0; ix <= NX; ix++) {
            const fx = -(W / 2 + MARG) + (ix / NX) * (W + 2 * MARG);
            const fy = -(H / 2 + MARG) + (iy / NY) * (H + 2 * MARG);
            const inAperture = Math.abs(fx) < W / 2 - 0.02 && Math.abs(fy) < H / 2 - 0.02;
            const portR = 0.33 + 0.06;   // porthole open radius + rim
            const inPort = (fx * fx + (fy - 0.28) * (fy - 0.28)) < portR * portR;   // porthole centre door-local fy 0.28
            if (inAperture && inPort) continue;   // skip the glass disc (legit see-through)
            total++;
            // aim through a shallow SPREAD around this edge point at the WEDGE depths (behind the frame
            //   plane) — the grazing crack threads BEHIND the proud frame bar, so aim at several radial
            //   depths from the slab outer face back to the shell surface. A crack = ANY of these rays
            //   whose NEAREST opaque hit (pod OR ship, either side of the slab) is FAR/void — meaning
            //   you can see PAST the near hull through the door edge to something distant or to space.
            //   (A truly sealed edge: every such ray's first opaque hit is near pod/frame metal <~2.2m.)
            // SEAL TEST (fast): raycast ONLY the POD-opaque meshes (a small set). A sealed edge blocks
            //   the ray with NEAR pod metal (< NEARLIMIT). A crack ray has NO near pod hit → it threads
            //   the wedge; the eye then sees PAST the pod. Aim at several wedge depths behind the frame.
            const NEARLIMIT = 2.2;   // m — a pod hit nearer than this seals the ray
            let sealedAll = true, crackDir = null;
            for (const fz of [0.11, 0.02, -0.06, -0.14]) {   // slab outer face → into the shell wedge
              const aimLocal = new THREE.Vector3(R + fz, CY + fy, -fx).applyMatrix4(pod.matrixWorld);
              const dir = aimLocal.clone().sub(eyeWorld).normalize();
              ray.set(eyeWorld, dir);
              const hits = ray.intersectObjects(podMeshes, true);
              if (!hits[0] || hits[0].distance > NEARLIMIT) { sealedAll = false; crackDir = dir; break; }
            }
            if (sealedAll) { sealCount++; continue; }
            // a crack candidate — ONE scene-wide raycast to classify what the eye sees THROUGH the gap.
            ray.set(eyeWorld, crackDir);
            const sceneHits = ray.intersectObjects(sceneMeshes, true);
            const first = sceneHits[0];
            const exit = !first ? 'SPACE (void)' : (first.object.name || (first.object.parent && first.object.parent.name) || 'unnamed');
            const firstR = first ? +first.distance.toFixed(2) : 999, firstName = exit;
            crackCount++;
            // which edge region?
            let region = 'field';
            if (fx <= -W / 2) region = 'left-jamb';
            else if (fx >= W / 2) region = 'right-jamb';
            else if (fy >= H / 2) region = 'top';
            else if (fy <= -H / 2) region = 'bottom';
            edgeTally[region]++;
            if (crackRays.length < 14) crackRays.push({ region, fx: +fx.toFixed(3), fy: +fy.toFixed(3), seenDist: firstR, seenObj: firstName, exit });
          }
        }
        }   // eyeLocals
        out.byYaw.push({ yaw: +yaw.toFixed(4), yawDeg: +(yaw * 180 / Math.PI).toFixed(1), eyes: eyeLocals.length, total, sealCount, crackCount, edgeTally, sampleCracks: crackRays });
      }
      try { g.setBayPodYaw(0); } catch {}
      return out;
    }, { yaws: [0, Math.PI / 4, Math.PI / 2] });
    console.log('[pod-seal-sweep] ' + JSON.stringify(results, null, 2));
    const shotYaws = String(argv.yaws || '0,90').split(',').map((s) => Number(s.trim()) * Math.PI / 180);
    for (const yaw of shotYaws) {
      const dataUrl = await page.evaluate(({ yaw, zc, dolly }) => {
        const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
        try { g.setBayPodDoorOpen(0); } catch {}
        try { g.setBayPodYaw(yaw); } catch {}
        ctx.flags.paused = true;
        ctx.three.renderer.setSize(1100, 760, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 760; cam.updateProjectionMatrix(); }
        const pod = ctx.three.scene.getObjectByName('dockedCanonicalPod');
        pod.updateMatrixWorld(true);
        const eye = new THREE.Vector3(0.25 + (dolly || 0), 1.30, zc || 0).applyMatrix4(pod.matrixWorld);
        const look = new THREE.Vector3(1.44, 1.12, zc || 0).applyMatrix4(pod.matrixWorld);
        cam.position.copy(eye);
        cam.lookAt(look);
        cam.updateMatrixWorld(true);
        // render + grab the pixels directly (bypasses Playwright's screenshot font/viewport wait that
        //   stalls on the space backdrop). One explicit draw of the paused scene, then toDataURL.
        ctx.three.renderer.render(ctx.three.scene, cam);
        return ctx.three.renderer.domElement.toDataURL('image/png');
      }, { yaw, zc: Number(argv.zc || 0), dolly: Number(argv.dolly || 0) });
      const tag = `yaw${Math.round(yaw * 180 / Math.PI)}${argv.zc ? `-z${argv.zc}` : ''}${argv.tag ? `-${argv.tag}` : ''}`;
      const b64 = dataUrl.replace(/^data:image\/png;base64,/, '');
      writeFileSync(join(OUT, `scen-seal-sweep-${tag}.png`), Buffer.from(b64, 'base64'));
      console.log(`[pod-seal-sweep] → scen-seal-sweep-${tag}.png`);
    }
    if (gate) {
      const bad = results.byYaw.filter((y) => y.crackCount > 0);
      if (bad.length) throw new Error(`pod-seal-sweep GATE FAILED — see-through cracks at yaw(s): ${JSON.stringify(bad.map((b) => ({ yawDeg: b.yawDeg, crackCount: b.crackCount, byEdge: b.byEdge })))}`);
      console.log('[pod-seal-sweep] GATE PASS — zero see-through cracks at all rotation angles.');
    }
  },

  // Wake interior (T4.1): the REAL first-person view as you COME TO inside the crashed pod in
  // the desert, looking out the ajar hatch (the C18 wake-inside read). Drives the intro to the
  // wake beat (which builds the wake interior + seats the player at the desert spawn), lets the
  // come-to black fade, then poses the seated eye looking −Z out the hatch + shoots.
  'wake': async (page) => {
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      g.setTime(0.46);   // CONSISTENT-MIDDAY (user re-scope) — the wake now happens at bright clear midday (not dawn); the beat sets this too
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1000, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 760; cam.updateProjectionMatrix(); }
      g.startIntro();
      // R3a — the wake now happens INSIDE the real hero cabin (no separate shell). Run the
      // chain through impact (which settles the cabin to its crashed pose at the spawn + frees
      // the player), then jump to wake (seats inside the crashed cabin, looking at its hatch).
      g.jumpToBeat('impact');
    });
    await page.waitForTimeout(2800);   // let impact settle the crashed cabin + fade
    await page.evaluate(() => { window.__game.jumpToBeat('wake'); });
    await page.waitForTimeout(4200);   // let the come-to black fade naturally (mode seated, ticking)
    if (argv.blow) await page.evaluate(() => { try { window.__game.blowCabinHatch(1); } catch {} });   // R3a — force the hatch fully open (the climb-out read: the dawn desert through the wide door)
    // The come-to fade is a transient; we grade the STEADY wake-INSIDE read (the cabin lighting),
    //   so force the black overlay clear before the shot (else we'd grade the fade, not the cabin —
    //   the fade doesn't auto-complete in the non-pointer-locked scenario tick).
    await page.evaluate(() => { const f = document.getElementById('intro-fade'); if (f) f.style.opacity = '0'; });
    const meas = await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.paused = true;
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      const tr = ctx.player.body.body.translation();
      const eye = new V(tr.x, tr.y + (ctx.player.eyeOffset || 0.5), tr.z);
      cam.position.copy(eye);
      // CLUSTER D — look at the cabin's merged FRONT DOOR (−Z, FDOOR_AZ=π → outward dir (0,-1)). The
      //   wake camera faces the door (yaw 0) in-beat; mirror it here so the shot frames the front door
      //   + the midday desert past it, with the riveted cabin wall around (the SAME hero cabin read).
      const haz = Math.PI;
      cam.lookAt(new V(eye.x + Math.sin(haz) * 2, eye.y - 0.05, eye.z + Math.cos(haz) * 2));
      cam.updateMatrixWorld(true);
      const wi = ctx.three.scene.getObjectByName('escapePodCabin');
      let meshes = 0; if (wi) wi.traverse((o) => { if (o.isMesh) meshes++; });
      let sunI = 0; ctx.three.scene.traverse((o) => { if (o.isDirectionalLight && o.castShadow) sunI = o.intensity; });
      const expo = +ctx.three.renderer.toneMappingExposure.toFixed(2);
      // sanity: the come-to fade overlay must be clear for the wake read (else the shot grades the
      //   black fade, not the cabin — the footgun this scenario hit before the pre-shot fade-clear).
      const fadeEl = document.getElementById('intro-fade');
      const fadeOp = fadeEl ? +getComputedStyle(fadeEl).opacity : -1;
      return { found: !!wi, meshes, fadeOp, sunI: +sunI.toFixed(2), expo, dayTime: +ctx.time.dayTime.toFixed(3), eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)] };
    });
    await page.waitForTimeout(300);
    const wtag = argv.blow ? 'scen-wake-blown.png' : 'scen-wake.png';
    await page.screenshot({ path: join(OUT, wtag), fullPage: false });
    console.log(`[wake] ${JSON.stringify(meas)} → ${wtag}`);
    // CRASH-AFTERMATH (2026-07-03) — GATE the interior wake lamp-flicker mechanism (a still can't
    //   judge a temporal flicker): arm + drive it headlessly, report lamp varied / spark toggled / settled.
    const flick = await page.evaluate(() => { try { return window.__game.smokeWakeFlicker(); } catch (e) { return { error: String(e) }; } });
    console.log(`[wake-flicker] ${JSON.stringify(flick)}`);
  },

  // ONE-ENTERABLE-POD (user re-scope, 2026-07-01) — drive the REAL chain through stepOut, which
  // UNIFIES the crashed cabin into the ONE persistent walk-in pod (exterior skin + walkable
  // colliders), then shoot it FROM OUTSIDE in the real game: the step-out-beside read, the
  // walk-back-in approach at the hatch, a look INTO the interior through the open hatch, and a
  // descent-low-vs-stepout light-match. --angle=beside|approach|interior|3q (default beside).
  // Verifies: no model swap (ONE pod in↔out), it's enterable (open hatch + walkable interior),
  // and the light/time is a CONSISTENT bright midday. Front-lit by the real midday sun.
  'stepout-pod': async (page) => {
    const angle = argv.angle || 'beside';
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1000, 800, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 800; cam.updateProjectionMatrix(); }
      g.startIntro();
      g.jumpToBeat('impact');
    });
    await page.waitForTimeout(2600);
    await page.evaluate(() => { window.__game.jumpToBeat('wake'); });
    await page.waitForTimeout(1600);
    // drive the REAL stepOut (unify) — jump to stepOut + let its init tick run (unifyEnterablePod),
    //   then let the reveal-dwell (~4s) elapse so endEscapePodIntro HANDS OFF to the real game (the
    //   real midday sun + game exposure take over — the pod is now a real-world lit object). Shoot
    //   the HANDED-OFF game, not the mid-intro suppressed-light frame.
    await page.evaluate(() => { window.__game.jumpToBeat('stepOut'); });
    await page.waitForTimeout(1400);   // let stepOut's init tick run unifyEnterablePod (builds the skin + colliders + salvage)
    // The rig tab is throttled (dustfall_preview_gotchas), so the reveal-dwell may not tick to the
    //   natural handoff — force it: skipIntro() calls endEscapePodIntro, which (post-re-scope) does
    //   NOT dispose the now-ENTERABLE pod (podIsEnterable) but DOES clear the black overlay + restore
    //   the game HUD/sun. So we hand off to the real game with the ONE unified pod persisting.
    await page.evaluate(() => { window.__game.skipIntro(); });
    await page.waitForTimeout(900);    // let the handed-off game run a lit frame (sun/sky/exposure restored)
    // --popchute (Item 2): fire the comic chute-pop on the UNIFIED pod + synchronously inflate it
    //   (the paused loop gates the per-frame driver, so advanceSeconds drives the settle). Verifies
    //   the canopy anchors ON the unified pod's true crown (not floating ~0.4m above it).
    if (argv.popchute) await page.evaluate(() => { try { window.__game.popChute(2.5); } catch (e) { console.log('popChute err', e); } });
    const r = await page.evaluate(({ ang }) => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.paused = true;
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      // the unified pod persists under the SAME group name ('escapePodCabin'); find its world (x,z).
      const pod = ctx.three.scene.getObjectByName('escapePodCabin');
      let px = 0, pz = 0;
      if (pod) { pod.updateMatrixWorld(true); const p = new V(); p.setFromMatrixPosition(pod.matrixWorld); px = p.x; pz = p.z; }
      const gy = ctx.terrain.heightAt(px, pz);
      // CLUSTER D — the merged FRONT DOOR faces cabin-local FDOOR_AZ=π (−Z) → world outward dir
      //   (sin π, cos π) = (0,−1) (the pod yaw≈0). beside/approach/interior frame the −Z front door.
      const haz = Math.PI, hnx = Math.sin(haz), hnz = Math.cos(haz);
      if (ang === 'beside') {
        // the STEP-OUT read: standing a few m out on the hatch side, looking back at the whole pod.
        cam.position.set(px + hnx * 4.4 + 1.2, gy + 1.7, pz + hnz * 4.4 + 0.6);
        cam.lookAt(px, gy + 1.1, pz);
      } else if (ang === 'approach') {
        // WALK BACK IN: squarely on the open hatch from ~2.6 m out along its normal (the entry read).
        cam.position.set(px + hnx * 2.8, gy + 1.55, pz + hnz * 2.8);
        cam.lookAt(px + hnx * 0.2, gy + 1.0, pz + hnz * 0.2);
      } else if (ang === 'interior') {
        // look INTO the interior through the open hatch (right at the sill) — the walk-in read.
        cam.position.set(px + hnx * 0.9, gy + 1.5, pz + hnz * 0.9);
        cam.lookAt(px - hnx * 1.0, gy + 1.0, pz - hnz * 1.0);
      } else if (ang === 'porthole') {
        // Item 3 — frame the −Z FORWARD arc where the exterior porthole echo bezel sits (VP_AZ=π →
        //   outward −Z). Stand off the −Z side + a touch high/oblique so the bezel is seen at the
        //   grazing angle where it read warm/detached — it must now read flush cool band-metal.
        cam.position.set(px - 1.6, gy + 2.0, pz - 4.2);
        cam.lookAt(px, gy + 1.5, pz);
      } else if (ang === 'chute') {
        // CHUTE-POP read (Item 2): stand well back + a touch high so the whole pod crown + the
        //   draped canopy frame together — the anchor must sit ON the crown, not float above it.
        cam.position.set(px + 6.6, gy + 3.4, pz + 6.2);
        cam.lookAt(px, gy + 2.4, pz);
      } else if (ang === 'furrow') {
        // CRASH-AFTERMATH (2026-07-03) — look DOWN the landing furrow from beyond its far end back
        //   toward the pod, so the whole skid gouge + berms + scattered debris + scorch read as one
        //   "this thing CRASHED here" story. The furrow trails the pod's back-left along the world
        //   heading dir≈(-0.57,+0.82) (crashAftermath _FURROW_DIR); stand ~24 m out along +dir, a
        //   little high + off-axis so the trench + both berms + the base scorch all read.
        const fx = -0.57, fz = 0.82;                 // must match _FURROW_DIR in podScene.ts
        cam.position.set(px + fx * 15 - 2.6, gy + 2.7, pz + fz * 15 + 1.0);   // closer + lower so the trench relief + berm shadows read (a high/far shot flattens them)
        cam.lookAt(px + fx * 3, gy + 0.4, pz + fz * 3);
      } else if (ang === 'furrow3q') {
        // a 3/4 CROSS view of the furrow's mid-section — perpendicular-ish to the skid so the trench
        //   BASIN + both proud berms + the shadow they rake read as real relief (the length view is
        //   near-axial, which flattens the ridges). Stand off the furrow's side, low + raking.
        const fx = -0.57, fz = 0.82;                 // furrow heading
        const perpx = -fz, perpz = fx;               // perpendicular (across the furrow)
        const midx = px + fx * 9, midz = pz + fz * 9;   // ~9 m down the furrow (its mid-section)
        cam.position.set(midx + perpx * 7 + fx * 2, gy + 2.2, midz + perpz * 7 + fz * 2);
        cam.lookAt(midx, gy - 0.1, midz);
      } else { // 3q — a 3/4 of the whole standing silhouette (the exterior form)
        cam.position.set(px + 4.2, gy + 2.4, pz + 4.0);
        cam.lookAt(px, gy + 1.2, pz);
      }
      cam.updateMatrixWorld(true);
      // FRONT-LIGHT prerequisite (visual-diagnostic-methodology.md): the intro's own midday sun is
      //   set, but a paused frame may not have re-derived the lit exposure — set a modest exposure +
      //   a front KEY from beside/above the camera so the camera-facing hull is LIT (not a backlit
      //   silhouette). This is the harness front-light, NOT a substitute viewpoint (D165) — the
      //   camera IS the real step-out-beside/approach/interior read.
      ctx.three.renderer.toneMappingExposure = 1.3;
      let DirCtor = null, HemiCtor = null;
      ctx.three.scene.traverse((o) => { if (o.isDirectionalLight && !DirCtor) DirCtor = o.constructor; if (o.isHemisphereLight && !HemiCtor) HemiCtor = o.constructor; });
      let key = ctx.three.scene.getObjectByName('__soKey');
      if (!key && DirCtor) { key = new DirCtor(); key.name = '__soKey'; key.color.set(0xfff2e0); ctx.three.scene.add(key.target); ctx.three.scene.add(key); }
      if (key) {
        key.intensity = 3.0;
        const toP = new V(px - cam.position.x, 0, pz - cam.position.z);
        key.position.set(cam.position.x + toP.x * 0.2 + 2, cam.position.y + 4, cam.position.z + toP.z * 0.2 + 1);
        key.target.position.set(px, gy + 1.0, pz); key.target.updateMatrixWorld(true);
      }
      let fill = ctx.three.scene.getObjectByName('__soFill');
      if (!fill && HemiCtor) { fill = new HemiCtor(0xcfe0f0, 0x7a6848, 0); fill.name = '__soFill'; ctx.three.scene.add(fill); }
      if (fill) fill.intensity = 1.1;
      // report the pod's exposed height + mesh count + the current dayTime (light-consistency check).
      let meshes = 0, maxY = -1e9;
      if (pod) pod.traverse((o) => { if (o.isMesh && o.geometry) { meshes++; o.geometry.computeBoundingBox(); const bb = o.geometry.boundingBox; const wv = new V(0, bb.max.y, 0); o.localToWorld(wv); maxY = Math.max(maxY, wv.y); } });
      const introActive = !!(ctx.intro && ctx.intro.active);
      const sunI = (() => { let s = 0; ctx.three.scene.traverse((o) => { if (o.isDirectionalLight && o.castShadow) s = o.intensity; }); return +s.toFixed(2); })();
      // walkable-collider check: count STATIC boxes near the pod (floor + wall-ring segments). A
      //   healthy walk-in pod has ~a dozen (the ring is gapped at the hatch, so not a full circle).
      let podCols = 0;
      ctx.physics.world.forEachCollider((c) => { const t = c.translation(); const d = Math.hypot(t.x - px, t.z - pz); if (d < 3.0 && Math.abs(t.y - gy) < 3.0) podCols++; });
      // the tutorial chain: is the unified pod registered as a machete-salvageable (the first-salvage
      //   target), and did the tutorial scatter scrap/cloth around it?
      const podSalvageable = (ctx.salvageables && ctx.salvageables.list || []).some((s) => s.kind === 'escape_pod');
      const scatter = (ctx.pickups && ctx.pickups.list || []).filter((p) => p.itemId === 'scrap' || p.itemId === 'cloth').length;
      return { angle: ang, podAt: [+px.toFixed(1), +pz.toFixed(1)], groundY: +gy.toFixed(2), exposedH: +(maxY - gy).toFixed(2), meshes, podCols, podSalvageable, scatter, dayTime: +ctx.time.dayTime.toFixed(3), introActive, sunI, found: !!pod };
    }, { ang: angle });
    await page.waitForTimeout(350);
    await page.screenshot({ path: join(OUT, `scen-stepout-pod-${angle}.png`), fullPage: false, animations: 'disabled', timeout: 60000 });
    console.log(`[stepout-pod] ${JSON.stringify(r)}`);
  },

  // LEVIATHAN-REVEAL (2026-07-01 midday consistency re-scope) — shoot the STEP-OUT reveal
  // looking OUT toward the beached-leviathan horizon landmark at the NEW bright midday
  // (was designed as a dawn-backlit silhouette; verify it still commands the horizon front-
  // lit). Drives the REAL chain: startIntro → jumpToBeat('stepOut') → let stepOut's init tick
  // run (teleport to the real desert spawn, setIntroMiddayClear, sky mode 0, atmosphere on),
  // then face the leviathan world-bearing from the spawn eye and shoot with the GAME'S OWN
  // midday sun (NO front-key override — the whole point is the natural front-lit read).
  // REQUIRES the intro feature ON so the leviathan is placed at world build:
  //   VITE_ESCAPE_POD_INTRO=1 node scripts/rig-shot.mjs --scenario=leviathan-reveal
  // --fov to widen the horizon read (default 62). --exp exposure (default = leave the game's).
  'leviathan-reveal': async (page) => {
    const fov = argv.fov !== undefined ? Number(argv.fov) : 62;
    const exp = argv.exp !== undefined ? Number(argv.exp) : 0;
    await page.evaluate(() => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1100, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 720; cam.updateProjectionMatrix(); }
      g.startIntro();
      // Jump straight to stepOut: its init tick teleports to the real spawn + sets the bright
      // clear midday + real desert sky/atmosphere (the exact handed-off world the player sees).
      g.jumpToBeat('stepOut');
    });
    await page.waitForTimeout(1400);   // let tickStepOut's init run (teleport + midday + sky/atmosphere + unify)
    // Force the HANDOFF to the real game (skipIntro → endEscapePodIntro) so the REAL midday sun/sky/
    //   exposure/atmosphere take over — the throttled rig tab won't auto-tick the reveal-dwell to the
    //   natural handoff, and we must judge the HANDED-OFF world (bright clear midday), not the mid-
    //   intro suppressed-sky frame. The unified pod + leviathan persist (not disposed).
    await page.evaluate(() => { window.__game.skipIntro(); });
    await page.waitForTimeout(900);    // let several handed-off game frames run so the sky/sun/exposure settle to real midday
    const r = await page.evaluate(({ fov, exp }) => {
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.paused = true;
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      // The player capsule is at the real desert spawn (stepOut teleported it to intro.returnPos).
      //   The enterable pod is UNIFIED at that same spot, so the raw spawn eye is INSIDE the cabin.
      //   The real reveal is the player having STEPPED OUT — stand a few m out along the leviathan
      //   bearing (clear of the hull), the honest step-out standpoint looking at the horizon.
      const tr = ctx.player.body.body.translation();
      // The leviathan's fixed world position (its own module reports it).
      const lev = ctx.three.scene.getObjectByName('leviathanLandmark');
      let lx = -403, lz = 106, foundLev = !!lev;
      if (lev) lev.updateMatrixWorld(true);
      // Bearing from spawn to the landmark.
      const bx = lx - tr.x, bz = lz - tr.z;
      const bl = Math.hypot(bx, bz);
      const bnx = bx / bl, bnz = bz / bl;
      // Step OUT ~5m along the bearing so the camera clears the unified pod hull.
      const STEP = 5.0;
      const ex = tr.x + bnx * STEP, ez = tr.z + bnz * STEP;
      const egy = ctx.terrain.heightAt(ex, ez);
      const ey = egy + 1.7;   // standing eye height on the sand
      // Compute the bearing from THIS standpoint to the landmark; aim along it, pitched a hair up.
      const dx = lx - ex, dz = lz - ez;
      const dist = Math.hypot(dx, dz);
      // Aim a touch above the horizon: the leviathan mass sits ~gy..gy+~30 at 340m; a small
      //   upward pitch keeps the skyline centred without cropping the prow.
      const aimY = ctx.terrain.heightAt(lx, lz) + 14;
      if (cam.isPerspectiveCamera) { cam.fov = fov; cam.updateProjectionMatrix(); }
      cam.position.set(ex, ey, ez);
      cam.lookAt(lx, aimY, lz);
      cam.updateMatrixWorld(true);
      if (exp) ctx.three.renderer.toneMappingExposure = exp;
      // Report the true bearing (unit dir) so we can confirm it matches (-0.949,+0.315), the
      //   current dayTime (midday consistency), the sun direction/intensity (front-lit check),
      //   and the leviathan's exposed silhouette height above its ground (does it clear the horizon).
      const dir = [+(dx / dist).toFixed(3), +(dz / dist).toFixed(3)];
      let sunDir = null, sunI = 0;
      ctx.three.scene.traverse((o) => {
        if (o.isDirectionalLight && o.castShadow) {
          sunI = +o.intensity.toFixed(2);
          const p = o.getWorldPosition(new V());
          const t2 = o.target ? o.target.getWorldPosition(new V()) : new V();
          const d = new V().subVectors(t2, p);
          if (d.length() > 1e-4) { d.normalize(); sunDir = [+d.x.toFixed(2), +d.y.toFixed(2), +d.z.toFixed(2)]; }
        }
      });
      // Leviathan silhouette extent above its ground (from its meshes).
      let levMinY = 1e9, levMaxY = -1e9, levMeshes = 0;
      if (lev) lev.traverse((o) => {
        if (o.isMesh && o.geometry) {
          levMeshes++;
          o.geometry.computeBoundingBox();
          const b = o.geometry.boundingBox;
          for (const cy of [b.min.y, b.max.y]) { const w = new V(0, cy, 0); o.localToWorld(w); levMinY = Math.min(levMinY, w.y); levMaxY = Math.max(levMaxY, w.y); }
        }
      });
      const levGy = ctx.terrain.heightAt(lx, lz);
      return {
        foundLev, levMeshes, dist: +dist.toFixed(1), bearing: dir,
        exposedH: lev ? +(levMaxY - levGy).toFixed(1) : 0,
        dayTime: +ctx.time.dayTime.toFixed(3),
        exposure: +ctx.three.renderer.toneMappingExposure.toFixed(2),
        sunDir, sunI, spawn: [+ex.toFixed(1), +ez.toFixed(1)],
      };
    }, { fov, exp });
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, `scen-leviathan-reveal.png`), fullPage: false, animations: 'disabled', timeout: 60000 });
    console.log(`[leviathan-reveal] ${JSON.stringify(r)}`);
  },

  // LEVIATHAN INTERIOR (2026-07-15) — exterior + breach-MOUTH (head-on + grazing) +
  // interior player-eye reads for the now-enterable colossal wreck. The leviathan is
  // a FIXED hand-placed monument at getLeviathanLandmarkPos() (built at boot when the
  // intro feature is on — the default), so NO descriptor scan / stream: enterLive has
  // already built it. Find it by name, read its world pose + bbox + the builder's
  // leviathanProbe waypoints, and shoot. Prints a DIAGNOSTIC (terrain profile down the
  // hull axis + world Y of the deck) so the interior fit can be tuned.
  //   Run: node scripts/rig-shot.mjs --scenario=leviathan-shot --port=57xx
  'leviathan-shot': async (page) => {
    const info = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0;
      try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.1;
      g.setTime(0.40);                                 // mid-morning raking front light
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1280, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1280 / 720; cam.updateProjectionMatrix(); }
      const lev = ctx.three.scene.getObjectByName('leviathanLandmark');
      if (!lev) return { found: false };
      lev.updateMatrixWorld(true);
      const V = cam.position.constructor;
      const cx = lev.position.x, cz = lev.position.z, yaw = lev.rotation.y;
      // World-space bbox from the meshes (localToWorld each geo box corner).
      let minY = 1e9, maxY = -1e9;
      lev.traverse((o) => {
        if (o.isMesh && o.geometry) {
          o.geometry.computeBoundingBox(); const b = o.geometry.boundingBox;
          for (const yy of [b.min.y, b.max.y]) { const w = new V(0, yy, 0); o.localToWorld(w); minY = Math.min(minY, w.y); maxY = Math.max(maxY, w.y); }
        }
      });
      // Terrain profile down the hull axis (fwd = local +Z under the yaw).
      const fwd = [Math.sin(yaw), Math.cos(yaw)];
      const prof = [];
      for (let z = 12; z >= -48; z -= 6) prof.push([z, +ctx.terrain.heightAt(cx + fwd[0] * z, cz + fwd[1] * z).toFixed(2)]);
      let probe = null;
      lev.traverse((o) => { if (o.userData?.leviathanProbe) probe = o.userData.leviathanProbe; });
      return { found: true, cx: +cx.toFixed(1), cz: +cz.toFixed(1), yaw: +yaw.toFixed(3), gy: +ctx.terrain.heightAt(cx, cz).toFixed(2), minY: +minY.toFixed(2), maxY: +maxY.toFixed(2), prof, probe: probe ? { waypoints: probe.waypoints, ceilY: probe.ceilY, wallX: probe.wallX } : null };
    });
    if (!info.found) { console.log('[leviathan-shot] leviathanLandmark not in scene (intro feature off?)'); return; }
    console.log(`[leviathan-shot] DIAG ${JSON.stringify({ cx: info.cx, cz: info.cz, yaw: info.yaw, gy: info.gy, minY: info.minY, maxY: info.maxY, prof: info.prof })}`);
    // The interior lights are proximity-gated on the PLAYER body (a fixed monument
    // can't hold always-on lights). Teleport the player INTO the wreck + tick a few
    // frames UNPAUSED so updateLeviathanLandmark claims the pool lights before we
    // pause + shoot (else the interior renders dark).
    await page.evaluate(async ({ cx, cz }) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((r) => requestAnimationFrame(() => r()));
      ctx.player.body.body.setTranslation({ x: cx, y: ctx.terrain.heightAt(cx, cz) + 2, z: cz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let i = 0; i < 24; i++) await raf();
    }, { cx: info.cx, cz: info.cz });
    const yaw = info.yaw;
    const fwd = [Math.sin(yaw), Math.cos(yaw)];
    const broad = [Math.cos(yaw), -Math.sin(yaw)];
    const shot = async (name, camDir, along, dist, lift, aimAlong, aimY, side = 1) => {
      await page.evaluate(({ camDir, along, dist, lift, aimAlong, aimY, side, fwd, broad, cx: bcx, cz: bcz }) => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
        const ax = bcx + fwd[0] * aimAlong, az = bcz + fwd[1] * aimAlong;
        const px = ax + (broad[0] * camDir[0] + fwd[0] * camDir[1]) * dist * side;
        const pz = az + (broad[1] * camDir[0] + fwd[1] * camDir[1]) * dist * side;
        const gy = ctx.terrain.heightAt(px, pz);
        cam.position.set(px, gy + lift, pz);
        cam.lookAt(ax, ctx.terrain.heightAt(ax, az) + aimY, az);
        cam.updateMatrixWorld(true);
      }, { camDir, along, dist, lift, aimAlong, aimY, side, fwd, broad, cx: info.cx, cz: info.cz });
      await page.waitForTimeout(350);
      await page.screenshot({ path: join(OUT, `scen-leviathan-${name}.png`), timeout: 60000 });
      console.log(`[leviathan-shot] saved scen-leviathan-${name}.png`);
    };
    // Exterior: full broadside length (aim mid aft-mass), a 3/4 approach.
    await shot('long', [1, 0], -20, 96, 10, -20, 8);
    await shot('approach', [0.8, 0.7], 4, 60, 6, -14, 6);
    // ── THE BREACH (2026-07-16). These used to aim at the amidships FRACTURE (local
    //    z≈+8) and were a FALSE PASS: the reared bow's 21m bore encloses that face, so
    //    a camera placed 15m "outside" it was in fact standing INSIDE the bow's bore
    //    shooting the interior through a hole no player could reach. Framing an
    //    unreachable opening from an unreachable viewpoint is how the sealed build got
    //    signed off. The entrance is now the STARBOARD breach at local (≈+10.9, -0.5),
    //    so these shots are posed in the wreck's LOCAL frame against real coordinates,
    //    from real player standing positions on the sand/ramp.
    const localShot = async (name, cam, aim) => {
      await page.evaluate(({ cam, aim }) => {
        const ctx = window.__game.ctx; const c = ctx.three.camera; ctx.flags.paused = true;
        const lev = ctx.three.scene.getObjectByName('leviathanLandmark');
        const V = c.position.constructor;
        const cw = lev.localToWorld(new V(cam[0], cam[1], cam[2]));
        const aw = lev.localToWorld(new V(aim[0], aim[1], aim[2]));
        c.position.copy(cw); c.lookAt(aw); c.updateMatrixWorld(true);
      }, { cam, aim });
      await page.waitForTimeout(350);
      await page.screenshot({ path: join(OUT, `scen-leviathan-${name}.png`), timeout: 60000 });
      console.log(`[leviathan-shot] saved scen-leviathan-${name}.png`);
    };
    // A camera STOOD ON THE REAL SAND at a local (x,z) — eye height above whatever the
    // dune actually does there, not a hand-guessed local y. The breach shots below were
    // written for the z=-0.5 breach and kept their old aim after it moved to z=-3.6, so
    // they were framing 3m of blank plating beside the door; and their hand-set local y
    // put the camera under the dune once the drift was rebuilt from the real terrain.
    // Both are the same D165 failure — a harness that shoots a viewpoint the player
    // can't occupy is testing a different scene than the one that ships.
    const BZ = -3.6;                                   // I_BREACH_Z (leviathanLandmark.ts)
    const groundShot = async (name, camXZ, aim, eye = 1.6) => {
      await page.evaluate(({ camXZ, aim, eye }) => {
        const ctx = window.__game.ctx; const c = ctx.three.camera; ctx.flags.paused = true;
        const lev = ctx.three.scene.getObjectByName('leviathanLandmark');
        const V = c.position.constructor;
        const cw = lev.localToWorld(new V(camXZ[0], 0, camXZ[1]));
        const aw = lev.localToWorld(new V(aim[0], aim[1], aim[2]));
        c.position.set(cw.x, ctx.terrain.heightAt(cw.x, cw.z) + eye, cw.z);
        c.lookAt(aw); c.updateMatrixWorld(true);
      }, { camXZ, aim, eye });
      await page.waitForTimeout(350);
      await page.screenshot({ path: join(OUT, `scen-leviathan-${name}.png`), timeout: 60000 });
      console.log(`[leviathan-shot] saved scen-leviathan-${name}.png`);
    };
    // Head-on into the tear from the open sand, at eye height — the REAL approach read.
    await groundShot('breach-head', [26, BZ], [9, 5.4, BZ]);
    // Standing OUTSIDE on the drift crest at the sill, looking straight INTO the hold.
    // Local y = the drift's own crest here (I_DECK_Y + 0.08 − 1.5·RAMP_TAN) + eye.
    await localShot('breach-into-hold', [12.6, 3.21 + 1.6, BZ], [-2, 5.0, BZ]);
    // GRAZING both ways across the opening — proves the 0.9m cut cross-section reads
    // as a thick welded rim with NO bright gap/slot between the skins.
    await groundShot('breach-graze-fwd', [13.5, BZ + 9.5], [10.4, 5.2, BZ + 1.5], 4.6);
    await groundShot('breach-graze-aft', [13.5, BZ - 9.5], [10.4, 5.2, BZ - 0.5], 4.6);
    // The DECOY: the reared bow's root, which used to read as an arched way in.
    await localShot('bow-root-decoy', [16, 1.5, 16], [4, 8, 7]);
    // Interior player-eye reads from the builder's probe waypoints.
    if (info.probe) {
      const wps = Object.fromEntries(info.probe.waypoints.map((w) => [w.name, w]));
      const interiorShot = async (name, f, t) => {
        await page.evaluate(({ f, t }) => {
          const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
          cam.position.set(f.x, f.y + 1.6, f.z);
          cam.lookAt(t.x, t.y + 1.3, t.z);
          cam.updateMatrixWorld(true);
        }, { f, t });
        await page.waitForTimeout(350);
        await page.screenshot({ path: join(OUT, `scen-leviathan-${name}.png`), timeout: 60000 });
        console.log(`[leviathan-shot] saved scen-leviathan-${name}.png`);
      };
      const order = info.probe.waypoints.map((w) => w.name);
      for (let i = 0; i < order.length - 1; i++) await interiorShot(`int-${order[i]}`, wps[order[i]], wps[order[i + 1]]);
      // A look back toward the mouth from the deepest interior waypoint (the daylight read).
      const last = wps[order[order.length - 1]];
      await interiorShot('int-back', last, wps[order[0]]);
      // The AFT crew station / story focal — from the aft waypoint look at the
      // console + end wall (−fwd), where the salvage panels + flight-recorder sit.
      const aftW = wps.aft;
      await interiorShot('int-console', aftW, { x: aftW.x - fwd[0] * 6, y: aftW.y, z: aftW.z - fwd[1] * 6 });
    } else {
      console.log('[leviathan-shot] no leviathanProbe userData yet (interior not built) — exterior shots only');
    }
  },

  // LEVIATHAN WALK PROBE (rule 9, real motion) — mirrors skyfall-walk for the fixed
  // leviathan monument. Walk outside → mouth → each interior waypoint → back out →
  // re-enter, asserting at every waypoint that a castDown hits a FLOOR collider (or
  // shin-deep sand ingress), the capsule wasn't ejected (doorway/sill fit), and the
  // roof caps a drop from above. No stream (the monument is always in the scene).
  'leviathan-walk': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0; try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.40);
      ctx.three.renderer.setSize(64, 64, false);   // physics probe: no pixels needed
    });
    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      ctx.flags.paused = false;
      const body = ctx.player.body.body;
      let probe = null;
      ctx.three.scene.traverse((o) => { if (o.userData?.leviathanProbe) probe = o.userData.leviathanProbe; });
      if (!probe) return { fails: ['no leviathanProbe userData (interior not built?)'] };
      const wps = Object.fromEntries(probe.waypoints.map((w) => [w.name, w]));
      const order = probe.waypoints.map((w) => w.name);
      const fails = [];
      const CAP = 1.05;
      const placeAt = async (w) => { body.setTranslation({ x: w.x, y: w.y + CAP + 0.25, z: w.z }, true); body.setLinvel({ x: 0, y: 0, z: 0 }, true); await frames(45); };
      // Teleport-march along the path, RIDING the surface under each step.
      //
      // This used to grant a flat +0.12m of lift per 0.5m step and leave the rest to
      // the solver — i.e. it could only follow ground shallower than ~13°. That was
      // invisible while every leviathan/skyfall surface was a flat deck, but the
      // moment the entrance gained a sand ramp the probe buried the capsule in it and
      // then reported "FALL-THROUGH" at every waypoint — on a wreck whose deck was
      // fine. It was conflating "can't climb" with "no floor", which is not what this
      // gate is for: it exists to prove a floor is THERE and the fit is right.
      // castDown-following makes it measure that honestly. The 1.4m look-up cap keeps
      // it from scaling a wall. Whether the ramp FEELS good to climb is a motion
      // question a teleport probe cannot answer — that is for the human walk-test.
      const CAPSULE_FOOT = 1.05;
      const walkTo = async (w) => {
        for (let i = 0; i < 240; i++) {
          const p = body.translation(); const dx = w.x - p.x, dz = w.z - p.z; const d = Math.hypot(dx, dz);
          if (d < 0.35) break; const s = Math.min(0.5, d);
          const nx = p.x + (dx / d) * s, nz = p.z + (dz / d) * s;
          const surf = g.castDown(nx, nz, p.y + 1.4, true);
          const ny = surf ? Math.max(surf.hitY + CAPSULE_FOOT + 0.05, p.y - 1.5) : p.y + 0.12;
          body.setTranslation({ x: nx, y: ny, z: nz }, true);
          body.setLinvel({ x: 0, y: 0, z: 0 }, true); await frames(6);
        }
        await frames(30);
      };
      const arrived = (w, name) => { const p = body.translation(); const d = Math.hypot(w.x - p.x, w.z - p.z); if (d > 0.9) fails.push(`${name}: did not arrive (blocked ${d.toFixed(2)}m short)`); return d <= 0.9; };
      const floorSet = new Set(probe.floorHandles ?? [probe.deckHandle]);
      const onDeck = (name, w) => {
        const p = body.translation(); const hit = g.castDown(p.x, p.z, p.y, true);
        if (!hit) { fails.push(`${name}: castDown hit NOTHING`); return; }
        if (floorSet.has(hit.colliderHandle)) return;
        if (hit.hitY >= w.y - 0.05 && hit.hitY <= w.y + 0.5) return;
        fails.push(`${name}: on collider ${hit.colliderHandle} (deck=${probe.deckHandle}) hitY=${hit.hitY.toFixed(2)} deckY=${w.y.toFixed(2)} (FALL-THROUGH or deep ingress)`);
      };
      // Walk the full ordered path in + back out + re-enter.
      await placeAt(wps[order[0]]);
      for (let i = 1; i < order.length; i++) { await walkTo(wps[order[i]]); if (arrived(wps[order[i]], order[i])) onDeck(order[i], wps[order[i]]); }
      // Back out to the first waypoint (exit), then re-enter to the 3rd (a hold-ish).
      for (let i = order.length - 2; i >= 0; i--) { await walkTo(wps[order[i]]); }
      { const p = body.translation(); if (Math.hypot(wps[order[0]].x - p.x, wps[order[0]].z - p.z) > 1.0) fails.push('exit: did not get back OUT of the mouth'); }
      const reI = Math.min(2, order.length - 1);
      await walkTo(wps[order[reI]]); if (arrived(wps[order[reI]], `re-enter ${order[reI]}`)) onDeck(`re-enter ${order[reI]}`, wps[order[reI]]);
      // Roof check: a capsule dropped from +6 above a mid waypoint must NOT land on the deck.
      const midW = wps[order[Math.floor(order.length / 2)]];
      body.setTranslation({ x: midW.x, y: midW.y + 6.0, z: midW.z }, true); body.setLinvel({ x: 0, y: 0, z: 0 }, true); await frames(50);
      { const p = body.translation(); const hit = g.castDown(p.x, p.z, p.y, true); if (hit && hit.colliderHandle === probe.deckHandle) fails.push('roof: a capsule dropped from ABOVE landed on the interior deck (hole in the roof colliders)'); }
      return { fails, wps: probe.waypoints.length };
    });
    const pass = r.fails.length === 0;
    console.log(`LEVIATHAN-WALK pass=${pass ? 1 : 0} waypoints=${r.wps ?? 0} fails=${r.fails.length}`);
    console.log(`[leviathan-walk] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r.fails)}`);
    if (!pass) throw new Error('leviathan-walk GATE FAILED');
  },

  // ── ribcage-climb — the CLIMBABLE-SKELETON gate (Zach's walk-test: "the massive
  //    skeleton needs full collision on the top, i want to be able to climb it").
  //    Builds the colossal ribcage through the REAL code path (makeGiantRibcage +
  //    conform + applyColliders) on real terrain ~80m off the player, steps physics
  //    so the Rapier QueryPipeline sees the new colliders, then proves the collision
  //    is a walkable surface, not a set of teleport-lie waypoints:
  //      (A) REST-ON-TOP  — castDown from just above each crest / rib-top sample must
  //          hit the BONE surface (hitY ≈ sample, well above the sand): a player
  //          standing there rests ON the bone, no fall-through.
  //      (B) CLIMB MARCH  — sweep a player-radius sphere from the open SAND up the
  //          spine crest to the crown, riding the floor each 0.45m step with a ~50°
  //          step-up limit (0.55m) and ZERO collider overlap. This is the real proof
  //          a climb path onto the skeleton EXISTS (a gap drops the sphere to sand →
  //          never reaches the crown; an invisible wall → overlap). The march is the
  //          proof; the rest checks alone are not (teleported waypoints lie).
  //      (C) TRAVERSE MARCH — from the crest OUT along a mid-span rib's top to its
  //          tip, sphere never overlapping + staying on bone: you can walk ALONG it.
  //    Prints RIBCAGE-CLIMB pass=… for verify:chunks. Also drops marker spheres on the
  //    proven surface + shoots a framed shot as the "standing on the spine" evidence.
  //    Run: node scripts/rig-shot.mjs --scenario=ribcage-climb --port=5210
  'ribcage-climb': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0; try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.5);
      ctx.three.renderer.setSize(1180, 780, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1180 / 780; cam.updateProjectionMatrix(); }
    });
    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const RAPIER = g.RAPIER;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      // dynImport — eval-import first, <script type=module> shim fallback (mirrors
      // verify-solid: the ribcage builder is not on a game hook, so import it).
      const dynImport = async (url) => {
        try { return await (0, eval)(`import(${JSON.stringify(url)})`); }
        catch (e) {
          if (e && /module|import/i.test(String(e.message)) === false) throw e;
          return await new Promise((resx, rej) => {
            const key = '__si_' + Math.random().toString(36).slice(2);
            const s = document.createElement('script'); s.type = 'module';
            s.textContent = `import * as m from ${JSON.stringify(url)}; window[${JSON.stringify(key)}]=m; window.dispatchEvent(new Event(${JSON.stringify(key)}));`;
            const t = setTimeout(() => { cleanup(); rej(new Error('import timeout ' + url)); }, 20000);
            const onEvt = () => { const m = window[key]; cleanup(); resx(m); };
            function cleanup() { clearTimeout(t); window.removeEventListener(key, onEvt); s.remove(); delete window[key]; }
            window.addEventListener(key, onEvt);
            document.head.appendChild(s);
          });
        }
      };
      const mod = await dynImport('/src/world/giantRibcage.ts');
      const rng = await dynImport('/src/core/rng.ts');
      const bp = ctx.player.body.body.translation();
      const bx = bp.x + 80, bz = bp.z + 6;
      const gy = ctx.terrain.heightAt(bx, bz);
      const rc = mod.makeGiantRibcage(rng.makeRng(0x8a17ce), {
        name: 'giantRibcageClimb',
        conform: { groundAt: (a, b) => ctx.terrain.heightAt(a, b), originX: bx, originZ: bz, yaw: 0, baseY: gy },
      });
      rc.group.position.set(bx, gy, bz);
      rc.group.rotation.y = 0;
      ctx.three.scene.add(rc.group);
      const bodiesAdded = rc.applyColliders(ctx.physics.world, new THREE.Vector3(bx, gy, bz), 0);
      rc.group.updateMatrixWorld(true);
      const bodyCount = bodiesAdded.length;
      const probe = rc.group.userData.ribcageProbe;
      if (!probe || !probe.crest || !probe.crest.length) return { fails: ['no ribcageProbe.crest — collider descriptors missing'], colliders: 0, bodyCount };
      // STEP physics so the QueryPipeline sees the new colliders (castRay /
      // intersectionWithShape are vacuous until world.step() — the CLAUDE.md gate lesson).
      ctx.flags.paused = false;
      await frames(24);
      const toW = (p) => { const v = rc.group.localToWorld(new THREE.Vector3(p.x, p.y, p.z)); return { x: v.x, y: v.y, z: v.z }; };
      const crest = probe.crest.map(toW);
      const ribRests = probe.ribRests.map(toW);
      const ribTrav = (probe.ribTraverse || []).map(toW);
      const fails = [];
      const excludeBody = ctx.player.body.body;
      const R = 0.35;                     // Tuning.PLAYER_CAPSULE_RADIUS
      // Overlap-test ball: slightly UNDER the player radius. A ball centered R above a
      // castDown point on a TILTED floor (a ramp) grazes the slope face — a false wall.
      // A real wall (a collider standing UP in the path, taller than the step-up limit)
      // penetrates far deeper. The under-size ball ignores the graze but still catches
      // the wall (verify-solid's walkin uses full R because its decks are FLAT).
      const ball = new RAPIER.Ball(0.27);
      const OLIFT = 0.20;                  // overlap-ball centre lift above the floor point
      const IDQ = { x: 0, y: 0, z: 0, w: 1 };
      const markers = [];                 // world points proven "on bone" (for the evidence shot)

      // (A) REST-ON-TOP — castDown must land on the bone surface, above the sand.
      const restCheck = (label, pts, sampleN) => {
        const step = Math.max(1, Math.floor(pts.length / sampleN));
        let tested = 0, onBone = 0;
        for (let i = 0; i < pts.length; i += step) {
          const p = pts[i];
          const sand = ctx.terrain.heightAt(p.x, p.z);
          if (p.y - sand < 0.9) continue;                    // barely above sand — nothing to prove
          tested++;
          const hit = g.castDown(p.x, p.z, p.y + 0.6, true);
          if (hit && Math.abs(hit.hitY - p.y) <= 0.75 && hit.hitY - sand > 0.6) {
            onBone++; markers.push({ x: p.x, y: hit.hitY, z: p.z });
          } else {
            fails.push(`${label}[${i}] NOT on bone: hitY=${hit ? hit.hitY.toFixed(2) : 'none'} expected~${p.y.toFixed(2)} sand=${sand.toFixed(2)}`);
          }
        }
        return { tested, onBone };
      };
      const crestRest = restCheck('crest', crest, 10);
      const ribRest = restCheck('rib', ribRests, 8);

      // Sphere-march along a plan polyline, riding the floor each step (castDown) with
      // a ~50° step-UP limit; records peak floor + first collider overlap.
      const STEP = 0.45, STEP_UP = 0.55, LIFT = 0.15;
      const march = (pts) => {
        let y = pts[0].y; let peak = -Infinity; let overlap = null; let minAboveSand = Infinity; let onBoneSteps = 0, totalSteps = 0;
        for (let seg = 0; seg < pts.length - 1; seg++) {
          const a = pts[seg], b = pts[seg + 1];
          const len = Math.hypot(b.x - a.x, b.z - a.z);
          const n = Math.max(1, Math.ceil(len / STEP));
          for (let s = 1; s <= n; s++) {
            const t = s / n;
            const px = a.x + (b.x - a.x) * t, pz = a.z + (b.z - a.z) * t;
            const sand = ctx.terrain.heightAt(px, pz);
            const hit = g.castDown(px, pz, y + STEP_UP, true);
            const floor = Math.max(hit ? hit.hitY : -Infinity, sand);
            y = floor + R + LIFT;
            peak = Math.max(peak, floor);
            totalSteps++;
            if (floor - sand > 0.4) { onBoneSteps++; minAboveSand = Math.min(minAboveSand, floor - sand); }
            const c = ctx.physics.world.intersectionWithShape({ x: px, y: floor + R + OLIFT, z: pz }, IDQ, ball, undefined, undefined, undefined, excludeBody);
            if (c !== null && c !== undefined && !overlap) overlap = { x: +px.toFixed(1), y: +y.toFixed(1), z: +pz.toFixed(1), seg };
          }
        }
        return { peak, endY: y, overlap, onBoneSteps, totalSteps };
      };

      // (B) CLIMB MARCH — from open sand outboard of the low ridge end, up to the crown.
      let crownIdx = 0; for (let i = 1; i < crest.length; i++) if (crest[i].y > crest[crownIdx].y) crownIdx = i;
      const crown = crest[crownIdx];
      // start on the SAND a few m outboard of the near (lower-x) ridge end.
      const nearEnd = crest[0];
      const sandStart = { x: nearEnd.x - 5, z: nearEnd.z, y: 0 };
      sandStart.y = ctx.terrain.heightAt(sandStart.x, sandStart.z) + R + 0.2;
      const crownSand = ctx.terrain.heightAt(crown.x, crown.z);
      const climb = march([sandStart, { x: crown.x, y: crown.y, z: crown.z }]);
      const climbedTo = climb.peak - crownSand;                 // how high above the local sand the sphere got
      const crownAbove = crown.y - crownSand;
      const climbOk = !climb.overlap && climb.peak >= crown.y - 1.0;
      if (climb.overlap) fails.push(`climb: collider OVERLAP at ${JSON.stringify(climb.overlap)} (invisible wall on the ramp)`);
      if (climb.peak < crown.y - 1.0) fails.push(`climb: reached floor y=${climb.peak.toFixed(2)} (crown ${crown.y.toFixed(2)}, sand ${crownSand.toFixed(2)}) — could not climb onto/up the spine`);
      if (climbOk) markers.push({ x: crown.x, y: climb.peak, z: crown.z });

      // (C) TRAVERSE MARCH — from the crest OUT along a mid-span rib to its tip.
      let travOk = true; let trav = null;
      if (ribTrav.length >= 3) {
        trav = march(ribTrav);
        travOk = !trav.overlap && trav.onBoneSteps >= Math.floor(trav.totalSteps * 0.5);
        if (trav.overlap) fails.push(`traverse: collider OVERLAP at ${JSON.stringify(trav.overlap)} (invisible wall on the rib)`);
        if (trav.onBoneSteps < Math.floor(trav.totalSteps * 0.5)) fails.push(`traverse: only ${trav.onBoneSteps}/${trav.totalSteps} steps on bone — rib collision has gaps`);
      }

      // Stash the evidence-shot framing on window for the second evaluate.
      window.__ribClimb = { crown, crest, markers, cx: bx, cz: bz, gy, length: rc.length };
      ctx.flags.paused = true;
      return {
        fails, colliders: probe.crest.length, bodyCount,
        crestRest, ribRest,
        climb: { climbedTo: +climbedTo.toFixed(2), crownAbove: +crownAbove.toFixed(2), peak: +climb.peak.toFixed(2), overlap: !!climb.overlap, ok: climbOk },
        traverse: trav ? { onBone: `${trav.onBoneSteps}/${trav.totalSteps}`, overlap: !!trav.overlap, ok: travOk } : null,
        ribCount: ribRests.length, crestCount: crest.length,
      };
    });
    const pass = r.fails.length === 0;
    console.log(`RIBCAGE-CLIMB pass=${pass ? 1 : 0} bodies=${r.bodyCount ?? 0} crest=${r.crestCount ?? 0}pts ribs=${r.ribCount ?? 0} crestRest=${r.crestRest ? r.crestRest.onBone + '/' + r.crestRest.tested : 'n/a'} ribRest=${r.ribRest ? r.ribRest.onBone + '/' + r.ribRest.tested : 'n/a'} climb=${r.climb ? (r.climb.ok ? 'UP' : 'FAIL') + '(' + r.climb.climbedTo + '/' + r.climb.crownAbove + 'm)' : 'n/a'} traverse=${r.traverse ? (r.traverse.ok ? 'OK' : 'FAIL') + '(' + r.traverse.onBone + ')' : 'n/a'} fails=${r.fails.length}`);
    if (r.fails.length) console.log('[ribcage-climb] ' + JSON.stringify(r.fails.slice(0, 8)));
    // Evidence shot — drop bright marker spheres on the PROVEN surface + frame the cage.
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
      const info = window.__ribClimb; if (!info) return;
      const mat = new THREE.MeshBasicMaterial({ color: 0xff2222 });
      const mg = new THREE.Group(); mg.name = 'climbMarkers';
      for (const m of info.markers) {
        const s = new THREE.Mesh(new THREE.SphereGeometry(0.35, 12, 10), mat);
        s.position.set(m.x, m.y + 0.35, m.z);   // sit the sphere ON the surface it proved
        mg.add(s);
      }
      ctx.three.scene.add(mg);
      // Frame a 3/4 view of the whole cage from off one flank, above eye level.
      const cam = ctx.three.camera;
      const c = info.crown; const L = info.length;
      cam.position.set(c.x - L * 0.55, c.y + 10, c.z + L * 0.5);
      cam.lookAt(c.x, c.y - 1, c.z);
      cam.updateMatrixWorld(true);
    });
    await page.waitForTimeout(450);
    await page.screenshot({ path: join(OUT, 'scen-ribcage-climb-evidence.png'), timeout: 60000 });
    console.log('[ribcage-climb] saved scen-ribcage-climb-evidence.png');
    // A second angle: down the crest from the near ridge end (the climb ramp).
    await page.evaluate(() => {
      const ctx = window.__game.ctx; const info = window.__ribClimb; if (!info) return;
      const cam = ctx.three.camera; const end = info.crest[0]; const c = info.crown;
      cam.position.set(end.x - 8, ctx.terrain.heightAt(end.x - 8, end.z) + 2.0, end.z + 4);
      cam.lookAt(c.x, c.y, c.z);
      cam.updateMatrixWorld(true);
    });
    await page.waitForTimeout(400);
    await page.screenshot({ path: join(OUT, 'scen-ribcage-climb-ramp.png'), timeout: 60000 });
    console.log('[ribcage-climb] saved scen-ribcage-climb-ramp.png');
    if (!pass) throw new Error('ribcage-climb GATE FAILED');
  },

  // ── dune-slope — the ERG (mega dune-sea) PLAYABILITY gate (The Deep Desert,
  //    campaign 2026-07-18). Locates the nearest erg region, then samples the
  //    REAL pure height function (terrain.pureHeightAt — the exact samples the
  //    heightfield collider is baked from, so an analytic march against it is a
  //    faithful KCC model, not a teleport lie) and asserts:
  //      (A) SLOPES        — a dense grid across the core dunes, classified by the
  //          erg's own wind: windward faces (rising downwind) p95 ≤ 30° (the KCC's
  //          50° climb limit + the charter's walkable-windward rule); slip faces
  //          (falling downwind) median within [28,36]° (the dry-sand angle of
  //          repose — the sled's playground). Proves the windward/slip ASYMMETRY.
  //      (B) BORDER        — radial transects through the erg→desert border zone:
  //          NO slope in the transition exceeds the interior dune max (a wide
  //          smoothstep border must not spike a seam).
  //      (C) AMPLITUDE     — crest-to-trough of the primary mega-dunes within the
  //          ERG_DUNE_AMP_* bounds (a real dune SEA, not ripples).
  //      (D) KCC MARCH     — a step-limited march up a windward face trough→crest
  //          SUCCEEDS (max per-step rise ≤ the 50° KCC limit); the paired slip
  //          face is measurably STEEPER (asymmetry, the sled's descent line).
  //      (E) PERF          — a chunk-sized (193²) pureHeightAt grid in the erg
  //          generates within a small multiple of the origin cost (≤4-octave
  //          budget guidance) — the erg height fn isn't a frame killer.
  //    Prints DUNE-SLOPE pass=… for verify:chunks, and shoots crest / trough /
  //    approach vista stubs for the next cycle's real vista set.
  //    Run: node scripts/rig-shot.mjs --scenario=dune-slope --seed=1337 --port=5211
  'dune-slope': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0; try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.5);
      ctx.three.renderer.setSize(1180, 780, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1180 / 780; cam.updateProjectionMatrix(); }
    });
    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const dynImport = async (url) => {
        try { return await (0, eval)(`import(${JSON.stringify(url)})`); }
        catch (e) {
          if (e && /module|import/i.test(String(e.message)) === false) throw e;
          return await new Promise((resx, rej) => {
            const key = '__si_' + Math.random().toString(36).slice(2);
            const s = document.createElement('script'); s.type = 'module';
            s.textContent = `import * as m from ${JSON.stringify(url)}; window[${JSON.stringify(key)}]=m; window.dispatchEvent(new Event(${JSON.stringify(key)}));`;
            const t = setTimeout(() => { cleanup(); rej(new Error('import timeout ' + url)); }, 20000);
            const onEvt = () => { const m = window[key]; cleanup(); resx(m); };
            function cleanup() { clearTimeout(t); window.removeEventListener(key, onEvt); s.remove(); delete window[key]; }
            window.addEventListener(key, onEvt);
            document.head.appendChild(s);
          });
        }
      };
      const { Tuning } = await dynImport('/src/config/tuning.ts');
      const bio = ctx.biomes; const ph = (x, z) => ctx.terrain.pureHeightAt(x, z);
      const DEG = 180 / Math.PI;
      const fails = [];

      // ── locate the nearest erg core (coarse scan → centroid refine) ──
      let coarse = null, bestD = Infinity;
      for (let x = -24000; x <= 24000; x += 200) {
        for (let z = -24000; z <= 24000; z += 200) {
          const dd = x * x + z * z;
          if (dd < 3000 * 3000) continue;
          if (dd < bestD && bio.ergAt(x, z) > 0.9) { bestD = dd; coarse = { x, z }; }
        }
      }
      if (!coarse) return { fails: ['NO ERG found within a 24km scan (seed-dependent — rarity too low?)'], found: false };
      let sx = 0, sz = 0, w = 0;
      for (let dx = -400; dx <= 400; dx += 16) {
        for (let dz = -400; dz <= 400; dz += 16) {
          if (bio.ergAt(coarse.x + dx, coarse.z + dz) > 0.95) { sx += coarse.x + dx; sz += coarse.z + dz; w++; }
        }
      }
      const cx = w ? Math.round(sx / w) : coarse.x;
      const cz = w ? Math.round(sz / w) : coarse.z;
      const info = bio.ergInfoAt(cx, cz);
      const windRad = info ? info.windRad : 0;
      const wd = { x: Math.cos(windRad), z: Math.sin(windRad) };
      const dist = Math.hypot(cx, cz);

      // slope + along-wind gradient sign at (x,z), central diff over 2m.
      const D = 2;
      const slopeAt = (x, z) => {
        const gx = (ph(x + D, z) - ph(x - D, z)) / (2 * D);
        const gz = (ph(x, z + D) - ph(x, z - D)) / (2 * D);
        const slope = Math.atan(Math.hypot(gx, gz)) * DEG;
        const gu = gx * wd.x + gz * wd.z;   // >0 windward (rising downwind), <0 slip
        return { slope, gu };
      };
      const pct = (arr, p) => {
        if (!arr.length) return NaN;
        const a = arr.slice().sort((u, v) => u - v);
        return a[Math.min(a.length - 1, Math.max(0, Math.floor(p * a.length)))];
      };

      // ── (A) dense grid across the core dunes ──
      const wind = [], slip = [];
      for (let dx = -300; dx <= 300; dx += 4) {
        for (let dz = -300; dz <= 300; dz += 4) {
          const x = cx + dx, z = cz + dz;
          if (bio.ergAt(x, z) < 0.98) continue;       // core only (mask ~1) — no border mixing
          const s = slopeAt(x, z);
          if (s.slope < 10) continue;                 // skip trough/crest transitions — measure FACES
          if (s.gu > 0.03) wind.push(s.slope);
          else if (s.gu < -0.03) slip.push(s.slope);
        }
      }
      const windP95 = pct(wind, 0.95), windMax = Math.max(...wind, 0);
      const slipMed = pct(slip, 0.5), slipP05 = pct(slip, 0.05), slipP95 = pct(slip, 0.95), slipMax = Math.max(...slip, 0);
      const interiorMax = Math.max(windMax, slipMax);
      // The KCC climbs ≤50°, the charter requires walkable windward: p95 ≤ 30°.
      if (!(windP95 <= 30)) fails.push(`windward p95 ${windP95.toFixed(1)}° > 30° (unwalkable windward face)`);
      // Slip faces sit at the dry-sand angle of repose (~28-34°). Real dune fields
      // vary (the envelope scales dune height), so the MEDIAN is checked over a
      // band that admits legitimate ±few° seed variance but still catches a field
      // that is all-gentle (no sled faces) or all-cliff (unnatural).
      if (!(slipMed >= 27 && slipMed <= 37)) fails.push(`slip median ${slipMed.toFixed(1)}° outside [27,37]° (angle-of-repose band)`);
      // The steep slip faces (the sled's descent line) must reach the repose band.
      if (!(slipP95 >= 30 && slipP95 <= 50)) fails.push(`slip p95 ${slipP95.toFixed(1)}° outside [30,50]° (the steep slip faces are wrong)`);
      // Asymmetry: the slip side is genuinely steeper than the windward side.
      if (!(slipMed > windP95 - 3)) fails.push(`no asymmetry: slip median ${slipMed.toFixed(1)}° not steeper than windward p95 ${windP95.toFixed(1)}°`);

      // ── (B) border-zone continuity: radial transects out through the border ──
      let borderMax = 0;
      for (let a = 0; a < Math.PI * 2; a += Math.PI / 6) {
        const dirx = Math.cos(a), dirz = Math.sin(a);
        for (let rr = 0; rr <= Tuning.ERG_FIELD_RADIUS + 40; rr += 4) {
          const x = cx + dirx * rr, z = cz + dirz * rr;
          const m = bio.ergAt(x, z);
          if (m <= 0 || m >= 0.98) continue;          // the transition band only
          const s = slopeAt(x, z).slope;
          if (s > borderMax) borderMax = s;
        }
      }
      // The wide smoothstep border must not create a slope STEEPER than the erg's
      // own dunes (a hard seam) — and never an unclimbable ramp near the 50° KCC
      // limit. A real seam discontinuity would spike well past the interior dunes.
      if (borderMax > interiorMax + 6) fails.push(`border slope ${borderMax.toFixed(1)}° spikes above interior max ${interiorMax.toFixed(1)}° (+6° tol) — seam discontinuity`);
      if (borderMax > 48) fails.push(`border slope ${borderMax.toFixed(1)}° > 48° — the erg edge is an unclimbable seam`);

      // ── wind-aligned transect through the core (for amplitude + the marches) ──
      const STEP = 0.4, T0 = -420, TN = 420;
      const prof = [];
      for (let t = T0; t <= TN; t += STEP) {
        const x = cx + wd.x * t, z = cz + wd.z * t;
        prof.push({ t, x, z, h: ph(x, z) });
      }
      // extrema with a ±6m window + ≥6m prominence → primary crests/troughs only.
      const WW = Math.round(6 / STEP);
      const ext = [];
      for (let i = WW; i < prof.length - WW; i++) {
        let isMax = true, isMin = true;
        for (let k = i - WW; k <= i + WW; k++) {
          if (prof[k].h > prof[i].h + 1e-6) isMax = false;
          if (prof[k].h < prof[i].h - 1e-6) isMin = false;
        }
        if (isMax) ext.push({ i, kind: 'max', h: prof[i].h });
        else if (isMin) ext.push({ i, kind: 'min', h: prof[i].h });
      }
      // dedup adjacent same-kind (plateaus)
      const ex2 = [];
      for (const e of ext) { const last = ex2[ex2.length - 1]; if (last && last.kind === e.kind) { if (e.kind === 'max' ? e.h > last.h : e.h < last.h) ex2[ex2.length - 1] = e; } else ex2.push(e); }
      const amps = [];
      for (let i = 1; i < ex2.length; i++) { const d = Math.abs(ex2[i].h - ex2[i - 1].h); if (d > 6) amps.push(d); }
      const ampMed = amps.length ? pct(amps, 0.5) : 0;
      if (!(ampMed >= Tuning.ERG_DUNE_AMP_MIN && ampMed <= Tuning.ERG_DUNE_AMP_MAX))
        fails.push(`mega-dune amplitude ${ampMed.toFixed(1)}m outside [${Tuning.ERG_DUNE_AMP_MIN},${Tuning.ERG_DUNE_AMP_MAX}]m`);

      // ── (D) KCC marches: pick a mid crest + its windward (lower-t) & slip
      //     (higher-t) troughs, then measure the per-step rise up each face. ──
      const maxima = ex2.filter((e) => e.kind === 'max');
      const minima = ex2.filter((e) => e.kind === 'min');
      let march = null;
      if (maxima.length && minima.length >= 1) {
        // crest nearest the transect centre
        const crest = maxima.reduce((b, e) => Math.abs(prof[e.i].t) < Math.abs(prof[b.i].t) ? e : b, maxima[0]);
        const windTrough = minima.filter((m) => m.i < crest.i).sort((a, b) => b.i - a.i)[0];
        const slipTrough = minima.filter((m) => m.i > crest.i).sort((a, b) => a.i - b.i)[0];
        const stepRise = (aIdx, bIdx) => {         // steepest per-STEP height change between two prof indices
          const lo = Math.min(aIdx, bIdx), hi = Math.max(aIdx, bIdx);
          let mx = 0;                              // |Δh| — direction-agnostic (a face is a face climbed either way)
          for (let i = lo; i < hi; i++) { const d = Math.abs(prof[i + 1].h - prof[i].h); if (d > mx) mx = d; }
          return mx;
        };
        const KCC_LIMIT = STEP * Math.tan(50 * Math.PI / 180);   // 50° per 0.4m step ≈ 0.476m
        let windRise = NaN, slipRise = NaN, climbWind = false, climbedTo = 0;
        if (windTrough) {
          windRise = stepRise(windTrough.i, crest.i);
          climbWind = windRise <= KCC_LIMIT;
          climbedTo = crest.h - windTrough.h;
          if (!climbWind) fails.push(`windward march NOT climbable: max step-rise ${windRise.toFixed(3)}m > KCC limit ${KCC_LIMIT.toFixed(3)}m`);
        } else fails.push('no windward trough found on the transect');
        if (slipTrough) slipRise = stepRise(slipTrough.i, crest.i);
        // On this crest's pair, the slip face must be steeper than the windward
        // (a small margin — the STRONG asymmetry proof is the grid stat above; a
        // single transect pair is noisier, so this is a sanity floor, not the gate).
        if (windTrough && slipTrough && !(slipRise > windRise * 1.05))
          fails.push(`slip face not steeper than windward (slip step-rise ${slipRise.toFixed(3)}m vs windward ${windRise.toFixed(3)}m)`);
        march = { windRise, slipRise, climbWind, climbedTo, kccLimit: KCC_LIMIT, crestT: +prof[crest.i].t.toFixed(0), crestH: +crest.h.toFixed(1) };
      } else fails.push('could not resolve a crest+trough pair on the wind transect');

      // ── (E) perf: a chunk-sized (193²) pure-height grid, erg vs origin ──
      const gridMs = (ox, oz) => {
        const t0 = performance.now();
        let acc = 0;
        for (let i = 0; i <= 192; i++) for (let j = 0; j <= 192; j++) acc += ph(ox + (i - 96) * 2, oz + (j - 96) * 2);
        return { ms: performance.now() - t0, acc };
      };
      const perfErg = gridMs(cx, cz).ms;
      const perfOrigin = gridMs(0, 0).ms;
      if (perfErg > perfOrigin * 4 + 30) fails.push(`erg grid ${perfErg.toFixed(1)}ms >> origin ${perfOrigin.toFixed(1)}ms (×4+30 budget) — erg height fn too costly`);

      window.__ergSpot = { cx, cz, windRad, crestT: march ? march.crestT : 0 };
      return {
        found: true, fails, cx, cz, dist, windRad,
        windP95, windMax, slipMed, slipP05, slipP95, slipMax, interiorMax,
        borderMax, ampMed, windN: wind.length, slipN: slip.length,
        march,
        perfErg, perfOrigin,
      };
    });
    const pass = r.found && r.fails.length === 0;
    if (!r.found) {
      console.log(`DUNE-SLOPE pass=0 seed=${argv.seed || '?'} found=0 fails=${r.fails.length}`);
      console.log('[dune-slope] ' + JSON.stringify(r.fails));
      throw new Error('dune-slope GATE FAILED — no erg found');
    }
    const m = r.march || {};
    console.log(
      `DUNE-SLOPE pass=${pass ? 1 : 0} seed=${argv.seed || '?'} erg=(${r.cx},${r.cz})@${r.dist.toFixed(0)}m wind=${(r.windRad * 180 / Math.PI).toFixed(0)}° ` +
      `windP95=${r.windP95.toFixed(1)}° windMax=${r.windMax.toFixed(1)}° slipMed=${r.slipMed.toFixed(1)}° slip=[${r.slipP05.toFixed(1)}-${r.slipP95.toFixed(1)}]° ` +
      `amp=${r.ampMed.toFixed(1)}m border=${r.borderMax.toFixed(1)}° interiorMax=${r.interiorMax.toFixed(1)}° ` +
      `climbWind=${m.climbWind ? 'UP' : 'FAIL'}(rise=${(m.windRise ?? 0).toFixed(3)}/lim=${(m.kccLimit ?? 0).toFixed(3)}m,+${(m.climbedTo ?? 0).toFixed(1)}m) slipRise=${(m.slipRise ?? 0).toFixed(3)}m ` +
      `perfErg=${r.perfErg.toFixed(1)}ms perfOrigin=${r.perfOrigin.toFixed(1)}ms fails=${r.fails.length}`
    );
    if (r.fails.length) console.log('[dune-slope] ' + JSON.stringify(r.fails.slice(0, 8)));

    // ── vista stubs for the next cycle: stream the erg in, shoot crest / trough /
    //    approach. (Terrain tiles stream on teleport; colliders not needed for a shot.) ──
    await page.evaluate(async (spot) => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      ctx.player.body.body.setTranslation({ x: spot.cx, y: ctx.terrain.heightAt(spot.cx, spot.cz) + 1.6, z: spot.cz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 160; f++) await raf();
      ctx.flags.paused = true;
    }, { cx: r.cx, cz: r.cz });
    const shot = async (name, code) => {
      await page.evaluate(code);
      await page.waitForTimeout(400);
      await page.screenshot({ path: join(OUT, `scen-dune-slope-${name}.png`), timeout: 60000 });
      console.log(`[dune-slope] saved scen-dune-slope-${name}.png`);
    };
    // A helper string: local steepest-ascent unit direction at (x,z) via central diff.
    const upDir = `(x,z)=>{ const ctx=window.__game.ctx; const h=(a,b)=>ctx.terrain.heightAt(a,b); const gx=h(x+3,z)-h(x-3,z), gz=h(x,z+3)-h(x,z-3); const L=Math.hypot(gx,gz)||1; return {x:gx/L, z:gz/L}; }`;
    // crest view — stand on a crest, look ALONG the ridge line (perpendicular to
    // wind) so a colonnade of dunes recedes into the haze (the dune-sea postcard).
    await shot('crest', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const s = window.__ergSpot; const wr = s.windRad;
      let bx = s.cx, bz = s.cz, bh = -1e9;
      for (let t = -160; t <= 160; t += 3) { const x = s.cx + Math.cos(wr)*t, z = s.cz + Math.sin(wr)*t; const h = ctx.terrain.heightAt(x,z); if (h > bh) { bh = h; bx = x; bz = z; } }
      const rv = { x: -Math.sin(wr), z: Math.cos(wr) };   // along the ridge (perp to wind)
      cam.position.set(bx, ctx.terrain.heightAt(bx, bz) + 1.7, bz);
      const tx = bx + rv.x*160, tz = bz + rv.z*160;
      cam.lookAt(tx, ctx.terrain.heightAt(tx, tz) - 6, tz);   // slight downward — fill frame with sand
      cam.updateMatrixWorld(true);
    })()`);
    // trough view — drop into a low sample, look UP the steepest local face so a
    // dune WALL rises and fills the frame (sightline occlusion — the trough read).
    await shot('trough', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const s = window.__ergSpot; const wr = s.windRad; const upDir = ${upDir};
      let bx = s.cx, bz = s.cz, bh = 1e9;
      for (let t = -160; t <= 160; t += 3) { const x = s.cx + Math.cos(wr)*t, z = s.cz + Math.sin(wr)*t; const h = ctx.terrain.heightAt(x,z); if (h < bh) { bh = h; bx = x; bz = z; } }
      const up = upDir(bx, bz);
      cam.position.set(bx, ctx.terrain.heightAt(bx, bz) + 1.7, bz);
      const tx = bx + up.x*80, tz = bz + up.z*80;
      cam.lookAt(tx, ctx.terrain.heightAt(tx, tz) + 8, tz);   // up the face toward the crest
      cam.updateMatrixWorld(true);
    })()`);
    // approach view — stand out on the flat desert just beyond the erg edge and
    // look HORIZONTALLY at the near wall of dunes rising from the flats (the
    // "approaching the dune sea" read). The vantage is ~1.6km from the erg core,
    // OUTSIDE the origin-following sky sphere's last recenter — so we teleport the
    // player to the vantage first (unpaused, to stream terrain + recenter the sky
    // there) BEFORE framing the shot, else the sky renders as a distant dome.
    await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const s = window.__ergSpot;
      const ang = Math.atan2(-s.cz, -s.cx);   // roughly toward origin
      let ex = s.cx, ez = s.cz;               // march out to the erg boundary
      for (let rr = 0; rr <= 2400; rr += 8) { const x = s.cx + Math.cos(ang)*rr, z = s.cz + Math.sin(ang)*rr; if (ctx.biomes.ergAt(x, z) <= 0) { ex = x; ez = z; break; } }
      const ox = ex + Math.cos(ang) * 90, oz = ez + Math.sin(ang) * 90;   // 90m out on the flats
      window.__ergApproach = { ox, oz, tx: ex - Math.cos(ang) * 260, tz: ez - Math.sin(ang) * 260 };
      ctx.flags.paused = false;
      ctx.player.body.body.setTranslation({ x: ox, y: ctx.terrain.heightAt(ox, oz) + 1.6, z: oz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 160; f++) await raf();   // stream + recenter sky at the vantage
      ctx.flags.paused = true;
    });
    await shot('approach', `(() => {
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const a = window.__ergApproach;
      cam.position.set(a.ox, ctx.terrain.heightAt(a.ox, a.oz) + 2.0, a.oz);
      cam.lookAt(a.tx, ctx.terrain.heightAt(a.tx, a.tz) + 10, a.tz);
      cam.updateMatrixWorld(true);
    })()`);
    if (!pass) throw new Error('dune-slope GATE FAILED');
  },

  // ── erg-vista (Deep Desert cycle 3) — the CHECKPOINT vista set Zach approves
  //    scale/feel from. Streams the nearest erg core in at late-afternoon raking
  //    light (dayTime 0.70), hides the HUD chrome, and shoots four well-framed
  //    player's-eye vistas — approach / crest / trough / scale — printing the
  //    LOCAL dune height + wavelength at each spot so numbers ship WITH pictures.
  //    Output: verification/scen-erg-vista-<name>.png.
  //    Run: node scripts/rig-shot.mjs --scenario=erg-vista --port=5262
  'erg-vista': async (page) => {
    // ── clean scene + late-afternoon raking sun + hidden HUD + big canvas ──
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0; try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0;
      g.setTime(0.65);   // late afternoon — raking sun (~37° elev) shows dune form + keeps sand legible
      const css = document.createElement('style');
      css.textContent = '#hud,#hotbar,#crosshair,#dev-mode-badge,#interact-prompt,#damage-vignette,#long-storm-indicator,#shelter-indicator,#toast,#perf-hud,#crafting-menu,#dev-item-panel{display:none!important}';
      document.head.appendChild(css);
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;   // re-enabled only for the scale shot
      ctx.three.renderer.setSize(1600, 900, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1600 / 900; cam.updateProjectionMatrix(); }
    });

    // ── locate the nearest erg core (coarse scan → centroid refine) ──
    const spot = await page.evaluate(() => {
      const bio = window.__game.ctx.biomes;
      let coarse = null, bestD = Infinity;
      for (let x = -24000; x <= 24000; x += 200)
        for (let z = -24000; z <= 24000; z += 200) {
          const dd = x * x + z * z; if (dd < 3000 * 3000) continue;
          if (dd < bestD && bio.ergAt(x, z) > 0.9) { bestD = dd; coarse = { x, z }; }
        }
      if (!coarse) return null;
      let sx = 0, sz = 0, w = 0;
      for (let dx = -400; dx <= 400; dx += 16)
        for (let dz = -400; dz <= 400; dz += 16)
          if (bio.ergAt(coarse.x + dx, coarse.z + dz) > 0.95) { sx += coarse.x + dx; sz += coarse.z + dz; w++; }
      const cx = w ? Math.round(sx / w) : coarse.x, cz = w ? Math.round(sz / w) : coarse.z;
      const info = bio.ergInfoAt(cx, cz);
      return { cx, cz, windRad: info ? info.windRad : 0, dist: Math.round(Math.hypot(cx, cz)) };
    });
    if (!spot) throw new Error('erg-vista: NO erg found within a 24km scan');
    console.log(`[erg-vista] erg core @(${spot.cx},${spot.cz}) ${spot.dist}m from origin, wind=${(spot.windRad * 180 / Math.PI).toFixed(0)}°`);
    await page.evaluate((s) => { window.__ergVista = s; }, spot);

    // ── stream the core in (teleport past the anchor margin → ring re-anchors) ──
    await page.evaluate(async (s) => {
      const ctx = window.__game.ctx; ctx.flags.paused = false;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      ctx.player.body.body.setTranslation({ x: s.cx, y: ctx.terrain.heightAt(s.cx, s.cz) + 1.6, z: s.cz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 200; f++) await raf();   // stream the 3×3 tile ring + recenter sky
      ctx.flags.paused = true;
    }, spot);

    // Shared in-page helpers, re-declared per shot (each page.evaluate is isolated):
    //   duneMetrics(cx,cz,windRad) → {height, wavelength} from a ±300m wind transect.
    const HELPERS = `
      const ctx = window.__game.ctx; const cam = ctx.three.camera; ctx.flags.paused = true;
      const h = (x, z) => ctx.terrain.heightAt(x, z);
      const duneMetrics = (px, pz, wr) => {
        const wx = Math.cos(wr), wz = Math.sin(wr);
        const prof = [];
        for (let t = -300; t <= 300; t += 2) prof.push({ t, y: h(px + wx * t, pz + wz * t) });
        const WW = 4; const ext = [];
        for (let i = WW; i < prof.length - WW; i++) {
          let isMax = true, isMin = true;
          for (let k = i - WW; k <= i + WW; k++) { if (prof[k].y > prof[i].y + 1e-6) isMax = false; if (prof[k].y < prof[i].y - 1e-6) isMin = false; }
          if (isMax) ext.push({ t: prof[i].t, y: prof[i].y, kind: 'max' });
          else if (isMin) ext.push({ t: prof[i].t, y: prof[i].y, kind: 'min' });
        }
        const ded = [];
        for (const e of ext) { const l = ded[ded.length - 1]; if (l && l.kind === e.kind) { if (e.kind === 'max' ? e.y > l.y : e.y < l.y) ded[ded.length - 1] = e; } else ded.push(e); }
        const amps = [], spac = []; let lastMax = null;
        for (let i = 1; i < ded.length; i++) { const d = Math.abs(ded[i].y - ded[i - 1].y); if (d > 4) amps.push(d); }
        for (const e of ded) { if (e.kind === 'max') { if (lastMax) spac.push(Math.abs(e.t - lastMax)); lastMax = e.t; } }
        const med = (a) => { if (!a.length) return NaN; const s = a.slice().sort((u, v) => u - v); return s[Math.floor(s.length / 2)]; };
        return { height: med(amps), wavelength: med(spac) };
      };
    `;
    const shoot = async (name, code) => {
      const meta = await page.evaluate('(() => {' + HELPERS + code + '})()');
      await page.waitForTimeout(450);
      await page.screenshot({ path: join(OUT, `scen-erg-vista-${name}.png`), timeout: 60000 });
      const hStr = Number.isFinite(meta.height) ? meta.height.toFixed(1) : '?';
      const wStr = Number.isFinite(meta.wavelength) ? meta.wavelength.toFixed(0) : '?';
      console.log(`[erg-vista] ${name}: dune height ~${hStr}m · wavelength ~${wStr}m  → scen-erg-vista-${name}.png  ${meta.note || ''}`);
      return meta;
    };

    // 1) CREST — stand on the tallest local mega-dune crest, look DOWNWIND so the
    //    slip face drops away underfoot and the sea of crests recedes to the haze.
    await shoot('crest', `
      const s = window.__ergVista; const wr = s.windRad; const wx = Math.cos(wr), wz = Math.sin(wr);
      const rx = -Math.sin(wr), rz = Math.cos(wr);                 // along ridge (toward the lit horizon)
      let bx = s.cx, bz = s.cz, by = -1e9;
      for (let t = -200; t <= 200; t += 3) { const x = s.cx + wx * t, z = s.cz + wz * t; const y = h(x, z); if (y > by) { by = y; bx = x; bz = z; } }
      cam.position.set(bx, h(bx, bz) + 1.7, bz);
      // diagonal: ridge axis (lit) blended with downwind (slip face drops away underfoot)
      let dxk = rx + wx * 0.6, dzk = rz + wz * 0.6; const dl = Math.hypot(dxk, dzk); dxk /= dl; dzk /= dl;
      const tx = bx + dxk * 320, tz = bz + dzk * 320;
      cam.lookAt(tx, h(tx, tz) - 7, tz);                          // gentle down-tilt: corrugated sea recedes
      cam.updateMatrixWorld(true);
      return duneMetrics(bx, bz, wr);
    `);

    // 2) TROUGH — drop into the lowest local interdune, look ALONG the ridge axis
    //    (perpendicular to wind) so dune WALLS flank both sides and occlude the
    //    horizon — the lost-in-the-dunes read.
    await shoot('trough', `
      const s = window.__ergVista; const wr = s.windRad; const wx = Math.cos(wr), wz = Math.sin(wr);
      const rx = -Math.sin(wr), rz = Math.cos(wr);                 // along ridge (perp to wind)
      let bx = s.cx, bz = s.cz, by = 1e9;
      for (let t = -200; t <= 200; t += 3) { const x = s.cx + wx * t, z = s.cz + wz * t; const y = h(x, z); if (y < by) { by = y; bx = x; bz = z; } }
      cam.position.set(bx, h(bx, bz) + 1.7, bz);
      const tx = bx + rx * 160, tz = bz + rz * 160;
      cam.lookAt(tx, h(tx, tz) + 6, tz);                           // slight up: walls rise, sky slot narrows
      cam.updateMatrixWorld(true);
      return duneMetrics(bx, bz, wr);
    `);

    // 3) SCALE — the player figure at a trough base with a mega-dune towering
    //    behind (human ~1.8m against a ~45m dune = the scale read). Re-enable the
    //    rig, face it into the dune, camera behind + above looking past it.
    await shoot('scale', `
      const s = window.__ergVista; const wr = s.windRad; const wx = Math.cos(wr), wz = Math.sin(wr);
      // trough base near core, and the crest it faces (upwind, higher-ground side)
      let bx = s.cx, bz = s.cz, by = 1e9;
      for (let t = -200; t <= 200; t += 3) { const x = s.cx + wx * t, z = s.cz + wz * t; const y = h(x, z); if (y < by) { by = y; bx = x; bz = z; } }
      // steepest-ascent direction at the trough (toward the near dune wall)
      const gx = h(bx + 4, bz) - h(bx - 4, bz), gz = h(bx, bz + 4) - h(bx, bz - 4);
      const gl = Math.hypot(gx, gz) || 1; const ux = gx / gl, uz = gz / gl;
      // place the player body at the trough, facing up the dune
      const py = h(bx, bz);
      ctx.player.body.body.setTranslation({ x: bx, y: py + 1.0, z: bz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      if (ctx.player.rig) { ctx.player.rig.group.visible = true; ctx.player.rig.group.position.set(bx, py, bz); ctx.player.rig.group.rotation.y = Math.atan2(ux, uz); }
      // camera behind + above the figure, looking past it up the dune face
      cam.position.set(bx - ux * 7, py + 3.0, bz - uz * 7);
      const tx = bx + ux * 80, tz = bz + uz * 80;
      cam.lookAt(tx, h(tx, tz) + 14, tz);
      cam.updateMatrixWorld(true);
      return duneMetrics(bx, bz, wr);
    `);

    // 4) APPROACH — teleport OUT onto the flat desert beyond the erg edge (stream
    //    + recenter the sky there), then look horizontally at the near wall of
    //    mega-dunes rising from the flats (the "entering the erg" moment).
    await page.evaluate(async () => {
      const ctx = window.__game.ctx; const bio = ctx.biomes;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const s = window.__ergVista;
      const wr = s.windRad;
      // Front-light the wall: choose the edge azimuth pointing most toward the SUN
      // (so looking inward at the dunes has the sun behind the camera → warm lit
      // faces, not a shadowed lump). sunDir.xz points toward the sun.
      const sd = ctx.time.sunDir; let sax = sd.x, saz = sd.z; const sl = Math.hypot(sax, saz) || 1; sax /= sl; saz /= sl;
      let best = null;
      for (let a = 0; a < Math.PI * 2; a += Math.PI / 24) {
        const dx = Math.cos(a), dz = Math.sin(a);
        // CROSS-LIGHT the wall: outward ~perpendicular to the sun, so the inward
        // view has the low sun off to one side → lit windward faces + shadowed
        // slip faces = the corrugated sea reads as sand (the same oblique light
        // that makes the crest/trough shots work). Reward perpendicular alignment.
        const sunAlign = -Math.abs(dx * sax + dz * saz);
        // march to the erg boundary along this azimuth
        let ex = s.cx, ez = s.cz;
        for (let rr = 0; rr <= 2400; rr += 8) { const x = s.cx + dx * rr, z = s.cz + dz * rr; if (bio.ergAt(x, z) <= 0) { ex = x; ez = z; break; } }
        // tallest dune in the 500m just inside this edge (for aim framing)
        let tall = -1e9, tx = ex, tz = ez;
        for (let rr = -500; rr <= -60; rr += 20) { const x = ex + dx * rr, z = ez + dz * rr; const y = ctx.terrain.heightAt(x, z); if (y > tall) { tall = y; tx = x; tz = z; } }
        // score: front-lighting dominates, a modest tall-dune bonus breaks ties
        const score = sunAlign * 10 + tall * 0.02;
        if (!best || score > best.score) best = { score, a, dx, dz, ex, ez, tall, tx, tz };
      }
      const ox = best.ex + best.dx * 180, oz = best.ez + best.dz * 180;   // 180m out — clean flats in the foreground
      window.__ergApproach = { ox, oz, ex: best.ex, ez: best.ez, dx: best.dx, dz: best.dz, tx: best.tx, tz: best.tz, wr };
      ctx.flags.paused = false;
      ctx.player.body.body.setTranslation({ x: ox, y: ctx.terrain.heightAt(ox, oz) + 1.6, z: oz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      for (let f = 0; f < 200; f++) await raf();   // stream + recenter sky at the vantage
      ctx.flags.paused = true;
    });
    await shoot('approach', `
      const a = window.__ergApproach;
      cam.position.set(a.ox, h(a.ox, a.oz) + 2.0, a.oz);
      // look INTO the erg toward the rising interior sea (~800m inside the edge),
      // aimed slightly up so the front-lit dune mass fills the upper-middle band
      // and the clean flats read as the foreground you're crossing.
      const tx = a.ex - a.dx * 650, tz = a.ez - a.dz * 650;
      cam.lookAt(tx, h(tx, tz) + 30, tz);                         // aim up: cross-lit dune sea fills the frame
      cam.updateMatrixWorld(true);
      // metrics sampled well inside the dune sea
      return duneMetrics(a.ex - a.dx * 700, a.ez - a.dz * 700, a.wr);
    `);
  },

  // ── erg-smoke (Deep Desert cycle 7) — the CREST SMOKE proof + the erg hush +
  //    the first-crest discovery beat. Streams the nearest erg, stands the player
  //    on the tallest local crest, and PROVES: spindrift is visible + crest-riding
  //    (a visible-puff count), it costs ~nothing (frame-ms in erg vs out on the
  //    flats), it CULLS OFF the instant you leave the erg (particles.visible=false),
  //    it never GLOWS at night (uColor darkens with the sun), the erg hush ducks
  //    the calm wind gain (inside < outside), and the discovery line fires ONCE
  //    then never again. Day + night screenshots ship WITH the numbers.
  //    Run: node scripts/rig-shot.mjs --scenario=erg-smoke --port=5271
  'erg-smoke': async (page) => {
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.sandWorms.list.length = 0; try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; ctx.weather.perceivedIntensity = 0;
      const css = document.createElement('style');
      css.textContent = '#hud,#hotbar,#crosshair,#dev-mode-badge,#interact-prompt,#damage-vignette,#long-storm-indicator,#shelter-indicator,#toast,#perf-hud,#crafting-menu,#dev-item-panel{display:none!important}';
      document.head.appendChild(css);
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.three.renderer.setSize(1600, 900, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1600 / 900; cam.updateProjectionMatrix(); }
    });

    // locate the nearest erg core + its tallest local crest
    const spot = await page.evaluate(() => {
      const bio = window.__game.ctx.biomes, terr = window.__game.ctx.terrain;
      let coarse = null, bestD = Infinity;
      for (let x = -24000; x <= 24000; x += 200)
        for (let z = -24000; z <= 24000; z += 200) {
          const dd = x * x + z * z; if (dd < 3000 * 3000) continue;
          if (dd < bestD && bio.ergAt(x, z) > 0.9) { bestD = dd; coarse = { x, z }; }
        }
      if (!coarse) return null;
      const info = bio.ergInfoAt(coarse.x, coarse.z);
      // Find the tallest crest (max prominence over a 60m ring) in a grid around core.
      const prom = (x, z) => {
        const c = terr.heightAt(x, z); let s = 0;
        for (let d = 0; d < 6; d++) { const a = d / 6 * Math.PI * 2; s += terr.heightAt(x + Math.cos(a) * 60, z + Math.sin(a) * 60); }
        return c - s / 6;
      };
      let best = null, bp = -1e9;
      for (let dx = -600; dx <= 600; dx += 24)
        for (let dz = -600; dz <= 600; dz += 24) {
          const x = coarse.x + dx, z = coarse.z + dz;
          if (bio.ergAt(x, z) < 0.9) continue;
          const p = prom(x, z);
          if (p > bp) { bp = p; best = { x, z }; }
        }
      return { cx: best.x, cz: best.z, prom: +bp.toFixed(1), windRad: info ? info.windRad : 0, dist: Math.round(Math.hypot(best.x, best.z)) };
    });
    if (!spot) throw new Error('erg-smoke: NO erg found within a 24km scan');
    console.log(`[erg-smoke] crest @(${spot.cx},${spot.cz}) ${spot.dist}m out, prominence=${spot.prom}m, wind=${(spot.windRad * 180 / Math.PI).toFixed(0)}°`);
    await page.evaluate((s) => { window.__ergSmoke = s; }, spot);

    // stream the crest in + let the smoke seed, then read state + day perf
    const dayInfo = await page.evaluate(async (s) => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      window.__game.setTime(0.62);   // afternoon raking light
      ctx.flags.paused = false;
      ctx.player.body.body.setTranslation({ x: s.cx, y: ctx.terrain.heightAt(s.cx, s.cz) + 1.7, z: s.cz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 200; f++) await raf();   // stream + seed the spindrift
      const cs = ctx.crestSmoke;
      const pos = cs.particles.geometry.attributes.position.array;
      const al = cs.particles.geometry.attributes.aAlpha.array;
      let visible = 0, aboveGround = 0;
      for (let i = 0; i < al.length; i++) {
        if (pos[i * 3 + 1] > -9000) aboveGround++;
        if (al[i] > 0.02 && pos[i * 3 + 1] > -9000) visible++;
      }
      // day perf: median frame ms over 120 frames (smoke ON)
      const ms = [];
      let last = performance.now();
      for (let f = 0; f < 120; f++) { await raf(); const n = performance.now(); ms.push(n - last); last = n; }
      ms.sort((a, b) => a - b);
      const col = cs.mat.uniforms.uColor.value;
      return {
        layerVisible: cs.particles.visible, pool: al.length, aboveGround, visiblePuffs: visible,
        dayMedMs: +ms[60].toFixed(2), dayColor: [+col.r.toFixed(3), +col.g.toFixed(3), +col.b.toFixed(3)],
        opacity: +cs.mat.uniforms.uOpacity.value.toFixed(3),
      };
    }, spot);

    // frame the crest looking DOWNWIND across the slip face (spindrift streams off
    // the lip toward the haze), then PAUSE so the rig stays hidden + camera holds.
    const frameCrest = () => {
      const ctx = window.__game.ctx, cam = ctx.three.camera, s = window.__ergSmoke;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      const wr = s.windRad, wx = Math.cos(wr), wz = Math.sin(wr);
      // eye just behind + above the crest, looking downwind + slightly down the slip face
      cam.position.set(s.cx - wx * 6, ctx.terrain.heightAt(s.cx, s.cz) + 3.2, s.cz - wz * 6);
      const tx = s.cx + wx * 90, tz = s.cz + wz * 90;
      cam.lookAt(tx, ctx.terrain.heightAt(tx, tz) + 2, tz);
      cam.updateMatrixWorld(true);
      ctx.flags.paused = true;
    };
    await page.evaluate(frameCrest);
    await page.waitForTimeout(400);
    await page.screenshot({ path: join(OUT, 'scen-erg-smoke-day.png'), timeout: 60000 });
    console.log('[erg-smoke] saved scen-erg-smoke-day.png');

    // NIGHT — assert no glow (uColor darkens); re-seed the smoke at midnight (unpause
    // → run frames → re-frame → pause), then screenshot.
    const nightInfo = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      ctx.flags.paused = false;
      window.__game.setTime(0.0);   // midnight
      for (let f = 0; f < 80; f++) await raf();
      const col = ctx.crestSmoke.mat.uniforms.uColor.value;
      return { nightColor: [+col.r.toFixed(3), +col.g.toFixed(3), +col.b.toFixed(3)] };
    });
    await page.evaluate(frameCrest);
    await page.waitForTimeout(400);
    await page.screenshot({ path: join(OUT, 'scen-erg-smoke-night.png'), timeout: 60000 });
    console.log('[erg-smoke] saved scen-erg-smoke-night.png');
    // unpause for the remaining runtime checks (cull / hush / discovery)
    await page.evaluate(() => { window.__game.ctx.flags.paused = false; });

    // CULL — teleport far out onto the open flats; smoke must switch OFF. Also the
    // "far perf" baseline for the frame-cost delta.
    const cullInfo = await page.evaluate(async () => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      window.__game.setTime(0.62);
      ctx.player.body.body.setTranslation({ x: 0, y: ctx.terrain.heightAt(0, 0) + 1.7, z: 0 }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 120; f++) await raf();
      const ms = []; let last = performance.now();
      for (let f = 0; f < 120; f++) { await raf(); const n = performance.now(); ms.push(n - last); last = n; }
      ms.sort((a, b) => a - b);
      return { layerVisible: ctx.crestSmoke.particles.visible, farMedMs: +ms[60].toFixed(2) };
    });

    // ERG HUSH — read the calm wind body gain inside the erg vs on the flats.
    const hush = await page.evaluate(async (s) => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      const read = () => { try { return window.__game.audioState(); } catch { return null; } };
      // outside (still at origin from the cull step) — settle the hush lerp
      ctx.weather.intensity = 0; ctx.weather.perceivedIntensity = 0;
      for (let f = 0; f < 160; f++) await raf();
      const out = read();
      // inside the erg core — settle again
      ctx.player.body.body.setTranslation({ x: s.cx, y: ctx.terrain.heightAt(s.cx, s.cz) + 1.7, z: s.cz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      for (let f = 0; f < 220; f++) await raf();
      const ins = read();
      // The desert WIND bed is muted (WIND_*_MASTER=0), so the audible ambience is
      // the MUSIC pad — that's what the hush ducks. The sand-sigh (howl) rises.
      const mus = (o) => o ? +o.gains.musicCalm.toFixed(4) : null;
      return {
        audioLive: !!out,
        outHush: out ? +out.ergHush.toFixed(3) : null, inHush: ins ? +ins.ergHush.toFixed(3) : null,
        outMusic: mus(out), inMusic: mus(ins),
        outHowl: out && out.pwind ? +out.pwind.howlGain.toFixed(4) : null,
        inHowl: ins && ins.pwind ? +ins.pwind.howlGain.toFixed(4) : null,
      };
    }, spot);

    // DISCOVERY — reset the tutorial flag, spy the toast, crest ONCE → fire, then
    // move off + back on → must NOT re-fire (flag persists = reload-proof).
    const disco = await page.evaluate(async (s) => {
      const ctx = window.__game.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(r));
      try { window.__game.resetTutorial(); } catch {}
      window.__dd = 0;
      const orig = ctx.ui.showToast;
      ctx.ui.showToast = (t, o) => { if (t === 'the deep desert') window.__dd++; return orig ? orig(t, o) : undefined; };
      const flag = () => { try { const r = JSON.parse(localStorage.getItem('dustfall.tutorial.v1') || '{}'); return Array.isArray(r.usedItems) && r.usedItems.includes('_evt_erg_first_crest'); } catch { return false; } };
      // stand on the crest (prominence high, erg core) — fire
      ctx.player.body.body.setTranslation({ x: s.cx, y: ctx.terrain.heightAt(s.cx, s.cz) + 1.7, z: s.cz }, true);
      for (let f = 0; f < 90; f++) await raf();
      const firedFlag = flag();
      await new Promise((r) => setTimeout(r, 1200));   // let the 900ms toast timeout land
      const toast1 = window.__dd;
      // drop into a trough (low prominence) then climb the SAME crest again
      const wr = s.windRad, wx = Math.cos(wr), wz = Math.sin(wr);
      ctx.player.body.body.setTranslation({ x: s.cx + wx * 150, y: ctx.terrain.heightAt(s.cx + wx * 150, s.cz + wz * 150) + 1.7, z: s.cz + wz * 150 }, true);
      for (let f = 0; f < 60; f++) await raf();
      ctx.player.body.body.setTranslation({ x: s.cx, y: ctx.terrain.heightAt(s.cx, s.cz) + 1.7, z: s.cz }, true);
      for (let f = 0; f < 90; f++) await raf();
      await new Promise((r) => setTimeout(r, 1200));
      const toast2 = window.__dd;
      ctx.ui.showToast = orig;
      return { firedFlag, toast1, toast2, flagPersists: flag() };
    }, spot);

    // ── verdict ──
    const fails = [];
    if (!dayInfo.layerVisible) fails.push('smoke layer not visible in the erg');
    if (dayInfo.visiblePuffs < 8) fails.push(`too few visible puffs (${dayInfo.visiblePuffs})`);
    if (cullInfo.layerVisible) fails.push('smoke did NOT cull off outside the erg');
    // night glow: night color must be clearly DARKER than day color (sum of channels)
    const daySum = dayInfo.dayColor.reduce((a, b) => a + b, 0);
    const nightSum = nightInfo.nightColor.reduce((a, b) => a + b, 0);
    if (nightSum > daySum * 0.5) fails.push(`night glow: night color ${nightInfo.nightColor} not dark vs day ${dayInfo.dayColor}`);
    if (hush.audioLive) {
      if (!(hush.inHush > hush.outHush + 0.2)) fails.push(`hush factor did not rise inside erg (in=${hush.inHush} out=${hush.outHush})`);
      // audible ambience (the music pad) must DUCK inside; the deep sand-sigh (howl) must RISE inside.
      if (hush.inMusic != null && hush.outMusic != null && !(hush.inMusic < hush.outMusic * 0.9)) fails.push(`music not ducked inside erg (in=${hush.inMusic} out=${hush.outMusic})`);
      if (hush.inHowl != null && hush.outHowl != null && !(hush.inHowl > hush.outHowl + 0.002)) fails.push(`sand-sigh did not rise inside (in=${hush.inHowl} out=${hush.outHowl})`);
    }
    if (!disco.firedFlag) fails.push('discovery flag not set on first crest');
    if (disco.toast1 !== 1) fails.push(`discovery toast fired ${disco.toast1}× on first crest (want 1)`);
    if (disco.toast2 !== 1) fails.push(`discovery re-fired (toast count ${disco.toast2}) on second crest`);
    if (!disco.flagPersists) fails.push('discovery flag did not persist (reload would re-fire)');
    const pass = fails.length === 0;
    console.log(`ERG-SMOKE pass=${pass ? 1 : 0} pool=${dayInfo.pool} visiblePuffs=${dayInfo.visiblePuffs} opacity=${dayInfo.opacity} perf(inErg=${dayInfo.dayMedMs}ms far=${cullInfo.farMedMs}ms delta=${(dayInfo.dayMedMs - cullInfo.farMedMs).toFixed(2)}ms) cull=${cullInfo.layerVisible ? 'ON!' : 'off'} nightColor=${JSON.stringify(nightInfo.nightColor)} dayColor=${JSON.stringify(dayInfo.dayColor)} hush(audio=${hush.audioLive} ergHush in=${hush.inHush}/out=${hush.outHush} music in=${hush.inMusic}/out=${hush.outMusic} sigh in=${hush.inHowl}/out=${hush.outHowl}) disco(flag=${disco.firedFlag} t1=${disco.toast1} t2=${disco.toast2} persist=${disco.flagPersists}) fails=${fails.length}`);
    console.log(`[erg-smoke] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(fails)}`);
    if (!pass) throw new Error('erg-smoke GATE FAILED');
  },

  // ── erg-dress (Deep Desert cycle 7) — the sparse TROUGH DRESSING proof. Scans
  //    describeChunk over a large erg area: counts finds vs troughs (sparse:
  //    target < ~1 per 2-3 troughs), asserts the descriptor is STABLE across two
  //    derivations (determinism), confirms every find sits in the erg biome on a
  //    trough floor (never a crest), and shoots ONE dressed trough as a picture.
  //    Run: node scripts/rig-shot.mjs --scenario=erg-dress --seed=1337 --port=5273
  'erg-dress': async (page) => {
    const scan = await page.evaluate(() => {
      const g = window.__game, ctx = g.ctx, bio = ctx.biomes, terr = ctx.terrain;
      // find the nearest erg core
      let core = null, bestD = Infinity;
      for (let x = -24000; x <= 24000; x += 200)
        for (let z = -24000; z <= 24000; z += 200) {
          const dd = x * x + z * z; if (dd < 3000 * 3000) continue;
          if (dd < bestD && bio.ergAt(x, z) > 0.9) { bestD = dd; core = { x, z }; }
        }
      if (!core) return null;
      const SIZE = 112;
      const ccx = Math.floor(core.x / SIZE), ccz = Math.floor(core.z / SIZE);
      // radius in chunks covering the ~1500m erg radius (+margin)
      const RC = 16;
      let ergChunks = 0, troughChunks = 0, finds = 0, mismatch = 0, offBiome = 0, notTrough = 0;
      const kinds = { wreck: 0, bone: 0, tree: 0 };
      const found = [];
      const troughDrop = (x, z) => {
        const c = terr.pureHeightAt(x, z), R = 82;
        const avg = (terr.pureHeightAt(x + R, z) + terr.pureHeightAt(x - R, z) + terr.pureHeightAt(x, z + R) + terr.pureHeightAt(x, z - R)) / 4;
        return avg - c;
      };
      for (let dcx = -RC; dcx <= RC; dcx++)
        for (let dcz = -RC; dcz <= RC; dcz++) {
          const cx = ccx + dcx, cz = ccz + dcz;
          const centerX = (cx + 0.5) * SIZE, centerZ = (cz + 0.5) * SIZE;
          const isErg = bio.ergAt(centerX, centerZ) > 0.5;
          if (isErg) ergChunks++;
          // a chunk "has a trough" if its center sits meaningfully below its ring
          if (isErg && troughDrop(centerX, centerZ) >= 6) troughChunks++;
          const a = JSON.stringify(g.chunkDescribe(cx, cz));
          const b = JSON.stringify(g.chunkDescribe(cx, cz));
          if (a !== b) mismatch++;
          const d = g.chunkDescribe(cx, cz);
          if (d.ergDressing) {
            finds++;
            kinds[d.ergDressing.kind] = (kinds[d.ergDressing.kind] || 0) + 1;
            const ex = d.ergDressing.x, ez = d.ergDressing.z;
            if (bio.biomeAt(ex, ez) !== 'erg') offBiome++;
            if (troughDrop(ex, ez) < 6) notTrough++;
            if (found.length < 40) found.push({ cx, cz, kind: d.ergDressing.kind, x: ex, z: ez });
          }
        }
      return { core, ccx, ccz, ergChunks, troughChunks, finds, mismatch, offBiome, notTrough, kinds, found, seed: ctx.seed };
    });
    if (!scan) throw new Error('erg-dress: NO erg found within a 24km scan');
    const perTrough = scan.troughChunks ? (scan.finds / scan.troughChunks) : 0;
    const fails = [];
    if (scan.mismatch !== 0) fails.push(`${scan.mismatch} chunks unstable across two derivations`);
    if (scan.offBiome !== 0) fails.push(`${scan.offBiome} finds off the erg biome`);
    if (scan.notTrough !== 0) fails.push(`${scan.notTrough} finds NOT on a trough floor`);
    if (scan.finds < 2) fails.push(`too few finds to judge (${scan.finds}) — is the erg big enough?`);
    if (perTrough >= 0.5) fails.push(`too DENSE: ${perTrough.toFixed(2)} finds/trough (want < 0.5)`);
    const pass = fails.length === 0;
    console.log(`ERG-DRESS seed=${scan.seed} ergChunks=${scan.ergChunks} troughChunks=${scan.troughChunks} finds=${scan.finds} perTrough=${perTrough.toFixed(3)} kinds=${JSON.stringify(scan.kinds)} stable=${scan.mismatch === 0} offBiome=${scan.offBiome} notTrough=${scan.notTrough} fails=${fails.length}`);
    console.log(`[erg-dress] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(fails)}`);

    // Hunt a TREE find across a WIDER chunk window (chunkDescribe uses the pure
    // closed-form height, valid anywhere) so we can eyeball the rarest kind's
    // render path even when the local erg didn't happen to roll one.
    const treeFind = await page.evaluate((core) => {
      const g = window.__game, SIZE = 112;
      const ccx = Math.floor(core.x / SIZE), ccz = Math.floor(core.z / SIZE);
      for (let rc = 1; rc <= 130; rc++) {
        for (let dcx = -rc; dcx <= rc; dcx++)
          for (let dcz = -rc; dcz <= rc; dcz++) {
            if (Math.max(Math.abs(dcx), Math.abs(dcz)) !== rc) continue;   // ring shell only
            const d = g.chunkDescribe(ccx + dcx, ccz + dcz);
            if (d.ergDressing && d.ergDressing.kind === 'tree') return { cx: ccx + dcx, cz: ccz + dcz, kind: 'tree', x: d.ergDressing.x, z: d.ergDressing.z };
          }
      }
      return null;
    }, scan.core);
    if (treeFind) { console.log(`[erg-dress] tree find located @(${Math.round(treeFind.x)},${Math.round(treeFind.z)}) — rendering it`); scan.found.unshift(treeFind); }

    // shoot ONE dressed trough (if any) — prefer a TREE find (rarest, worth
    // eyeballing its render path), else the first find. Stream the chunk + frame it.
    if (scan.found.length) {
      const pick = scan.found.find((f) => f.kind === 'tree') || scan.found[0];
      await page.evaluate(() => {
        const ctx = window.__game.ctx;
        const css = document.createElement('style');
        css.textContent = '#hud,#hotbar,#crosshair,#dev-mode-badge,#interact-prompt,#damage-vignette,#toast,#perf-hud{display:none!important}';
        document.head.appendChild(css);
        if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
        if (ctx.player.rig) ctx.player.rig.group.visible = false;
        ctx.three.renderer.setSize(1600, 900, false);
        const cam = ctx.three.camera; if (cam.isPerspectiveCamera) { cam.aspect = 1600 / 900; cam.updateProjectionMatrix(); }
        window.__game.setTime(0.6);
      });
      await page.evaluate(async (p) => {
        const ctx = window.__game.ctx;
        const raf = () => new Promise((r) => requestAnimationFrame(r));
        ctx.flags.paused = false;
        ctx.player.body.body.setTranslation({ x: p.x, y: ctx.terrain.heightAt(p.x, p.z) + 1.7, z: p.z }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        for (let f = 0; f < 200; f++) await raf();   // stream the chunk containing the find
        const cam = ctx.three.camera;
        cam.position.set(p.x + 8, ctx.terrain.heightAt(p.x + 8, p.z + 8) + 3, p.z + 8);
        cam.lookAt(p.x, ctx.terrain.heightAt(p.x, p.z) + 0.6, p.z);
        cam.updateMatrixWorld(true);
        ctx.flags.paused = true;
      }, pick);
      await page.waitForTimeout(400);
      await page.screenshot({ path: join(OUT, `scen-erg-dress-${pick.kind}.png`), timeout: 60000 });
      console.log(`[erg-dress] saved scen-erg-dress-${pick.kind}.png (a ${pick.kind} in a trough @(${Math.round(pick.x)},${Math.round(pick.z)}))`);
    }
    if (!pass) throw new Error('erg-dress GATE FAILED');
  },

  // ── bone-scatter — the strewn bone-bit GALLERY (bone_field scatter vocabulary).
  //    Builds every BoneBitKind across several seeds in a grid on real terrain +
  //    shoots them, and NUMERICALLY guards the `vertebra` kind against the tall cone
  //    SPIKE Zach flagged in his walk-test ("kill the big-spike scatter bone"): asserts
  //    no vertebra bit's local bbox rises taller than SPIKE_MAX above its base — a
  //    modest weathered nub, never a 2-3m sharp cone.
  //    Run: node scripts/rig-shot.mjs --scenario=bone-scatter --port=5214
  'bone-scatter': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.sandWorms.list.length = 0; try { ctx.vultures.list.length = 0; } catch {}
      ctx.weather.intensity = 0; g.setTime(0.5);
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1180, 780, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1180 / 780; cam.updateProjectionMatrix(); }
    });
    const r = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
      const dynImport = async (url) => {
        try { return await (0, eval)(`import(${JSON.stringify(url)})`); }
        catch (e) {
          if (e && /module|import/i.test(String(e.message)) === false) throw e;
          return await new Promise((resx, rej) => {
            const key = '__si_' + Math.random().toString(36).slice(2);
            const s = document.createElement('script'); s.type = 'module';
            s.textContent = `import * as m from ${JSON.stringify(url)}; window[${JSON.stringify(key)}]=m; window.dispatchEvent(new Event(${JSON.stringify(key)}));`;
            const t = setTimeout(() => { cleanup(); rej(new Error('import timeout ' + url)); }, 20000);
            const onEvt = () => { const m = window[key]; cleanup(); resx(m); };
            function cleanup() { clearTimeout(t); window.removeEventListener(key, onEvt); s.remove(); delete window[key]; }
            window.addEventListener(key, onEvt);
            document.head.appendChild(s);
          });
        }
      };
      const scat = await dynImport('/src/world/boneScatter.ts');
      const rngm = await dynImport('/src/core/rng.ts');
      const bp = ctx.player.body.body.translation();
      const ox = bp.x + 26, oz = bp.z + 8;
      const kinds = scat.BONE_BIT_KINDS;
      const SEEDS = 6;
      const root = new THREE.Group(); root.name = 'boneScatterGallery';
      const tallest = {};                     // per-kind max local bbox height (informational)
      const cones = {};                       // per-kind ConeGeometry mesh count
      for (let ki = 0; ki < kinds.length; ki++) {
        const kind = kinds[ki];
        for (let si = 0; si < SEEDS; si++) {
          const bit = scat.buildBoneBit(kind, rngm.makeRng(0x51c0 + ki * 131 + si * 17));
          bit.traverse((o) => { if (o.isMesh && o.geometry && o.geometry.type === 'ConeGeometry') cones[kind] = (cones[kind] || 0) + 1; });
          const box = new THREE.Box3().setFromObject(bit);
          tallest[kind] = Math.max(tallest[kind] || 0, box.max.y - box.min.y);
          const wx = ox + si * 3.4, wz = oz + ki * 3.4;
          bit.position.set(wx, ctx.terrain.heightAt(wx, wz) - box.min.y + 0.02, wz);
          root.add(bit);
        }
      }
      ctx.three.scene.add(root);
      root.updateMatrixWorld(true);
      window.__scatGallery = { ox, oz, kinds, cols: SEEDS };
      // The SPIKE fix guard: the vertebra kind must contain ZERO ConeGeometry — the
      // sharp cone-blade spike Zach flagged is removed (its drum/endplates/girdle read
      // carries the vertebra on its own). Cones on the `spine` kind (its small neural
      // spines) are APPROVED and not guarded here.
      const vertCones = cones['vertebra'] || 0;
      const fails = [];
      if (vertCones > 0) fails.push(`vertebra still has ${vertCones} ConeGeometry mesh(es) across ${SEEDS} seeds — a cone spike remains`);
      return { fails, tallest: Object.fromEntries(Object.entries(tallest).map(([k, v]) => [k, +v.toFixed(2)])), cones, vertCones };
    });
    const pass = r.fails.length === 0;
    console.log(`BONE-SCATTER pass=${pass ? 1 : 0} vertebraCones=${r.vertCones} cones=${JSON.stringify(r.cones)} heights=${JSON.stringify(r.tallest)} fails=${r.fails.length}`);
    if (r.fails.length) console.log('[bone-scatter] ' + JSON.stringify(r.fails));
    // Shoot the gallery: a low 3/4 angle across the grid (catches any tall spike on the
    // horizon) + a top-down-ish read.
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx; const info = window.__scatGallery; if (!info) return;
      ctx.flags.paused = true;                          // freeze so the follow-cam tick can't overwrite our frame
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      const cam = ctx.three.camera;
      const midX = info.ox + (info.cols - 1) * 3.4 * 0.5, midZ = info.oz + 2 * 3.4;
      cam.position.set(midX - 4, ctx.terrain.heightAt(midX - 4, midZ - 11) + 3.0, midZ - 11);
      cam.lookAt(midX, ctx.terrain.heightAt(midX, midZ) + 0.4, midZ);
      cam.updateMatrixWorld(true);
    });
    await page.waitForTimeout(450);
    await page.screenshot({ path: join(OUT, 'scen-bone-scatter-gallery.png'), timeout: 60000 });
    console.log('[bone-scatter] saved scen-bone-scatter-gallery.png');
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx; const info = window.__scatGallery; if (!info) return;
      ctx.flags.paused = true;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      const cam = ctx.three.camera;
      const midX = info.ox + (info.cols - 1) * 3.4 * 0.5, midZ = info.oz + 2 * 3.4;
      cam.position.set(midX, ctx.terrain.heightAt(midX, midZ) + 13, midZ + 0.5);
      cam.lookAt(midX, ctx.terrain.heightAt(midX, midZ), midZ);
      cam.updateMatrixWorld(true);
    });
    await page.waitForTimeout(400);
    await page.screenshot({ path: join(OUT, 'scen-bone-scatter-top.png'), timeout: 60000 });
    console.log('[bone-scatter] saved scen-bone-scatter-top.png');
    if (!pass) throw new Error('bone-scatter GATE FAILED');
  },

  // FLOW-CLARITY (action-beat framing audit): drive each REAL action beat to its PROMPT
  // moment and shoot the ACTUAL viewpoint the game gives the player (the beat's own
  // faceControl pose — NOT a rig-substituted lookAt, per D165). Answers "when the prompt
  // fires, can the player SEE where to go / what to do?". --beat=checkEngines|corridor|
  // enterPod|wake (default all four in one run). No camera override: reads camera.rotation
  // as the game left it + reports yaw so direction is checkable.
  'flow-clarity': async (page) => {
    const which = argv.beat ? [String(argv.beat)] : ['checkEngines', 'corridor', 'enterPod', 'wake'];
    const flowAngle = argv.angle || 'hatch';
    await page.evaluate((a) => { window.__FLOW_ANGLE = a; }, flowAngle);
    const results = [];
    for (const beat of which) {
      const meas = await page.evaluate(async (beat) => {
        const g = window.__game;
        const ctx = g.ctx;
        const V = ctx.three.camera.position.constructor;
        // clean render: no weather streaks, FP (hide rig/viewmodel), warm-ish exposure.
        ctx.flags.thirdPerson = false;
        if (ctx.player.rig) ctx.player.rig.group.visible = false;
        if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
        try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
        try { ctx.three.renderer.toneMappingExposure = 1.1; } catch {}
        ctx.three.renderer.setSize(1100, 760, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 760; cam.updateProjectionMatrix(); }
        const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
        ctx.flags.paused = false;           // UNPAUSE — the prior iteration paused to freeze for its shot;
                                            //   the intro beat controllers only tick while unpaused.
        ctx.input.controls.isLocked = true; // keep isPlaying()===true so updateEscapePodIntro ticks
        try { g.skipIntro(); } catch {}     // FULL teardown of any prior iteration's intro (no state bleed)
        await sleep(250);
        // Helper: build the ship interior + seat at the bridge, waiting until getShipSpawn takes
        //   (the cockpit tick reseats to y≈3000). Retries the jump if the async tick raced.
        const seatInShip = async () => {
          g.startIntro();
          g.jumpToBeat('cockpit');
          for (let i = 0; i < 20; i++) {
            await sleep(120);
            const t = ctx.player.body.body.translation();
            if (t.y > 2900) return true;    // seated in the ship (SHIP_ORIGIN.y=3000)
            g.jumpToBeat('cockpit');        // nudge the init again
          }
          return false;
        };

        if (beat === 'checkEngines') {
          // Drive the REAL cockpit→checkEngines transition so the camera is EXACTLY where
          // the game leaves it when "check the engines (aft)" fires (inherited from the
          // cockpit's opening faceControl — the game does NOT reframe on checkEngines).
          await seatInShip();
          try { g.setSkyIntroMode(1); } catch {}   // in orbit — the window shows space
          await sleep(300);                 // let the open framing settle
          g.jumpToBeat('checkEngines');     // fires the prompt; mode→walk; NO faceControl
          await sleep(250);                 // let the beat tick set the prompt/mode
        } else if (beat === 'corridor') {
          // Realistic pose at the disaster trigger: the player walked AFT to the dead-end
          // (facing +Z, aft). Fire the disaster + shoot what they see when "GET TO THE
          // ESCAPE POD" appears (they're facing the fire; the pod-bay is behind them fwd).
          await seatInShip();
          try { g.setSkyIntroMode(0); } catch {}   // interior beat — normal lighting, not the space skybox
          await sleep(200);
          const sp = ctx.player.body.body.translation();   // the FRESH cockpit spawn (bridge)
          g.jumpToBeat('corridor');
          try { g.setEngineFire(1, 2.1); g.setShipAlert(2, 0.9); g.setCockpitAlert(2); } catch {}
          // The disaster erupts at the aft dead-end; the player TURNS AND FLEES FORWARD (−Z)
          // toward the bridge/pod. --angle=fire → face aft at the blaze (the trigger view);
          // default → the FLEE view: mid-corridor facing forward −Z (is the pod signposted
          // ahead as they run for it?). The pod-bay is on the −X wall at z≈4.8.
          cam.rotation.order = 'YXZ';
          if ((window.__FLOW_ANGLE || '') === 'fire') {
            ctx.player.body.body.setTranslation({ x: sp.x, y: sp.y, z: sp.z + 13.4 }, true);
            cam.rotation.set(0, Math.PI, 0);   // face +Z (aft, toward the engine bay blaze)
          } else {
            ctx.player.body.body.setTranslation({ x: sp.x, y: sp.y, z: sp.z + 9.0 }, true);
            cam.rotation.set(0, 0, 0);         // face −Z (forward, fleeing toward the bridge/pod)
          }
          ctx.player.cameraSnapNextFrame = true;
          await sleep(150);
        } else if (beat === 'enterPod') {
          // Drive the REAL enterPod walkUp start: the player fled to the bridge; the docked
          // pod-bay hatch is on the −X wall at world z≈4.8. Place the body a little aft of
          // the bay facing the flee direction (−Z, forward toward the bridge) — the pose they
          // arrive in — so the shot answers "is the open hatch obvious as they arrive?".
          await seatInShip();
          try { g.setSkyIntroMode(0); } catch {}   // interior beat — normal lighting, not the space skybox
          await sleep(200);
          const sp = ctx.player.body.body.translation();   // FRESH bridge spawn
          g.jumpToBeat('enterPod');
          await sleep(150);                  // let walkUp init (prompt "Get in the escape pod")
          // --angle=flee: stand aft of the bay facing forward −Z (the arriving pose — is the
          //   hatch visible as they run up?). --angle=hatch (default): at the threshold facing
          //   the bay hatch (−X) — is the open lit entry obvious to walk into?
          const ang = window.__FLOW_ANGLE || 'hatch';
          cam.rotation.order = 'YXZ';
          if (ang === 'flee') {
            ctx.player.body.body.setTranslation({ x: sp.x + 0.4, y: sp.y, z: sp.z + 6.6 }, true);
            cam.rotation.set(0, 0, 0);       // face −Z (forward, the flee direction); bay is ahead-left
          } else {
            // at the bay threshold (corridor-side of the hatch), facing −X into the aperture.
            ctx.player.body.body.setTranslation({ x: sp.x - 0.45, y: sp.y, z: sp.z + 4.8 }, true);
            cam.rotation.set(0, Math.PI / 2, 0);   // yaw +90° → face −X (into the docked-pod hatch)
          }
          ctx.player.cameraSnapNextFrame = true;
          try { g.setEngineFire(1, 2.1); g.setShipAlert(2, 0.9); } catch {}
          await sleep(150);
        } else if (beat === 'wake') {
          // Drive the REAL wake: run through impact (settles the crashed cabin) then wake
          // (seats inside it + faceControl(CABIN_HATCH_YAW) at the hatch), let the come-to
          // black fade, and shoot the ACTUAL pose — do NOT override rotation.
          g.setTime(0.32);
          g.startIntro();
          g.jumpToBeat('impact');
          await sleep(2600);                 // impact settles the crashed cabin + fades
          g.jumpToBeat('wake');
          await sleep(4200);                 // come-to black fades naturally (mode seated ticking)
        }

        // Read the ACTUAL pose the game left (no override). Pin the camera to the body eye
        // for position but KEEP the rotation the beat set.
        ctx.flags.paused = true;
        const tr = ctx.player.body.body.translation();
        cam.position.set(tr.x, tr.y + (ctx.player.eyeOffset || 0.5), tr.z);
        cam.updateMatrixWorld(true);
        const yaw = cam.rotation.y, pitch = cam.rotation.x;
        const ship = ctx.three.scene.getObjectByName('escapePodShipCockpit');
        let shipMeshes = 0; if (ship) ship.traverse((o) => { if (o.isMesh && o.visible) shipMeshes++; });
        return {
          beat,
          mode: ctx.intro ? ctx.intro.mode : null,
          eye: [+cam.position.x.toFixed(2), +cam.position.y.toFixed(2), +cam.position.z.toFixed(2)],
          yawDeg: +(yaw * 180 / Math.PI).toFixed(1),
          pitchDeg: +(pitch * 180 / Math.PI).toFixed(1),
          shipMeshes,
        };
      }, beat);
      await page.waitForTimeout(250);
      // only tag a suffix when an explicit --angle was passed that overrides the beat default.
      const dfl = { enterPod: 'hatch', corridor: 'flee' };
      const suffix = (argv.angle && dfl[beat] && argv.angle !== dfl[beat]) ? `-${argv.angle}` : '';
      const path = join(OUT, `scen-flow-${beat}${suffix}.png`);
      // wake sits over the full desert scene (heavy) — the clipped/animations-disabled grab
      //   stalls there (known); use a plain grab for it. Interior beats use the clean clip.
      if (beat === 'wake') await page.screenshot({ path, fullPage: false });
      else await page.screenshot({ path, fullPage: false, clip: { x: 0, y: 0, width: 1100, height: 760 }, animations: 'disabled', timeout: 60000 });
      results.push(meas);
      console.log(`[flow-clarity] ${JSON.stringify(meas)} → scen-flow-${beat}${suffix}.png`);
    }
    console.log(`[flow-clarity] all: ${JSON.stringify(results)}`);
  },

  // Smoke-intro (T1.2): run the whole intro beat chain headless + report {ok,beats}.
  // Escape-pod intro health GATE: drives the whole 12-beat chain headless + asserts
  // {ok:true, beats:12}. THROWS on failure so `node rig-shot.mjs --scenario=smoke-intro`
  // exits non-zero (main().catch → exit 1) — usable as `npm run verify:intro`. No screenshot.
  'smoke-intro': async (page) => {
    const r = await page.evaluate(() => window.__game.smokeIntro());
    console.log(`[smoke-intro] ${JSON.stringify(r)}`);
    if (!r || !r.ok || r.beats !== 12) throw new Error(`smoke-intro GATE FAILED: ${JSON.stringify(r)}`);
  },

  // B2 — THE PLAYER-GATED BOARDING WALK-IN PROOF (reuses the B1.f trapped-in-chair real-motion test
  //   pattern: prove the walkable path with REAL KCC motion, not collider math). Drives the enterPod
  //   beat LIVE: seats the player in the ship, jumps to enterPod, then (1) E-opens the closed door,
  //   (2) drives real WASD → the KCC physically WALKS the player corridor → through the airlock
  //   doorway → INTO the pod bore (sampling the body position each leg so we PROVE it traversed, not
  //   teleported), (3) E-sits, and asserts the beat reached the sealed/eject phase. THROWS if the
  //   walk-in path is blocked (the body never gets inside) so this gates like smoke-intro. No shot —
  //   it's a motion proof; the console log reports the traversal. Every boarding phase is driven by
  //   the FIXED-DT sim-budget loop (see below) so the proof is DETERMINISTIC under the ~1 fps
  //   headless swiftshader tab — no wall-clock timing dependence.
  'pod-walkin': async (page) => {
    const log = await page.evaluate(async () => {
      const g = window.__game;
      const ctx = g.ctx;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const trace = [];
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      ctx.flags.paused = false;
      ctx.input.controls.isLocked = true;   // isPlaying()===true → updatePlayer processes real KCC motion
      // ── DETERMINISTIC DRIVER (throttle-proof — the same fixed-dt sim-budget technique as
      //    pod-walkout). The OLD driver gave each boarding phase a WALL-CLOCK iteration budget
      //    (E-open 20×80 ms, E-sit 25×80 ms, …) — but the headless swiftshader tab renders this
      //    heavy ship+bay scene at ~1 fps, so a whole phase budget could elapse with ZERO game
      //    frames ticking (instrumented: 15 straight E-sit iterations with phase=atSeat, the gaze
      //    near/look BOTH true and E pending, while ctx.time.elapsed sat frozen — the game-side
      //    gate is healthy; the harness just raced a starved loop → "E-sit did not seat", flaky).
      //    THE FIX: pin the loop's dt to FIXED_DT so every ticked frame advances a KNOWN sim-dt,
      //    and drive each phase until its PHASE-FLIP CONDITION (or a sim-time budget) — never a
      //    wall-clock count — re-asserting facing + input every yield. Assertions stay strict.
      const FIXED_DT = 0.05;   // sim-seconds per frame (under the loop's 0.1 clamp → never clamped)
      const cam = ctx.three.camera;
      const faceNegX = () => { cam.rotation.order = 'YXZ'; cam.rotation.set(0, Math.PI / 2, 0); };   // face −X (toward the docked pod / the seat)
      /** Drive the live loop until cond() is true or simBudget sim-seconds elapse. perTick
       *  re-asserts input/facing every yield (so whenever a real frame lands, the inputs are
       *  there). Stall-bail: ~10 s of yields with no ticked frame → the loop is wedged, bail
       *  (never hangs; a long BLOCKING frame — e.g. a shader compile — can't false-trip it,
       *  because these yields don't run while the main thread is blocked either). */
      const drive = async (simBudget, cond, perTick) => {
        const simStart = ctx.time.elapsed;
        let lastSim = simStart, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          if (perTick) perTick();
          await sleep(16);
          const nowSim = ctx.time.elapsed;
          if (nowSim > lastSim + 1e-6) { lastSim = nowSim; stalls = 0; }
          else if (++stalls > 600) break;
          if (cond()) return { ok: true, sim: +(nowSim - simStart).toFixed(2) };
          if (nowSim - simStart >= simBudget) break;
        }
        return { ok: cond(), sim: +(ctx.time.elapsed - simStart).toFixed(2) };
      };
      const realClock = ctx.three.clock;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      let walkedInX = 0, insideOk = false, seated = false, ejected = false;
      try {
        realClock.getDelta = () => FIXED_DT;             // pin the per-frame sim-dt (throttle-proof)
        ctx.three.renderer.setSize(48, 48, false);       // tiny canvas → more REAL frames tick per second (this gate takes no screenshots)
        try { g.skipIntro(); } catch {}
        await drive(0.2, () => !ctx.intro || !ctx.intro.active);   // let the teardown tick run
        // seat in the ship (retry the cockpit jump until the reseat to y≈3000 takes).
        g.startIntro();
        for (let a = 0; a < 20; a++) {
          g.jumpToBeat('cockpit');
          const r = await drive(0.3, () => ctx.player.body.body.translation().y > 2900);
          if (r.ok) break;
        }
        try { g.setSkyIntroMode(0); } catch {}
        const sp = ctx.player.body.body.translation();
        // the bridge spawn sits at SEAT_Z = −0.30 off the ship origin → origin.z = sp.z + 0.30. Use
        //   the ORIGIN frame so the walk line is centred on the bay door (local z = BAY_ZC = 4.8).
        const SHIP = { x: sp.x, y: sp.y, z: sp.z + 0.30 };
        // Position the player in the CORRIDOR, just fore of the bay opening (bay z-span ≈ +3.2..+6.4 on
        //   the −X wall), on the +X side of the walkable tube, facing −X toward the docked pod door.
        g.jumpToBeat('enterPod');
        await drive(0.4, () => ctx.intro.beat === 'enterPod' && ctx.intro.scratch.phase === 'approach');   // the beat's init tick ran (mode=walk, door closed)
        const startPos = { x: SHIP.x + 0.6, y: sp.y, z: SHIP.z + 4.8 };   // corridor, +X side, on the door centreline
        ctx.player.body.body.setTranslation(startPos, true);
        ctx.player.cameraSnapNextFrame = true;
        faceNegX();
        await drive(0.15, () => false, faceNegX);        // ≥2 ticked frames: the camera snap + anchor apply
        const p0 = ctx.player.body.body.translation();
        trace.push({ leg: 'start(corridor)', phase: ctx.intro.scratch.phase, x: +(p0.x - SHIP.x).toFixed(2), z: +(p0.z - SHIP.z).toFixed(2) });
        // (1) E-OPEN the door — re-assert E + the −X facing every yield until the gaze-gated press
        //     lands (phase flips approach→enter). Sim budget 2 s ≈ 40 fixed-dt frames.
        const rOpen = await drive(2.0,
          () => ctx.intro.scratch.phase === 'enter' || ctx.intro.scratch.phase === 'atSeat',
          () => { faceNegX(); ctx.input.pressed.add('KeyE'); });
        trace.push({ leg: 'after E-open', phase: ctx.intro.scratch.phase, doorOpened: rOpen.ok, sim: rOpen.sim });
        // (2) WALK IN — hold W (real KCC) to walk −X through the doorway into the bore. The stop
        //     condition is phase=atSeat AND a fixed DEPTH LINE (x < −1.8): the atSeat gate flips at
        //     the 1.05 m stand radius (x ≈ −1.16), shy of the assertion's −1.2 walked-in-depth
        //     proof, so we walk the deterministic 2-3 extra fixed-dt frames to −1.8 — well past the
        //     −1.2 line, still 0.4 m fore of the stand-point (no seat overshoot; the CLUSTER D
        //     halt-near-the-seat intent holds, now deterministic). The door swing (0.75 sim-s) runs
        //     concurrently in this phase; budget 6 sim-s covers the swing + the ~2.8 m walk.
        const rWalk = await drive(6.0,
          () => ctx.intro.scratch.phase === 'atSeat' && (ctx.player.body.body.translation().x - SHIP.x) < -1.8,
          () => { faceNegX(); ctx.input.keys['KeyW'] = true; });
        ctx.input.keys['KeyW'] = false;
        insideOk = rWalk.ok;
        // capture the REAL walked-in depth (the gate's proof of the KCC boarding) BEFORE any settle.
        walkedInX = ctx.player.body.body.translation().x - SHIP.x;   // well into −X (past the −1.0 wall, toward the pod at −2.5)
        // settle the body at the interior stand-point so the E-sit gaze/proximity is deterministic (a
        //   real player stands by the seat before sitting). BAY_POD_X = −(COR_HW 1.0 + BAY_RECESS
        //   2.9 · 0.52) = −2.508; stand = +0.30 fore. (Framing aid ONLY — walkedInX above already
        //   proves the real walk reached the bore.)
        if (insideOk) {
          const stand = { x: SHIP.x - 2.508 + 0.30, y: ctx.player.body.body.translation().y, z: SHIP.z + 4.8 };
          ctx.player.body.body.setTranslation(stand, true);
          ctx.player.cameraSnapNextFrame = true;
          await drive(0.15, () => false, faceNegX);      // ≥2 ticked frames: the snap + camera anchor land at the stand
        }
        const pIn = ctx.player.body.body.translation();
        trace.push({ leg: 'inside?', phase: ctx.intro.scratch.phase, x: +walkedInX.toFixed(2), z: +(pIn.z - SHIP.z).toFixed(2), insideOk, walkSim: rWalk.sim });
        // (3) E-SIT — re-assert E + the −X facing (the seat gaze target) every yield until the
        //     edge-triggered sit lands (phase flips atSeat→sealing). Sim budget 2 s.
        const rSit = await drive(2.0,
          () => { const ph = ctx.intro.scratch.phase; return ph === 'sealing' || ph === 'eject' || ctx.intro.beat !== 'enterPod'; },
          () => { faceNegX(); ctx.input.pressed.add('KeyE'); });
        seated = rSit.ok;
        trace.push({ leg: 'after E-sit', beat: ctx.intro.beat, phase: ctx.intro.beat === 'enterPod' ? ctx.intro.scratch.phase : '(advanced)', seated, sim: rSit.sim });
        // (4) E-EJECT — the auto-seal is 0.9 SIM-seconds (deterministic now: 18 fixed-dt frames),
        //     then inject E at the eject gate until the beat ADVANCES to shipExplode (the lever is
        //     purely player-gated — no fallback timer). Sim budget 5 s covers the seal + the press.
        const rEject = await drive(5.0,
          () => ctx.intro.beat !== 'enterPod',
          () => { if (ctx.intro.beat === 'enterPod' && ctx.intro.scratch.phase === 'eject') ctx.input.pressed.add('KeyE'); });
        ejected = rEject.ok;
        trace.push({ leg: 'after E-eject', beat: ctx.intro.beat, ejected, sim: rEject.sim });
      } finally {
        ctx.input.keys['KeyW'] = false;
        realClock.getDelta = origGetDelta;               // restore the real clock (leak-free)
        ctx.three.renderer.setSize(origW, origH, false); // restore the canvas
      }
      return { trace, walkedInX, reachedInside: insideOk, seated, ejected };
    });
    console.log('[pod-walkin] ' + JSON.stringify(log.trace, null, 0));
    console.log(`[pod-walkin] walkedInX=${log.walkedInX.toFixed(2)} reachedInside=${log.reachedInside} seated=${log.seated}`);
    // GATE: the body must have physically walked PAST the −1.0 corridor-wall line into the bore
    //   (x < −1.2 relative to SHIP_ORIGIN) via real KCC, reached the atSeat gate, and E-sit advanced it.
    if (!log.reachedInside) throw new Error(`pod-walkin GATE FAILED: the player never walked INTO the pod (walkedInX=${log.walkedInX.toFixed(2)}, expected < −1.2). The walkable boarding path is blocked.`);
    if (log.walkedInX > -1.2) throw new Error(`pod-walkin GATE FAILED: the body only reached x=${log.walkedInX.toFixed(2)} (expected < −1.2 inside the bore).`);
    if (!log.seated) throw new Error(`pod-walkin GATE FAILED: E-sit did not seat/advance the beat.`);
    if (!log.ejected) throw new Error(`pod-walkin GATE FAILED: E-eject did not fire/advance to shipExplode.`);
    console.log('[pod-walkin] GATE PASS — corridor → through the doorway → inside the pod → seated → E-eject fired (real KCC motion + real input path).');
  },

  // Z4 — THE POD-ROTATION-CLEARANCE SWEEP (the machine gate for "ship geometry intrudes into the pod").
  //   The docked bay pod rotates 0→π/2 in its cradle (setBayPodYaw). NOTHING fixed in the bay (collar,
  //   umbilicals, clamp arms, mate bands, airlock frame, ship box) may enter the pod's interior VOLUME —
  //   a cylinder of radius BAY_POD_R (1.44, the outer hull) about the pod's own vertical axis, spanning
  //   the pod's y-range (floor→shoulder). The pod's OWN meshes yaw WITH it (excluded from the test). The
  //   fixed bay meshes don't move, so a mesh's minimum radius from the pod axis is yaw-independent — BUT
  //   the door aperture only excuses an intruder at yaw 0 (the door faces the collar); at any other yaw
  //   the SOLID hull sweeps over that spot and the intruder pokes through the shell (the user's screenshot
  //   + probe-rotate-{73,90}-porthole.png). So the gate is: no fixed bay mesh may reach r < POD_R inside
  //   the pod y-range, ANYWHERE (the legitimate mate interface stops AT the +X door face, r≈1.44). Drives
  //   the sweep stepwise (visual-truth: the pod really rotates), enumerates every violating mesh by name,
  //   and FAILS with the worst penetration depth. No screenshot — a geometry assertion.
  //     node scripts/rig-shot.mjs --scenario=pod-rotation-clearance --port=5192
  'pod-rotation-clearance': async (page) => {
    const wantShots = !!argv.shots;
    if (wantShots) await page.evaluate(() => { window.__CLEARANCE_SHOTS = true; });
    const out = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      ctx.flags.thirdPerson = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      // DIAGNOSTIC BUILD — disable the static merge so INDIVIDUAL named greeble meshes survive (else
      //   the collar/frame/umbilical bits are baked into a few anonymous per-material merged meshes and
      //   we can't name the intruder). This is the same __stageNoMerge hook the geometry-lint stage uses.
      window.__stageNoMerge = true;
      window.__clearanceShots = !!(window.__CLEARANCE_SHOTS);   // --shots → also render the seated-eye confirm frames
      // Build the ship+bay+docked pod: start the intro + jump to cockpit (retry until the reseat takes).
      try { g.skipIntro(); } catch {}
      await sleep(120);
      g.startIntro();
      for (let a = 0; a < 30; a++) {
        g.jumpToBeat('cockpit');
        await sleep(120);
        if (ctx.player.body.body.translation().y > 2900) break;
      }
      const scene = ctx.three.scene;
      // NOTE: buildShipScene STATIC-MERGES shared-material greebles (mergeStaticByMaterial) at the SHIP
      //   ROOT — so the individual collar/frame/umbilical meshes no longer live under 'escapePodBay';
      //   they're baked into a few per-material merged BufferGeometries parented at the ship root. So we
      //   scan the WHOLE ship group (escapePodShipCockpit) and exclude ONLY the pod subtree (which is
      //   noMerge-protected → still a real transformable subtree that yaws with the pod).
      const ship = scene.getObjectByName('escapePodShipCockpit');
      const pod = scene.getObjectByName('dockedCanonicalPod');   // _bayGroup — the yawing pod root
      if (!ship || !pod) return { error: `ship/pod not built (ship=${!!ship} pod=${!!pod})` };
      // The pod's vertical axis (world) + geometry envelope.
      const centre = g.getBayPodCenter();   // {x,y,z} — deck-plane centre of the pod axis
      const POD_R = 1.44;         // BAY_POD_R — outer hull radius (the test cylinder)
      const INNER_R = 1.28;       // CAB_R — the interior bore (deep-inside = a worse intrusion class)
      const Y_LO = centre.y + 0.06, Y_HI = centre.y + 3.10;   // floor (a hair up) → shoulder/dome spring
      const MARGIN = 0.02;        // the legit mate interface stops AT r≈POD_R; only r < POD_R−MARGIN penetrates
      // Collect the set of Object3Ds that ARE the pod (yaw WITH it → excluded from the fixed-mesh test).
      const podSet = new Set(); pod.traverse((o) => podSet.add(o));
      // Gather the fixed ship meshes (anywhere in the ship, NOT in the pod subtree, real geometry). The
      //   post-merge scene has ~a dozen big merged meshes + the protected dynamics; that's what we test.
      const fixed = [];
      ship.traverse((o) => {
        if (!o.isMesh || !o.geometry || podSet.has(o)) return;
        fixed.push(o);
      });
      // Per fixed mesh: the MIN radial distance from the pod axis over its world-space vertices that lie
      //   within the pod y-range. Sample the geometry's position attribute (transformed to world).
      const _v = new THREE.Vector3();
      const measure = () => {
        pod.updateMatrixWorld(true); ship.updateMatrixWorld(true);
        const hits = [];
        for (const m of fixed) {
          const pos = m.geometry.getAttribute('position');
          if (!pos) continue;
          m.updateWorldMatrix(true, false);
          let minR = Infinity, atY = 0;
          const N = pos.count;
          // sample every vertex (these greeble meshes are small — few hundred verts each at most)
          for (let i = 0; i < N; i++) {
            _v.fromBufferAttribute(pos, i).applyMatrix4(m.matrixWorld);
            if (_v.y < Y_LO || _v.y > Y_HI) continue;
            const dx = _v.x - centre.x, dz = _v.z - centre.z;
            const r = Math.hypot(dx, dz);
            if (r < minR) { minR = r; atY = _v.y; }
          }
          if (minR < POD_R - MARGIN) {
            // report the mesh's WORLD origin (local to the ship: subtract centre) + a geometry hint so an
            //   unnamed _box/_cyl greeble can be traced to its builder line.
            const wp = new THREE.Vector3(); m.getWorldPosition(wp);
            const gt = m.geometry.type.replace('Geometry', '');
            const bb = m.geometry.boundingBox || (m.geometry.computeBoundingBox(), m.geometry.boundingBox);
            const sz = bb ? { x: +(bb.max.x - bb.min.x).toFixed(2), y: +(bb.max.y - bb.min.y).toFixed(2), z: +(bb.max.z - bb.min.z).toFixed(2) } : null;
            // the min-radius vertex in WORLD, + the mesh's ancestry path (names) to pin the builder
            const minV = new THREE.Vector3();
            for (let i2 = 0; i2 < N; i2++) { _v.fromBufferAttribute(pos, i2).applyMatrix4(m.matrixWorld); if (_v.y < Y_LO || _v.y > Y_HI) continue; const dx2 = _v.x - centre.x, dz2 = _v.z - centre.z; if (Math.hypot(dx2, dz2) === minR) { minV.copy(_v); break; } }
            let path = ''; { let p = m; for (let k = 0; k < 6 && p; k++) { path = (p.name || p.type) + (path ? '>' : '') + path; p = p.parent; } }
            const rot = { x: +m.rotation.x.toFixed(2), y: +m.rotation.y.toFixed(2), z: +m.rotation.z.toFixed(2) };
            const minVW = { x: +(minV.x - centre.x).toFixed(2), y: +(minV.y - centre.y).toFixed(2), z: +(minV.z - centre.z).toFixed(2) };
            hits.push({ name: m.name || `(${gt})`, minR: +minR.toFixed(3), atY: +(atY - centre.y).toFixed(2),
              depth: +(POD_R - minR).toFixed(3), interior: minR < INNER_R,
              // ship-local origin (x relative to pod centre, absolute y-off-floor, z relative to pod centre)
              pos: { x: +(wp.x - centre.x).toFixed(2), y: +(wp.y - centre.y).toFixed(2), z: +(wp.z - centre.z).toFixed(2) },
              geom: gt, size: sz, rot, path, minVert: minVW });
          }
        }
        // de-dupe & rank by worst penetration
        return hits.sort((a, b) => a.minR - b.minR);
      };
      // Sweep 0→π/2 in 11 steps (visual-truth: the pod really turns). Union the violations across steps.
      const STEPS = 11;
      const worst = new Map();   // key: name+atY bucket → the deepest hit seen
      const perStep = [];
      for (let s = 0; s < STEPS; s++) {
        const yaw = (s / (STEPS - 1)) * (Math.PI / 2);
        g.setBayPodYaw(yaw);
        await sleep(24);   // let a frame tick so the matrices settle (also drives the real rotation)
        const hits = measure();
        perStep.push({ yaw: +yaw.toFixed(3), nViol: hits.length });
        for (const h of hits) {
          const key = h.name + '@' + JSON.stringify(h.pos);
          const prev = worst.get(key);
          if (!prev || h.depth > prev.depth) worst.set(key, h);
        }
      }
      const violations = [...worst.values()].sort((a, b) => b.depth - a.depth);
      // OWN-EYES CONFIRM (with --shots): pose the SEATED interior eye, orbited about the pod axis in
      //   lockstep with the yaw (the sequence.ts rotate-phase pose), looking at the porthole/door — the
      //   REAL view the player has mid-rotation. Matches the Z4 repro frames probe-rotate-{73,90}. Expose
      //   a poser so the harness can screenshot per angle; else just leave the pod docked.
      if (window.__clearanceShots) {
        // Own-eyes: pause the loop + drive the camera manually (the seated eye, orbited with the yaw).
        //   Renders straight to the canvas; the harness reads it via gl.readPixels (page.screenshot
        //   can race a paused paint, so we blit the framebuffer to a data-URL the node side writes out).
        ctx.flags.paused = true;
        const SW = 1100, SH = 800;
        ctx.three.renderer.setSize(SW, SH, false);
        const cam0 = ctx.three.camera; cam0.aspect = SW / SH; cam0.updateProjectionMatrix();
        window.__clearancePose = (yawDeg) => {
          const yaw = (yawDeg * Math.PI) / 180;
          g.setBayPodYaw(yaw);
          const cam = ctx.three.camera;
          const V = cam.position.constructor;
          const cos = Math.cos(yaw), sin = Math.sin(yaw);
          // The BAY pod's interior is yawed so its DOOR/porthole faces pod-local +X (θ=π/2) — the seated
          //   eye looks +X at the door (NOT −Z like the ride cabin). Eye sits a touch −X of centre so the
          //   whole door/porthole frames. Orbit both about +Y by the yaw.
          const ex = -0.15 * cos, ez = 0.15 * sin;   // eye pod-local (−0.15, +1.70, 0) rotated
          const eye = new V(centre.x + ex, centre.y + 1.70, centre.z + ez);
          const fx = cos, fz = -sin;   // pod-local +X (forward, toward the door) rotated by yaw
          cam.rotation.order = 'YXZ';
          cam.position.copy(eye);
          cam.lookAt(eye.x + fx, eye.y - 0.28, eye.z + fz);   // dip to frame the porthole (door centre ~1.3)
          cam.updateMatrixWorld(true);
          const r = ctx.three.renderer;
          r.render(ctx.three.scene, ctx.three.camera);
          // blit the WebGL framebuffer → a 2D canvas (flip Y) → PNG data URL (node writes it to disk)
          const gl = r.getContext();
          const px = new Uint8Array(SW * SH * 4);
          gl.readPixels(0, 0, SW, SH, gl.RGBA, gl.UNSIGNED_BYTE, px);
          const cv = document.createElement('canvas'); cv.width = SW; cv.height = SH;
          const c2 = cv.getContext('2d'); const img = c2.createImageData(SW, SH);
          for (let y = 0; y < SH; y++) { const sy = SH - 1 - y; for (let x = 0; x < SW; x++) { const s = (sy * SW + x) * 4, d = (y * SW + x) * 4; img.data[d] = px[s]; img.data[d + 1] = px[s + 1]; img.data[d + 2] = px[s + 2]; img.data[d + 3] = 255; } }
          c2.putImageData(img, 0, 0);
          return cv.toDataURL('image/png');
        };
      } else {
        g.setBayPodYaw(0);   // leave it docked
      }
      return {
        nFixedMeshes: fixed.length,
        centre, podR: POD_R, yRange: [+(Y_LO - centre.y).toFixed(2), +(Y_HI - centre.y).toFixed(2)],
        perStep,
        violations,
      };
    });
    if (out.error) throw new Error('[pod-rotation-clearance] ' + out.error);
    console.log('[pod-rotation-clearance] fixed bay meshes tested=' + out.nFixedMeshes +
      ' | pod y-range(local)=' + JSON.stringify(out.yRange) + ' | test radius=' + out.podR);
    console.log('[pod-rotation-clearance] per-step violation counts: ' + JSON.stringify(out.perStep));
    if (out.violations.length) {
      console.log('[pod-rotation-clearance] INTRUDING MESHES (worst penetration across the sweep):');
      for (const v of out.violations) {
        console.log(`   • ${v.name} [${v.geom} ${JSON.stringify(v.size)} rot${JSON.stringify(v.rot)}]  minR=${v.minR}m (POD_R−${v.depth}m past the hull` +
          (v.interior ? ', INSIDE the bore' : '') + `)  mesh-origin(pod-local)=${JSON.stringify(v.pos)}  minVert(pod-local)=${JSON.stringify(v.minVert)}  path=${v.path}`);
      }
    }
    const fails = out.violations.length;
    console.log('[pod-rotation-clearance] ' + (fails
      ? `FAIL — ${fails} fixed bay mesh(es) penetrate the pod's interior volume during the 0→π/2 sweep.`
      : 'PASS — no fixed bay/collar/ship mesh enters the pod interior volume at any sweep angle (the pod rotates freely with clearance).'));
    // OWN-EYES confirm frames (matches the Z4 repro probe-rotate-{73,90}-porthole.png): the seated
    //   interior eye at 73° + 90° yaw — the barrel around the porthole must be clean.
    if (wantShots) {
      const { writeFileSync } = await import('node:fs');
      for (const deg of [73, 90]) {
        const durl = await page.evaluate((d) => (window.__clearancePose ? window.__clearancePose(d) : null), deg);
        if (durl) {
          const b64 = durl.replace(/^data:image\/png;base64,/, '');
          const p = join(OUT, `scen-pod-clearance-${deg}.png`);
          writeFileSync(p, Buffer.from(b64, 'base64'));
          console.log(`[pod-rotation-clearance] seated-eye confirm @ ${deg}° → scen-pod-clearance-${deg}.png`);
        }
      }
    }
    if (fails) throw new Error(`pod-rotation-clearance GATE FAILED: ${fails} intruding mesh(es).`);
  },

  // W2b — THE AIRLOCK COLLIDER MOTION PROBE (Rule 9: collision matches the visible airlock, proven by
  //   real motion). Independent of the sequence flow (the orchestrator rewires that later). Boots the
  //   ship, seats the KCC body in the corridor on the airlock centreline (+X side), and proves:
  //   (1) CLOSED sliding door BLOCKS — drive W(−X) into the closed door; the body stops at the wall
  //       plane (can't cross past x ≈ AIRLOCK_WALL_X − a small margin). The seal collider works.
  //   (2) OPEN sliding door PASSES — slide the leaves open (by name) + drop the seal (find + remove
  //       the aperture static box), drive W(−X); the body walks THROUGH into the collar and reaches
  //       near the pod-door threshold (x < COLLAR_FAR_X + margin). The collar floor/walls are walkable.
  //   (3) NO FALL-THROUGH / NO GAP TO SPACE — y stays on the ship floor (≈3000) the whole way.
  //   No screenshot — a motion assertion (like cockpit-motion / pod-walkin).
  'airlock-motion': async (page) => {
    const log = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      const realClock = ctx.three.clock; const FIXED_DT = 0.05;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      realClock.getDelta = () => FIXED_DT;
      ctx.three.renderer.setSize(48, 48, false);
      const drive = async (simBudget, perTick) => {
        const s0 = ctx.time.elapsed; let last = s0, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          if (perTick) perTick();
          await sleep(16);
          const now = ctx.time.elapsed;
          if (now > last + 1e-6) { last = now; stalls = 0; } else if (++stalls > 600) break;
          if (now - s0 >= simBudget) break;
        }
      };
      const result = { legs: [], closedBlocked: false, openedPassed: false, onFloor: true };
      try {
        try { g.skipIntro(); } catch {}
        await drive(0.2);
        g.startIntro();
        for (let a = 0; a < 20; a++) { g.jumpToBeat('cockpit'); await drive(0.3); if (ctx.player.body.body.translation().y > 2900) break; }
        try { g.setSkyIntroMode(0); } catch {}
        ctx.flags.paused = false;
        ctx.input.controls.isLocked = true;   // isPlaying() → real KCC motion processed
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.player.eyeOffset = 0.85; }   // free-walk (the cockpit opens seated → locomotion gated otherwise)
        const cam = ctx.three.camera; cam.rotation.order = 'YXZ';
        // ORIGIN frame: the bridge spawn is at SEAT_Z = −0.30 → origin.z = spawn.z + 0.30. Airlock is
        //   at local z = BAY_ZC = 4.8, wall plane at local x = AIRLOCK_WALL_X = −1.0, collar far = −1.92.
        const sp = ctx.player.body.body.translation();
        const OX = sp.x, OY = sp.y, OZ = sp.z + 0.30;   // ship-origin frame
        const WALL_X = -1.0, COLLAR_FAR = -1.92, POD_X = -3.36, AHW = 0.72, TRAVEL = 0.82, BZ = 4.8;
        const faceNegX = () => { cam.rotation.set(0, Math.PI / 2, 0); if (ctx.intro) ctx.intro.mode = 'walk'; };   // YXZ yaw +π/2 → forward = −X; keep walk mode
        const floorY = OY;   // the KCC body-centre y at the corridor floor (spawn y ≈ ship floor)

        // ── LEG 1: CLOSED door blocks. Place the body in the corridor on the airlock centreline, +X
        //    side (x = −0.4 local, well corridor-side of the −1.0 wall), face −X, drive W into the door.
        ctx.player.body.body.setTranslation({ x: OX - 0.4, y: OY, z: OZ + BZ }, true);
        ctx.player.cameraSnapNextFrame = true;
        await drive(0.15, faceNegX);
        await drive(2.4, () => { faceNegX(); ctx.input.keys['KeyW'] = true; });
        ctx.input.keys['KeyW'] = false;
        const p1 = ctx.player.body.body.translation();
        const x1 = p1.x - OX;
        // BLOCKED if the body did NOT cross meaningfully past the wall plane (allow the KCC skin ~0.1).
        result.closedBlocked = x1 > (WALL_X - 0.15);
        if (Math.abs(p1.y - floorY) > 0.6) result.onFloor = false;
        result.legs.push({ leg: 'closed-block', xEnd: +x1.toFixed(2), wallX: WALL_X, blocked: result.closedBlocked, y: +p1.y.toFixed(1) });

        // ── OPEN the door: slide the leaves into their pockets (by name) + DROP the seal collider. The
        //    seal is the ONE static collider at the aperture centre (world x = OX+WALL_X, z = OZ+BZ,
        //    y ≈ OY + AIRLOCK_TOP/2). Find + remove it from the rapier world.
        const lL = ctx.three.scene.getObjectByName('airlockDoorLeafL');
        const lR = ctx.three.scene.getObjectByName('airlockDoorLeafR');
        if (lL) lL.position.z = (BZ - AHW / 2) - TRAVEL;
        if (lR) lR.position.z = (BZ + AHW / 2) + TRAVEL;
        // remove the seal collider (search the rapier world for a collider at the aperture centre)
        const world = ctx.physics.world;
        const sealWX = OX + WALL_X, sealWZ = OZ + BZ;
        let removed = 0;
        world.forEachCollider((col) => {
          const body = col.parent(); if (!body) return;
          const t = body.translation();   // world position lives on the BODY (makeStaticBox sets it there)
          let hz = 1; try { hz = col.halfExtents().z; } catch {}
          // the seal is the box at the aperture centre (x/z) spanning the aperture width (hz≈AIRLOCK_HW 0.72).
          if (Math.abs(t.x - sealWX) < 0.2 && Math.abs(t.z - sealWZ) < 0.25 && hz > 0.6 && hz < 0.85) {
            world.removeRigidBody(body); removed++;
          }
        });
        result.sealRemoved = removed;
        // DIAGNOSTIC — dump every collider near the boarding lane (x −2.2..0, z BZ±1) so we can see
        //   what blocks the walk-in. (After the seal removal, so it shows the remaining set.)
        result.nearColliders = [];
        world.forEachCollider((col) => {
          const body = col.parent(); if (!body) return;
          const t = body.translation();
          const lx = t.x - OX, lz = t.z - OZ;
          if (lx > -2.4 && lx < 0.2 && Math.abs(lz - BZ) < 1.0 && t.y > OY - 0.5 && t.y < OY + 2.6) {
            let hx = 0, hy = 0, hz = 0;
            try { const h = col.halfExtents(); hx = h.x; hy = h.y; hz = h.z; } catch {}
            result.nearColliders.push({ lx: +lx.toFixed(2), lz: +lz.toFixed(2), ly: +(t.y - OY).toFixed(2), hx: +hx.toFixed(2), hy: +hy.toFixed(2), hz: +hz.toFixed(2) });
          }
        });

        // ── LEG 2: OPEN door passes. Re-place in the corridor (+X side), face −X, drive W through the
        //    open door + collar toward the pod door.
        ctx.player.body.body.setTranslation({ x: OX - 0.4, y: OY, z: OZ + BZ }, true);
        ctx.player.cameraSnapNextFrame = true;
        await drive(0.15, faceNegX);
        await drive(3.5, () => { faceNegX(); ctx.input.keys['KeyW'] = true; });
        ctx.input.keys['KeyW'] = false;
        const p2 = ctx.player.body.body.translation();
        const x2 = p2.x - OX;
        // PASSED if the body walked past the wall into the collar, near the pod-door threshold.
        result.openedPassed = x2 < (COLLAR_FAR + 0.35);
        if (Math.abs(p2.y - floorY) > 0.6) result.onFloor = false;
        result.legs.push({ leg: 'open-pass', xEnd: +x2.toFixed(2), collarFar: COLLAR_FAR, passed: result.openedPassed, y: +p2.y.toFixed(1) });
      } finally {
        ctx.input.keys['KeyW'] = false;
        realClock.getDelta = origGetDelta;
        ctx.three.renderer.setSize(origW, origH, false);
      }
      return result;
    });
    console.log('[airlock-motion] ' + JSON.stringify(log.legs, null, 0));
    console.log('[airlock-motion] nearColliders=' + JSON.stringify(log.nearColliders || []));
    console.log(`[airlock-motion] closedBlocked=${log.closedBlocked} openedPassed=${log.openedPassed} onFloor=${log.onFloor} sealRemoved=${log.sealRemoved}`);
    if (!log.closedBlocked) throw new Error('airlock-motion GATE FAILED: the CLOSED sliding door did NOT block the player (they crossed the wall plane) — the seal collider is missing/misplaced.');
    if (!log.openedPassed) throw new Error('airlock-motion GATE FAILED: the OPEN sliding door did NOT let the player through to the pod threshold — the collar is not walkable (a blocking collider or a floor gap).');
    if (!log.onFloor) throw new Error('airlock-motion GATE FAILED: the player fell through the floor / a gap to space along the boarding path.');
    console.log('[airlock-motion] GATE PASS — closed door blocks, open door + collar are walkable to the pod threshold, no fall-through (real KCC motion).');
  },

  // Z2 — the CREW-QUARTERS WALK PROBE (CLAUDE.md rule 9: the re-lofted room's colliders match the
  //   visible furniture). Real-KCC motion (the airlock-motion idiom): seats the player in the ship,
  //   free-walk mode, then drives WASD to PROVE (1) the OPEN quarters doorway is passable INTO the room
  //   (no invisible wall barring the entry — the 3rd-report clipping/clearance check), (2) the BUNK
  //   BERTH blocks (you can't walk through the mattress into the back wall), (3) the FORE-DESK blocks,
  //   (4) the open floor is walkable, and (5) no fall-through anywhere. FIXED-DT sim-budget loop so
  //   it's deterministic under the ~1fps headless tab. THROWS like the other motion gates.
  'quarters-walk': async (page) => {
    const log = await page.evaluate(async () => {
      const g = window.__game; const ctx = g.ctx;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      const realClock = ctx.three.clock; const FIXED_DT = 0.05;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      realClock.getDelta = () => FIXED_DT;
      ctx.three.renderer.setSize(48, 48, false);
      const drive = async (simBudget, perTick) => {
        const s0 = ctx.time.elapsed; let last = s0, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          if (perTick) perTick();
          await sleep(16);
          const now = ctx.time.elapsed;
          if (now > last + 1e-6) { last = now; stalls = 0; } else if (++stalls > 600) break;
          if (now - s0 >= simBudget) break;
        }
      };
      const result = { legs: [], onFloor: true };
      try {
        try { g.skipIntro(); } catch {}
        await drive(0.2);
        g.startIntro();
        for (let a = 0; a < 20; a++) { g.jumpToBeat('cockpit'); await drive(0.3); if (ctx.player.body.body.translation().y > 2900) break; }
        try { g.setSkyIntroMode(0); } catch {}
        try { g.setQuartersDoor(0); } catch {}   // the quarters door is parked OPEN
        ctx.flags.paused = false;
        ctx.input.controls.isLocked = true;
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.player.eyeOffset = 0.85; }
        const cam = ctx.three.camera; cam.rotation.order = 'YXZ';
        const sp = ctx.player.body.body.translation();
        const OX = sp.x, OY = sp.y, OZ = sp.z + 0.30;   // ship-origin frame
        // room local: door at (x −1.0, z 9.6); back-wall front (berth face) x≈−3.22; room x −1.0..−4.1.
        const faceKey = (yaw) => { cam.rotation.set(0, yaw, 0); if (ctx.intro) ctx.intro.mode = 'walk'; };
        const YAW_NEGX = Math.PI / 2;    // forward = −X (into the room / at the bunk)
        const YAW_POSZ = Math.PI;        // forward = +Z (aft along the room)
        const floorY = OY;
        const put = (lx, lz) => { ctx.player.body.body.setTranslation({ x: OX + lx, y: OY, z: OZ + lz }, true); ctx.player.cameraSnapNextFrame = true; };
        const pos = () => { const p = ctx.player.body.body.translation(); return { x: +(p.x - OX).toFixed(2), z: +(p.z - OZ).toFixed(2), y: p.y }; };
        const checkFloor = (p) => { if (Math.abs(p.y - floorY) > 0.6) result.onFloor = false; };

        // ── LEG 1: DOORWAY PASSABLE. Corridor-side on the door centreline (x −0.4, z 9.6), face −X,
        //    drive W → should pass INTO the room (x < −1.3, well past the wall plane).
        put(-0.4, 9.6); await drive(0.15, () => faceKey(YAW_NEGX));
        await drive(2.6, () => { faceKey(YAW_NEGX); ctx.input.keys['KeyW'] = true; });
        ctx.input.keys['KeyW'] = false;
        let p = pos(); checkFloor(p);
        const doorPassed = p.x < -1.3;
        result.legs.push({ leg: 'doorway-pass', xEnd: p.x, passed: doorPassed, y: +p.y.toFixed(1) });

        // ── LEG 2: BUNK BLOCKS. Inside the room (x −2.2, z 10.2), face −X (at the berth), drive W → the
        //    body must NOT cross into the berth (front x≈−3.22); allow the KCC skin (~0.15) → stop by −3.1.
        put(-2.2, 10.2); await drive(0.15, () => faceKey(YAW_NEGX));
        await drive(2.6, () => { faceKey(YAW_NEGX); ctx.input.keys['KeyW'] = true; });
        ctx.input.keys['KeyW'] = false;
        p = pos(); checkFloor(p);
        // Quarters v2 recessed-alcove redesign: the bed is now SET INTO the back wall, so the player
        //   is blocked at the opening-frame lip collider (~-3.58) — well before the -4.1 wall — and the
        //   floor in front is open (the old projecting platform stopped them by ~-3.1). Assert stopped
        //   BEFORE the wall / not walked into the pocket, not at the retired platform line (-3.15).
        const bunkBlocked = p.x > -3.9;
        result.legs.push({ leg: 'bunk-block', xEnd: p.x, blocked: bunkBlocked, y: +p.y.toFixed(1) });

        // ── LEG 3: OPEN FLOOR WALKABLE. Inside (x −1.6, z 9.4), face +Z, drive W → should walk aft freely
        //    across the open floor (z increases toward ~11), no invisible wall in the walkable centre.
        put(-1.6, 9.4); await drive(0.15, () => faceKey(YAW_POSZ));
        await drive(2.2, () => { faceKey(YAW_POSZ); ctx.input.keys['KeyW'] = true; });
        ctx.input.keys['KeyW'] = false;
        p = pos(); checkFloor(p);
        const floorWalkable = p.z > 10.2;
        result.legs.push({ leg: 'floor-walk', zEnd: p.z, walked: floorWalkable, y: +p.y.toFixed(1) });

        // ── LEG 4: DESK BLOCKS. On the door-side fore wall in front of the desk (x −1.95, z 9.2), face
        //    −Z (at the fore wall / desk), drive W → must NOT pass the desk face (z≈8.3); stop by z 8.6.
        put(-1.95, 9.2); await drive(0.15, () => faceKey(0));   // yaw 0 → forward +Z? YXZ yaw 0 → −Z
        await drive(2.2, () => { faceKey(0); ctx.input.keys['KeyW'] = true; });
        ctx.input.keys['KeyW'] = false;
        p = pos(); checkFloor(p);
        const deskBlocked = p.z > 8.55;
        result.legs.push({ leg: 'desk-block', zEnd: p.z, blocked: deskBlocked, y: +p.y.toFixed(1) });

        result.doorPassed = doorPassed; result.bunkBlocked = bunkBlocked;
        result.floorWalkable = floorWalkable; result.deskBlocked = deskBlocked;
      } finally {
        ctx.input.keys['KeyW'] = false;
        realClock.getDelta = origGetDelta;
        ctx.three.renderer.setSize(origW, origH, false);
      }
      return result;
    });
    console.log('[quarters-walk] legs=' + JSON.stringify(log.legs));
    console.log(`[quarters-walk] doorPassed=${log.doorPassed} bunkBlocked=${log.bunkBlocked} floorWalkable=${log.floorWalkable} deskBlocked=${log.deskBlocked} onFloor=${log.onFloor}`);
    if (!log.doorPassed) throw new Error('quarters-walk GATE FAILED: the OPEN quarters doorway did NOT let the player into the room (an invisible wall / clip bars the entry).');
    if (!log.bunkBlocked) throw new Error('quarters-walk GATE FAILED: the player walked THROUGH the bunk berth (missing/misplaced bunk collider — rule 9 violation).');
    if (!log.floorWalkable) throw new Error('quarters-walk GATE FAILED: the open floor is NOT walkable (an invisible wall in the room centre).');
    if (!log.deskBlocked) throw new Error('quarters-walk GATE FAILED: the player walked THROUGH the desk (missing/misplaced desk collider — rule 9 violation).');
    if (!log.onFloor) throw new Error('quarters-walk GATE FAILED: the player fell through the floor somewhere in the room.');
    console.log('[quarters-walk] GATE PASS — doorway passable, bunk + desk block, open floor walkable, no fall-through (real KCC motion).');
  },

  // CLUSTER D — the WALK-OUT gate (user spec: crash → wake → kick the FRONT door → walk out on your
  //   OWN legs onto the real terrain, NO teleport; the exposure EASES like eye-adaptation, no snap).
  //   Drives the REAL chain impact → wake → kick the door → real-KCC walk out the −Z door, and PROVES:
  //   (1) the player physically walked OUT through the door onto the terrain (position moved −Z past
  //   the pod radius via real KCC, not a teleport — sampled continuity), (2) the step-out did NOT
  //   teleport (no discontinuous jump at the handoff), and (3) the renderer exposure EASED from the
  //   wake lift toward the desert base over ~1.8s (monotone-ish descent, no single-frame snap).
  //   The real-KCC walk is driven by a FIXED-DT sim-budget loop (see below) so the proof is
  //   DETERMINISTIC under the ~2 fps headless swiftshader tab — no wall-clock timing dependence.
  'pod-walkout': async (page) => {
    const log = await page.evaluate(async () => {
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      // ── DETERMINISTIC DRIVER (throttle-proof). The OLD driver was wall-clock end to end: the
      //    impact/wake setup slept 2600+600 ms and the walk loop held W for 90×70 ms, measuring
      //    however far the KCC happened to travel — but the headless swiftshader tab renders this
      //    heavy scene at ~1-2 fps, so BOTH legs raced a starved loop: (a) the wake beat's init tick
      //    could MISS the 600 ms window, so forcing phase='climb' got undone by the late init
      //    (blowCabinHatch(0) re-shut the door + mode='seated' → walkedOutZ≈0, flaky), and (b) the
      //    walked distance swung run-to-run (~−5.6..−6.9 m; could dip under the −2.0 GATE-2 floor).
      //    THE FIX (same technique as pod-walkin / smokeExposureEase): pin the loop's dt to FIXED_DT
      //    so every ticked frame advances a KNOWN sim-dt, drive the impact→wake chain by its REAL
      //    phase-flip conditions, and drive the walk until a SIM-TIME budget elapses — never a
      //    wall-clock count. The assertions below are UNCHANGED and strict.
      const FIXED_DT = 0.05;      // sim-seconds per frame (under the loop's 0.1 clamp → never clamped)
      const SIM_BUDGET = 2.0;     // sim-seconds of walking: at WALK_SPEED 6 m/s → ~11 m out the door
                                  //   (well past the −2.0 GATE-2 floor + the 2.2 m stepOut climb gate)
      /** Drive the live loop until cond() or simBudget sim-seconds. Stall-bail: ~10 s of yields with
       *  no ticked frame → the loop is wedged, bail (a long BLOCKING frame can't false-trip it —
       *  these yields don't run while the main thread is blocked either). */
      const drive = async (simBudget, cond, perTick) => {
        const simStart = ctx.time.elapsed;
        let lastSim = simStart, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          if (perTick) perTick();
          await sleep(16);
          const nowSim = ctx.time.elapsed;
          if (nowSim > lastSim + 1e-6) { lastSim = nowSim; stalls = 0; }
          else if (++stalls > 600) break;
          if (cond()) return { ok: true, sim: +(nowSim - simStart).toFixed(2) };
          if (nowSim - simStart >= simBudget) break;
        }
        return { ok: cond(), sim: +(ctx.time.elapsed - simStart).toFixed(2) };
      };
      const realClock = ctx.three.clock;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      const cam = ctx.three.camera;
      let expoAtWake = 0, wakeInitOk = false;
      let inside = { x: 0, y: 0, z: 0 };
      let maxJump = 0;          // the largest single-tick position jump (a teleport would spike this)
      let reachedStepOut = false;
      let teleportAtHandoff = 0;
      let framesTicked = 0, simElapsed = 0;
      try {
        realClock.getDelta = () => FIXED_DT;             // pin the per-frame sim-dt (throttle-proof)
        ctx.three.renderer.setSize(48, 48, false);       // tiny canvas → more REAL frames tick per second (no screenshots in this gate)
        g.startIntro();
        // run through the crash → the REAL impact beat auto-advances → wake, whose init tick seats
        //   the player inside the crashed cabin + lifts the exposure. Driven by the CHAIN's own
        //   conditions (impact runs IMPACT_FADE+IMPACT_HOLD = 2.7 sim-s, then advanceBeat → wake).
        g.jumpToBeat('impact');
        const rWake = await drive(4.5, () => ctx.intro && ctx.intro.beat === 'wake' && ctx.intro.scratch.init === true);
        wakeInitOk = rWake.ok;
        expoAtWake = ctx.three.renderer.toneMappingExposure;   // the lifted wake exposure (~1.62)
        // FORCE the wake to its walk-out-ready state deterministically (the come-to fade phases are
        //   proven by smokeIntro; this gate proves the WALK). Safe now: the wake init has PROVABLY
        //   run (rWake cond), so no late init will undo this. Blow the FRONT door fully open + hand
        //   control to WALK — the exact end-state of the wake 'blowing'→'climb' phases.
        g.blowCabinHatch(1);                 // kick the −Z front door wide (the wake exit)
        const f = document.getElementById('intro-fade'); if (f) f.style.opacity = '0';   // clear the come-to overlay
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.intro.scratch.phase = 'climb'; ctx.intro.scratch.t = 0; }
        // record the spawn (inside the cabin) — the walk-out must MOVE the body from here, not teleport.
        const p0 = ctx.player.body.body.translation();
        inside = { x: p0.x, y: p0.y, z: p0.z };
        // WALK OUT the −Z front door on real legs: face −Z, hold W (forward = −Z), sample the path
        //   each yield (proves the motion is continuous). Terminated by the SIM budget.
        cam.rotation.order = 'YXZ';
        let prev = { x: inside.x, y: inside.y, z: inside.z };
        const simStart = ctx.time.elapsed;
        let lastSim = simStart, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          cam.rotation.set(-0.05, 0, 0);   // face −Z (yaw 0) → W walks toward/through the −Z front door
          ctx.input.keys['KeyW'] = true;   // re-assert each iteration (endInputFrame clears pressed; keys persist, belt-and-braces)
          await sleep(16);                 // yield so real rAF frames tick between samples
          const t = ctx.player.body.body.translation();
          const jump = Math.hypot(t.x - prev.x, t.z - prev.z);
          if (jump > maxJump) maxJump = jump;
          prev = { x: t.x, y: t.y, z: t.z };
          // the wake-climb advanced to stepOut (or handed off) — capture whether the body JUMPED at that
          //   moment (a teleport-to-returnPos would spike jump exactly here; the real flow does NOT teleport).
          if (!reachedStepOut && ctx.intro && (ctx.intro.beat === 'stepOut' || !ctx.intro.active)) {
            reachedStepOut = true; teleportAtHandoff = jump;
          }
          const nowSim = ctx.time.elapsed;
          if (nowSim > lastSim + 1e-6) { lastSim = nowSim; stalls = 0; }
          else if (++stalls > 600) break;   // ~10 s of yields with no ticked frame → loop wedged, bail
          simElapsed = nowSim - simStart;
          framesTicked = Math.round(simElapsed / FIXED_DT);
          if (simElapsed >= SIM_BUDGET) break;
        }
      } finally {
        ctx.input.keys['KeyW'] = false;
        realClock.getDelta = origGetDelta;               // restore the real clock (leak-free)
        ctx.three.renderer.setSize(origW, origH, false); // restore the canvas
      }
      const pOut = ctx.player.body.body.translation();
      const walkedOutZ = pOut.z - inside.z;   // negative = walked −Z out the front door

      // ── ZERO-SHIFT EXPOSURE PROOF (W6 item 5). The wake NO LONGER lifts the exposure — it stays at
      //    the desert base (1.05) from the crash onward, so there is nothing to ease and no washed-out
      //    exit. __game.smokeExposureConstant() drives the crash-pose settle 0→1 and asserts the
      //    renderer exposure is CONSTANT at 1.05 across the whole settle (min==max==base).
      const easeReport = g.smokeExposureConstant();
      // ── WORLD-LIGHT LEAK CENSUS (2026-07-05 — the parked-pod global-light bug): after step-out
      //    NO scene-global light (Directional/Hemisphere) may be lit except the core sun/moon set.
      //    The persisted pod's fill+rakes once parked LIT (~3.7 units over the whole desert:
      //    "too bright, shadows gone, day/night has no effect"). This census makes that class
      //    machine-caught forever.
      const foreignGlobals = [];
      ctx.three.scene.traverse((o) => {
        if ((o.isDirectionalLight || o.isHemisphereLight) && o.intensity > 0.01 &&
            o !== ctx.lights.sun && o !== ctx.lights.moon && o !== ctx.lights.ambient) {
          foreignGlobals.push({ type: o.type, name: o.name || '(unnamed)', intensity: +o.intensity.toFixed(2) });
        }
      });
      return {
        walkExpoAtWake: +expoAtWake.toFixed(3), walkExpoFinal: +ctx.three.renderer.toneMappingExposure.toFixed(3),
        ease: easeReport, foreignGlobals,
        inside: [+inside.x.toFixed(2), +inside.z.toFixed(2)], walkedOutZ: +walkedOutZ.toFixed(2),
        maxJump: +maxJump.toFixed(2), reachedStepOut, teleportAtHandoff: +teleportAtHandoff.toFixed(2),
        driver: { simElapsed: +simElapsed.toFixed(2), framesTicked, wakeInitOk },   // deterministic-driver diagnostics
      };
    });
    console.log('[pod-walkout] ' + JSON.stringify(log));
    // GATE 0 — the SETUP proved itself: the real impact→wake chain advanced + the wake init tick ran
    //   (seats the player inside the crashed cabin). Without this, a walk failure below would be a
    //   confusing symptom of a broken setup, not a broken walk-out.
    if (!log.driver.wakeInitOk) throw new Error(`pod-walkout GATE FAILED: the impact→wake chain never initialised the wake (driver=${JSON.stringify(log.driver)}) — the crash-chain setup is broken.`);
    // GATE 1 — the player physically WALKED OUT (moved −Z out the front door onto the terrain).
    if (log.walkedOutZ > -1.0) throw new Error(`pod-walkout GATE FAILED: the body only moved z=${log.walkedOutZ} out the door (expected < −1.0 — the walk-out path is blocked or the door didn't open).`);
    // GATE 2 — NO TELEPORT: a stepOut teleport-to-returnPos would SNAP the body back near the spawn
    //   (returnPos ≈ the inside/origin) — but the player ends where they WALKED (z well past the door),
    //   proving no teleport. The definitive no-teleport signal is the END POSITION: a real teleport to
    //   returnPos would land the body back at |Δz|≈0, not the ~−11 m the deterministic driver walks to.
    if (Math.abs(log.walkedOutZ) < 2.0) throw new Error(`pod-walkout GATE FAILED: the body ended only ${log.walkedOutZ}m from the spawn — a teleport-back-to-returnPos would land here; the walk-out should leave the player where they WALKED (well out the door).`);
    // a per-tick jump far beyond any walking step WOULD be a teleport. With the fixed-dt driver the KCC
    //   step is a steady ~0.6 m (FIXED_DT 0.05 s × WALK_SPEED 6 m/s); the 3.0 m ceiling flags a real snap.
    if (log.maxJump > 3.0) throw new Error(`pod-walkout GATE FAILED: a discontinuous ${log.maxJump}m jump (a teleport, not a KCC step) occurred during the walk-out.`);
    // GATE 3 — the wake-climb advanced to stepOut (the walk-out → stepOut chain fired).
    if (!log.reachedStepOut) throw new Error(`pod-walkout GATE FAILED: the walk-out never advanced to stepOut (the climb-out distance gate didn't fire).`);
    // GATE 4 — ZERO-SHIFT EXPOSURE (W6 item 5): the exposure is CONSTANT at the desert base (1.05)
    //   across the whole crash-pose settle — the wake never lifts it, so there's no washed-out exit
    //   + nothing to ease. Both the settle-sweep (smokeExposureConstant) AND the live wake capture
    //   must sit at the base.
    if (!log.ease || !log.ease.ok || !log.ease.constant) throw new Error(`pod-walkout GATE FAILED: the exposure is NOT CONSTANT at the desert base across the crash settle — smokeExposureConstant=${JSON.stringify(log.ease)} (expected min==max==${log.ease ? log.ease.base : '1.05'}).`);
    if (Math.abs(log.walkExpoAtWake - 1.05) > 1e-2) throw new Error(`pod-walkout GATE FAILED: the LIVE wake exposure lifted to ${log.walkExpoAtWake} (expected 1.05 — the wake must not lift the exposure; W6 item 5).`);
    if (Math.abs(log.walkExpoFinal - 1.05) > 1e-2) throw new Error(`pod-walkout GATE FAILED: the exposure ended at ${log.walkExpoFinal} after the walk-out (expected 1.05 — bit-stable across the exit).`);
    if (log.foreignGlobals && log.foreignGlobals.length) throw new Error(`pod-walkout GATE FAILED — WORLD-LIGHT LEAK: scene-global lights lit after step-out (the whole desert gets washed; shadows fill flat; night never darkens): ${JSON.stringify(log.foreignGlobals)}`);
    console.log(`[pod-walkout] GATE PASS — kicked the front door + walked OUT on real legs (Δz=${log.walkedOutZ}m over ${log.driver.simElapsed}s sim / ${log.driver.framesTicked} fixed-dt frames, maxJump=${log.maxJump}m, handoff jump=${log.teleportAtHandoff}m = NO teleport), reached stepOut, and the exposure held CONSTANT at ${log.ease.base} (wake=${log.walkExpoAtWake}, settle min/max=${log.ease.min}/${log.ease.max}) — zero-shift handoff.`);
  },

  // W6 item 4 GATE — the IMPACT VIEW NEVER LEAVES THE POD. Drives the real descent→parachute→impact
  //   →wake chain with a FIXED sim-dt and, each ticked frame from the ground-approach through the
  //   crash-settle + wake, probes whether the camera EYE is inside the (possibly-tilted) cabin shell
  //   (probeEyeInCabin). Asserts the eye stays INSIDE the whole time — no frame where the view clips
  //   outside the pod (the "seeing above the pod / the landscape" bug). The bug this catches: the
  //   body left ~20 m up when the cabin grounded at impact → the eye hung above the pod for a few frames.
  'impact-eye': async (page) => {
    const log = await page.evaluate(async () => {
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const g = window.__game;
      const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      const FIXED_DT = 0.05;
      const realClock = ctx.three.clock;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      const cam = ctx.three.camera;
      let worstMargin = 999;        // the smallest radial margin seen (negative = clipped outside the wall)
      let worstReport = null;
      let anyOutside = false, framesProbed = 0, sawImpact = false, sawWake = false;
      const beatsSeen = {};
      try {
        realClock.getDelta = () => FIXED_DT;
        ctx.three.renderer.setSize(48, 48, false);
        g.startIntro();
        // enter the descent LATE (near the ground) so we exercise the ground-approach → impact → wake
        //   frames densely; then let the chain auto-advance through parachute → impact → wake.
        g.jumpToBeat('descent');
        // drive frames; sample the eye vs cabin each ticked frame once we're at/after the parachute
        //   (the ground-approach) and all the way through wake's come-to.
        const simStart = ctx.time.elapsed;
        let lastSim = simStart, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          await sleep(16);
          const beat = ctx.intro ? ctx.intro.beat : 'done';
          beatsSeen[beat] = (beatsSeen[beat] || 0) + 1;
          if (beat === 'impact') sawImpact = true;
          if (beat === 'wake') sawWake = true;
          // probe from the parachute (ground-approach) through impact + wake — the window the bug lived in.
          if (beat === 'parachute' || beat === 'impact' || beat === 'wake') {
            const eye = { x: cam.position.x, y: cam.position.y, z: cam.position.z };
            const r = g.probeEyeInCabin(eye);
            if (r.built) {
              framesProbed++;
              if (!r.inside) anyOutside = true;
              if (r.radialMargin < worstMargin) { worstMargin = r.radialMargin; worstReport = { beat, ...r }; }
            }
          }
          const nowSim = ctx.time.elapsed;
          if (nowSim > lastSim + 1e-6) { lastSim = nowSim; stalls = 0; }
          else if (++stalls > 600) break;
          // stop a couple seconds into wake (past the come-to fade) — the whole impact→wake window is covered.
          if (sawWake && (beatsSeen['wake'] || 0) > 30) break;
          if (nowSim - simStart > 40) break;   // hard sim-time cap
        }
      } finally {
        realClock.getDelta = origGetDelta;
        ctx.three.renderer.setSize(origW, origH, false);
        if (window.__game.ctx.intro && window.__game.ctx.intro.active) { try { window.__game.skipIntro(); } catch {} }
      }
      return { anyOutside, framesProbed, sawImpact, sawWake, worstMargin: +worstMargin.toFixed(3), worstReport, beatsSeen };
    });
    console.log('[impact-eye] ' + JSON.stringify(log));
    if (!log.sawImpact) throw new Error(`impact-eye GATE FAILED: the chain never reached the impact beat (beatsSeen=${JSON.stringify(log.beatsSeen)}).`);
    if (!log.sawWake) throw new Error(`impact-eye GATE FAILED: the chain never reached the wake beat (beatsSeen=${JSON.stringify(log.beatsSeen)}).`);
    if (log.framesProbed < 10) throw new Error(`impact-eye GATE FAILED: too few eye probes (${log.framesProbed}) — the descent/impact window wasn't exercised.`);
    if (log.anyOutside) throw new Error(`impact-eye GATE FAILED: the camera eye CLIPPED OUTSIDE the cabin on at least one frame (worst=${JSON.stringify(log.worstReport)}) — the view left the pod during impact/wake (the "seeing above the pod / the landscape" bug).`);
    console.log(`[impact-eye] GATE PASS — the eye stayed INSIDE the cabin across ${log.framesProbed} probed frames through impact→wake (worst radial margin=${log.worstMargin}m, all inside). The view never leaves the pod.`);
  },

  // W6 item 5 GATE — THE ZERO-SHIFT HANDOFF. The visible world must be BIT-STABLE across the exit
  //   threshold: exposure, fog density, sun intensity, and the diurnal clock must NOT snap at the
  //   wake, at step-out, or after handoff — the wake IS the survival world; walking out is just a
  //   door. Drives the real chain to wake, then to step-out + handoff + 5 s of gameplay, sampling
  //   the world state at each point and asserting they match (within tight tolerances). The clock
  //   ADVANCES continuously (that's fine — it must not SNAP BACKWARD); exposure/fog/sun hold.
  'zero-shift-handoff': async (page) => {
    const log = await page.evaluate(async () => {
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const g = window.__game;
      const ctx = g.ctx;
      const FIXED_DT = 0.05;
      const realClock = ctx.three.clock;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      const sample = () => ({
        expo: +ctx.three.renderer.toneMappingExposure.toFixed(4),
        fog: ctx.three.scene.fog && ctx.three.scene.fog.density != null ? +ctx.three.scene.fog.density.toFixed(6) : null,
        sun: ctx.lights && ctx.lights.sun ? +ctx.lights.sun.intensity.toFixed(4) : null,
        dayTime: +ctx.time.dayTime.toFixed(4),
      });
      const drive = async (cond, budget) => {
        const start = ctx.time.elapsed; let last = start, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          await sleep(16);
          if (cond()) return true;
          const now = ctx.time.elapsed;
          if (now > last + 1e-6) { last = now; stalls = 0; } else if (++stalls > 600) break;
          if (now - start > budget) break;
        }
        return cond();
      };
      let atWake = null, atStepOut = null, afterHandoff = null, reachedWake = false, reachedStepOut = false, handedOff = false;
      try {
        realClock.getDelta = () => FIXED_DT;
        ctx.three.renderer.setSize(48, 48, false);
        g.startIntro();
        // run the REAL descent → crash → wake so the fog/exposure/time are set by the actual flow.
        g.jumpToBeat('descent');
        reachedWake = await drive(() => ctx.intro && ctx.intro.beat === 'wake' && ctx.intro.scratch.init === true, 30);
        atWake = sample();
        // force the wake to walk-out-ready + walk out to trigger stepOut → endEscapePodIntro.
        g.blowCabinHatch(1);
        const f = document.getElementById('intro-fade'); if (f) f.style.opacity = '0';
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.intro.scratch.phase = 'climb'; ctx.intro.scratch.t = 0; }
        const cam = ctx.three.camera; cam.rotation.order = 'YXZ';
        // capture the moment we enter stepOut (the unify has just run — the pod is now the persistent world object).
        reachedStepOut = await drive(() => { cam.rotation.set(-0.05, 0, 0); ctx.input.keys['KeyW'] = true; return ctx.intro && ctx.intro.beat === 'stepOut'; }, 6);
        atStepOut = sample();
        ctx.input.keys['KeyW'] = false;
        // let stepOut's REVEAL_DWELL elapse → endEscapePodIntro (handoff), then 5 s of gameplay.
        handedOff = await drive(() => !ctx.intro || !ctx.intro.active, 8);
        await drive(() => false, 5);   // 5 s of real gameplay ticks (the fog-ease window that USED to exist)
        afterHandoff = sample();
      } finally {
        realClock.getDelta = origGetDelta;
        ctx.three.renderer.setSize(origW, origH, false);
        if (ctx.intro && ctx.intro.active) { try { g.skipIntro(); } catch {} }
      }
      return { atWake, atStepOut, afterHandoff, reachedWake, reachedStepOut, handedOff };
    });
    console.log('[zero-shift-handoff] ' + JSON.stringify(log));
    if (!log.reachedWake) throw new Error(`zero-shift-handoff GATE FAILED: never reached wake (${JSON.stringify(log)}).`);
    if (!log.reachedStepOut) throw new Error(`zero-shift-handoff GATE FAILED: never reached stepOut (${JSON.stringify(log)}).`);
    if (!log.handedOff) throw new Error(`zero-shift-handoff GATE FAILED: the intro never handed off (${JSON.stringify(log)}).`);
    const w = log.atWake, s = log.atStepOut, a = log.afterHandoff;
    // EXPOSURE — constant 1.05 at every point (no lift, no ease).
    for (const [tag, p] of [['wake', w], ['stepOut', s], ['afterHandoff', a]]) {
      if (Math.abs(p.expo - 1.05) > 1e-2) throw new Error(`zero-shift-handoff GATE FAILED: exposure at ${tag} was ${p.expo} (expected 1.05 — no lift/ease anywhere).`);
    }
    // FOG — bit-stable across the exit (already at survival by the crash; no clear pin, no ease). The
    //   wake→stepOut→afterHandoff fog must not jump (tolerance covers float noise, not a visible shift).
    if (Math.abs(w.fog - s.fog) > 2e-5 || Math.abs(s.fog - a.fog) > 2e-5) throw new Error(`zero-shift-handoff GATE FAILED: fog density shifted across the exit — wake=${w.fog} stepOut=${s.fog} afterHandoff=${a.fog} (must be bit-stable; the fog is already survival by the crash).`);
    // SUN intensity — bit-stable (the midday sun the pod fell under continues; no relight at exit).
    if (w.sun != null && (Math.abs(w.sun - s.sun) > 0.05 || Math.abs(s.sun - a.sun) > 0.1)) throw new Error(`zero-shift-handoff GATE FAILED: sun intensity shifted across the exit — wake=${w.sun} stepOut=${s.sun} afterHandoff=${a.sun}.`);
    // CLOCK — must ADVANCE (or hold), never SNAP BACKWARD (the old setIntroMiddayClear re-set was a backward jump).
    const wrap = (b, x) => x < b - 0.5 ? x + 1 : x;   // handle a midnight wrap (won't happen at midday, but be safe)
    if (wrap(w.dayTime, s.dayTime) < w.dayTime - 1e-4 || wrap(s.dayTime, a.dayTime) < s.dayTime - 1e-4) throw new Error(`zero-shift-handoff GATE FAILED: the diurnal clock SNAPPED BACKWARD across the exit — wake=${w.dayTime} stepOut=${s.dayTime} afterHandoff=${a.dayTime} (the clock must continue, not reset).`);
    console.log(`[zero-shift-handoff] GATE PASS — the world is bit-stable across the exit: exposure ${w.expo}/${s.expo}/${a.expo} (constant 1.05), fog ${w.fog}/${s.fog}/${a.fog} (stable), sun ${w.sun}/${s.sun}/${a.sun} (stable), clock ${w.dayTime}→${s.dayTime}→${a.dayTime} (continuous, no backward snap). The wake IS the survival world.`);
  },

  // B2 dev diagnostic — dump every physics collider whose AABB centre falls in the pod-bay boarding
  //   region (relative to the bridge spawn) so a blocked walk-in path can be diagnosed exactly.
  'bay-probe': async (page) => {
    const out = await page.evaluate(async () => {
      const g = window.__game;
      const ctx = g.ctx;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      ctx.flags.paused = false;
      ctx.input.controls.isLocked = true;
      try { g.skipIntro(); } catch {}
      await sleep(200);
      g.startIntro();
      g.jumpToBeat('cockpit');
      for (let i = 0; i < 20; i++) { await sleep(120); if (ctx.player.body.body.translation().y > 2900) break; g.jumpToBeat('cockpit'); }
      const sp = ctx.player.body.body.translation();
      const SHIP = { x: sp.x, y: sp.y - 0.85, z: sp.z + 0.30 };   // bridge spawn → ship origin (seat at z −0.30; body centre ≈ +0.85)
      const hits = [];
      ctx.physics.world.forEachCollider((col) => {
        const t = col.translation();
        const lx = t.x - SHIP.x, lz = t.z - SHIP.z;
        if (t.y < SHIP.y - 2 || t.y > SHIP.y + 6) return;      // ship-deck band only
        const sh = col.shape;
        // AABB-overlap the boarding region (a long wall's CENTRE can sit far outside it).
        const hx = sh.halfExtents ? Math.max(sh.halfExtents.x, sh.halfExtents.z) : (sh.radius || 0.5);
        const hz = hx;
        if (lx + hx < -4.5 || lx - hx > 1.5 || lz + hz < 2.0 || lz - hz > 7.5) return;
        const desc = { type: sh.type, x: +lx.toFixed(2), y: +(t.y - SHIP.y).toFixed(2), z: +lz.toFixed(2) };
        if (sh.halfExtents) { desc.he = [+sh.halfExtents.x.toFixed(2), +sh.halfExtents.y.toFixed(2), +sh.halfExtents.z.toFixed(2)]; }
        if (sh.radius != null) desc.r = +sh.radius.toFixed(2);
        if (sh.halfHeight != null) desc.hh = +sh.halfHeight.toFixed(2);
        const q = col.rotation();
        const yaw = Math.atan2(2 * (q.w * q.y + q.x * q.z), 1 - 2 * (q.y * q.y + q.z * q.z));
        if (Math.abs(yaw) > 0.01) desc.yawDeg = +(yaw * 180 / Math.PI).toFixed(0);
        hits.push(desc);
      });
      hits.sort((a, b) => a.x - b.x);
      // ── KCC blocker interrogation: park the capsule AT the stall point on the door centreline and
      //    ask the character controller for a −X step; report exactly which collider(s) it hits.
      ctx.flags.paused = true;   // freeze the sim so nothing re-moves the body under us
      const pb = ctx.player.body;
      pb.body.setTranslation({ x: SHIP.x - 0.7, y: sp.y, z: SHIP.z + 4.8 }, true);
      pb.controller.computeColliderMovement(pb.collider, { x: -0.6, y: -0.05, z: 0 });
      const mv = pb.controller.computedMovement();
      const cols = [];
      try {
        const n = pb.controller.numComputedCollisions();
        for (let i = 0; i < n; i++) {
          const c = pb.controller.computedCollision(i);
          if (!c || !c.collider) continue;
          const ct = c.collider.translation();
          const cs = c.collider.shape;
          cols.push({
            type: cs.type, x: +(ct.x - SHIP.x).toFixed(2), y: +(ct.y - SHIP.y).toFixed(2), z: +(ct.z - SHIP.z).toFixed(2),
            he: cs.halfExtents ? [+cs.halfExtents.x.toFixed(2), +cs.halfExtents.y.toFixed(2), +cs.halfExtents.z.toFixed(2)] : undefined,
            r: cs.radius != null ? +cs.radius.toFixed(2) : undefined,
            n1: c.normal1 ? [+c.normal1.x.toFixed(2), +c.normal1.y.toFixed(2), +c.normal1.z.toFixed(2)] : undefined,
          });
        }
      } catch (e) { cols.push({ err: String(e) }); }
      ctx.flags.paused = false;
      return { shipY: +SHIP.y.toFixed(1), n: hits.length, hits, kcc: { moved: [+mv.x.toFixed(3), +mv.y.toFixed(3), +mv.z.toFixed(3)], cols } };
    });
    console.log('[bay-probe] shipY=' + out.shipY + ' n=' + out.n);
    for (const h of out.hits) console.log('[bay-probe] ' + JSON.stringify(h));
    console.log('[bay-probe][kcc] ' + JSON.stringify(out.kcc));
  },

  // FLAG-OFF byte-identical GATE — a normal (no-intro) game save must write NO podCrash field, so
  // the live game is unaffected by this feature. enterLive already ran enterGame (a normal dev game,
  // NO intro/unify); we just save + assert the field is absent. THROWS on failure.
  'pod-persistence-flagoff': async (page) => {
    const r = await page.evaluate(() => {
      const g = window.__game;
      const sv = g.saveGame();
      const raw = localStorage.getItem('dustfall.save.v1');
      const parsed = raw ? JSON.parse(raw) : {};
      return { saveOk: sv.ok, hasPodCrash: 'podCrash' in parsed };
    });
    console.log(`[pod-persistence-flagoff] ${JSON.stringify(r)}`);
    if (!r.saveOk || r.hasPodCrash) throw new Error(`FLAG-OFF GATE FAILED — a no-pod save wrote podCrash: ${JSON.stringify(r)}`);
    console.log('[pod-persistence-flagoff] PASS — no podCrash in a normal (no-pod) save.');
  },

  // Pod-tutorial GATE — the craft→salvage→chute-pop loop, headless. Mirrors smoke-intro's gate.
  'smoke-pod-tutorial': async (page) => {
    const r = await page.evaluate(() => window.__game.smokePodTutorial());
    console.log(`[smoke-pod-tutorial] ${JSON.stringify(r)}`);
    if (!r || !r.ok) throw new Error(`smoke-pod-tutorial GATE FAILED: ${JSON.stringify(r)}`);
  },

  // ── Y3 fix 8 — DOOR-FLUSH-AUDIT: the merged front door must read PERFECTLY FLUSH (pivot rotation
  //    == 0 exactly) at EVERY sealed state (bay pre-open, post-seal, descent altitudes, impact, wake
  //    pre-kick). Steps each state, reads probeCabinDoor()/the bay pivot, and GATES local rotation.y
  //    == 0 (and local x/z == 0). THROWS on any drift. No screenshot — a hard assertion.
  'door-flush-audit': async (page) => {
    const log = await page.evaluate(async () => {
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const g = window.__game; const ctx = g.ctx;
      const realClock = ctx.three.clock;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      const rows = [];
      const EPS = 1e-3;
      const readRide = (label) => {
        const p = g.probeCabinDoor();   // the RIDE/landed cabin's front-door pivot
        rows.push({ label, kind: 'ride', built: p.built, localX: p.localX, localY: p.localY, localZ: p.localZ, ajarY: p.ajarY });
        return p;
      };
      const readBay = (label) => {
        const pod = ctx.three.scene.getObjectByName('dockedCanonicalPod') || ctx.three.scene.getObjectByName('canonicalPod');
        let localY = null, found = false;
        if (pod) { pod.traverse((o) => { if (o.name === 'canonicalPodDoor') { found = true; localY = +o.rotation.y.toFixed(4); } }); }
        rows.push({ label, kind: 'bay', built: found, localY });
        return { found, localY };
      };
      try {
        realClock.getDelta = () => 0.05;
        ctx.three.renderer.setSize(48, 48, false);
        // 1) BAY pre-open (the docked pod door sealed, before the player E-opens it).
        g.startIntro(); g.jumpToBeat('cockpit');
        const driveBay = async () => { for (let i = 0; i < 120; i++) { await sleep(16); if (ctx.three.scene.getObjectByName('dockedCanonicalPod')) return; } };
        await driveBay();
        readBay('bay pre-open (docked, sealed)');
        // 1b) MID-RELEASE sampling (live-test 1h coverage hole: the audit only checked RESTING
        //     sealed states while releasePodFromBay's old door rattle read as "tilted" IN TRANSIT —
        //     the player now rides the bay pod through the release). Drive the real shipExplode
        //     release and assert the bay door pivot stays pinned (the rattle fix) until the ship
        //     disposes at the release end (found:false rows are skipped by the gate).
        g.jumpToBeat('shipExplode');
        for (let i = 0; i < 6; i++) {
          await sleep(120);
          const r = readBay(`mid-release sample ${i}`);
          if (!r.found) break;   // phase B disposed the ship — the release window is over
        }
        // 2) RIDE cabin sealed states — drive the descent chain + sample the front-door pivot sealed.
        g.jumpToBeat('descent');
        const driveTo = async (cond, budget) => { const s0 = ctx.time.elapsed; let last = s0, st = 0; for (let i = 0; i < 8000; i++) { await sleep(16); const n = ctx.time.elapsed; if (n > last + 1e-6) { last = n; st = 0; } else if (++st > 400) break; if (cond()) return true; if (n - s0 >= budget) break; } return cond(); };
        // sample the sealed door at several descent altitudes (the user still saw crooked in SOME phases)
        for (const d of [0.02, 0.15, 0.5, 0.9]) {
          try { g.setDescentProgress(d); } catch {}
          await sleep(60);
          readRide(`descent p=${d} (sealed)`);
        }
        // 3) impact (the crash settles the cabin — the door must still read sealed/flush pre-kick)
        await driveTo(() => ctx.intro && ctx.intro.beat === 'impact' && ctx.intro.scratch.init === true, 25);
        await sleep(80); readRide('impact (crash, pre-kick)');
        // 4) wake pre-kick (comeTo — the blast cracked it AJAR; the FLUSH audit is the pre-ajar seal, so
        //    we assert the ajar REST value is the intended _cabinHatchAjarY (0), i.e. sealed-then-ajar==0).
        await driveTo(() => ctx.intro && ctx.intro.beat === 'wake' && ctx.intro.scratch.init === true, 10);
        await sleep(80);
        // force the sealed pre-ajar read: blowCabinHatch(0) sets the ajar rest; the FLUSH contract is the
        //   SEALED pivot == 0. Read the ajar rest value (should be 0 = the door was flush before the kick).
        const preKick = readRide('wake pre-kick (ajar rest)');
        rows[rows.length - 1].note = `ajarY=${preKick.ajarY} (0 = the door was flush/sealed before the blast cracked it)`;
      } finally { realClock.getDelta = origGetDelta; ctx.three.renderer.setSize(origW, origH, false); }
      return { rows, EPS };
    });
    console.log('[door-flush-audit]');
    for (const r of log.rows) console.log('  ' + JSON.stringify(r));
    // GATE: every SEALED state must read the door pivot local rotation.y == 0 (and x/z == 0 for the ride).
    const EPS = 1e-3;
    const fails = [];
    for (const r of log.rows) {
      if (!r.built) continue;   // (a dev jump may not build a given door — the built states are what we gate)
      // the ride pivot: local (x,y,z) must all be ~0 when sealed; the ajar-rest read is gated on ajarY==0.
      if (r.kind === 'ride') {
        const ajar = r.label.includes('ajar rest');
        const y = ajar ? r.ajarY : r.localY;
        if (Math.abs(y) > EPS || Math.abs(r.localX) > EPS || Math.abs(r.localZ) > EPS) fails.push(r);
      } else {   // bay
        if (Math.abs(r.localY) > EPS) fails.push(r);
      }
    }
    if (fails.length) throw new Error(`door-flush-audit GATE FAILED — the door DRIFTED from flush (rotation != 0) in: ${JSON.stringify(fails)}`);
    console.log(`[door-flush-audit] GATE PASS — the door read PERFECTLY FLUSH (pivot == 0) at every sealed state (${log.rows.filter((r) => r.built).length} states checked).`);
  },

  // ── LANDED-DOORWAY-DIAG (round-2a): the REAL landed 'escapePodCabin' with the door OPEN.
  //    Drives the real crash→wake→stepOut→skipIntro chain (like crashed-pod), OPENS the front
  //    door, then fires a RAYCAST FAN from the user's exact OUTSIDE vantage (standing ~2m out on
  //    the −Z door side at eye height, aiming through the LOWER doorway) and names the FIRST
  //    opaque hit per ray + its nearest-named ancestor + pod-local Y. Any near hit that isn't the
  //    interior deck/wall names the blocking exterior-skin band/lathe/foot. Also renders the shot.
  'landed-doorway-diag': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1100, 820, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 820; cam.updateProjectionMatrix(); }
      g.startIntro();
      g.jumpToBeat('impact');
    });
    await page.waitForTimeout(2600);
    await page.evaluate(() => { window.__game.jumpToBeat('wake'); });
    await page.waitForTimeout(1600);
    await page.evaluate(() => { window.__game.jumpToBeat('stepOut'); });
    await page.waitForTimeout(1400);
    await page.evaluate(() => { window.__game.skipIntro(); });
    await page.waitForTimeout(900);
    const camMode = argv.angle || 'outside';
    const diag = await page.evaluate((camMode) => {
      const g = window.__game; const ctx = g.ctx;
      const THREE = g.THREE;
      g.setTime(0.32);
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.12;
      ctx.three.renderer.toneMappingExposure = 1.25;
      ctx.flags.paused = true;
      const V = THREE.Vector3;
      const pod = ctx.three.scene.getObjectByName('escapePodCabin');
      if (!pod) return { error: 'escapePodCabin not found' };
      pod.updateMatrixWorld(true);
      const podWorld = pod.getWorldPosition(new V());
      // BLOW the front door fully open (the wake-exit state), so the aperture is clear of the slab.
      try { g.blowCabinHatch(1); } catch {}
      pod.updateMatrixWorld(true);
      // Front door outward normal: FDOOR_AZ = π → world (sin π, cos π) = (0,-1) at pod yaw≈0, but the
      //   pod settled with a small crash tilt — use the pod's actual −Z world axis for the door face.
      const haz = Math.PI;
      const nrm = new V(Math.sin(haz), 0, Math.cos(haz)).applyQuaternion(pod.quaternion); nrm.y = 0; nrm.normalize();
      const sillWorldY = podWorld.y + 0.11;   // aperture bottom (FDOOR_CY 1.10 − FDOOR_H/2 0.99)
      const side = new V().crossVectors(nrm, new V(0, 1, 0)).normalize();
      const cam = ctx.three.camera;
      let eye;
      if (camMode === 'inside') {
        // INSIDE looking OUT through the door (no new holes from the interior side) — eye at the deck
        //   centre, seated-ish, aiming out the −Z aperture toward the sand/sky.
        eye = podWorld.clone().add(nrm.clone().multiplyScalar(-0.55)); eye.y = podWorld.y + 1.35;
        cam.position.copy(eye);
        cam.lookAt(podWorld.clone().add(nrm.clone().multiplyScalar(3.0)).setY(podWorld.y + 0.6));
      } else if (camMode === 'oblique') {
        // The user's actual screenshot vantage: standing ~2m out, biased to one side (oblique), eye 1.62.
        eye = podWorld.clone().add(nrm.clone().multiplyScalar(2.3)).add(side.clone().multiplyScalar(1.4)); eye.y = podWorld.y + 1.62;
        cam.position.copy(eye);
        cam.lookAt(podWorld.x, sillWorldY + 0.45, podWorld.z);
      } else {
        // USER VANTAGE (outside, straight on): ~2m out on the door side, standing eye 1.62, aim LOWER doorway.
        eye = podWorld.clone().add(nrm.clone().multiplyScalar(2.1)); eye.y = podWorld.y + 1.62;
        cam.position.copy(eye);
        cam.lookAt(podWorld.x, sillWorldY + 0.35, podWorld.z);
      }
      cam.updateMatrixWorld(true);
      // Aperture plane at the pod's outer door face: podWorld + nrm*(CAB_R+SHELL)=1.44
      const apCenter = podWorld.clone().add(nrm.clone().multiplyScalar(1.44));
      const rc = new THREE.Raycaster();
      const meshes = [];
      pod.traverse((o) => { if (o.isMesh && o.visible && o.material && !o.material.transparent) meshes.push(o); });
      const rows = [];
      const tally = {};
      // scan LOWER HALF of the door: y from sill (0.11) up to mid (~1.15), width ±0.48
      for (let yi = 0; yi <= 6; yi++) {
        const ty = sillWorldY + (yi / 6) * 1.04;
        const cols = [];
        for (let zi = -3; zi <= 3; zi++) {
          const target = apCenter.clone().add(side.clone().multiplyScalar((zi / 3) * 0.48));
          target.y = ty;
          const dir = target.clone().sub(eye).normalize();
          rc.set(eye, dir); rc.far = 5.0;
          const hits = rc.intersectObjects(meshes, false).filter((h) => h.distance > 0.05);
          if (hits.length === 0) { cols.push('·'); continue; }
          const h = hits[0];
          let nm = h.object.name, node = h.object;
          while (!nm && node.parent && node !== pod) { node = node.parent; nm = node.name; }
          nm = nm || (h.object.material && h.object.material.name) || '?';
          const local = pod.worldToLocal(h.point.clone());
          const radial = Math.hypot(local.x, local.z);
          // a NEAR occluder = radial ≥ ~outer body (1.2+) i.e. it's the shell crossing the aperture,
          //   not the far interior wall/deck (which sits at the interior side, radial small or opposite).
          const near = radial > 1.15 && local.z < -0.2;   // outer radius, on the −Z door side
          cols.push({ named: nm, hitY: +h.point.y.toFixed(2), locY: +local.y.toFixed(2), radial: +radial.toFixed(2), dist: +h.distance.toFixed(2), near });
          if (near) tally[nm] = (tally[nm] || 0) + 1;
        }
        rows.push({ ty: +ty.toFixed(2), cols });
      }
      // also: list every mesh whose material is _podScorchFadeMat-like (Lambert vertexColors) and its Y-span
      const suspects = [];
      pod.traverse((o) => {
        if (!o.isMesh || !o.geometry) return;
        o.geometry.computeBoundingBox(); const bb = o.geometry.boundingBox; if (!bb) return;
        // world Y span
        const lo = new V(0, bb.min.y, 0); o.localToWorld(lo);
        const hi = new V(0, bb.max.y, 0); o.localToWorld(hi);
        let nm = o.name, node = o; while (!nm && node.parent && node !== pod) { node = node.parent; nm = node.name; }
        const isLambert = o.material && o.material.type === 'MeshLambertMaterial';
        const podLocalMinY = +(lo.y - podWorld.y).toFixed(2), podLocalMaxY = +(hi.y - podWorld.y).toFixed(2);
        // crosses the lower doorway band (sill 0.11 → mid 1.15)?
        const crossesLowerDoor = podLocalMinY < 1.15 && podLocalMaxY > 0.11;
        if (crossesLowerDoor && (isLambert || /scorch|foot|band|skin|base/i.test(nm || ''))) {
          suspects.push({ named: nm || '?', matType: o.material && o.material.type, vertexColors: !!(o.material && o.material.vertexColors), side: o.material && o.material.side, podLocalMinY, podLocalMaxY });
        }
      });
      ctx.three.renderer.render(ctx.three.scene, cam);
      return {
        podWorld: [+podWorld.x.toFixed(2), +podWorld.y.toFixed(2), +podWorld.z.toFixed(2)],
        podRot: [+pod.rotation.x.toFixed(3), +pod.rotation.y.toFixed(3), +pod.rotation.z.toFixed(3)],
        eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)], sillWorldY: +sillWorldY.toFixed(2),
        rows, blockerTally: tally, suspects,
      };
    }, camMode);
    console.log('[landed-doorway-diag] mode=' + camMode + ' eye ' + JSON.stringify(diag.eye) + ' sillY ' + diag.sillWorldY + ' podRot ' + JSON.stringify(diag.podRot));
    console.log('[landed-doorway-diag] BLOCKER TALLY (near occluders crossing lower doorway): ' + JSON.stringify(diag.blockerTally));
    console.log('[landed-doorway-diag] SUSPECT meshes crossing lower door band:');
    for (const s of (diag.suspects || [])) console.log('  ' + JSON.stringify(s));
    console.log('[landed-doorway-diag] RAY FAN (sill→mid):');
    for (const r of (diag.rows || [])) console.log('  y=' + r.ty + ' ' + JSON.stringify(r.cols));
    await page.waitForTimeout(200);
    // Grab the canvas via toDataURL IN-PAGE (avoids Playwright's screenshot compositor wait that
    //   hangs on the heavy full-desert frame — the known limitation). Force one render first.
    const dataUrl = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.three.renderer.render(ctx.three.scene, ctx.three.camera);
      return ctx.three.renderer.domElement.toDataURL('image/png');
    });
    try {
      const b64 = dataUrl.split(',')[1];
      const fn = `scen-landed-doorway-diag-${camMode}.png`;
      writeFileSync(join(OUT, fn), Buffer.from(b64, 'base64'));
      console.log('[landed-doorway-diag] → ' + fn + ' (canvas toDataURL)');
    } catch (e) { console.log('[landed-doorway-diag] canvas write failed: ' + e.message); }
  },

  // ── Y3 fix 9 — DOORWAY-TORTURE: enter/exit the LANDED pod ×6 across the wake→step-out→tutorial
  //    states on REAL KCC legs. The player must NEVER be blocked from walking IN through the −Z door,
  //    NEVER fall through the floor, and NEVER get trapped inside (the walls exist from the crash, one
  //    state forever). Asserts the body physically crosses the doorway plane in AND out each cycle.
  'doorway-torture': async (page) => {
    const log = await page.evaluate(async () => {
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      const realClock = ctx.three.clock;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      const cam = ctx.three.camera; cam.rotation.order = 'YXZ';
      const FIXED_DT = 0.05;
      const cycles = [];
      let _colliderDump = [];
      let podX = 0, podZ = 0, gy = 0, minY = 1e9, maxJump = 0, everTrapped = false;
      let _diag = null;
      const driveTo = async (cond, budget) => { const s0 = ctx.time.elapsed; let last = s0, st = 0; for (let i = 0; i < 8000; i++) { await sleep(16); const n = ctx.time.elapsed; if (n > last + 1e-6) { last = n; st = 0; } else if (++st > 500) break; if (cond()) return true; if (n - s0 >= budget) break; } return cond(); };
      // WALK in a compass direction for a sim-budget, sampling the path (continuity + floor).
      const walk = async (yaw, budget) => {
        const s0 = ctx.time.elapsed; let last = s0, st = 0;
        let prev = ctx.player.body.body.translation();
        for (let i = 0; i < 8000; i++) {
          cam.rotation.set(-0.02, yaw, 0);
          ctx.input.keys['KeyW'] = true;
          await sleep(16);
          const t = ctx.player.body.body.translation();
          const jump = Math.hypot(t.x - prev.x, t.z - prev.z);
          if (jump > maxJump) maxJump = jump;
          if (t.y < minY) minY = t.y;
          prev = t;
          const n = ctx.time.elapsed;
          if (n > last + 1e-6) { last = n; st = 0; } else if (++st > 500) break;
          if (n - s0 >= budget) break;
        }
        ctx.input.keys['KeyW'] = false;
      };
      try {
        realClock.getDelta = () => FIXED_DT;
        ctx.three.renderer.setSize(48, 48, false);
        // drive the intro to step-out so the pod is the persistent WALK-IN structure (colliders live).
        g.startIntro();
        g.jumpToBeat('impact');   // mirror pod-walkout: impact→wake is the deterministic landed path
        await driveTo(() => ctx.intro && ctx.intro.beat === 'wake' && ctx.intro.scratch.init === true, 25);
        // Hand off to step-out (unify) so the pod is the fully-landed + enterable structure.
        //   Z7 made the wake climb→stepOut advance MOVEMENT-gated (the WAKE_BLOW_FALLBACK time
        //   fallback was removed → progression is player-gated, per the user's "nothing on a timer"
        //   rule). Forcing scratch.t no longer advances it; the player must WALK OUT to trigger the
        //   handoff — so mirror pod-walkout: kick the door, enable walk, and hold W toward −Z until
        //   stepOut hands off. (The 6× cycle below re-spawns the body outside, so walking out here
        //   only serves to complete the handoff.)
        g.blowCabinHatch(1);
        const _fade = document.getElementById('intro-fade'); if (_fade) _fade.style.opacity = '0';
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.intro.scratch.phase = 'climb'; ctx.intro.scratch.t = 0; }
        const _pPreWalk = ctx.player.body.body.translation();
        for (let i = 0; i < 12 && !(ctx.intro && (ctx.intro.beat === 'stepOut' || !ctx.intro.active)); i++) {
          await walk(0, 1.0);   // yaw 0 = face −Z = walk OUT (movement advances the climb gate)
        }
        await driveTo(() => !ctx.intro || !ctx.intro.active, 12);   // let stepOut hand off + startPodTutorial
        const _pPostWalk = ctx.player.body.body.translation();
        _diag = {
          introExists: !!ctx.intro, introActive: !!(ctx.intro && ctx.intro.active),
          beat: ctx.intro ? ctx.intro.beat : '(none)', mode: ctx.intro ? ctx.intro.mode : '(none)',
          phase: ctx.intro && ctx.intro.scratch ? ctx.intro.scratch.phase : '(none)',
          movedInHandoff: +Math.hypot(_pPostWalk.x - _pPreWalk.x, _pPostWalk.z - _pPreWalk.z).toFixed(2),
          playerY: +_pPostWalk.y.toFixed(2),
        };
        const pod = ctx.three.scene.getObjectByName('escapePodCabin');
        if (pod) { pod.updateMatrixWorld(true); const V = cam.position.constructor; const p = pod.getWorldPosition(new V()); podX = p.x; podZ = p.z; }
        gy = ctx.terrain.heightAt(podX, podZ);
        // DIAGNOSTIC — dump the walkable colliders near the pod (position + half-extents) so a
        //   missing/mis-placed wall segment is visible in the log.
        _colliderDump = [];
        ctx.physics.world.forEachCollider((col) => {
          const t = col.translation();
          if (Math.hypot(t.x - podX, t.z - podZ) < 3.2 && Math.abs(t.y - gy) < 3.5) {
            let hx = 0, hy = 0, hz = 0;
            try { const h = col.halfExtents(); hx = +h.x.toFixed(2); hy = +h.y.toFixed(2); hz = +h.z.toFixed(2); } catch {}
            _colliderDump.push({ dz: +(t.z - podZ).toFixed(2), dx: +(t.x - podX).toFixed(2), y: +(t.y - gy).toFixed(2), hx, hy, hz });
          }
        });
        // the −Z door faces world −Z (pod yaw ≈ 0). Walking toward −Z (yaw 0) walks THROUGH the door.
        // Start the player just OUTSIDE the −Z door, ~3 m out.
        const startOutside = () => ctx.player.body.body.setTranslation({ x: podX, y: gy + 1.0, z: podZ - 3.2 }, true);
        for (let c = 0; c < 6; c++) {
          // IN — from outside (−Z), face −Z? No: to enter through the −Z door we walk toward +... the
          //   door is on −Z, so from further −Z we walk +Z (yaw π) INTO the pod. Start outside at −Z.
          startOutside();
          await sleep(60);
          const before = ctx.player.body.body.translation();
          await walk(Math.PI, 1.2);   // yaw π = face +Z = walk toward the pod centre (through the −Z door)
          const afterIn = ctx.player.body.body.translation();
          // reached the bore = crossed the −Z door INTO the hull AND was STOPPED (not passed through the
          //   far +Z wall out the other side). POD_R≈1.44; inside = within the hull, not beyond +Z wall.
          const insideNow = (afterIn.z > podZ - 1.6) && (afterIn.z < podZ + 1.6) && Math.hypot(afterIn.x - podX, afterIn.z - podZ) < 1.7;
          // OUT — from inside, walk −Z (yaw 0) back out the door.
          await walk(0, 1.4);
          const afterOut = ctx.player.body.body.translation();
          const outsideNow = (afterOut.z - podZ) < -1.4;   // cleared the door outward
          if (!outsideNow) everTrapped = true;   // couldn't get back out → trapped
          cycles.push({ c, walkedInReached: insideNow, inZ: +afterIn.z.toFixed(2), walkedOut: outsideNow, outZ: +afterOut.z.toFixed(2) });
        }
      } finally { realClock.getDelta = origGetDelta; ctx.three.renderer.setSize(origW, origH, false); ctx.input.keys['KeyW'] = false; }
      return { podAt: [+podX.toFixed(2), +podZ.toFixed(2)], gy: +gy.toFixed(2), minY: +minY.toFixed(2), maxJump: +maxJump.toFixed(2), everTrapped, cycles, colliderDump: _colliderDump, diag: _diag };
    });
    console.log('[doorway-torture] ' + JSON.stringify({ podAt: log.podAt, gy: log.gy, minY: log.minY, maxJump: log.maxJump, everTrapped: log.everTrapped }));
    console.log('[doorway-torture] handoff diag: ' + JSON.stringify(log.diag));
    console.log('[doorway-torture] colliders (dz,dx,y,halfExtents) near pod: ' + JSON.stringify(log.colliderDump));
    for (const c of log.cycles) console.log('  ' + JSON.stringify(c));
    // GATE 1 — never fell through the floor (minY stayed near/above the pod ground; a fall-through spikes minY far below gy).
    if (log.minY < log.gy - 2.0) throw new Error(`doorway-torture GATE FAILED: the body FELL THROUGH the floor (minY=${log.minY}, gy=${log.gy}).`);
    // GATE 2 — never trapped: every cycle walked back OUT the door.
    if (log.everTrapped) throw new Error(`doorway-torture GATE FAILED: the player got TRAPPED inside (a cycle could not walk back out): ${JSON.stringify(log.cycles)}`);
    // GATE 3 — the walk-in reached the bore + the walk-out cleared the door in a majority of cycles (the
    //   door is walkable both ways; a fully blocked doorway would fail every cycle).
    const inOk = log.cycles.filter((c) => c.walkedInReached).length;
    const outOk = log.cycles.filter((c) => c.walkedOut).length;
    if (inOk < 4) throw new Error(`doorway-torture GATE FAILED: the walk-IN reached the bore in only ${inOk}/6 cycles (the doorway is blocked): ${JSON.stringify(log.cycles)}`);
    if (outOk < 4) throw new Error(`doorway-torture GATE FAILED: the walk-OUT cleared the door in only ${outOk}/6 cycles: ${JSON.stringify(log.cycles)}`);
    // GATE 4 — no teleport (a KCC step never jumps more than a walking stride).
    if (log.maxJump > 2.0) throw new Error(`doorway-torture GATE FAILED: a discontinuous ${log.maxJump}m jump (teleport, not a KCC step).`);
    console.log(`[doorway-torture] GATE PASS — entered/exited the landed pod on real legs across 6 cycles (in ${inOk}/6, out ${outOk}/6, minY=${log.minY} ≥ gy−2, maxJump=${log.maxJump} — never blocked, never fell through, never trapped).`);
  },

  // ── Y3 DIAGNOSIS PROBE (findings-before-fixes; no screenshot — hard measurements only) ──
  //    Gathers the geometry/collider/timeline evidence for the four Y3 diagnosis questions:
  //    (1) the bay-pod doorway "black wall" lower half, (2) the collider state-flip trap,
  //    (3) the base/ground swap at landing, (4) old+new interior coexistence.
  //    Prints one JSON blob per finding. Never throws (diagnostic).
  // ROUND-1f — a LIGHT sealed-door render (first screenshot = reliable, unlike pod-diag's late shots).
  //   Builds the bay pod, keeps the pod door CLOSED, seats the eye INSIDE facing the door (the user's
  //   sealed-eye vantage), and shoots — the AIRTIGHT check (no star-gaps down the door sides).
  //   --angle: seated (inside, facing the +X door) [default] | edge-left | edge-right (graze each jamb)
  'pod-sealed': async (page) => {
    const angle = argv.angle || 'seated';
    await page.evaluate(() => {
      const g = window.__game;
      g.ctx.flags.thirdPerson = false;
      if (g.ctx.player.rig) g.ctx.player.rig.group.visible = false;
      g.startIntro();
      g.jumpToBeat('cockpit');   // builds the ship + docked canonical pod
    });
    await page.waitForTimeout(900);
    const meas = await page.evaluate(({ angle }) => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
      ctx.flags.paused = true;
      ctx.three.renderer.setSize(1100, 820, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 820; cam.updateProjectionMatrix(); }
      const pod = ctx.three.scene.getObjectByName('dockedCanonicalPod');
      pod.updateMatrixWorld(true);
      const p = pod.getWorldPosition(new THREE.Vector3());
      try { g.setBayPodDoorOpen(0); } catch {}   // sealed
      // seat the eye INSIDE the pod facing the +X door (the door faces +X in the bay).
      let eye, look;
      if (angle === 'edge-left') { eye = new THREE.Vector3(p.x + 0.9, p.y + 1.10, p.z - 0.60); look = new THREE.Vector3(p.x + 2.0, p.y + 1.05, p.z - 0.45); }
      else if (angle === 'edge-right') { eye = new THREE.Vector3(p.x + 0.9, p.y + 1.10, p.z + 0.60); look = new THREE.Vector3(p.x + 2.0, p.y + 1.05, p.z + 0.45); }
      else { eye = new THREE.Vector3(p.x + 0.35, p.y + 1.30, p.z); look = new THREE.Vector3(p.x + 2.0, p.y + 1.05, p.z); }
      cam.position.copy(eye); cam.lookAt(look); cam.updateMatrixWorld(true);
      ctx.three.renderer.render(ctx.three.scene, cam);
      return { angle, podWorld: [+p.x.toFixed(2), +p.y.toFixed(2), +p.z.toFixed(2)], eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)] };
    }, { angle });
    await page.waitForTimeout(200);
    await page.screenshot({ path: join(OUT, `scen-pod-sealed-${angle}.png`), fullPage: false });
    console.log(`[pod-sealed] ${JSON.stringify(meas)} → scen-pod-sealed-${angle}.png`);
  },

  'pod-diag': async (page) => {
    // ── FINDING 1 + 4: the BAY pod (docked) — doorway aperture geometry + interior duplicate audit.
    await page.evaluate(() => {
      const g = window.__game;
      g.ctx.flags.thirdPerson = false;
      g.startIntro();
      g.jumpToBeat('cockpit');   // builds the ship incl. the pod-bay + docked canonical pod
    });
    await page.waitForTimeout(900);
    const bay = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      const V = ctx.three.camera.position.constructor;
      const scene = ctx.three.scene;
      const pod = scene.getObjectByName('dockedCanonicalPod');
      if (!pod) return { error: 'dockedCanonicalPod not found' };
      pod.updateMatrixWorld(true);
      const podWorld = pod.getWorldPosition(new V());
      // FINDING 4 — how many interior sub-groups exist? (canonicalPodInterior). >1 = duplicate build.
      let interiors = 0, canopyGroups = 0, doorSlabs = 0, meshes = 0;
      const names = {};
      pod.traverse((o) => {
        if (o.name) names[o.name] = (names[o.name] || 0) + 1;
        if (o.name === 'canonicalPodInterior') interiors++;
        if (o.name === 'canonicalPodDoor') doorSlabs++;
        if (o.isMesh) meshes++;
      });
      // whole-scene: are there MULTIPLE pod cabins (escapePodCabin + dockedCanonicalPod both live)?
      let escapePodCabins = 0, dockedPods = 0;
      scene.traverse((o) => { if (o.name === 'escapePodCabin') escapePodCabins++; if (o.name === 'dockedCanonicalPod') dockedPods++; });
      // FINDING 1 — the doorway aperture. The bay door faces +X; the collar approach eye stands at
      //   the pod-door face plane. Sample the aperture bottom vs the collar floor world Y.
      // door aperture bottom (world Y) = pod floor (podWorld.y) + (CPOD_DOOR_CY − CPOD_DOOR_H/2).
      const FDOOR_CY = 1.10, FDOOR_H = 1.98;                    // from podScene (frozen contract)
      const apertureBottomLocal = FDOOR_CY - FDOOR_H / 2;       // 0.11 above pod floor
      const apertureBottomWorld = podWorld.y + apertureBottomLocal;
      // collar/corridor floor world Y = SHIP_ORIGIN.y (bay-local floor 0). The pod floor is at bay
      //   local 0 too (pod.position.set(podLocalX, 0, podZ)). So both floors are at podWorld.y here.
      // The collar deck top is ~0.02 above that. Report the delta the standing eye sees.
      const collarFloorWorld = podWorld.y;                     // bay-local 0 == pod-local floor 0
      // what fills the LOWER doorway (below apertureBottomWorld, at the door plane)? Sample: is there
      //   an opaque mesh spanning the aperture-bottom band on the +X face inside the collar?
      return {
        podWorldY: +podWorld.y.toFixed(3),
        interiorSubgroups: interiors,        // FINDING 4: should be exactly 1
        doorSlabGroups: doorSlabs,           // should be 1
        escapePodCabinsInScene: escapePodCabins,   // should be 0 during the bay (ride cabin not built yet)
        dockedPodsInScene: dockedPods,       // should be 1
        podMeshCount: meshes,
        apertureBottomLocal: +apertureBottomLocal.toFixed(3),   // FINDING 1: 0.11m above the floor
        apertureBottomWorld: +apertureBottomWorld.toFixed(3),
        collarFloorWorld: +collarFloorWorld.toFixed(3),
        doorSillGap: +(apertureBottomWorld - collarFloorWorld).toFixed(3),   // FINDING 1: the sill step you face
        uniqueNamedGroups: names,
      };
    });
    console.log('[pod-diag][FINDING-1+4 bay] ' + JSON.stringify(bay, null, 0));

    // ── FINDING 1 (rendered): OPEN the sliding door + the POD door, stand at the collar eye, look
    //    into the OPEN aperture. This reproduces the user's "black wall lower half on first E-open".
    const openMeas = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      const V = ctx.three.camera.position.constructor;
      ctx.flags.paused = true;
      ctx.three.renderer.setSize(1100, 820, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 820; cam.updateProjectionMatrix(); }
      const tr = ctx.player.body.body.translation();
      const floorY = tr.y - (ctx.player.body.halfHeight + ctx.player.body.radius);
      const bayZ = tr.z + 4.8, wallX = tr.x - 1.0, podDoorX = tr.x - 1.92;
      // open the sliding airlock door (both leaves into their pockets)
      const aHW = 0.72, travel = 0.82, bzL = 4.8;
      const lL = ctx.three.scene.getObjectByName('airlockDoorLeafL');
      const lR = ctx.three.scene.getObjectByName('airlockDoorLeafR');
      if (lL) lL.position.z = (bzL - aHW / 2) - travel;
      if (lR) lR.position.z = (bzL + aHW / 2) + travel;
      // OPEN the pod door fully via the REAL animator (the first-E-open state) — drives _bayDoorPivot.
      let doorOpened = false;
      try { g.setBayPodDoorOpen ? g.setBayPodDoorOpen(1) : null; doorOpened = true; } catch {}
      const podDoor = ctx.three.scene.getObjectByName('canonicalPodDoor');
      if (!doorOpened && podDoor) { podDoor.rotation.y = -1.9; doorOpened = true; }
      // Stand BACK in the collar (the user's vantage: at the airlock/collar, the just-opened door
      //   ahead), eye at standing height 1.62, look LEVEL straight in (−X) through the aperture — this
      //   reproduces the "curved grey sheet walling the lower half of the doorway" the user reports.
      const eye = new V(podDoorX + 0.85, floorY + 1.62, bayZ);
      cam.position.copy(eye);
      cam.lookAt(new V(podDoorX - 1.2, floorY + 1.20, bayZ));   // look nearly LEVEL into the aperture (slight down)
      cam.updateMatrixWorld(true);
      return { eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)], floorY: +floorY.toFixed(2), doorOpened };
    });
    await page.waitForTimeout(200);
    await page.screenshot({ path: join(OUT, 'scen-pod-diag-dooropen.png'), fullPage: false });
    console.log('[pod-diag][FINDING-1 rendered] ' + JSON.stringify(openMeas) + ' → scen-pod-diag-dooropen.png');

    // ── FINDING 1b (mesh identification): which named mesh actually OCCLUDES the lower doorway from
    //    the collar eye? A RAYCAST FAN — fire rays from the standing collar eye through a grid of
    //    aperture-plane targets covering the LOWER HALF of the doorway (sill 0.11 up to mid), and for
    //    each ray report the FIRST opaque hit's nearest-named ancestor + the hit world-Y + the mesh's
    //    pod-local extents. Rays that pass CLEAN through to the interior (hit far interior wall / seat)
    //    tell us the aperture is clear; rays stopped by a near curved plate name the blocker.
    const rayProbe = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      const THREE = g.THREE;
      const pod = ctx.three.scene.getObjectByName('dockedCanonicalPod');
      if (!pod || !THREE) return { error: 'pod or THREE missing' };
      pod.updateMatrixWorld(true);
      const podWorld = pod.getWorldPosition(new THREE.Vector3());
      const cam = ctx.three.camera;
      const eye = cam.position.clone();
      // The door faces −X from the eye (podDoorX < eye.x). Aperture plane at pod +X face (world x = podWorld.x + doorPlaneX).
      const CAB_R = 1.28, SHELL = 0.16, doorPlaneX = CAB_R + SHELL;   // 1.44
      const apX = podWorld.x + doorPlaneX;
      // Build a fan of targets on the aperture plane: z (width) across the door ±0.48, y (height) from
      //   the sill (podWorld.y+0.11) up to mid-door (podWorld.y+1.05) — the LOWER HALF the user reports.
      const rc = new THREE.Raycaster();
      const meshes = [];
      pod.traverse((o) => { if (o.isMesh && o.visible && o.material && !o.material.transparent) meshes.push(o); });
      const rows = [];
      for (let yi = 0; yi <= 6; yi++) {
        const ty = podWorld.y + 0.11 + (yi / 6) * 0.94;   // sill → mid
        const cols = [];
        for (let zi = -3; zi <= 3; zi++) {
          const tz = podWorld.z + (zi / 3) * 0.48;
          const target = new THREE.Vector3(apX, ty, tz);
          const dir = target.clone().sub(eye).normalize();
          rc.set(eye, dir);
          rc.far = 4.0;
          const hits = rc.intersectObjects(meshes, false).filter((h) => h.distance > 0.05);
          if (hits.length === 0) { cols.push('·'); continue; }
          const h = hits[0];
          let nm = h.object.name, node = h.object;
          while (!nm && node.parent && node !== pod) { node = node.parent; nm = node.name; }
          // hit BEFORE the aperture plane (nearer than apX) AND below mid = a blocker of the lower doorway
          const beforePlane = h.point.x > apX - 0.02;   // hit at/outside the door plane (a near occluder)
          const local = pod.worldToLocal(h.point.clone());
          cols.push({ y: +ty.toFixed(2), z: +tz.toFixed(2), named: nm || '?', hitWorldY: +h.point.y.toFixed(2), hitLocalX: +local.x.toFixed(2), hitLocalY: +local.y.toFixed(2), dist: +h.distance.toFixed(2), near: beforePlane });
        }
        rows.push({ ty: +ty.toFixed(2), cols });
      }
      // tally the blockers (named hits at the low band that are NEAR occluders)
      const tally = {};
      for (const r of rows) for (const c of r.cols) if (c && c.named) tally[c.named] = (tally[c.named] || 0) + 1;
      return { podWorldY: +podWorld.y.toFixed(3), apertureWorldX: +apX.toFixed(3), eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)], sillWorldY: +(podWorld.y + 0.11).toFixed(2), rows, blockerTally: tally };
    });
    console.log('[pod-diag][FINDING-1b raycast fan] ' + JSON.stringify(rayProbe, null, 0));

    // ── FINDING 1d (AIRTIGHT SEAL): CLOSE the pod door, seat the eye INSIDE the pod facing the door
    //    (+X, the user's sealed-eye vantage), and shoot. Star-gaps down the door sides = the slab
    //    clearance against the curved shell reads as space. The stop-lip fix must make it airtight.
    const sealMeas = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      const THREE = g.THREE;
      ctx.flags.paused = true;
      const pod = ctx.three.scene.getObjectByName('dockedCanonicalPod');
      pod.updateMatrixWorld(true);
      const podWorld = pod.getWorldPosition(new THREE.Vector3());
      try { g.setBayPodDoorOpen(0); } catch {}   // CLOSE the door (sealed)
      // raycast fan at the door SIDES (just inside each vertical edge) from the seated eye — count how
      //   many rays hit OPAQUE pod metal (sealed) vs pass to the sky (a star-gap crack).
      const eye = new THREE.Vector3(podWorld.x + 0.55, podWorld.y + 1.35, podWorld.z);   // seated-ish, inside, near the door
      const cam = ctx.three.camera;
      cam.position.copy(eye);
      cam.lookAt(new THREE.Vector3(podWorld.x + 2.0, podWorld.y + 1.15, podWorld.z));   // face +X at the door
      cam.updateMatrixWorld(true);
      const rc = new THREE.Raycaster();
      const meshes = []; pod.traverse((o) => { if (o.isMesh && o.visible && o.material && !o.material.transparent) meshes.push(o); });
      // aperture edges in world: door plane +X at podWorld.x + 1.44; edges z = podWorld.z ± 0.51; y sill..lintel
      const apX = podWorld.x + 1.44;
      let sealed = 0, leaks = 0; const leakPts = [];
      for (const edgeZ of [-0.50, -0.48, 0.48, 0.50]) {
        for (let yi = 0; yi <= 8; yi++) {
          const ty = podWorld.y + 0.13 + (yi / 8) * 1.90;
          const target = new THREE.Vector3(apX + 0.02, ty, podWorld.z + edgeZ);
          const dir = target.clone().sub(eye).normalize();
          rc.set(eye, dir); rc.far = 3.0;
          const hits = rc.intersectObjects(meshes, false).filter((h) => h.distance > 0.05);
          if (hits.length > 0 && hits[0].point.x <= apX + 0.12) sealed++;
          else { leaks++; leakPts.push({ z: +edgeZ.toFixed(2), y: +ty.toFixed(2) }); }
        }
      }
      ctx.three.renderer.setSize(1100, 820, false);
      if (cam.isPerspectiveCamera) { cam.aspect = 1100 / 820; cam.updateProjectionMatrix(); }
      ctx.three.renderer.render(ctx.three.scene, cam);   // force a frame (headless rAF is throttled)
      return { doorClosed: true, eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)], sealedRays: sealed, leakRays: leaks, leaks: leakPts.slice(0, 10) };
    });
    await page.waitForTimeout(150);
    try { await page.screenshot({ path: join(OUT, 'scen-pod-diag-sealed.png'), fullPage: false, timeout: 15000, animations: 'disabled' }); } catch (e) { console.log('[pod-diag] sealed screenshot flaked: ' + e.name); }
    console.log('[pod-diag][FINDING-1d AIRTIGHT] ' + JSON.stringify(sealMeas) + ' → scen-pod-diag-sealed.png');

    // ── FINDING 1c (the TWO top-left pipes): stand BACK in the collar (the user's actual vantage),
    //    shoot the whole open doorway, and project every TALL-THIN rod mesh to screen so we can name
    //    which pipe-like rods land in the UPPER-LEFT of the door sightline (the ones to relocate).
    const rods = await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      const THREE = g.THREE;
      const pod = ctx.three.scene.getObjectByName('dockedCanonicalPod');
      if (!pod || !THREE) return { error: 'pod or THREE missing' };
      pod.updateMatrixWorld(true);
      const podWorld = pod.getWorldPosition(new THREE.Vector3());
      const cam = ctx.three.camera;
      // stand BACK ~1.1m from the door in the collar, eye 1.62, look level −X through the aperture
      const eye = new THREE.Vector3(podWorld.x + (1.28 + 0.16) + 0.55, podWorld.y + 1.62, podWorld.z);
      cam.position.copy(eye);
      cam.lookAt(new THREE.Vector3(podWorld.x - 0.5, podWorld.y + 1.25, podWorld.z));
      cam.updateMatrixWorld(true); cam.updateProjectionMatrix();
      // find TALL-THIN rod meshes (a vertical rod: bbY span > 0.35, footprint < 0.16) in the interior.
      const found = [];
      pod.traverse((o) => {
        if (!o.isMesh || !o.geometry) return;
        o.geometry.computeBoundingBox(); const bb = o.geometry.boundingBox; if (!bb) return;
        const dx = bb.max.x - bb.min.x, dy = bb.max.y - bb.min.y, dz = bb.max.z - bb.min.z;
        const isRod = dy > 0.35 && Math.max(dx, dz) < 0.18;
        if (!isRod) return;
        const c = new THREE.Vector3((bb.min.x + bb.max.x) / 2, (bb.min.y + bb.max.y) / 2, (bb.min.z + bb.max.z) / 2).applyMatrix4(o.matrixWorld);
        const loc = pod.worldToLocal(c.clone());
        const azBay = Math.atan2(loc.x, loc.z);   // bay-frame azimuth (door faces +X ⇒ az≈π/2)
        const azCabin = azBay + Math.PI / 2;       // undo the −π/2 interior yaw → cabin-local az the builder used
        const sp = c.clone().project(cam);         // NDC: x −1(left)..+1(right), y −1(bottom)..+1(top)
        // is it visible through the door (in front + roughly within the aperture frame)?
        const onScreen = sp.z < 1 && Math.abs(sp.x) < 1.1 && Math.abs(sp.y) < 1.1;
        found.push({
          mat: o.material && o.material.color ? '#' + o.material.color.getHexString() : '?',
          worldC: [+c.x.toFixed(2), +c.y.toFixed(2), +c.z.toFixed(2)],
          bayAz: +azBay.toFixed(2), cabinAz: +azCabin.toFixed(2),
          ndc: [+sp.x.toFixed(2), +sp.y.toFixed(2)],
          quadrant: (sp.y > 0 ? 'TOP-' : 'BOT-') + (sp.x < 0 ? 'LEFT' : 'RIGHT'),
          onScreen, dyH: +(bb.max.y - bb.min.y).toFixed(2),
        });
      });
      // upper-left rods through the door = the user's "two pipes"
      found.sort((a, b) => a.ndc[0] - b.ndc[0]);
      return { eye: [+eye.x.toFixed(2), +eye.y.toFixed(2), +eye.z.toFixed(2)], rodCount: found.length, upperLeft: found.filter((r) => r.onScreen && r.ndc[1] > -0.1 && r.ndc[0] < 0.2), all: found };
    });
    await page.waitForTimeout(150);
    try { await page.screenshot({ path: join(OUT, 'scen-pod-diag-collar.png'), fullPage: false, timeout: 15000 }); } catch (e) { console.log('[pod-diag] collar screenshot flaked: ' + e.name); }
    console.log('[pod-diag][FINDING-1c rods] ' + JSON.stringify(rods, null, 0) + ' → scen-pod-diag-collar.png');

    // ── FINDING 2 + 3: the CRASH → WAKE → STEP-OUT collider + base timeline.
    const timeline = await page.evaluate(async () => {
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const g = window.__game; const ctx = g.ctx;
      const V = ctx.three.camera.position.constructor;
      const podColCount = (px, pz, gy) => {
        let n = 0; ctx.physics.world.forEachCollider((c) => {
          const t = c.translation();
          if (Math.hypot(t.x - px, t.z - pz) < 3.2 && Math.abs(t.y - gy) < 3.5) n++;
        }); return n;
      };
      const snap = (label) => {
        const pod = ctx.three.scene.getObjectByName('escapePodCabin');
        let px = 0, pz = 0, py = 0, hasSkin = false, hasSalvagePanel = false;
        if (pod) {
          pod.updateMatrixWorld(true);
          const p = pod.getWorldPosition(new V()); px = p.x; pz = p.z; py = p.y;
          pod.traverse((o) => {
            if (o.name === 'podExteriorSkin') hasSkin = true;
            if (o.name && /accessPanel|salvage/i.test(o.name)) hasSalvagePanel = true;
          });
        }
        const gy = ctx.terrain ? ctx.terrain.heightAt(px, pz) : 0;
        return {
          label, beat: ctx.intro ? ctx.intro.beat : null, mode: ctx.intro ? ctx.intro.mode : null,
          podCols: pod ? podColCount(px, pz, gy) : 0,
          hasExteriorSkin: hasSkin,      // FINDING 3: the exterior skin/base appears at unify (step-out)
          hasSalvagePanel,
          podFloorY: +py.toFixed(2), groundY: +gy.toFixed(2),
        };
      };
      const out = [];
      // pin a fixed sim-dt + tiny canvas so the beat chain advances deterministically under the
      //   starved headless tab (mirrors the pod-walkout driver — the reliable pattern).
      const realClock = ctx.three.clock;
      const origGetDelta = realClock.getDelta.bind(realClock);
      const origW = ctx.three.renderer.domElement.width, origH = ctx.three.renderer.domElement.height;
      const drive = async (cond, simBudget) => {
        const simStart = ctx.time.elapsed; let lastSim = simStart, stalls = 0;
        for (let i = 0; i < 8000; i++) {
          await sleep(16);
          const nowSim = ctx.time.elapsed;
          if (nowSim > lastSim + 1e-6) { lastSim = nowSim; stalls = 0; } else if (++stalls > 400) break;
          if (cond()) return true;
          if (nowSim - simStart >= simBudget) break;
        }
        return cond();
      };
      try {
        realClock.getDelta = () => 0.05;
        ctx.three.renderer.setSize(48, 48, false);
        g.startIntro();
        // drive the REAL chain from descent so the pod grounds naturally (impact needs _descentBase).
        g.jumpToBeat('descent');
        await drive(() => ctx.intro && ctx.intro.beat === 'impact' && ctx.intro.scratch.init === true, 25);
        out.push(snap('at-impact (crash moment, cage dropped by setCabinCrashPose)'));
        await drive(() => ctx.intro && ctx.intro.beat === 'wake' && ctx.intro.scratch.init === true, 8);
        out.push(snap('wake comeTo (player still inside, NO colliders)'));
        // force the wake to the climb/walk state (the trap window if the player lingers).
        g.blowCabinHatch(1);
        if (ctx.intro) { ctx.intro.mode = 'walk'; ctx.intro.scratch.phase = 'climb'; ctx.intro.scratch.t = 0; }
        await drive(() => false, 0.5);
        out.push(snap('wake CLIMB (mode=walk, NO colliders — the TRAP window)'));
        // trip WAKE_CLIMB_FALLBACK (8s) → advance to stepOut → unifyEnterablePod (walls appear).
        if (ctx.intro) { ctx.intro.scratch.t = 999; }
        await drive(() => ctx.intro && (ctx.intro.beat === 'stepOut' || !ctx.intro.active), 15);
        await drive(() => false, 0.8);
        out.push(snap('after stepOut/unify (exterior skin + walls appear — the state FLIP)'));
      } finally { realClock.getDelta = origGetDelta; ctx.three.renderer.setSize(origW, origH, false); }
      return out;
    });
    console.log('[pod-diag][FINDING-2+3 timeline]');
    for (const s of timeline) console.log('  ' + JSON.stringify(s));
    console.log('[pod-diag] DONE (diagnostic — no gate).');
  },

  // SAVE/LOAD pod-persistence GATE — headless save→teardown→restore round-trip on the ONE walk-in
  // pod. Proves (a) the bug (the pod is GONE after a fresh-boot teardown) and (b) the fix (the restore
  // re-builds it with matching salvage/chute state). THROWS on failure so `--scenario=smoke-pod-
  // persistence` exits non-zero (usable as a gate). No screenshot.
  'smoke-pod-persistence': async (page) => {
    const r = await page.evaluate(() => window.__game.smokePodPersistence());
    console.log(`[smoke-pod-persistence] ${JSON.stringify(r)}`);
    if (!r || !r.ok) throw new Error(`smoke-pod-persistence GATE FAILED: ${JSON.stringify(r)}`);
  },

  // END-TO-END pod persistence via a REAL page reload + Continue. Drives the intro to step-out (the
  // ONE walk-in pod unifies + persists), SAVES, RELOADS the page (a genuine fresh boot — the pod is
  // NOT re-built at boot), then clicks CONTINUE and asserts the pod is back. This is the strongest
  // proof: it exercises the actual boot → onContinue → loadGameState → handoff → restore chain, not
  // an in-page simulation. THROWS on failure.
  'pod-persistence-reload': async (page) => {
    // 1. Force-start the intro + drive the whole chain to step-out (unify the pod), then hand off.
    const before = await page.evaluate(() => {
      const g = window.__game;
      const r = g.smokeIntro();   // runs the chain incl. tickStepOut → unifyEnterablePod; ends the intro
      const pod = g.ctx.three.scene.getObjectByName('escapePodCabin');
      let px = 0, pz = 0;
      if (pod) { pod.updateMatrixWorld(true); const V = g.ctx.three.camera.position.constructor; const p = new V(); p.setFromMatrixPosition(pod.matrixWorld); px = +p.x.toFixed(2); pz = +p.z.toFixed(2); }
      // save to the single slot (the exact menu Save path, minus UI)
      const sv = g.saveGame();
      const raw = localStorage.getItem('dustfall.save.v1');
      const parsed = raw ? JSON.parse(raw) : {};
      return { beats: r.beats, podPresent: !!pod, podAt: [px, pz], saveOk: sv.ok, hasPodCrash: !!parsed.podCrash };
    });
    console.log(`[pod-persistence-reload] before-reload: ${JSON.stringify(before)}`);
    if (!before.podPresent || !before.saveOk || !before.hasPodCrash) {
      throw new Error(`pod-persistence-reload SETUP FAILED (pod not built / not saved): ${JSON.stringify(before)}`);
    }
    // 2. REAL fresh boot — reload the page. (addInitScript re-pins the SAME seed each load, so the save
    //    passes the seed check; it also re-sets seenIntro so no controls panel opens.)
    await page.reload();
    await page.waitForFunction(() => !!(window.__game && window.__game.ctx?.player?.rig), undefined, { timeout: 30000 });
    // 3. Click the real CONTINUE button on the title overlay (drives main.ts onContinue →
    //    loadGameState → handoffToGame → applyPendingPodCrashRestore).
    const clicked = await page.evaluate(() => {
      const btns = Array.from(document.querySelectorAll('button'));
      const cont = btns.find((b) => (b.textContent || '').trim().toUpperCase() === 'CONTINUE');
      if (!cont) return false;
      cont.click();
      return true;
    });
    if (!clicked) throw new Error('pod-persistence-reload: no CONTINUE button on the reloaded title (save missing?)');
    await page.waitForTimeout(1200);   // let onContinue + the restore run
    // 4. Assert the pod is BACK after the real reload + Continue.
    const after = await page.evaluate(() => {
      const g = window.__game;
      const pod = g.ctx.three.scene.getObjectByName('escapePodCabin');
      let px = 0, pz = 0;
      if (pod) { pod.updateMatrixWorld(true); const V = g.ctx.three.camera.position.constructor; const p = new V(); p.setFromMatrixPosition(pod.matrixWorld); px = +p.x.toFixed(2); pz = +p.z.toFixed(2); }
      const podSalvageable = (g.ctx.salvageables && g.ctx.salvageables.list || []).some((s) => s.kind === 'escape_pod');
      // walkable colliders near the pod (floor + gapped wall ring) — the walk-in read survived
      let podCols = 0;
      if (pod) { const gy = g.ctx.terrain.heightAt(px, pz); g.ctx.physics.world.forEachCollider((c) => { const t = c.translation(); if (Math.hypot(t.x - px, t.z - pz) < 3.0 && Math.abs(t.y - gy) < 3.0) podCols++; }); }
      return { podPresent: !!pod, podAt: [px, pz], podSalvageable, podCols, titleActive: !!g.ctx.flags.titleActive };
    });
    console.log(`[pod-persistence-reload] after-continue: ${JSON.stringify(after)}`);
    if (!after.podPresent || !after.podSalvageable || after.podCols < 3) {
      throw new Error(`pod-persistence-reload GATE FAILED — pod did NOT survive reload+Continue: ${JSON.stringify(after)}`);
    }
    console.log('[pod-persistence-reload] PASS — the walk-in pod survived save → reload → Continue.');
  },

  'tree': async (page) => {
    const t = argv.time !== undefined ? Number(argv.time) : 0.42;
    const r = await page.evaluate((t) => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.3;
      window.__game.setTime(t);
      ctx.three.renderer.setSize(900, 950, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 950; cam.updateProjectionMatrix(); }
      const V = cam.position.constructor;
      let tree = null;
      ctx.three.scene.traverse((o) => { if (!tree && o.name === 'deadTree') tree = o; });
      if (!tree) return { found: false };
      const wp = tree.getWorldPosition(new V());
      ctx.flags.paused = true;
      // Full-tree 3/4 framing: stand back ~3.5m, eye ~1.9m, look at mid-trunk.
      cam.position.set(wp.x + 2.3, wp.y + 1.5, wp.z + 2.7);
      cam.lookAt(wp.x, wp.y + 1.5, wp.z);
      cam.updateMatrixWorld(true);
      // ACAI (T6) — assert a trunk collider sits near this tree (within 0.6m
      // horizontally, raised above the base = the static cylinder, not the
      // terrain heightfield which sits at/near the ground plane).
      let trunkCol = 0;
      ctx.physics.world.forEachCollider((c) => {
        const tr = c.translation();
        const dx = tr.x - wp.x, dz = tr.z - wp.z;
        if (dx * dx + dz * dz < 0.36 && tr.y > wp.y + 0.2) trunkCol++;
      });
      return { found: true, pos: [wp.x.toFixed(1), wp.y.toFixed(1), wp.z.toFixed(1)], trunkCol };
    }, t);
    await page.waitForTimeout(350);
    await page.screenshot({ path: join(OUT, 'scen-tree.png'), fullPage: false });
    console.log(`[tree] ${JSON.stringify(r)}`);
  },

  // Perf-probe (ACAH diag): report renderer.info (draw calls, triangles, compiled
  // programs) + scene object counts + per-itemId pickup mesh totals. No screenshot.
  'perf-probe': async (page) => {
    await page.waitForTimeout(2000);
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const ren = ctx.three.renderer;
      // Boot phase deltas (ms) from the __bootT marks.
      const bt = window.__bootT || [];
      const bootPhases = {};
      for (let i = 1; i < bt.length; i++) bootPhases[bt[i][0]] = Math.round(bt[i][1] - bt[i - 1][1]);
      const bootTotal = bt.length ? Math.round(bt[bt.length - 1][1] - bt[0][1]) : -1;
      ren.render(ctx.three.scene, ctx.three.camera);   // populate info for this frame
      const info = ren.info;
      let objs = 0, meshes = 0;
      ctx.three.scene.traverse((o) => { objs++; if (o.isMesh) meshes++; });
      const pk = ctx.pickups?.list || [];
      const meshCount = (g) => { let m = 0; g.traverse((o) => { if (o.isMesh) m++; }); return m; };
      const byId = {};
      for (const p of pk) {
        const id = p.itemId;
        byId[id] = byId[id] || { n: 0, meshes: 0 };
        byId[id].n++; byId[id].meshes += meshCount(p.mesh);
      }
      // Biggest individual scene children by mesh count (perf-hog finder).
      const ranked = ctx.three.scene.children
        .map((c) => ({ c, k: c.name || c.userData?.poiKind || c.userData?.kind || c.type || 'unnamed', m: meshCount(c) }))
        .filter((x) => x.m > 3)
        .sort((a, b) => b.m - a.m);
      const topGroups = ranked.slice(0, 18).map((x) => `${x.k}:${x.m}m`);
      // Deep dump of the top 6 — what ARE these big groups? (identify before optimizing, D193)
      const idOf = (o) => o.name || o.userData?.poiKind || o.userData?.kind || o.type;
      const topGroupsDeep = ranked.slice(0, 6).map((x) => {
        const kids = x.c.children || [];
        const hist = {};
        for (const kid of kids) { const id = idOf(kid); hist[id] = (hist[id] || 0) + 1; }
        return {
          k: x.k, m: x.m, kids: kids.length,
          ud: Object.keys(x.c.userData || {}).join(',') || '-',
          childKinds: Object.entries(hist).map(([id, n]) => `${n}x${id}`).slice(0, 8),
        };
      });
      return {
        topGroups,
        topGroupsDeep,
        drawCalls: info.render.calls,
        triangles: info.render.triangles,
        programs: info.programs ? info.programs.length : -1,
        sceneObjects: objs,
        sceneMeshes: meshes,
        pickupTotal: pk.length,
        pickupsByIdMeshes: Object.fromEntries(Object.entries(byId).map(([k, v]) => [k, `${v.n}pk/${v.meshes}mesh`])),
        salvageables: ctx.salvageables?.list?.length ?? -1,
        bootTotalMs: bootTotal,
        bootPhasesMs: bootPhases,
      };
    });
    console.log('[perf-probe] ' + JSON.stringify(r));
  },

  // M1 pickup-instancing GATE (campaign 2026-07-09) — proves the instanced pickups
  // still COLLECT through the real interaction path end-to-end: teleport the player
  // to a pickup, aim the camera at it, let updateInteraction raycast it (the
  // intersection.instanceId → instanceToPickupId resolver), dispatch a REAL KeyE,
  // and assert the pickup left the list + the pool slot freed. Exercises the
  // swap-with-last index-fixup explicitly (take a MIDDLE instance, then take the
  // pickup whose instance was MOVED into the freed slot). THROWS on failure.
  'pickup-take-sweep': async (page) => {
    await page.waitForTimeout(2000);
    const r = await page.evaluate(async () => {
      const g = window.__game;
      const ctx = g.ctx;
      const raf = () => new Promise((res) => requestAnimationFrame(() => res()));
      const frames = async (n) => { for (let i = 0; i < n; i++) await raf(); };
      g.enterGame(true);                 // dev handoff (skips the intro) so updateInteraction ticks
      ctx.input.controls.isLocked = true; // isPlaying() gate — no real pointer lock headless (enterLive idiom)
      ctx.flags.paused = false;
      // The live-scenario boot (enterLive) defaults to THIRD PERSON, parking the camera
      // on a spring-arm ~1.8m behind the body (diagnosed: cam static 1.87m off the eye).
      // This sweep aims with cam.lookAt + expects the FP eye-origin ray → force FP.
      ctx.flags.thirdPerson = false;
      // Remove the companion: she's an interact TARGET that follows the player, and she
      // intercepts the ray while the sweep loiters at a pickup cluster (diagnosed: the
      // direct imesh raycast hits; the game ray loses to a nearer target — Pebble).
      if (ctx.companion) {
        ctx.three.scene.remove(ctx.companion.group);
        ctx.companion = null;
      }
      window.__interactionDebug = true;   // tap the game's raw raycast hits (fail diagnostics)
      // NOTE: read ctx.player.body LIVE (via pb()) — enterGame(dev) rebuilds the
      // player body, so a reference captured before it is a STALE body (diagnosed:
      // teleports moved the stale body while the camera followed the real one).
      const pb = () => ctx.player.body;
      const cam = ctx.three.camera;
      const out = { takes: [], fails: [], invariant: 'unchecked' };
      // Wait until the camera sits at the body eye before sweeping/aiming.
      let _settleDbg = '';
      const camSettled = async (maxFrames) => {
        let d = -1;
        const c0 = cam.position.clone();
        for (let i = 0; i < maxFrames; i++) {
          const t = pb().body.translation();
          d = Math.hypot(cam.position.x - t.x, cam.position.y - (t.y + 1.2), cam.position.z - t.z);
          if (d < 1.6) return true;
          await raf();
        }
        const t = pb().body.translation();
        _settleDbg = `d=${d.toFixed(2)} cam=(${cam.position.x.toFixed(1)},${cam.position.y.toFixed(1)},${cam.position.z.toFixed(1)})`
          + ` camMoved=${cam.position.distanceTo(c0).toFixed(2)} body=(${t.x.toFixed(1)},${t.y.toFixed(1)},${t.z.toFixed(1)})`
          + ` title=${ctx.flags.titleActive} intro=${ctx.intro ? ctx.intro.mode : 'none'} locked=${ctx.input.controls.isLocked}`;
        return false;
      };
      if (!(await camSettled(600))) {
        out.fails.push(`camera never settled onto the player after enterGame: ${_settleDbg}`);
        return out;
      }

      const takeOne = async (p) => {
        const label = `${p.itemId}#${p.id}` + (p.inst ? `@i${p.inst.index}` : '(mesh)');
        // Stand CLOSE (eye-to-pickup must be < the 2.5m ray reach; the standing eye
        // sits ~1.9m above a ground pickup, so keep the horizontal standoff tight).
        // Order matters (diagnosed): teleport body → let the controller re-seat the
        // camera onto the body eye (position is controller-owned) → THEN aim (the
        // look direction persists; aiming before the re-seat left a ~6° error).
        const dx = 0.55, dz = 0.35;
        const b = pb();
        b.body.setTranslation({ x: p.pos.x + dx, y: p.pos.y + b.halfHeight + b.radius + 0.05, z: p.pos.z + dz }, true);
        if (!(await camSettled(120))) {     // camera follow may EASE across the teleport
          out.fails.push(`${label}: camera never settled at the teleport`);
          return false;
        }
        // Aim at the instance's ACTUAL world bbox centre (a branch is a thin stick
        // extending away from its origin — an exact-origin ray passes through air;
        // diagnosed: perfect aim at p.pos, no hit). Then wiggle a small pattern.
        const T = window.__game.THREE;
        let aimC = new T.Vector3(p.pos.x, p.pos.y, p.pos.z);
        if (p.inst) {
          const geo = p.inst.pool.imesh.geometry;
          if (!geo.boundingBox) geo.computeBoundingBox();
          const m = new T.Matrix4();
          p.inst.pool.imesh.getMatrixAt(p.inst.index, m);
          aimC = geo.boundingBox.getCenter(new T.Vector3()).applyMatrix4(m);
        }
        // Union of aim candidates: the bbox centre can sit in a twig-fork GAP for some
        // variants while the origin misses for others — sweep around BOTH anchors.
        const pat = [[0, 0, 0], [0.08, 0.02, 0], [-0.08, 0.02, 0], [0, 0.02, 0.08], [0, 0.02, -0.08],
                     [0.16, 0.03, 0], [-0.16, 0.03, 0], [0, 0.03, 0.16], [0, 0.03, -0.16]];
        const anchors = [aimC, new T.Vector3(p.pos.x, p.pos.y + 0.02, p.pos.z)];
        let hover = null;
        const aimTaps = [];
        outer: for (const a of anchors) {
          for (const [ax, ay, az] of pat) {
            // Re-pin the aim EVERY frame: the teleported body keeps settling under
            // gravity for a few frames, dropping the eye ~cm after a one-shot lookAt
            // (diagnosed: the tick's ray ran ~2° off ≈ 6cm at range — fatal for a
            // 2cm-thick stick, tolerable for a 15cm scrap chunk).
            for (let k = 0; k < 3; k++) {
              cam.lookAt(a.x + ax, a.y + ay, a.z + az);
              await raf();
            }
            hover = ctx.inventory.hover;
            aimTaps.push(window.__lastHits ?? null);
            if (hover && hover.type === 'take') break outer;
          }
        }
        if (!hover || hover.type !== 'take') {
          const d = cam.getWorldDirection(new T.Vector3());
          const to = new T.Vector3(p.pos.x - cam.position.x, p.pos.y - cam.position.y, p.pos.z - cam.position.z);
          const dist = to.length(); to.normalize();
          const t = pb().body.translation();
          let deep = '';
          if (p.inst) {
            // Direct raycast at the pool imesh (no game code) — does three even see it?
            const rc = new T.Raycaster(cam.position.clone(), new T.Vector3().subVectors(aimC, cam.position).normalize());
            rc.camera = cam;   // Sprite.raycast requires it (scene-wide pass hits sprites)
            const ih = rc.intersectObject(p.inst.pool.imesh, false);
            const m = new T.Matrix4(); p.inst.pool.imesh.getMatrixAt(p.inst.index, m);
            const mp = new T.Vector3().setFromMatrixPosition(m);
            const sh = rc.intersectObjects(ctx.three.scene.children, true).slice(0, 4)
              .map((h) => `${h.object.name || h.object.type}@${h.distance.toFixed(2)}${h.instanceId !== undefined ? `#i${h.instanceId}` : ''}${h.object.userData.pickupId !== undefined ? `(pk${h.object.userData.pickupId})` : ''}`);
            deep = ` [direct: ${ih.length} hits${ih.length ? ` d=${ih[0].distance.toFixed(2)} inst=${ih[0].instanceId}` : ''};`
              + ` matPos=(${mp.x.toFixed(2)},${mp.y.toFixed(2)},${mp.z.toFixed(2)}) poolCount=${p.inst.pool.count} idx=${p.inst.index}`
              + ` inScene=${!!p.inst.pool.imesh.parent}; sceneRay=${sh.join(' | ')};`
              + ` aim0Tap=${JSON.stringify(aimTaps[0] ?? null)}]`;
          }
          out.fails.push(`${label}: no take-hover (got ${hover ? hover.type : 'none'}) `
            + `dist=${dist.toFixed(2)} aimDot=${d.dot(to).toFixed(3)} cam=(${cam.position.x.toFixed(1)},${cam.position.y.toFixed(1)},${cam.position.z.toFixed(1)}) `
            + `body=(${t.x.toFixed(1)},${t.y.toFixed(1)},${t.z.toFixed(1)}) pickup=(${p.pos.x.toFixed(1)},${p.pos.y.toFixed(1)},${p.pos.z.toFixed(1)})${deep}`);
          return false;
        }
        const before = ctx.pickups.list.length;
        window.dispatchEvent(new KeyboardEvent('keydown', { code: 'KeyE' }));
        await frames(2);
        window.dispatchEvent(new KeyboardEvent('keyup', { code: 'KeyE' }));
        await frames(2);
        const gone = !ctx.pickups.list.includes(p);
        if (!gone || ctx.pickups.list.length !== before - 1) {
          out.fails.push(`${label}: E-take did not despawn (len ${before}→${ctx.pickups.list.length})`);
          return false;
        }
        out.takes.push(label);
        return true;
      };

      const scraps = ctx.pickups.list.filter((p) => p.itemId === 'scrap' && p.inst);
      const branches = ctx.pickups.list.filter((p) => p.itemId === 'branch' && p.inst);
      if (scraps.length < 5 || branches.length < 3) {
        out.fails.push(`too few instanced pickups (scrap ${scraps.length}, branch ${branches.length}) — instancing not active?`);
        return out;
      }

      // 1. Take a MIDDLE scrap instance → forces swap-with-last.
      const pool = scraps[0].inst.pool;
      const midIndex = Math.floor(pool.count / 2);
      const midPickupId = pool.ids[midIndex];
      const midPickup = ctx.pickups.list.find((p) => p.id === midPickupId);
      const lastPickupId = pool.ids[pool.count - 1];   // this instance will MOVE into midIndex
      if (midPickup) await takeOne(midPickup);
      // 2. Take the MOVED pickup (its inst.index must have been fixed up to midIndex).
      const moved = ctx.pickups.list.find((p) => p.id === lastPickupId);
      if (moved) {
        if (!moved.inst || moved.inst.index !== midIndex) {
          out.fails.push(`swap-fixup: moved pickup #${lastPickupId} index ${moved.inst ? moved.inst.index : 'none'} != freed ${midIndex}`);
        }
        await takeOne(moved);
      }
      // 3. Take instance 0 (head) + a branch sample (one per available variant pool).
      const head = ctx.pickups.list.find((p) => p.inst && p.inst.pool === pool && p.inst.index === 0);
      if (head) await takeOne(head);
      const seenPools = new Set();
      for (const b of branches) {
        if (!ctx.pickups.list.includes(b) || !b.inst) continue;
        if (seenPools.has(b.inst.pool)) continue;
        seenPools.add(b.inst.pool);
        await takeOne(b);
        if (seenPools.size >= 3) break;
      }

      // 4. Global invariant: every remaining instanced pickup's slot maps back to it.
      let bad = 0;
      for (const p of ctx.pickups.list) {
        if (!p.inst) continue;
        if (p.inst.index >= p.inst.pool.count || p.inst.pool.ids[p.inst.index] !== p.id) bad++;
      }
      out.invariant = bad === 0 ? 'ok' : `${bad} stale instance mappings`;
      return out;
    });
    console.log('[pickup-take-sweep] ' + JSON.stringify(r));
    const pass = r.fails.length === 0 && r.invariant === 'ok' && r.takes.length >= 6;
    if (!pass) throw new Error(`pickup-take-sweep GATE FAILED: ${JSON.stringify(r)}`);
  },

  // Branch-match (ACAF f/u): FP held branch + a world branch in ONE frame under
  // the SAME lighting, to verify they read identical (vm scene now mirrors the
  // world sun/moon/ambient). Runs LIVE (not paused) so updateViewModel tracks
  // the camera each frame. --time=<0..1> to compare day/dusk.
  'branch-match': async (page) => {
    const t = argv.time !== undefined ? Number(argv.time) : 0.5;
    await captureStrip(page, 'branch-match', `(i)=>{
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0;
      window.__game.setTime(${t});
      ctx.flags.thirdPerson = false;
      ctx.three.renderer.setSize(900, 700, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900/700; cam.updateProjectionMatrix(); }
      const inv = ctx.inventory;
      inv.slots[0].item='branch'; inv.slots[0].count=1; inv.slots[0].meta=undefined; inv.selectedIdx=0;
      const bs = (ctx.pickups.list||[]).filter(p=>p.itemId==='branch');
      const b = bs[0]; if(!b){console.log('[branch-match] no world branch');return;}
      const p = b.pos; const gy = ctx.terrain.heightAt(p.x, p.z);
      const bx = p.x + 0.9, bz = p.z + 0.9;
      ctx.player.body.body.setTranslation({x:bx, y:gy+1.0, z:bz}, true);
      cam.position.set(bx, gy+1.55, bz);
      cam.lookAt(p.x, p.y+0.05, p.z);
      cam.updateMatrixWorld(true);
      if(i===0) console.log('[branch-match] world branch at '+p.x.toFixed(1)+','+p.z.toFixed(1));
    }`);
  },

  // Cloud-shadows (ACAH): force overcast + frame the lit ground from above so the
  // moving cloud-shadow dapple on the terrain is visible. --cl=<0..1> coverage.
  'cloud-shadows': async (page) => {
    const cl = argv.cl !== undefined ? Number(argv.cl) : 0.9;
    const r = await page.evaluate((cl) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.5);                 // bright midday so the dapple contrasts
      ctx.weather.cloudiness = cl;
      ctx.weather.cloudinessHold = cl;            // pin it against the wander
      ctx.three.renderer.setSize(900, 700, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 700; cam.updateProjectionMatrix(); }
      const tr = ctx.player.body.body.translation();
      ctx.flags.paused = true;
      // Look down-ahead across the flats from ~14m up.
      cam.position.set(tr.x, tr.y + 9, tr.z + 2);
      cam.lookAt(tr.x + 14, tr.y, tr.z + 30);
      cam.updateMatrixWorld(true);
      return { cloudiness: ctx.weather.cloudiness };
    }, cl);
    await page.waitForTimeout(600);
    await page.screenshot({ path: join(OUT, 'scen-cloud-shadows.png'), fullPage: false });
    console.log(`[cloud-shadows] ${JSON.stringify(r)}`);
  },

  // Storm (C20): force a PEAK sandstorm centered on the player + render the dust-
  // storm LOOK (the signature atmosphere moment — 3 dust layers + fog + sun/ambient
  // dimming + the storm vignette). No storm-render scenario existed; this is the
  // reusable enabler for atmosphere iteration. Eye-level horizontal view into the wall.
  // Sandstorm overhaul (review 2026-07-14). Three shots that judge the storm from the
  // real player view against a spawned wreck (the occlusion test object):
  //   approach — the dust WALL on the horizon with the wreck clearly visible (light haze)
  //   mid      — the wall advancing, thick driven dust, wreck fogging out
  //   peak     — the whiteout: player inside the wall core; NO distant outline may survive
  // `--shot=approach|mid|peak|all` (default all). The wall travels +Z; the player stands
  // north of the wreck looking -Z toward the incoming front. Intensity is WALL-DERIVED
  // (updateWeather recomputes it each tick from the wall geometry), so we place the wall,
  // let the sim tick, then pause + frame.
  'storm': async (page) => {
    const shot = String(argv.shot || 'all');
    const shots = shot === 'all' ? ['approach', 'mid', 'peak'] : [shot];
    // Spawn ONE procgen wreck as the occlusion target; find its world center.
    const wreck = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.34);                 // bright midday for a legible daytime brownout
      // review 2026-07-16 — was 1.35: the harness graded the storm at an exposure the game
      // never ships (scene.ts sets 1.05). That matters more than it looks here — the sky dome
      // is toneMapped:false while fogged geometry is tone-mapped, so exposure moves ONLY the
      // fogged half of the image and the sky/ground match was being judged against a
      // brightness the player never sees. Grade what ships.
      ctx.three.renderer.toneMappingExposure = 1.05;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.player.inShelter = false;
      window.__game.spawnProcgenWreckRig('freighter', 4242);
      let mw = null;
      ctx.three.scene.traverse((o) => { if (!mw && o.name === 'procgenWreckRig') mw = o; });
      if (!mw) return null;
      mw.updateMatrixWorld(true);
      const box = new (ctx.three.camera.position.constructor)(); void box;
      let minX = 1e9, minZ = 1e9, maxX = -1e9, maxZ = -1e9, maxY = -1e9;
      mw.traverse((o) => {
        if (!o.isMesh || !o.geometry) return;
        o.geometry.computeBoundingBox(); const bb = o.geometry.boundingBox;
        const V = ctx.three.camera.position.constructor;
        for (const cx of [bb.min.x, bb.max.x]) for (const cy of [bb.min.y, bb.max.y]) for (const cz of [bb.min.z, bb.max.z]) {
          const p = new V(cx, cy, cz); o.localToWorld(p);
          minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
          minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
          maxY = Math.max(maxY, p.y);
        }
      });
      ctx.flags.paused = false;
      return { cx: (minX + maxX) / 2, cz: (minZ + maxZ) / 2, topY: maxY };
    });
    if (!wreck) { console.log('[storm] FAILED to spawn wreck'); return; }
    console.log(`[storm] wreck @ (${wreck.cx.toFixed(0)}, ${wreck.cz.toFixed(0)})`);

    const CFG = {
      // leadingEdgeDist = how far ahead of the player the wall's front sits (m).
      approach: { edge: 340, wreckDist: 46 },
      mid:      { edge: 165, wreckDist: 46 },
      peak:     { edge: 0,   wreckDist: 46 },
    };

    for (const sh of shots) {
      const cfg = CFG[sh];
      if (!cfg) { console.log(`[storm] unknown shot ${sh}`); continue; }
      await page.evaluate(({ sh, cfg, wreck }) => {
        const ctx = window.__game.ctx;
        ctx.flags.paused = false;
        const w = ctx.weather;
        const cam = ctx.three.camera;
        ctx.three.renderer.setSize(1200, 680, false);
        if (cam.isPerspectiveCamera) { cam.aspect = 1200 / 680; cam.updateProjectionMatrix(); }
        // Player stands `wreckDist` north (+Z) of the wreck, looking -Z toward the front.
        const px = wreck.cx, pz = wreck.cz + cfg.wreckDist;
        const gy = ctx.terrain.heightAt(px, pz);
        ctx.player.body.body.setTranslation({ x: px, y: gy + 1.6, z: pz }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        ctx.player.inShelter = false;
        // Configure the wall: travels +Z; front at player - dir*edge (i.e. -Z of player).
        w.state = 'storm';
        w.currentStormDuration = 1e6;
        w.stateTimer = 0;
        w.wall.active = true;
        w.wall.dirX = 0; w.wall.dirZ = 1; w.wall.age = 0; w.wall.approaching = true;
        if (sh === 'peak') {
          // Player inside a wide core → intensity 1 (whiteout).
          w.wall.width = 400;
          w.wall.posX = px; w.wall.posZ = pz;
        } else {
          w.wall.width = 140;
          // leading edge at pz - edge ; center = edge - dir*width along +Z ⇒ posZ = (pz - edge) - width.
          w.wall.posX = px;
          w.wall.posZ = (pz - cfg.edge) - w.wall.width;
        }
      }, { sh, cfg, wreck });
      // Tick live so fog + intensity + dust layers + the dust wall all settle.
      await page.waitForTimeout(2200);
      // review 2026-07-15 — the approach shot renders from a YAW SWEEP (pan the camera
      // left/centre/right from a FIXED position) so we can confirm the wall reads as a
      // flat WORLD-fixed advancing front and does NOT spin/re-yaw with the view. Other
      // shots stay single-view.
      const yaws = sh === 'approach' ? [{ tag: 'L', d: -34 }, { tag: '', d: 0 }, { tag: 'R', d: 34 }] : [{ tag: '', d: 0 }];
      for (const yv of yaws) {
        const r = await page.evaluate(({ sh, wreck, cfg, yawDeg }) => {
          const ctx = window.__game.ctx;
          const w = ctx.weather;
          const cam = ctx.three.camera;
          const px = wreck.cx, pz = wreck.cz + cfg.wreckDist;
          const gy = ctx.terrain.heightAt(px, pz);
          ctx.flags.paused = true;
          // Eye at 1.7m, looking -Z toward the wreck top / incoming wall, slightly up so the
          // towering front reads.
          cam.position.set(px, gy + 1.7, pz);
          const aimY = gy + Math.max(4, Math.min(16, (wreck.topY - gy) * 0.5));
          cam.lookAt(wreck.cx, aimY, wreck.cz);
          // Pan the VIEW about world-Y by yawDeg (the wall must not follow it).
          if (yawDeg) cam.rotateOnWorldAxis(new (ctx.time.sunDir.constructor)(0, 1, 0), yawDeg * Math.PI / 180);
          cam.updateMatrixWorld(true);
          ctx.three.renderer.render(ctx.three.scene, cam);
          const fog = ctx.three.scene.fog;
          const dw = w.dustWall;

          // ── review 2026-07-16 — SILHOUETTE GATE (the reviewer's exact complaint:
          //    "i can still see the outline of distant wrecks ... a yellow silhouette
          //    against the sky no matter how far away it is").
          //    A silhouette REQUIRES a value edge, so we measure one directly off the
          //    framebuffer: sky above the horizon vs the fogged ground below it. At peak
          //    they must converge — if they differ, EVERY distant object reads as a cutout.
          //    Root cause this gate exists to catch: the sky dome is a raw ShaderMaterial
          //    (three injects no <colorspace_fragment>, so it writes LINEAR bytes) while
          //    fogged geometry is sRGB-encoded — the same hex rendered 69 RGB units apart.
          //    Code inspection CANNOT see this; only pixels can. ──
          let silhouette = null;
          if (sh === 'peak') {
            const gl = ctx.three.renderer.getContext();
            const BW = gl.drawingBufferWidth, BH = gl.drawingBufferHeight;
            const buf = new Uint8Array(BW * BH * 4);
            gl.readPixels(0, 0, BW, BH, gl.RGBA, gl.UNSIGNED_BYTE, buf);
            const patch = (cx, cyTop) => {   // readPixels is bottom-left origin
              let rr = 0, gg = 0, bb = 0, n = 0;
              for (let dx = -2; dx <= 2; dx++) for (let dy = -2; dy <= 2; dy++) {
                const x = Math.max(0, Math.min(BW - 1, cx + dx));
                const y = Math.max(0, Math.min(BH - 1, BH - 1 - (cyTop + dy)));
                const i = (y * BW + x) * 4;
                rr += buf[i]; gg += buf[i + 1]; bb += buf[i + 2]; n++;
              }
              return [Math.round(rr / n), Math.round(gg / n), Math.round(bb / n)];
            };
            // Sample RELATIVE TO THE HORIZON, not to the frame. Fixed frame fractions are
            // wrong: the peak camera aims up, so a "0.82" row lands on terrain ~3m from the
            // player's boots — near-field, barely fogged, and inside the storm vignette. That
            // measures the vignette, not the whiteout. Project a point at eye height far down
            // the view axis to get the true horizon row, then straddle it: the ground sample
            // must sit just below it (≳40m out ⇒ fully fogged at density 0.18), not at the feet.
            const V = ctx.time.sunDir.constructor;
            const fwd = new V();
            cam.getWorldDirection(fwd);
            const far = new V(
              cam.position.x + fwd.x * 4000,
              cam.position.y,                 // eye height ⇒ the true horizon
              cam.position.z + fwd.z * 4000,
            );
            const ndc = far.clone().project(cam);
            const horizonY = Math.round((-ndc.y * 0.5 + 0.5) * BH);
            const midX = Math.round(BW / 2);
            const skyY2 = Math.max(3, horizonY - 90);
            const gndY2 = Math.min(BH - 4, horizonY + 22);
            const skyRGB = patch(midX, skyY2);   // well above the horizon
            const gndRGB = patch(midX, gndY2);   // fogged distant ground, just below it
            const delta = Math.max(
              Math.abs(skyRGB[0] - gndRGB[0]),
              Math.abs(skyRGB[1] - gndRGB[1]),
              Math.abs(skyRGB[2] - gndRGB[2]),
            );
            silhouette = { skyRGB, gndRGB, delta, horizonY, skyY: skyY2, gndY: gndY2, pass: delta <= 6 };
          }
          return {
            shot: sh, yawDeg,
            silhouette,
            intensity: +w.intensity.toFixed(3),
            pi: +w.perceivedIntensity.toFixed(3),
            fogDensity: fog ? +fog.density.toFixed(4) : null,
            fogColor: fog ? '#' + fog.color.getHexString() : null,
            dustWallVisible: dw ? dw.group.visible : null,
            dustWallYaw: dw ? +dw.group.rotation.y.toFixed(4) : null,
            dustWallOp: dw && dw.shells[0] ? +dw.shells[0].mat.uniforms.uOpacity.value.toFixed(3) : null,
            layerOp: [
              +w.layers.near.mat.opacity.toFixed(2),
              +w.layers.mid.mat.opacity.toFixed(2),
              +w.layers.far.mat.opacity.toFixed(2),
              +w.layers.streak.mat.opacity.toFixed(2),
            ],
          };
        }, { sh, wreck, cfg, yawDeg: yv.d });
        await page.waitForTimeout(120);
        await page.screenshot({ path: join(OUT, `scen-storm-${sh}${yv.tag ? '-yaw' + yv.tag : ''}.png`), fullPage: false });
        console.log(`[storm] ${JSON.stringify(r)}`);
        // review 2026-07-16 — the peak whiteout is now a hard PASS/FAIL, not a vibe check.
        if (r.silhouette) {
          const s = r.silhouette;
          console.log(
            `[storm] SILHOUETTE GATE ${s.pass ? 'PASS' : 'FAIL'} — ` +
            `sky=(${s.skyRGB}) ground=(${s.gndRGB}) delta=${s.delta} (must be <= 6)`,
          );
          if (!s.pass) {
            console.log(
              '[storm] FAIL: sky and fogged ground render different values at peak, so every ' +
              'distant object silhouettes against the sky. Check the sky-dome colour-space ' +
              'encode (sky.ts _stormDustSky) vs the fog colour — a raw ShaderMaterial gets no ' +
              '<colorspace_fragment>, so the same hex renders ~69 RGB units apart.',
            );
            process.exitCode = 1;
          }
        }
      }
    }
  },

  // storm-drift (review 2026-07-17) — Zach's 3rd storm round: the dust WALL must have
  // ZERO sideways movement — "just look like it's moving forward toward the player." This
  // probe proves it in three parts, with numbers:
  //   A) GEOMETRY  — over N advancing frames, the wall's heading vector stays constant
  //      (dot≈1), the group yaw is constant, a FIXED reference point on the wall face has
  //      ~0 lateral displacement (projected onto the wall's width axis) while its forward
  //      advance (projected onto the travel dir) is monotonic.
  //   B) SHADER    — the FACE itself must not scroll along its width. We freeze the wall
  //      head-on on a BLACK background (re-parent → the wall is the ONLY signal, no static
  //      terrain/sky to bias the correlation toward 0), render two frames at uTime 0 and
  //      6.0s WITHOUT moving the geometry, and cross-correlate the horizontal luminance
  //      profile. The best-fit horizontal shift is the net sideways drift of the surface
  //      pattern in px — must be ~0. A region frame-delta proves the mass IS animating
  //      (so a 0 shift isn't a frozen frame); the vertical shift is printed as evidence the
  //      churn moves up/in-place, not sideways.
  //   C) SEQUENCE  — a 3-frame approach (far → near → enveloping) from ONE fixed camera for
  //      the human: the wall grows while its features hold the SAME horizontal position.
  // The prior rounds fixed the geometry (wind-locked yaw, linear wall, dir frozen at arm) —
  // this probe guards A as a regression gate AND targets the real remaining source, B.
  'storm-drift': async (page) => {
    // ── PART A — GEOMETRY: heading constant + zero lateral group translation. ──
    console.log('[storm-drift] PART A — geometry (heading dot, group yaw, ref-point lateral vs forward)');
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const w = ctx.weather;
      window.__game.setTime(0.34);                 // bright midday
      ctx.flags.paused = false;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1200, 680, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1200 / 680; cam.updateProjectionMatrix(); }
      const px = 0, pz = 0;
      const gy = ctx.terrain.heightAt(px, pz);
      ctx.player.body.body.setTranslation({ x: px, y: gy + 1.6, z: pz }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      ctx.player.inShelter = false;
      // Storm with a wall travelling +Z toward the player at origin. speed=0 so ONLY our
      // manual per-frame advance moves it (deterministic under the slow headless clock);
      // updateWeather still re-seats the dust-wall group from the wall state each frame.
      w.state = 'storm'; w.currentStormDuration = 1e6; w.stateTimer = 0; w.longStormAnnounced = true;
      w.wall.active = true;
      w.wall.dirX = 0; w.wall.dirZ = 1; w.wall.width = 140; w.wall.speed = 0; w.wall.age = 0; w.wall.approaching = true;
      const edge = 500;                            // leading edge 500m south (-Z) of the player
      w.wall.posX = px; w.wall.posZ = (pz - edge) - w.wall.width;
    });
    const STEP = 45;   // manual +dir advance per frame (world u) — guarantees forward motion
    const samples = [];
    for (let i = 0; i < 8; i++) {
      await page.evaluate((step) => {
        const w = window.__game.ctx.weather;
        w.wall.posX += w.wall.dirX * step;
        w.wall.posZ += w.wall.dirZ * step;
      }, i === 0 ? 0 : STEP);
      await page.waitForTimeout(150);              // let ≥1 RAF run updateWeather → updateDustWall (re-seat)
      const s = await page.evaluate(() => {
        const ctx = window.__game.ctx; const w = ctx.weather; const dw = w.dustWall;
        const V = ctx.time.sunDir.constructor;
        dw.group.updateMatrixWorld(true);
        const ref = new V(300, 170, 0);            // FIXED flank point on the face, in LOCAL space
        dw.group.localToWorld(ref);
        return {
          dirX: w.wall.dirX, dirZ: w.wall.dirZ,
          yaw: +dw.group.rotation.y.toFixed(6),
          rx: +ref.x.toFixed(4), rz: +ref.z.toFixed(4),
          op: dw.shells[0] ? +dw.shells[0].mat.uniforms.uOpacity.value.toFixed(3) : 0,
          vis: dw.group.visible,
        };
      });
      samples.push(s);
    }
    const s0 = samples[0];
    const dir0 = { x: s0.dirX, z: s0.dirZ };
    const widthAxis = { x: dir0.z, z: -dir0.x };   // perpendicular to dir in XZ
    let maxHeadingErr = 0, maxLateral = 0, forwardMonotonic = true, prevFwd = -Infinity;
    const rows = samples.map((s) => {
      const dot = s.dirX * dir0.x + s.dirZ * dir0.z;
      maxHeadingErr = Math.max(maxHeadingErr, Math.abs(1 - dot));
      const drx = s.rx - s0.rx, drz = s.rz - s0.rz;
      const fwd = drx * dir0.x + drz * dir0.z;
      const lat = drx * widthAxis.x + drz * widthAxis.z;
      maxLateral = Math.max(maxLateral, Math.abs(lat));
      if (fwd < prevFwd - 0.01) forwardMonotonic = false;
      prevFwd = fwd;
      return { fwd: +fwd.toFixed(3), lat: +lat.toFixed(5), dot: +dot.toFixed(6), yaw: s.yaw, op: s.op, vis: s.vis };
    });
    console.log('[storm-drift] geometry samples:');
    rows.forEach((r, i) => console.log(`  f${i}: ${JSON.stringify(r)}`));
    const yawConst = samples.every((s) => Math.abs(s.yaw - s0.yaw) < 1e-4);
    const headingPass = maxHeadingErr < 1e-6;
    const lateralPass = maxLateral < 0.05;         // world u — essentially zero
    const geomPass = headingPass && yawConst && lateralPass && forwardMonotonic;
    console.log(
      `[storm-drift] GEOMETRY ${geomPass ? 'PASS' : 'FAIL'} — headingDotErr=${maxHeadingErr.toExponential(2)} (want <1e-6) | ` +
      `yawConst=${yawConst} | maxLateral=${maxLateral.toFixed(5)}u (want <0.05) | forwardMonotonic=${forwardMonotonic} ` +
      `(fwd ${rows[0].fwd}→${rows[rows.length - 1].fwd}u)`,
    );
    if (!geomPass) process.exitCode = 1;

    // ── PART B — SHADER: the FACE must not scroll along its width axis. ──
    console.log('[storm-drift] PART B — shader face-scroll (cross-correlate two frames at fixed geometry)');
    const sig = await page.evaluate(() => {
      const ctx = window.__game.ctx; const w = ctx.weather; const dw = w.dustWall;
      const cam = ctx.three.camera; const R = ctx.three.renderer;
      ctx.flags.paused = true;
      R.setSize(1200, 680, false);
      if (cam.isPerspectiveCamera) { cam.aspect = 1200 / 680; cam.updateProjectionMatrix(); }
      const H = 340;
      // Freeze the wall head-on: local +Z (leading/face dir) → world +Z; face at z≈0.
      dw.group.position.set(0, 0, 0);
      dw.group.rotation.set(0, 0, 0);
      dw.group.updateMatrixWorld(true);
      dw.group.visible = true;
      for (const s of dw.shells) {
        s.mesh.visible = true;
        s.mat.uniforms.uOpacity.value = 0.97;      // MAX — read the pattern clearly
        s.mat.uniforms.uWind.value = 1.5;          // representative wind (the OLD code scrolled x by uTime·uWind·0.12)
      }
      cam.position.set(0, H * 0.45, 470);
      cam.lookAt(0, H * 0.45, 0);
      cam.updateMatrixWorld(true);
      // Isolate the wall on BLACK so the ONLY varying signal is the wall itself (static
      // terrain/sky would bias the correlation toward shift 0 and mask a real drift).
      const Col = ctx.three.scene.fog.color.constructor;
      const prevClear = R.getClearColor(new Col());
      const prevAlpha = R.getClearAlpha();
      const tmp = new (ctx.three.scene.constructor)();
      tmp.add(dw.group);                           // re-parent the wall out of the main scene
      R.setClearColor(0x000000, 1);
      const gl = R.getContext();
      const BW = gl.drawingBufferWidth, BH = gl.drawingBufferHeight;
      const x0 = 300, x1 = 900, y0 = 200, y1 = 480;
      function readFrame(t) {
        for (const s of dw.shells) s.mat.uniforms.uTime.value = t;
        R.render(tmp, cam);
        const buf = new Uint8Array(BW * BH * 4);
        gl.readPixels(0, 0, BW, BH, gl.RGBA, gl.UNSIGNED_BYTE, buf);
        return buf;
      }
      const lum = (buf, i) => 0.299 * buf[i] + 0.587 * buf[i + 1] + 0.114 * buf[i + 2];
      const bufA = readFrame(0.0);
      const bufB = readFrame(6.0);
      const colA = [], colB = [], rowA = [], rowB = [];
      for (let x = x0; x < x1; x++) {
        let a = 0, b = 0;
        for (let y = y0; y < y1; y++) { const i = (y * BW + x) * 4; a += lum(bufA, i); b += lum(bufB, i); }
        colA.push(a / (y1 - y0)); colB.push(b / (y1 - y0));
      }
      for (let y = y0; y < y1; y++) {
        let a = 0, b = 0;
        for (let x = x0; x < x1; x++) { const i = (y * BW + x) * 4; a += lum(bufA, i); b += lum(bufB, i); }
        rowA.push(a / (x1 - x0)); rowB.push(b / (x1 - x0));
      }
      let dsum = 0, dn = 0;
      for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
        const i = (y * BW + x) * 4; dsum += Math.abs(lum(bufB, i) - lum(bufA, i)); dn++;
      }
      // restore
      ctx.three.scene.add(dw.group);
      R.setClearColor(prevClear, prevAlpha);
      return { colA, colB, rowA, rowB, meanRegionDelta: +(dsum / dn).toFixed(3) };
    });
    // Node-side normalized cross-correlation → best integer shift (px).
    const bestShift = (a, b, maxShift) => {
      const n = a.length;
      const ma = a.reduce((s, v) => s + v, 0) / n, mb = b.reduce((s, v) => s + v, 0) / n;
      const A = a.map((v) => v - ma), B = b.map((v) => v - mb);
      let best = 0, bestC = -Infinity;
      for (let s = -maxShift; s <= maxShift; s++) {
        let num = 0, da = 0, db = 0;
        for (let x = 0; x < n; x++) { const xb = x + s; if (xb < 0 || xb >= n) continue; num += A[x] * B[xb]; da += A[x] * A[x]; db += B[xb] * B[xb]; }
        const c = num / (Math.sqrt(da * db) || 1);
        if (c > bestC) { bestC = c; best = s; }
      }
      return { shift: best, corr: +bestC.toFixed(4) };
    };
    const horiz = bestShift(sig.colA, sig.colB, 40);
    const vert = bestShift(sig.rowA, sig.rowB, 40);
    const animates = sig.meanRegionDelta > 1.5;
    const shaderPass = Math.abs(horiz.shift) <= 1 && animates;
    console.log(
      `[storm-drift] SHADER ${shaderPass ? 'PASS' : 'FAIL'} — horizShift=${horiz.shift}px (corr=${horiz.corr}, want |shift|<=1) | ` +
      `meanFrameDelta=${sig.meanRegionDelta} (want >1.5 → the mass IS churning) | vertShift=${vert.shift}px (corr=${vert.corr}, evidence of vertical/in-place churn)`,
    );
    if (!shaderPass) {
      console.log('[storm-drift] SHADER FAIL: the wall face translates along its width axis — a uTime term leaked into the .x noise coordinate in dustWall.ts FRAG.');
      process.exitCode = 1;
    }
    // Human eyeball of the face (T1 frame currently on the buffer would be black — re-render lit).
    await page.evaluate(() => {
      const ctx = window.__game.ctx; ctx.three.renderer.render(ctx.three.scene, ctx.three.camera);
    });
    await page.waitForTimeout(80);
    await page.screenshot({ path: join(OUT, 'scen-stormdrift-face.png'), fullPage: false });
    console.log('[storm-drift] saved scen-stormdrift-face.png');

    // ── PART C — 3-frame approach sequence from ONE fixed camera. ──
    console.log('[storm-drift] PART C — 3-frame approach (fixed camera; features hold azimuth as it grows)');
    for (const [tag, approachDist] of [['1-far', 500], ['2-near', 260], ['3-envelop', 70]]) {
      await page.evaluate((ad) => {
        const ctx = window.__game.ctx; const w = ctx.weather;
        ctx.flags.paused = false;
        const px = 0, pz = 0;
        const gy = ctx.terrain.heightAt(px, pz);
        w.state = 'storm'; w.currentStormDuration = 1e6;
        w.wall.active = true; w.wall.dirX = 0; w.wall.dirZ = 1; w.wall.width = 140; w.wall.speed = 0; w.wall.age = 0;
        w.wall.posX = px; w.wall.posZ = (pz - ad) - w.wall.width;
        ctx.player.body.body.setTranslation({ x: px, y: gy + 1.6, z: pz }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
        ctx.player.inShelter = false;
      }, approachDist);
      await page.waitForTimeout(600);              // let the loop re-seat the group + settle fog/opacity
      await page.evaluate(() => {
        const ctx = window.__game.ctx; const cam = ctx.three.camera;
        ctx.flags.paused = true;
        const px = 0, pz = 0; const gy = ctx.terrain.heightAt(px, pz);
        // IDENTICAL camera every frame (fixed pos + fixed look target) → azimuth reference.
        cam.position.set(px, gy + 1.7, pz);
        cam.lookAt(px, gy + 40, pz - 300);
        cam.updateMatrixWorld(true);
        ctx.three.renderer.render(ctx.three.scene, cam);
      });
      await page.waitForTimeout(120);
      await page.screenshot({ path: join(OUT, `scen-stormdrift-seq-${tag}.png`), fullPage: false });
      console.log(`[storm-drift] saved scen-stormdrift-seq-${tag}.png (approachDist=${approachDist})`);
    }
    console.log('[storm-drift] done.');
  },

  // Smoke-plume (C21): deploy a lit fire + let its smoke-signal column build, then
  // frame it from a distance against the sky (the "visible-from-afar" signal read).
  // Tall frame for a vertical plume. --storm forces a peak storm (the plume tears flat).
  'smoke-plume': async (page) => {
    const stormy = !!argv.storm;
    await page.evaluate((stormy) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.5);         // noon — sun overhead (not behind the plume → front/side-lit, not backlit)
      ctx.weather.cloudiness = 0.12;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(720, 840, false);   // tall frame for a vertical plume
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 720 / 840; cam.updateProjectionMatrix(); }
      // Offset the fire to the player's side + ahead (clear of the wreck the player spawns by).
      const tr = ctx.player.body.body.translation();
      const V = ctx.three.camera.position.constructor;
      const fwd = new V(); ctx.three.camera.getWorldDirection(fwd); fwd.y = 0; fwd.normalize();
      const fx = tr.x + fwd.z * 20 + fwd.x * 6;
      const fz = tr.z - fwd.x * 20 + fwd.z * 6;
      window.__fireId = window.__game.spawnFire(fx, fz);
      if (stormy) {
        const w = ctx.weather; const tr = ctx.player.body.body.translation();
        w.state = 'storm'; w.intensity = 1; w.perceivedIntensity = 1; w.currentStormDuration = 1e6; w.stateTimer = 0;
        w.wall.active = true; w.wall.posX = tr.x; w.wall.posZ = tr.z; w.wall.dirX = 1; w.wall.dirZ = 0; w.wall.width = 400; w.wall.age = 0;
      } else {
        ctx.weather.intensity = 0;
      }
      // Deterministically build the column (headless rAF throttling starves the
      // real-time accumulation) — fast-forward ~10s of plume.
      window.__game.warmSmoke(10);
    }, stormy);
    await page.waitForTimeout(400);
    const r = await page.evaluate((stormy) => {
      const ctx = window.__game.ctx;
      const f = ctx.fires.list.find((x) => x.id === window.__fireId) || ctx.fires.list[0];
      if (stormy) { ctx.weather.intensity = 1; ctx.weather.perceivedIntensity = 1; }
      ctx.flags.paused = true;
      const cam = ctx.three.camera;
      const p = f.pos;
      // Stand back ~15m + a touch up; look at the lower-mid column so the full plume
      // rises through the upper frame against the sky.
      cam.position.set(p.x - 12, p.y + 3, p.z - 2);
      cam.lookAt(p.x, p.y + 7, p.z);
      cam.updateMatrixWorld(true);
      ctx.three.renderer.render(ctx.three.scene, cam);
      let active = 0, topY = 0;
      if (f.smoke) for (const s of f.smoke) if (s.active) { active++; topY = Math.max(topY, s.sprite.position.y); }
      return { fireId: f.id, alive: f.alive, activePuffs: active, columnHeight: +topY.toFixed(1) };
    }, stormy);
    await page.waitForTimeout(120);
    await page.screenshot({ path: join(OUT, `scen-smoke-plume${stormy ? '-storm' : ''}.png`), fullPage: false });
    console.log(`[smoke-plume] ${JSON.stringify(r)}`);
  },

  // Signal flare (C37): fire signal_kit's transient flare from the player's view,
  // advance the arc to mid-climb (head high + a full ember trail), then frame the
  // whole arc from the side against the sky. --day forces noon; default is a dimmer
  // evening sky where the additive flare reads brightest. Tall frame for the arc.
  'signal-flare': async (page) => {
    const day = !!argv.day;
    await page.evaluate((day) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(day ? 0.5 : 0.86);   // noon, or a dim evening so the flare pops
      ctx.weather.cloudiness = 0.1;
      ctx.weather.intensity = 0;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(720, 840, false);   // tall frame for the vertical arc
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 720 / 840; cam.updateProjectionMatrix(); }
      // Flatten the look so the flare launches along the horizontal forward (a clean arc).
      const V = cam.position.constructor;
      const fwd = new V(); cam.getWorldDirection(fwd); fwd.y = 0; fwd.normalize();
      // Capture the launch origin + forward BEFORE firing (the flare uses the live camera).
      window.__flareOrigin = { x: cam.position.x + fwd.x * 0.6, y: cam.position.y - 0.15, z: cam.position.z + fwd.z * 0.6 };
      window.__flareFwd = { x: fwd.x, z: fwd.z };
      // Fire + fast-forward ~1.6s of arc (head near apogee → the ballistic curve +
      // downrange lean read clearly, and the ember ribbon is fully formed behind it).
      window.__flareCount = window.__game.fireSignalFlare(1.6);
    }, day);
    await page.waitForTimeout(300);
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = true;
      const O = window.__flareOrigin, F = window.__flareFwd;
      const cam = ctx.three.camera;
      // Side vantage: perpendicular to the launch forward, ~15m off, looking at mid-arc.
      const rx = F.z, rz = -F.x;                       // right vector ⟂ to the launch/lean dir → profile view of the arc
      const midX = O.x + F.x * 2.6, midZ = O.z + F.z * 2.6;   // ~mid of the leaned arc
      cam.position.set(midX + rx * 16, O.y + 5.0, midZ + rz * 16);
      cam.lookAt(midX, O.y + 7, midZ);
      cam.updateMatrixWorld(true);
      ctx.three.renderer.render(ctx.three.scene, cam);
      return { liveFlares: window.__flareCount };
    });
    await page.waitForTimeout(120);
    await page.screenshot({ path: join(OUT, `scen-signal-flare${day ? '-day' : ''}.png`), fullPage: false });
    console.log(`[signal-flare] ${JSON.stringify(r)}`);
  },

  // Vista (C28): the horizon-landmark-silhouette check. Find a hand-modeled flagship
  // by name, stand ~--dist=600m away across the desert, and look AT it — does it read
  // as a skyline silhouette, or fade into the fog/sky? --dist=<m> sets the camera range.
  'vista': async (page) => {
    const dist = argv.dist !== undefined ? Number(argv.dist) : 600;
    const fogmult = argv.fogmult !== undefined ? Number(argv.fogmult) : 1;
    const info = await page.evaluate(({ dist, fogmult }) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.5);            // midday, clear sky
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.1;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(1000, 480, false);   // wide for the horizon
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 480; cam.updateProjectionMatrix(); }
      const V = cam.position.constructor;
      // Find a flagship landmark by name (the hand-modeled hero wrecks).
      const names = ['megaShip', 'megaWreck', 'satelliteDish', 'crashedHull', 'openingWreck'];
      let target = null, hit = null;
      for (const n of names) {
        const o = ctx.three.scene.getObjectByName(n);
        if (o) { target = o.getWorldPosition(new V()); hit = n; break; }
      }
      if (!target) return { noTarget: true };
      // Stand `dist` m from the landmark (along the line to origin), eye-level on the dune.
      const d = Math.hypot(target.x, target.z) || 1;
      const ux = target.x / d, uz = target.z / d;
      const cx = target.x - ux * dist, cz = target.z - uz * dist;
      const groundY = ctx.terrain.heightAt(cx, cz);
      cam.position.set(cx, groundY + 3, cz);
      cam.lookAt(target.x, target.y + 12, target.z);   // look at the upper landmark
      cam.updateMatrixWorld(true);
      ctx.flags.paused = true;
      const fog = ctx.three.scene.fog;
      // C30 — optional fog multiplier to preview the vista-crest fog-LIFT effect.
      if (fog && fogmult !== 1) fog.density *= fogmult;
      return { landmark: hit, target: [+target.x.toFixed(0), +target.y.toFixed(0), +target.z.toFixed(0)], dist, fogmult, fogDensity: fog ? +fog.density.toFixed(4) : null };
    }, { dist, fogmult });
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, `scen-vista-${dist}${argv.fogmult !== undefined ? '-fog' + argv.fogmult : ''}.png`), fullPage: false });
    console.log('[vista] ' + JSON.stringify(info));
  },

  // ── skeleton-sockets — the LEGACY (surface) skeleton's skull, close, from three bearings.
  //    Exists because the shipped eye sockets are `CircleGeometry` — one zero-thickness face each —
  //    and that defect is INVISIBLE face-on by definition: a disc looks like a socket right up until
  //    the moment you are not square to it. So a single framed portrait is exactly the shot that
  //    cannot see this. Three bearings: square on, 70° off-axis (where a disc thins to a line), and a
  //    hard 88° graze (where it disappears entirely). Run against the REAL opening-wreck skeleton in
  //    the live world, not a bench copy.
  //      npm run rig -- --scenario=skeleton-sockets --port=52xx --tag=before
  'skeleton-sockets': async (page) => {
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.5);
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.1;
      ctx.flags.paused = true; ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(900, 700, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 700; cam.updateProjectionMatrix(); }
      // The figure declares its own skull (`userData.skullAnchor`) rather than the probe guessing —
      // the merged build has no per-bone objects to search, and a diagnostic that has to guess where
      // the head is photographs a rib and grades it green.
      let skull = null;
      ctx.three.scene.traverse((o) => { if (!skull && o.userData && o.userData.skullAnchor) skull = o; });
      if (!skull) return { noSkull: true };
      const V = cam.position.constructor;
      const c = skull.getWorldPosition(new V());
      // The skull's own +Z (the face direction) in world space, flattened. Read straight off
      // matrixWorld — the skull is a leaf under two rotated groups, so a local guess is wrong.
      const m = skull.matrixWorld.elements;
      let fx = m[8], fz = m[10];                     // local +Z basis, world XZ
      const fl = Math.hypot(fx, fz) || 1; fx /= fl; fz /= fl;
      window.__socketFrame = (deg, dist) => {
        const a = (deg * Math.PI) / 180;
        const bx = fx * Math.cos(a) - fz * Math.sin(a);
        const bz = fx * Math.sin(a) + fz * Math.cos(a);
        cam.position.set(c.x + bx * dist, c.y + 0.012, c.z + bz * dist);
        cam.lookAt(c.x, c.y, c.z);
        cam.updateMatrixWorld(true);
      };
      return { skull: { x: +c.x.toFixed(2), y: +c.y.toFixed(2), z: +c.z.toFixed(2) }, face: [+fx.toFixed(2), +fz.toFixed(2)] };
    });
    if (info.noSkull) { console.log('[skeleton-sockets] NO skullLegacy IN THE SCENE — nothing was measured (vacuous)'); throw new Error('skeleton-sockets found no skull'); }
    console.log('[skeleton-sockets] ' + JSON.stringify(info));
    const tag = argv.tag ? `-${argv.tag}` : '';
    // The first three are DIAGNOSTIC macros (0.4m) — that is where a zero-thickness socket is caught,
    // and nowhere else. `read` is the honest one: the distance the opening wreck is actually met at.
    // Judge TONE there and rule 7 in the macros; grading tone off a 0.4m macro optimises a frame no
    // player will ever stand in.
    for (const [name, deg, dist] of [['face', 0, 0.42], ['turn70', 70, 0.42], ['graze88', 88, 0.40], ['read', 22, 2.6]]) {
      await page.evaluate(({ deg, dist }) => window.__socketFrame(deg, dist), { deg, dist });
      await page.waitForTimeout(220);
      await page.screenshot({ path: join(OUT, `scen-sockets-${name}${tag}.png`), fullPage: false, timeout: 60000 });
      console.log(`[skeleton-sockets] saved scen-sockets-${name}${tag}.png`);
    }
  },

  // Spyglass zoom (C29): stand `dist` m from a flagship landmark, force the spyglass
  // FOV zoom + the scope vignette, and capture the world-through-the-glass. Pass
  // --raw to capture the UN-zoomed wide view for a before/after compare.
  'spyglass-view': async (page) => {
    const dist = argv.dist !== undefined ? Number(argv.dist) : 480;
    const raw = !!argv.raw;
    const info = await page.evaluate(({ dist, raw }) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.5);
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.1;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(720, 720, false);
      const cam = ctx.three.camera;
      const V = cam.position.constructor;
      const names = ['megaShip', 'megaWreck', 'satelliteDish', 'crashedHull', 'openingWreck'];
      let target = null, hit = null;
      for (const n of names) {
        const o = ctx.three.scene.getObjectByName(n);
        if (o) { target = o.getWorldPosition(new V()); hit = n; break; }
      }
      if (!target) return { noTarget: true };
      const d = Math.hypot(target.x, target.z) || 1;
      const ux = target.x / d, uz = target.z / d;
      const cx = target.x - ux * dist, cz = target.z - uz * dist;
      const groundY = ctx.terrain.heightAt(cx, cz);
      cam.position.set(cx, groundY + 3, cz);
      cam.lookAt(target.x, target.y + 10, target.z);
      // Force the zoom (paused → updateSpyglass won't fight it) + the vignette.
      const zoomFov = raw ? 78 : 24;          // SPYGLASS_FOV
      cam.fov = zoomFov;
      cam.aspect = 1; cam.updateProjectionMatrix();
      cam.updateMatrixWorld(true);
      const scope = document.getElementById('spyglass-scope');
      if (scope) scope.style.opacity = raw ? '0' : '0.96';
      ctx.flags.paused = true;
      return { landmark: hit, dist, fov: zoomFov, raw, hasScope: !!scope };
    }, { dist, raw });
    await page.waitForTimeout(320);
    await page.screenshot({ path: join(OUT, `scen-spyglass-${raw ? 'raw' : 'zoom'}-${dist}.png`), fullPage: false });
    console.log('[spyglass-view] ' + JSON.stringify(info));
  },

  // Sun-shade probe (C31): replicate the updateSunExposure heightfield raymarch over a
  // deterministic grid at 3 sun heights, report the shaded fraction. Confirms the
  // occlusion logic detects MEANINGFUL dune shade on the real terrain (not all-sun /
  // all-shade) + reacts to sun height (overhead = clear, low = long shadows).
  'sun-probe': async (page) => {
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const STEP = 2.5, MAXD = 140, CLEAR = 22;
      // Compute the sun direction directly from dayTime (lighting.ts formula) so the
      // probe doesn't depend on the rAF-throttled lighting tick.
      const zones = window.__game.sunInfo().boxes.concat(ctx.shelter.zones);
      const hitsAABB = (ox, oy, oz, dx, dy, dz, z) => {
        let tmin = 0.5, tmax = MAXD;
        const ax = [[ox, dx, z.cx, z.hx], [oy, dy, z.cy, z.hy], [oz, dz, z.cz, z.hz]];
        for (const [o, d, c, h] of ax) {
          if (Math.abs(d) < 1e-6) { if (o < c - h || o > c + h) return false; continue; }
          let t1 = (c - h - o) / d, t2 = (c + h - o) / d; if (t1 > t2) { const m = t1; t1 = t2; t2 = m; }
          if (t1 > tmin) tmin = t1; if (t2 < tmax) tmax = t2; if (tmin > tmax) return false;
        }
        return true;
      };
      const probe = (dayTime) => {
        const ang = (dayTime - 0.25) * Math.PI * 2;
        let sx = Math.cos(ang), sy = Math.sin(ang), sz = 0.18;
        const len = Math.hypot(sx, sy, sz); sx /= len; sy /= len; sz /= len;
        const sunHeight = Math.sin(ang);   // matches ctx.time.sunHeight
        if (sunHeight <= 0.08 || sy <= 0.02) return { dayTime, sunHeight: +sunHeight.toFixed(3), note: 'low sun' };
        let terr = 0, struct = 0, total = 0;
        // Wide grid centered to reach the flagship wrecks (megaShip ~-485,227).
        for (let gx = -560; gx <= 360; gx += 40) {
          for (let gz = -160; gz <= 440; gz += 40) {
            const headY = ctx.terrain.heightAt(gx, gz) + 1.6;
            let tBlock = false;
            for (let d = STEP; d <= MAXD; d += STEP) {
              const ry = headY + sy * d;
              const th = ctx.terrain.heightAt(gx + sx * d, gz + sz * d);
              if (th > ry + 0.3) { tBlock = true; break; }
              if (ry - th > CLEAR) break;
            }
            let sBlock = false;
            if (!tBlock) for (const z of zones) { if (hitsAABB(gx, headY, gz, sx, sy, sz, z)) { sBlock = true; break; } }
            if (tBlock) terr++;
            if (sBlock) struct++;
            total++;
          }
        }
        return { dayTime, sunHeight: +sunHeight.toFixed(3), terrainPct: Math.round((terr / total) * 100), structPct: Math.round((struct / total) * 100), total };
      };
      const out = [probe(0.5), probe(0.40), probe(0.33), probe(0.29), probe(0.275)];   // noon → low sun
      // Targeted: a point on a wreck's SHADOW side must read shaded; the SUNNY side must not.
      let targeted = null;
      const tboxes = window.__game.sunInfo().boxes;
      if (tboxes.length) {
        const b = tboxes[0];
        const ang = (0.33 - 0.25) * Math.PI * 2;
        let sx = Math.cos(ang), sy = Math.sin(ang), sz = 0.18; const L = Math.hypot(sx, sy, sz); sx /= L; sy /= L; sz /= L;
        const off = b.hx + b.hz + 6;
        const shadowSideDetected = hitsAABB(b.cx - sx * off, b.cy, b.cz - sz * off, sx, sy, sz, b);
        const sunnySideClear = !hitsAABB(b.cx + sx * off, b.cy, b.cz + sz * off, sx, sy, sz, b);
        targeted = { boxHalf: { hx: +b.hx.toFixed(1), hy: +b.hy.toFixed(1), hz: +b.hz.toFixed(1) }, shadowSideDetected, sunnySideClear };
      }
      return { occluderBoxes: tboxes.length, zoneTotal: zones.length, targeted, probes: out };
    });
    console.log('[sun-probe] ' + JSON.stringify(r));
  },

  // Wordless prop scene (C32): frame a storytelling tableau (skeleton + props).
  // --idx=N picks the Nth scene; --angle=3q|front|side. Rotation forced to 0 +
  // morning sun (front-light, not noon-flat) per the harness footgun.
  'wordless': async (page) => {
    const idx = argv.idx !== undefined ? Number(argv.idx) : 0;
    const ang = argv.angle || '3q';
    const r = await page.evaluate(({ idx, ang }) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.42);            // morning sun — front/side light, not flat noon
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.15;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(840, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 840 / 760; cam.updateProjectionMatrix(); }
      const V = cam.position.constructor;
      const scenes = [];
      ctx.three.scene.traverse((o) => { if (o.name === 'wordlessScene') scenes.push(o); });
      const s = scenes[idx];
      if (!s) return { found: false, count: scenes.length };
      s.rotation.y = 0;                       // face +Z for a stable read
      s.updateMatrixWorld(true);
      const c = s.getWorldPosition(new V());
      const D = 2.7;
      let cp;
      if (ang === 'front') cp = [c.x, c.y + 1.15, c.z + D];
      else if (ang === 'side') cp = [c.x + D, c.y + 1.0, c.z + 0.2];
      else cp = [c.x + D * 0.72, c.y + 1.35, c.z + D * 0.72];   // 3q
      cam.position.set(cp[0], cp[1], cp[2]);
      cam.lookAt(c.x, c.y + 0.45, c.z);
      cam.updateMatrixWorld(true);
      ctx.flags.paused = true;
      return { found: true, idx, count: scenes.length, center: [+c.x.toFixed(0), +c.y.toFixed(1), +c.z.toFixed(0)] };
    }, { idx, ang });
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, `scen-wordless-${idx}-${ang}.png`), fullPage: false });
    console.log('[wordless] ' + JSON.stringify(r));
  },

  // Worm far-horizon crossing (C36): force a distant crossing, fast-forward to mid-
  // sweep (fully surfaced + central), and frame the dorsal ridge from ~190m.
  'worm-crossing': async (page) => {
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.33);              // warm afternoon — side-lit dunes, dark ridge
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.1;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(920, 600, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 920 / 600; cam.updateProjectionMatrix(); }
      const c = window.__game.triggerWormCrossing();
      if (!c) return { found: false };
      window.__game.advanceWormCrossing(13);    // jump to mid-sweep (surfaced + central)
      const pl = ctx.player.body.body.translation();
      const dx = c.cx - pl.x, dz = c.cz - pl.z, d = Math.hypot(dx, dz) || 1;
      const ux = dx / d, uz = dz / d, camDist = 165;
      const ccx = c.cx - ux * camDist, ccz = c.cz - uz * camDist;
      cam.position.set(ccx, ctx.terrain.heightAt(ccx, ccz) + 16, ccz);   // raised to clear foreground dunes
      cam.lookAt(c.cx, ctx.terrain.heightAt(c.cx, c.cz) + 4, c.cz);
      cam.updateMatrixWorld(true);
      ctx.flags.paused = true;
      return { found: true, center: [+c.cx.toFixed(0), +c.cz.toFixed(0)] };
    });
    await page.waitForTimeout(320);
    await page.screenshot({ path: join(OUT, 'scen-worm-crossing.png'), fullPage: false });
    console.log('[worm-crossing] ' + JSON.stringify(r));
  },

  // Fireball/bolide (C34): force a rare fireball at midnight, aim the camera at its
  // arc, let it advance to ~peak, and capture the night-sky moment.
  'fireball': async (page) => {
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.0);               // midnight
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(860, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 860 / 760; cam.updateProjectionMatrix(); }
      const res = window.__game.triggerFireball();
      if (!res) return { found: false };
      const d = res.dir, R = 460, p = cam.position;
      cam.lookAt(p.x + d[0] * R, p.y + d[1] * R, p.z + d[2] * R);   // aim at the fireball's peak point
      cam.updateMatrixWorld(true);
      return { found: true, dir: d.map((x) => +x.toFixed(2)) };
    });
    await page.waitForTimeout(700);             // let night settle + the fireball advance to ~peak
    await page.screenshot({ path: join(OUT, 'scen-fireball.png'), fullPage: false });
    console.log('[fireball] ' + JSON.stringify(r));
  },

  // ACBE (D1) — the crashing-wreck event, captured DETERMINISTICALLY: trigger, PAUSE the
  // main tick, then step the FSM via __game.advanceCrash to an exact moment (the live sim
  // runs slow headless, so wall-clock waits are unreliable). The paused scene still renders,
  // so the static screenshot doesn't time out. --phase=streak (mid-flight asset shot) |
  // impact (settled FX) | ground (player POV up at the descending streak). --time=day|night.
  'crash': async (page) => {
    const phase = argv.phase || 'impact';
    const dn = argv.time === 'day' ? 0.5 : 0.0;
    await page.evaluate(({ dn }) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(dn);
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.12;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      ctx.three.renderer.setSize(900, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 760; cam.updateProjectionMatrix(); }
    }, { dn });
    await page.waitForTimeout(550);   // let lighting/sky settle to the set time of day (paused would freeze it)
    const r = await page.evaluate(({ phase }) => {
      const ctx = window.__game.ctx;
      const FLIGHT = 5.5;   // = Tuning.CRASH_FLIGHT_S
      const pp = ctx.player.body.body.translation();
      const res = window.__game.triggerCrash();
      if (!res) return { found: false };
      const ix = res.x, iz = res.z, iy = ctx.terrain.heightAt(ix, iz);
      ctx.flags.paused = true;                                                    // freeze the live tick
      // Fine sub-steps → the trail builds densely like real 60fps play (not blobby).
      const adv = (phase === 'site' || phase === 'interior') ? FLIGHT + 9 : phase === 'impact' ? FLIGHT + 0.5 : FLIGHT * 0.5;
      window.__game.advanceCrash(adv, 220);
      const st = window.__game.crashState();
      const hp = st.headPos;
      const cam = ctx.three.camera;
      if (phase === 'streak' && hp) {
        cam.position.set(hp[0] + 120, hp[1] - 70, hp[2] + 120);   // side + below the head → trail streaks up-back
        cam.lookAt(hp[0], hp[1] - 4, hp[2]);
      } else if (phase === 'ground' && hp) {
        cam.position.set(pp.x, iy + 2.6, pp.z);                   // player eye, look up at the streak
        cam.lookAt(hp[0], hp[1], hp[2]);
      } else if (phase === 'site') {
        cam.position.set(ix + 24, iy + 11, iz + 24);             // settled site: wreck + scorch + beacon column
        cam.lookAt(ix, iy + 4, iz);
      } else if (phase === 'interior') {
        ctx.three.renderer.toneMappingExposure = 2.4;           // brighten the dim trough so the dressing reads for verification
        cam.position.set(ix + 5, iy + 7, iz + 8);               // lower 3/4 down into the open husk → the dressed interior
        cam.lookAt(ix, iy - 0.8, iz);
      } else {
        cam.position.set(ix + 36, iy + 16, iz + 36);             // 3/4 over the impact moment
        cam.lookAt(ix, iy + 3, iz);
      }
      cam.updateMatrixWorld(true);
      const jl = ctx.journals.list.filter((j) => j.kind === 'crash_log').slice(-1)[0];
      const log = jl && jl.content ? (jl.content.subtitle + ' :: ' + jl.content.entries.map((e) => e[1]).join(' // ')) : null;
      return { found: true, ix: +ix.toFixed(1), iy: +iy.toFixed(1), iz: +iz.toFixed(1),
        role: res.role, t: +st.t.toFixed(2), impacted: st.impacted, head: hp ? hp.map((v) => +v.toFixed(0)) : null, log };
    }, { phase });
    if (!r.found) { console.log('[crash] not armed'); return; }
    // 'site' adds a wreck (new materials) → let the paused scene render a few frames first so
    // the cold shader compile (ABL multi-second stall) finishes BEFORE the screenshot.
    await page.waitForTimeout((phase === 'site' || phase === 'interior') ? 2200 : 300);
    await page.screenshot({ path: join(OUT, `scen-crash-${phase}-${argv.time || 'night'}.png`), fullPage: false, timeout: 90000 });
    console.log('[crash] ' + JSON.stringify(r));
  },

  // ACBE (D1) Tier 4 — crash SAVE ROUND-TRIP test (no screenshot). Land a crash, then run the
  // full save → clear → load(v15) → restore cycle and report site counts: PASS iff
  // before === afterRestore (>0) && afterReset === 0 && saveOk && loadOk.
  'crash-roundtrip': async (page) => {
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.5);
      ctx.weather.intensity = 0;
      window.__game.triggerCrash();
      window.__game.advanceCrash(7, 120);   // fly + land the crash so a site exists
      return window.__game.crashRoundtrip();
    });
    const pass = r.before > 0 && r.afterReset === 0 && r.afterRestore === r.before && r.saveOk && r.loadOk;
    console.log(`[crash-roundtrip] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r)}`);
  },

  // ACBE (D1) Tier 4 (C) — interior HEAT-HAZARD probe (no screenshot). Land a fresh crash, then
  // sample the heat falloff + bake the player at centre. PASS iff center>near>half>edge==0 and
  // the temperature CLIMBS while baking. Runs at NIGHT so the climb is the crash heat, not the sun.
  'crash-heat': async (page) => {
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.92);          // night — cold drains, so a temp climb = the crash bake
      ctx.weather.intensity = 0;
      window.__game.triggerCrash();
      window.__game.advanceCrash(7, 120);   // land a fresh crash so its fires are at full burn
      return window.__game.crashHeatProbe();
    });
    const pass = !r.error && r.center > r.near && r.near > r.half && r.half > r.edge && r.edge === 0 && r.dTemp > 0 && r.shelterAfter > 0;
    console.log(`[crash-heat] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r)}`);
  },

  // Vulture (ACAH): frame a perched vulture on its tree for model iteration.
  // --angle=3q|side|front; head faces +X (rotation forced to 0 for a stable read).
  'vulture': async (page) => {
    const ang = argv.angle || '3q';
    const r = await page.evaluate((ang) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.45);
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.three.renderer.setSize(820, 900, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 820 / 900; cam.updateProjectionMatrix(); }
      const v = ctx.vultures?.list?.[0];
      if (!v) return { found: false };
      v.mesh.rotation.y = 0;                 // head faces +X for a stable read
      ctx.flags.paused = true;
      const p = v.pos;
      const eye = p.y + 0.28;                // bird body height
      let cp;
      if (ang === 'side') cp = [p.x, eye, p.z + 1.1];
      else if (ang === 'front') cp = [p.x + 1.1, eye, p.z + 0.15];
      else cp = [p.x + 1.0, eye + 0.12, p.z + 1.0];   // 3q
      cam.position.set(cp[0], cp[1], cp[2]);
      cam.lookAt(p.x + 0.05, p.y + 0.24, p.z);
      cam.updateMatrixWorld(true);
      return { found: true, count: ctx.vultures.list.length, perchY: +p.y.toFixed(1) };
    }, ang);
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, `scen-vulture-${ang}.png`), fullPage: false });
    console.log(`[vulture] ${JSON.stringify(r)}`);
  },

  // Vulture-pose (ACAI): force the first vulture into a state + pin it in frame so
  // the live loop poses the rig (idle/flying/landing/dead). --state=<state>.
  'vulture-pose': async (page) => {
    const state = argv.state || 'flying';
    await page.evaluate((state) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.45);
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.three.renderer.setSize(820, 760, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 820 / 760; cam.updateProjectionMatrix(); }
      const v = ctx.vultures?.list?.[0];
      if (!v) return;
      // Pin the bird at a clear spot ~3m up; remember it for re-pinning each frame.
      window.__poseAnchor = { x: v.pos.x, y: v.pos.y + 1.5, z: v.pos.z };
      window.__poseV = v;
      v.state = state;
      v.landed = false;
    }, state);
    // Let the live loop pose the rig for ~0.4s, THEN pause (freezing the rig
    // rotations) + re-pin the bird at the anchor + frame the camera on it.
    await page.waitForTimeout(450);
    const ang = argv.angle || '3q';
    await page.evaluate((ang) => {
      const ctx = window.__game.ctx;
      const v = window.__poseV; const a = window.__poseAnchor;
      if (!v || !a) return;
      ctx.flags.paused = true;
      v.pos.set(a.x, a.y, a.z);
      v.mesh.position.set(a.x, a.y, a.z);
      v.mesh.rotation.set(0, 0, 0);   // head faces +X → camera on +Z sees the profile
      const cam = ctx.three.camera;
      // side = pure +Z (left flank profile); 3q = front-quarter (+X +Z).
      const cp = ang === 'side' ? [a.x, a.y + 0.04, a.z + 0.82] : [a.x + 0.64, a.y + 0.1, a.z + 0.64];
      cam.position.set(cp[0], cp[1], cp[2]);
      cam.lookAt(a.x, a.y, a.z);
      cam.updateMatrixWorld(true);
    }, ang);
    await page.waitForTimeout(120);
    await page.screenshot({ path: join(OUT, `scen-vulture-pose-${state}.png`), fullPage: false });
    console.log(`[vulture-pose] state=${state}`);
  },

  // Vulture-kill (ACAH): verify the kill->fall->land->'take'-tag path (the loot
  // E-take + combat dispatch mirror the verified shrew pattern). Logic eval.
  // Vulture-flight (ACAI T4): verify the relocate-and-land FSM cycle
  // perched → flying (relocating, target on ANOTHER tree) → landing → perched
  // (re-perched at the target). Logic eval — the in-motion arc/cadence is
  // foreground-owed (D150), so this asserts the state machine, not the feel.
  'vulture-flight': async (page) => {
    const r1 = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const v = ctx.vultures?.list?.[0];
      if (!v) return { noVulture: true };
      // Park the perched bird right beside the player so proximity triggers the
      // launch; its relocation target is then a far salt-flat perch (different tree).
      const pp = ctx.player.body.body.translation();
      const gy = ctx.terrain.heightAt(pp.x + 5, pp.z);
      v.state = 'perched'; v.relocating = false; v.landed = false;
      v.perch.set(pp.x + 5, gy + 2.5, pp.z);
      v.pos.copy(v.perch);
      v.mesh.position.copy(v.pos);
      v.body.setNextKinematicTranslation({ x: v.pos.x, y: v.pos.y + 0.26, z: v.pos.z });
      return { ok: true };
    });
    if (r1.noVulture) { console.log('[vulture-flight] SKIP — no vulture'); return; }
    await page.waitForTimeout(1600);   // let it launch + pick a target
    // ACAI f/u — sample terrain clearance during the REAL flight (the bug: the
    // bird sank through dunes when leaving the salt flats). Min over a few frames.
    let minClear = Infinity, minFacing = 1;
    for (let i = 0; i < 5; i++) {
      await page.waitForTimeout(120);
      const c = await page.evaluate(() => {
        const ctx = window.__game.ctx;
        const v = ctx.vultures.list[0];
        if (v.state !== 'flying') return null;
        // Head-forward check: world +X (the head) should align with the travel dir.
        const V = ctx.three.camera.position.constructor;
        const fwd = new V(1, 0, 0).applyQuaternion(v.mesh.quaternion);
        const vx = Math.sin(v.heading), vz = Math.cos(v.heading);
        const facing = fwd.x * vx + fwd.z * vz;   // ~+1 forward, ~-1 backwards
        return { clear: +(v.pos.y - ctx.terrain.heightAt(v.pos.x, v.pos.z)).toFixed(2), facing: +facing.toFixed(2) };
      });
      if (c) { if (c.clear < minClear) minClear = c.clear; if (c.facing < minFacing) minFacing = c.facing; }
    }
    const r2 = await page.evaluate(() => {
      const v = window.__game.ctx.vultures.list[0];
      const dTree = Math.sqrt((v.target.x - v.perch.x) ** 2 + (v.target.z - v.perch.z) ** 2);
      return { state: v.state, relocating: v.relocating, targetTreeDist: +dTree.toFixed(1) };
    });
    // Shortcut the long cross-map flight: drop the bird just overhead its target
    // so the landing → re-perch leg runs without waiting out 40m of travel.
    const r3 = await page.evaluate(() => {
      const v = window.__game.ctx.vultures.list[0];
      if (v.state !== 'flying') return { notFlying: v.state };
      v.pos.set(v.target.x, v.target.y + 1.2, v.target.z);
      v.mesh.position.copy(v.pos);
      return { ok: true };
    });
    await page.waitForTimeout(16000);   // descend + re-perch (slow sim clock)
    const r4 = await page.evaluate(() => {
      const v = window.__game.ctx.vultures.list[0];
      const atTarget = Math.sqrt((v.perch.x - v.target.x) ** 2 + (v.perch.z - v.target.z) ** 2);
      const hd = Math.sqrt((v.pos.x - v.target.x) ** 2 + (v.pos.z - v.target.z) ** 2);
      return { state: v.state, rePerchAtTarget: +atTarget.toFixed(2), hd: +hd.toFixed(2), dy: +(v.pos.y - v.target.y).toFixed(2) };
    });
    const launchOk = r2.state === 'flying' && r2.relocating === true && r2.targetTreeDist >= 40;
    const landOk = r4.state === 'perched' && r4.rePerchAtTarget < 0.3;
    // Clearance must stay near/above VULTURE_MIN_FLIGHT_CLEARANCE (3.0m) — a small
    // negative slack tolerates the heightAt sample landing on a sharp ridge tip.
    const clearOk = minClear === Infinity || minClear >= 2.0;
    // Head must point ALONG travel (forward), not backwards.
    const facingOk = minFacing > 0.7;
    console.log(`[vulture-flight] ${launchOk && landOk && clearOk && facingOk ? 'PASS' : 'FAIL'} launch=${JSON.stringify(r2)} minClear=${minClear === Infinity ? 'n/a' : minClear} minFacing=${minFacing} flightShortcut=${JSON.stringify(r3)} land=${JSON.stringify(r4)}`);
  },

  // Vulture-circle (ACAI f/u E1): a vulture wheeling over a bone carcass. Reports
  // the circler + carcass counts and frames the orbit (paused mid-wheel).
  'vulture-circle': async (page) => {
    await page.waitForTimeout(800);   // let the circlers climb to orbit altitude
    const r = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const circlers = ctx.vultures.list.filter((v) => v.carcass);
      const carcasses = new Set(ctx.vultures.list.filter((v) => v.carcass).map((v) => `${v.carcass.x.toFixed(0)},${v.carcass.z.toFixed(0)}`));
      if (!circlers.length) return { circlers: 0 };
      const v = circlers[0];
      const c = v.carcass;
      ctx.weather.intensity = 0; window.__game.setTime(0.5);
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.flags.paused = true;   // freeze the wheel for a clean still
      const cam = ctx.three.camera;
      // Close on the soaring bird (carcass below-ground in frame for context).
      cam.position.set(v.pos.x + 4.5, v.pos.y + 1.2, v.pos.z + 4.5);
      cam.lookAt(v.pos.x, v.pos.y - 1.5, v.pos.z);
      cam.updateMatrixWorld(true);
      return {
        circlers: circlers.length, carcasses: carcasses.size,
        state: v.state,
        vpos: [v.pos.x.toFixed(1), v.pos.y.toFixed(1), v.pos.z.toFixed(1)],
        alt: +(v.pos.y - c.y).toFixed(1),
      };
    });
    await page.waitForTimeout(300);
    if (r.circlers) await page.screenshot({ path: join(OUT, 'scen-vulture-circle.png'), fullPage: false });
    console.log(`[vulture-circle] ${JSON.stringify(r)}`);
  },

  // Vulture-hunt (ACAI f/u E3): a circling vulture swoops, grabs a lizard, and
  // carries it off. Teleports a lizard under a carcass + forces the hunt, then
  // asserts swooping → carrying (prey clutched) → lizard removed from the world.
  'vulture-hunt': async (page) => {
    const r1 = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const v = ctx.vultures.list[0];
      const l = ctx.lizards[0];
      if (!v || !l) return { noEntity: true };
      // Synthesize a circling vulture over a lizard (seed-independent): anchor a
      // carcass at the lizard, set the bird wheeling above it, force the hunt.
      const V = ctx.three.camera.position.constructor;
      const cy = ctx.terrain.heightAt(l.pos.x, l.pos.z);
      v.carcass = new V(l.pos.x, cy, l.pos.z);
      v.prey = null;
      v.state = 'circling';
      v.circlePhase = 0;
      v.pos.set(l.pos.x + 13, cy + 15, l.pos.z);
      v.huntCooldown = 0;   // hunt now
      return { ok: true, lizardId: l.id, vId: v.id, lizardsBefore: ctx.lizards.length };
    });
    if (r1.noEntity) { console.log(`[vulture-hunt] SKIP ${JSON.stringify(r1)}`); return; }
    let sawSwoop = false, sawCarry = false, sawPrey = false, sawFeed = false, sawReturn = false, feedDist = null;
    for (let i = 0; i < 340; i++) {
      await page.waitForTimeout(250);
      const s = await page.evaluate((a) => {
        const ctx = window.__game.ctx;
        const v = ctx.vultures.list.find((vv) => vv.id === a.vId);
        const feedDist = v && v.state === 'feeding' && v.carcass
          ? Math.sqrt((v.pos.x - v.carcass.x) ** 2 + (v.pos.z - v.carcass.z) ** 2) : null;
        return { state: v ? v.state : 'gone', hasPrey: !!(v && v.prey), lizGone: !ctx.lizards.find((l) => l.id === a.lizardId), feedDist };
      }, { lizardId: r1.lizardId, vId: r1.vId });
      if (s.state === 'swooping') sawSwoop = true;
      if (s.state === 'carrying') sawCarry = true;
      if (s.hasPrey) sawPrey = true;
      if (s.state === 'feeding') { sawFeed = true; if (feedDist === null && s.feedDist !== null) feedDist = +s.feedDist.toFixed(1); }
      if (s.state === 'returning') sawReturn = true;
      // The bird should fly off a distance → land to eat → fly back (NOT teleport).
      if (sawFeed && sawReturn) break;
    }
    const fin = await page.evaluate((a) => {
      const ctx = window.__game.ctx;
      const v = ctx.vultures.list.find((vv) => vv.id === a.vId);
      return { state: v ? v.state : 'gone', lizGone: !ctx.lizards.find((l) => l.id === a.lizardId), lizardsAfter: ctx.lizards.length };
    }, { lizardId: r1.lizardId, vId: r1.vId });
    // Must have flown a real distance from the carcass before landing to feed.
    const fedFar = feedDist !== null && feedDist >= 30;
    const pass = sawSwoop && sawCarry && sawPrey && fin.lizGone && sawFeed && fedFar;
    console.log(`[vulture-hunt] ${pass ? 'PASS' : 'FAIL'} sawSwoop=${sawSwoop} sawCarry=${sawCarry} sawFeed=${sawFeed} feedDist=${feedDist} sawReturn=${sawReturn} ${JSON.stringify(fin)}`);
  },

  // Vulture-escape (ACAI f/u): a swooped shrew dives for cover; once it's half-
  // buried the vulture loses the target + pulls up (shrew survives).
  'vulture-escape': async (page) => {
    const r1 = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const v = ctx.vultures.list[0];
      const s = ctx.shrews.list[0];
      if (!v || !s) return { noEntity: true };
      const V = ctx.three.camera.position.constructor;
      const cy = ctx.terrain.heightAt(s.pos.x, s.pos.z);
      v.carcass = new V(s.pos.x, cy, s.pos.z);
      v.prey = null; v.state = 'circling'; v.circlePhase = 0;
      v.pos.set(s.pos.x + 6, cy + 8, s.pos.z);
      v.huntCooldown = 0;
      window.__rand = Math.random; Math.random = () => 0;   // force the escape roll to succeed
      return { ok: true, shrewId: s.id, vId: v.id };
    });
    if (r1.noEntity) { console.log('[vulture-escape] SKIP'); return; }
    let sawSwoop = false, sawBurrow = false, forced = false;
    for (let i = 0; i < 70; i++) {
      await page.waitForTimeout(180);
      const o = await page.evaluate((a) => {
        const ctx = window.__game.ctx;
        const v = ctx.vultures.list.find((x) => x.id === a.vId);
        const s = ctx.shrews.list.find((x) => x.id === a.shrewId);
        return { vstate: v ? v.state : 'gone', sstate: s ? s.state : 'gone' };
      }, r1);
      if (o.vstate === 'swooping') sawSwoop = true;
      if (o.sstate === 'burrow') {
        sawBurrow = true;
        // It dove — complete the burrow so the escape is decisive (skip the close race).
        if (!forced) { forced = true; await page.evaluate((a) => { const s = window.__game.ctx.shrews.list.find((x) => x.id === a.shrewId); if (s) { s.burrowT = 1; s.burrowHold = 4; } }, r1); }
      }
      if (sawBurrow && forced && o.vstate === 'circling') break;   // swoop aborted
    }
    const fin = await page.evaluate((a) => {
      Math.random = window.__rand;
      const ctx = window.__game.ctx;
      const v = ctx.vultures.list.find((x) => x.id === a.vId);
      const s = ctx.shrews.list.find((x) => x.id === a.shrewId);
      return { vstate: v ? v.state : 'gone', shrewAlive: !!s, sstate: s ? s.state : 'gone' };
    }, r1);
    const pass = sawSwoop && sawBurrow && fin.shrewAlive && fin.vstate === 'circling';
    console.log(`[vulture-escape] ${pass ? 'PASS' : 'FAIL'} sawSwoop=${sawSwoop} sawBurrow=${sawBurrow} ${JSON.stringify(fin)}`);
  },

  // Vulture-scavenge (ACAI f/u): a circler is attracted to dropped MEAT, swoops,
  // grabs it off the ground + carries it off (the pickup is removed).
  'vulture-scavenge': async (page) => {
    const r1 = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const v = ctx.vultures.list[0];
      if (!v) return { noVulture: true };
      const V = ctx.three.camera.position.constructor;
      // Anchor a carcass near the player + drop a fake meat pickup beside it.
      const pt = ctx.player.body.body.translation();
      const cy = ctx.terrain.heightAt(pt.x + 20, pt.z);
      v.carcass = new V(pt.x + 20, cy, pt.z);
      v.prey = null; v.state = 'circling'; v.circlePhase = 0;
      v.pos.set(pt.x + 20 + 13, cy + 15, pt.z);
      v.huntCooldown = 0;
      const mx = pt.x + 20 + 4, mz = pt.z + 4;
      const fakeMesh = new (ctx.three.scene.constructor)();   // throwaway Object3D
      const id = 990000 + Math.floor(Math.random() * 1000);
      ctx.pickups.list.push({
        id, itemId: 'raw_lizard_meat', mesh: fakeMesh,
        pos: new V(mx, ctx.terrain.heightAt(mx, mz) + 0.06, mz),
        body: null, bobPhase: 0, hovered: false, ridingSledId: null,
      });
      window.__rand = Math.random; Math.random = () => 0;   // force the scavenge roll
      return { ok: true, meatId: id, vId: v.id, pickupsBefore: ctx.pickups.list.length };
    });
    if (r1.noVulture) { console.log('[vulture-scavenge] SKIP'); return; }
    let sawSwoop = false, sawPickupTarget = false, sawCarry = false;
    for (let i = 0; i < 80; i++) {
      await page.waitForTimeout(200);
      const o = await page.evaluate((a) => {
        const ctx = window.__game.ctx;
        const v = ctx.vultures.list.find((x) => x.id === a.vId);
        return { vstate: v ? v.state : 'gone', huntKind: v ? v.huntKind : null, meatGone: !ctx.pickups.list.find((p) => p.id === a.meatId) };
      }, r1);
      if (o.vstate === 'swooping') sawSwoop = true;
      if (o.huntKind === 'pickup') sawPickupTarget = true;
      if (o.vstate === 'carrying') sawCarry = true;
      if (sawCarry && o.meatGone) break;
    }
    const fin = await page.evaluate((a) => {
      Math.random = window.__rand;
      const ctx = window.__game.ctx;
      const v = ctx.vultures.list.find((x) => x.id === a.vId);
      return { vstate: v ? v.state : 'gone', meatGone: !ctx.pickups.list.find((p) => p.id === a.meatId) };
    }, r1);
    const pass = sawSwoop && sawPickupTarget && sawCarry && fin.meatGone;
    console.log(`[vulture-scavenge] ${pass ? 'PASS' : 'FAIL'} sawSwoop=${sawSwoop} pickupTarget=${sawPickupTarget} sawCarry=${sawCarry} ${JSON.stringify(fin)}`);
  },

  'vulture-kill': async (page) => {
    const r1 = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const v = ctx.vultures?.list?.[0];
      if (!v) return { noVulture: true };
      // Relocate to OPEN ground (6m off the tree) + lift ~3m so the dynamic-body
      // tumble (T5) falls clear of the trunk and reads against bare dune.
      const ox = v.pos.x + 6, oz = v.pos.z + 6;
      const gy = ctx.terrain.heightAt(ox, oz);
      v.perch.set(ox, gy, oz);
      v.pos.set(ox, gy + 3.0, oz);
      v.mesh.position.copy(v.pos);
      v.body.setNextKinematicTranslation({ x: v.pos.x, y: v.pos.y + 0.26, z: v.pos.z });
      // Frame a side camera on the bird so the fall strip reads (pulled back +
      // raised; sun high so it isn't a horizon silhouette).
      const cam = ctx.three.camera;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.weather.intensity = 0;
      cam.position.set(v.pos.x + 7, gy + 4.5, v.pos.z + 7);
      cam.lookAt(v.pos.x, gy + 1.2, v.pos.z);
      cam.updateMatrixWorld(true);
      window.__game.setTime(0.5);
      // Drive the REAL death → swaps in the dynamic tumbling body.
      const killed = window.__game.killVulture(v.id);
      return { ok: true, killed, id: v.id };
    });
    if (r1.noVulture) { console.log('[vulture-kill] SKIP — no vulture'); return; }
    // Let the dynamic body tumble + settle (game stays live so physics ticks).
    // The player camera is far away + auto-tracks the player, so we can't film
    // the fall from here (D150 — in-motion feel is foreground-owed); instead we
    // PAUSE once it has settled and frame the resting corpse for a clean read.
    // rig-shot runs a deliberately slow sim clock (D172, ~8× wall:sim), so a 3m
    // fall + tumble + settle needs many wall-seconds of game-time to complete.
    await page.waitForTimeout(16000);
    const r2 = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const V = ctx.three.camera.position.constructor;
      const v = ctx.vultures.list[0];
      let tagged = false;
      v.mesh.traverse((o) => { if (o.userData.interactType === 'take' && o.userData.interactRegistry === 'vultures') tagged = true; });
      const gy = ctx.terrain.heightAt(v.pos.x, v.pos.z);
      // Measure the mesh's actual lowest point vs the ground (the feet-origin is
      // misleading once the bird rests on its side).
      v.mesh.updateMatrixWorld(true);
      const Box3 = ctx.three.scene.constructor === Object ? null : null;  // (unused — keep V import live)
      const box = { minY: Infinity, maxY: -Infinity };
      v.mesh.traverse((o) => {
        if (!o.isMesh || !o.geometry) return;
        if (!o.geometry.boundingBox) o.geometry.computeBoundingBox();
        const bb = o.geometry.boundingBox;
        for (const cx of [bb.min.x, bb.max.x]) for (const cy of [bb.min.y, bb.max.y]) for (const cz of [bb.min.z, bb.max.z]) {
          const p = new V(cx, cy, cz); o.localToWorld(p);
          if (p.y < box.minY) box.minY = p.y;
          if (p.y > box.maxY) box.maxY = p.y;
        }
      });
      const bottomGap = +(box.minY - gy).toFixed(2);   // lowest mesh point above ground
      // Freeze + frame the corpse on the dune.
      ctx.flags.paused = true;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.weather.intensity = 0;
      window.__game.setTime(0.5);
      const cam = ctx.three.camera;
      cam.position.set(v.pos.x + 1.6, gy + 1.0, v.pos.z + 1.6);
      cam.lookAt(v.pos.x, gy + 0.15, v.pos.z);
      cam.updateMatrixWorld(true);
      return { state: v.state, landed: v.landed, tagged, bottomGap, deathAge: +v.deathAge.toFixed(1) };
    });
    await page.waitForTimeout(250);
    await page.screenshot({ path: join(OUT, 'scen-vulture-kill-rest.png'), fullPage: false });
    // Lowest mesh point within ~0.25m of the ground = resting on the dune.
    const onGround = r2.bottomGap >= -0.25 && r2.bottomGap <= 0.25;
    const pass = r2.state === 'dead' && r2.landed === true && r2.tagged === true && onGround;
    console.log(`[vulture-kill] ${pass ? 'PASS' : 'FAIL'} ${JSON.stringify(r2)}`);
  },

  // Scrap-loot (ACAH): verify scrap debris scatters around wrecks (the bootstrap
  // loot fix) — count scrap pickups + how many sit within 12m of a wreck, and
  // frame a wreck with its scrap ring. --time for legibility.
  'scrap-loot': async (page) => {
    const t = argv.time !== undefined ? Number(argv.time) : 0.42;
    const r = await page.evaluate((t) => {
      const ctx = window.__game.ctx;
      window.__game.setTime(t);
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.three.renderer.setSize(900, 700, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 700; cam.updateProjectionMatrix(); }
      const scrap = (ctx.pickups.list || []).filter((p) => p.itemId === 'scrap');
      const wrecks = (ctx.salvageables?.list || []).map((s) => s.pos);
      // count scrap within 12m of any wreck
      let nearWreck = 0;
      for (const sp of scrap) {
        for (const w of wrecks) {
          const dx = sp.pos.x - w.x, dz = sp.pos.z - w.z;
          if (dx * dx + dz * dz < 144) { nearWreck++; break; }
        }
      }
      // frame the wreck that has the most scrap around it
      let best = null, bestN = -1;
      for (const w of wrecks) {
        let c = 0;
        for (const sp of scrap) {
          const dx = sp.pos.x - w.x, dz = sp.pos.z - w.z;
          if (dx * dx + dz * dz < 144) c++;
        }
        if (c > bestN) { bestN = c; best = w; }
      }
      if (best) {
        ctx.flags.paused = true;
        cam.position.set(best.x + 13, best.y + 11, best.z + 13);
        cam.lookAt(best.x, best.y + 0.3, best.z);
        cam.updateMatrixWorld(true);
      }
      return { scrapTotal: scrap.length, nearWreck, wreckCount: wrecks.length, bestWreckScrap: bestN };
    }, t);
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, 'scen-scrap-loot.png'), fullPage: false });
    console.log(`[scrap-loot] ${JSON.stringify(r)}`);
  },

  // Worm-shelter (ACAH): verify the sandworm won't acquire a SHELTERED player +
  // disengages if they reach shelter. Inject a shelter zone over a teleported
  // player 40m from the worm (inside still-detection ~82m); sheltered → stays
  // patrol; remove the zone → acquires. Logic eval (state read), no screenshot.
  'worm-shelter': async (page) => {
    const r1 = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setTime(0.5);           // midday — no twilight breach/ambush confounds
      const worm = ctx.sandWorms?.list?.[0];
      if (!worm) return { noWorm: true };
      worm.state = 'patrol';
      const wx = worm.basePos.x, wz = worm.basePos.z;
      const px = wx + 40, pz = wz;          // 40m away — inside still-detection radius
      const gy = ctx.terrain.heightAt(px, pz);
      ctx.player.body.body.setTranslation({ x: px, y: gy + 1.0, z: pz }, true);
      ctx.shelter.zones.push({ cx: px, cy: gy + 1.0, cz: pz, hx: 6, hy: 6, hz: 6 });
      return { ok: true };
    });
    if (r1.noWorm) { console.log('[worm-shelter] SKIP — no worm in world'); return; }
    await page.waitForTimeout(2800);
    const sheltered = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const worm = ctx.sandWorms.list[0];
      const out = { state: worm.state, inShelter: ctx.player.inShelter };
      ctx.shelter.zones.pop();              // expose the player for phase 2
      return out;
    });
    await page.waitForTimeout(3200);
    const exposed = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const worm = ctx.sandWorms.list[0];
      return { state: worm.state, inShelter: ctx.player.inShelter };
    });
    const pass = sheltered.inShelter === true && sheltered.state === 'patrol'
      && exposed.inShelter === false && exposed.state !== 'patrol';
    console.log(`[worm-shelter] ${pass ? 'PASS' : 'FAIL'} sheltered=${JSON.stringify(sheltered)} exposed=${JSON.stringify(exposed)}`);
  },

  // WORM-MODEL studio (Campaign C12) — surfaces ctx.sandWorms.list[0] on the sand
  // in a clean head-at-+X pose + frames it for MODEL iteration (the M3 hero creature).
  // `--angle=head|side|3q`. Pauses the sim so the posed mesh holds. If no worm exists
  // at spawn, tries ctx.sandWorms.spawnAt/forceSpawn; SKIPs if it can't make one.
  'worm-model': async (page) => {
    const angle = argv.angle || 'head';
    // M12 ⓖ — lunge time for the strike/dive angles (default a visible MID-dive; --t=<0..1> to scan).
    const lungeT = argv.t !== undefined ? parseFloat(argv.t) : (angle === 'strike' ? 0.5 : 0.65);
    const r = await page.evaluate(({ ang, lt }) => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0; ctx.weather.cloudiness = 0.12;
      window.__game.setTime(0.42);                 // raking light — reads the body taper + ridges
      ctx.three.renderer.toneMappingExposure = 1.25;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      ctx.flags.paused = true;                      // freeze the tick so the posed mesh holds
      let worm = ctx.sandWorms?.list?.[0];
      if (!worm && ctx.sandWorms?.spawnAt) {        // best-effort spawn near the player
        const pp = ctx.player.body.body.translation();
        try { worm = ctx.sandWorms.spawnAt(pp.x + 80, pp.z); } catch { /* no-op */ }
      }
      if (!worm) return { found: false };
      const ax = worm.basePos.x, az = worm.basePos.z;
      const groundY = ctx.terrain.heightAt(ax, az);
      const rad = 10, halfLen = 60;                 // SANDWORM_MAX_RADIUS, SANDWORM_LENGTH/2
      // Surface + pose: body along +X, head at +X.
      worm.mesh.visible = true;
      worm.mesh.rotation.set(0, 0, 0);
      let meshes = 0; worm.mesh.traverse((o) => { if (o.isMesh) meshes++; });
      let diveInfo = null;   // M12 ⓖ — the real poseLunge numbers for the dive/strike angles
      if (ang === 'arc') {
        // Faithful LUNGE-PEAK pose — mirrors sandWorm.ts applyBodyBend + the lunge Y-curve at t=0.5:
        // PEAK=20, DEPTH=12.5, RAD=10 → basePos.y = ground − DEPTH/2 + PEAK = ground+13.75; bend amp 2.5;
        // tailSink = aboveGround + RAD*0.5 = 18.75. Confirms the C14 TAIL-BURIED read (tail under, front arcs).
        const aboveGround = 13.75, bendAmp = 2.5, tailSink = aboveGround + rad * 1.2;
        worm.mesh.position.set(ax, groundY + aboveGround, az);
        for (const child of worm.mesh.children) {
          if (child.userData._nomY === undefined) child.userData._nomY = child.position.y;
          const s = child.position.x / halfLen;
          const sBias = s - 0.15;
          const arch = Math.max(0, 1 - sBias * sBias) * bendAmp;
          const rear = Math.max(0, -s);
          child.position.y = child.userData._nomY + arch - rear * rear * tailSink;
        }
      } else if (ang === 'charge') {
        // C15 charge exposure: rides ground − MAX_RADIUS*CHARGE_SUBMERGE (0.42) so only the armored
        // back-ridge breaks the surface; the REAR tapers into the dune (mirrors applyBodyBend chargeDip).
        worm.mesh.position.set(ax, groundY - rad * 0.42, az);
        const chargeDip = rad * 1.0;
        for (const child of worm.mesh.children) {
          if (child.userData._nomY === undefined) child.userData._nomY = child.position.y;
          const s = child.position.x / halfLen;
          const rear = Math.max(0, -s);
          child.position.y = child.userData._nomY - rear * rear * chargeDip;
        }
      } else if (ang === 'dive' || ang === 'strike') {
        // M12 ⓖ — the REAL breach-and-dive lunge pose (applyLungePose + applyMeshTransform via
        // the poseLunge hook → no rig-vs-real drift). 'strike' = head reared (t=0.5), 'dive' = plunging (t=0.82).
        worm.yaw = 0;   // lie along +X so the broadside camera sees the breach/dive profile
        diveInfo = window.__game.poseLunge(lt);
      } else {
        worm.mesh.position.set(ax, groundY + rad * 0.55, az);
      }
      worm.mesh.updateMatrixWorld(true);
      const cam = ctx.three.camera;
      const headX = ax + halfLen;
      if (ang === 'arc') {                           // side-on lunge arc — tail buried + body arcing out
        cam.position.set(ax - halfLen * 0.05, groundY + rad * 2.4, az + halfLen * 1.5);
        cam.lookAt(ax - halfLen * 0.05, groundY + rad * 0.7, az);
      } else if (ang === 'charge') {                 // low 3q — the armored back-ridge breaking the surface
        cam.position.set(ax + halfLen * 0.55, groundY + rad * 1.1, az + halfLen * 0.65);
        cam.lookAt(ax, groundY + rad * 0.15, az);
      } else if (ang === 'dive' || ang === 'strike') {   // M12 ⓖ — full broadside (body in the sand, head rearing/diving)
        cam.position.set(ax + halfLen * 0.05, groundY + rad * 4.0, az + halfLen * 2.0);
        cam.lookAt(ax + halfLen * 0.05, groundY + rad * 0.8, az);
      } else if (ang === 'head') {                   // close 3/4 on the maw + front body
        cam.position.set(headX + rad * 2.0, groundY + rad * 1.5, az + rad * 2.4);
        cam.lookAt(headX - rad * 0.8, groundY + rad * 0.7, az);
      } else if (ang === 'side') {                   // full 120m silhouette broadside
        cam.position.set(ax + halfLen * 0.1, groundY + rad * 3.4, az + halfLen * 1.6);
        cam.lookAt(ax, groundY + rad * 0.4, az);
      } else {                                       // 3q — head-led three-quarter of the whole body
        cam.position.set(ax + halfLen * 0.8, groundY + rad * 2.4, az + halfLen * 1.0);
        cam.lookAt(ax + halfLen * 0.15, groundY + rad * 0.4, az);
      }
      cam.updateMatrixWorld(true);
      let DirCtor = null, HemiCtor = null;
      ctx.three.scene.traverse((o) => { if (o.isDirectionalLight && !DirCtor) DirCtor = o.constructor; if (o.isHemisphereLight && !HemiCtor) HemiCtor = o.constructor; });
      let key = ctx.three.scene.getObjectByName('__wormKey');
      if (!key && DirCtor) { key = new DirCtor(); key.name = '__wormKey'; key.intensity = 2.1; key.color.set(0xfff2e0); ctx.three.scene.add(key.target); ctx.three.scene.add(key); }
      if (key) { key.position.set(cam.position.x + rad, cam.position.y + 24, cam.position.z + 12); key.target.position.set(ax + halfLen * 0.4, groundY, az); key.target.updateMatrixWorld(true); }
      if (!ctx.three.scene.getObjectByName('__wormFill') && HemiCtor) { const fill = new HemiCtor(0xbfccdd, 0x6b5840, 0.7); fill.name = '__wormFill'; ctx.three.scene.add(fill); }
      return { found: true, meshes, angle: ang, halfLen, diveInfo };
    }, { ang: angle, lt: lungeT });
    await page.waitForTimeout(340);
    if (!r.found) { console.log('[worm-model] SKIP — no worm in world'); return; }
    await page.screenshot({ path: join(OUT, `scen-worm-${angle}.png`), fullPage: false });
    console.log(`[worm-model] ${JSON.stringify(r)}`);
  },

  // Dev-panel (ACAD): open the dev item-spawner panel + click an item, verify
  // it renders + adds to inventory.
  'dev-panel': async (page) => {
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.flags.devMode = true;
      const badge = document.getElementById('dev-mode-badge');
      badge?.classList.add('visible');
      badge?.click();   // toggle the panel open
    });
    await page.waitForTimeout(450);
    await page.screenshot({ path: join(OUT, 'scen-dev-panel.png'), fullPage: false });
    const res = await page.evaluate(() => {
      const inv = window.__game.ctx.inventory;
      const total = () => inv.slots.concat(inv.backpack).reduce((n, s) => n + (s.item ? s.count : 0), 0);
      const before = total();
      // click the LAST item button (likely pulse_rifle — unlikely already in the loadout)
      const btns = document.querySelectorAll('.dev-item-btn');
      btns[btns.length - 1]?.click();
      return { itemCount: btns.length, totalBefore: before, totalAfter: total() };
    });
    console.log(`[dev-panel] items=${res.itemCount} invTotal ${res.totalBefore}→${res.totalAfter}`);
  },

  // Pulse-test (ACAC): smoke-test the pulse rifle's auto-fire + self-recharging
  // energy cell. Holds LMB (mouseHeld) for ~1.2s → the cell should drain; then
  // releases + waits → it should recharge. Numeric (no screenshot).
  'pulse-test': async (page) => {
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.input.controls.isLocked = true; ctx.flags.paused = false; ctx.flags.thirdPerson = false;
      const inv = ctx.inventory;
      inv.slots[0].item = 'pulse_rifle'; inv.slots[0].count = 1; inv.slots[0].meta = undefined;
      inv.selectedIdx = 0;
    });
    await page.waitForTimeout(350);   // updateHeld inits the cell
    const full = await page.evaluate(() => window.__game.ctx.inventory.slots[0].meta?.ammoRemaining ?? -1);
    const inp = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.input.mouseHeld.add(0);     // hold LMB
      return { hasHeld: ctx.input.mouseHeld.has(0), locked: ctx.input.controls.isLocked, hasSpec: !!window.__game.ctx };
    });
    // NOTE: the headless harness runs the game clock in slow-motion (dt clamped,
    // low fps) so GAME-time passes ~5x slower than wall-clock — wait long.
    const traj = [];
    for (let i = 0; i < 8; i++) {
      await page.waitForTimeout(900);
      traj.push(await page.evaluate(() => {
        const ctx = window.__game.ctx;
        return +(ctx.inventory.slots[0].meta?.ammoRemaining ?? -1).toFixed(1) + (ctx.input.mouseHeld.has(0) ? '' : '!');
      }));
    }
    await page.evaluate(() => window.__game.ctx.input.mouseHeld.delete(0)); // release
    await page.waitForTimeout(9000);
    const afterRecharge = await page.evaluate(() => +(window.__game.ctx.inventory.slots[0].meta?.ammoRemaining ?? -1).toFixed(1));
    // (Headless runs the game clock slow, so the cell drains/recharges in
    // slow-motion vs wall-clock — the trajectory should DROP while held + return
    // to full after release.)
    console.log(`[pulse-test] cellFull=${full} input=${JSON.stringify(inp)} hold-traj=[${traj.join(',')}] afterRecharge=${afterRecharge}`);
  },

  // Sky (ACAB, Cycle 6): sweep cloud cover × time-of-day, aim the camera up at
  // the dome, and screenshot — verifies the procedural cloud layer (clear →
  // partly → overcast) and that clouds occlude stars at night. Headless.
  'sky': async (page) => {
    // [label, cloudiness, dayTime, pitch]
    const shots = [
      ['clear-noon', 0.0, 0.5, 0.55],
      ['partly-noon', 0.45, 0.5, 0.55],
      ['overcast-noon', 0.9, 0.5, 0.55],
      ['partly-dusk', 0.5, 0.72, 0.32],
      ['clear-night', 0.0, 0.95, 0.55],
      ['overcast-night', 0.9, 0.95, 0.55],
      // Ground-level: see the overcast LIGHTING flatten on terrain (vs clear).
      ['clear-noon-ground', 0.0, 0.5, -0.12],
      ['overcast-noon-ground', 0.92, 0.5, -0.12],
    ];
    for (const [label, cloud, time, pitch] of shots) {
      await page.evaluate(({ cloud, time }) => {
        const ctx = window.__game.ctx;
        ctx.weather.intensity = 0;
        window.__game.setCloudiness(cloud);
        window.__game.setTime(time);
        ctx.three.renderer.setSize(900, 700, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 900 / 700; cam.updateProjectionMatrix(); }
        ctx.flags.thirdPerson = false;
        if (ctx.player.rig) ctx.player.rig.group.visible = false;
      }, { cloud, time });
      await page.waitForTimeout(380);
      await page.evaluate((pitch) => {
        const cam = window.__game.ctx.three.camera;
        cam.rotation.set(pitch, 0.6, 0);
        cam.updateMatrixWorld(true);
      }, pitch);
      await page.waitForTimeout(220);
      const path = join(OUT, `scen-sky-${label}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[sky] ${label} → ${path}`);
    }
    // Storm telegraph: trigger a storm, let the 'building' state ramp the sky to
    // ominous overcast (before the dust wall), capture it.
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      window.__game.setCloudiness(-1);      // release the hold → auto (storm forces overcast)
      window.__game.setTime(0.5);
      window.__game.triggerStorm();
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
    });
    await page.waitForTimeout(4500);        // let cloudiness ramp during 'building'
    await page.evaluate(() => {
      const cam = window.__game.ctx.three.camera;
      cam.rotation.set(0.28, 0.6, 0); cam.updateMatrixWorld(true);
    });
    await page.waitForTimeout(300);
    const st = await page.evaluate(() => {
      const w = window.__game.ctx.weather;
      return { state: w.state, intensity: +w.intensity.toFixed(2), cloud: +w.cloudiness.toFixed(2) };
    });
    await page.screenshot({ path: join(OUT, 'scen-sky-storm-build.png'), fullPage: false });
    console.log(`[sky] storm-build → scen-sky-storm-build.png ${JSON.stringify(st)}`);
  },

  // FP-item (ACAA): equip an item in FIRST person and screenshot the REAL
  // viewmodel as the player sees it — this exercises the two-pass depth-cleared
  // viewmodel render (loop.ts), the only path where the see-through-rings bug
  // appears (the item-studio uses default-material meshes that already
  // depth-sort, so it can't reproduce it). --item=<id> OR --items=a,b,c.
  'fp-item': async (page) => {
    const items = String(argv.items || argv.item || 'scrap_bar').split(',').map((s) => s.trim());
    for (const item of items) {
      await page.evaluate(({ item, night }) => {
        const ctx = window.__game.ctx;
        ctx.weather.intensity = 0;
        window.__game.setTime(night ? 0.96 : 0.5);   // --night → dark, to see emitted light
        ctx.three.renderer.setSize(900, 900, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
        ctx.flags.thirdPerson = false;        // FIRST person → FP viewmodel shows
        ctx.flags.started = true; ctx.flags.paused = false;
        // Hide the rig so the camera-at-head hood doesn't fill the frame in
        // this forced FP state (normal play keeps the head below the eyeline).
        if (ctx.player.rig) ctx.player.rig.group.visible = false;
        const inv = ctx.inventory;
        inv.slots[0].item = item; inv.slots[0].count = 1;
        // Light the torch / flashlight so their lit-only effects show.
        inv.slots[0].meta = item === 'torch' ? { lit: true, burnRemaining: 1 }
          : item === 'flashlight' ? { lit: true, fuelLevel: 1 } : undefined;
        inv.selectedIdx = 0;
      }, { item, night: !!argv.night });
      await page.waitForTimeout(450);         // let updateViewModel swap + camera settle to FP
      // Aim the FP camera UP at clean sky (FP sync only sets position, not
      // rotation) + re-assert FP/rig-hidden, so the item frames against sky.
      const lookPitch = argv.pitch !== undefined ? Number(argv.pitch) : 0.16;
      const dbg = await page.evaluate((pitch) => {
        const ctx = window.__game.ctx;
        ctx.flags.thirdPerson = false;
        if (ctx.player.rig) ctx.player.rig.group.visible = false;
        const cam = ctx.three.camera;
        cam.rotation.set(pitch, 2.2, 0);       // slight up + yaw away; --pitch=<rad> for look-down light tests
        cam.updateMatrixWorld(true);
        const vm = ctx.player.viewModel;
        const V = cam.position.constructor;
        vm.group.updateWorldMatrix(true, true);
        const ip = vm.itemRoot.getWorldPosition(new V());
        const cp = cam.position;
        return {
          tp: ctx.flags.thirdPerson, vmVisible: vm.group.visible, item: ctx.inventory.slots[0].item,
          sceneKids: vm.scene.children.length, groupInScene: vm.group.parent === vm.scene,
          itemMeshes: vm.itemRoot.children.length,
          cam: [cp.x.toFixed(1), cp.y.toFixed(1), cp.z.toFixed(1)],
          itemPos: [ip.x.toFixed(1), ip.y.toFixed(1), ip.z.toFixed(1)],
        };
      }, lookPitch);
      await page.waitForTimeout(260);
      const path = join(OUT, `scen-fp-${item}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[fp-item] ${item} → ${path}  ${JSON.stringify(dbg)}`);
    }
  },

  // Item-studio (ACY): build the item's makeViewModel mesh in ISOLATION (no rig
  // / world), suspended high against the sky gradient + lit for form, framed per
  // angle. The clean multi-angle view the deep item-detail pass iterates against
  // (the held-item shot buries small items behind the rig torso). --item=<id>,
  // --angles=front,3q,left,top (default). One PNG per angle.
  'item-studio': async (page) => {
    // --item=<id> OR --items=a,b,c (multiple items in one server boot).
    const items = String(argv.items || argv.item || 'machete').split(',').map((s) => s.trim());
    const angles = String(argv.angles || 'front,3q,left,top').split(',').map((s) => s.trim());
    for (const item of items) {
      for (const angle of angles) {
        const res = await page.evaluate(({ item, angle }) => window.__game.itemStudio(item, angle), { item, angle });
        await page.waitForTimeout(200);
        const path = join(OUT, `scen-item-${item}-${angle}.png`);
        await page.screenshot({ path, fullPage: false });
        console.log(`[item-studio] ${item} ${angle} → ${path}  ${JSON.stringify(res)}`);
      }
    }
  },

  // ACAV — panel-studio: isolated single salvage-panel framer for the shape +
  // interior visual-iteration loop. --shapes=rect,square,circle --kinds=fuselage
  // --archetype=electrical --state=open|closed --angles=front,3q,side,eye
  // --scale=1. Sweep mode (--sweep) loops shapes × a representative archetype set
  // × open/closed at 3q (one-pass /visual-triage fodder).
  'panel-studio': async (page) => {
    const sweep = argv.sweep !== undefined;
    const allArch = argv.allarch !== undefined;
    const shapes = String(argv.shapes || argv.shape || (sweep ? 'rect,square,circle' : 'rect')).split(',').map((s) => s.trim());
    const archetypes = (allArch)
      ? ['electrical', 'plumbing', 'avionics', 'mechanical', 'junction']
      : (argv.archetypes || argv.archetype)
        ? String(argv.archetypes || argv.archetype).split(',').map((s) => s.trim())
        : [undefined];
    const angles = String(argv.angles || (sweep || allArch ? '3q' : 'front,3q,side')).split(',').map((s) => s.trim());
    const states = argv.state ? [String(argv.state)] : (argv.open !== undefined ? ['open'] : (sweep ? ['closed', 'open'] : (allArch ? ['open'] : ['closed'])));
    const scale = Number(argv.scale || 1);
    const occlude = argv.occlude !== undefined;   // ACAX — drop a hull slab in front (stencil-portal spike)
    for (const shape of shapes) {
      for (const archetype of archetypes) {
        for (const st of states) {
          for (const angle of angles) {
            const res = await page.evaluate(
              ({ shape, archetype, st, angle, scale, occlude }) =>
                window.__game.spawnPanelStudio({ shape, archetype, scale, open: st === 'open', angle, occlude }),
              { shape, archetype, st, angle, scale, occlude },
            );
            await page.waitForTimeout(220);
            const tag = (archetype ? `${shape}-${archetype}` : `${shape}-fuselage`) + (occlude ? '-occ' : '');
            const path = join(OUT, `scen-panelstudio-${tag}-${st}-${angle}.png`);
            await page.screenshot({ path, fullPage: false });
            console.log(`[panel-studio] ${tag}/${st}/${angle} → ${path}  ${JSON.stringify(res)}`);
          }
        }
      }
    }
  },

  // ACAX — WYSIWYG salvage audit. For every registered panel, the number of VISIBLE
  // interior components must EQUAL salvageRemaining (so what you see is what you can
  // salvage). Boots the real world + iterates ctx.salvageables.list.
  'salvage-audit': async (page) => {
    const r = await page.evaluate(() => {
      const list = window.__game.ctx.salvageables.list;
      let mismatches = 0; const samples = []; const byCond = {};
      for (const s of list) {
        const comps = s.panel.userData.panelComponents ?? [];
        const visible = comps.filter((c) => c.visible).length;
        const match = visible === s.salvageRemaining;
        if (!match) mismatches++;
        byCond[s.condition] = byCond[s.condition] || { n: 0, vis: 0, rem: 0 };
        byCond[s.condition].n++; byCond[s.condition].vis += visible; byCond[s.condition].rem += s.salvageRemaining;
        if (!match && samples.length < 8) samples.push({ cond: s.condition, visible, remaining: s.salvageRemaining });
      }
      return { total: list.length, mismatches, byCond, samples };
    });
    console.log('[salvage-audit] ' + JSON.stringify(r));
    console.log(r.mismatches === 0
      ? `[salvage-audit] PASS — visible == salvageable across all ${r.total} panels`
      : `[salvage-audit] FAIL — ${r.mismatches}/${r.total} mismatches`);
  },

  // ACAX — door pop-off smoke test. Pops a salvage-panel door (physics), lets the
  // LIVE loop run, then asserts the door detached + FELL + reached a finite resting
  // pose (no NaN / explosion / fall-through). The "satisfying" feel is walk-test-owed.
  'door-pop': async (page) => {
    const before = await page.evaluate((seed) => window.__game.popTestDoor(seed), Number(argv.seed || 1337));
    console.log('[door-pop] pop: ' + JSON.stringify(before));
    if (!before.ok) { console.log('[door-pop] FAIL — door did not pop'); return; }
    await page.waitForTimeout(2800);   // live loop steps physics → door falls + settles
    const after = await page.evaluate(() => window.__game.panelDebris());
    const d = after.doors[0];
    const finite = !!d && Number.isFinite(d.y);
    const fell = finite && d.y < before.spawnY - 0.3;
    console.log(`[door-pop] spawnY=${before.spawnY} restY=${d ? d.y.toFixed(2) : 'NONE'} fell=${fell} finite=${finite} sleeping=${d ? d.sleeping : '?'} count=${after.count}`);
    console.log(fell && finite ? '[door-pop] PASS — door detached + fell with physics to a finite pose' : '[door-pop] FAIL');
  },

  // Speeder-FX (ACW C7/C8): drive the (unmounted) bike LIVE for ~0.6s so the
  // dust trail builds + the engine glow ramps with speed, then PAUSE (freezes
  // the dust cloud mid-air + holds the glow) and free-camera a 3/4-behind shot
  // showing the trail + the hot nozzle. Re-inject forward velocity each tick so
  // the unmounted damping doesn't bleed the speed (→ no dust).
  'speeder-fx': async (page) => {
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.weather.intensity = 0;
      window.__game.setTime(0.5);
      ctx.three.renderer.toneMappingExposure = 1.05;
      ctx.three.renderer.setSize(1000, 720, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 1000 / 720; cam.updateProjectionMatrix(); }
      const s = ctx.speeder;
      const bx = 8, bz = 0, by = ctx.terrain.heightAt(bx, bz) + 1.2;
      s.body.setTranslation({ x: bx, y: by, z: bz }, true);   // yaw 0 → forward = -Z
      s.body.setRotation({ x: 0, y: 0, z: 0, w: 1 }, true);
      s.mounted = false;
    });
    // Drive forward (-Z) for several ticks; re-inject velocity each step.
    for (let i = 0; i < 11; i++) {
      await page.evaluate(() => {
        const s = window.__game.ctx.speeder;
        s.body.setLinvel({ x: 0, y: s.body.linvel().y, z: -12 }, true);
      });
      await page.waitForTimeout(55);
    }
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = true;                 // freeze dust cloud + glow + camera
      const s = ctx.speeder;
      const p = s.body.translation();
      const cam = ctx.three.camera;
      // Bike drove -Z, so the dust trails behind it toward +Z. View 3/4
      // behind-right so the trail recedes into frame + the nozzle glow shows.
      cam.position.set(p.x + 1.8, p.y + 1.1, p.z + 3.6);
      cam.lookAt(p.x, p.y + 0.05, p.z + 0.6);
      cam.updateMatrixWorld(true);
      // ACAS A2 — static-merge safety check: every interactive/animated ref must
      // still resolve + sit in the speeder graph; count meshes under the group.
      const inGraph = (o) => { let n = o; while (n) { if (n === s.group) return true; n = n.parent; } return false; };
      let meshCount = 0; s.group.traverse((o) => { if (o.isMesh) meshCount++; });
      const merge = {
        discOk: !!(s.headlampDisc && s.headlampDisc.isMesh && inGraph(s.headlampDisc)),
        towBarOk: !!(s.towBar && s.towBar.isMesh && inGraph(s.towBar)),
        seatOk: !!(s.seat && s.seat.userData.interactType === 'mount' && inGraph(s.seat)),
        headlampOk: !!(s.headlamp && s.headlamp.isSpotLight && inGraph(s.headlamp)),
        speederMeshes: meshCount,
      };
      return { speed: +s.speed.toFixed(1), bikeZ: +p.z.toFixed(1), merge };
    });
    console.log(`[speeder-fx] final speed=${info.speed} bikeZ=${info.bikeZ} merge=${JSON.stringify(info.merge)}`);
    await page.waitForTimeout(250);
    const path = join(OUT, 'scen-speeder-fx.png');
    await page.screenshot({ path, fullPage: false });
    console.log(`[rig-shot] saved ${path}`);
  },

  // Companion (ACW B6 ASSESS): the companion is already a full proc-character
  // (icosahedron carapace + 5 radial legs + gait). Frame it close from two
  // angles + a walking-pose leg lift so we can judge whether it needs polish or
  // already reads. Paused free camera.
  'companion': async (page) => {
    const shots = [
      { tag: '3q', off: [0.55, 0.40, 0.62], walk: false },
      { tag: 'side', off: [0.0, 0.30, 0.78], walk: false },
      { tag: 'walk', off: [0.5, 0.34, 0.6], walk: true },
    ];
    for (const sh of shots) {
      await page.evaluate((sh) => {
        const ctx = window.__game.ctx;
        ctx.weather.intensity = 0;
        window.__game.setTime(0.5);
        ctx.three.renderer.toneMappingExposure = 1.1;
        ctx.three.renderer.setSize(900, 900, false);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera) { cam.aspect = 1; cam.updateProjectionMatrix(); }
        const c = ctx.companion;
        if (!c) return;
        const cx = c.pos.x, cz = c.pos.z;
        const cy = ctx.terrain.heightAt(cx, cz);
        if (sh.walk) {
          // Pose a mid-walk leg lift so leg taper/segmenting is visible.
          const REST = 0.6, LIFT = 0.55;
          for (let i = 0; i < c.legs.length; i++) {
            c.legs[i].visible = true;
            const ph = (i / 5) * Math.PI * 2;
            c.hips[i].rotation.z = -REST + Math.max(0, Math.sin(ph)) * LIFT;
          }
        }
        ctx.flags.paused = true;
        c.group.updateMatrixWorld(true);
        cam.position.set(cx + sh.off[0], cy + sh.off[1], cz + sh.off[2]);
        cam.lookAt(cx, cy + 0.12, cz);
        cam.updateMatrixWorld(true);
      }, sh);
      await page.waitForTimeout(250);
      const path = join(OUT, `scen-companion-${sh.tag}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[companion] ${sh.tag} → ${path}`);
    }
  },

  // Aim-twist (ACN dynamic): drive the 3P camera yaw over rAF ticks and sample
  // rig._aimTwist to PROVE it responds to turn RATE (not a constant). Then two
  // paused posed shots (resting bias vs full lead) for the visual range. The
  // page is visible Playwright so rAF actually ticks (unlike the hidden preview).
  'aim-twist': async (page) => {
    // Drive + sample from NODE (page.waitForTimeout), letting the game's own
    // tick loop run. Must NOT use in-page requestAnimationFrame: the Playwright
    // page is `hidden`, so rAF is throttled to ~0 (the game survives via its
    // setTimeout fallback in loop.ts — D146). Shrink canvas for fast ticks.
    await page.evaluate(() => window.__game.ctx.three.renderer.setSize(64, 64, false));
    const setYaw = (y) => page.evaluate((yy) => {
      const c = window.__game.ctx.three.camera;
      c.quaternion.setFromEuler(new (c.rotation.constructor)(-0.12, yy, 0, 'YXZ'));
      c.updateMatrixWorld(true);
    }, y);
    const readAim = () => page.evaluate(() => +window.__game.ctx.player.rig._aimTwist.toFixed(3));
    const samples = [];
    // steady → relaxes to the resting bias
    await setYaw(0); await page.waitForTimeout(1200);
    samples.push({ phase: 'steady', aim: await readAim() });
    // turn LEFT — ramp yaw + in small steps so the heading keeps changing
    // (continuous turn rate); read promptly so the lead is fresh.
    let y = 0;
    for (let i = 0; i < 14; i++) { y += 0.10; await setYaw(y); await page.waitForTimeout(70); }
    samples.push({ phase: 'turn+', aim: await readAim() });
    // turn RIGHT — ramp yaw back the other way
    for (let i = 0; i < 14; i++) { y -= 0.10; await setYaw(y); await page.waitForTimeout(70); }
    samples.push({ phase: 'turn-', aim: await readAim() });
    // stop → relaxes back toward the bias
    await page.waitForTimeout(1500);
    samples.push({ phase: 'relax', aim: await readAim() });
    console.log('[aim-twist] dynamic response: ' + JSON.stringify(samples));
    for (const [tag, val] of [['rest', 0.18], ['lead', 0.5]]) {
      await page.evaluate((v) => {
        const ctx = window.__game.ctx;
        ctx.three.renderer.setSize(900, 1100, false); // restore from the 48×48 numeric-loop size
        ctx.flags.paused = true;                       // freeze so our pose survives the shot
        const rig = ctx.player.rig;
        rig.shoulders[1].rotation.y = v;
        rig.group.updateMatrixWorld(true);
        const cam = ctx.three.camera; const V = cam.position.constructor;
        if (cam.isPerspectiveCamera) { cam.aspect = 900 / 1100; cam.updateProjectionMatrix(); }
        const hp = rig.headGroup.getWorldPosition(new V());
        cam.position.set(hp.x + 1.5, hp.y + 0.05, hp.z + 1.0); // front-ish, slightly above
        cam.lookAt(hp.x, hp.y - 0.30, hp.z);
        cam.updateMatrixWorld(true);
      }, val);
      await page.waitForTimeout(300);
      const path = join(OUT, `scen-aim-twist-${tag}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[rig-shot] saved ${path}`);
    }
  },

  // Rifle (ACL amban_rifle): equip in hotbar slot 0 (1P viewmodel), prove the
  // ranged FIRE path decrements ammo + the R-reload refills from scrap_bullet
  // stacks, then a 1P viewmodel screenshot. State-based (functional) verify —
  // reliable without trying to catch a muzzle flash in a slow software render.
  'rifle': async (page) => {
    // Equip + state setup. Node-driven press re-injection below (NOT in-page rAF
    // — the page is hidden so rAF is throttled, and a single-tick input inject
    // races endInputFrame which clears pressed/mousePressed each tick — D146).
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const inv = ctx.inventory;
      inv.slots[0].item = 'amban_rifle'; inv.slots[0].count = 1; inv.slots[0].meta = { ammoRemaining: 3 };
      inv.slots[1].item = 'scrap_bullet'; inv.slots[1].count = 12; inv.slots[1].meta = undefined;
      inv.selectedIdx = 0;
      ctx.three.renderer.setSize(64, 64, false);     // fast ticks for the fire/reload sim
    });
    const ammo = () => page.evaluate(() => window.__game.ctx.inventory.slots[0].meta.ammoRemaining);
    const bullets = () => page.evaluate(() => { const s = window.__game.ctx.inventory.slots[1]; return s.item === 'scrap_bullet' ? s.count : 0; });
    const ammo0 = await ammo();
    // FIRE — re-inject LMB each step until ammo drops (cooldown then blocks further shots).
    let ammoAfterShot = ammo0;
    for (let i = 0; i < 14; i++) {
      await page.evaluate(() => window.__game.ctx.input.mousePressed.add(0));
      await page.waitForTimeout(110);
      ammoAfterShot = await ammo();
      if (ammoAfterShot < ammo0) break;
    }
    // RELOAD — re-inject R until ammo refills from the scrap_bullet stack.
    let ammoAfterReload = ammoAfterShot;
    for (let i = 0; i < 14; i++) {
      await page.evaluate(() => window.__game.ctx.input.pressed.add('KeyR'));
      await page.waitForTimeout(110);
      ammoAfterReload = await ammo();
      if (ammoAfterReload > ammoAfterShot) break;
    }
    const result = { equipped: 'amban_rifle', ammo0, ammoAfterShot, ammoAfterReload, bulletsLeft: await bullets() };
    console.log('[rifle] ' + JSON.stringify(result));
    // 1P viewmodel screenshot (restore size).
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.three.renderer.setSize(900, 1100, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 1100; cam.updateProjectionMatrix(); }
    });
    await page.waitForTimeout(500);
    const path = join(OUT, 'scen-rifle-viewmodel.png');
    await page.screenshot({ path, fullPage: false });
    console.log(`[rig-shot] saved ${path}`);
  },

  // Night-sky (ACO): set deep night, let lighting settle sunHeight, confirm the
  // ambient tan dust drift is hidden (gated on sun height) + capture the sky so
  // the stars read. Camera pitched up toward the star field.
  'night-sky': async (page) => {
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.three.renderer.setSize(900, 1100, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 1100; cam.updateProjectionMatrix(); }
      window.__game.setTime(0.0);            // midnight
      return { dayTime: ctx.time.dayTime };
    });
    await page.waitForTimeout(900);          // let lighting.update settle sunHeight + dust fade
    const result = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const cam = ctx.three.camera;
      // pitch the camera up ~35° to frame the star field
      cam.quaternion.setFromEuler(new (cam.rotation.constructor)(0.6, 0, 0, 'YXZ'));
      cam.updateMatrixWorld(true);
      return {
        sunHeight: +ctx.time.sunHeight.toFixed(3),
        dustVisible: ctx.ambientDust ? ctx.ambientDust.particles.visible : null,
        dustOpacity: ctx.ambientDust ? +ctx.ambientDust.particleMat.opacity.toFixed(4) : null,
      };
    });
    console.log('[night-sky] ' + JSON.stringify(result));
    await page.waitForTimeout(300);
    const path = join(OUT, 'scen-night-sky.png');
    await page.screenshot({ path, fullPage: false });
    console.log(`[rig-shot] saved ${path}`);
  },

  // Panels (ACP; ACY-hardened): enumerate salvage panels, force every door
  // open, then (1) run a HEADLESS BURY ASSERTION — for each panel, raycast
  // inward along its own outward axis against its wreck root; if the nearest
  // hit isn't the panel itself, hull occludes it (buried) → FAIL — and (2)
  // screenshot a sample from the front. Each harness boot rolls a fresh random
  // seed, so re-running sweeps seeds. Static (pause after the door-lerp).
  'panels': async (page) => {
    await page.evaluate(() => { window.__game.ctx.three.renderer.setSize(900, 1100, false); window.__game.setTime(0.42); });
    const list = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.salvageables.list.forEach((s) => {
        s.panel.userData.panelOpened = true;
        s.panel.userData.panelDoorTarget = 2.2;   // ~126° — clearly open
      });
      return { count: ctx.salvageables.list.length, seed: ctx.seed ?? '?' };
    });
    console.log(`[panels] seed=${list.seed} count=${list.count}`);
    await page.waitForTimeout(1400);             // let updatePanelDoors lerp them open

    // ── Bury assertion (runs in TS via __game.panelBuryAudit — THREE there). ──
    const audit = await page.evaluate(() => window.__game.panelBuryAudit());
    console.log(`[panels] BURY-AUDIT seed=${list.seed} pass=${audit.pass}/${audit.tested} fails=${audit.failCount} ${audit.failCount ? JSON.stringify(audit.fails) : 'ALL CLEAR'}`);
    // ACBA — surface-scoped terrain audit (corner-aware; interiors excluded).
    const t = audit.terrain;
    if (t) console.log(`[panels] TERRAIN-AUDIT seed=${list.seed} pass=${t.pass}/${t.tested} fails=${t.failCount} ${t.failCount ? JSON.stringify(t.fails) : 'ALL CLEAR'}`);

    // ── Screenshots: sample panels from the front (all kinds + first few). ──
    const targets = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const V = ctx.three.camera.position.constructor;
      const Q = ctx.three.camera.quaternion.constructor;
      const items = ctx.salvageables.list.map((s, idx) => {
        const wp = s.panel.getWorldPosition(new V());
        const outward = new V(0, 0, 1).applyQuaternion(s.panel.getWorldQuaternion(new Q()));
        return { idx, kind: s.kind || s.wreckKind || '?', x: wp.x, y: wp.y, z: wp.z, ox: outward.x, oy: outward.y, oz: outward.z };
      });
      const seen = new Set(); const pick = [];
      for (const it of items) { const k = it.kind; if (!seen.has(k)) { seen.add(k); pick.push(it); } if (pick.length >= 12) break; }
      ctx.flags.paused = true;
      return pick;
    });
    for (let i = 0; i < targets.length; i++) {
      const t = targets[i];
      await page.evaluate((t) => {
        const ctx = window.__game.ctx;
        const cam = ctx.three.camera;
        cam.position.set(t.x + t.ox * 1.7, t.y + 0.35, t.z + t.oz * 1.7);
        cam.lookAt(t.x, t.y, t.z);
        cam.updateMatrixWorld(true);
      }, t);
      await page.waitForTimeout(200);
      const path = join(OUT, `scen-panel-${String(i).padStart(2, '0')}-${t.kind}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[panels] shot ${i}: kind=${t.kind} → ${path}`);
    }
  },

  // Stake (ACQ): equip + place a stake_kit, then frame the deployed stake to
  // confirm the ACQ fixes — no sand mound, rope-loop seated near the top
  // touching the shaft. Static (pause after place).
  'stake': async (page) => {
    await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.inventory.slots[0].item = 'stake_kit'; ctx.inventory.slots[0].count = 1;
      ctx.inventory.selectedIdx = 0;
      window.__game.setTime(0.42);
    });
    // Place via the LMB 'place' wield path (re-inject until a stake exists).
    let placed = false;
    for (let i = 0; i < 12 && !placed; i++) {
      placed = await page.evaluate(() => {
        window.__game.ctx.input.mousePressed.add(0);
        return window.__game.ctx.stakes.list.length > 0;
      });
      await page.waitForTimeout(120);
    }
    const info = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      const s = ctx.stakes.list[0];
      if (!s) return { placed: false };
      ctx.three.renderer.setSize(900, 1100, false);
      const cam = ctx.three.camera;
      if (cam.isPerspectiveCamera) { cam.aspect = 900 / 1100; cam.updateProjectionMatrix(); }
      ctx.flags.paused = true;
      cam.position.set(s.pos.x + 0.7, s.pos.y + 0.75, s.pos.z + 0.7); // close 3/4 from above
      cam.lookAt(s.pos.x, s.pos.y + 0.45, s.pos.z);
      cam.updateMatrixWorld(true);
      return { placed: true, pos: [+s.pos.x.toFixed(1), +s.pos.z.toFixed(1)] };
    });
    console.log('[stake] ' + JSON.stringify(info));
    await page.waitForTimeout(300);
    const path = join(OUT, 'scen-stake.png');
    await page.screenshot({ path, fullPage: false });
    console.log(`[rig-shot] saved ${path}`);
  },

  // Shrew-kill (ACR): equip the rifle, aim point-blank at a shrew, fire until
  // it dies, then take the meat. Verifies the combat→damageShrew→dead→'take'→
  // raw_shrew_meat chain via state (aim+cook loop still needs foreground feel).
  'shrew-kill': async (page) => {
    // Combat-aim on a small fleeing critter isn't reliably scriptable headlessly
    // (the shrew flees + its AI moves it each tick out of the ray). The
    // combat→damageShrew branch is a tsc-clean 1:1 mirror of the proven lizard
    // path; here we verify the NEW take→meat→lootShrew chain reliably by placing
    // a dead-tagged shrew directly in the crosshair (replicating
    // applyDeadShrewPose), then taking it via the real interaction path.
    const setup = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.three.renderer.setSize(64, 64, false);
      const s = ctx.shrews.list[0];
      if (!s) return { err: 'no shrew' };
      const cam = ctx.three.camera;
      const fwd = new (cam.position.constructor)();
      cam.getWorldDirection(fwd); fwd.y = 0; fwd.normalize();
      // Place the shrew 1.2m straight ahead of the camera (already in the
      // crosshair → the interaction raycast hits without any aim fight).
      const sx = cam.position.x + fwd.x * 1.2, sz = cam.position.z + fwd.z * 1.2;
      const gy = ctx.terrain.heightAt(sx, sz);
      s.pos.set(sx, gy + 0.04, sz); s.mesh.position.copy(s.pos);
      s.body.setNextKinematicTranslation({ x: sx, y: gy + 0.04, z: sz });
      // Mark dead + retag (replicate applyDeadShrewPose).
      s.state = 'dead';
      s.mesh.rotation.z = Math.PI / 2;
      s.mesh.traverse((o) => { o.userData.interactType = 'take'; o.userData.interactId = s.id; o.userData.interactRegistry = 'shrews'; });
      return { shrewId: s.id, deadState: s.state };
    });
    // Take it — aim the camera DOWN at the ground-level dead shrew each frame
    // (a level forward ray would pass over its head) + re-inject E.
    let meat = 0; let hoverNoun = null;
    for (let i = 0; i < 16 && meat === 0; i++) {
      hoverNoun = await page.evaluate(() => {
        const ctx = window.__game.ctx;
        const s = ctx.shrews.list.find((x) => x.state === 'dead');
        if (s) { const cam = ctx.three.camera; cam.lookAt(s.pos.x, s.pos.y + 0.04, s.pos.z); cam.updateMatrixWorld(true); }
        ctx.input.pressed.add('KeyE');
        return ctx.inventory.hover ? ctx.inventory.hover.promptNoun : null;
      });
      await page.waitForTimeout(110);
      meat = await page.evaluate(() => { let n = 0; for (const sl of window.__game.ctx.inventory.slots) if (sl.item === 'raw_shrew_meat') n += sl.count; return n; });
    }
    const looted = await page.evaluate(() => !window.__game.ctx.shrews.list.some((x) => x.id === 1 || x.state === 'dead'));
    console.log('[shrew-kill] ' + JSON.stringify({ ...setup, hoverNoun, rawShrewMeat: meat, deadRemovedAfterTake: looted }));
  },

  // Footprints (ACO repro): walk → mount speeder → dismount → walk again, and
  // sample rig.stepCount each phase. If stepCount stops climbing after the
  // mount/dismount cycle, the gait (and thus footprint spawning) is wedged.
  // Driven from Node (keys persist; pressed cleared each tick → re-inject E).
  'footprints': async (page) => {
    await page.evaluate(() => { window.__game.ctx.three.renderer.setSize(64, 64, false); });
    const walk = async (label, ms) => {
      const before = await page.evaluate(() => {
        const c = window.__game.ctx;
        c.input.keys['KeyW'] = true;          // hold forward (keys persist; not cleared by endInputFrame)
        return { step: c.player.rig.stepCount, x: +c.player.body.body.translation().x.toFixed(2) };
      });
      await page.waitForTimeout(ms);
      const after = await page.evaluate(() => {
        const c = window.__game.ctx;
        c.input.keys['KeyW'] = false;
        return {
          step: c.player.rig.stepCount, x: +c.player.body.body.translation().x.toFixed(2),
          speedMag: +c.player.rig.speedMag.toFixed(2), state: c.player.rig.state,
        };
      });
      console.log(`[footprints] ${label}: stepCount ${before.step}→${after.step} (Δ${after.step - before.step}), moved ${(after.x - before.x).toFixed(2)}m, speedMag=${after.speedMag} state=${after.state}`);
      return after.step - before.step;
    };
    const dWalkA = await walk('walk-A (pre-mount)', 1600);
    // Teleport adjacent to the speeder so the mount (proximity-gated) succeeds.
    await page.evaluate(() => {
      const c = window.__game.ctx;
      const s = c.speeder;
      if (s) {
        const gy = c.terrain.heightAt(s.pos.x + 1.2, s.pos.z);
        c.player.body.body.setTranslation({ x: s.pos.x + 1.2, y: gy + 1.6, z: s.pos.z }, true);
      }
    });
    await page.waitForTimeout(150);
    // Mount: re-inject E until mounted (updateSpeeder reads pressed.has('KeyE')).
    let mounted = false;
    for (let i = 0; i < 12 && !mounted; i++) {
      mounted = await page.evaluate(() => {
        const c = window.__game.ctx;
        c.input.pressed.add('KeyE');
        return !!(c.speeder && c.speeder.mounted);
      });
      await page.waitForTimeout(110);
    }
    const distInfo = await page.evaluate(() => {
      const c = window.__game.ctx;
      const p = c.player.body.body.translation();
      const s = c.speeder;
      return { mounted: !!(s && s.mounted), dist: s ? +Math.hypot(p.x - s.pos.x, p.z - s.pos.z).toFixed(1) : null };
    });
    console.log(`[footprints] after mount attempts: ${JSON.stringify(distInfo)}`);
    await page.waitForTimeout(800); // ride a beat
    // Dismount.
    for (let i = 0; i < 12; i++) {
      const stillMounted = await page.evaluate(() => {
        const c = window.__game.ctx;
        c.input.pressed.add('KeyE');
        return !!(c.speeder && c.speeder.mounted);
      });
      await page.waitForTimeout(110);
      if (!stillMounted) break;
    }
    await page.waitForTimeout(300);
    const dWalkB = await walk('walk-B (post-dismount)', 1600);
    console.log(`[footprints] VERDICT: pre-mount Δstep=${dWalkA}, post-dismount Δstep=${dWalkB} → ${dWalkB > 0 ? 'footprints RESUME (no bug here)' : 'footprints WEDGED (bug confirmed)'}`);
  },

  // ROUND-4 glaze-body probe (ADDITIVE — the cockpit-glass-luma/-cells isolation probes read a
  //   pinned constant in this build: with everything else hidden + space env active, the glass sheet
  //   fills the frame and its body reads the ENV-IBL reflection floor, which swamps the emissive glaze
  //   floor knob → the probe can't see a glaze change. This probe measures the REAL shipped forward view
  //   (all geometry + space sky) and reads pane-BODY luma over three FIXED star-sparse rectangles (upper-
  //   left pane, upper-right pane, crown-band) so a glaze change IS visible + front/side/top PARITY is
  //   read where the player actually sees it. Prints the three body-luma values + their max deviation.
  //     node scripts/rig-shot.mjs --scenario=cockpit-glaze-body --port=5193
  'cockpit-glaze-body': async (page) => {
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      ctx.flags.thirdPerson = false;
      if (ctx.player.rig) ctx.player.rig.group.visible = false;
      if (ctx.player.viewModel && ctx.player.viewModel.group) ctx.player.viewModel.group.visible = false;
      try { ctx.weather.intensity = 0; ctx.weather.cloudiness = 0; } catch {}
      try { ctx.three.renderer.toneMappingExposure = 1.08; } catch {}
      g.startIntro(); g.jumpToBeat('cockpit'); g.setSkyIntroMode(1);
      try { if (ctx.dustMotes) ctx.dustMotes.particles.visible = false; } catch {}
      try { if (ctx.ambientDust) ctx.ambientDust.particles.visible = false; } catch {}
    });
    await page.waitForTimeout(700);
    const out = await page.evaluate(() => {
      const ctx = window.__game.ctx;
      ctx.flags.paused = true;
      const cam = ctx.three.camera; const V = cam.position.constructor;
      const W = 1100, H = 760; ctx.three.renderer.setSize(W, H, false);
      if (cam.isPerspectiveCamera) { cam.aspect = W / H; cam.updateProjectionMatrix(); }
      // the REAL seated forward gaze (mirror the cockpit scenario 'forward' path exactly).
      const tr = ctx.player.body.body.translation();
      const eyeY = tr.y + (ctx.player.eyeOffset || 0.5);
      cam.position.set(tr.x, eyeY, tr.z + 0.1);
      cam.rotation.order = 'YXZ';
      cam.rotation.set(-0.03, -0.09, 0);
      cam.updateMatrixWorld(true);
      const gl = ctx.three.renderer.getContext();
      // Three FIXED rects over the BRIGHT galaxy band (where the faint glaze is actually perceived —
      //   over pure black the glaze is correctly near-invisible). One per region for front/side/top
      //   PARITY. Sampled glass-ON then glass-OFF → the delta IS the haze the glaze floor adds.
      const rects = {
        frontBand: [430, 70, 560, 150],   // galaxy band through the front-centre panes
        leftBand:  [180, 80, 330, 170],   // galaxy band through a left pane
        crownBand: [560, 30, 700, 100],   // galaxy band through the crown/top band
      };
      const readRects = () => {
        ctx.three.renderer.render(ctx.three.scene, ctx.three.camera);
        const px = new Uint8Array(W * H * 4);
        gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px);
        const r = {};
        for (const [name, [x0, y0, x1, y1]] of Object.entries(rects)) {
          let s = 0, n = 0;
          for (let py = y0; py < y1; py++) { const gy = H - 1 - py;
            for (let x = x0; x < x1; x++) { const i = (gy * W + x) * 4;
              const l = 0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2];
              if (l < 80) { s += l; n++; } } }   // exclude stars/border glint (>80)
          r[name] = n ? +(s / n).toFixed(3) : 0;
        }
        return r;
      };
      const on = readRects();
      // hide the glass sheet, re-render, read the same rects (the raw sky behind the panes).
      let glass = null;
      ctx.three.scene.traverse((o) => { if (o.isMesh && o.material && o.material.transparent && o.renderOrder === 2) { glass = o; o.visible = false; } });
      const off = readRects();
      if (glass) glass.visible = true;
      return { on, off };
    });
    const delta = {}; for (const k of Object.keys(out.on)) delta[k] = +(out.on[k] - out.off[k]).toFixed(3);
    const dvals = Object.values(delta);
    const dm = dvals.reduce((a, b) => a + b, 0) / dvals.length;
    const ddev = dm !== 0 ? Math.max(...dvals.map((v) => Math.abs(v - dm) / Math.abs(dm))) : 0;
    console.log('[glaze-body] glass-ON  luma over galaxy band: ' + JSON.stringify(out.on));
    console.log('[glaze-body] glass-OFF luma over galaxy band: ' + JSON.stringify(out.off));
    console.log('[glaze-body] HAZE DELTA (on-off): front=' + delta.frontBand + '  left=' + delta.leftBand +
      '  crown=' + delta.crownBand + '  | meanΔ=' + dm.toFixed(3) + '  parity maxDev=' + (ddev * 100).toFixed(1) + '% ' +
      (ddev <= 0.12 ? 'PARITY-OK' : 'MISMATCH'));
  },
};

function startDev() {
  const isWin = process.platform === 'win32';
  const cmd = isWin ? 'npm.cmd' : 'npm';
  const proc = spawn(cmd, ['run', 'dev', '--', '--host', '127.0.0.1', '--port', String(PORT), '--strictPort'], {
    cwd: ROOT,
    shell: isWin,
  });
  let exited = false;
  proc.on('exit', () => { exited = true; });
  proc.stdout.on('data', () => {});
  proc.stderr.on('data', () => {});
  return new Promise((res, rej) => {
    const start = Date.now();
    const tick = async () => {
      if (exited) return rej(new Error('dev server exited early'));
      // 120s: a cold Vite boot takes >30s when the machine is loaded (e.g. a
      // concurrent project's verify suite) — 30s made every probe flake then.
      if (Date.now() - start > 120000) { proc.kill(); return rej(new Error('dev server not ready in 120s')); }
      try {
        const r = await fetch(`http://127.0.0.1:${PORT}/`);
        if (r.ok) return res(proc);
      } catch {}
      setTimeout(tick, 300);
    };
    tick();
  });
}

// Dramatic key/fill/shadow lighting — rigStudio cranks ambient to 2.2 + exposure
// 2.0 (flat, even, kills all form). For a fair realism read (and a better in-game
// presentation), drop ambient, keep a strong directional sun for shadow/form, and
// lower exposure so highlights don't blow out. Self-shadowing on the rig (chin,
// folds, under the tunic hem) is what makes a 3D form read as solid rather than flat.
async function maybeFormLight(page) {
  if (LIT !== 'form') return;
  await page.evaluate(() => {
    const ctx = window.__game.ctx;
    const scene = ctx.three.scene;
    const cam = ctx.three.camera;
    const V = cam.position.constructor;
    let sun = null;
    scene.traverse((o) => {
      if (!o.isLight) return;
      if (o.type === 'AmbientLight') o.intensity = 0.28;          // low fill → form reads
      else if (o.type === 'HemisphereLight') o.intensity = 0.35;
      else if (o.type === 'DirectionalLight' && o.intensity > 0 && !sun) {
        sun = o;                                                   // KEY
        o.intensity = 3.0;
        o.castShadow = true;
        if (o.shadow) { o.shadow.bias = -0.0004; o.shadow.normalBias = 0.02; }
      }
    });
    // RIM/back light — separates the silhouette from the ground = the single
    // biggest "solid 3D figure" read. Placed behind the figure relative to the
    // camera, up high, cool tint. Created once + repositioned per shot.
    const rig = ctx.player.rig;
    const head = rig.headGroup.getWorldPosition(new V());
    const behind = new V().subVectors(head, cam.position).normalize(); // away from camera
    let rim = scene.getObjectByName('__rimLight');
    if (!rim && sun) { rim = new sun.constructor(0xbfd4ff, 2.2); rim.name = '__rimLight'; scene.add(rim); }
    if (rim) {
      rim.position.set(head.x + behind.x * 4 + 1.5, head.y + 3.5, head.z + behind.z * 4);
      if (rim.target) { rim.target.position.copy(head); rim.target.updateMatrixWorld(true); }
    }
    ctx.three.renderer.shadowMap.enabled = true;
    ctx.three.renderer.toneMappingExposure = 1.05;
  });
  await page.waitForTimeout(250);
}

async function main() {
  if (!POSES[POSE]) throw new Error(`unknown pose "${POSE}" (idle|apose|walk)`);
  console.log(`[rig-shot] starting dev server on ${PORT}…`);
  const dev = await startDev();
  console.log(`[rig-shot] dev up; launching chromium…`);
  // GL backend (2026-07-13 probe-infra): swiftshader is SOFTWARE rendering —
  // it pins every CPU core (the machine-heat complaint). RIG_GL=angle switches
  // to the platform GPU via ANGLE/D3D11 on Windows (headless=new exposes it
  // when a real GPU is present) — far cooler + faster for SHOT scenarios.
  // Content gates (determinism/streaming/walk) are pixel-independent, so the
  // backend can't change their result; only screenshots differ, and those are
  // A/B-validated before adoption. Falls back to swiftshader on any doubt.
  const glMode = GL_MODE;   // DEFAULT GPU (2026-07-13): validated identical digest + correct renders, ~10× faster, CPU-cool. RIG_GL=swiftshader (or --gl=swiftshader) forces the old software path.
  const glArgs = glMode === 'angle'
    ? ['--enable-webgl', '--use-angle=d3d11', '--enable-gpu', '--ignore-gpu-blocklist']
    : ['--enable-webgl', '--use-angle=swiftshader', '--ignore-gpu-blocklist'];
  const browser = await chromium.launch({ args: glArgs });
  try {
    const ctx = await browser.newContext({ viewport: { width: 900, height: 1100 }, deviceScaleFactor: 1 });
    const page = await ctx.newPage();
    // W2 ASPECT FIX — scenarios resize the RENDER BUFFER (renderer.setSize(w,h,false) + a matching
    // camera.aspect) but the canvas CSS box stays at the fixed 900×1100 viewport, so page.screenshot
    // resampled the buffer into the wrong aspect → every non-900×1100 shot was stretched (the
    // "oval porthole" false frame; circles are just where it shows). Snap the viewport to the canvas
    // buffer dims right before each capture so CSS == buffer == camera aspect and shots are true.
    const _origScreenshot = page.screenshot.bind(page);
    page.screenshot = async (opts = {}) => {
      try {
        const dims = await page.evaluate(() => {
          const c = document.querySelector('canvas');
          return c && c.width > 50 ? { w: c.width, h: c.height } : null;
        });
        const vp = page.viewportSize();
        if (dims && vp && (dims.w !== vp.width || dims.h !== vp.height)) {
          await page.setViewportSize({ width: dims.w, height: dims.h });
          await page.waitForTimeout(120);   // let layout/compositor settle before the capture
        }
      } catch { /* fall through — a wrong-aspect shot beats no shot */ }
      return _origScreenshot(opts);
    };
    page.on('pageerror', (e) => console.log(`  [page error] ${e.message}`));
    page.on('console', (m) => { if (m.type() === 'error') console.log(`  [browser error] ${m.text()}`); });
    // ACN — mark the tutorial intro as seen BEFORE any page script runs, so the
    // first-boot controls panel never opens. Otherwise it stays open in the
    // headless session and `updateWieldAction`'s overlayOpen() gate suppresses
    // ALL LMB actions (attack/place) — which silently blocked the rifle-fire
    // scenario (reload uses a separate path with no overlay gate, so it worked).
    await page.addInitScript((seed) => {
      try { localStorage.setItem('dustfall.tutorial.v1', JSON.stringify({ seenIntro: true, usedItems: [] })); } catch { /* ignore */ }
      // Pin the world seed so rig-shots are DETERMINISTIC (same world every run →
      // clean before/after visual comparisons). Re-set on every document load
      // (boot consumes/removes the pending key). Override with --seed=<n>.
      try { localStorage.setItem('dustfall.pendingSeed', String(seed)); } catch { /* ignore */ }
      // BLOCK THE VITE-HMR WEBSOCKET (mirrors model-stage.mjs): concurrent sessions editing src/
      //   (sibling agents own shipScene/haulerScene) would otherwise trigger a full-reload mid-run
      //   ("Execution context was destroyed, most likely because of a navigation") and kill long
      //   live-scenario evals (the pod boarding/walk gates). The page becomes a snapshot of the
      //   source at boot; re-run to pick up edits. (The stub also stalls window 'load' — we already
      //   gate on domcontentloaded + the __game poll below, so that's fine.)
      const NativeWS = window.WebSocket;
      // eslint-disable-next-line func-names
      window.WebSocket = function (url, protocols) {
        const isHmr = (protocols && String(protocols).includes('vite-hmr')) || /vite/.test(String(url));
        if (isHmr) {
          return { addEventListener() {}, removeEventListener() {}, send() {}, close() {}, readyState: 3, onopen: null, onmessage: null, onclose: null, onerror: null };
        }
        return new NativeWS(url, protocols);
      };
      window.WebSocket.prototype = NativeWS.prototype;
    }, Number(argv.seed ?? 1337));
    await page.goto(`http://127.0.0.1:${PORT}/`, { waitUntil: 'domcontentloaded' });
    // Ensure the document is parsed before we poll for __game — under swiftshader the
    // first WebGL context creation can lag, and polling before DOM-ready can catch a
    // half-initialised window (the boot-race root the verify:* gates retry around).
    await page.waitForLoadState('domcontentloaded').catch(() => {});
    // Wait for the rig to exist (Rapier WASM + boot done). 45s (up from 30s): the
    // swiftshader first-paint tail can exceed 30s on a cold/loaded headless boot,
    // which surfaced as the "NO AUDIT LINE" flake. The verify:* single-retry is the
    // real safety net; this just makes the retry fire less often.
    await page.waitForFunction(() => !!(window.__game && window.__game.ctx?.player?.rig), undefined, { timeout: 45000 });
    // ACN — live scenario mode short-circuits the static pose/angle path.
    if (SCENARIO) {
      const fn = SCENARIOS[SCENARIO];
      if (!fn) throw new Error(`unknown scenario "${SCENARIO}" (${Object.keys(SCENARIOS).join('|')})`);
      console.log(`[rig-shot] running live scenario "${SCENARIO}" (${FRAMES} frames @ ${INTERVAL}ms)…`);
      await enterLive(page, ['shrew-flee', 'rifle', 'shrew-kill'].includes(SCENARIO) ? false : true);
      await fn(page);
      return; // the finally below closes browser + kills dev
    }
    // Enter the studio (headless enter + lighting + unpause), let a frame settle
    // the rig at the player, then pause + pose.
    await page.evaluate(() => window.__game.rigStudio());
    await page.waitForTimeout(700);
    await page.evaluate((poseCode) => {
      const g = window.__game;
      const rig = g.ctx.player.rig;
      g.ctx.flags.paused = true;
      // eslint-disable-next-line no-eval
      eval(poseCode);
      rig.group.updateMatrixWorld(true);
    }, POSES[POSE]);
    if (CLOSEUP) {
      const spec = CLOSEUPS[CLOSEUP];
      if (!spec) throw new Error(`unknown closeup "${CLOSEUP}" (${Object.keys(CLOSEUPS).join('|')})`);
      await page.evaluate(({ jointExpr, off, look }) => {
        const g = window.__game;
        const rig = g.ctx.player.rig;
        const cam = g.ctx.three.camera;
        const V = cam.position.constructor;
        g.ctx.flags.paused = true;
        // eslint-disable-next-line no-eval
        const joint = eval(jointExpr);
        const jp = joint.getWorldPosition(new V());
        const fz = rig.headGroup.getWorldDirection(new V()); fz.y = 0; fz.normalize();
        const side = new V(-fz.z, 0, fz.x);
        cam.position.set(
          jp.x + side.x * off[0] + fz.x * off[2],
          jp.y + off[1],
          jp.z + side.z * off[0] + fz.z * off[2],
        );
        cam.lookAt(jp.x + look[0], jp.y + look[1], jp.z + look[2]);
        cam.updateMatrixWorld(true);
      }, { jointExpr: spec.joint, off: spec.off, look: spec.look });
      await page.waitForTimeout(350);
      await maybeFormLight(page);
      const path = join(OUT, `rig-${TAG}-${POSE}-closeup-${CLOSEUP}${LIT ? '-' + LIT : ''}.png`);
      await page.screenshot({ path, fullPage: false });
      console.log(`[rig-shot] saved ${path}`);
    } else {
      for (const angle of ANGLES) {
        await page.evaluate((a) => window.__game.rigStudio(a), angle);
        await page.waitForTimeout(350);
        await maybeFormLight(page);
        const path = join(OUT, `rig-${TAG}-${POSE}-${angle}${LIT ? '-' + LIT : ''}.png`);
        await page.screenshot({ path, fullPage: false });
        console.log(`[rig-shot] saved ${path}`);
      }
    }
  } finally {
    await browser.close();
    // Windows: dev.kill() only signals the npm wrapper; the vite child is left
    // orphaned — it keeps --strictPort 5191 bound (so the NEXT run can't bind)
    // AND its stdio pipes keep this node process alive → the run "hangs" after
    // the screenshot is already written. Kill the whole process tree so the
    // port frees and the loop doesn't wedge.
    try {
      if (process.platform === 'win32' && dev.pid) {
        spawnSync('taskkill', ['/pid', String(dev.pid), '/T', '/F'], { stdio: 'ignore' });
      } else {
        dev.kill();
      }
    } catch {}
  }
}

// Force a clean exit — on win32 a lingering child handle can otherwise keep the
// event loop alive even after teardown completes.
main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

/** DEEPER cycle 9 — PER-KIND SMOKE SHOTS. Three torch-lit player-eye framings per kind, written to
 *  verification/scen-kind-<kind>-<name>.png.
 *
 *  DELIBERATELY NOT a rule-8 look pass — that is the follow-up cycle's job, and this cycle's claim is
 *  about parameters and traversability, not about the shipped read. What these exist for is the
 *  cheapest possible answer to "does the silhouette actually differ?": three frames per kind that a
 *  human (or the visual cycle that follows) can put side by side.
 *
 *  The three framings are chosen to show the thing the kind CHANGED:
 *    · `room`      — standing on the deepest chamber's floor looking across it. Room scale + height.
 *    · `corridor`  — standing at a corridor mouth looking down the tube. Cross-section + length.
 *    · `signature` — the kind's own feature: the biggest pool (flooded), the nearest fungi cluster
 *                    (fungal), a rubble heap (shaft), a scrap flake (warren).
 *
 *  Carried light is modelled through the game's OWN setter (`__game.setCaveRockLight`), same as
 *  `cave-audit`, so the rock's envelope/bounce response is the shipping one and not a rig re-derivation.
 */
async function caveKindShots(page, kind, residentKey) {
  const EYE = 1.68;
  const TAG = argv.tag ? `-${String(argv.tag)}` : '';
  const plan = await page.evaluate(({ KEY, EYE }) => {
    const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const T = g.Tuning;
    const res = ctx.caveStream.residents().find((r) => r.key === KEY);
    if (!res) return null;
    const p = res.cave.probe;
    const nodes = p.nodes;
    const egg = nodes.find((n) => n.id === p.eggId) || nodes[0];
    const byId = new Map(nodes.map((n) => [n.id, n]));
    // THE FLOOR SNAP — with a SANITY CLAMP (cycle-9-look round 1). The old version cast from
    // `guess + 3` and took whatever it hit; when the guess was a ceiling feature or a scene object
    // whose Y was wrong the ray escaped the cave and returned the DESERT SURFACE, and two of the
    // four shipped `signature` frames were of the outside of the tor under an orange sky. A cave
    // shot that renders sky is a broken instrument, not a bad asset. So: cast from inside the room's
    // own dome, and reject any hit that is not within ±3.5m of the room floor we asked about.
    const floorAt = (x, z, guess, span) => {
      const h = g.castDown(x, z, guess + (span === undefined ? 2.5 : span), true);
      if (!h) return guess;
      if (Math.abs(h.hitY - guess) > 3.5) return guess;
      return h.hitY;
    };
    // A HORIZONTAL ray against the SHIPPED colliders (the cave trimesh IS the visible geometry, rule
    // 9) — used to measure real stand-off before a camera is parked, and to prove a framed feature
    // is not occluded. Returns the distance to the first rock, or `max` if the ray never hits.
    const RAPIER = g.RAPIER;
    const pbody = ctx.player.body.body;
    let shelfCount = 0;
    const hRay = (ox, oy, oz, dx, dz, max) => {
      const h = ctx.physics.world.castRay(
        new RAPIER.Ray({ x: ox, y: oy, z: oz }, { x: dx, y: 0, z: dz }), max, true,
        undefined, undefined, undefined, pbody,
      );
      return h ? h.timeOfImpact : max;
    };
    const out = [];
    // 1 — the deepest room, from its rim looking across the middle at HEAD height (not at 45% of the
    //     dome: that pitched the frame into the black and hid the floor read).
    //
    //     …EXCEPT FOR `flooded` (close-out finding 5 — a BROKEN INSTRUMENT, not a bad asset). The
    //     `room` frame is the kind's primary read, and for every other kind the deepest chamber IS
    //     the kind's best room. But the deepest chamber is the EGG chamber, which is DRY BY
    //     CONSTRUCTION (the pool placer keeps clear of the dais), so the flooded cave's headline
    //     frame contained no water at all — it graded the one kind whose whole identity is standing
    //     water on the one room that cannot have any. Flooded frames its largest POOLED chamber, and
    //     the look target drops so the waterline is in shot rather than above it.
    {
      let R = egg, lookF = 0.30;
      if (p.kind === 'flooded' && p.pools && p.pools.length) {
        const big = p.pools.slice().sort((a, b) => b.r - a.r)[0];
        const n = byId.get(big.node);
        if (n) { R = n; lookF = 0.12; }
      }
      const a = 0.62, ux = Math.cos(a), uz = Math.sin(a);
      // ── CLOSE-OUT ROUND 2 (finding N4) — DON'T STAND IN THE ROCK. `rx · 0.80` is a stand-off
      //    against the ANALYTIC room; the room the camera is actually in is the SDF surface, which
      //    comes in up to ~0.4m tighter, and where a neighbouring chamber clips the dome it comes in
      //    metres tighter. `scen-kind-fungal-room-c5.png` spent its right-hand 15% on an out-of-focus
      //    rock face 30cm from the lens — a framing defect being graded as an asset defect. So the
      //    stand-off is MEASURED with a ray along the same bearing and pulled back to leave ≥1.8m of
      //    air in front of the eye. Purely a camera change; the asset is untouched.
      //    ROUND 2, TAKE 2: a single ray along the STAND bearing is not enough, and the r4 frame
      //    proved it — the offending mass in `scen-kind-fungal-room-r4.png` was a COLUMN beside the
      //    lens (this kind runs speleoColumnScale 3.2), not the wall the camera was backing toward.
      //    So the stand point is tested with a full RING of rays at eye height and pulled toward the
      //    room centre until nothing is inside 0.95m of the eye in any direction.
      const R0 = floorAt(R.x, R.z, R.y);
      let stand = R.rx * 0.80;
      for (let att = 0; att < 6; att++) {
        const cx = R.x + ux * stand, cz = R.z + uz * stand;
        const cy = floorAt(cx, cz, R.y) + EYE;
        let minC = Infinity;
        for (let b2 = 0; b2 < 12; b2++) {
          const t2 = (b2 / 12) * Math.PI * 2;
          minC = Math.min(minC, hRay(cx, cy, cz, Math.cos(t2), Math.sin(t2), 3.0));
        }
        if (minC >= 0.95 || stand <= 1.2) break;
        stand = Math.max(1.2, stand - R.rx * 0.12);
      }
      const sx = R.x + ux * stand, sz = R.z + uz * stand;
      const fy = floorAt(sx, sz, R.y);
      out.push({ name: 'room', cam: [sx, fy + EYE, sz], look: [R.x - ux * R.rx * 0.5, R.y + R.height * lookF, R.z - uz * R.rx * 0.5] });
    }
    // 1b — THE VAULT READ. Stand in the middle of the deepest room and pitch UP. This is the shot
    //      that answers "is the height legible or is it a black void" for fungal AND shaft; the
    //      across-the-room framing cannot answer it because the ceiling leaves the frame.
    {
      const a = 2.1, ux = Math.cos(a), uz = Math.sin(a);
      const sx = egg.x + ux * egg.rx * 0.30, sz = egg.z + uz * egg.rx * 0.30;
      const fy = floorAt(sx, sz, egg.y);
      out.push({ name: 'vault', cam: [sx, fy + EYE, sz], look: [egg.x - ux * egg.rx * 0.9, egg.y + egg.height * 0.95, egg.z - uz * egg.rx * 0.9] });
    }
    // 2 — down a corridor from just inside its mouth. Prefer a squeeze (that is what the warren
    //     changed); fall back to whatever the tree has.
    {
      const e = p.edges.find((q) => q.squeeze) || p.edges[0];
      const A = byId.get(e.a), B = byId.get(e.b);
      const D = Math.hypot(B.x - A.x, B.z - A.z) || 1;
      const hx = (B.x - A.x) / D, hz = (B.z - A.z) / D;
      const s0 = A.rx + 1.0;
      const sx = A.x + hx * s0, sz = A.z + hz * s0;
      const fy = floorAt(sx, sz, A.y + (B.y - A.y) * (s0 / D));
      out.push({ name: 'corridor', cam: [sx, fy + EYE, sz], look: [B.x, B.y + 1.4, B.z] });
    }
    // 2b — THE ARRIVAL FRAME. Standing on the entrance chamber's floor at the crevice hand-off,
    //      looking in. This is literally the player's FIRST five seconds of the kind, so it is the
    //      frame the whole look pass is graded on.
    {
      const a0 = nodes[0];
      let ux = a0.x - p.junction.x, uz = a0.z - p.junction.z;
      const ul = Math.hypot(ux, uz) || 1; ux /= ul; uz /= ul;
      const sx = a0.x - ux * a0.rx * 0.85, sz = a0.z - uz * a0.rx * 0.85;
      const fy = floorAt(sx, sz, a0.y);
      out.push({ name: 'arrival', cam: [sx, fy + EYE, sz], look: [a0.x + ux * a0.rx * 0.9, a0.y + a0.height * 0.32, a0.z + uz * a0.rx * 0.9] });
    }
    // 2c — THE SMALLEST SIDE POCKET, from its rim. The warren's claustrophobia claim lives here (the
    //      egg chamber is by construction the biggest room in EVERY kind, so it can never show it).
    {
      let pockets = nodes.filter((n) => n.kind !== 'egg' && n.id !== nodes[0].id).sort((a, b) => a.rx - b.rx);
      // ── CLOSE-OUT ROUND 2 (finding N5) — A FLOODED POCKET MUST CONTAIN WATER. The smallest side
      //    pocket is the right choice for "how tight is this kind", and for the flooded cave it kept
      //    landing on the one small room the pool placer skipped: `scen-kind-flooded-pocket-c5.png`
      //    is a DRY floor, i.e. the kind's own claim is absent from the frame that is supposed to
      //    show a small room of it. Restrict the candidate set to POOLED pockets when the kind has
      //    any, and drop the look target so the waterline is in shot rather than above it.
      let lookF = 0.34;
      if (p.kind === 'flooded' && p.pools && p.pools.length) {
        const pooled = new Set(p.pools.map((q) => q.node));
        const wet = pockets.filter((n) => pooled.has(n.id));
        if (wet.length) { pockets = wet; lookF = 0.14; }
      }
      const q = pockets[0];
      if (q) {
        const a = 1.4, ux = Math.cos(a), uz = Math.sin(a);
        const sx = q.x + ux * q.rx * 0.72, sz = q.z + uz * q.rx * 0.72;
        const fy = floorAt(sx, sz, q.y);
        out.push({ name: 'pocket', cam: [sx, fy + EYE, sz], look: [q.x - ux * q.rx * 0.8, q.y + q.height * lookF, q.z - uz * q.rx * 0.8] });
      }
    }
    // 2d — A WALL SHELF, CLOSE UP (close-out). The r3 "sconce / floating orb" finding was caught by
    //      accident, in a pocket framing that happened to contain a shelf; the frame that could
    //      prove or disprove it did not exist. Wall shelves DECLARE their mount now
    //      (`userData.wallShelf`, with the rock normal they were anchored to), so this stands 1.7m
    //      straight out along that normal and looks back at the rock — the one angle where "is this
    //      attached to anything?" is answerable.
    {
      let best = null, bd = 1e9;
      res.cave.group.traverse((o) => {
        const w = o.userData && o.userData.wallShelf;
        if (!w || !o.visible) return;
        shelfCount++;
        const d = Math.hypot(w.x - egg.x, w.z - egg.z);
        if (d < bd) { bd = d; best = w; }
      });
      if (best) {
        // A GRAZING 3/4, never dead-on down the normal: a cap photographed along its own axis is a
        // flat disc no matter how it is mounted, which answers nothing. Off to one side and below,
        // so the mount, the stalk and the rock behind are all in the frame.
        //
        // ── CLOSE-OUT ROUND 2 (finding N3, the evidence half). Round 1's version was a WIDE lens at
        //    ~1.6m, and the shipped frames prove that answers nothing either: the flooded shelf came
        //    out as a 12-pixel teal dot on black (`scen-kind-flooded-shelf-c5.png`) and the fungal one
        //    filled its frame with cap and no rock. The eye distance stays in the honest 1.5-2m
        //    evidence window — a diagnostic that teleports to 20cm is testing a view the game never
        //    shows — and the LENS does the work instead: the FOV is solved so the cap subtends a
        //    fixed ~38% of frame height whatever the kind's cap scale is, i.e. a macro lens on the
        //    junction. It also declares the JUNCTION POINT, so the render pass can machine-check that
        //    the mount is not hidden behind another rock (a photograph of an occluded mount is a
        //    photograph of nothing, and it would have graded green).
        const D = 1.7;
        const tl = Math.hypot(best.nz, -best.nx) || 1;
        const tx = best.nz / tl, tz = -best.nx / tl;
        // WELL below and well to the SIDE. The r5 frame was still three-quarters front-on, and a
        // bracket fungus's own cap overhangs its stem — so the cap covered the junction it was
        // supposed to prove. From under-and-beside, the cap swings up out of the way and the stem
        // meets the stone in clear air.
        // …and LOWER still for a small cap. A shelf mushroom's own cap overhangs its stem by roughly
        // its radius, and the stem that has to be visible is only ~10cm long at canonical cap scale
        // (the flooded/canonical kinds), so the angle that works for a 30cm cathedral cap still
        // photographs a small one as a bare disc. The rise is scaled to the cap: the smaller the cap,
        // the further under it the lens has to get to see the mount.
        const under = 0.70 + 0.55 * Math.max(0, 1 - (best.capR || 0.16) / 0.24);
        let ox = best.nx * 0.45 + tx * 0.85, oy = best.ny * 0.45 - under, oz = best.nz * 0.45 + tz * 0.85;
        const ol = Math.hypot(ox, oy, oz) || 1;
        ox = (ox / ol) * D; oy = (oy / ol) * D; oz = (oz / ol) * D;
        const capR = best.capR || 0.16;
        const fov = Math.min(60, Math.max(20, (2 * Math.atan((capR * 4.2) / D) * 180) / Math.PI));
        out.push({
          name: 'shelf', cam: [best.x + ox, best.y + oy, best.z + oz], look: [best.x, best.y, best.z],
          fov: +fov.toFixed(1), junction: [best.x, best.y, best.z],
        });
      }
    }
    // 3 — the kind's signature feature, framed from ~2.6m away at eye height. Every target now
    //     carries the NODE it belongs to, so the floor snap has an honest guess and the clamp above
    //     can catch an escape instead of shipping a picture of the sky.
    {
      let tgt = null;
      const nearestNode = (x, z) => {
        let best = nodes[0], bd = 1e9;
        for (const n of nodes) { const d = Math.hypot(n.x - x, n.z - z); if (d < bd) { bd = d; best = n; } }
        return best;
      };
      const pools = (p.pools || []).slice().sort((a, b) => b.r - a.r);
      if (pools.length) tgt = { x: pools[0].x, y: pools[0].y, z: pools[0].z, r: Math.max(1.6, pools[0].r) };
      // fungi / rubble / scrap are all SCENE objects; find the nearest to the deepest room.
      const want = new THREE.Color(T.CAVE_FUNGI_EMISSIVE_HEX).getHexString();
      const wp = new THREE.Vector3();
      let fung = null, fd = 1e9;
      res.cave.group.traverse((o) => {
        if (!o.isMesh || !o.material || !o.material.emissive) return;
        if (o.material.emissive.getHexString() !== want) return;
        o.getWorldPosition(wp);
        const d = Math.hypot(wp.x - egg.x, wp.z - egg.z);
        if (d < fd) { fd = d; fung = { x: wp.x, y: wp.y, z: wp.z, r: 1.4 }; }
      });
      const K = p.kind;
      if (K === 'fungal' && fung) tgt = fung;
      if (K === 'warren') {
        // ── DEEPER cycle 12 — THE WARREN'S SIGNATURE IS THE DEAD EXPLORER, not a scrap flake. The
        //    kind's defining feature moved when the beat landed, so the frame that exists to show
        //    "what did this kind change" moved with it. Same lesson as the line it replaces: take the
        //    anchor PUBLISHED ON THE BUILT CAVE (`cave.beatAnchor`), never the sink-spawned scene
        //    objects, which may not be populated when the framing is computed.
        const ba0 = res.cave.beatAnchor;
        if (ba0) tgt = { x: ba0.pos.x, y: ba0.pos.y + 0.35, z: ba0.pos.z, r: 1.1 };
        else {
          // The SCRAP ANCHORS, straight off the built cave — the pickup list was the wrong source (it
          // is spawned by the resident sink, may not be populated yet, and carries no node).
          const anc = (res.cave.scrapAnchors || []).map((v) => ({ x: v.x, y: v.y, z: v.z }));
          let best = null, bd = 1e9;
          for (const q of anc) { const d = Math.hypot(q.x - egg.x, q.z - egg.z); if (d < bd) { bd = d; best = q; } }
          if (best) tgt = { x: best.x, y: best.y, z: best.z, r: 1.1 };
        }
      }
      if (K === 'shaft') {
        // Rubble heaps DECLARE themselves (`userData.rubbleHeap`). The previous version guessed —
        // "a small solid near a chamber floor" — and framed stalagmites instead, so the one shot
        // that exists to prove this kind's defining feature never showed it.
        let best = null, bd = 1e9;
        res.cave.group.traverse((o) => {
          const h = o.userData && o.userData.rubbleHeap;
          if (!h) return;
          const d = Math.hypot(h.x - egg.x, h.z - egg.z);
          if (d < bd) { bd = d; best = { x: h.x, y: h.floorY, z: h.z, r: Math.max(1.3, h.r) }; }
        });
        if (best) tgt = best;
      }
      if (tgt) {
        // STAND ON THE ROOM-CENTRE SIDE OF THE TARGET. The previous version backed the eye off along
        // a FIXED bearing (+0.78,+0.62); every signature target (pool rim, scrap cache, rubble heap,
        // wall fungi) sits out near the wall, so half the time that put the camera INSIDE THE ROCK —
        // and the cave shell is FrontSide, so from inside the rock you see straight out to the
        // desert. Three of cycle 9's four `signature` frames were pictures of the sky for this
        // reason. Backing off toward the chamber centre cannot leave the cavity.
        const nd0 = nearestNode(tgt.x, tgt.z);
        let bx = nd0.x - tgt.x, bz = nd0.z - tgt.z;
        const bl = Math.hypot(bx, bz);
        if (bl < 0.4) { bx = 1; bz = 0; } else { bx /= bl; bz /= bl; }
        const off = Math.min(tgt.r + 2.4, Math.max(1.6, nd0.rx * 0.9));
        const sx = tgt.x + bx * off, sz = tgt.z + bz * off;
        const nd = nearestNode(sx, sz);
        const fy = floorAt(sx, sz, nd.y);
        out.push({ name: 'signature', cam: [sx, fy + EYE, sz], look: [tgt.x, Math.max(tgt.y, fy) + 0.35, tgt.z] });
      }
    }
    // ── 4 — THE DEAD EXPLORER, AT THE RANGE IT IS ACTUALLY READ (DEEPER cycle 12, the close-read
    //    pass). This prop is met at 1-2m by torchlight, kneeling over it — which is a completely
    //    different instrument from the 2.6m `signature` frame, and the defects that matter (a
    //    zero-thickness eye socket, a limb that tapers to a blade, a faceted tube) are INVISIBLE at
    //    2.6m by construction. Five framings, one per failure mode:
    //      beat      — the whole tableau at 4m, i.e. the read as you walk into the room.
    //      torch     — 1.5m head-on, the conversation distance.
    //      skull     — 1.0m on the skull, face-on; and
    //      skullturn — the SAME skull from ~70° off-axis: the head-turn. A `CircleGeometry` socket
    //                  is a single face, so it survives the first frame and VANISHES in this one.
    //                  Two frames or the socket claim is untested.
    //      limb      — a grazing, near-floor angle along the reaching arm: the edge-on read of the
    //                  limb bones (rule 7's "verify from grazing angles, not face-on").
    //      fracture  — a macro on a DECLARED broken bone (`userData.boneFracture`), the shot that
    //                  proves the cross-section is solid and splintered rather than a capped pill.
    //    Anchors come off the BUILT CAVE (`cave.beatAnchor`) with the declared prop tags as a
    //    refinement, never from a scene search alone — same lesson as the signature frame above.
    const ba = res.cave.beatAnchor;
    let bedding = null;
    if (ba) {
      const fx = Math.sin(ba.yaw), fz = Math.cos(ba.yaw);      // the figure's own +Z (it faces the room)
      const sx0 = fz, sz0 = -fx;                               // its right-hand side
      const L2W = (lx, ly, lz) => ({
        x: ba.pos.x + lx * sx0 + lz * fx,
        y: ba.pos.y + ly,
        z: ba.pos.z + lx * sz0 + lz * fz,
      });
      // Declared prop anchors, if the sink has attached (it has, whenever a resident exists — but a
      // missing tag must degrade to the authored local offset, never to no frame at all).
      let skullW = null, fracW = null, fracR = 0.03;
      for (const root of ctx.three.scene.children) {
        if (root.name !== 'deadExplorer') continue;
        root.traverse((o) => {
          const u = o.userData || {};
          if (u.skullAnchor) { const v = new THREE.Vector3(); o.getWorldPosition(v); skullW = v; }
          if (u.boneFracture) {
            const v = new THREE.Vector3();
            o.localToWorld(v.set(u.boneFracture.x, u.boneFracture.y, u.boneFracture.z));
            fracW = v; fracR = u.boneFracture.r || 0.03;
          }
        });
      }
      const SK = skullW || L2W(0, 0.754, -0.410);               // the authored skull centre
      // ── THE BEDDING PROBE. The tableau is ONE plane (the group's anchor y) but the cave floor is
      //    DISPLACED rock, so every prop out at the edge of the group can be left hanging in air —
      //    which the `fracture` macro caught as a levitating journal. Measure the rock under each
      //    prop and name the gap in metres; a picture cannot answer "is that 2cm or 10cm?".
      //    ⚠ THIS PROBE WAS REWRITTEN THE FIRST TIME IT WAS TRUSTED. Its first version measured
      //    `anchor.pos.y - rockUnder(localOffset)` — the ANCHOR PLANE against the rock, never the
      //    prop. That is a real quantity (it is the floor's gradient under the tableau) but it is not
      //    the question, and it is INSENSITIVE TO THE FIX BY CONSTRUCTION: after every prop was
      //    re-seated on its own rock the probe reported the same seven numbers to the millimetre,
      //    because none of them had ever depended on where a prop was. A gate that cannot move when
      //    the defect is fixed cannot tell you the defect is fixed. Measure the OBJECT.
      const propWorld = [];
      const beatRoot = (() => { let r = null; res.cave.group.parent.traverse((o) => { if (o.name === 'deadExplorer') r = o; }); return r; })();
      if (beatRoot) {
        beatRoot.updateMatrixWorld(true);
        beatRoot.traverse((o) => {
          const tag = o.userData && o.userData.beatProp;
          if (!tag) return;
          propWorld.push([tag, o]);
        });
      }
      const jr = (ctx.journals.list || []).find((j) => Math.hypot(j.pos.x - ba.pos.x, j.pos.z - ba.pos.z) < 2.0);
      if (jr) propWorld.push(['journal', jr.mesh]);
      const cr = (ctx.lootContainers.list || []).find((c) => Math.hypot(c.pos.x - ba.pos.x, c.pos.z - ba.pos.z) < 2.5);
      if (cr) propWorld.push(['crate', cr.mesh]);
      //    …and measure the prop's LOWEST VERTEX, not its origin. Round 2 of this probe reported the
      //    lantern at +0.157 and the canteen at +0.153 while both were correctly seated: their
      //    origins sit deliberately above their contact points (a tipped lantern rests on its cage,
      //    a flask on its rim), so origin-vs-rock reads a design offset as a defect. The question is
      //    "is there daylight under this object", and that is the bounding box's floor.
      bedding = propWorld.length
        ? propWorld.map(([nm, o]) => {
          const bb = new THREE.Box3().setFromObject(o);
          if (!isFinite(bb.min.y)) return `${nm}=NO-GEOMETRY`;
          const cx = (bb.min.x + bb.max.x) / 2, cz = (bb.min.z + bb.max.z) / 2;
          const h = g.castDown(cx, cz, bb.max.y + 1.6, true);
          return `${nm}=${h ? (bb.min.y - h.hitY).toFixed(3) : 'MISS'}`;
        }).join(' ')
        : 'NO TAGGED PROPS FOUND — the probe measured nothing (vacuous)';
      // A camera stand-off that cannot end up inside the rock: measure along the bearing and keep
      // 0.35m of air behind the eye (the beat sits AGAINST a wall, so "back off 4m" is only safe if
      // the room is actually that deep — the r1 lesson from the signature frame).
      const backOff = (want) => {
        const d = hRay(ba.pos.x, ba.pos.y + EYE * 0.6, ba.pos.z, fx, fz, want + 0.8);
        return Math.max(1.0, Math.min(want, d - 0.35));
      };
      const park = (name, dist, side, eyeY, look, extra) => {
        const D = backOff(dist);
        const cx = ba.pos.x + fx * D + sx0 * side, cz = ba.pos.z + fz * D + sz0 * side;
        const fy = floorAt(cx, cz, ba.pos.y);
        out.push({ name, cam: [cx, fy + eyeY, cz], look: [look.x, look.y, look.z], ...(extra || {}) });
      };
      // (e) the arrival read — standing, 4m out.
      park('beat', 4.0, 0, EYE, L2W(0, 0.55, 0));
      // (a) 1.5m head-on, still standing: this is the torch-range conversation frame.
      park('torch', 1.5, 0.15, EYE, L2W(0, 0.55, 0));
      // (b) 1.0m on the skull, at ITS height — the player has crouched to look at the face. A 34°
      //     lens so the head fills the frame honestly instead of being 40px in a wide shot.
      {
        const D = backOff(1.0);
        out.push({
          name: 'skull', cam: [ba.pos.x + fx * D + sx0 * 0.10, SK.y + 0.10, ba.pos.z + fz * D + sz0 * 0.10],
          look: [SK.x, SK.y, SK.z], fov: 34,
        });
      }
      // (b') THE HEAD-TURN. Same distance, same lens, ~70° around: the socket's grazing read.
      {
        const a = 1.22;                                        // rad off the facing axis
        const ax = fx * Math.cos(a) + sx0 * Math.sin(a), az = fz * Math.cos(a) + sz0 * Math.sin(a);
        const D = Math.max(0.75, Math.min(1.0, hRay(SK.x, SK.y, SK.z, ax, az, 1.8) - 0.3));
        out.push({
          name: 'skullturn', cam: [SK.x + ax * D, SK.y + 0.06, SK.z + az * D],
          look: [SK.x, SK.y, SK.z], fov: 34,
        });
      }
      // (c) THE GRAZING LIMB READ — low, from the side, looking along the reaching right arm and the
      //     femurs. Edge-on is where a 5-segment cylinder shows its facets and a blade shows its edge.
      {
        const t = L2W(0.15, 0.16, 0.30);
        const a = 1.05;
        const ax = -(fx * Math.cos(a) + sx0 * Math.sin(a)), az = -(fz * Math.cos(a) + sz0 * Math.sin(a));
        const D = Math.max(0.8, Math.min(1.35, hRay(t.x, t.y + 0.2, t.z, ax, az, 2.2) - 0.3));
        out.push({
          name: 'limb', cam: [t.x + ax * D, t.y + 0.16, t.z + az * D], look: [t.x, t.y, t.z], fov: 40,
        });
      }
      // (d) THE FRACTURE MACRO. Only emitted when a bone DECLARES a break, so a silently-missing
      //     fracture is a missing FILE (the shelf-evidence lesson) rather than a green grade on a
      //     photograph of something else.
      if (fracW) {
        const a = 2.35;
        const ax = fx * Math.cos(a) + sx0 * Math.sin(a), az = fz * Math.cos(a) + sz0 * Math.sin(a);
        const D = 0.55;
        const fov = Math.min(60, Math.max(18, (2 * Math.atan((fracR * 5.0) / D) * 180) / Math.PI));
        out.push({
          name: 'fracture', cam: [fracW.x + ax * D, fracW.y + 0.16, fracW.z + az * D],
          look: [fracW.x, fracW.y, fracW.z], fov: +fov.toFixed(1),
        });
      } else {
        out.push({ name: '__nofracture' });
      }
    }
    const keep = out.filter((s) => s.name !== '__nofracture');
    return { specs: keep, shelfCount, noFracture: keep.length !== out.length, hasBeat: !!ba, bedding };
  }, { KEY: residentKey, EYE });
  if (!plan) { console.log(`[cave-kinds] ${kind}: no resident to shoot`); return; }
  const specs = plan.specs;
  // ── THE MISSING-FILE TOOTH (finding N3). A kind that builds ZERO visible wall shelves silently
  //    produced NO `-shelf` frame at all, and "the file isn't there" is indistinguishable from "the
  //    helper crashed" when a critic is reading a directory. Name it, loudly, every run.
  if (!plan.shelfCount) {
    console.log(`[cave-kinds] ⚠ SHELF EVIDENCE ABSENT — kind '${kind}' built 0 VISIBLE wall-shelf fungi, `
      + `so scen-kind-${kind}-shelf${TAG}.png does not exist and cannot be graded. That is the kind table's `
      + `fungiWallChance talking (warren 0.15 / shaft 0.2 over 1-2 fungi chambers), not a broken helper.`);
  } else {
    console.log(`[cave-kinds] ${kind}: ${plan.shelfCount} visible wall shelves; framing the nearest one.`);
  }
  if (plan.bedding) {
    console.log(`[cave-kinds] ${kind} beat BEDDING (each prop's REAL world y MINUS the rock under it; `
      + `+ve = the prop is hanging that far above the floor, -ve = bedded into it): ${plan.bedding}`);
  }
  if (plan.hasBeat && plan.noFracture) {
    console.log(`[cave-kinds] ⚠ FRACTURE EVIDENCE ABSENT — the dead explorer in '${kind}' declares no `
      + `\`userData.boneFracture\`, so scen-kind-${kind}-fracture${TAG}.png does not exist and the `
      + `cross-section claim (rule 7) is UNTESTED. That is the builder's tag missing, not a broken helper.`);
  }
  if (!plan.hasBeat && kind === 'warren') {
    console.log(`[cave-kinds] ⚠ NO BEAT ANCHOR on this warren — the dead-explorer frames are absent.`);
  }

  for (const spec of specs) {
    const st = await page.evaluate((s) => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const T = g.Tuning;
      const cam = ctx.three.camera;
      // FREEZE FIRST. The game keeps rendering on its own rAF, so without the pause `updatePlayer`
      // puts the camera back on the capsule and the composited screenshot shows the SURFACE the
      // player is standing on — which is exactly what the first run of this helper produced.
      ctx.flags.paused = true;
      ctx.three.renderer.setSize(1100, 720, false);
      const prevFov = cam.fov;
      if (cam.isPerspectiveCamera) {
        cam.aspect = 1100 / 720;
        // A per-framing LENS (close-out round 2). Only the `shelf` evidence shot asks for one: it is
        // a macro of a 10-30cm junction, and at the shipping FOV that is a dozen pixels. Restored
        // with the rest of the scene afterward so no other framing inherits it.
        if (s.fov) cam.fov = s.fov;
        cam.updateProjectionMatrix();
      }
      ctx.three.renderer.toneMappingExposure = 1.05;      // the SHIPPING exposure, never hotter
      cam.position.set(s.cam[0], s.cam[1], s.cam[2]);
      cam.lookAt(s.look[0], s.look[1], s.look[2]);
      cam.updateMatrixWorld(true);
      const hidden = [], dom = [];
      const hide = (o) => { if (o && o.visible) { hidden.push(o); o.visible = false; } };
      hide(ctx.player.rig && ctx.player.rig.group);
      hide(ctx.player.viewModel && ctx.player.viewModel.group);
      for (const el of Array.from(document.body.children)) {
        if (el === ctx.three.renderer.domElement || el.tagName === 'SCRIPT' || el.tagName === 'STYLE') continue;
        if (el.style.display !== 'none') { dom.push([el, el.style.display]); el.style.display = 'none'; }
      }
      let torchI = 0;
      if (ctx.player.viewModel) { torchI = ctx.player.viewModel.heldPointLight.intensity; ctx.player.viewModel.heldPointLight.intensity = 0; }
      const fwd = new THREE.Vector3(); cam.getWorldDirection(fwd);
      const right = new THREE.Vector3().crossVectors(fwd, new THREE.Vector3(0, 1, 0)).normalize();
      const lp = cam.position.clone().addScaledVector(fwd, 0.45).addScaledVector(right, 0.30);
      lp.y -= 0.28;
      const tl = new THREE.PointLight(T.TORCH_LIGHT_COLOR_HEX, T.TORCH_LIGHT_INTENSITY, T.TORCH_LIGHT_DISTANCE, 2);
      tl.position.copy(lp); ctx.three.scene.add(tl);
      g.setCaveRockLight(lp.x, lp.y, lp.z, T.TORCH_LIGHT_INTENSITY);
      ctx.three.renderer.render(ctx.three.scene, cam);
      window.__kindShotRestore = { hidden, dom, torchI, light: tl, prevFov };
      // THE BROKEN-INSTRUMENT TOOTH. An interior shot whose eye is ABOVE the desert surface is a
      // picture of the outside of the tor; grading one of those is how a look pass ships a lie.
      const surf = ctx.terrain.heightAt(cam.position.x, cam.position.z);
      // ── THE OCCLUSION TOOTH (finding N3). A framing that declares a JUNCTION must prove the
      //    junction is the first rock the lens meets. `wallShelf` anchors are embedded a few cm INTO
      //    the wall, so a clean shot hits rock just SHORT of the declared point; anything markedly
      //    shorter is a different rock standing in the way, and the resulting photograph of a
      //    stalagmite would have been graded as evidence of a mount.
      // TEMP IDENTITY PROBE — what is actually AT these screen points? (removed after the round)
      let ident = null;
      if (s.probe) {
        const rc = new THREE.Raycaster();
        ident = [];
        for (const q of s.probe) {
          rc.setFromCamera(new THREE.Vector2(q[0], q[1]), cam);
          const hits = rc.intersectObjects(ctx.three.scene.children, true);
          const h0 = hits.find((h) => h.object.isMesh && h.object.visible);
          ident.push(h0 ? {
            px: q, d: +h0.distance.toFixed(2),
            verts: h0.object.geometry.attributes.position.count,
            idx: h0.object.geometry.index ? h0.object.geometry.index.count : 0,
            ud: Object.keys(h0.object.userData || {}).join('|') || '-',
            gt: h0.object.geometry.type,
          } : { px: q, miss: true });
        }
      }
      let occl = null;
      if (s.junction) {
        const RAPIER = g.RAPIER;
        const jx = s.junction[0] - cam.position.x, jy = s.junction[1] - cam.position.y, jz = s.junction[2] - cam.position.z;
        const want = Math.hypot(jx, jy, jz) || 1;
        const hit = ctx.physics.world.castRay(
          new RAPIER.Ray({ x: cam.position.x, y: cam.position.y, z: cam.position.z },
            { x: jx / want, y: jy / want, z: jz / want }),
          want + 1.0, true, undefined, undefined, undefined, ctx.player.body.body,
        );
        occl = { want: +want.toFixed(2), got: hit ? +hit.timeOfImpact.toFixed(2) : null };
      }
      return { ok: true, above: cam.position.y > surf - 0.5, eye: +cam.position.y.toFixed(1), surf: +surf.toFixed(1), occl, ident };
    }, spec);
    if (!st) continue;
    if (st.ident) for (const q of st.ident) console.log(`[cave-kinds] IDENT ${kind}/${spec.name} ${JSON.stringify(q)}`);
    if (st.above) console.log(`[cave-kinds] ⚠ ${kind}/${spec.name} EYE IS ABOVE GROUND (${st.eye}m vs surface ${st.surf}m) — framing is broken, not the asset`);
    if (st.occl) {
      const { want, got } = st.occl;
      if (got === null || got < want - 0.45) {
        console.log(`[cave-kinds] ⚠ ${kind}/${spec.name} JUNCTION OCCLUDED — the declared mount is ${want}m from the eye `
          + `but the first rock on that line is at ${got === null ? 'NOTHING (the ray left the cave)' : got + 'm'}. `
          + `This frame does NOT show the cap-stem-rock junction; do not grade the mount from it.`);
      } else {
        console.log(`[cave-kinds] ${kind}/${spec.name} junction clear: rock at ${got}m vs the declared mount at ${want}m.`);
      }
    }
    await page.waitForTimeout(120);
    try {
      await page.screenshot({ path: join(OUT, `scen-kind-${kind}-${spec.name}${TAG}.png`), fullPage: false, timeout: 60000 });
      console.log(`[cave-kinds] saved scen-kind-${kind}-${spec.name}${TAG}.png`);
    } catch (e) { console.log(`[cave-kinds] ${kind}/${spec.name} shot flaked (${e.name})`); }
    await page.evaluate(() => {
      const g = window.__game; const ctx = g.ctx;
      const st = window.__kindShotRestore;
      if (st) {
        for (const o of st.hidden) o.visible = true;
        for (const [el, d] of st.dom) el.style.display = d;
        if (ctx.player.viewModel) ctx.player.viewModel.heldPointLight.intensity = st.torchI;
        ctx.three.scene.remove(st.light);
        g.setCaveRockLight(0, 0, 0, 0);
        const cam = ctx.three.camera;
        if (cam.isPerspectiveCamera && st.prevFov !== undefined && cam.fov !== st.prevFov) {
          cam.fov = st.prevFov; cam.updateProjectionMatrix();   // the macro lens is per-framing only
        }
        window.__kindShotRestore = null;
      }
      // UNPAUSE UNCONDITIONALLY — never behind the `st` guard. This helper freezes the world (see
      // the FREEZE FIRST note above) and `main.ts`'s pause gate stops physics, streaming and cave
      // eviction, so an early `return` past this line hands every later leg a frozen world with
      // nothing in its failure text pointing back here. (Cycle 10 paid for this exact shape in the
      // sibling `caveLightShot`: seven cave-kinds failures from one missing unpause.)
      ctx.flags.paused = false;
    });
  }
}

/** The cave interior shot set — the mouth, trunk descent, a squeeze corridor, the large hall, the
 *  egg chamber, a junction looking back up, plus the DARK-TRUTH set (real light model, no rig fill).
 *  Shared by the `cave-walk` gate and the fast `cave-look` iteration scenario so both frame the
 *  IDENTICAL views — the A/B against `verification/baseline-shell/` is only meaningful if the camera
 *  setups are byte-identical between rounds. Writes `verification/scen-<prefix>-<name>.png`. */
async function caveShotSet(page, prefix) {
  {
    const geo = await page.evaluate(() => {
      const ctx = window.__game.ctx; let p = null, b = null;
      ctx.three.scene.traverse((o) => {
        if (o.userData && o.userData.caveGenProbe) p = o.userData.caveGenProbe;
        if (o.userData && o.userData.caveEntranceProbe) b = o.userData.caveEntranceProbe;
      });
      if (!p) return null;
      const egg = p.nodes.find((n) => n.id === p.eggId);
      const hall = p.nodes.find((n) => n.kind === 'hall') || p.nodes.find((n) => n.kind === 'entrance');
      const ent = p.nodes.find((n) => n.kind === 'entrance');
      const squeeze = p.edges.find((e) => e.squeeze);
      const na = squeeze ? p.nodes.find((n) => n.id === squeeze.a) : null;
      const nb = squeeze ? p.nodes.find((n) => n.id === squeeze.b) : null;
      // a trunk corridor for the descent shot: entrance's first child
      const firstEdge = p.edges.find((e) => e.a === ent.id) || p.edges[0];
      const t0 = p.nodes.find((n) => n.id === firstEdge.a), t1 = p.nodes.find((n) => n.id === firstEdge.b);
      return { egg, hall, ent, na, nb, t0, t1, mouthX: b.mouthX, gy: b.gy, cz: b.centerZ, chamberFarX: b.chamberFarX, floor: b.chamberFloorY, wps: b.waypoints, torH: b.torHeight, skyFarX: b.trenchFarX };
    });
    const shoot = async (spec, name) => {
      // Set up + LEAVE it (the render loop keeps rendering the paused scene with this camera, so
      // the setup must persist through the screenshot); restore in a second pass afterward.
      await page.evaluate((s) => {
        const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
        ctx.flags.paused = true;
        ctx.three.renderer.toneMappingExposure = s.exp;
        const cam = ctx.three.camera;
        cam.position.set(s.cam[0], s.cam[1], s.cam[2]);
        cam.lookAt(s.look[0], s.look[1], s.look[2]);
        cam.updateMatrixWorld(true);
        const st = { hidden: [], fill: null, amb: null, bg: ctx.three.scene.background, fog: ctx.three.scene.fog };
        // INTERIOR shots: hide everything but the cave group + dark background, so the one-sided
        // terrain sheet (seen straight through from underground → sky/desert) doesn't fill the frame.
        if (s.interior) {
          let caveGrp = null; ctx.three.scene.traverse((o) => { if (o.name === 'caveGen') caveGrp = o; });
          if (caveGrp) {
            ctx.three.scene.traverse((o) => {
              if (!o.isMesh) return;
              let inCave = false; for (let p = o; p; p = p.parent) if (p === caveGrp) { inCave = true; break; }
              if (!inCave && o.visible) { st.hidden.push(o); o.visible = false; }
            });
            ctx.three.scene.background = new THREE.Color(0x0a0806);
            ctx.three.scene.fog = null;
            // Flat fill ambient so the greybox rock reads evenly (a point light alone leaves the far
            // walls of a big chamber black); the fill lamp below adds a little warm shape on top.
            st.amb = new THREE.AmbientLight(0xb9b0a4, 0.85);
            ctx.three.scene.add(st.amb);
          }
        }
        if (s.fill) {
          st.fill = new THREE.PointLight(0xffe6c0, s.fill.intensity, s.fill.dist, 1.4);
          st.fill.position.set(s.fill.pos[0], s.fill.pos[1], s.fill.pos[2]);
          ctx.three.scene.add(st.fill);
        }
        // UNDERWORLD cycle 3 — render the companion EGG on the dais for the proof shot. DEV boots
        // set companionAcquired → the real ctx.egg is removed at handoff, so build a faithful stand-in
        // (same geometry/material as buildCompanionEgg) at the dais top. Added to the cave group so the
        // interior-hide keeps it. Cleaned up in restore.
        if (s.showEgg) {
          let caveGrp = null; ctx.three.scene.traverse((o) => { if (o.name === 'caveGen') caveGrp = o; });
          const em = new THREE.Mesh(new THREE.SphereGeometry(0.16, 18, 14),
            new THREE.MeshStandardMaterial({ color: 0xcab89a, roughness: 0.55, emissive: 0x6a4420, emissiveIntensity: 1.2 }));
          em.scale.set(1, 1.4, 1);
          em.position.set(s.showEgg[0], s.showEgg[1], s.showEgg[2]);
          (caveGrp || ctx.three.scene).add(em); st.egg = em;
        }
        ctx.three.renderer.render(ctx.three.scene, cam);
        window.__shotRestore = st;
      }, spec);
      await page.waitForTimeout(240);
      try { await page.screenshot({ path: join(OUT, `scen-${prefix}-${name}.png`), fullPage: false, timeout: 60000 }); console.log(`[cave-walk] saved scen-${prefix}-${name}.png`); }
      catch (e) { console.log(`[${prefix}] ${name} shot flaked (${e.name})`); }
      await page.evaluate(() => {
        const ctx = window.__game.ctx; const st = window.__shotRestore; if (!st) return;
        if (st.fill) ctx.three.scene.remove(st.fill);
        if (st.amb) ctx.three.scene.remove(st.amb);
        if (st.egg && st.egg.parent) st.egg.parent.remove(st.egg);
        for (const o of st.hidden) o.visible = true;
        ctx.three.scene.background = st.bg; ctx.three.scene.fog = st.fog;
        window.__shotRestore = null;
      });
    };
    // UNDERWORLD cycle 2 — DARK-TRUTH shots. Unlike the geometry shots above (rig-only flat fill so
    // the greybox reads), these prove the REAL darkness + light model: NO rig fill/ambient. Instead
    // they drive the SHIPPING light objects at their real tuning — the cave darkness floors on
    // ambient/sun/moon, the near-black cave fog, the player's real torch (heldPointLight) for the
    // torch-lit shot, and the atmosphere's mouth SHAFT SpotLight. So a torch-lit hall shows the warm
    // pool + speleothem shadows; an unlit corridor is near-black; the shaft shot shows daylight down
    // the ramp. These use ONLY objects that ship (no probe-invented lights).
    const shootDark = async (spec, name) => {
      await page.evaluate((s) => {
        const g = window.__game; const ctx = g.ctx; const THREE = g.THREE;
        ctx.flags.paused = true;
        ctx.three.renderer.toneMappingExposure = s.exp;
        const cam = ctx.three.camera;
        cam.position.set(s.cam[0], s.cam[1], s.cam[2]);
        cam.lookAt(s.look[0], s.look[1], s.look[2]);
        cam.updateMatrixWorld(true);
        const L = ctx.lights; const T = g.Tuning;
        const st = {
          hidden: [], bg: ctx.three.scene.background, fog: ctx.three.scene.fog,
          amb: L.ambient.intensity, sun: L.sun.intensity, moon: L.moon.intensity,
          torchI: ctx.player.viewModel ? ctx.player.viewModel.heldPointLight.intensity : 0,
          shaftI: ctx.caveAtmosphere ? ctx.caveAtmosphere.shaft.intensity : 0,
          shaftV: ctx.caveAtmosphere ? ctx.caveAtmosphere.shaft.visible : false,
        };
        // Hide everything but the cave group (the one-sided terrain sheet seen from underground would
        // fill the frame with sky/desert). Near-black background so unlit rock reads as black.
        let caveGrp = null; ctx.three.scene.traverse((o) => { if (o.name === 'caveGen') caveGrp = o; });
        const boreGrp = []; ctx.three.scene.traverse((o) => { if (o.name === 'caveEntrance') boreGrp.push(o); });
        ctx.three.scene.traverse((o) => {
          if (!o.isMesh) return;
          let keep = false; for (let p = o; p; p = p.parent) { if (p === caveGrp || p.name === 'caveEntrance') { keep = true; break; } }
          if (!keep && o.visible) { st.hidden.push(o); o.visible = false; }
        });
        ctx.three.scene.background = new THREE.Color(0x020304);
        // REAL cave darkness — the shipping floors (near-black), + the near-black cave fog.
        // LEGACY RIG-LIT CONSTANT (DEEPER cycle 10). This was `AMBIENT_BASE * CAVE_DARK_AMBIENT_FLOOR`
      // = 0.0054 back when the deep target was a multiplier. Cycle 10 replaced that with an ABSOLUTE
      // CAVE_DARK_AMBIENT_LEVEL (0.021 — what the multiplier actually produced in game at the audit
      // clock), so reading the new key here would move this instrument's baseline ~4x. The literal is
      // kept so the pool gate's ratio + unlit-median teeth stay on the axis they were signed off on.
      // (That the rig-lit approximation was 4x darker than shipping is a real, separate divergence.)
      L.ambient.intensity = 0.0054;
        L.sun.intensity = 0; L.moon.intensity = 0;
        ctx.three.scene.fog = new THREE.FogExp2(new THREE.Color(T.CAVE_FOG_HEX), T.CAVE_FOG_DENSITY);
        // The player's REAL torch, at the given position (proves the held light works underground).
        if (s.torch && ctx.player.viewModel) {
          const tl = ctx.player.viewModel.heldPointLight;
          tl.color.setHex(T.TORCH_LIGHT_COLOR_HEX); tl.distance = T.TORCH_LIGHT_DISTANCE;
          tl.intensity = T.TORCH_LIGHT_INTENSITY; tl.position.set(s.torch[0], s.torch[1], s.torch[2]);
        }
        // The REAL mouth shaft (daylight down the ramp) at full daytime intensity.
        if (s.shaft && ctx.caveAtmosphere) { ctx.caveAtmosphere.shaft.visible = true; ctx.caveAtmosphere.shaft.intensity = T.CAVE_SHAFT_INTENSITY; }
        ctx.three.renderer.render(ctx.three.scene, cam);
        window.__shotRestore = st;
      }, spec);
      await page.waitForTimeout(240);
      try { await page.screenshot({ path: join(OUT, `scen-${prefix}-${name}.png`), fullPage: false, timeout: 60000 }); console.log(`[cave-walk] saved scen-${prefix}-${name}.png`); }
      catch (e) { console.log(`[${prefix}] ${name} shot flaked (${e.name})`); }
      await page.evaluate(() => {
        const ctx = window.__game.ctx; const st = window.__shotRestore; if (!st) return;
        const L = ctx.lights;
        for (const o of st.hidden) o.visible = true;
        ctx.three.scene.background = st.bg; ctx.three.scene.fog = st.fog;
        L.ambient.intensity = st.amb; L.sun.intensity = st.sun; L.moon.intensity = st.moon;
        if (ctx.player.viewModel) ctx.player.viewModel.heldPointLight.intensity = st.torchI;
        if (ctx.caveAtmosphere) { ctx.caveAtmosphere.shaft.intensity = st.shaftI; ctx.caveAtmosphere.shaft.visible = st.shaftV; }
        window.__shotRestore = null;
      });
    };
    if (geo) {
      const { egg, hall, ent, na, nb, t0, t1 } = geo;
      // mouth (from the surface, down the trench)
      // ── DEEPER cycle 4 — THE CREVICE APPROACH SET. All at PLAYER EYE HEIGHT on the real terrain,
      //    because the question ("does the outcrop read as a landmark, and does the opening read as
      //    a crevice rather than a doorway?") is only answerable from where the player stands. Three
      //    approach distances + the threshold + the descent + looking back up at the daylight. ──
      const eyeAt = async (dist, name, offZ = 0, pitch = 0) => {
        const p = await page.evaluate((d) => {
          const t = window.__game.ctx.terrain;
          const g = window.__game.ctx; void g;
          return { y: t.pureHeightAt(d.x, d.z) };
        }, { x: geo.mouthX - dist, z: geo.cz + offZ });
        await shoot({
          exp: 1.15,
          cam: [geo.mouthX - dist, p.y + 1.68, geo.cz + offZ],
          look: [geo.mouthX + 2, p.y + 1.68 + pitch, geo.cz],
        }, name);
      };
      await eyeAt(78, 'approach-far', 26);
      await eyeAt(34, 'approach-mid', 11);
      await eyeAt(13, 'approach-near', 3);
      // The THRESHOLD — standing at the lip looking in (the "do I commit?" frame).
      await shoot({ exp: 1.15, cam: [geo.mouthX - 7.5, geo.gy + 2.0, geo.cz], look: [geo.mouthX + 9, geo.gy - 0.4, geo.cz] }, 'threshold');
      // OVERHEAD (W-4.2, Zach: "quite open, especially from above") — plan view from 26m up. The
      // from-above read has no ground framing that can answer it: how big is the rock in plan, and
      // does the fissure read as a hairline crack or an open trench?
      await shoot({ exp: 1.15, cam: [geo.mouthX + 4, geo.gy + 26, geo.cz + 0.01], look: [geo.mouthX + 4, geo.gy, geo.cz] }, 'overhead');
      // THE DESCENT at eye height, a third of the way down the slot, looking on down.
      if (geo.wps && geo.wps.length > 3) {
        const a = geo.wps[2], b2 = geo.wps[Math.min(geo.wps.length - 1, 4)];
        await shoot({ exp: 1.3, cam: [a.x, a.y + 1.68, a.z], look: [b2.x, b2.y + 1.2, b2.z],
          fill: { pos: [a.x + 2, a.y + 1.8, a.z], intensity: 8, dist: 16 } }, 'descent');
        // INSIDE LOOKING BACK OUT — the slot of daylight above you is the whole mood of a descent.
        const c2 = geo.wps[Math.min(geo.wps.length - 1, 4)];
        await shoot({ exp: 1.15, cam: [c2.x, c2.y + 1.68, c2.z], look: [geo.mouthX, geo.gy + 4.0, geo.cz] }, 'lookback');
      }
      await shoot({ exp: 1.25, cam: [geo.mouthX - 8, geo.gy + 1.7, geo.cz], look: [geo.mouthX + 8, geo.gy - 2.0, geo.cz] }, 'mouth');
      // trunk descent — stand in t0 looking toward t1 (down the first corridor)
      await shoot({ interior: true, exp: 1.5, cam: [t0.x, t0.y + 1.7, t0.z], look: [t1.x, t1.y + 1.0, t1.z],
        fill: { pos: [(t0.x + t1.x) / 2, (t0.y + t1.y) / 2 + 1.6, (t0.z + t1.z) / 2], intensity: 15, dist: 30 } }, 'trunk-descent');
      // squeeze corridor
      if (na && nb) await shoot({ interior: true, exp: 1.5, cam: [na.x + (nb.x - na.x) * 0.15, na.y + 1.6, na.z + (nb.z - na.z) * 0.15], look: [nb.x, nb.y + 1.2, nb.z],
        fill: { pos: [(na.x + nb.x) / 2, (na.y + nb.y) / 2 + 1.4, (na.z + nb.z) / 2], intensity: 14, dist: 24 } }, 'squeeze');
      // the large hall
      await shoot({ interior: true, exp: 1.5, cam: [hall.x - hall.rx * 0.8, hall.y + 1.7, hall.z], look: [hall.x + hall.rx, hall.y + hall.height * 0.4, hall.z],
        fill: { pos: [hall.x, hall.y + hall.height * 0.5, hall.z], intensity: 26, dist: 40 } }, 'hall');
      // the egg chamber (the deepest, distinct) — framed from a raised corner looking IN + DOWN toward
      // the central dais (fixes the old black frame: the camera used to sit near/into the far wall and
      // look across at a dark span). Stronger fill for the tall cathedral ceiling.
      await shoot({ interior: true, exp: 1.55, cam: [egg.x - egg.rx * 0.6, egg.y + 2.6, egg.z - egg.rx * 0.5], look: [egg.x + egg.rx * 0.25, egg.y + 0.8, egg.z + egg.rx * 0.15],
        showEgg: [egg.x, egg.y + 0.9 + 0.23, egg.z],   // UNDERWORLD cycle 3 — the companion egg on the dais top
        fill: { pos: [egg.x, egg.y + egg.height * 0.55, egg.z], intensity: 44, dist: 70 } }, 'egg');
      // looking back UP a junction (from the first trunk chamber toward the entrance)
      await shoot({ interior: true, exp: 1.5, cam: [t1.x, t1.y + 1.7, t1.z], look: [ent.x, ent.y + 2.5, ent.z],
        fill: { pos: [(t1.x + ent.x) / 2, (t1.y + ent.y) / 2 + 1.6, (t1.z + ent.z) / 2], intensity: 20, dist: 34 } }, 'junction-up');

      // ── UNDERWORLD cycle 2 DARK-TRUTH + LIFE shots (real light model, no rig fill) ──
      // Find a glowing fungus cap (its emissive teal material) to frame the mushroom shot.
      const fungi = await page.evaluate(() => {
        const ctx = window.__game.ctx; const T = window.__game.Tuning;
        const want = new (window.__game.THREE.Color)(T.CAVE_FUNGI_EMISSIVE_HEX).getHexString();
        const wp = new (window.__game.THREE.Vector3)(); let found = null;
        ctx.three.scene.traverse((o) => {
          if (found || !o.isMesh || !o.material || !o.material.emissive) return;
          if (o.material.emissive.getHexString() === want) { o.getWorldPosition(wp); found = { x: +wp.x.toFixed(2), y: +wp.y.toFixed(2), z: +wp.z.toFixed(2) }; }
        });
        return found;
      });
      console.log(`[cave-walk] fungi cap for shot: ${fungi ? JSON.stringify(fungi) : 'NONE FOUND (no glowing fungi in the scene!)'}`);
      // torch-lit hall — the player's real torch throws a warm pool; speleothems cast shadows.
      // DEEPER cycle 3: the torch used to sit AT the camera aimed across the hall's open middle, so
      // the pool fell past the far wall and out of frame — the shot was near-black and could not
      // judge anything. It is the cave's REAL in-game read (torch light on rock), so it now frames
      // the near WALL at torch range: camera 1.2m off the wall, torch 1.5m ahead of it. This is the
      // shot that decides whether the surface reads as carved rock to a player.
      await shootDark({ exp: 1.25, cam: [hall.x - hall.rx * 0.72, hall.y + 1.7, hall.z], look: [hall.x - hall.rx * 1.05, hall.y + 1.3, hall.z + hall.rx * 0.45],
        torch: [hall.x - hall.rx * 0.84, hall.y + 1.6, hall.z + hall.rx * 0.16] }, 'dark-torch-hall');
      // torch on the FLOOR — the walkable surface at grazing torch light, the read the player spends
      // the most time looking at (and the one the floor attenuation flattens).
      await shootDark({ exp: 1.25, cam: [hall.x, hall.y + 1.7, hall.z], look: [hall.x + hall.rx * 0.55, hall.y - 0.4, hall.z + hall.rx * 0.2],
        torch: [hall.x + hall.rx * 0.2, hall.y + 1.1, hall.z + hall.rx * 0.08] }, 'dark-torch-floor');
      // unlit corridor — no torch: near-black (darkness dominates; the survival stakes).
      await shootDark({ exp: 1.35, cam: [na.x + (nb.x - na.x) * 0.18, na.y + 1.6, na.z + (nb.z - na.z) * 0.18], look: [nb.x, nb.y + 1.2, nb.z] }, 'dark-unlit-corridor');
      // mushroom cluster — torch-lit so stalks read + the caps glow their cool bioluminescence.
      if (fungi) await shootDark({ exp: 1.2, cam: [fungi.x + 1.4, fungi.y + 0.7, fungi.z + 1.4], look: [fungi.x, fungi.y, fungi.z],
        torch: [fungi.x + 1.2, fungi.y + 0.7, fungi.z + 1.2] }, 'mushrooms');
      // mouth light-shaft from INSIDE — stand in the entrance hall, look back up toward the daylight.
      await shootDark({ exp: 1.3, cam: [ent.x, ent.y + 1.7, ent.z], look: [geo.mouthX, geo.floor + 1.2, geo.cz], shaft: true }, 'shaft-inside');
    }
  }
}

/** DEEPER cycle 6 — the CAVE POOL shot set (the hero-visual pass's iteration loop).
 *
 *  Every frame here is the REAL in-game read: the shipping cave darkness floors, the shipping cave
 *  fog, the shipping torch tuning carried at the flame position relative to the eye — and, since the
 *  round-12 code critique, the SHIPPING TONE-MAPPING EXPOSURE (`POOL_SHOT_EXPOSURE`, which must equal
 *  `src/core/scene.ts`'s `renderer.toneMappingExposure`). Rounds 1-11 shot at 1.25-1.35 while claiming
 *  in this very docstring that nothing was brightened — i.e. every look judgement was made ~20-30%
 *  hot. That is fixed: ONE constant, equal to shipping, used by every framing. If the water turns out
 *  to be unreadable at 1.05 in some framing, that is a FINDING to report (it feeds the darkness-taste
 *  pass), never a licence to re-brighten the rig.
 *
 *  THE PIXEL METRICS (round-12 finding 12 — "gate blindness"). `pool-fill`'s water check is a CPU
 *  raycast, which cannot see the fragment `discard`: a pool whose every fragment was discarded would
 *  pass green. So every framing here is now shot TWICE — water visible, then water hidden — and the
 *  per-pixel DIFF of the two renders is the water's true on-screen footprint. From that mask:
 *    · `waterL` mean luminance of the water, `rockL` mean of the lit rock in a ring around it
 *      → `ratio` (finding 1 wants water DARKER than the rock it sits in: ratio < 1),
 *    · `mod%` high-pass modulation of the water region (finding 2's ripple floor),
 *    · `plateau` the worst run of one identical 8-bit value along a scanline (finding 3's banding),
 *    · `inner/outer` the depth cue (the middle must be DARKER than the shallows).
 *  Printed per framing as `[pool-metric]` lines, and returned so `pool-fill` can assert on them.
 *
 *  Writes `verification/scen-<prefix>-<name>.png`. */
const POOL_SHOT_EXPOSURE = 1.05;      // === src/core/scene.ts renderer.toneMappingExposure. Do not raise.

// ── THE PIXEL VERDICT, SHARED (round-13). One definition, used by BOTH `pool-look` (the full
//    12-framing visual pass) and `pool-fill` (the permanent gate in `verify:chunks`, which shoots a
//    3-framing subset). Two harnesses that grade water by two different rules is how a gate drifts
//    away from the thing it is supposed to protect.
const POOL_LIT = ['rim', 'refill', 'graze', 'wade', 'shore', 'flash', 'dimtorch', 'fungi', 'pool2-rim'];
// The DARKER-THAN-ROCK rule is asked only where the torch is actually lighting the rock the pool
// sits in — i.e. standing at/over/in the water. `firstsight`, `graze` and `flash` deliberately frame
// water at 4-12m, where the rock around it is NOT torch-lit and the pool's mirrored glints are
// correctly the brightest thing in the room (that is the "catch your eye in a black room" read the
// feature exists for). Applying a ratio<1 rule there would be a gate measuring the wrong thing.
//   `wade` is excluded from it on purpose and NOT quietly: standing IN the pool puts the water
//   0.5-1.5m from the flame and the only "adjacent rock" in frame at 3-6m, so an inverse-square
//   comparison there measures distance, not albedo. `wade` is held to the un-gameable rule below.
const POOL_NEAR = ['rim', 'refill', 'shore', 'dimtorch', 'pool2-rim'];
//   …which every near framing must pass: the water may never make what is BEHIND it brighter.
//   Same pixels, same lights, water on vs water off — no framing artefact can flatter it.
const POOL_DARKENS = ['rim', 'refill', 'wade', 'shore', 'dimtorch', 'pool2-rim'];
// PLACEMENT-DEPENDENT framings: `fungi` needs a bioluminescent cluster within 26m of the hero pool
// and `pool2-rim` needs the seed to have placed a second pool. Absent ⇒ logged skip. Everything else
// in POOL_LIT is unconditional, and its absence is a FAIL (round-13 sev-3 — the old loop `continue`d
// past any missing framing, so a shot set that silently lost half its framings graded green).
const POOL_OPTIONAL = ['fungi', 'pool2-rim'];

/** Grade one shot set. `want` limits the judgement to framings this run actually shot. Returns fails. */
function poolPixelFails(metrics, want) {
  const fails = [];
  const lit = POOL_LIT.filter((k) => !want || want.includes(k));
  for (const k of lit) {
    const q = metrics[k];
    if (!q) {
      if (POOL_OPTIONAL.includes(k)) { console.log(`[pool-metric] ${k} SKIPPED — placement-dependent framing not available for this seed`); continue; }
      fails.push(`${k}: framing missing from the shot set`); continue;
    }
    if (!q.waterPx) { fails.push(`${k}: the water renders ZERO pixels (fragment discard ate the whole pool)`); continue; }
    // (a) it demonstrably renders — the A/B diff has real extent.
    if (q.pctFrame < 0.5) fails.push(`${k}: water covers only ${q.pctFrame}% of the frame (< 0.5% floor — the framing or the discard is wrong)`);
    // (b) finding 1 — water must be DARKER than the lit rock around it.
    if (POOL_NEAR.includes(k)) {
      // NOT a silent skip any more (round-13 sev-3). `ratio` is null when there is no lit rock in the
      // ring, and these five framings are all defined as "standing at the water with the torch up" —
      // if the surround is unlit, the framing broke, and passing quietly would hide it.
      if (q.ratio === null) fails.push(`${k}: NO lit rock in the ring around the water (rockLitPx=${q.rockLitPx}, rockLitL=${q.rockLitL}) — the darker-than-rock rule could not be evaluated in a framing that is supposed to be torch-lit`);
      // The water side of this comparison is the MEDIAN, not the mean (round-13, found by extending
      // the gate to a second seed). The rule's intent is "the BODY of the water is darker than the
      // rock beside it — a dark mirror, not a bright diffuse floor". The MEAN includes the specular
      // glint path, which is the feature itself: penalising it grades the pool down for answering
      // the torch, which is the one thing it exists to do. On seed 7 the mean ratio read 1.30 and
      // failed — but 78% of the move from seed 1337's 0.73 was the RING ROCK getting dimmer
      // (rockLitL 5.15 → 3.35), not the water getting brighter (waterL 3.75 → 4.35). A rule that
      // swings on how bright the rock happens to be is measuring the rock.
      //   The median is the same discriminator the `unlit` canary already uses and for the same
      //   reason: a mirror is mostly dark with sparse bright glints (low p50, high p99); a glowing
      //   or diffuse sheet lifts every pixel (high p50). Measured p50/rockLitL: seed 1337 rim 0.42,
      //   refill 0.31, shore 0.43, dimtorch 0.06, pool2-rim 0.72; seed 7 rim 0.85.
      //   The MEAN-vs-MEAN comparison is not dropped — it survives in the un-gameable DARKENS rule
      //   below, which compares the water against the very pixels behind it rather than a ring of
      //   different ones, and which seed 7 passes by 3.2×.
      else if (q.p50 > q.rockLitL) fails.push(`${k}: the water's MEDIAN luminance ${q.p50} exceeds the adjacent LIT rock's mean ${q.rockLitL} (ratio of means ${q.ratio}) — the body of the water is brighter than the stone it sits in, i.e. a bright diffuse floor rather than a dark mirror`);
    }
    if (POOL_DARKENS.includes(k) && q.waterL >= q.behindL) fails.push(`${k}: the water (${q.waterL}) is BRIGHTER than the bare rock behind it (${q.behindL}) — a surface that adds light rather than absorbing it`);
    // (c) THE RIPPLE. See the `ripple` metric's block in poolShotSet for why this is a TEMPORAL
    //     measurement and not the spatial high-pass it replaced: measured on the shipping cave, the
    //     spatial number cannot tell a rippling surface (6.8-9.3%) from one with the wave slope
    //     forced to zero (5.2-7.1%) — the distributions overlap and pool2-rim actually scores HIGHER
    //     flat. The temporal number is 0.00 on a flat surface by construction.
    //     Floors: measured shipping minimum is 2.38 levels / 16.98% (`graze`); the floors sit at
    //     ~2.1-2.4× below that, and infinitely above flat.
    if (q.litPx <= 2000) {
      // Also not a silent skip any more: every framing in POOL_LIT is defined as lit.
      fails.push(`${k}: only ${q.litPx} lit water pixels (floor 2000) — a framing that is supposed to be torch-lit has almost no lit water, so the ripple floor could not be evaluated`);
    } else {
      if (q.ripple !== null && q.ripple < 1.0) fails.push(`${k}: ripple motion ${q.ripple} 8-bit levels over 2s of wave time (floor 1.0; a surface with NO ripple measures exactly 0.00, shipping measures 2.4-7.9). r11's failure was 0.14 of one level`);
      if (q.ripplePct !== null && q.ripplePct < 8) fails.push(`${k}: ripple motion is ${q.ripplePct}% of the water's own layer magnitude (floor 8%; shipping measures 17-81%)`);
      // The ORIGINAL quantization question, kept as its own canary: is the water's spatial signal
      // above one 8-bit level at all? This is NOT a ripple test (a flat surface still scores
      // 0.52-0.86 here) — it catches the r11 class where the whole surface collapsed to 0.14 of a
      // level and banded. `mod`/`modTot` are reported alongside as diagnostics and NOT gated,
      // precisely because they were measured to be unable to separate rippled from flat.
      if (q.modAbs !== null && q.modAbs < 0.35) fails.push(`${k}: spatial high-pass ${q.modAbs} of one 8-bit level (floor 0.35) — the water's signal is being eaten by quantization, r11-style`);
    }
    // (d) finding 3 — no 8-bit plateaus across the pool.
    if (q.maxPlateau > 90) fails.push(`${k}: a ${q.maxPlateau}px run of ONE identical 8-bit value (contour banding; dither floor is 90px)`);
    // (d2) FINDING 4 — THE ENVIRONMENT APPEARS IN THE SURFACE. Asked in the `fungi` framing, which
    //      is the one deliberately composed around the nearest bioluminescent cluster (and is
    //      therefore already placement-optional). A mirroring surface carries sparse BRIGHT
    //      highlights: measured p99 76.6 (seed 1337) / 58.0 (seed 7) against a floor of 8.
    if (k === 'fungi' && q.p99 < 8) fails.push(`fungi: the water's 99th-percentile luminance is only ${q.p99} in the framing composed around the nearest emissive cluster — nothing bright is being mirrored (finding 4 regressed; shipping measures 58-77)`);
  }
  // (e) THE SELF-ILLUMINATION CANARY. With no lamp in the room the pool must not GLOW. The
  //     discriminator is the MEDIAN, not the mean: a mirror is mostly black with sparse glints.
  //
  //     WHEN THE WATER RENDERS NOTHING HERE, THAT IS A PASS, and it is stated rather than skipped.
  //     Round-13 first asserted `waterPx > 0` on this framing as a "the surface must mirror
  //     something" proof — and seed 7 failed it. Correctly: this framing's camera is a fixed offset
  //     from the hero pool, so whether a mirrored emitter lands in its reflection lobe depends on
  //     where that seed put its fungi (seed 1337's hero pool has a cluster 2.5m away and 5 live
  //     emitter slots; seed 7's has 2, and none of them reflect into this pose). A pool that
  //     correctly shows NOTHING in a black room is the desired behaviour and satisfies this canary
  //     trivially — it is not evidence of a broken mirror. The mirroring proof lives where it is
  //     actually well-founded: the `fungi` framing's p99 above, and the emitter-publication
  //     assertion in `pool-fill` leg 6.
  const u = metrics['unlit'];
  if (want && !want.includes('unlit')) { /* not shot */ }
  else if (!u) fails.push('unlit: framing missing from the shot set — the self-illumination canary did not run');
  else if (!u.waterPx) console.log(`[pool-metric] unlit: water changes no pixel by ≥2/255 with no lamp in the room (anyPx=${u.anyPx}) — nothing to mirror from this pose; the no-glow canary passes trivially`);
  else {
    if (u.p50any > 0.6) fails.push(`unlit: MEDIAN luminance ${u.p50any} across the water's whole footprint with no lamp in the room — the surface is self-illuminating, not mirroring`);
    if (u.ratio !== null && u.ratio > 1.0) fails.push(`unlit: the water (${u.waterL}) is brighter than the emissive features it mirrors (${u.rockLitL})`);
    // …and when it DOES render here, those pixels must be sparse GLINTS, not a wash.
    if (u.p99 < 8) fails.push(`unlit: the water renders ${u.waterPx}px with no lamp but its 99th-percentile luminance is only ${u.p99} — that is a uniform wash, not mirrored glints (shipping measures ~110)`);
  }
  return fails;
}

/** `opts.only` — a Set/array of framing names to shoot (default: all of them). `opts.shots:false`
 *  skips the PNG writes and the settle wait, which is what the permanent `pool-fill` gate uses: it
 *  wants the pixel METRICS, not the pictures, and the screenshots are most of the wall clock. */
async function poolShotSet(page, prefix, opts = {}) {
  const only = opts.only ? new Set(opts.only) : null;
  const wantShots = opts.shots !== false;
  const geo = await page.evaluate(() => {
    const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const T = g.Tuning;
    let p = null;
    ctx.three.scene.traverse((o) => { if (o.userData && o.userData.caveGenProbe) p = o.userData.caveGenProbe; });
    if (!p || !(p.pools || []).length) return null;
    const pools = p.pools.slice().sort((a, b) => b.r - a.r).map((q) => {
      const n = p.nodes.find((x) => x.id === q.node) || { x: q.x, y: q.y - 0.26, z: q.z, rx: 6, kind: '?' };
      return { x: q.x, y: q.y, z: q.z, r: q.r, node: q.node, nx: n.x, nz: n.z, nrx: n.rx, floorY: n.y, nkind: n.kind };
    });
    // Nearest bioluminescent cap to the hero pool — the "light context changes everything" variant.
    const want = new THREE.Color(T.CAVE_FUNGI_EMISSIVE_HEX).getHexString();
    const wp = new THREE.Vector3(); let best = null, bd = 1e9;
    ctx.three.scene.traverse((o) => {
      if (!o.isMesh || !o.material || !o.material.emissive) return;
      if (o.material.emissive.getHexString() !== want) return;
      o.getWorldPosition(wp);
      const d = Math.hypot(wp.x - pools[0].x, wp.z - pools[0].z);
      if (d < bd) { bd = d; best = { x: +wp.x.toFixed(2), y: +wp.y.toFixed(2), z: +wp.z.toFixed(2), d: +d.toFixed(1) }; }
    });
    return { pools, fungi: best };
  });
  // A NAMED FAIL, not a silent `return undefined` (round-13 sev-3): the old early-return handed the
  // caller `undefined`, which then threw a bare TypeError on `m['rim']` — an unreadable crash for
  // what is actually a hard content regression. Every cave is guaranteed ≥1 pool
  // (CAVE_POOL_CHAMBERS_MIN), so zero pools is a placement bug, not a "nothing to shoot" condition.
  if (!geo) throw new Error('poolShotSet: the cave exposes NO pools (or no caveGenProbe at all) — placement regression? CAVE_POOL_CHAMBERS_MIN guarantees ≥1.');
  console.log('[pool-look] pools=' + JSON.stringify(geo.pools.map((q) => 'n' + q.node + '@(' + q.x.toFixed(1) + ',' + q.z.toFixed(1) + ')r' + q.r.toFixed(1) + ' ' + q.nkind)) + ' fungi=' + JSON.stringify(geo.fungi));

  const metrics = {};
  const shoot = async (s, name) => {
    if (only && !only.has(name)) return;
    const m = await page.evaluate((s) => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const T = g.Tuning;
      ctx.flags.paused = true;
      ctx.three.renderer.toneMappingExposure = s.exp;
      const cam = ctx.three.camera;
      cam.position.set(s.cam[0], s.cam[1], s.cam[2]);
      cam.lookAt(s.look[0], s.look[1], s.look[2]);
      cam.updateMatrixWorld(true);
      const L = ctx.lights;
      const st = {
        hidden: [], added: [], bg: ctx.three.scene.background, fog: ctx.three.scene.fog,
        amb: L.ambient.intensity, sun: L.sun.intensity, moon: L.moon.intensity,
        torchI: ctx.player.viewModel ? ctx.player.viewModel.heldPointLight.intensity : 0,
      };
      // Hide everything outside the cave (the one-sided terrain sheet, seen from below, would fill
      // the frame with sky + desert). Background pure black: unlit rock must read as unlit.
      let caveGrp = null; ctx.three.scene.traverse((o) => { if (o.name === 'caveGen') caveGrp = o; });
      ctx.three.scene.traverse((o) => {
        if (!o.isMesh) return;
        let keep = false;
        for (let q = o; q; q = q.parent) { if (q === caveGrp || q.name === 'caveEntrance') { keep = true; break; } }
        if (!keep && o.visible) { st.hidden.push(o); o.visible = false; }
      });
      ctx.three.scene.background = new THREE.Color(0x000000);
      if (ctx.player.viewModel) ctx.player.viewModel.heldPointLight.intensity = 0;
      // THE REAL LIGHT MODEL — the shipping cave floors + the shipping near-black cave fog.
      // LEGACY RIG-LIT CONSTANT (DEEPER cycle 10). This was `AMBIENT_BASE * CAVE_DARK_AMBIENT_FLOOR`
      // = 0.0054 back when the deep target was a multiplier. Cycle 10 replaced that with an ABSOLUTE
      // CAVE_DARK_AMBIENT_LEVEL (0.021 — what the multiplier actually produced in game at the audit
      // clock), so reading the new key here would move this instrument's baseline ~4x. The literal is
      // kept so the pool gate's ratio + unlit-median teeth stay on the axis they were signed off on.
      // (That the rig-lit approximation was 4x darker than shipping is a real, separate divergence.)
      L.ambient.intensity = 0.0054;
      L.sun.intensity = 0; L.moon.intensity = 0;
      ctx.three.scene.fog = new THREE.FogExp2(new THREE.Color(T.CAVE_FOG_HEX), T.CAVE_FOG_DENSITY);
      if (s.light !== 'none') {
        const fwd = new THREE.Vector3(); cam.getWorldDirection(fwd);
        const right = new THREE.Vector3().crossVectors(fwd, new THREE.Vector3(0, 1, 0)).normalize();
        // Where the game actually puts the flame: ahead + right + a little below the eye.
        const lp = cam.position.clone().addScaledVector(fwd, 0.45).addScaledVector(right, 0.30);
        lp.y -= 0.28;
        if (s.light === 'flashlight') {
          const sp = new THREE.SpotLight(T.FLASHLIGHT_LIGHT_COLOR_HEX, T.FLASHLIGHT_LIGHT_INTENSITY,
            T.FLASHLIGHT_LIGHT_DISTANCE, T.FLASHLIGHT_LIGHT_ANGLE_RAD, T.FLASHLIGHT_LIGHT_PENUMBRA, 1.2);
          sp.position.copy(lp); sp.target.position.set(s.look[0], s.look[1], s.look[2]);
          ctx.three.scene.add(sp); ctx.three.scene.add(sp.target); st.added.push(sp, sp.target);
        } else {
          const tl = new THREE.PointLight(T.TORCH_LIGHT_COLOR_HEX,
            T.TORCH_LIGHT_INTENSITY * (s.torchMul || 1), T.TORCH_LIGHT_DISTANCE, 2);
          tl.position.copy(lp); ctx.three.scene.add(tl); st.added.push(tl);
        }
      }
      // ── THE A/B PIXEL METRIC (finding 12). Render with the water, read the framebuffer; hide every
      //    `cavePoolWater` mesh, render, read again; the DIFF mask is the water's true rendered
      //    footprint — a mask the CPU raycast cannot fake and the fragment `discard` cannot hide.
      const R = ctx.three.renderer, gl = R.getContext();
      const W = R.domElement.width, H = R.domElement.height;
      const read = () => { R.render(ctx.three.scene, cam); const px = new Uint8Array(W * H * 4); gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px); return px; };
      const on = read();
      const waters = []; ctx.three.scene.traverse((o) => { if (o.isMesh && o.name === 'cavePoolWater' && o.visible) waters.push(o); });
      for (const o of waters) o.visible = false;
      const off = read();
      for (const o of waters) o.visible = true;
      R.render(ctx.three.scene, cam);          // leave the canvas showing the real frame for the screenshot
      window.__shotRestore = st;

      const lum = (p, i) => 0.2126 * p[i] + 0.7152 * p[i + 1] + 0.0722 * p[i + 2];
      // TWO masks, and the difference between them matters (round-12g). ANY non-zero diff proves the
      // water RENDERS there — that is the existence check the CPU raycast could never make. But the
      // water mesh reaches 1.10m past the rim and fades to alpha≈0 over the last of it, so an
      // any-diff mask is up to 90% of the frame and is mostly DRY ROCK that the outermost fragment
      // nudged by one LSB. Grading appearance on that mask measures the rock, not the water: it is
      // why r12c-f reported a flat ~5% "ripple modulation" no matter what the ripple did. The
      // appearance metrics use the ≥2/255 mask — where the water is actually doing something.
      const maskAny = new Uint8Array(W * H), mask = new Uint8Array(W * H);
      let nAny = 0, n = 0, sumOn = 0, sumOff = 0, cx = 0, cy = 0;
      for (let i = 0, k = 0; k < W * H; k++, i += 4) {
        const d0 = Math.abs(on[i] - off[i]), d1 = Math.abs(on[i + 1] - off[i + 1]), d2 = Math.abs(on[i + 2] - off[i + 2]);
        const dm = Math.max(d0, d1, d2);
        if (dm === 0) continue;
        maskAny[k] = 1; nAny++;
        if (dm < 2) continue;
        mask[k] = 1; n++;
        sumOn += lum(on, i); sumOff += lum(off, i);
        cx += k % W; cy += (k / W) | 0;
      }
      if (!nAny) return { waterPx: 0, note: 'NO water pixels — the water renders NOTHING in this framing' };
      if (!n) return { waterPx: 0, anyPx: nAny, note: 'water renders, but changes NO pixel by ≥2/255 — invisible in practice' };
      cx /= n; cy /= n;
      // Adjacent rock: a dilation ring outside the mask (RING px), lit pixels only (L ≥ 2).
      const RING = 16;
      let rn = 0, rsum = 0, rlit = 0, rlitSum = 0;
      for (let k = 0; k < W * H; k++) {
        if (mask[k]) continue;
        const x = k % W, y = (k / W) | 0;
        let near = false;
        for (let dy = -RING; dy <= RING && !near; dy += 4) {
          const yy = y + dy; if (yy < 0 || yy >= H) continue;
          for (let dx = -RING; dx <= RING; dx += 4) {
            const xx = x + dx; if (xx < 0 || xx >= W) continue;
            if (mask[yy * W + xx]) { near = true; break; }
          }
        }
        if (!near) continue;
        const L = lum(on, k * 4); rn++; rsum += L;
        if (L >= 2) { rlit++; rlitSum += L; }
      }
      // ── RIPPLE MODULATION — measured on the WATER LAYER, not on the frame (round-13 metric fix).
      //
      //   THE BUG IN THE OLD METRIC. It was |L − localmean(L)| / mean(L) over the lit water: a
      //   high-pass normalised by TOTAL pixel value. But total pixel value in a shallow pool is
      //   dominated by TRANSMISSION — the lit rock you can see through the water. `shore` measured
      //   mean L 16.8 against `rim`'s 5.0, so the same physical ripple scored ~1/3 there purely
      //   because the denominator was 3.4× bigger. That is a gate measuring the wrong thing (the
      //   bottom's brightness), and it produced two false reds — shore 6.98% and pool2-rim 11.29% —
      //   that a visual critic confirmed by eye were correct, rippling water.
      //
      //   THE FIX. Work in the A/B DIFFERENCE layer D = L(water on) − L(water off): the water's own
      //   contribution, with the bare rock behind it algebraically removed. Both the high-pass AND
      //   its normaliser now live in that layer — mean|D − localmean(D)| / mean|D| — so a brighter
      //   bottom scales numerator and denominator together and cancels. A sheet that uniformly
      //   attenuates a uniform bottom has constant D and scores 0 no matter how bright the bottom
      //   is; a rippling sheet scores its true structure fraction. `modTot` (the OLD number) is kept
      //   alongside so this recalibration stays auditable, and `modAbs` reports the raw high-pass in
      //   8-bit LEVELS, which is the original quantization question ("0.14 of one level").
      //
      //   Measured on the LIT water only (≥2/255, the same signal floor the banding scan uses). Over
      //   near-black water the ratio is meaningless in both directions — quantization noise inflates it
      //   (the unlit frame reports 90%+ off two dozen glint pixels) and a large dead area deflates it.
      //   BOX is +-10px, strided by 2. The band scale that matters here is the caustic/glint structure,
      //   which measures 10-25px across at these framings; a +-4px box (round-12c-f) partially TRACKED
      //   those bands and so subtracted the very signal it was meant to detect, pinning every framing
      //   near 5% no matter what the ripple did. The stride keeps the cost sane at 400-500k lit pixels.
      const BOX = 10, STEP = 2;
      let hpD = 0, hpL = 0, hpN = 0, litSum = 0, absD = 0, litN = 0;
      for (let k = 0; k < W * H; k++) {
        if (!mask[k] || on[k * 4 + 1] < 2) continue;
        const x = k % W, y = (k / W) | 0;
        let s2 = 0, s2d = 0, c2 = 0;
        for (let dy = -BOX; dy <= BOX; dy += STEP) {
          const yy = y + dy; if (yy < 0 || yy >= H) continue;
          for (let dx = -BOX; dx <= BOX; dx += STEP) {
            const xx = x + dx; if (xx < 0 || xx >= W) continue;
            const kk = yy * W + xx; if (!mask[kk]) continue;
            s2 += lum(on, kk * 4); s2d += lum(on, kk * 4) - lum(off, kk * 4); c2++;
          }
        }
        if (c2 < 12) continue;
        const Lk = lum(on, k * 4), Dk = Lk - lum(off, k * 4);
        hpL += Math.abs(Lk - s2 / c2);
        hpD += Math.abs(Dk - s2d / c2);
        absD += Math.abs(Dk);
        hpN++; litSum += Lk; litN++;
      }
      // ── RIPPLE MOTION — THE METRIC WITH TEETH (round-13).
      //
      //   Why a THIRD metric had to be built. `mod` above (and `modTot` before it) is a spatial
      //   high-pass, and a pool's frame is FULL of spatial structure that is not the ripple: the
      //   output dither (±1 level by design), the gravel-scale alpha noise, the waterline jitter,
      //   the depth gradient, and the rock bottom's own texture read through the water. Measured on
      //   the shipping cave, the six large lit framings score 6.8-9.3 with the ripple ON — and
      //   5.2-7.1 with the wave slope forced to ZERO (`--flat=spec`). The distributions OVERLAP:
      //   pool2-rim scores HIGHER flat (7.11) than rippled (6.78). No floor on a spatial high-pass
      //   can separate those, so no floor on it is a gate. Shipping one would have been this
      //   project's own worst failure mode — a number that launders a dead surface as verified.
      //
      //   What is unique to the ripple is that it MOVES. So: render the same pixels again with
      //   `uPoolTime` advanced, and difference them. Dither is screen-space (identical), the gravel
      //   and jitter noises are world-space static, the bottom is static, the lights have not moved
      //   — the wave field is the ONLY thing in the frame that changed. A surface with no ripple
      //   returns ~0 by construction, which is what a floor needs underneath it.
      //   ΔT = 2.0s: the base wave turns 0.44 rad and the k=31 octave 1.78 rad, so both the slow
      //   swell and the glint-shatter octaves have visibly moved without the metric depending on
      //   catching a particular phase.
      //
      //   REPRODUCE THE CALIBRATION:
      //     npm run rig -- --scenario=pool-look --port=52xx --flat=all --framings=rim,refill,shore
      //   Measured 2026-07-26, seed 1337, exposure 1.05:
      //     flat=all  rim/refill/graze/wade/shore → ripple 0.00, ripplePct 0.00  (exactly zero)
      //     shipping  the same five             → ripple 2.6-3.0, ripplePct 17.1-21.4
      //   (`--flat` patches the LIVE uniforms, so a framing that forces three to recompile the
      //   program — `flash`, which swaps the PointLight for a SpotLight — gets a fresh unpatched
      //   shader and reports shipping numbers again. That is why the calibration set stops at the
      //   five same-light framings.)
      let rip = 0, ripN = 0;
      {
        const shaders = [];
        for (const o of waters) {
          const ss = o.material && o.material.userData && o.material.userData.poolShaders;
          if (ss) for (const q of ss) if (shaders.indexOf(q) < 0) shaders.push(q);
        }
        const t0 = (shaders[0] && shaders[0].uniforms.uPoolTime) ? shaders[0].uniforms.uPoolTime.value : 0;
        for (const q of shaders) if (q.uniforms.uPoolTime) q.uniforms.uPoolTime.value = t0 + 2.0;
        const mov = read();
        for (const q of shaders) if (q.uniforms.uPoolTime) q.uniforms.uPoolTime.value = t0;
        for (let k = 0; k < W * H; k++) {
          if (!mask[k] || on[k * 4 + 1] < 2) continue;
          rip += Math.abs(lum(on, k * 4) - lum(mov, k * 4)); ripN++;
        }
        R.render(ctx.three.scene, cam);        // put the un-advanced frame back for the screenshot
      }

      // Banding: longest run of ONE identical green byte along a scanline inside the mask. Only over
      // pixels carrying actual SIGNAL (≥2/255): a long run of pure black is a black room, not a
      // contour band, and counting it would make this metric measure the wrong thing.
      let maxPlat = 0, platSum = 0, platN = 0; const levels = new Set();
      for (let y = 0; y < H; y++) {
        let run = 0, prev = -1;
        for (let x = 0; x < W; x++) {
          const k = y * W + x;
          if (!mask[k] || on[k * 4 + 1] < 2) { if (run > 1) { platSum += run; platN++; if (run > maxPlat) maxPlat = run; } run = 0; prev = -1; continue; }
          const gV = on[k * 4 + 1]; levels.add(gV);
          if (gV === prev) run++; else { if (run > 1) { platSum += run; platN++; if (run > maxPlat) maxPlat = run; } run = 1; prev = gV; }
        }
        if (run > 1) { platSum += run; platN++; if (run > maxPlat) maxPlat = run; }
      }
      // Depth cue: mean L of the mask's inner third vs its outer third (by radius from the centroid).
      const rad = []; for (let k = 0; k < W * H; k++) if (mask[k]) rad.push(Math.hypot((k % W) - cx, ((k / W) | 0) - cy));
      rad.sort((a, b) => a - b);
      const rIn = rad[(rad.length / 3) | 0], rOut = rad[((rad.length * 2) / 3) | 0];
      let inS = 0, inN = 0, outS = 0, outN = 0;
      for (let k = 0; k < W * H; k++) {
        if (!mask[k]) continue;
        const r2 = Math.hypot((k % W) - cx, ((k / W) | 0) - cy);
        if (r2 <= rIn) { inS += lum(on, k * 4); inN++; } else if (r2 >= rOut) { outS += lum(on, k * 4); outN++; }
      }
      // Percentiles of the water's own luminance. The MEDIAN is the honest test for
      // self-illumination: a pool that mirrors a few bright things is mostly black with sparse
      // glints (low p50, high p99), whereas a pool that GLOWS lifts every pixel (high p50).
      const allL = new Float32Array(n);
      for (let k = 0, j = 0; k < W * H; k++) if (mask[k]) allL[j++] = lum(on, k * 4);
      allL.sort();
      const pct = (q) => allL[Math.min(n - 1, Math.floor(q * n))];
      // …and the median over the FULL footprint (any-diff), which is the self-illumination canary:
      // a mirror is mostly black with sparse glints, a glowing sheet lifts every pixel it covers.
      const anyL = new Float32Array(nAny);
      for (let k = 0, j = 0; k < W * H; k++) if (maskAny[k]) anyL[j++] = lum(on, k * 4);
      anyL.sort();
      const p50any = anyL[Math.floor(nAny / 2)];
      const f2 = (v) => +v.toFixed(2);
      const waterL = sumOn / n, rockL = rlit ? rlitSum / rlit : 0;
      return {
        waterPx: n, anyPx: nAny, pctFrame: f2((100 * n) / (W * H)),
        waterL: f2(waterL), p50: f2(pct(0.5)), p99: f2(pct(0.99)), p50any: f2(p50any), behindL: f2(sumOff / n),
        rockAllL: rn ? f2(rsum / rn) : 0, rockLitL: f2(rockL), rockLitPx: rlit,
        ratio: rockL > 0.05 ? f2(waterL / rockL) : null,
        // `mod` = the GATED metric (water-layer relative high-pass). `modTot` = the pre-round-13
        // total-value normalisation, kept as a diagnostic. `modAbs` = the same high-pass in 8-bit
        // levels — the literal "is the ripple above one quantization step" question.
        mod: hpN ? f2((100 * (hpD / hpN)) / Math.max(0.5, absD / hpN)) : null,
        modTot: hpN ? f2((100 * (hpL / hpN)) / Math.max(0.01, litSum / litN)) : null,
        modAbs: hpN ? f2(hpD / hpN) : null,
        waterLayerL: hpN ? f2(absD / hpN) : null,
        // The gated one: mean |ΔL| over the lit water when uPoolTime advances 2s, in 8-bit LEVELS,
        // and the same as a % of the water's own layer magnitude. ~0 on a surface with no ripple.
        ripple: ripN ? f2(rip / ripN) : null,
        ripplePct: (ripN && hpN) ? f2((100 * (rip / ripN)) / Math.max(0.5, absD / hpN)) : null,
        ripplePx: ripN,
        litPx: litN,
        maxPlateau: maxPlat, meanPlateau: platN ? f2(platSum / platN) : 0, levels: levels.size,
        innerL: inN ? f2(inS / inN) : 0, outerL: outN ? f2(outS / outN) : 0,
      };
    }, s);
    if (wantShots) {
      await page.waitForTimeout(200);
      try { await page.screenshot({ path: join(OUT, 'scen-' + prefix + '-' + name + '.png'), fullPage: false, timeout: 60000 }); console.log('[pool-look] saved scen-' + prefix + '-' + name + '.png'); }
      catch (e) { console.log('[pool-look] ' + name + ' shot flaked (' + e.name + ')'); }
    }
    metrics[name] = m;
    console.log('[pool-metric] ' + name.padEnd(11) + ' ' + JSON.stringify(m));
    await page.evaluate(() => {
      const ctx = window.__game.ctx; const st = window.__shotRestore; if (!st) return;
      const L = ctx.lights;
      for (const o of st.added) ctx.three.scene.remove(o);
      for (const o of st.hidden) o.visible = true;
      ctx.three.scene.background = st.bg; ctx.three.scene.fog = st.fog;
      L.ambient.intensity = st.amb; L.sun.intensity = st.sun; L.moon.intensity = st.moon;
      if (ctx.player.viewModel) ctx.player.viewModel.heldPointLight.intensity = st.torchI;
      window.__shotRestore = null;
    });
  };

  const P = geo.pools[0];
  // "Toward the chamber centre" — the side with open floor, i.e. where a player would stand.
  let ix = P.nx - P.x, iz = P.nz - P.z;
  const IL = Math.hypot(ix, iz) || 1; ix /= IL; iz /= IL;
  const EYE = 1.68;

  const EXP = POOL_SHOT_EXPOSURE;
  // (a) FIRST SIGHT — walking into the chamber with the torch up. ~7m out; the pool is the thing
  //     that has to catch your eye in a black room.
  await shoot({ exp: EXP, cam: [P.x + ix * (P.r + 7.0), P.floorY + EYE, P.z + iz * (P.r + 7.0)],
    look: [P.x, P.y - 0.05, P.z] }, 'firstsight');
  // (b) THE RIM — standing right over the edge, looking DOWN at the near water, not across at the
  //     far side. (Round 1 aimed at the pool CENTRE from r+1.2m: at a 21 degree pitch the whole
  //     near half of the pool fell below the frame and the shot graded water that was 4-6m away,
  //     i.e. past the torch's useful range. The read that decides "water or chalky disc" is the
  //     water inside the torch pool, at your feet.)
  await shoot({ exp: EXP, cam: [P.x + ix * (P.r * 0.98), P.floorY + EYE, P.z + iz * (P.r * 0.98)],
    look: [P.x + ix * P.r * 0.18, P.y - 0.02, P.z + iz * P.r * 0.18] }, 'rim');
  // (b2) THE REFILL POSE — the single most-played camera in this feature: standing at the edge with
  //     the crosshair ON the water, about to press E. It is also the ONE pose where the geometry lets
  //     you see the torch's own reflection: a light carried at the eye mirrors to a point roughly
  //     halfway between your feet and the flame, so it lands on water only when you are over it and
  //     looking down. (Rounds 1-4 all framed from further back and higher, which is why the specular
  //     kept falling outside the frame and the water kept grading "no reflection".)
  //     ROUND-12 REFRAME. At the round-11 aim (1.0m ahead, pitch ≈ -55°) the mirror of a light carried
  //     AT the eye lands ~0.25m in front of you — 23° below the view axis, i.e. two-thirds of the way
  //     down the frame, right where the hotbar DOM sits in a real screenshot. Aiming 0.42m ahead
  //     (pitch ≈ -73°) puts the same reflection ~13% below frame centre: the glint path now runs up
  //     through the upper-centre third with the far water above it, clear of the HUD.
  await shoot({ exp: EXP, cam: [P.x + ix * (P.r * 0.92), P.floorY + EYE, P.z + iz * (P.r * 0.92)],
    look: [P.x + ix * (P.r * 0.92 - 0.42), P.y - 0.02, P.z + iz * (P.r * 0.92 - 0.42)] }, 'refill');
  // (c) GRAZING — from the near rim across the surface to the FAR rim. Water is most reflective
  //     exactly here, so this is where a wrong Fresnel reads as ice.
  await shoot({ exp: EXP, cam: [P.x + ix * (P.r + 0.7), P.floorY + 1.30, P.z + iz * (P.r + 0.7)],
    look: [P.x - ix * P.r * 1.02, P.y + 0.05, P.z - iz * P.r * 1.02] }, 'graze');
  // (d) MID-WADE — standing IN it, looking down at your feet through the water. The bottom you see
  //     here is the collider you are standing on (rule 9), so it had better read as a bottom.
  await shoot({ exp: EXP, cam: [P.x, P.floorY + EYE - 0.10, P.z],
    look: [P.x + ix * 0.85, P.floorY - 0.10, P.z + iz * 0.85] }, 'wade');
  // (e) THE WATERLINE, close. Crouched at the shore: does stone meet water, or does a disc end?
  await shoot({ exp: EXP, cam: [P.x + ix * (P.r + 1.05), P.floorY + 1.05, P.z + iz * (P.r + 1.05)],
    look: [P.x + ix * P.r * 0.86, P.y - 0.06, P.z + iz * P.r * 0.86] }, 'shore');
  // (f) FLASHLIGHT — a cool-white narrow beam instead of the warm point. Different light, different
  //     water; both must work.
  await shoot({ exp: EXP, light: 'flashlight', cam: [P.x + ix * (P.r + 1.4), P.floorY + EYE, P.z + iz * (P.r + 1.4)],
    look: [P.x - ix * P.r * 0.35, P.y, P.z - iz * P.r * 0.35] }, 'flash');
  // (f2) DIM TORCH ON THE WATER — the round-11 "chalk bug" regime had ZERO coverage: a torch burned
  //     down to a third, aimed straight at the surface. This is where an UNLIT additive term (a raw
  //     Fresnel colour wash) stops being a whisper and becomes self-illumination.
  await shoot({ exp: EXP, torchMul: 0.30, cam: [P.x + ix * (P.r * 0.95), P.floorY + EYE, P.z + iz * (P.r * 0.95)],
    look: [P.x - ix * P.r * 0.30, P.y - 0.02, P.z - iz * P.r * 0.30] }, 'dimtorch');
  // (g) UNLIT — no torch at all. The honest question: with nothing to reflect, is it a black hole in
  //     the floor? (It should be near-invisible, not a bright artefact.)
  await shoot({ exp: EXP, light: 'none', cam: [P.x + ix * (P.r + 1.2), P.floorY + EYE, P.z + iz * (P.r + 1.2)],
    look: [P.x, P.y, P.z] }, 'unlit');
  // (h) MUSHROOM CONTEXT — the pool framed with the nearest bioluminescent cluster in shot, torch
  //     dimmed to a third so the cool glow actually contributes.
  if (geo.fungi && geo.fungi.d < 26) {
    let fx = geo.fungi.x - P.x, fz = geo.fungi.z - P.z;
    const FL = Math.hypot(fx, fz) || 1; fx /= FL; fz /= FL;
    await shoot({ exp: EXP, torchMul: 0.34,
      cam: [P.x - fx * (P.r + 2.6), P.floorY + EYE, P.z - fz * (P.r + 2.6)],
      look: [geo.fungi.x, geo.fungi.y - 0.2, geo.fungi.z] }, 'fungi');
  }
  // (i) A SECOND POOL, if the seed placed one — one pool looking right is not the material looking
  //     right (the shared-material discipline from the rusted-hull canon).
  if (geo.pools[1]) {
    const Q = geo.pools[1];
    let qx = Q.nx - Q.x, qz = Q.nz - Q.z;
    const QL = Math.hypot(qx, qz) || 1; qx /= QL; qz /= QL;
    // ROUND-12: pool2 graded "no reflection at all" — 100% of its playfield under L16. The round-11
    // framing aimed at the pool CENTRE from r+1.4m, i.e. a 25° pitch onto water 3-6m away, past the
    // torch's useful throw AND past the near-specular geometry. That is a SHOT bug, not a material
    // bug, so it is fixed here: pool 2 gets the same over-the-edge aim as the hero pool's `rim`.
    await shoot({ exp: EXP, cam: [Q.x + qx * (Q.r * 0.98), Q.floorY + EYE, Q.z + qz * (Q.r * 0.98)],
      look: [Q.x + qx * Q.r * 0.18, Q.y - 0.02, Q.z + qz * Q.r * 0.18] }, 'pool2-rim');
    // …and the round-11 framing kept as-is, so the "does it hold up across the room" question is
    // still asked honestly rather than framed away.
    await shoot({ exp: EXP, cam: [Q.x + qx * (Q.r + 1.4), Q.floorY + EYE, Q.z + qz * (Q.r + 1.4)],
      look: [Q.x, Q.y, Q.z] }, 'pool2-far');
  }
  return metrics;
}

/* ══════════════════════════════════════════════════════════════════════════════════════════════
   DEEPER cycle 10 — LIGHT & DARKNESS INTEGRITY. Two teeth, one instrument.

   Zach's walk-test, verbatim: *"the caves are brighter during the day and darker at night so the
   light looks like it is penetrating the terrain … also i can see the sun slightly through the
   terrain and i think the moon as well"*. Both are measurable, so both get a number:

     A. DAY-INVARIANCE. The same DEEP framing is shot at NOON and at MIDNIGHT with no carried
        light. A deep chamber is sealed under tens of metres of rock; its read must not know what
        the sun is doing. `meanL` and `p95` must agree within DITHER tolerance across the two.
        (Not zero: the rock shader dithers, and the frame is re-rendered, so ±0.15 code of jitter
        is expected. The pre-fix delta is ~2.6× the mean, i.e. hundreds of times the tolerance.)
     B. NO SKY BODY THROUGH ROCK. The same deep chamber, framed 80° UP so the zenith is inside the
        frustum, with no carried light, rendered TWICE in one turn — as shipped, and with the sun +
        moon sprites hidden — and diffed per pixel. ZERO pixels may change. NOON puts the sun at
        the zenith, MIDNIGHT puts the moon there (it sits opposite the sun), and a vacuity guard
        fails the run if the body is not actually in-frustum and being drawn.

   Runs against BOTH cave populations: the origin cave (`--kind=origin`) and a STREAMED kind cave
   (`--kind=warren|fungal|flooded|shaft`), because the plural-cave world is exactly where the
   origin-scoped cycle-7 fix stopped applying.
   ══════════════════════════════════════════════════════════════════════════════════════════════ */

const CAVE_LIGHT_EYE = 1.68;
// The tolerance on A, CALIBRATED against the fixed build rather than guessed. Post-fix, across the
// origin cave and all four streamed kinds, the noon↔midnight Δ on meanL/p95 measured 0.000-0.002 —
// the residual is float noise in the tick, not light. 0.03 is 15× that headroom and still small
// enough to have caught the ORIGIN cave's own (much milder, sub-code) pre-fix coupling of 0.035;
// the streamed caves' coupling was Δ13.7, i.e. 450× this bound.
const CAVE_LIGHT_DAY_TOL = 0.03;
// Reporting-only: the fraction of the frame above this luminance is printed alongside the A/B so a
// reader can see at a glance whether anything bright is in shot at all. NOT a threshold — B is a
// per-pixel diff against the sprites themselves (see the header for why a max gate was rejected).
const CAVE_LIGHT_HOT_L = 96;

/** Resolve the deep-chamber framings for a cave (streamed resident by key, or the origin cave). */
async function caveLightPlan(page, residentKey) {
  return page.evaluate(({ KEY, EYE }) => {
    const g = window.__game; const ctx = g.ctx;
    let p = null;
    if (KEY) {
      const res = ctx.caveStream ? ctx.caveStream.residents().find((r) => r.key === KEY) : null;
      if (!res) return null;
      p = res.cave.probe;
    } else {
      ctx.three.scene.traverse((o) => { if (o.userData && o.userData.caveGenProbe) p = o.userData.caveGenProbe; });
    }
    if (!p) return null;
    const nodes = p.nodes;
    const egg = nodes.find((n) => n.id === p.eggId) || nodes[0];
    // The floor snap, with the same sanity clamp caveKindShots uses: a ray that escapes the cave
    // and returns the DESERT SURFACE would park the eye outside the rock and measure the sky.
    const floorAt = (x, z, guess) => {
      const h = g.castDown(x, z, guess + 2.5, true);
      if (!h) return guess;
      if (Math.abs(h.hitY - guess) > 3.5) return guess;
      return h.hitY;
    };
    const specs = [];
    // 1 — DEEP-ACROSS. Off-centre in the deepest room, looking across it at head height. This is
    //     the day-invariance framing: mostly rock, lit only by whatever the light model leaks in.
    {
      const a = 0.62, ux = Math.cos(a), uz = Math.sin(a);
      const st = egg.rx * 0.70;
      const sx = egg.x + ux * st, sz = egg.z + uz * st;
      const fy = floorAt(sx, sz, egg.y);
      specs.push({ name: 'deep-across', stand: [sx, fy, sz], cam: [sx, fy + EYE, sz],
        look: [egg.x - ux * egg.rx * 0.6, egg.y + egg.height * 0.28, egg.z - uz * egg.rx * 0.6] });
    }
    // 2 — DEEP-UP. Centre of the deepest room, pitched ~80° up so the ZENITH is inside the
    //     frustum (a dead-vertical lookAt is degenerate against the +Y up vector). This is where
    //     a sun/moon sprite drawn without depth testing lands.
    {
      const cx = egg.x, cz = egg.z;
      const fy = floorAt(cx, cz, egg.y);
      specs.push({ name: 'deep-up', stand: [cx, fy, cz], cam: [cx, fy + EYE, cz],
        look: [cx + 8, fy + 45, cz + 3] });
    }
    // 3 — A SECOND DEEP ROOM, also pitched up. One chamber can be lucky; the deepest OTHER
    //     chamber is the cross-check that the occlusion holds tree-wide.
    {
      const other = nodes.filter((n) => n.id !== egg.id).sort((a, b) => a.y - b.y)[0] || egg;
      const fy = floorAt(other.x, other.z, other.y);
      specs.push({ name: 'deep2-up', stand: [other.x, fy, other.z], cam: [other.x, fy + EYE, other.z],
        look: [other.x - 8, fy + 45, other.z + 3] });
    }
    return {
      kind: p.kind || 'origin',
      depth: +(p.depthBelowSurface ?? 0).toFixed(1),
      eggRx: +egg.rx.toFixed(1),
      specs: specs.map((s) => Object.assign({}, s, { cam: [s.cam[0], s.stand[1] + EYE, s.cam[2]] })),
    };
  }, { KEY: residentKey || null, EYE: CAVE_LIGHT_EYE });
}

/** Pin at `stand`, set the clock, let the REAL tick chain light it, pause, render, read pixels.
 *
 *  ⚠ THIS HELPER FREEZES THE GAME, AND THE UNFREEZE IS A `finally`. It sets `ctx.flags.paused`
 *  for the same reason `caveKindShots` does — the game keeps rendering on its own rAF, so an
 *  un-paused `updatePlayer` would put the camera back on the capsule between the pin and the
 *  readPixels. But `main.ts`'s pause gate skips EVERY system (architecture rule 4): physics,
 *  `caveStream.update`, `updateChunks`, eviction. A shot that returns while still paused does not
 *  fail — it silently freezes the WORLD for every leg that runs after it.
 *
 *  That is exactly what the first cut of this helper did (cycle 10): it copied `caveKindShots`'s
 *  freeze and dropped its unpause, so `cave-kinds` went from green to seven failures — the warren's
 *  cave never evicted, its scrap never despawned, and the other three kinds' terrain tiles never
 *  streamed in, all downstream of one line. Measured: `paused=true`, `elapsedΔ=0.00s` over 900 rAF
 *  frames. So the restore now runs in a `finally`, restores paused/exposure unconditionally (no
 *  `if (!st) return` in front of it), and `caveLightAsserts` re-asserts liveness afterwards. */
async function caveLightShot(page, spec, dayTime, opts = {}) {
  try {
    return await caveLightShotInner(page, spec, dayTime, opts);
  } finally {
    // ── THE UNFREEZE. Runs on the success path AND on any throw above (a lost page, a WebGL
    //    context loss, a screenshot timeout). Restores in dependency order and unpauses LAST.
    await page.evaluate(() => {
      const ctx = window.__game.ctx; const st = window.__shotRestore;
      if (st) {
        for (const o of st.added) ctx.three.scene.remove(o);
        for (const o of st.hidden) o.visible = true;
        for (const [el, d] of st.dom) el.style.display = d;
        if (ctx.player.viewModel) ctx.player.viewModel.heldPointLight.intensity = st.heldI || 0;
        if (st.prevExposure !== undefined) ctx.three.renderer.toneMappingExposure = st.prevExposure;
        window.__shotRestore = null;
      }
      ctx.flags.paused = false;    // ← unconditional: NOT behind the `st` guard, by construction
    }).catch(() => { /* the page is gone; the run is failing for a louder reason */ });
  }
}

async function caveLightShotInner(page, spec, dayTime, opts = {}) {
  const live = await page.evaluate(async ({ s, t }) => {
    const g = window.__game; const ctx = g.ctx;
    const raf = () => new Promise((r) => requestAnimationFrame(() => r()));
    ctx.flags.paused = false;
    g.setTime(t);
    const pin = () => {
      ctx.player.body.body.setTranslation({ x: s.stand[0], y: s.stand[1] + 0.85, z: s.stand[2] }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
    };
    for (let i = 0; i < 6; i++) { pin(); g.setTime(t); await raf(); }
    pin(); g.setTime(t);
    ctx.flags.paused = true;
    const fog = ctx.three.scene.fog;
    const A = ctx.caveAtmosphere;
    return {
      t,
      dark: A ? +A.darkness.toFixed(3) : null,
      amb: +ctx.lights.ambient.intensity.toFixed(5),
      ambC: '#' + ctx.lights.ambient.color.getHexString(),
      sun: +ctx.lights.sun.intensity.toFixed(4),
      moon: +ctx.lights.moon.intensity.toFixed(4),
      sunY: +ctx.time.sunDir.y.toFixed(3),
      shaft: A ? +A.shaft.intensity.toFixed(2) : null,
      fogD: fog ? +fog.density.toFixed(5) : null,
      fogC: fog ? '#' + fog.color.getHexString() : null,
    };
  }, { s: spec, t: dayTime });

  const m = await page.evaluate(({ s, exp, light, hideBodies, HOT_L }) => {
    const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const T = g.Tuning;
    const cam = ctx.three.camera;
    const prevExposure = ctx.three.renderer.toneMappingExposure;
    ctx.three.renderer.toneMappingExposure = exp;
    cam.position.set(s.cam[0], s.cam[1], s.cam[2]);
    cam.lookAt(s.look[0], s.look[1], s.look[2]);
    cam.updateMatrixWorld(true);
    const st = { added: [], hidden: [], dom: [], prevExposure };
    // Published IMMEDIATELY, before anything below can throw, so the `finally` restore always has
    // the full list of what to put back (the first cut published it only after readPixels).
    window.__shotRestore = st;
    const hide = (o) => { if (o && o.visible) { st.hidden.push(o); o.visible = false; } };
    hide(ctx.player.rig && ctx.player.rig.group);
    hide(ctx.player.viewModel && ctx.player.viewModel.group);
    // ── THE SKY-BODY A/B (DEEPER cycle 10). Report where each sky body sits in this frame, and —
    //    when `abSky` is set — render the frame TWICE, once as shipped and once with the sun + moon
    //    SPRITES hidden, and diff it PER PIXEL. Any pixel that changes is a sky body being drawn,
    //    and underground that means through rock.
    //
    //    Two design points, both bought with a wrong first cut:
    //      · NOT A RAW MAX. A bioluminescent cap renders at L≈124-167, so a max threshold would
    //        either flag fungi as the sun or sit so high it stops catching the sun — the "gate that
    //        measures the wrong thing" failure this project has already paid for twice.
    //      · SAME FRAME, NO rAF BETWEEN. The first cut re-ran the whole pin-and-settle for the
    //        hidden leg, so the two renders were at different `time.elapsed` and every animated
    //        emitter (a fungus drifting in and out of the framing at L≈16) showed up as a Δ. It
    //        reported a 15-code "sun leak" in the fungal cave that was a mushroom. Both renders now
    //        happen inside one JS turn against a frozen scene, so the only thing that can differ is
    //        the sprite itself.
    //    Also reported: whether each body is INSIDE the frustum and actually being drawn, so a
    //    framing that quietly stopped pointing at the sky fails as VACUOUS instead of passing free.
    const bodies = {};
    const bodyObjs = [];
    for (const nm of ['skySun', 'skyMoon']) {
      const o = ctx.three.scene.getObjectByName(nm);
      if (!o) { bodies[nm] = null; continue; }
      const v = new THREE.Vector3().copy(o.position).project(cam);
      bodies[nm] = {
        visible: !!o.visible,
        opacity: +(o.material.opacity ?? 1).toFixed(3),
        depthTest: !!o.material.depthTest,
        inFrustum: Math.abs(v.x) <= 1 && Math.abs(v.y) <= 1 && v.z > -1 && v.z < 1,
        ndc: [+v.x.toFixed(2), +v.y.toFixed(2)],
      };
      bodyObjs.push(o);
    }
    for (const el of Array.from(document.body.children)) {
      if (el === ctx.three.renderer.domElement || el.tagName === 'SCRIPT' || el.tagName === 'STYLE') continue;
      if (el.style.display !== 'none') { st.dom.push([el, el.style.display]); el.style.display = 'none'; }
    }
    let heldI = 0;
    if (ctx.player.viewModel) { heldI = ctx.player.viewModel.heldPointLight.intensity; ctx.player.viewModel.heldPointLight.intensity = 0; }
    st.heldI = heldI;
    // The carried light, if any, goes through the GAME's setter so the envelope/bounce response is
    // the shipping one (D165: a rig that re-derives the light model grades a game nobody plays).
    g.setCaveRockLight(0, 0, 0, 0);
    if (light && light !== 'none') {
      const fwd = new THREE.Vector3(); cam.getWorldDirection(fwd);
      const right = new THREE.Vector3().crossVectors(fwd, new THREE.Vector3(0, 1, 0)).normalize();
      const lp = cam.position.clone().addScaledVector(fwd, 0.45).addScaledVector(right, 0.30);
      lp.y -= 0.28;
      if (light === 'flashlight') {
        const sp = new THREE.SpotLight(T.FLASHLIGHT_LIGHT_COLOR_HEX, T.FLASHLIGHT_LIGHT_INTENSITY,
          T.FLASHLIGHT_LIGHT_DISTANCE, T.FLASHLIGHT_LIGHT_ANGLE_RAD, T.FLASHLIGHT_LIGHT_PENUMBRA, 1.2);
        sp.position.copy(lp); sp.target.position.set(s.look[0], s.look[1], s.look[2]);
        ctx.three.scene.add(sp, sp.target); st.added.push(sp, sp.target);
        g.setCaveRockLight(lp.x, lp.y, lp.z, T.FLASHLIGHT_LIGHT_INTENSITY * T.CAVE_BOUNCE_SPOT_FRAC);
      } else if (light === 'lantern') {
        const ln = new THREE.PointLight(T.LANTERN_LIGHT_COLOR_HEX, T.LANTERN_LIGHT_INTENSITY, T.LANTERN_LIGHT_DISTANCE, 2);
        ln.position.copy(lp); ctx.three.scene.add(ln); st.added.push(ln);
        g.setCaveRockLight(lp.x, lp.y, lp.z, T.LANTERN_LIGHT_INTENSITY);
      } else {
        const tl = new THREE.PointLight(T.TORCH_LIGHT_COLOR_HEX, T.TORCH_LIGHT_INTENSITY, T.TORCH_LIGHT_DISTANCE, 2);
        tl.position.copy(lp); ctx.three.scene.add(tl); st.added.push(tl);
        g.setCaveRockLight(lp.x, lp.y, lp.z, T.TORCH_LIGHT_INTENSITY);
      }
    }
    const R = ctx.three.renderer, gl = R.getContext();
    const W = R.domElement.width, H = R.domElement.height;
    R.render(ctx.three.scene, cam);
    const px = new Uint8Array(W * H * 4);
    gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px);
    // The A/B leg — same turn, same clock, same scene, only the two sprites removed.
    let ab = null;
    if (hideBodies && bodyObjs.length) {
      const wasVis = bodyObjs.map((o) => o.visible);
      for (const o of bodyObjs) o.visible = false;
      R.render(ctx.three.scene, cam);
      const px2 = new Uint8Array(W * H * 4);
      gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px2);
      for (let i = 0; i < bodyObjs.length; i++) bodyObjs[i].visible = wasVis[i];
      let changed = 0, dMax = 0, dMaxIdx = 0, hiddenMax = 0, sumA = 0, sumB = 0;
      for (let k = 0, i = 0; k < W * H; k++, i += 4) {
        const a = 0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2];
        const b = 0.2126 * px2[i] + 0.7152 * px2[i + 1] + 0.0722 * px2[i + 2];
        sumA += a; sumB += b;
        if (b > hiddenMax) hiddenMax = b;
        const dd = Math.abs(a - b);
        if (dd > 1) changed++;
        if (dd > dMax) { dMax = dd; dMaxIdx = k; }
      }
      ab = {
        changedPx: changed, dMax: +dMax.toFixed(2),
        dMaxAt: [+((dMaxIdx % W) / W).toFixed(2), +(((dMaxIdx / W) | 0) / H).toFixed(2)],
        dMean: +(Math.abs(sumA - sumB) / (W * H)).toFixed(4),
        hiddenMax: +hiddenMax.toFixed(2),
      };
      // Re-render the shipped frame so the screenshot below (and the canvas the user would see)
      // is the SHIPPING one, not the diagnostic leg.
      R.render(ctx.three.scene, cam);
    }
    const N = W * H;
    const L = new Float32Array(N);
    let sum = 0, hot = 0, argmax = 0, best = -1;
    for (let k = 0, i = 0; k < N; k++, i += 4) {
      const l = 0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2];
      L[k] = l; sum += l;
      if (l > HOT_L) hot++;
      if (l > best) { best = l; argmax = k; }
    }
    const S = L.slice(); S.sort();
    const q = (f) => +S[Math.min(N - 1, Math.floor(f * N))].toFixed(3);
    return {
      res: W + 'x' + H,
      meanL: +(sum / N).toFixed(3), p50: q(0.50), p95: q(0.95), p99: q(0.99),
      maxL: +best.toFixed(2), hotPct: +((100 * hot) / N).toFixed(3),
      // Where the brightest pixel is, in frame fractions (0,0 = bottom-left) — a sun disc lands in
      // a tight blob and naming its position makes "which emitter is that" answerable.
      maxAt: [+((argmax % W) / W).toFixed(2), +(((argmax / W) | 0) / H).toFixed(2)],
      bodies, ab,
    };
  }, { s: spec, exp: CAVE_AUDIT_EXPOSURE, light: opts.light || 'none', hideBodies: !!opts.hideBodies, HOT_L: CAVE_LIGHT_HOT_L });

  if (opts.shotFile) {
    await page.waitForTimeout(120);
    try { await page.screenshot({ path: join(OUT, opts.shotFile), fullPage: false, timeout: 60000 }); }
    catch (e) { console.log('[cave-light] shot flaked (' + e.name + ')'); }
  }
  // NOTE: the scene/DOM restore + the UNPAUSE live in `caveLightShot`'s `finally`, deliberately
  // not here — a `return` (or a throw) must never be able to walk past them.
  return { live, m };
}

/** THE GATE. Day-invariance (A) + no-sky-body-through-rock (B) for one cave. Returns fails/rows. */
async function caveLightAsserts(page, label, residentKey, opts = {}) {
  const fails = [], rows = [];
  const plan = await caveLightPlan(page, residentKey);
  if (!plan) {
    return { fails: [`${label}: no cave probe resolved — the light gate could not run (VACUOUS)`], rows: [] };
  }
  const NOON = 0.5, MIDNIGHT = 0.0;
  const shots = !!opts.shots;
  const out = {};
  // The clock this leg borrows. Every shot drives `dayTime` to noon or midnight, and the LAST one
  // is midnight — so without this the gate would hand the rest of the run a world stuck at night.
  const prevDayTime = await page.evaluate(() => window.__game.ctx.time.dayTime);
  try {
    for (const s of plan.specs) {
      const ab = s.name.endsWith('-up');    // the upward framings also run the sky-body A/B
      const noon = await caveLightShot(page, s, NOON, { hideBodies: ab, shotFile: shots ? `scen-cavelight-${label}-${s.name}-noon.png` : null });
      const night = await caveLightShot(page, s, MIDNIGHT, { hideBodies: ab, shotFile: shots ? `scen-cavelight-${label}-${s.name}-night.png` : null });
      out[s.name] = { noon, night };
      const dMean = Math.abs(noon.m.meanL - night.m.meanL);
      const dP95 = Math.abs(noon.m.p95 - night.m.p95);
      rows.push(`[cave-light] ${label} ${s.name.padEnd(12)} noon meanL=${noon.m.meanL} p95=${noon.m.p95} max=${noon.m.maxL}@${noon.m.maxAt}`
        + ` | night meanL=${night.m.meanL} p95=${night.m.p95} max=${night.m.maxL}@${night.m.maxAt}`
        + ` | Δmean=${dMean.toFixed(3)} Δp95=${dP95.toFixed(3)}`
        + ` | noon(dark=${noon.live.dark} amb=${noon.live.amb}${noon.live.ambC} sun=${noon.live.sun} fog=${noon.live.fogD}${noon.live.fogC})`
        + ` night(dark=${night.live.dark} amb=${night.live.amb}${night.live.ambC} sun=${night.live.sun} moon=${night.live.moon} fog=${night.live.fogD}${night.live.fogC})`);
      // ── A. DAY-INVARIANCE ────────────────────────────────────────────────────────────────────
      if (dMean > CAVE_LIGHT_DAY_TOL) {
        fails.push(`${label} ${s.name}: deep-cave meanL tracks the surface clock — noon ${noon.m.meanL} vs midnight ${night.m.meanL} (Δ${dMean.toFixed(3)} > ${CAVE_LIGHT_DAY_TOL} dither tolerance)`);
      }
      if (dP95 > CAVE_LIGHT_DAY_TOL) {
        fails.push(`${label} ${s.name}: deep-cave p95 tracks the surface clock — noon ${noon.m.p95} vs midnight ${night.m.p95} (Δ${dP95.toFixed(3)} > ${CAVE_LIGHT_DAY_TOL})`);
      }
      // ── B. NO SKY BODY THROUGH ROCK (the upward framings only) ───────────────────────────────
      //   Two teeth per body-hour: a VACUITY guard (the body must actually be in frame and drawn,
      //   or this framing proves nothing) and the A/B (hiding the sprite must change nothing).
      if (s.name.endsWith('-up')) {
        for (const [when, r, body] of [['noon(sun)', noon, 'skySun'], ['midnight(moon)', night, 'skyMoon']]) {
          const b = r.m.bodies[body];
          if (!b) { fails.push(`${label} ${s.name} @${when}: no '${body}' object in the scene — the occlusion check is VACUOUS`); continue; }
          if (!b.inFrustum || !b.visible || b.opacity <= 0.02) {
            fails.push(`${label} ${s.name} @${when}: ${body} is not being drawn into this frame `
              + `(inFrustum=${b.inFrustum} visible=${b.visible} opacity=${b.opacity} ndc=${b.ndc}) — VACUOUS, the framing no longer aims at it`);
            continue;
          }
          const A = r.m.ab;
          if (!A) { fails.push(`${label} ${s.name} @${when}: the sky A/B leg did not run — VACUOUS`); continue; }
          rows.push(`[cave-light] ${label} ${s.name.padEnd(12)} @${when.padEnd(15)} sky-A/B: changedPx=${A.changedPx} Δmax=${A.dMax}@${A.dMaxAt} Δmean=${A.dMean}`
            + ` | shipped max=${r.m.maxL} · bodies-hidden max=${A.hiddenMax}`
            + ` | ${body} depthTest=${b.depthTest} ndc=${b.ndc} opacity=${b.opacity}`);
          if (A.changedPx > 0 || A.dMax > 1.0) {
            fails.push(`${label} ${s.name} @${when}: hiding the sky bodies changes ${A.changedPx} pixels (worst Δ${A.dMax} at frame ${A.dMaxAt}) `
              + `— a disc is being drawn through solid rock (shipped max ${r.m.maxL}, hidden ${A.hiddenMax})`);
          }
        }
      }
    }
  } finally {
    await page.evaluate((t) => { window.__game.setTime(t); }, prevDayTime)
      .catch(() => { /* page gone */ });
  }
  // ── THE LIVENESS TOOTH. This gate freezes the world to shoot it; the ONE thing that must be true
  //   when it hands control back is that the world is running again. Not a code-review promise — a
  //   measurement, because the cost of getting it wrong is not a red light here, it is SEVEN red
  //   lights in unrelated legs downstream (streaming, eviction, pickup despawn) with nothing in
  //   any of their messages pointing back at this function.
  const alive = await caveWorldTicking(page);
  if (!alive.ticking) {
    fails.push(`${label}: the light gate handed back a FROZEN world — ${alive.why}. `
      + `Everything after this point (streaming, cave eviction, pickup despawn) would starve silently.`);
  }
  return { fails, rows, data: out, plan };
}

/** Is the game actually ticking? Advance real rAF frames and watch `time.elapsed` move. A paused
 *  game still renders (main.ts returns from the tick callback BEFORE the systems, but the loop
 *  keeps drawing), so "frames go by" proves nothing — the sim clock is the honest witness. */
async function caveWorldTicking(page) {
  return page.evaluate(async () => {
    const ctx = window.__game.ctx;
    const raf = () => new Promise((r) => requestAnimationFrame(() => r()));
    const e0 = ctx.time.elapsed;
    for (let i = 0; i < 8; i++) await raf();
    const dE = ctx.time.elapsed - e0;
    return {
      ticking: dE > 0,
      why: `paused=${ctx.flags.paused} titleActive=${ctx.flags.titleActive} time.elapsed advanced ${dE.toFixed(3)}s over 8 rendered frames`,
      paused: !!ctx.flags.paused, dElapsed: +dE.toFixed(3),
    };
  });
}

/** THE CARRIED-LIGHT REFERENCE SET (DEEPER cycle 10, Zach's item 3). Four framings the strength
 *  dials actually change — a wall at torch range, a room across, a ceiling, and a pool — each shot
 *  with each of the three carried lights at their SHIPPING tuning. Numbers + PNGs, so "torch +50%"
 *  is a documented before/after rather than a claim, and so his next walk-test has a reference. */
async function caveLightRefs(page, label, residentKey) {
  const plan = await page.evaluate(({ KEY, EYE }) => {
    const g = window.__game; const ctx = g.ctx; const RAPIER = g.RAPIER;
    let p = null;
    if (KEY) {
      const res = ctx.caveStream ? ctx.caveStream.residents().find((r) => r.key === KEY) : null;
      if (!res) return null;
      p = res.cave.probe;
    } else {
      ctx.three.scene.traverse((o) => { if (o.userData && o.userData.caveGenProbe) p = o.userData.caveGenProbe; });
    }
    if (!p) return null;
    const nodes = p.nodes;
    const egg = nodes.find((n) => n.id === p.eggId) || nodes[0];
    const gallery = nodes.filter((n) => n.id !== egg.id).sort((a, b) => (b.rx * b.height) - (a.rx * a.height))[0] || egg;
    const pbody = ctx.player.body.body;
    const floorAt = (x, z, guess) => {
      const h = g.castDown(x, z, guess + 2.5, true);
      if (!h || Math.abs(h.hitY - guess) > 3.5) return guess;
      return h.hitY;
    };
    const hRay = (ox, oy, oz, dx, dz, max) => {
      const h = ctx.physics.world.castRay(new RAPIER.Ray({ x: ox, y: oy, z: oz }, { x: dx, y: 0, z: dz }), max, true,
        undefined, undefined, undefined, pbody);
      return h ? h.timeOfImpact : max;
    };
    const specs = [];
    // 1 — WALL-2M. The single most diagnostic frame for a carried-light dial: a rock face at
    //     exactly 2m, which is where a torch either reads as stone or reads as a smudge. The
    //     stand-off is MEASURED against the shipped colliders, not assumed from the analytic room.
    {
      const a = 0.35, ux = Math.cos(a), uz = Math.sin(a);
      const cy0 = floorAt(egg.x, egg.z, egg.y) + EYE;
      const d = hRay(egg.x, cy0, egg.z, ux, uz, egg.rx + 6);
      const wx = egg.x + ux * d, wz = egg.z + uz * d;
      const back = Math.max(0.6, d - 2.0);
      const sx = egg.x + ux * back, sz = egg.z + uz * back;
      const fy = floorAt(sx, sz, egg.y);
      specs.push({ name: 'wall2m', stand: [sx, fy, sz], cam: [sx, fy + EYE, sz], look: [wx, fy + EYE - 0.15, wz], note: `wallDist=${(d - back).toFixed(2)}m` });
    }
    // 2 — GALLERY. The biggest ordinary chamber, across at head height: "can I read the space I am
    //     mostly walking through".
    {
      const a = 1.9, ux = Math.cos(a), uz = Math.sin(a);
      const st = gallery.rx * 0.72;
      const sx = gallery.x + ux * st, sz = gallery.z + uz * st;
      const fy = floorAt(sx, sz, gallery.y);
      specs.push({ name: 'gallery', stand: [sx, fy, sz], cam: [sx, fy + EYE, sz],
        look: [gallery.x - ux * gallery.rx * 0.7, gallery.y + gallery.height * 0.25, gallery.z - uz * gallery.rx * 0.7], note: `rx=${gallery.rx.toFixed(1)}m h=${gallery.height.toFixed(1)}m` });
    }
    // 3 — CEILING. The vault read: carried light is the ONLY thing that can reach a ceiling, so
    //     this is the framing the bounce term and the range dial move most.
    {
      const fy = floorAt(egg.x, egg.z, egg.y);
      specs.push({ name: 'ceiling', stand: [egg.x, fy, egg.z], cam: [egg.x, fy + EYE, egg.z],
        look: [egg.x + 8, fy + 45, egg.z + 3], note: `eggH=${egg.height.toFixed(1)}m` });
    }
    // 4 — POOL, when the cave has one. The pool pixel gates are RATIO gates (water darker than lit
    //     rock); a strength change that broke the ratio would show here first.
    if (p.pools && p.pools.length) {
      const q = p.pools.slice().sort((a, b) => b.r - a.r)[0];
      const a = 2.4, ux = Math.cos(a), uz = Math.sin(a);
      const sx = q.x + ux * (q.r + 1.2), sz = q.z + uz * (q.r + 1.2);
      const fy = floorAt(sx, sz, q.y - 0.3);
      specs.push({ name: 'pool', stand: [sx, fy, sz], cam: [sx, fy + EYE, sz], look: [q.x, q.y - 0.05, q.z], note: `poolR=${q.r.toFixed(1)}m` });
    }
    return {
      specs,
      dials: {
        torch: [g.Tuning.TORCH_LIGHT_INTENSITY, g.Tuning.TORCH_LIGHT_DISTANCE],
        flashlight: [g.Tuning.FLASHLIGHT_LIGHT_INTENSITY, g.Tuning.FLASHLIGHT_LIGHT_DISTANCE],
        lantern: [g.Tuning.LANTERN_LIGHT_INTENSITY, g.Tuning.LANTERN_LIGHT_DISTANCE],
      },
    };
  }, { KEY: residentKey || null, EYE: CAVE_LIGHT_EYE });
  if (!plan) { console.log('[cave-light] refs: no cave probe — skipped'); return null; }
  console.log(`[cave-light] refs dials: torch=${plan.dials.torch[0]}/${plan.dials.torch[1]}m `
    + `flashlight=${plan.dials.flashlight[0]}/${plan.dials.flashlight[1]}m lantern=${plan.dials.lantern[0]}/${plan.dials.lantern[1]}m`);
  const TAG = argv.tag ? `-${String(argv.tag)}` : '';
  const out = {};
  for (const s of plan.specs) {
    for (const light of ['torch', 'flashlight', 'lantern', 'none']) {
      // Mid-morning, the clock every prior cave audit used — these are LOOK references, and after
      // the day-decoupling fix the deep interior reads the same at any hour anyway.
      const r = await caveLightShot(page, s, 0.42, { light, shotFile: `scen-caveref-${label}-${s.name}-${light}${TAG}.png` });
      out[`${s.name}/${light}`] = r.m;
      console.log(`[cave-ref] ${label} ${s.name.padEnd(9)} ${light.padEnd(10)} ${String(s.note || '').padEnd(18)}`
        + ` meanL=${r.m.meanL} p50=${r.m.p50} p95=${r.m.p95} p99=${r.m.p99} max=${r.m.maxL}`
        + ` | dark=${r.live.dark} amb=${r.live.amb} fog=${r.live.fogD}${r.live.fogC}`
        + ` -> scen-caveref-${label}-${s.name}-${light}${TAG}.png`);
    }
  }
  return out;
}

/* ══════════════════════════════════════════════════════════════════════════════════════════════
   DEEPER cycle 7 — THE CAVE AUDIT SET + the CAVE_ROCK_BUMP perf answer.

   See the `cave-audit` scenario above for the WHY. These two helpers are the whole implementation:
     · caveAuditShotSet — 17 REAL-settings framings across the whole tree, each with pixel metrics.
     · caveBumpPerf     — the bump-shader A/B frame-time table (shipping shader vs a no-bump clone).
   ══════════════════════════════════════════════════════════════════════════════════════════════ */

// MUST equal src/core/scene.ts's `renderer.toneMappingExposure`. The audit's entire claim is that it
// shows the shipping read; a shot taken hot is a shot that grades a cave nobody plays. Do not raise.
const CAVE_AUDIT_EXPOSURE = 1.05;
const CAVE_AUDIT_EYE = 1.68;          // m — eye above the SNAPPED physics floor (Tuning.PLAYER_HEIGHT class)

/** Resolve every framing's camera/stand/look IN THE PAGE (that is where `castDown` and the probes
 *  live), then shoot them one by one from node. Returns the metrics map, keyed by framing name.
 *  Writes verification/scen-<prefix>-<name>.png. */
async function caveAuditShotSet(page, prefix, opts = {}) {
  const only = opts.framings ? new Set(opts.framings) : null;
  const hideSky = !!opts.hideSky;

  const plan = await page.evaluate((EYE) => {
    const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const T = g.Tuning;
    let p = null, b = null;
    ctx.three.scene.traverse((o) => {
      if (o.userData && o.userData.caveGenProbe) p = o.userData.caveGenProbe;
      if (o.userData && o.userData.caveEntranceProbe) b = o.userData.caveEntranceProbe;
    });
    if (!p || !b) return null;

    const nodes = p.nodes;
    const ent = nodes.find((n) => n.kind === 'entrance') || nodes[0];
    const hall = nodes.find((n) => n.kind === 'hall') || ent;
    const egg = nodes.find((n) => n.id === p.eggId) || hall;
    // "A mid gallery" = the biggest ordinary chamber that is neither the hall nor the egg room —
    // the space the tree is mostly MADE of, and therefore the one the read has to hold up in.
    const gallery = nodes.filter((n) => n.kind === 'pocket')
      .sort((a, c) => (c.rx * c.height) - (a.rx * a.height))[0] || hall;
    const sq = p.edges.find((e) => e.squeeze) || p.edges[0];
    const sqa = nodes.find((n) => n.id === sq.a) || ent;
    const sqb = nodes.find((n) => n.id === sq.b) || hall;
    const wps = b.waypoints;

    // Nearest bioluminescent cap to the gallery + the chamber it belongs to (for the stand-off dir).
    const want = new THREE.Color(T.CAVE_FUNGI_EMISSIVE_HEX).getHexString();
    const wp = new THREE.Vector3(); let fungi = null, fd = 1e9;
    ctx.three.scene.traverse((o) => {
      if (!o.isMesh || !o.material || !o.material.emissive) return;
      if (o.material.emissive.getHexString() !== want) return;
      o.getWorldPosition(wp);
      const d = Math.hypot(wp.x - gallery.x, wp.z - gallery.z);
      if (d < fd) { fd = d; fungi = { x: +wp.x.toFixed(2), y: +wp.y.toFixed(2), z: +wp.z.toFixed(2), d: +d.toFixed(1) }; }
    });
    let fnode = null;
    if (fungi) {
      let bd = 1e9;
      for (const n of nodes) { const d = Math.hypot(n.x - fungi.x, n.z - fungi.z); if (d < bd) { bd = d; fnode = n; } }
    }
    const pools = (p.pools || []).slice().sort((a, c) => c.r - a.r).map((q) => {
      const n = nodes.find((x) => x.id === q.node) || { x: q.x, z: q.z, y: q.y - 0.26 };
      return { x: q.x, y: q.y, z: q.z, r: q.r, nx: n.x, nz: n.z, floorY: n.y, node: q.node };
    });

    // THE FLOOR SNAP — the real collider, not a node's nominal floorY. A chamber's polygonized floor
    // sits up to the displacement amplitude away from its analytic centre height, and the audit's
    // whole point is that the eye is where the CAPSULE would put it.
    const floorAt = (x, z, guess) => {
      const h = g.castDown(x, z, guess + 3.0, true);
      return h ? +h.hitY.toFixed(3) : guess;
    };

    const specs = [];

    // ── A. ENTRANCE APPROACH — daylight, real sun, real weather fog, NO carried light. The 78m
    //    frame is the one the "small dark bump" residual lives in, so it is shot first and framed
    //    exactly like a player walking in on a 3/4 line rather than dead down the slot axis.
    for (const d of [78, 40, 15]) {
      const x = b.mouthX - d, z = b.centerZ + d * 0.30;
      const fy = ctx.terrain.pureHeightAt(x, z);
      specs.push({
        name: 'app' + d, light: 'none', tag: 'exterior',
        stand: [x, fy, z], cam: [x, fy + EYE, z],
        look: [b.mouthX, b.gy + b.torHeight * 0.50, b.centerZ],
      });
    }
    // The threshold: standing on the apron at the mouth, looking IN. The "do I commit?" frame — and
    // the one that shows whether the crack reads as a way down or as a black smear.
    {
      const wm = wps[2], wd = wps[Math.min(wps.length - 1, 5)];
      specs.push({
        name: 'threshold', light: 'none', tag: 'exterior',
        stand: [wm.x, wm.y, wm.z], cam: [wm.x, wm.y + EYE, wm.z],
        look: [wd.x, wd.y + 0.7, wd.z],
      });
    }

    // ── B. THE DESCENT — inside the fissure slot. Torch out (a player descending has one lit).
    //    `slot-wall-up` deliberately aims UP a side wall at torch range: that is where the sawtooth
    //    spike residual lives, and a shot aimed down the slot axis never looks at it.
    {
      const si = (f) => wps[Math.min(wps.length - 1, Math.max(3, 3 + Math.round((wps.length - 4) * f)))];
      const a = si(0.20), c = si(0.58);
      specs.push({
        name: 'slot-upper', light: 'torch', tag: 'descent',
        stand: [a.x, a.y, a.z], cam: [a.x, a.y + EYE, a.z], look: [c.x, c.y + 1.0, c.z],
      });
      const m0 = si(0.45), m1 = si(0.66);
      let hx = m1.x - m0.x, hz = m1.z - m0.z; const hl = Math.hypot(hx, hz) || 1; hx /= hl; hz /= hl;
      specs.push({
        name: 'slot-wall-up', light: 'torch', tag: 'descent',
        stand: [m0.x, m0.y, m0.z], cam: [m0.x, m0.y + EYE, m0.z],
        look: [m0.x + (-hz) * 2.2, m0.y + 4.2, m0.z + hx * 2.2],
      });
      const h0 = wps[wps.length - 1];
      specs.push({
        name: 'slot-handoff', light: 'torch', tag: 'descent',
        stand: [h0.x, h0.y, h0.z], cam: [h0.x, h0.y + EYE, h0.z],
        look: [ent.x, ent.y + 1.2, ent.z],
      });
    }

    // ── C. CHAMBERS — one frame per distinct SPACE, walking the tree. Aimed the way a player looks:
    //    at the rock in front of them (the cycle-3 lesson), except `hall-wide`, which deliberately
    //    asks the opposite question — what do you see down the LONGEST sightline the cave has?
    {
      const t = 0.25;
      const x = sqa.x + (sqb.x - sqa.x) * t, z = sqa.z + (sqb.z - sqa.z) * t;
      const fy = floorAt(x, z, sqa.y + (sqb.y - sqa.y) * t);
      specs.push({ name: 'squeeze', light: 'torch', tag: 'chamber',
        stand: [x, fy, z], cam: [x, fy + EYE, z], look: [sqb.x, sqb.y + 1.1, sqb.z] });
    }
    // THE CYCLE-3 LESSON, APPLIED: aim at rock the TORCH REACHES. A torch is 1.8 candela at
    // distance 12 with quadratic decay, so a chamber wall 8m off receives ~1/16th of what a wall 2m
    // off does — round 1 of this set framed the gallery across its full width and graded a black
    // rectangle. The gallery frame now stands half a radius out and looks at the NEAR wall ~3m away,
    // with the chamber curving off to one side so the shot still carries the space, not just a patch.
    const galleryStand = (() => {
      const gx = gallery.x - gallery.rx * 0.50, gz = gallery.z - gallery.rx * 0.15;
      return { x: gx, z: gz, y: floorAt(gx, gz, gallery.y) };
    })();
    const galleryLook = [gallery.x - gallery.rx * 1.05, gallery.y + gallery.height * 0.22, gallery.z + gallery.rx * 0.28];
    specs.push({ name: 'gallery', light: 'torch', tag: 'chamber',
      stand: [galleryStand.x, galleryStand.y, galleryStand.z],
      cam: [galleryStand.x, galleryStand.y + EYE, galleryStand.z], look: galleryLook });
    {
      const hx = hall.x - hall.rx * 0.86, hz = hall.z;
      const fy = floorAt(hx, hz, hall.y);
      specs.push({ name: 'hall-wide', light: 'torch', tag: 'chamber',
        stand: [hx, fy, hz], cam: [hx, fy + EYE, hz],
        look: [hall.x + hall.rx * 1.05, hall.y + hall.height * 0.28, hall.z] });
    }
    {
      // A FIXED 3.2m stand-off, not a fraction of rx: the egg chamber is the biggest room in the
      // cave (rx ≈ 9.5m), so 0.6·rx put the camera 6m from the dais — outside useful torch range.
      const ex = egg.x - 3.2 * 0.90, ez = egg.z - 3.2 * 0.44;
      const fy = floorAt(ex, ez, egg.y);
      specs.push({ name: 'egg-dais', light: 'torch', tag: 'chamber',
        stand: [ex, fy, ez], cam: [ex, fy + EYE, ez],
        look: [egg.x, egg.y + 1.15, egg.z] });          // the dais top (buildDais H=0.9 + egg centre)
    }

    // ── D. CEILINGS + the NEAR-FIELD WALL. The named residual is a "dark smoky band at 8-15m", so
    //    two frames pitch up at ~75° (not 90° — a dead-vertical lookAt is degenerate against the up
    //    vector, and no player holds that pose anyway): one in a gallery, one in the tallest room.
    //    Plus one wall at ~2m, which is where the torch actually lands and where the rock either
    //    reads as carved stone or does not.
    {
      const off = Math.max(1.0, gallery.height * 0.26);
      const fy = floorAt(gallery.x, gallery.z, gallery.y);
      specs.push({ name: 'ceil-gallery', light: 'torch', tag: 'ceiling',
        stand: [gallery.x, fy, gallery.z], cam: [gallery.x, fy + EYE, gallery.z],
        look: [gallery.x + off, fy + gallery.height * 0.98, gallery.z + off * 0.35] });
    }
    {
      const hx = hall.x + hall.rx * 0.30, hz = hall.z - hall.rx * 0.18;
      const off = Math.max(1.2, hall.height * 0.28);
      const fy = floorAt(hx, hz, hall.y);
      specs.push({ name: 'ceil-hall', light: 'torch', tag: 'ceiling',
        stand: [hx, fy, hz], cam: [hx, fy + EYE, hz],
        look: [hx + off, fy + hall.height * 1.00, hz + off * 0.35] });
    }
    {
      const ux = hall.x + hall.rx * 0.75, uz = hall.z;         // ~0.25·rx ≈ 2m off the wall
      const fy = floorAt(ux, uz, hall.y);
      specs.push({ name: 'wall-2m', light: 'torch', tag: 'ceiling',
        stand: [ux, fy, uz], cam: [ux, fy + EYE, uz],
        look: [hall.x + hall.rx * 1.15, fy + 1.35, hall.z] });
    }

    // ── E. LIGHT CONTEXTS. `flash-gallery` is the SAME camera as `gallery` so the carried light is
    //    the only variable between the two frames. `fungi-only` kills the torch entirely — the cave
    //    lit by nothing but its own bioluminescence. `pool-rock` is the joint frame the "leopard
    //    mottle competes with the water" finding needs: water and rock, one composition, one light.
    specs.push({ name: 'flash-gallery', light: 'flashlight', tag: 'light',
      stand: [galleryStand.x, galleryStand.y, galleryStand.z],
      cam: [galleryStand.x, galleryStand.y + EYE, galleryStand.z], look: galleryLook });
    if (fungi && fnode) {
      let dx = fungi.x - fnode.x, dz = fungi.z - fnode.z; const dl = Math.hypot(dx, dz) || 1; dx /= dl; dz /= dl;
      const fx = fungi.x - dx * 1.8, fz = fungi.z - dz * 1.8;
      const fy = floorAt(fx, fz, fungi.y);
      specs.push({ name: 'fungi-only', light: 'none', tag: 'light',
        stand: [fx, fy, fz], cam: [fx, fy + EYE, fz], look: [fungi.x, fungi.y, fungi.z] });
    }
    if (pools.length) {
      const P = pools[0];
      let ix = P.nx - P.x, iz = P.nz - P.z; const il = Math.hypot(ix, iz) || 1; ix /= il; iz /= il;
      const cx = P.x + ix * (P.r + 1.6), cz = P.z + iz * (P.r + 1.6);
      const fy = floorAt(cx, cz, P.floorY + 0.4);
      specs.push({ name: 'pool-rock', light: 'torch', tag: 'light',
        stand: [cx, fy, cz], cam: [cx, fy + EYE, cz],
        look: [P.x - ix * P.r * 0.55, P.y + 0.30, P.z - iz * P.r * 0.55] });
    }

    return {
      specs,
      info: {
        nodes: nodes.length,
        kinds: nodes.map((n) => n.kind).join(','),
        ent: 'n' + ent.id + ' rx' + ent.rx.toFixed(1) + ' h' + ent.height.toFixed(1),
        hall: 'n' + hall.id + ' rx' + hall.rx.toFixed(1) + ' h' + hall.height.toFixed(1),
        gallery: 'n' + gallery.id + ' rx' + gallery.rx.toFixed(1) + ' h' + gallery.height.toFixed(1),
        egg: 'n' + egg.id + ' rx' + egg.rx.toFixed(1) + ' h' + egg.height.toFixed(1),
        squeeze: (sq.squeeze ? 'SQUEEZE ' : 'fallback-edge ') + 'n' + sq.a + '-n' + sq.b + ' halfW' + sq.halfW.toFixed(2),
        slotWaypoints: wps.length - 3,
        mouth: '(' + b.mouthX.toFixed(1) + ',' + b.centerZ.toFixed(1) + ') gy=' + b.gy.toFixed(2) + ' torH=' + b.torHeight,
        descentDeg: b.descentAngleDeg, mouthClearW: b.mouthClearW,
        pools: pools.length, fungiDist: fungi ? fungi.d : null,
      },
    };
  }, CAVE_AUDIT_EYE);

  if (!plan) throw new Error('cave-audit: no caveGenProbe / caveEntranceProbe in the scene — the cave did not build (VITE_CAVE_TEST off, or a placement regression)');
  console.log('[cave-audit] cave: ' + JSON.stringify(plan.info));

  const metrics = {};
  for (const s of plan.specs) {
    if (only && !only.has(s.name)) continue;

    // ── 1. PIN + LET THE REAL TICK LIGHT IT. The shipping depth-fade decides ambient/sun/fog/shaft;
    //    the rig does not get to choose them. Pause afterwards (the pause gate freezes lighting, so
    //    the values survive into the render below).
    const live = await page.evaluate(async (spec) => {
      const g = window.__game; const ctx = g.ctx;
      const raf = () => new Promise((r) => requestAnimationFrame(() => r()));
      ctx.flags.paused = false;
      const pin = () => {
        ctx.player.body.body.setTranslation({ x: spec.stand[0], y: spec.stand[1] + 0.85, z: spec.stand[2] }, true);
        ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      };
      for (let i = 0; i < 5; i++) { pin(); await raf(); }
      pin();
      ctx.flags.paused = true;
      const fog = ctx.three.scene.fog;
      const A = ctx.caveAtmosphere;
      return {
        dark: A ? +A.darkness.toFixed(3) : null,
        amb: +ctx.lights.ambient.intensity.toFixed(4),
        sun: +ctx.lights.sun.intensity.toFixed(4),
        shaft: A ? +A.shaft.intensity.toFixed(2) : null,
        fogD: fog ? +fog.density.toFixed(4) : null,
        fogC: fog ? '#' + fog.color.getHexString() : null,
      };
    }, s);

    // ── 2. FRAME, RENDER, MEASURE. Shipping exposure; shipping carried-light tuning at the flame
    //    offset; nothing hidden but the first-person body + view model.
    const m = await page.evaluate(({ spec, exp }) => {
      const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const T = g.Tuning;
      const cam = ctx.three.camera;
      ctx.three.renderer.toneMappingExposure = exp;
      cam.position.set(spec.cam[0], spec.cam[1], spec.cam[2]);
      cam.lookAt(spec.look[0], spec.look[1], spec.look[2]);
      cam.updateMatrixWorld(true);

      const st = { added: [], hidden: [], torchI: 0, dom: [] };
      const hide = (o) => { if (o && o.visible) { st.hidden.push(o); o.visible = false; } };
      hide(ctx.player.rig && ctx.player.rig.group);
      hide(ctx.player.viewModel && ctx.player.viewModel.group);
      // ── DEEPER cycle 7, METRIC HYGIENE. The [cave-metric] line reads the WebGL framebuffer, which
      //    has never contained the HUD — but `page.screenshot()` composites the DOM on top, and the
      //    critics grade the PNG. In a frame whose 99th percentile is L≈2, the hotbar swatch (L≈220)
      //    and the crosshair (L≈112) ARE the maxima: every "max=" a critic quotes off the image is
      //    the UI, not the rock. So the HUD is hidden for the shot — same spirit as hiding the FP
      //    body + view model, which this set already did. `--keephud` restores the old behaviour.
      if (!spec.keepHud) {
        for (const sel of ['#hud', '#hotbar', '#crosshair', '#devPanel', '#devBadge', '#interactPrompt',
                           '#toasts', '#statusBars', '#compass', '#perfHud', '#clock']) {
          document.querySelectorAll(sel).forEach((el) => {
            if (el.style.display !== 'none') { st.dom.push([el, el.style.display]); el.style.display = 'none'; }
          });
        }
        // Belt + braces: anything that is a direct child of <body> other than the renderer canvas is
        // UI chrome by construction in this project (each UI module owns its own root element).
        for (const el of Array.from(document.body.children)) {
          if (el === ctx.three.renderer.domElement || el.tagName === 'SCRIPT' || el.tagName === 'STYLE') continue;
          if (el.style.display !== 'none') { st.dom.push([el, el.style.display]); el.style.display = 'none'; }
        }
      }
      // `--hidesky` — the A/B leg for the SKY-BLEED question. The sky dome and the sun sprite are
      // built with `depthTest: false` (src/world/sky.ts), so they draw OVER solid geometry no matter
      // what is in front of them. Underground that is not academic: in a chamber whose 99th
      // percentile is L≈2, a single L≈220 blob is the sun painted onto the rock. This leg hides
      // every depth-test-disabled object so the same framing can be measured without them; the
      // difference in `maxL` is the bleed. Off by default — the audit's default is what SHIPS.
      if (spec.hideSky) {
        ctx.three.scene.traverse((o) => {
          if ((o.isMesh || o.isSprite || o.isPoints) && o.material && o.material.depthTest === false) hide(o);
        });
      }
      // `--hidegroup=caveGen|caveEntrance` — a SURFACE-ATTRIBUTION leg. The entrance is two separate
      // watertight solids that overlap by design (the tor's fissure sits INSIDE the cave SDF's slot),
      // so when a defect appears in the crack — slivers, z-fighting shrapnel, a stray dark blade —
      // "which of the two surfaces is that?" is the first question and is otherwise unanswerable from
      // a screenshot. Hiding one names the culprit in one frame. Diagnostic only; never a shipping read.
      if (spec.hideGroup) {
        for (const nm of String(spec.hideGroup).split('|')) {
          const g2 = ctx.three.scene.getObjectByName(nm.trim());
          if (g2) g2.traverse((o) => { if (o.isMesh) hide(o); });
        }
      }
      if (ctx.player.viewModel) {
        st.torchI = ctx.player.viewModel.heldPointLight.intensity;
        ctx.player.viewModel.heldPointLight.intensity = 0;   // the rig carries its own, below
      }
      // DEEPER cycle 7 — the carried light also drives the cave-rock BOUNCE + envelope uniforms, and
      // it must do so through the game's OWN setter (`__game.setCaveRockLight` → the same
      // `setCaveRockLightState` updateCaveAtmosphere calls). Re-deriving the bounce formula in the
      // harness is exactly the D165 failure mode: the rig would be grading a light model that does
      // not ship. `intensity` here is the same number the game feeds it (held point + spot × frac).
      g.setCaveRockLight(0, 0, 0, 0);       // default: nothing lit — the no-free-light baseline
      if (spec.light && spec.light !== 'none') {
        const fwd = new THREE.Vector3(); cam.getWorldDirection(fwd);
        const right = new THREE.Vector3().crossVectors(fwd, new THREE.Vector3(0, 1, 0)).normalize();
        // Where the game actually puts the flame: ahead + right + a little below the eye.
        const lp = cam.position.clone().addScaledVector(fwd, 0.45).addScaledVector(right, 0.30);
        lp.y -= 0.28;
        if (spec.light === 'flashlight') {
          const sp = new THREE.SpotLight(T.FLASHLIGHT_LIGHT_COLOR_HEX, T.FLASHLIGHT_LIGHT_INTENSITY,
            T.FLASHLIGHT_LIGHT_DISTANCE, T.FLASHLIGHT_LIGHT_ANGLE_RAD, T.FLASHLIGHT_LIGHT_PENUMBRA, 1.2);
          sp.position.copy(lp); sp.target.position.set(spec.look[0], spec.look[1], spec.look[2]);
          ctx.three.scene.add(sp, sp.target); st.added.push(sp, sp.target);
          g.setCaveRockLight(lp.x, lp.y, lp.z, T.FLASHLIGHT_LIGHT_INTENSITY * T.CAVE_BOUNCE_SPOT_FRAC);
        } else {
          const tl = new THREE.PointLight(T.TORCH_LIGHT_COLOR_HEX, T.TORCH_LIGHT_INTENSITY, T.TORCH_LIGHT_DISTANCE, 2);
          tl.position.copy(lp); ctx.three.scene.add(tl); st.added.push(tl);
          g.setCaveRockLight(lp.x, lp.y, lp.z, T.TORCH_LIGHT_INTENSITY);
        }
      }

      const R = ctx.three.renderer, gl = R.getContext();
      const W = R.domElement.width, H = R.domElement.height;
      R.render(ctx.three.scene, cam);
      const px = new Uint8Array(W * H * 4);
      gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, px);
      window.__shotRestore = st;

      // Whole-frame luminance statistics. `dark%` (< L16) is the "is there anything to look at"
      // number; the three BAND means are top/middle/bottom thirds of the IMAGE (readPixels row 0 is
      // the BOTTOM of the frame, and this accounts for it) — a ceiling that dies into a smoky band
      // shows up as bandTop collapsing relative to bandMid.
      const N = W * H;
      const L = new Float32Array(N);
      let sum = 0, dark = 0, black = 0, hot = 0;
      const band = [0, 0, 0], bandN = [0, 0, 0];
      const third = H / 3;
      for (let k = 0, i = 0; k < N; k++, i += 4) {
        const l = 0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2];
        L[k] = l; sum += l;
        if (l < 16) dark++;
        if (l < 4) black++;
        if (l > 200) hot++;
        const y = (k / W) | 0;
        const bi = y < third ? 0 : y < third * 2 ? 1 : 2;    // 0 = bottom rows, 2 = top rows
        band[bi] += l; bandN[bi]++;
      }
      const S = L.slice(); S.sort();
      const q = (f) => +S[Math.min(N - 1, Math.floor(f * N))].toFixed(2);
      const f2 = (v) => +v.toFixed(2);

      // ── THE OUTPUT-ENVELOPE INSTRUMENT (DEEPER cycle 7). The cycle's root-cause finding is that the
      //    whole interior renders into ~18 of 255 output codes, so the lighting ratio that IS there
      //    cannot be seen. Three numbers make that measurable rather than a claim:
      //      · codes   — distinct 8-bit LUMINANCE values present in the frame (the envelope width).
      //      · rgbVals — distinct packed RGB triples (a stricter envelope: dither widens this first).
      //      · run*    — horizontal runs of pixels with an IDENTICAL RGB triple. A frame that is
      //                  quantization-limited is made of long flat runs with Mach steps between them;
      //                  a dithered frame's runs collapse to ~1px. `runP8` = % of pixels living in a
      //                  run of ≥8px (the pool's post-dither reference is ~39%), `runMed` = the run
      //                  length of the MEDIAN PIXEL, `runMax` = the longest single run.
      const codeSeen = new Uint8Array(256);
      const rgbSeen = new Set();
      let runP8 = 0, runMax = 0;
      const runHist = new Uint32Array(4097);      // run length (clamped) → pixels living in such a run
      for (let y = 0; y < H; y++) {
        let base = y * W * 4;
        let prev = -1, runLen = 0;
        for (let x = 0; x <= W; x++) {
          let key = -1;
          if (x < W) {
            const i = base + x * 4;
            key = (px[i] << 16) | (px[i + 1] << 8) | px[i + 2];
            codeSeen[Math.round(L[y * W + x])] = 1;
            rgbSeen.add(key);
          }
          if (key === prev && x < W) { runLen++; continue; }
          if (runLen > 0) {
            if (runLen >= 8) runP8 += runLen;
            if (runLen > runMax) runMax = runLen;
            runHist[Math.min(4096, runLen)] += runLen;
          }
          prev = key; runLen = 1;
        }
      }
      let acc = 0, runMed = 0;
      for (let k = 1; k <= 4096; k++) { acc += runHist[k]; if (acc >= N / 2) { runMed = k; break; } }
      let codes = 0; for (let k = 0; k < 256; k++) if (codeSeen[k]) codes++;

      return {
        res: W + 'x' + H,
        meanL: f2(sum / N), p05: q(0.05), p50: q(0.50), p95: q(0.95), p99: q(0.99), maxL: f2(S[N - 1]),
        darkPct: f2((100 * dark) / N), blackPct: f2((100 * black) / N), hotPct: f2((100 * hot) / N),
        bandTop: f2(band[2] / bandN[2]), bandMid: f2(band[1] / bandN[1]), bandBot: f2(band[0] / bandN[0]),
        codes, rgbVals: rgbSeen.size, runP8: f2((100 * runP8) / N), runMed, runMax,
      };
    }, { spec: Object.assign({ hideSky, keepHud: !!opts.keepHud, hideGroup: opts.hideGroup || null }, s), exp: CAVE_AUDIT_EXPOSURE });

    await page.waitForTimeout(160);
    const file = 'scen-' + prefix + '-' + s.name + '.png';
    try { await page.screenshot({ path: join(OUT, file), fullPage: false, timeout: 60000 }); }
    catch (e) { console.log('[cave-audit] ' + s.name + ' shot flaked (' + e.name + ')'); }

    metrics[s.name] = Object.assign({ live }, m);
    console.log('[cave-metric] ' + s.name.padEnd(14) + ' ' + s.tag.padEnd(8) +
      ' light=' + String(s.light).padEnd(10) +
      ' at=(' + s.cam.map((v) => v.toFixed(1)).join(',') + ')' +
      ' | dark=' + live.dark + ' amb=' + live.amb + ' sun=' + live.sun + ' shaft=' + live.shaft +
      ' fog=' + live.fogD + live.fogC +
      ' | meanL=' + m.meanL + ' p50=' + m.p50 + ' p95=' + m.p95 + ' p99=' + m.p99 + ' max=' + m.maxL +
      ' <16=' + m.darkPct + '% <4=' + m.blackPct + '%' +
      ' bands(T/M/B)=' + m.bandTop + '/' + m.bandMid + '/' + m.bandBot +
      ' | codes=' + m.codes + ' rgb=' + m.rgbVals + ' run>=8=' + m.runP8 + '% runMed=' + m.runMed + ' runMax=' + m.runMax +
      ' -> ' + file);

    await page.evaluate(() => {
      const ctx = window.__game.ctx; const st = window.__shotRestore; if (!st) return;
      for (const o of st.added) ctx.three.scene.remove(o);
      for (const o of st.hidden) o.visible = true;
      for (const [el, d] of (st.dom || [])) el.style.display = d;
      window.__game.setCaveRockLight(0, 0, 0, 0);   // leave no modelled carried light behind
      if (ctx.player.viewModel) ctx.player.viewModel.heldPointLight.intensity = st.torchI;
      window.__shotRestore = null;
    });
  }
  console.log('CAVE-AUDIT exposure=' + CAVE_AUDIT_EXPOSURE + ' framings=' + Object.keys(metrics).length + ' prefix=' + prefix);
  return metrics;
}

/** DEEPER cycle 7 — DOES CAVE_ROCK_BUMP COST TOO MUCH ON A LOW-END GPU?
 *
 *  The bump is ~8 value-noise evaluations (64 hashes) per cave fragment, flagged as the cycle's one
 *  real perf risk when it shipped and never measured. This measures it.
 *
 *  THE A/B HAS TO BE A SHADER SWAP, NOT A UNIFORM. Setting `uCaveBump = 0` changes nothing about the
 *  cost: the fragment shader still runs `caveRockGrad()` in full and then multiplies the result by
 *  zero. So the OFF leg swaps in a rig-local CLONE of each cave material with `onBeforeCompile`
 *  neutered and a different `customProgramCacheKey` — same Lambert/vertexColors/flatShading/FrontSide
 *  material, compiled WITHOUT the bump code. Shipping defaults are untouched; the clones are dropped
 *  when the measurement ends.
 *
 *  METHOD. Two framings (a 2m wall, where cave rock fills the frame — the worst case; and the hall's
 *  long sightline — a typical play view), each measured as render→readPixels(1px) so the GPU is
 *  actually forced to finish before the clock stops. Legs are INTERLEAVED (bump, no-bump, bump,
 *  no-bump) so thermal/scheduler drift cannot masquerade as the effect, and each leg re-warms after
 *  the program switch so no shader compile lands in a sample. Frame coverage (the % of the frame
 *  that is cave surface) is reported alongside, because cost-per-frame without coverage is unreadable.
 *
 *  Run the low-end answer with `--gl=swiftshader` (software raster) and the reference on the GPU. */
async function caveBumpPerf(page, opts = {}) {
  const SAMPLES = opts.samples || (GL_MODE === 'swiftshader' ? 8 : 24);
  const WARM = GL_MODE === 'swiftshader' ? 2 : 4;
  const BURST = GL_MODE === 'swiftshader' ? 1 : 12;   // renders per timed sample — see `measure` below
  const rows = await page.evaluate(async ({ SAMPLES, WARM, BURST, EYE }) => {
    const g = window.__game; const ctx = g.ctx; const THREE = g.THREE; const T = g.Tuning;
    const raf = () => new Promise((r) => requestAnimationFrame(() => r()));
    let p = null;
    ctx.three.scene.traverse((o) => { if (o.userData && o.userData.caveGenProbe) p = o.userData.caveGenProbe; });
    if (!p) return { error: 'no caveGenProbe' };
    const hall = p.nodes.find((n) => n.kind === 'hall') || p.nodes[0];

    // Pin the player in the hall and let the REAL tick set the cave light model, then freeze it —
    // the fragment cost depends on the lighting the shader actually evaluates.
    ctx.flags.paused = false;
    for (let i = 0; i < 5; i++) {
      ctx.player.body.body.setTranslation({ x: hall.x, y: hall.y + 0.9, z: hall.z }, true);
      ctx.player.body.body.setLinvel({ x: 0, y: 0, z: 0 }, true);
      await raf();
    }
    ctx.flags.paused = true;
    ctx.three.renderer.toneMappingExposure = 1.05;
    if (ctx.player.rig && ctx.player.rig.group) ctx.player.rig.group.visible = false;
    if (ctx.player.viewModel) { ctx.player.viewModel.group.visible = false; ctx.player.viewModel.heldPointLight.intensity = 0; }

    const floorAt = (x, z, guess) => { const h = g.castDown(x, z, guess + 3.0, true); return h ? h.hitY : guess; };
    const wx = hall.x + hall.rx * 0.75, wz = hall.z, wy = floorAt(wx, wz, hall.y);
    const hx = hall.x - hall.rx * 0.86, hy = floorAt(hx, hall.z, hall.y);
    const framings = [
      { name: 'perf-wall', cam: [wx, wy + EYE, wz], look: [hall.x + hall.rx * 1.15, wy + 1.35, hall.z] },
      { name: 'perf-hall', cam: [hx, hy + EYE, hall.z], look: [hall.x + hall.rx * 1.05, hall.y + hall.height * 0.28, hall.z] },
    ];

    // Every mesh drawn with a bump-patched cave material (the interior surface AND the crevice tor,
    // which carries its own strength uniform on the same program).
    const meshes = [];
    ctx.three.scene.traverse((o) => {
      if (o.isMesh && o.material && o.material.userData && o.material.userData.bumpU) meshes.push(o);
    });
    if (!meshes.length) return { error: 'no bump-patched cave meshes found - the material wiring moved' };
    const origMat = new Map(); for (const m of meshes) origMat.set(m, m.material);
    const noBump = new Map();
    for (const m of meshes) {
      const src = m.material;
      if (noBump.has(src)) continue;
      const c = src.clone();
      c.onBeforeCompile = function () { /* NO bump patch - that is the whole point of this leg */ };
      c.customProgramCacheKey = function () { return 'caveAudit-noBump-v1'; };
      c.needsUpdate = true;
      noBump.set(src, c);
    }
    const setLeg = (bump) => { for (const m of meshes) m.material = bump ? origMat.get(m) : noBump.get(origMat.get(m)); };

    const R = ctx.three.renderer, gl = R.getContext();
    const W = R.domElement.width, H = R.domElement.height;
    const one = new Uint8Array(4);
    const cam = ctx.three.camera;
    const out = [];

    for (const f of framings) {
      cam.position.set(f.cam[0], f.cam[1], f.cam[2]);
      cam.lookAt(f.look[0], f.look[1], f.look[2]);
      cam.updateMatrixWorld(true);
      // The shipping torch, at the flame offset — the light the fragment shader is evaluating.
      const fwd = new THREE.Vector3(); cam.getWorldDirection(fwd);
      const right = new THREE.Vector3().crossVectors(fwd, new THREE.Vector3(0, 1, 0)).normalize();
      const lp = cam.position.clone().addScaledVector(fwd, 0.45).addScaledVector(right, 0.30); lp.y -= 0.28;
      const tl = new THREE.PointLight(T.TORCH_LIGHT_COLOR_HEX, T.TORCH_LIGHT_INTENSITY, T.TORCH_LIGHT_DISTANCE, 2);
      tl.position.copy(lp); ctx.three.scene.add(tl);

      // COVERAGE — what fraction of the frame is actually cave surface (the fragments that pay).
      setLeg(true);
      R.render(ctx.three.scene, cam);
      const a = new Uint8Array(W * H * 4); gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, a);
      for (const m of meshes) m.visible = false;
      R.render(ctx.three.scene, cam);
      const b = new Uint8Array(W * H * 4); gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, b);
      for (const m of meshes) m.visible = true;
      const covMask = new Uint8Array(W * H);
      let cov = 0;
      for (let i = 0; i < W * H; i++) {
        const k = i * 4;
        if (a[k] !== b[k] || a[k + 1] !== b[k + 1] || a[k + 2] !== b[k + 2]) { covMask[i] = 1; cov++; }
      }

      // ── THE A/B PROOF. This project's canonical failure is a gate that measures the wrong thing
      //    and launders it as verified. A perf A/B whose OFF leg silently still ran the bump shader
      //    would report "+2%, affordable" off two identical programs. So: render both legs and
      //    DIFFERENCE THE PIXELS over the cave-covered region. The bump perturbs the shading normal,
      //    so removing it MUST change the image. A near-zero diff means the swap did not take, and
      //    the frame-time table below is meaningless — reported, loudly, rather than assumed.
      setLeg(false);
      R.render(ctx.three.scene, cam);
      const c2 = new Uint8Array(W * H * 4); gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, c2);
      setLeg(true);
      let abSum = 0, abN = 0, abHit = 0;
      const lum = (q, i) => 0.2126 * q[i] + 0.7152 * q[i + 1] + 0.0722 * q[i + 2];
      for (let i = 0; i < W * H; i++) {
        if (!covMask[i]) continue;
        const d = Math.abs(lum(a, i * 4) - lum(c2, i * 4));
        abSum += d; abN++; if (d >= 2) abHit++;
      }

      // ONE SAMPLE = A BURST OF `BURST` RENDERS, then ONE readPixels, divided through.
      //
      // Round 1 of this measurement timed render -> readPixels ONE frame at a time and reported the
      // bump shader as 15% FASTER than no bump - i.e. pure noise carrying a sign. The reason: a
      // 1-pixel readPixels on the default framebuffer costs a full GPU round-trip (~6ms here through
      // ANGLE), which utterly swamped a sub-millisecond shading delta. Bursting amortises that fixed
      // cost across BURST frames, so what is left is dominated by the thing being measured. On the
      // software rasteriser one frame is already the dominant cost, so BURST is 1 there.
      const measure = () => {
        const t = performance.now();
        for (let k = 0; k < BURST; k++) R.render(ctx.three.scene, cam);
        gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, one);   // forces the pipeline to finish
        return (performance.now() - t) / BURST;
      };
      const on = [], off = [];
      const half = Math.ceil(SAMPLES / 2);
      // INTERLEAVED **and order-swapped**: pass 0 runs bump -> no-bump, pass 1 runs no-bump -> bump,
      // so neither thermal drift nor a first-leg warm-up advantage can masquerade as the effect.
      for (let pass = 0; pass < 2; pass++) {
        for (const bump of (pass === 0 ? [true, false] : [false, true])) {
          setLeg(bump);
          for (let i = 0; i < WARM; i++) measure();
          const dst = bump ? on : off;
          for (let i = 0; i < half; i++) dst.push(measure());
        }
      }
      setLeg(true);
      ctx.three.scene.remove(tl);

      const stat = (arr) => {
        const s = arr.slice().sort((x, y) => x - y);
        return {
          n: s.length,
          mean: +(s.reduce((q, v) => q + v, 0) / s.length).toFixed(2),
          p50: +s[Math.floor(s.length * 0.5)].toFixed(2),
          p95: +s[Math.min(s.length - 1, Math.floor(s.length * 0.95))].toFixed(2),
          min: +s[0].toFixed(2), max: +s[s.length - 1].toFixed(2),
        };
      };
      out.push({
        framing: f.name, res: W + 'x' + H, covPct: +((100 * cov) / (W * H)).toFixed(1),
        abMeanDL: abN ? +(abSum / abN).toFixed(3) : 0,
        abChangedPct: abN ? +((100 * abHit) / abN).toFixed(1) : 0,
        on: stat(on), off: stat(off),
      });
    }

    for (const m of meshes) m.material = origMat.get(m);
    for (const c of noBump.values()) c.dispose();
    // The INTERIOR strength is what the measured fragments actually run (the tor carries its own,
    // far weaker uniform) — labelling this with the legacy CAVE_ROCK_BUMP would report a number no
    // shipping fragment uses.
    return { rows: out, meshes: meshes.length, bump: T.CAVE_ROCK_BUMP_INTERIOR };
  }, { SAMPLES, WARM, BURST, EYE: CAVE_AUDIT_EYE });

  if (rows.error) { console.log('[cave-perf] ERROR ' + rows.error); return rows; }
  console.log('[cave-perf] gl=' + GL_MODE + ' CAVE_ROCK_BUMP_INTERIOR=' + rows.bump + ' patchedMeshes=' + rows.meshes +
    ' samples=' + SAMPLES + '/leg burst=' + BURST + ' (order-swapped interleave x2)');
  for (const r of rows.rows) {
    const d = +(r.on.mean - r.off.mean).toFixed(2);
    const pct = +((100 * d) / r.off.mean).toFixed(1);
    if (r.abMeanDL < 0.05) {
      console.log('[cave-perf] !! ' + r.framing + ' A/B PROOF FAILED: the no-bump leg renders an IDENTICAL image ' +
        '(meanDL=' + r.abMeanDL + ') — the material swap did not take, so the frame times below compare a program to itself');
    }
    console.log('[cave-perf] ' + r.framing.padEnd(10) + ' ' + r.res + ' caveCoverage=' + r.covPct + '%' +
      ' abProof(meanDL/changed%)=' + r.abMeanDL + '/' + r.abChangedPct + '%' +
      ' | bumpON  mean=' + r.on.mean + 'ms p50=' + r.on.p50 + ' p95=' + r.on.p95 + ' min=' + r.on.min + ' max=' + r.on.max +
      ' | bumpOFF mean=' + r.off.mean + 'ms p50=' + r.off.p50 + ' p95=' + r.off.p95 + ' min=' + r.off.min + ' max=' + r.off.max +
      ' | BUMP COST = ' + (d >= 0 ? '+' : '') + d + 'ms (' + (pct >= 0 ? '+' : '') + pct + '%)');
  }
  return rows;
}
